package com.osrscompanion;

import java.util.*;
import java.util.function.Supplier;

/**
 * Items the player deposited through a deposit box (interface open), which
 * does not send the bank container to the client, or moved into the bank
 * by other means the client is not shown (a crew member banking the hold). Without this the deposited items simply vanish from the
 * plugin's holdings until the next real bank visit. Kept as bank-memory
 * source {@code bank_deposits}, seeded from the server's figure on the
 * first deposit of a session, and cleared when the bank proper is read
 * (which then holds everything). Pure, for unit tests.
 */
final class BankDepositLedger {
	static final String SOURCE = "bank_deposits";
	/** Ticks after a "Deposit" click (or with a deposit interface open) during which removed items count as deposited. */
	static final int DEPOSIT_WINDOW_TICKS = 3;

	private final Supplier<Map<Integer, Integer>> seed;
	private final Map<Integer, Integer> deposits = new LinkedHashMap<>();
	private boolean seeded;
	private boolean interfaceOpen;
	private int lastDepositClickTick = Integer.MIN_VALUE;

	BankDepositLedger(Supplier<Map<Integer, Integer>> seed) {
		this.seed = seed == null ? Map::of : seed;
	}

	void onDepositInterface(boolean open) {
		interfaceOpen = open;
	}

	/** A "Deposit…" menu option was clicked on the given tick. */
	void onDepositClick(int tick) {
		lastDepositClickTick = tick;
	}

	boolean inDepositContext(int tick) {
		return interfaceOpen || (long) tick - lastDepositClickTick < DEPOSIT_WINDOW_TICKS;
	}

	/**
	 * Items that left the inventory or gear (canonical id to quantity) on
	 * {@code tick}. Returns true when they were counted as deposits.
	 */
	boolean onItemsRemoved(Map<Integer, Integer> removed, int tick) {
		if (removed == null || removed.isEmpty() || !inDepositContext(tick)) {
			return false;
		}
		ensureSeeded();
		removed.forEach((id, qty) -> {
			if (qty != null && qty > 0) {
				deposits.merge(id, qty, Integer::sum);
			}
		});
		return true;
	}

	/** A storage item (barrel, sack...) was emptied into a deposit box: its contents are banked too. */
	void onContainerEmptied(Map<Integer, Integer> contents) {
		if (contents == null || contents.isEmpty()) {
			return;
		}
		ensureSeeded();
		contents.forEach((id, qty) -> {
			if (id != null && qty != null && qty > 0) {
				deposits.merge(id, qty, Integer::sum);
			}
		});
	}

	/** The bank proper was read: it now holds everything, so the deposits are folded in. Returns true if there were any. */
	boolean onBankRead() {
		seeded = true; // the server's old figure is superseded by the bank read
		boolean had = !deposits.isEmpty();
		deposits.clear();
		return had;
	}

	/** Logout: seed again next session from whatever the server has then. */
	void resetSession() {
		seeded = false;
		interfaceOpen = false;
		lastDepositClickTick = Integer.MIN_VALUE;
		deposits.clear();
	}

	Map<Integer, Integer> contents() {
		return new LinkedHashMap<>(deposits);
	}

	private void ensureSeeded() {
		if (seeded) {
			return;
		}
		seeded = true;
		Map<Integer, Integer> server = seed.get();
		if (server != null) {
			server.forEach((id, qty) -> {
				if (id != null && qty != null && qty > 0) {
					deposits.merge(id, qty, Integer::sum);
				}
			});
		}
	}
}

package com.osrscompanion;

import com.osrscompanion.model.BossGear;
import com.osrscompanion.model.FarmRoute;
import com.osrscompanion.model.SlayerGear;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.util.Text;

/**
 * Gets the bank ready for the Boss gear window or the farm run: while the bank is open with the Boss
 * gear window open (or the Farm run window open, or a run going) it shows only what is needed, laid out
 * like the worn equipment (doll shape, left) and the inventory (4 x 7, right), with the rune pouch under
 * the doll. Items you do not have in the bank show as faded placeholders in their spot.
 *
 * <p>The layout goes through the core Bank Tags plugin's public API (the same as Inventory Setups):
 * {@link TagManager#registerTag} adds a tag whose items are the loadout's (variants included), a
 * {@link Layout} for it is saved with {@link LayoutManager#saveLayout} and the tag opens with
 * {@link BankTagsService#openBankTag}. When the Bank Tags plugin is off, the bank is left alone.
 *
 * <p>The Slayer helper's picked setup (Slayer gear window) is laid out the same way, its worn gear only.
 *
 * <p>Only one drives the bank at a time: an open Boss gear / Slayer gear window first, then the farm
 * run, then the boss setup, then the slayer setup.
 *
 * <p>The "Bank Tag Layouts" hub plugin lays out any open tag itself when its "Enable layout by
 * default" is on: right after Bank Tags draws our layout it packs every item from the top again, and
 * saves that as its own layout for the tag (it saves every layout it applies). A plugin may not change
 * another plugin's settings, so we only read them ({@link #hubLayoutConflict}): our tag still opens (the
 * bank shows only the needed items, in its order) and a chat message once tells the player that turning
 * that plugin off gives our layout.
 */
@Slf4j
@Singleton
public class BankLayoutPrep {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "bank-layout";

	static final String BOSS_TAG = "osrs companion boss gear";
	static final String FARM_TAG = "osrs companion farm run";
	static final String SLAYER_TAG = "osrs companion slayer gear";

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final FarmRunManager farmRun;
	private final BossGearManager bossGear;
	private final SlayerHelperManager slayer;
	private final OSRSCompanionConfig config;
	private final BankTagsService bankTags;
	private final TagManager tagManager;
	private final LayoutManager layoutManager;
	private final PluginManager pluginManager;
	private final ConfigManager configManager;

	/**
	 * The "Bank Tag Layouts" hub plugin (read only): its class, its config group, a tag's own layout under
	 * "layout_" + tag ("DISABLED" = it leaves the tag alone) and its "Enable layout by default" switch.
	 */
	static final String HUB_LAYOUTS_PLUGIN = "com.banktaglayouts.BankTagLayoutsPlugin";
	private static final String HUB_LAYOUTS_GROUP = "banktaglayouts";
	private static final String HUB_LAYOUT_DISABLED = "DISABLED";
	private static final String HUB_LAYOUT_BY_DEFAULT = "layoutEnabledByDefault";

	/** Whether the "turn Bank Tags on" hint was shown this session (once is enough). */
	private boolean bankTagsHintShown;
	/** Whether the "Bank Tag Layouts takes the layout over" tip was shown since this login (once per login). */
	private boolean hubLayoutsHintShown;

	/** What was put in the open bank ("boss:..." / "farm:..."), so it is redone only when that changes. Client thread. */
	private String applied;

	enum Driver {
		BOSS, FARM, SLAYER
	}

	/**
	 * The "active in the bank" settings: only one may be on at a time, turning one on turns the others
	 * off. The first wins when more than one is on at start up. Add a new bank layout's key here.
	 */
	private final Map<String, java.util.function.BooleanSupplier> bankLayoutSettings = new LinkedHashMap<>();

	/**
	 * Set when the player clicks another bank tab / view (a vanilla tab, View all items, a Bank Tags tag
	 * tab, the search, the potion store) while the bank is open: the bank is then left alone, no layout
	 * or retry, until it is closed and opened again. Client thread.
	 */
	private boolean userLeft;

	@Inject
	public BankLayoutPrep(Client client, ClientThread clientThread, ItemManager itemManager, FarmRunManager farmRun,
		BossGearManager bossGear, SlayerHelperManager slayer, OSRSCompanionConfig config, BankTagsService bankTags, TagManager tagManager,
		LayoutManager layoutManager, PluginManager pluginManager, ConfigManager configManager) {
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.farmRun = farmRun;
		this.bossGear = bossGear;
		this.slayer = slayer;
		this.config = config;
		this.bankTags = bankTags;
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
		this.pluginManager = pluginManager;
		this.configManager = configManager;
		bankLayoutSettings.put("bossGearBankLayout", config::bossGearBankLayout);
		bankLayoutSettings.put("farmRunBankFilter", config::farmRunBankFilter);
		bankLayoutSettings.put("slayerGearBankLayout", config::slayerGearBankLayout);
	}

	/** Registers the tags; their items follow the active set / route / slayer setup live. */
	public void startUp() {
		// Bank Tags reads its tags on the client thread.
		Guard.invoke(clientThread, GUARD_FEATURE, () -> {
			tagManager.registerTag(BOSS_TAG, bossGear::needs);
			tagManager.registerTag(FARM_TAG, farmRun::needs);
			tagManager.registerTag(SLAYER_TAG, slayer::needs);
		});
		// Both used to be on by default: keep only the first one that is on.
		String first = null;
		for (Map.Entry<String, java.util.function.BooleanSupplier> e : bankLayoutSettings.entrySet()) {
			if (e.getValue().getAsBoolean()) {
				if (first == null) {
					first = e.getKey();
				} else {
					configManager.setConfiguration(OSRSCompanionConfig.CONFIG_GROUP, e.getKey(), false);
				}
			}
		}
	}

	/** Logging out: the Bank Tag Layouts tip shows again on the first bank visit of the next login (not on a world hop). */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGIN_SCREEN) {
			hubLayoutsHintShown = false;
		}
	}

	/** Turning one bank layout setting on (side panel or config panel) turns the others off. */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!OSRSCompanionConfig.CONFIG_GROUP.equals(event.getGroup()) || !bankLayoutSettings.containsKey(event.getKey())
					|| !"true".equals(event.getNewValue())) {
				return;
			}
			for (Map.Entry<String, java.util.function.BooleanSupplier> e : bankLayoutSettings.entrySet()) {
				if (!e.getKey().equals(event.getKey()) && e.getValue().getAsBoolean()) {
					configManager.setConfiguration(OSRSCompanionConfig.CONFIG_GROUP, e.getKey(), false);
				}
			}
		});
	}

	/** A click on another bank tab / view: the bank is left as the player chose until it is reopened. */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (userLeft || (event.getParam1() >>> 16) != InterfaceID.BANKMAIN || client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null) {
				return;
			}
			String option = event.getMenuOption() == null ? "" : Text.removeTags(event.getMenuOption());
			boolean tabClick = option.startsWith("View tab") || option.equals("View all items") || option.startsWith("View tag tab")
				|| event.getParam1() == InterfaceID.Bankmain.SEARCH || event.getParam1() == InterfaceID.Bankmain.POTIONSTORE_BUTTON;
			if (tabClick) {
				userLeft = true;
				waitingForBuild = false;
			}
		});
	}

	/** What the "Bank Tag Layouts" hub plugin would do to our tag. */
	enum HubConflict {
		/** Nothing: not installed / off, or it leaves the tag alone. */
		NONE,
		/** Its "Enable layout by default" is on: it would pack the tag and save that as its own layout. */
		BY_DEFAULT,
		/** It already saved its own layout for the tag (an earlier session), which it keeps using. */
		SAVED
	}

	/** Whether the "Bank Tag Layouts" hub plugin would lay out (pack) our tag over the Bank Tags layout. Reads its settings only. */
	HubConflict hubLayoutConflict(String tag) {
		if (!hubLayoutsPluginActive()) {
			return HubConflict.NONE;
		}
		return hubConflict(configManager.getConfiguration(HUB_LAYOUTS_GROUP, "layout_" + tag),
			configManager.getConfiguration(HUB_LAYOUTS_GROUP, HUB_LAYOUT_BY_DEFAULT));
	}

	/** The conflict from its saved layout for our tag and its "Enable layout by default" value (pure, for tests). */
	static HubConflict hubConflict(String savedLayout, String byDefault) {
		if (HUB_LAYOUT_DISABLED.equals(savedLayout)) {
			return HubConflict.NONE;
		}
		if (savedLayout != null && !savedLayout.isEmpty()) {
			return HubConflict.SAVED;
		}
		return "true".equals(byDefault) ? HubConflict.BY_DEFAULT : HubConflict.NONE;
	}

	private boolean hubLayoutsPluginActive() {
		for (Plugin p : pluginManager.getPlugins()) {
			if (HUB_LAYOUTS_PLUGIN.equals(p.getClass().getName())) {
				return pluginManager.isPluginActive(p);
			}
		}
		return false;
	}

	/** Tells the player once per login (on the first bank visit with one of our layouts) how to get our layout back from "Bank Tag Layouts". */
	private void hubLayoutsHint(HubConflict conflict) {
		if (hubLayoutsHintShown) {
			return;
		}
		hubLayoutsHintShown = true;
		// Either way it ends up saving its own order for our view (it saves every layout it applies), after
		// which only turning that plugin off gives ours back: so that is the one tip.
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ff9040>OSRS Companion: your gear is shown in the order of the Bank Tag Layouts plugin. For our neater layout (worn gear,"
				+ " rune pouch and inventory in their slots), turn the Bank Tag Layouts plugin off.</col>", null);
	}

	public void shutDown() {
		// A clean-up: runs even when the feature was turned off, so no tag stays registered.
		clientThread.invoke(Guard.wrapCleanup(GUARD_FEATURE, () -> {
			if (isOurTagOpen()) {
				bankTags.closeBankTag();
			}
			tagManager.unregisterTag(BOSS_TAG);
			tagManager.unregisterTag(FARM_TAG);
			tagManager.unregisterTag(SLAYER_TAG);
			// The layouts are rebuilt on every bank open: none left in the Bank Tags config.
			layoutManager.removeLayout(BOSS_TAG);
			layoutManager.removeLayout(FARM_TAG);
			layoutManager.removeLayout(SLAYER_TAG);
			applied = null;
			userLeft = false;
		}));
	}

	// ---- When ---------------------------------------------------------------------

	/**
	 * Opening our tag right as the bank opens does not always stick: Bank Tags and the server's tab
	 * sync can still put the whole bank back while our tag counts as open. So for a few ticks after the
	 * bank opens (and after each apply) we check what the bank actually shows, and when it shows items
	 * the set / route does not need, close and open our layout again, a few times at most. A bank tab /
	 * view the player clicks (see {@link #userLeft}) stops all of this until the bank is reopened.
	 */
	private static final int VERIFY_TICKS = 5;
	private static final int MAX_RETRIES = 4;
	private int verifyUntilTick = -1;
	private int retries;

	/** Re-reads the active boss setup / farm route when the bank opens, at most this often (one just picked on the website). */
	private static final long AUTO_REFRESH_MS = 60_000;
	private long lastBossRefresh;

	/** Set when the bank opens until its first build: the layout waits for it. */
	private boolean waitingForBuild;
	private int bankOpenedTick;
	/** The positions last laid out (-1: empty): an item showing in an empty one means the layout is not drawn. */
	private int[] laidOut;

	/** Loads the active boss setup in the background after login, at most this often, so the first bank open has it. */
	private static final int PRELOAD_EVERY_TICKS = 50;
	private int lastPreloadTick = -PRELOAD_EVERY_TICKS;

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.BANKMAIN) {
				applied = null;
				retries = 0;
				userLeft = false;
				// An active setup / route lays the bank out even with its window closed: make sure it is loaded and current.
				long now = System.currentTimeMillis();
				if (config.bossGearBankLayout() && config.bossGearActive() && !bossGear.isOpen() && !bossGear.isLoading()
						&& (bossGear.getSet() == null || now - lastBossRefresh > AUTO_REFRESH_MS)) {
					lastBossRefresh = now;
					bossGear.refresh();
				}
				if (config.farmRunBankFilter() && config.showFarmRun() && farmRun.isRunning() && !farmRun.isOpen()) {
					farmRun.refreshIfStale();
				}
				if (config.slayerGearBankLayout() && config.slayerGuide() && slayer.getTask() != null) {
					slayer.refreshIfStale();
				}
				verifyUntilTick = client.getTickCount() + VERIFY_TICKS;
				// Not yet: opening our tag before the bank has been built leaves Bank Tags filtering without
				// drawing the layout. The first build (or two ticks, whichever comes first) lays it out.
				waitingForBuild = true;
				bankOpenedTick = client.getTickCount();
			}
		});
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getScriptId() == ScriptID.BANKMAIN_BUILD && waitingForBuild && !userLeft) {
				waitingForBuild = false;
				Guard.invokeLater(clientThread, GUARD_FEATURE, this::update);
			}
		});
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.BANKMAIN) {
				applied = null;
				userLeft = false;
			}
		});
	}

	/** A window opened or closed, or a set / route (re)loaded, while the bank is open. */
	@Subscribe
	public void onGameTick(GameTick tick) {
		Guard.run(GUARD_FEATURE, () -> {
			preloadBossGear();
			if (client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null || userLeft) {
				return;
			}
			if (waitingForBuild) {
				if (client.getTickCount() - bankOpenedTick < 2) {
					return;
				}
				waitingForBuild = false;
			}
			if (applied != null && client.getTickCount() <= verifyUntilTick && retries < MAX_RETRIES && bankTagsOn() && !showingOurs()) {
				retries++;
				if (isOurTagOpen()) {
					bankTags.closeBankTag();
				}
				applied = null;
			}
			update();
		});
	}

	/** Bank filler and the empty-slot object: shown in a whole bank, never items of a set. */
	private static final int BANK_FILLER = 20594;
	private static final int EMPTY_SLOT = 6512;

	/** Whether the open bank shows our tag: no item the set / route does not need is on show. Client thread. */
	private boolean showingOurs() {
		if (!isOurTagOpen()) {
			return false;
		}
		Driver d = driver();
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (d == null || items == null) {
			return true;
		}
		Widget[] children = items.getDynamicChildren();
		if (children == null) {
			return true;
		}
		int[] positions = laidOut;
		if (positions != null && config.bankLayoutPositions()) {
			// Laid out, the empty spots of the layout show nothing; filtered only, the items fill them from the top.
			for (int pos = 0; pos < positions.length && pos < children.length; pos++) {
				Widget w = children[pos];
				int id = w.getItemId();
				if (positions[pos] == -1 && !w.isHidden() && id > 0 && id != BANK_FILLER && id != EMPTY_SLOT) {
					return false;
				}
			}
		}
		for (Widget w : children) {
			int id = w.getItemId();
			if (w.isHidden() || id <= 0 || id == BANK_FILLER || id == EMPTY_SLOT) {
				continue;
			}
			int item = itemManager.canonicalize(id);
			if (!needs(d, item)) {
				return false;
			}
		}
		return true;
	}

	private boolean needs(Driver d, int item) {
		switch (d) {
			case BOSS:
				return bossGear.needs(item);
			case SLAYER:
				return slayer.needs(item);
			default:
				return farmRun.needs(item);
		}
	}

	/** With the boss setup Active in the bank, have it loaded before the bank opens. */
	private void preloadBossGear() {
		int now = client.getTickCount();
		if (config.bossGearBankLayout() && config.bossGearActive() && bossGear.getSet() == null && !bossGear.isLoading() && !bossGear.isLoaded()
				&& client.getGameState() == GameState.LOGGED_IN && now - lastPreloadTick >= PRELOAD_EVERY_TICKS) {
			lastPreloadTick = now;
			lastBossRefresh = System.currentTimeMillis();
			bossGear.refresh();
		}
	}

	/**
	 * Which feature drives the bank now. Each is "active in the bank" by its own setting and only while its
	 * guide is on (the boss setup Active, the farm run guide, the Slayer guide): the farm route only while a
	 * farm run is going (started and not complete), the slayer setup only with a task. When more are, an open boss gear / slayer gear window wins, then the farm run, then the
	 * boss setup, then the slayer setup.
	 */
	Driver driver() {
		boolean boss = bossGear.isSetActive() && config.bossGearBankLayout();
		boolean farm = farmRun.getRoute() != null && config.farmRunBankFilter() && config.showFarmRun() && farmRun.isRunning() && !farmRun.isComplete();
		boolean slayerGear = config.slayerGearBankLayout() && config.slayerGuide() && slayer.getTask() != null && slayer.getGearSet() != null;
		return pick(boss, bossGear.isOpen(), farm, slayerGear, slayer.isGearOpen());
	}

	/** Which one drives the bank, given which are on and which windows are open (see {@link #driver()}). */
	static Driver pick(boolean boss, boolean bossOpen, boolean farm, boolean slayerGear, boolean slayerOpen) {
		if (boss && bossOpen) {
			return Driver.BOSS;
		}
		if (slayerGear && slayerOpen) {
			return Driver.SLAYER;
		}
		if (farm) {
			return Driver.FARM;
		}
		if (boss) {
			return Driver.BOSS;
		}
		return slayerGear ? Driver.SLAYER : null;
	}

	/** Changes with the driver and whenever its data is reloaded (a new object), so a switched set is laid out again. */
	private String key(Driver d) {
		if (d == Driver.BOSS) {
			BossGear s = bossGear.getSet();
			return "boss:" + s.getId() + ":" + System.identityHashCode(s) + ":" + config.bankLayoutPositions();
		}
		if (d == Driver.SLAYER) {
			SlayerGear.Set s = slayer.getGearSet();
			return "slayer:" + s.getKey() + ":" + System.identityHashCode(s) + ":" + config.bankLayoutPositions();
		}
		FarmRoute r = farmRun.getRoute();
		return "farm:" + r.getId() + ":" + System.identityHashCode(r) + ":" + farmRun.inventory().size() + ":" + config.bankLayoutPositions();
	}

	private void update() {
		if (client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null) {
			return;
		}
		if (userLeft) {
			// A reload (new set / route object) or a setting change must not take the bank back from the tab the player picked.
			return;
		}
		Driver d = driver();
		String k = d == null ? null : key(d);
		if (k == null) {
			if (applied != null || isOurTagOpen()) {
				release();
			}
			applied = null;
			return;
		}
		if (k.equals(applied)) {
			return;
		}
		applied = k;
		try {
			apply(d);
		} catch (RuntimeException e) {
			log.warn("Could not lay out the bank", e);
		}
	}

	// ---- How ----------------------------------------------------------------------------

	private boolean bankTagsOn() {
		return bankTags instanceof Plugin && pluginManager.isPluginActive((Plugin) bankTags);
	}

	private boolean isOurTagOpen() {
		String tag = bankTagsOn() ? bankTags.getActiveTag() : null;
		return BOSS_TAG.equals(tag) || FARM_TAG.equals(tag) || SLAYER_TAG.equals(tag);
	}

	private void apply(Driver d) {
		String tag = d == Driver.BOSS ? BOSS_TAG : d == Driver.SLAYER ? SLAYER_TAG : FARM_TAG;
		laidOut = null;
		if (!bankTagsOn()) {
			// The layout goes through Bank Tags; without it the bank is left alone (no typing into the bank search).
			if (!bankTagsHintShown) {
				bankTagsHintShown = true;
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=ff9040>OSRS Companion: turn on RuneLite's Bank Tags plugin to have your "
					+ (d == Driver.BOSS ? "boss gear" : d == Driver.SLAYER ? "slayer gear" : "farm run") + " laid out in the bank.</col>", null);
			}
			return;
		}
		HubConflict conflict = hubLayoutConflict(tag);
		if (conflict != HubConflict.NONE) {
			// "Bank Tag Layouts" re-sorts our tag into its own order: the bank still shows only the needed
			// items, just not in our layout. Tell the player once which of its settings gives ours.
			hubLayoutsHint(conflict);
		}
		BankItems bank = new BankItems();
		int[] positions = d == Driver.BOSS ? bossLayout(bossGear.getSet(), bank) : d == Driver.SLAYER ? slayerLayout(slayer.getGearSet(), bank)
			: farmLayout(bank);
		layoutManager.saveLayout(new Layout(tag, positions));
		laidOut = positions;
		int options = BankTagsService.OPTION_HIDE_TAG_NAME | BankTagsService.OPTION_ITEMS_NOT_IN_LAYOUT_AT_BOTTOM
			| (config.bankLayoutPositions() ? 0 : BankTagsService.OPTION_NO_LAYOUT);
		bankTags.openBankTag(tag, options);
		verifyUntilTick = client.getTickCount() + VERIFY_TICKS;
	}

	/** Back to the normal bank: our tag closes. */
	private void release() {
		if (isOurTagOpen()) {
			bankTags.closeBankTag();
		}
	}

	/**
	 * The boss set's worn gear, inventory and rune pouch in their places; an item you don't own (red in the
	 * window) leaves its place empty. Below the inventory: the weapon's ammo / spell options (as many as the
	 * setting says) and what recharges the charged items.
	 */
	private int[] bossLayout(BossGear set, BankItems bank) {
		// Before your items are synced nothing counts as owned: everything shows then.
		boolean known = set.isSynced();
		Map<String, Integer> worn = new LinkedHashMap<>();
		for (BossGear.Slot s : set.getEquipment()) {
			if (!"special".equals(s.getSlot()) && (!known || s.isOwned())) {
				worn.put(s.getSlot(), bank.resolve(s.getIds()));
			}
		}
		List<Integer> inv = new ArrayList<>();
		for (BossGear.Item it : set.getInventory()) {
			inv.add(it == null || known && !it.isOwned() ? -1 : bank.resolve(it.getIds()));
		}
		List<Integer> pouch = new ArrayList<>();
		for (BossGear.Item it : set.getPouch()) {
			pouch.add(!known || it.isOwned() ? bank.resolve(it.getIds()) : -1);
		}
		// The extras start on the row under the inventory.
		while (inv.size() < 28) {
			inv.add(-1);
		}
		Set<Integer> placed = new HashSet<>();
		for (int id : inv) {
			addBase(placed, id);
		}
		for (int id : worn.values()) {
			addBase(placed, id);
		}
		List<Integer> extras = new ArrayList<>();
		for (int id : set.supplyItems(config.slayerGearSupplyOptions())) {
			extras.add(bank.resolveOne(id));
		}
		for (com.osrscompanion.model.SlayerGear.Bring b : set.getBring()) {
			extras.add(bank.resolve(b.getItems()));
		}
		for (int id : extras) {
			if (id > 0 && placed.add(base(id))) {
				inv.add(id);
			}
		}
		BossGear.Slot special = set.slot("special");
		int spec = special == null || known && !special.isOwned() ? -1 : bank.resolve(special.getIds());
		// One item is brought once: the Alternate weapon is left out when the inventory or the weapon
		// slot has it, the special attack weapon when any of those has it (one blowpipe does all three).
		Set<Integer> brought = new HashSet<>();
		for (int id : inv) {
			addBase(brought, id);
		}
		addBase(brought, worn.getOrDefault("weapon", -1));
		Integer sw = worn.get("switch");
		if (sw != null && sw > 0 && brought.contains(base(sw))) {
			worn.remove("switch");
			worn.remove("switch_shield");
			sw = null;
		}
		addBase(brought, sw == null ? -1 : sw);
		if (spec > 0 && brought.contains(base(spec))) {
			spec = -1;
		}
		return BankLayouts.build(worn, inv, pouch, spec);
	}

	/** The item without its charges / ornament (two versions of one item count as the same). */
	private static int base(int itemId) {
		return ItemVariationMapping.map(itemId);
	}

	private static void addBase(Set<Integer> into, int itemId) {
		if (itemId > 0) {
			into.add(base(itemId));
		}
	}

	/**
	 * The slayer setup's worn gear in the doll's places, and in the inventory's places its ammo / spell
	 * options (darts, arrows or bolts, the spells' runes), best first, as many as the setting says, then
	 * its boost (potion, heart) and what recharges its charged items (runes, scales, ether...).
	 */
	private int[] slayerLayout(SlayerGear.Set set, BankItems bank) {
		List<Integer> supplies = new ArrayList<>();
		for (int id : set.supplyItems(config.slayerGearSupplyOptions())) {
			supplies.add(bank.resolveOne(id));
		}
		for (SlayerGear.Bring b : set.getBring()) {
			int id = bank.resolve(b.getItems());
			if (id > 0 && !supplies.contains(id)) {
				supplies.add(id);
			}
		}
		return BankLayouts.build(slayerWorn(set, bank::resolveOne), supplies, Collections.emptyList(), -1);
	}

	/** Worn slot name to item (resolved to the version in the bank), the first piece per slot; pieces without an item are left out. */
	static Map<String, Integer> slayerWorn(SlayerGear.Set set, java.util.function.IntUnaryOperator resolve) {
		Map<String, Integer> worn = new LinkedHashMap<>();
		for (SlayerGear.Piece p : set.getEquipment()) {
			if (p.getSlot() != null && p.getItem() > 0) {
				worn.putIfAbsent(p.getSlot(), resolve.applyAsInt(p.getItem()));
			}
		}
		return worn;
	}

	private int[] farmLayout(BankItems bank) {
		FarmRoute r = farmRun.getRoute();
		Map<String, Integer> worn = new LinkedHashMap<>();
		for (FarmRoute.Stack s : r.getEquipment()) {
			if (s.getSlot() != null) {
				worn.putIfAbsent(s.getSlot(), bank.resolve(Collections.singletonList(s.getItem())));
			}
		}
		// The farm run window draws the route's inventory one stack per slot, in order: the bank does the same.
		List<Integer> inv = new ArrayList<>();
		for (FarmRoute.Stack s : farmRun.inventory()) {
			inv.add(bank.resolve(Collections.singletonList(s.getItem())));
		}
		return BankLayouts.build(worn, inv, Collections.emptyList(), -1);
	}

	/**
	 * The bank's items, to put the version you actually have in the layout (a charged, coloured or
	 * same-named one); otherwise the item itself, which Bank Tags shows faded. Client thread.
	 */
	private final class BankItems {
		private final java.util.Set<Integer> ids = new java.util.HashSet<>();
		private final Map<Integer, Integer> byBase = new HashMap<>();
		private Map<String, Integer> byName;

		BankItems() {
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank == null) {
				return;
			}
			for (Item item : bank.getItems()) {
				int id = item.getId();
				if (id <= 0 || item.getQuantity() <= 0) {
					continue;
				}
				ids.add(id);
				byBase.putIfAbsent(ItemVariationMapping.map(id), id);
			}
		}

		int resolveOne(int itemId) {
			return resolve(Collections.singletonList(itemId));
		}

		int resolve(List<Integer> candidates) {
			if (candidates.isEmpty()) {
				return -1;
			}
			for (int c : candidates) {
				int id = itemManager.canonicalize(c);
				if (ids.contains(id)) {
					return id;
				}
			}
			for (int c : candidates) {
				Integer id = byBase.get(ItemVariationMapping.map(itemManager.canonicalize(c)));
				if (id != null) {
					return id;
				}
			}
			String name = nameOf(itemManager.canonicalize(candidates.get(0)));
			Integer byNameId = name == null ? null : names().get(name);
			return byNameId != null ? byNameId : itemManager.canonicalize(candidates.get(0));
		}

		private Map<String, Integer> names() {
			if (byName == null) {
				byName = new HashMap<>();
				for (int id : ids) {
					String n = nameOf(id);
					if (n != null) {
						byName.putIfAbsent(n, id);
					}
				}
			}
			return byName;
		}
	}

	private String nameOf(int itemId) {
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp == null || comp.getName() == null ? null : comp.getName().toLowerCase();
	}
}

package com.osrscompanion;

import java.util.*;

/**
 * Bank positions for a loadout, 8 items per bank row: the worn equipment in the game's doll shape on
 * the left (columns 0-2), the 28 inventory slots as the 4 x 7 inventory on the right (columns 4-7),
 * the rune pouch under the doll, and anything past 28 items below it all. The special attack weapon
 * sits right of the helmet, an alternate weapon (and its off-hand) in column 3 next to it.
 *
 * <p>The positions follow the Inventory Setups plugin's "preset" bank layout (dillydill123/inventory-setups,
 * InventorySetupLayoutUtilities#getPresetLayout, BSD 2-Clause), so the bank looks the same either way.
 */
final class BankLayouts {
	private BankLayouts() {
	}

	static final int ROW = 8;
	/** Where the special attack weapon goes: right of the helmet, where the doll has no slot. */
	static final int SPECIAL_POS = 2;
	/** The boss gear's Alternate weapon (a switch): next to the special attack weapon, its off-hand under it. */
	static final int SWITCH_POS = 3;
	static final int SWITCH_SHIELD_POS = 11;
	/** The rune pouch's runes: under the doll (row 5, columns 0-3). */
	static final int POUCH_START = 40;
	/** Items past the 28 inventory slots: from row 7 on. */
	static final int EXTRA_START = 56;

	static final Map<String, Integer> EQUIPMENT_POS;

	static {
		Map<String, Integer> m = new HashMap<>();
		Tables.map("bankEquipmentPos").forEach((key, pos) -> m.put(key, pos.getAsInt()));
		m.put("switch", SWITCH_POS);
		m.put("switch_shield", SWITCH_SHIELD_POS);
		EQUIPMENT_POS = Collections.unmodifiableMap(m);
	}

	/** Inventory slot i (0-27) in the 4 x 7 grid on the right; later items run on below. */
	static int inventoryPos(int i) {
		return i < 28 ? (i / 4) * ROW + 4 + i % 4 : EXTRA_START + (i - 28);
	}

	/**
	 * The layout as bank positions holding item ids (-1: empty).
	 *
	 * @param worn      item per worn slot name (head, cape, ..., switch, switch_shield); unknown slots are left out
	 * @param inventory item per inventory slot in order; null or -1 = empty slot
	 * @param pouch     the rune pouch's runes (up to 4 used)
	 * @param special   the special attack weapon, or -1
	 */
	static int[] build(Map<String, Integer> worn, List<Integer> inventory, List<Integer> pouch, int special) {
		// The pouch row, or further down when the inventory reaches its last rows (slot 27 is position 55).
		int last = POUCH_START + 3;
		if (!inventory.isEmpty()) {
			last = Math.max(last, inventoryPos(inventory.size() - 1));
		}
		int size = (last / ROW + 1) * ROW;
		int[] out = new int[size];
		Arrays.fill(out, -1);
		for (Map.Entry<String, Integer> e : worn.entrySet()) {
			Integer pos = EQUIPMENT_POS.get(e.getKey());
			if (pos != null && e.getValue() != null && e.getValue() > 0) {
				out[pos] = e.getValue();
			}
		}
		if (special > 0) {
			out[SPECIAL_POS] = special;
		}
		for (int i = 0; i < inventory.size(); i++) {
			Integer id = inventory.get(i);
			if (id != null && id > 0) {
				out[inventoryPos(i)] = id;
			}
		}
		for (int i = 0; i < pouch.size() && i < 4; i++) {
			Integer id = pouch.get(i);
			if (id != null && id > 0) {
				out[POUCH_START + i] = id;
			}
		}
		// No empty rows at the end.
		int end = out.length;
		while (end > 0 && out[end - 1] == -1) {
			end--;
		}
		return Arrays.copyOf(out, Math.max(ROW, (end + ROW - 1) / ROW * ROW));
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Syncs the bank proper, the inventory and the worn gear as bank-memory
 * sources {@code bank}, {@code inventory} (the INV container only) and
 * {@code worn} (the WORN container). All go through one
 * {@link SourceSyncer}: inventory changes while skilling are collapsed on
 * the default cadence, changes to an item an owned-item goal is counting go
 * up on the short one, and logout always flushes. The bank container only
 * updates while the bank is open, so its last-seen contents are cached and
 * re-sent with the inventory (the dedupe makes that free).
 *
 * <p>The website replaces each source it receives, so a source is only read when the read is
 * reliable ({@link CarriedReadGate}): logged in, the player loaded, the containers present, and for
 * the inventory and worn gear both INV and WORN arrived since the last login or hop. The two are read
 * together and always uploaded together ({@link SourceSyncer#linkSources}): the website reads an
 * {@code inventory} without {@code worn} as an older plugin's inventory + worn gear. Uploading never depends on
 * this feature's breaker: the syncer's timer, the logout flush and the bank-close flush all run as
 * {@link Guard#SYNC_FEATURE}, which is never turned off, so a change already read is not lost when
 * this feature is turned off.
 *
 * <p>Group Ironman: the shared group storage ({@code InventoryID.INV_GROUP_TEMP}) is synced as the source
 * {@code group_storage} while its interface ({@code InterfaceID.SHARED_BANK}) is open, through the same
 * syncer, and flushed when it closes.
 */
@Singleton
public class BankMemoryMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "bank-sync";

	static final String SOURCE_BANK = "bank";
	/** The INV container (older plugins sent INV + WORN merged under this source). */
	static final String SOURCE_INVENTORY = "inventory";
	/** The WORN container: the equipment the player wears. */
	static final String SOURCE_WORN = "worn";
	/** The Group Ironman shared group storage: the group's, synced by whoever opens it (the website shows the newest copy). */
	static final String SOURCE_GROUP_STORAGE = "group_storage";

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final SourceSyncer syncer;
	/** Deposits made where the bank container is never sent (deposit box, bank boat). */
	private final BankDepositLedger deposits;

	private GameState previousGameState = GameState.UNKNOWN;
	/** The group storage interface is open (its container is only read then). */
	private boolean groupStorageOpen;
	/** The nothing-equipped read went up this session (once; later changes go up with the containers). */
	private boolean nothingWornSent;
	/** When INV / WORN / the bank may be read (see the class comment). */
	private final CarriedReadGate gate = new CarriedReadGate();
	/** Inventory + gear as last read, for deposit diffs. */
	private Map<Integer, Integer> lastCarried = new LinkedHashMap<>();

	@Inject
	public BankMemoryMonitor(
			Client client,
			ClientThread clientThread,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ItemManager itemManager,
			Gson gson,
			ScheduledExecutorService executor) {
		executor = GuardedExecutor.wrap(GUARD_FEATURE, executor);
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.syncer = new SourceSyncer("bank memory", gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
		this.syncer.setPriorityFlush(apiClient::requestOutboxFlush);
		this.syncer.linkSources(SOURCE_INVENTORY, SOURCE_WORN);
		this.deposits = new BankDepositLedger(() -> Map.of());
	}

	/** Items reached the bank without a bank container being sent (a crew member banking the hold): count them as
	 * deposited and push. */
	public void onItemsBankedUnseen(Map<Integer, Integer> contents) {
		deposits.onContainerEmptied(contents);
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> push(true, false));
	}

	/** Deposit boxes (and the bank boat) open this interface instead of the bank. */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.BANK_DEPOSITBOX) {
				deposits.onDepositInterface(true);
			}
			if (event.getGroupId() == InterfaceID.SHARED_BANK) {
				groupStorageOpen = true;
				push(true, false);
			}
		});
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.BANK_DEPOSITBOX) {
				deposits.onDepositInterface(false);
			}
			if (event.getGroupId() == InterfaceID.SHARED_BANK) {
				groupStorageOpen = false;
			}
		});
		if (event.getGroupId() == InterfaceID.BANKMAIN || event.getGroupId() == InterfaceID.BANK_DEPOSITBOX
			|| event.getGroupId() == InterfaceID.SHARED_BANK) {
			// Leaving the bank: what moved between the bank and the inventory goes up now, not after the
			// debounce, so a client killed (or crashed) a few seconds later cannot lose it. A lost bank
			// upload is what makes the next session's inventory upload look like the items are gone.
			flushPending();
		}
	}

	/**
	 * Sends what is pending now (already read while it was reliable). Used when leaving the bank and
	 * on logout. Runs as {@link Guard#SYNC_FEATURE}, never skipped.
	 */
	public void flushPending() {
		Guard.run(Guard.SYNC_FEATURE, syncer::flushPending);
	}

	/**
	 * Re-reads the bank/inventory/equipment on the client thread and re-pushes
	 * it immediately, even if unchanged. Used by the roadmap panel's
	 * "Sync &amp; refresh" button. The bank container is only populated while
	 * the bank is (or was) open this session; if it is null we simply skip.
	 */
	public void forceSync() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			syncer.invalidate();
			push(false, true);
		});
	}

	/**
	 * Reads the bank / inventory / worn gear now and sends what changed at once (no debounce), then runs
	 * {@code then} (on the client thread). Used before the Slayer guide reads the gear, so an item just moved
	 * into the inventory counts. Unchanged contents are not re-sent.
	 */
	public void syncNow(Runnable then) {
		// Only the read is this feature's: with it turned off (or failing) {@code then} still runs.
		clientThread.invokeLater(() -> {
			Guard.run(GUARD_FEATURE, () -> push(true, true));
			then.run();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (SyncGuard.isLogout(previousGameState, newState)) {
			// A final sync, always (even when this feature was turned off): whatever changed since
			// the last upload was captured while logged in. Do not re-read the client here: the
			// player name is already gone and the containers may read empty.
			flushPending();
		}
		Guard.run(GUARD_FEATURE, () -> {
			gate.onGameState(newState);
			if (newState == GameState.LOGIN_SCREEN || newState == GameState.LOGGING_IN || newState == GameState.HOPPING) {
				nothingWornSent = false;
			}
			if (SyncGuard.isLogout(previousGameState, newState)) {
				groupStorageOpen = false;
				deposits.resetSession();
				lastCarried = new LinkedHashMap<>();
			}
			previousGameState = newState;
			if (newState == GameState.LOGGED_IN) {
				// The containers may have arrived while still loading (nothing was read then): read them
				// now that the player is in game. Unchanged contents are not re-sent.
				push(true, false);
			}
		});
	}

	public void stop() {
		syncer.stop();
	}

	/** Bank, inventory and worn-gear changes all feed the same debounced upload. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			int id = event.getContainerId();
			if (id != InventoryID.BANK && id != InventoryID.INV && id != InventoryID.WORN && id != InventoryID.INV_GROUP_TEMP) {
				return;
			}
			gate.onContainerChanged(id, client.getItemContainer(id) != null, client.getTickCount());
			push(true, false);
		});
	}

	/**
	 * Nothing equipped: the game never sends a WORN container, so once the inventory has been there
	 * {@link CarriedReadGate#NO_WORN_TICKS} ticks the carried items are read (worn gear empty). Unchanged
	 * contents are not re-sent.
	 */
	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (client.getItemContainer(InventoryID.WORN) == null
				&& gate.nothingWorn(false, client.getTickCount()) && !nothingWornSent) {
				nothingWornSent = true;
				push(true, false);
			}
		});
	}

	/**
	 * Reads bank + inventory + equipment, tells the goal tracker, and submits
	 * to the syncer. Must run on the client thread.
	 *
	 * @param inventoryOnlyOk when the bank has not been opened this session,
	 *                        still push just inventory + gear (otherwise a
	 *                        missing bank pushes nothing)
	 * @param immediate       skip the debounce
	 */
	private void push(boolean inventoryOnlyOk, boolean immediate) {
		Map<String, Map<Integer, Integer>> bySource = readSources(inventoryOnlyOk);
		if (bySource == null) {
			return;
		}
		trackDeposits(bySource);
		syncer.submitSources(bySource, immediate);
	}

	/**
	 * Items that left the inventory or gear in a deposit context are banked
	 * even though no bank container was sent. Once the bank proper is read it
	 * holds everything, so the deposits go back to empty alongside it.
	 */
	private void trackDeposits(Map<String, Map<Integer, Integer>> bySource) {
		Map<Integer, Integer> carried = carried(bySource);
		Map<Integer, Integer> removed = new LinkedHashMap<>();
		if (carried != null) {
			// Only a reliable read of the carried items is diffed (no inventory: nothing to compare).
			for (Map.Entry<Integer, Integer> e : lastCarried.entrySet()) {
				int delta = e.getValue() - carried.getOrDefault(e.getKey(), 0);
				if (delta > 0) {
					removed.put(e.getKey(), delta);
				}
			}
			lastCarried = new LinkedHashMap<>(carried);
		}
		boolean changed = false;
		if (bySource.containsKey(SOURCE_BANK)) {
			changed = deposits.onBankRead();
			bySource.put(BankDepositLedger.SOURCE, deposits.contents());
		} else if (deposits.onItemsRemoved(removed, client.getTickCount())) {
			changed = true;
		}
		if (changed || (!deposits.contents().isEmpty() && !bySource.containsKey(BankDepositLedger.SOURCE))) {
			bySource.put(BankDepositLedger.SOURCE, deposits.contents());
		}
	}

	/**
	 * Everything carried (inventory + worn gear summed per item) when both were read, else null. The
	 * deposit ledger diffs this: unequipping and banking a piece of gear is a deposit too. Pure.
	 */
	static Map<Integer, Integer> carried(Map<String, Map<Integer, Integer>> bySource) {
		Map<Integer, Integer> inv = bySource.get(SOURCE_INVENTORY);
		Map<Integer, Integer> worn = bySource.get(SOURCE_WORN);
		if (inv == null || worn == null) {
			return null;
		}
		Map<Integer, Integer> carried = new LinkedHashMap<>(inv);
		worn.forEach((id, q) -> carried.merge(id, q, Integer::sum));
		return carried;
	}

	private Map<String, Map<Integer, Integer>> readSources(boolean inventoryOnlyOk) {
		if (GameModeUtil.isSpecialGameMode(client)) {
			return null;
		}
		GameState state = client.getGameState();
		boolean playerLoaded = SyncGuard.getPlayerUsername(client) != null;
		if (!CarriedReadGate.inGame(state, playerLoaded)) {
			// Logging in, hopping, loading or the login screen: the containers may read null or empty.
			return null;
		}
		ItemContainer bankContainer = client.getItemContainer(InventoryID.BANK);
		if (bankContainer == null && !inventoryOnlyOk) {
			return null;
		}
		Map<String, Map<Integer, Integer>> bySource = new LinkedHashMap<>();
		if (gate.canReadBank(state, playerLoaded, bankContainer != null)) {
			Map<Integer, Integer> bankQuantities = new LinkedHashMap<>();
			ItemCollector.collectBankItems(bankContainer, itemManager, bankQuantities);
			bySource.put(SOURCE_BANK, bankQuantities);
		}
		ItemContainer groupStorage = client.getItemContainer(InventoryID.INV_GROUP_TEMP);
		if (gate.canReadGroupStorage(state, playerLoaded, groupStorage != null, groupStorageOpen)) {
			Map<Integer, Integer> groupQuantities = new LinkedHashMap<>();
			ItemCollector.collectBankItems(groupStorage, itemManager, groupQuantities);
			bySource.put(SOURCE_GROUP_STORAGE, groupQuantities);
		}
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (gate.canReadCarried(state, playerLoaded, inv != null, worn != null, client.getTickCount())) {
			// Read together, sent together: never one without the other. No WORN container (nothing equipped)
			// reads as empty worn gear.
			Map<Integer, Integer> invQuantities = new LinkedHashMap<>();
			ItemCollector.collectItems(inv, itemManager, invQuantities);
			Map<Integer, Integer> wornQuantities = new LinkedHashMap<>();
			if (worn != null) {
				ItemCollector.collectItems(worn, itemManager, wornQuantities);
			}
			bySource.put(SOURCE_INVENTORY, invQuantities);
			bySource.put(SOURCE_WORN, wornQuantities);
		} else {
			// Not known (yet): leave the server's inventory as it is rather than send a partial one.
		}
		return bySource.isEmpty() ? null : bySource;
	}

}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import lombok.Getter;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.BossGear;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * The active boss gear set from the website (Tools > Boss Gear > Use in RuneLite): loaded when the
 * Boss gear window opens, switchable from the window. What you carry is counted by
 * {@link FarmRunManager#carried(int)} (inventory, worn and rune pouch, variants included).
 *
 * <p>Network work runs on OkHttp threads; fields the window and the bank layout read are volatile.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class BossGearManager {
	private final Client client;
	private final OSRSCompanionApiClient apiClient;
	private final RoadmapManager roadmapManager;
	private final FarmRunManager farmRunManager;
	private final OSRSCompanionConfig config;
	private final ConfigManager configManager;

	@Getter
	private volatile BossGear set;
	@Getter
	private volatile List<BossGear.SetSummary> sets = Collections.emptyList();
	@Getter
	private volatile List<BossGear.CatalogBoss> catalog = Collections.emptyList();
	/** The gear mode of wiki presets (BossGear.MODE_*), as stored on the website. */
	@Getter
	private volatile String mode = BossGear.MODE_OWNED;
	@Getter
	private volatile String error;
	@Getter
	private volatile boolean loading;
	@Getter
	private volatile boolean loaded;
	@Getter
	private volatile boolean open;

	// ---- Loading ---------------------------------------------------------------------

	public void refresh() {
		String player = roadmapManager.getPlayerUsername();
		if (player == null) {
			error = "Log in to the game to load your boss gear.";
			return;
		}
		if (!roadmapManager.hasAppKey()) {
			error = "Add your App Key in the OSRS Companion settings first.";
			return;
		}
		loading = true;
		apiClient.getBossGear(player, callback(null));
	}

	/** Switches the active set (on the website too) and loads it. */
	public void activate(BossGear.SetSummary summary) {
		String player = roadmapManager.getPlayerUsername();
		if (summary == null || player == null || (set != null && set.getId() == summary.getId())) {
			return;
		}
		loading = true;
		apiClient.activateBossGear(summary.getId(), player, callback(summary.getName()));
	}

	/**
	 * Saves what you wear, carry and have in the rune pouch as your own set for the shown set's boss (named
	 * {@code name}, on the website too) and makes it the active build. Client thread (reads the containers).
	 */
	public void saveCurrentGear(String name) {
		String player = roadmapManager.getPlayerUsername();
		BossGear shown = set;
		if (player == null || shown == null || shown.getBoss() == null || !roadmapManager.hasAppKey()) {
			error = "Pick a boss build first, then save your gear for it.";
			return;
		}
		Map<String, Object> equipment = new java.util.LinkedHashMap<>();
		net.runelite.api.ItemContainer worn = client.getItemContainer(net.runelite.api.gameval.InventoryID.WORN);
		for (net.runelite.api.EquipmentInventorySlot slot : net.runelite.api.EquipmentInventorySlot.values()) {
			String key = WORN_KEYS.get(slot);
			net.runelite.api.Item it = worn == null ? null : worn.getItem(slot.getSlotIdx());
			if (key != null && it != null && it.getId() > 0) {
				equipment.put(key, it.getId());
			}
		}
		java.util.List<Object> inventory = new java.util.ArrayList<>();
		net.runelite.api.ItemContainer inv = client.getItemContainer(net.runelite.api.gameval.InventoryID.INV);
		for (int i = 0; i < 28; i++) {
			net.runelite.api.Item it = inv == null ? null : inv.getItem(i);
			if (it == null || it.getId() <= 0) {
				inventory.add(null);
				continue;
			}
			Map<String, Object> cell = new java.util.LinkedHashMap<>();
			ItemComposition comp = client.getItemDefinition(it.getId());
			boolean noted = comp != null && comp.getNote() != -1;
			cell.put("id", noted ? comp.getLinkedNoteId() : it.getId());
			if (it.getQuantity() > 1) {
				cell.put("q", it.getQuantity());
			}
			if (noted) {
				cell.put("noted", true);
			}
			inventory.add(cell);
		}
		java.util.List<Object> pouch = new java.util.ArrayList<>();
		for (Map.Entry<Integer, Integer> e : RunePouchMonitor.read(client).entrySet()) {
			Map<String, Object> cell = new java.util.LinkedHashMap<>();
			cell.put("id", e.getKey());
			cell.put("q", e.getValue());
			pouch.add(cell);
		}
		Map<String, Object> loadout = new java.util.LinkedHashMap<>();
		loadout.put("equipment", equipment);
		loadout.put("inventory", inventory);
		loadout.put("pouch", pouch);
		// The set it was made from: the shown set's style among the boss's setups.
		int setup = 0;
		for (BossGear.CatalogBoss b : catalog) {
			if (shown.getBoss().equals(b.getKey())) {
				setup = Math.max(0, b.getSetups().indexOf(shown.getStyle()));
			}
		}
		loading = true;
		apiClient.saveBossGearCustom(shown.getBoss(), setup, name, loadout, player, callback("your new set " + name));
	}

	/** The website's slot names for the worn slots. */
	private static final Map<net.runelite.api.EquipmentInventorySlot, String> WORN_KEYS = new java.util.EnumMap<>(net.runelite.api.EquipmentInventorySlot.class);

	static {
		Tables.map("wornKeys").forEach((slot, key) -> WORN_KEYS.put(net.runelite.api.EquipmentInventorySlot.valueOf(slot), key.getAsString()));
	}

	/** Switches to any boss preset (on the website too) and loads it. */
	public void activatePreset(BossGear.CatalogBoss boss, int setup) {
		String player = roadmapManager.getPlayerUsername();
		if (boss == null || player == null || setup < 0 || setup >= boss.getSetups().size()) {
			return;
		}
		loading = true;
		apiClient.activateBossGearPreset(boss.getKey(), setup, player, callback(boss.getName() + " - " + boss.getSetups().get(setup)));
	}

	/**
	 * Sets the gear mode of wiki presets (stored on the website, the Boss Gear page shows the same choice)
	 * and reloads the set: always the best in slot, the best owned item of the wiki's list, or that plus
	 * the best owned item of the setup's style where you own none of the list.
	 */
	public void setMode(String newMode) {
		String player = roadmapManager.getPlayerUsername();
		String before = mode;
		if (player == null || !roadmapManager.hasAppKey() || newMode == null || newMode.equals(before)) {
			return;
		}
		// Shown straight away; the response confirms it.
		mode = newMode;
		loading = true;
		apiClient.setBossGearMode(newMode, player, new OSRSCompanionApiClient.RoadmapCallback<BossGear.Response>() {
			@Override
			public void onSuccess(BossGear.Response result) {
				callback(null).onSuccess(result);
			}

			@Override
			public void onError(String message) {
				mode = before;
				error = "Could not change the gear mode (" + message + ").";
				loading = false;
			}
		});
	}

	private OSRSCompanionApiClient.RoadmapCallback<BossGear.Response> callback(String switchedTo) {
		return new OSRSCompanionApiClient.RoadmapCallback<BossGear.Response>() {
			@Override
			public void onSuccess(BossGear.Response result) {
				BossGear before = set;
				set = result.getSet();
				// Another build was picked (here or with Use in RuneLite on the website): it is in use again.
				if (before != null && set != null && before.getId() != set.getId()) {
					setSetActive(true);
				}
				sets = result.getSets();
				catalog = result.getCatalog();
				mode = result.getMode();
				error = null;
				loaded = true;
				loading = false;
			}

			@Override
			public void onError(String message) {
				error = (switchedTo == null ? "Could not load your boss gear" : "Could not switch to " + switchedTo) + " (" + message + ").";
				loading = false;
			}
		};
	}

	// ---- The window --------------------------------------------------------------------

	public void toggle() {
		if (open) {
			close();
		} else {
			openWindow();
		}
	}

	/** Opens the window and always re-reads the set, so one just picked on the website shows straight away. */
	public void openWindow() {
		open = true;
		if (!loading) {
			refresh();
		}
	}

	public void close() {
		open = false;
	}

	// ---- Read by the window and the bank layout ----------------------------------------------

	/**
	 * Whether the selected setup is in use: Active lays out the bank and shows the gear, Inactive keeps it
	 * selected but leaves both alone (the side panel switch, stored in this plugin's settings).
	 */
	public boolean isSetActive() {
		return set != null && config.bossGearActive();
	}

	public void setSetActive(boolean active) {
		if (config.bossGearActive() != active) {
			configManager.setConfiguration(OSRSCompanionConfig.CONFIG_GROUP, "bossGearActive", active);
		}
	}

	/** A slot's tooltip (the window and the side panel): the item, what the setup picked and how many you carry. */
	public String slotTooltip(BossGear.Item it, int need, boolean synced) {
		int carried = carried(it);
		int want = Math.max(1, need);
		StringBuilder tip = new StringBuilder(it.getName());
		if (it.getQty() > 1) {
			tip.append(" x").append(it.getQty());
		}
		if (it.isNoted()) {
			tip.append(" (noted)");
		}
		if (it instanceof BossGear.Slot) {
			BossGear.Slot s = (BossGear.Slot) it;
			String where = "special".equals(s.getSlot()) ? "Special attack: " : "switch".equals(s.getSlot()) ? "Alternate weapon: "
				: "switch_shield".equals(s.getSlot()) ? "Alternate off-hand: " : "";
			tip.insert(0, where);
			tip.append(s.isAlternative() ? " - Alternative for " + s.getAltFor() + " (not owned)"
				: "bis".equals(s.getStatus()) ? " - best in slot" : "partial".equals(s.getStatus()) ? " - best you own (rank " + s.getRank() + ")"
				: "missing".equals(s.getStatus()) ? " - best in slot, not owned" : "");
		} else if (it.isAlternative()) {
			tip.append(" - Instead of ").append(it.getAltFor()).append(" (not owned)");
		}
		if (it.getNeed() != null) {
			tip.append(" - ").append(it.getNeed());
		}
		tip.append(" - carrying ").append(carried);
		if (carried < want) {
			tip.append(it.isOwned() ? ", in your bank or storage" : synced ? ", not in your bank" : "");
		}
		return tip.toString();
	}

	/** The tooltip of an empty inventory slot whose switch is already worn. */
	static String wornTooltip(BossGear.Item it) {
		return "Empty: you already wear " + it.getName() + ", the best for this switch (instead of " + it.getAltFor() + ")";
	}

	/** How many of the item you carry (inventory, worn, rune pouch), counting any of its versions. */
	public int carried(BossGear.Item item) {
		int best = 0;
		for (int id : item.getIds()) {
			best = Math.max(best, farmRunManager.carried(id));
		}
		return best;
	}

	/** How many of each item (by its shown id) the whole inventory and pouch need: one per slot, or the stack size. */
	public Map<Integer, Integer> inventoryNeeds() {
		BossGear s = set;
		Map<Integer, Integer> out = new HashMap<>();
		if (s == null) {
			return out;
		}
		for (BossGear.Item it : s.getInventory()) {
			if (it != null) {
				out.merge(it.getItem(), it.getQty(), Integer::sum);
			}
		}
		for (BossGear.Item it : s.getPouch()) {
			out.merge(it.getItem(), it.getQty(), Integer::sum);
		}
		return out;
	}

	/** Whether the set needs this item: one of an item's ids, another version of it (charges) or the same name. For the bank. */
	public boolean needs(int itemId) {
		BossGear s = set;
		if (s == null) {
			return false;
		}
		int base = ItemVariationMapping.map(itemId);
		// The ammo / spell options and charge materials the bank layout adds.
		for (int id : s.supplyItems(config.slayerGearSupplyOptions())) {
			if (id == itemId || ItemVariationMapping.map(id) == base) {
				return true;
			}
		}
		for (com.osrscompanion.model.SlayerGear.Bring b : s.getBring()) {
			for (int id : b.getItems()) {
				if (id == itemId || ItemVariationMapping.map(id) == base) {
					return true;
				}
			}
		}
		String name = null;
		for (BossGear.Item it : items(s)) {
			for (int id : it.getIds()) {
				if (id == itemId || ItemVariationMapping.map(id) == base) {
					return true;
				}
			}
		}
		for (BossGear.Item it : items(s)) {
			if (name == null) {
				name = nameOf(itemId);
				if (name == null) {
					return false;
				}
			}
			if (name.equals(nameOf(it.getItem()))) {
				return true;
			}
		}
		return false;
	}

	/** Every item of the set: worn (and special attack), inventory and rune pouch. */
	static List<BossGear.Item> items(BossGear s) {
		List<BossGear.Item> all = new java.util.ArrayList<>(s.getEquipment());
		for (BossGear.Item it : s.getInventory()) {
			if (it != null) {
				all.add(it);
			}
		}
		all.addAll(s.getPouch());
		return all;
	}

	/** Item names (lower case) read on the client thread, for the side panel which paints on Swing's thread. */
	private final Map<Integer, String> names = new java.util.concurrent.ConcurrentHashMap<>();

	/** The item's name in lower case; off the client thread only when it was read there before, else null. */
	private String nameOf(int itemId) {
		String cached = names.get(itemId);
		if (cached != null || !client.isClientThread()) {
			return cached;
		}
		ItemComposition comp = client.getItemDefinition(itemId);
		String name = comp == null || comp.getName() == null ? null : comp.getName().toLowerCase();
		if (name != null) {
			names.put(itemId, name);
		}
		return name;
	}

	public void clear() {
		open = false;
		set = null;
		sets = Collections.emptyList();
		mode = BossGear.MODE_OWNED;
		loaded = false;
		error = null;
	}
}

package com.osrscompanion;

import com.osrscompanion.model.BossGear;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.swing.JComponent;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

/**
 * The active boss setup in the side panel (Boss page, "Gear display" on): the worn gear in the
 * game's layout with the special attack weapon and the alternate weapon beside it, the 28 inventory
 * slots and the rune pouch, each slot coloured like the boss gear window (carried, in the bank, missing).
 */
class BossGearPanelView extends JComponent {
	private static final int SLOT = 36;
	private static final int CELL = 40;
	private static final int GRID = 4 * CELL - 4;
	private static final Color CARD = new Color(0x1A1F2B);
	private static final Color EDGE = new Color(0x313A4E);
	private static final Color HEADING = new Color(0x8C96A8);
	private static final Color SLOT_FILL = new Color(0x11151E);
	private static final Color SLOT_EDGE = new Color(0x2A3242);
	private static final Color GREEN = new Color(0x0DC10D);
	private static final Color STORED = new Color(0xFF981F);
	private static final Color RED = new Color(0xFF3D3D);
	private static final Color BEIGE = new Color(0xC9B98F);
	private static final Color YELLOW = new Color(0xFFFF00);
	private static final Color GREY = new Color(0x9A9080);

	private final BossGearManager manager;
	private final ItemManager itemManager;
	/** Each drawn slot's area and tooltip, from the last paint. */
	private volatile List<Tip> tips = Collections.emptyList();

	private static final class Tip {
		final Rectangle area;
		final String text;

		Tip(Rectangle area, String text) {
			this.area = area;
			this.text = text;
		}
	}

	BossGearPanelView(BossGearManager manager, ItemManager itemManager) {
		this.manager = manager;
		this.itemManager = itemManager;
		setMinimumSize(new Dimension(120, 54));
		setToolTipText("");
	}

	/** As tall as what it shows now: the side panel lays it out again when this changes. */
	@Override
	public Dimension getPreferredSize() {
		return new Dimension(200, wantedHeight());
	}

	@Override
	public Dimension getMaximumSize() {
		return new Dimension(Integer.MAX_VALUE, wantedHeight());
	}

	@Override
	public String getToolTipText(MouseEvent e) {
		for (Tip t : tips) {
			if (t.area.contains(e.getPoint())) {
				return t.text;
			}
		}
		return null;
	}

	/** The card's height: two lines of text without a set, else the three grids (no pouch: 60 less). */
	private int wantedHeight() {
		BossGear set = manager.getSet();
		if (set == null || !manager.isSetActive()) {
			return 54;
		}
		return set.getPouch().isEmpty() ? 578 : 638;
	}

	@Override
	protected void paintComponent(Graphics graphics) {
		Graphics2D g = (Graphics2D) graphics.create();
		try {
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, 14, 14);
			g.setColor(CARD);
			g.fill(card);
			g.setColor(EDGE);
			g.draw(card);
			BossGear set = manager.getSet();
			List<Tip> newTips = new ArrayList<>();
			if (set == null || !manager.isSetActive()) {
				String[] lines = set == null
					? new String[]{manager.isLoading() ? "Loading..." : "No setup picked yet", "Load one in Gear overview"}
					: new String[]{"Gear hidden while Inactive", "Set the setup Active above to show it"};
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, "ACTIVE GEAR", 12, 16, HEADING);
				g.setFont(FontManager.getRunescapeFont());
				shadow(g, fit(lines[0], g.getFontMetrics(), w - 24), 12, 32, Color.WHITE);
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, fit(lines[1], g.getFontMetrics(), w - 24), 12, 45, new Color(0xC9D1DE));
				tips = newTips;
				return;
			}

			int x0 = (w - GRID) / 2;
			g.setFont(FontManager.getRunescapeSmallFont());
			shadow(g, "ACTIVE GEAR", 12, 16, HEADING);

			// Worn: the game's 3-column doll, the special attack weapon in the 4th column on the weapon row
			// (on the cape row when there is an alternate weapon: that one, and its off-hand, go below it).
			g.setFont(FontManager.getRunescapeBoldFont());
			shadow(g, "Worn", x0, 36, Color.WHITE);
			for (int r = 0; r < BossGearWindow.EQUIPMENT.length; r++) {
				for (int col = 0; col < 3; col++) {
					String name = BossGearWindow.EQUIPMENT[r][col];
					if (name != null) {
						Rectangle area = new Rectangle(x0 + col * CELL, 44 + r * CELL, SLOT, SLOT);
						slot(g, area, set.slot(name), 0, set.isSynced(), newTips);
						if ("shield".equals(name) && set.isTwoHanded() && set.slot(name) == null) {
							// Nothing in the off-hand with a two-handed weapon.
							g.setFont(FontManager.getRunescapeSmallFont());
							shadow(g, "2H", area.x + (SLOT - g.getFontMetrics().stringWidth("2H")) / 2, area.y + SLOT / 2 + 4, GREY);
							newTips.add(new Tip(area, "Shield: empty, the weapon is two-handed"));
						}
					}
				}
			}
			BossGear.Slot special = set.slot("special");
			BossGear.Slot alternate = set.slot("switch");
			BossGear.Slot alternateShield = set.slot("switch_shield");
			int sx = x0 + 3 * CELL;
			g.setFont(FontManager.getRunescapeSmallFont());
			int specialY = alternate == null ? 124 : 84;
			if (special != null) {
				shadow(g, "Spec", sx + (SLOT - g.getFontMetrics().stringWidth("Spec")) / 2, specialY - 6, GREY);
				slot(g, new Rectangle(sx, specialY, SLOT, SLOT), special, 0, set.isSynced(), newTips);
			}
			if (alternate != null) {
				shadow(g, "Alt", sx + (SLOT - g.getFontMetrics().stringWidth("Alt")) / 2, 158, GREY);
				slot(g, new Rectangle(sx, 164, SLOT, SLOT), alternate, 0, set.isSynced(), newTips);
				if (alternateShield != null) {
					slot(g, new Rectangle(sx, 204, SLOT, SLOT), alternateShield, 0, set.isSynced(), newTips);
				}
			}

			// Inventory: 4 x 7.
			g.setFont(FontManager.getRunescapeBoldFont());
			shadow(g, "Inventory", x0, 260, Color.WHITE);
			List<BossGear.Item> inv = set.getInventory();
			Map<Integer, Integer> needs = manager.inventoryNeeds();
			for (int i = 0; i < 28; i++) {
				BossGear.Item it = i < inv.size() ? inv.get(i) : null;
				Rectangle r = new Rectangle(x0 + (i % 4) * CELL, 268 + (i / 4) * CELL, SLOT, SLOT);
				slot(g, r, it, it == null ? 0 : needs.getOrDefault(it.getItem(), it.getQty()), set.isSynced(), newTips);
				BossGear.Item wornHere = it == null ? set.wornAt(i) : null;
				if (wornHere != null) {
					// The best for this switch is already worn: empty, marked.
					g.setFont(FontManager.getRunescapeSmallFont());
					shadow(g, "W", r.x + r.width / 2 - 3, r.y + r.height / 2 + 4, GREEN);
					newTips.add(new Tip(r, BossGearManager.wornTooltip(wornHere)));
				}
			}
			if (inv.isEmpty()) {
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, fit("The wiki has no inventory for this setup.", g.getFontMetrics(), GRID), x0, 268 + 3 * CELL + 22, new Color(0xAEB6C4));
			}
			int y = 268 + 7 * CELL - 4;

			// Rune pouch: one row.
			if (!set.getPouch().isEmpty()) {
				g.setFont(FontManager.getRunescapeBoldFont());
				shadow(g, "Rune pouch", x0, 564, Color.WHITE);
				int px = x0;
				for (BossGear.Item it : set.getPouch()) {
					if (px + SLOT > x0 + GRID + 1) {
						break;
					}
					slot(g, new Rectangle(px, 572, SLOT, SLOT), it, needs.getOrDefault(it.getItem(), it.getQty()), set.isSynced(), newTips);
					px += CELL;
				}
				y = 572 + SLOT;
			}

			// Legend.
			g.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics fm = g.getFontMetrics();
			int ly = y + 24;
			int lx = x0;
			shadow(g, "Carried", lx, ly, GREEN);
			lx += fm.stringWidth("Carried") + 10;
			String stored = set.isSynced() ? "In bank (B)" : "Not synced";
			shadow(g, stored, lx, ly, set.isSynced() ? STORED : BEIGE);
			lx += fm.stringWidth(stored) + 10;
			shadow(g, "Missing", lx, ly, RED);
			tips = newTips;
		} finally {
			g.dispose();
		}
	}

	/** One slot: the item at its own size and a border saying carried (green), in the bank (orange, B) or missing (red). */
	private void slot(Graphics2D g, Rectangle r, BossGear.Item it, int need, boolean synced, List<Tip> newTips) {
		g.setColor(SLOT_FILL);
		g.fillRect(r.x, r.y, r.width, r.height);
		if (it == null) {
			g.setColor(SLOT_EDGE);
			g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
			return;
		}
		BufferedImage icon = itemManager.getImage(it.getItem(), it.getQty(), it.getQty() > 1);
		if (icon != null && icon.getWidth() > 0) {
			g.drawImage(icon, r.x + (r.width - icon.getWidth()) / 2, r.y + (r.height - icon.getHeight()) / 2, null);
		}
		int carried = manager.carried(it);
		Color edge;
		boolean inBank = false;
		if (carried >= Math.max(1, need)) {
			edge = GREEN;
		} else if (it.isOwned()) {
			edge = STORED;
			inBank = true;
		} else {
			edge = synced ? RED : BEIGE;
		}
		g.setColor(edge);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		g.setFont(FontManager.getRunescapeSmallFont());
		if (inBank) {
			shadow(g, "B", r.x + r.width - 8, r.y + r.height - 3, STORED);
		}
		if (it.isNoted()) {
			shadow(g, "N", r.x + 2, r.y + r.height - 3, YELLOW);
		}
		if (it.isAlternative()) {
			shadow(g, "A", r.x + 2, r.y + 10, BossGearWindow.ALT);
		}
		newTips.add(new Tip(r, manager.slotTooltip(it, need, synced)));
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color) {
		g.setColor(new Color(0, 0, 0, 170));
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String fit(String s, FontMetrics fm, int width) {
		if (fm.stringWidth(s) <= width) {
			return s;
		}
		String t = s;
		while (t.length() > 1 && fm.stringWidth(t + "...") > width) {
			t = t.substring(0, t.length() - 1);
		}
		return t + "...";
	}
}

package com.osrscompanion;

import static com.osrscompanion.GameUi.*;

import com.osrscompanion.model.BossGear;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * The boss gear window, drawn over the game like the farm run window: the active set's boss and
 * style (with a switcher), the worn equipment in the game's layout with the special attack weapon and
 * the alternate weapon under it, the 28 inventory slots and the rune pouch, each slot coloured by
 * whether you carry it, have it stored, or miss it; the gear mode chips and Go to wiki on the right.
 */
@Singleton
public class BossGearWindow extends GameWindow {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "boss-gear-window";

	private static final int MAX_WIDTH = 640;
	private static final int MAX_HEIGHT = 440;
	private static final int MIN_WIDTH = 480;
	private static final int MIN_HEIGHT = 320;
	private static final int SUBTITLE_HEIGHT = 22;
	private static final int SLOT_GAP = 3;
	private static final int BUTTON_WIDTH = 110;
	private static final int BUTTON_HEIGHT = 20;
	private static final Color STORED = new Color(0xFF981F);
	/** The "A" on slots and inventory items filled with an owned alternative. */
	static final Color ALT = new Color(0x93B4FF);
	/** The gear mode's label and chips above the buttons. */
	private static final int MODE_ROW = 40;
	private static final int CHIP_HEIGHT = 18;

	/** Worn-equipment layout as in the game: 3 columns, null = no slot there. */
	static final String[][] EQUIPMENT = {
		{null, "head", null}, {"cape", "neck", "ammo"}, {"weapon", "body", "shield"}, {null, "legs", null}, {"hands", "feet", "ring"},
	};

	private final BossGearManager manager;
	private final ItemManager itemManager;
	private final SuppliesCheck supplies;

	/** In the switcher: first row shown (mouse wheel scrolls) and the boss whose setups are unfolded. */
	private volatile int switcherScroll;
	private volatile String expandedBoss;
	/** The switcher's tab: {@link #TAB_RECENT}, {@link #TAB_WIKI} or {@link #TAB_CUSTOM}. */
	private volatile int tab;
	private static final int TAB_RECENT = 0;
	private static final int TAB_WIKI = 1;
	private static final int TAB_CUSTOM = 2;
	/** How many builds the Recently used tab lists. */
	private static final int RECENT_MAX = 10;

	private final net.runelite.client.game.chatbox.ChatboxPanelManager chatbox;
	private final net.runelite.client.callback.ClientThread clientThread;

	@Inject
	public BossGearWindow(Client client, BossGearManager manager, ItemManager itemManager, SuppliesCheck supplies,
		net.runelite.client.game.chatbox.ChatboxPanelManager chatbox, net.runelite.client.callback.ClientThread clientThread) {
		super(client, GUARD_FEATURE);
		this.manager = manager;
		this.itemManager = itemManager;
		this.supplies = supplies;
		this.chatbox = chatbox;
		this.clientThread = clientThread;
	}

	// ------------------------------------------------------------------ render

	@Override
	public Dimension render(Graphics2D g) {
		return Guard.render(GUARD_FEATURE, () -> {
			List<Hit> newHits = new ArrayList<>();
			Rectangle win = frame(g, client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null && manager.isOpen(), MAX_WIDTH, MAX_HEIGHT, MIN_WIDTH, MIN_HEIGHT, "Boss Gear", newHits);
			if (win == null) {
				return null;
			}
			int x = win.x;
			int y = win.y;
			int w = win.width;
			int h = win.height;

			BossGear set = manager.getSet();
			if (set == null) {
				message(g, win);
				Rectangle pick = null;
				if (!manager.getCatalog().isEmpty()) {
					pick = new Rectangle(x + (w - 120) / 2, y + h / 2 + 30, 120, BUTTON_HEIGHT);
					button(g, pick, switcherOpen ? "Close" : "Pick a build", false);
					newHits.add(new Hit(pick, this::toggleSwitcher, "Load a wiki preset or one of your custom builds", true));
				}
				if (switcherOpen && pick != null) {
					renderSwitcher(g, new Rectangle(x + (w - 300) / 2, y + TITLE_HEIGHT + 8, 300, 0), win, newHits);
				}
				finish(g, win, newHits);
				return new Dimension(w, h);
			}

			Rectangle switchButton = subtitle(g, set, win, newHits);
			int bodyY = y + TITLE_HEIGHT + SUBTITLE_HEIGHT + 6;
			int bodyBottom = y + h - 10;
			int bodyH = bodyBottom - bodyY;
			int slot = Math.max(26, Math.min(40, (bodyH - 52) / 7 - SLOT_GAP));
			int cell = slot + SLOT_GAP;

			// Worn equipment (and the special attack weapon) on the left.
			Rectangle worn = new Rectangle(x + 8, bodyY, 3 * cell + 20, bodyH);
			panel(g, worn);
			g.setFont(FontManager.getRunescapeBoldFont());
			text(g, "Worn", worn.x + 10, worn.y + 18, ORANGE);
			int ex = worn.x + 10;
			int ey = worn.y + 26;
			for (int r = 0; r < EQUIPMENT.length; r++) {
				for (int c = 0; c < 3; c++) {
					String name = EQUIPMENT[r][c];
					if (name != null) {
						Rectangle area = new Rectangle(ex + c * cell, ey + r * cell, slot, slot);
						drawSlot(g, area, set.slot(name), 0, set.isSynced(), newHits);
						if ("shield".equals(name) && set.isTwoHanded() && set.slot(name) == null) {
							// Nothing in the off-hand with a two-handed weapon.
							g.setFont(FontManager.getRunescapeSmallFont());
							centred(g, "2H", area.x + area.width / 2, area.y + area.height / 2 + 4, GREY);
							newHits.add(new Hit(area, () -> { }, "Shield: empty, the weapon is two-handed"));
						}
					}
				}
			}
			// Under the doll: the special attack weapon, and the alternate weapon (with its off-hand) beside it.
			BossGear.Slot special = set.slot("special");
			BossGear.Slot alternate = set.slot("switch");
			BossGear.Slot alternateShield = set.slot("switch_shield");
			int extraY = ey + 5 * cell + 16;
			if ((special != null || alternate != null) && extraY + slot <= worn.y + worn.height) {
				g.setFont(FontManager.getRunescapeSmallFont());
				if (alternate == null) {
					text(g, "Special attack", ex, extraY - 4, BEIGE);
					drawSlot(g, new Rectangle(ex + cell, extraY, slot, slot), special, 0, set.isSynced(), newHits);
				} else {
					if (special != null) {
						centred(g, "Spec", ex + slot / 2, extraY - 4, BEIGE);
						drawSlot(g, new Rectangle(ex, extraY, slot, slot), special, 0, set.isSynced(), newHits);
					}
					text(g, "Alt weapon", ex + cell, extraY - 4, BEIGE);
					drawSlot(g, new Rectangle(ex + cell, extraY, slot, slot), alternate, 0, set.isSynced(), newHits);
					if (alternateShield != null) {
						drawSlot(g, new Rectangle(ex + 2 * cell, extraY, slot, slot), alternateShield, 0, set.isSynced(), newHits);
					}
				}
			}

			// Inventory: 4 x 7.
			Rectangle invArea = new Rectangle(worn.x + worn.width + 8, bodyY, 4 * cell + 20, bodyH);
			panel(g, invArea);
			g.setFont(FontManager.getRunescapeBoldFont());
			text(g, "Inventory", invArea.x + 10, invArea.y + 18, ORANGE);
			List<BossGear.Item> inv = set.getInventory();
			Map<Integer, Integer> needs = manager.inventoryNeeds();
			for (int i = 0; i < 28; i++) {
				Rectangle r = new Rectangle(invArea.x + 10 + (i % 4) * cell, invArea.y + 26 + (i / 4) * cell, slot, slot);
				BossGear.Item it = i < inv.size() ? inv.get(i) : null;
				drawSlot(g, r, it, it == null ? 0 : needs.getOrDefault(it.getItem(), it.getQty()), set.isSynced(), newHits);
				BossGear.Item wornHere = it == null ? set.wornAt(i) : null;
				if (wornHere != null) {
					// The best for this switch is already worn: empty, marked.
					g.setFont(FontManager.getRunescapeSmallFont());
					text(g, "W", r.x + r.width / 2 - 3, r.y + r.height / 2 + 4, GREEN);
					newHits.add(new Hit(r, () -> { }, BossGearManager.wornTooltip(wornHere)));
				}
			}
			if (inv.isEmpty()) {
				g.setFont(FontManager.getRunescapeSmallFont());
				for (String line : wrap("The wiki has no inventory for this setup.", g.getFontMetrics(), invArea.width - 20)) {
					text(g, line, invArea.x + 10, invArea.y + bodyH / 2, BEIGE);
				}
			}

			// Rune pouch, legend and buttons on the right.
			Rectangle side = new Rectangle(invArea.x + invArea.width + 8, bodyY, x + w - 8 - (invArea.x + invArea.width + 8), bodyH);
			renderSide(g, set, side, slot, needs, newHits);

			if (switcherOpen && switchButton != null) {
				renderSwitcher(g, switchButton, win, newHits);
			}
			finish(g, win, newHits);
			return new Dimension(w, h);
		});
	}

	/**
	 * Boss, build and where it comes from (wiki preset / custom build), the button to change it, and
	 * how much of it you carry (or that it is Inactive, with a button to set it active). Returns the button.
	 */
	private Rectangle subtitle(Graphics2D g, BossGear set, Rectangle win, List<Hit> newHits) {
		int subY = win.y + TITLE_HEIGHT + 16;
		BossGear.SetSummary inUse = inUse(set);
		boolean custom = inUse != null && inUse.isCustom();
		g.setFont(FontManager.getRunescapeFont());
		int after = text(g, truncate(set.getBossName(), g.getFontMetrics(), Math.min(170, win.width / 4)), win.x + 12, subY, Color.WHITE);
		g.setFont(FontManager.getRunescapeSmallFont());
		String label = custom && inUse.getLabel() != null ? inUse.getLabel() : set.getStyle();
		after = text(g, truncate("  " + label, g.getFontMetrics(), 120), after, subY, BEIGE);
		badge(g, custom ? "Custom build" : "Wiki preset", after + 8, subY, custom ? YELLOW : BEIGE);
		// Right side: Change build, with Inactive and Set active before it while the setup is Inactive.
		int right = win.x + win.width - 12;
		Rectangle switchButton = new Rectangle(right - 84, subY - 13, 84, 17);
		button(g, switchButton, switcherOpen ? "Close" : "Change build", false);
		newHits.add(new Hit(switchButton, this::toggleSwitcher, "Load a wiki preset or one of your custom builds", true));
		int left = switchButton.x;
		if (!manager.isSetActive()) {
			Rectangle activate = new Rectangle(switchButton.x - 8 - 76, subY - 13, 76, 17);
			button(g, activate, "Set active", false);
			newHits.add(new Hit(activate, () -> manager.setSetActive(true), "Lay out the bank for this setup again"));
			badge(g, "Inactive", activate.x - 6 - 54, subY, ORANGE);
			left = activate.x - 6 - 54;
		}
		// Save what you wear and carry as your own set for this boss (named in the chatbox).
		Rectangle save = new Rectangle(left - 8 - 88, subY - 13, 88, 17);
		if (save.x > after + 70) {
			button(g, save, "Save my gear", manager.isLoading());
			newHits.add(new Hit(save, this::askSaveName,
				"Save your worn gear, inventory and rune pouch as your own " + set.getBossName() + " set (also on the website)"));
		}
		return switchButton;
	}

	/**
	 * Asks for the set's name in the chatbox, then saves the gear worn and carried now. Starts with the
	 * loaded build's name (your custom build's own name, else the wiki setup's style): saving under the
	 * name of one of your sets for this boss overwrites it, so Enter updates the build you are on.
	 */
	private void askSaveName() {
		BossGear set = manager.getSet();
		if (set == null) {
			return;
		}
		BossGear.SetSummary loaded = inUse(set);
		chatbox.openTextInput("Name your " + set.getBossName() + " set (same name overwrites):")
			.value(loaded != null && loaded.getLabel() != null ? loaded.getLabel() : set.getStyle())
			.onDone((String name) -> Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
				String n = name == null ? "" : name.trim();
				if (!n.isEmpty()) {
					manager.saveCurrentGear(n);
				}
			}))
			.build();
	}

	/** A small labelled box on the subtitle line (Wiki preset, Custom build, Inactive). Returns its right edge. */
	private static int badge(Graphics2D g, String label, int x, int baseline, Color color) {
		g.setFont(FontManager.getRunescapeSmallFont());
		int bw = Math.max(54, g.getFontMetrics().stringWidth(label) + 10);
		box(g, new Rectangle(x, baseline - 12, bw, 15), PANEL, PANEL_EDGE, PANEL_INNER);
		centred(g, label, x + bw / 2, baseline - 1, color);
		return x + bw;
	}

	/** The saved set the loaded build is (for its name and whether it is a custom build), or null. */
	private BossGear.SetSummary inUse(BossGear set) {
		if (set == null) {
			return null;
		}
		for (BossGear.SetSummary s : manager.getSets()) {
			if (s.getId() == set.getId()) {
				return s;
			}
		}
		return null;
	}

	/** Opens the switcher on Recently used (the wiki presets when you used none yet), or closes it. */
	private void toggleSwitcher() {
		if (switcherOpen) {
			switcherOpen = false;
			return;
		}
		tab = manager.getSets().isEmpty() ? TAB_WIKI : TAB_RECENT;
		switcherScroll = 0;
		switcherOpen = true;
	}

	private void renderSide(Graphics2D g, BossGear set, Rectangle area, int slot, Map<Integer, Integer> needs, List<Hit> newHits) {
		panel(g, area);
		int lx = area.x + 10;
		int ly = area.y + 18;
		if (!set.getPouch().isEmpty()) {
			g.setFont(FontManager.getRunescapeBoldFont());
			text(g, "Rune pouch", lx, ly, ORANGE);
			int px = lx;
			for (BossGear.Item it : set.getPouch()) {
				if (px + slot > area.x + area.width - 6) {
					break;
				}
				drawSlot(g, new Rectangle(px, ly + 8, slot, slot), it, needs.getOrDefault(it.getItem(), it.getQty()), set.isSynced(), newHits);
				px += slot + SLOT_GAP;
			}
			ly += slot + 26;
			if (set.getSpellbook() != null) {
				// The spellbook the pouch's runes are for (thralls: Arceuus, Vengeance: Lunar, barrages: Ancient).
				g.setFont(FontManager.getRunescapeSmallFont());
				text(g, "Spellbook: " + set.getSpellbook(), lx, ly - 4, BEIGE);
				ly += 12;
			}
		}
		g.setFont(FontManager.getRunescapeSmallFont());
		int textW = area.width - 20;
		if (set.getInventoryLabel() != null) {
			for (String line : wrap("Inventory: " + set.getInventoryLabel(), g.getFontMetrics(), textW)) {
				text(g, line, lx, ly, BEIGE);
				ly += 13;
			}
			ly += 4;
		}
		// The supplies check from the last time the bank was open with this setup.
		SuppliesCheck.Result check = supplies.getBoss();
		if (check != null && check.forId == set.getId()) {
			Color tone = check.trips < 1 ? RED : check.trips < 3 ? ORANGE : GREEN;
			String line = check.headline() + (check.runsOut == null ? "" : " (runs out of: " + check.runsOut + ")") + ", at your last bank visit.";
			for (String l : wrap(line, g.getFontMetrics(), textW)) {
				text(g, l, lx, ly, tone);
				ly += 13;
			}
			ly += 4;
		}
		text(g, "Carried", lx, ly, GREEN);
		ly += 13;
		text(g, set.isSynced() ? "In your bank or storage (B)" : "Not synced: sync your bank", lx, ly, set.isSynced() ? STORED : BEIGE);
		ly += 13;
		text(g, "Missing", lx, ly, RED);
		ly += 18;
		String hint = manager.isSetActive() ? "Open your bank with this window open: it shows only these items, laid out like your gear and inventory."
			: "Inactive: the bank is left alone. Press Set active to lay it out.";
		for (String line : wrap(hint, g.getFontMetrics(), textW)) {
			if (ly > area.y + area.height - BUTTON_HEIGHT - 16 - MODE_ROW) {
				break;
			}
			text(g, line, lx, ly, GREY);
			ly += 13;
		}
		// Go to wiki and Refresh side by side at the bottom, the gear mode above them.
		int bw = Math.min(BUTTON_WIDTH, (area.width - 26) / 2);
		int by = area.y + area.height - BUTTON_HEIGHT - 10;
		int bx = area.x + (area.width - 2 * bw - 6) / 2;
		Rectangle wiki = new Rectangle(bx, by, bw, BUTTON_HEIGHT);
		Rectangle refresh = new Rectangle(bx + bw + 6, by, bw, BUTTON_HEIGHT);
		modeChips(g, set, new Rectangle(area.x + 10, by - MODE_ROW, area.width - 20, MODE_ROW - 6), newHits);
		String url = set.getUrl();
		button(g, wiki, "Go to wiki", url == null);
		if (url != null) {
			newHits.add(new Hit(wiki, () -> LinkBrowser.browse(url), "Open the " + set.getBossName() + " strategy guide on the OSRS Wiki in your browser"));
		}
		button(g, refresh, manager.isLoading() ? "Loading..." : "Refresh", manager.isLoading());
		newHits.add(new Hit(refresh, manager::refresh, "Reload your builds from the website"));
	}

	/**
	 * The gear mode of wiki presets as three chips (stored on the website, like the Boss Gear page's
	 * choice): Best in slot, Best owned (from the wiki's list) or Owned alternatives. Clicking one sets it.
	 */
	private void modeChips(Graphics2D g, BossGear set, Rectangle area, List<Hit> newHits) {
		String mode = manager.getMode();
		BossGear.SetSummary inUse = inUse(set);
		boolean custom = inUse != null && inUse.isCustom();
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		text(g, truncate(custom ? "Gear mode (wiki presets only)" : "Gear mode", fm, area.width), area.x, area.y + 11, custom ? GREY : BEIGE);
		int gap = 3;
		int cw = (area.width - 2 * gap) / 3;
		// Full names when they fit, else short ones.
		boolean full = true;
		for (String m : BossGear.MODES) {
			full &= fm.stringWidth(BossGear.modeLabel(m)) + 8 <= cw;
		}
		int cy = area.y + area.height - CHIP_HEIGHT;
		for (int i = 0; i < BossGear.MODES.length; i++) {
			String m = BossGear.MODES[i];
			boolean on = m.equals(mode);
			Rectangle chip = new Rectangle(area.x + i * (cw + gap), cy, cw, CHIP_HEIGHT);
			box(g, chip, on ? TAB_ON : SLOT, PANEL_EDGE, on ? BUTTON_INNER : SLOT_INNER);
			Color tone = on ? (BossGear.MODE_ALTERNATIVES.equals(m) ? ALT : ORANGE) : GREY;
			centred(g, truncate(full ? BossGear.modeLabel(m) : BossGear.modeShortLabel(m), fm, cw - 4), chip.x + chip.width / 2, chip.y + 13, tone);
			String tip = BossGear.modeLabel(m) + (on ? " (in use)" : "") + ": " + BossGear.modeDescription(m)
				+ (custom ? " Custom builds are unchanged." : "") + " Synced with the website's Boss Gear page.";
			newHits.add(new Hit(chip, () -> manager.setMode(m), tip));
		}
	}

	/** One line of the switcher: a heading, a build, a boss (unfolds) or one of its setups. */
	private static final class Row {
		final String text;
		final Color color;
		final int indent;
		final Runnable action;
		final boolean keepOpen;
		final String note;
		final Color noteColor;

		Row(String text, Color color, int indent, Runnable action, boolean keepOpen, String note, Color noteColor) {
			this.text = text;
			this.color = color;
			this.indent = indent;
			this.action = action;
			this.keepOpen = keepOpen;
			this.note = note;
			this.noteColor = noteColor;
		}
	}

	private static final int TAB_BAR = 25;
	private static final int SWITCHER_WIDTH = 300;
	private static final String CUSTOM_FOOTER = "Custom builds are edited on the website (Tools > Boss Gear > My sets). Press Refresh to load changes.";
	private static final String CUSTOM_EMPTY = "On the website, open Tools > Boss Gear and pick a boss. Under Wiki sets, choose a setup and press "
		+ "Copy to my sets. Edit your copy there, then press Refresh here to load it.";

	/** A build's row: "In use" when it is the loaded one (Inactive: clicking sets it active), else clicking loads it (and makes it Active). */
	private Row buildRow(String text, int indent, Color color, boolean loaded, Runnable load) {
		if (loaded && manager.isSetActive()) {
			return new Row(text, ORANGE, indent, null, false, "In use", GREEN);
		}
		if (loaded) {
			return new Row(text, ORANGE, indent, () -> manager.setSetActive(true), false, "Inactive", ORANGE);
		}
		return new Row(text, color, indent, () -> {
			manager.setSetActive(true);
			load.run();
		}, false, null, null);
	}

	/** Recently used: the last builds you loaded (wiki presets and custom builds), newest first. */
	private List<Row> recentRows() {
		List<Row> rows = new ArrayList<>();
		BossGear set = manager.getSet();
		for (BossGear.SetSummary s : manager.getSets()) {
			if (rows.size() >= RECENT_MAX) {
				break;
			}
			Row row = buildRow(s.getName(), 8, Color.WHITE, set != null && set.getId() == s.getId(), () -> manager.activate(s));
			// Says which kind it is, unless the row already says In use / Inactive.
			rows.add(row.note != null ? row
				: new Row(row.text, row.color, row.indent, row.action, row.keepOpen, s.isCustom() ? "Custom" : "Wiki", s.isCustom() ? YELLOW : GREY));
		}
		return rows;
	}

	/** Wiki presets: every boss (click one to unfold its setups). */
	private List<Row> presetRows() {
		List<Row> rows = new ArrayList<>();
		BossGear set = manager.getSet();
		List<BossGear.CatalogBoss> catalog = manager.getCatalog();
		if (!catalog.isEmpty()) {
			BossGear.SetSummary inUse = inUse(set);
			boolean presetInUse = set != null && (inUse == null || !inUse.isCustom());
			for (BossGear.CatalogBoss b : catalog) {
				boolean open = b.getKey().equals(expandedBoss);
				rows.add(new Row((open ? "- " : "+ ") + b.getName(), Color.WHITE, 8, () -> expandedBoss = open ? null : b.getKey(), true,
					b.getSetups().size() + (b.getSetups().size() == 1 ? " setup" : " setups"), GREY));
				if (open) {
					for (int i = 0; i < b.getSetups().size(); i++) {
						final int setup = i;
						String style = b.getSetups().get(i);
						boolean loaded = presetInUse && b.getKey().equals(set.getBoss()) && style.equals(set.getStyle());
						rows.add(buildRow(style, 22, BEIGE, loaded, () -> {
							expandedBoss = null;
							manager.activatePreset(b, setup);
						}));
					}
				}
			}
		}
		return rows;
	}

	/** Your own builds (made and edited on the website). */
	private List<Row> customRows() {
		List<Row> rows = new ArrayList<>();
		BossGear set = manager.getSet();
		for (BossGear.SetSummary s : manager.getSets()) {
			if (s.isCustom()) {
				rows.add(buildRow(s.getName(), 8, Color.WHITE, set != null && set.getId() == s.getId(), () -> manager.activate(s)));
			}
		}
		return rows;
	}

	private void renderSwitcher(Graphics2D g, Rectangle anchor, Rectangle win, List<Hit> newHits) {
		int shownTab = tab;
		boolean custom = shownTab == TAB_CUSTOM;
		List<Row> rows = custom ? customRows() : shownTab == TAB_RECENT ? recentRows() : presetRows();
		int customCount = 0;
		for (BossGear.SetSummary s : manager.getSets()) {
			customCount += s.isCustom() ? 1 : 0;
		}
		int rowH = 18;
		int x = Math.min(anchor.x, win.x + win.width - 10 - SWITCHER_WIDTH);
		int top = anchor.y + anchor.height + 2;
		g.setFont(FontManager.getRunescapeSmallFont());
		List<String> footer = custom ? wrap(rows.isEmpty() ? CUSTOM_EMPTY : CUSTOM_FOOTER, g.getFontMetrics(), rows.isEmpty() ? 270 : 288)
			: Collections.emptyList();
		int footerH = rows.isEmpty() ? 0 : footer.isEmpty() ? 0 : footer.size() * 13 + 8;
		int maxRows = Math.max(3, (win.y + win.height - 12 - top - 6 - TAB_BAR - footerH) / rowH);
		int shown = Math.min(rows.size(), maxRows);
		int maxScroll = Math.max(0, rows.size() - shown);
		int scroll = Math.max(0, Math.min(switcherScroll, maxScroll));
		switcherScroll = scroll;
		int bodyH = rows.isEmpty() ? Math.max(90, 34 + footer.size() * 13) : shown * rowH;
		Rectangle list = new Rectangle(x, top, SWITCHER_WIDTH, TAB_BAR + bodyH + footerH + 6);
		switcherArea = list;
		box(g, list, BG, FRAME_DARK, BUTTON_INNER);
		List<Hit> optionHits = new ArrayList<>();

		// The tabs: recently used | wiki presets | your custom builds.
		Point m = mouse;
		String[] tabs = {"Recently used", "Wiki presets", "Custom builds (" + customCount + ")"};
		for (int t = 0; t < tabs.length; t++) {
			boolean on = t == shownTab;
			Rectangle tabArea = new Rectangle(list.x + 3 + t * 98, list.y + 3, 98, 22);
			g.setColor(on ? TAB_ON : PANEL);
			g.fillRect(tabArea.x, tabArea.y, tabArea.width, tabArea.height);
			g.setFont(FontManager.getRunescapeSmallFont());
			centred(g, tabs[t], tabArea.x + tabArea.width / 2, tabArea.y + 15, on ? ORANGE : GREY);
			final int to = t;
			optionHits.add(new Hit(tabArea, () -> {
				tab = to;
				switcherScroll = 0;
			}, null, true));
		}
		g.setColor(PANEL_EDGE);
		g.drawLine(list.x + 3, list.y + TAB_BAR, list.x + list.width - 4, list.y + TAB_BAR);

		int rowY = list.y + TAB_BAR + 3;
		if (rows.isEmpty()) {
			if (custom) {
				g.setFont(FontManager.getRunescapeBoldFont());
				centred(g, "No custom builds yet", list.x + list.width / 2, rowY + 17, Color.WHITE);
				g.setFont(FontManager.getRunescapeSmallFont());
				int ly = rowY + 34;
				for (String line : footer) {
					centred(g, line, list.x + list.width / 2, ly, BEIGE);
					ly += 13;
				}
			} else {
				g.setFont(FontManager.getRunescapeFont());
				String empty = manager.isLoading() ? "Loading..." : shownTab == TAB_RECENT ? "No builds used yet: pick one under Wiki presets"
					: "No bosses loaded: press Refresh";
				centred(g, empty, list.x + list.width / 2, rowY + 40, BEIGE);
			}
		}
		for (int i = scroll; i < scroll + shown; i++) {
			Row r = rows.get(i);
			Rectangle row = new Rectangle(list.x + 3, rowY, list.width - 6 - (maxScroll > 0 ? 6 : 0), rowH);
			if (r.action != null && m != null && row.contains(m)) {
				g.setColor(TAB_ON);
				g.fillRect(row.x, row.y, row.width, row.height);
			}
			g.setFont(r.action == null && r.indent == 0 ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont());
			text(g, truncate(r.text, g.getFontMetrics(), row.width - r.indent - 70), row.x + 6 + r.indent, row.y + 13, r.color);
			if (r.note != null) {
				g.setFont(FontManager.getRunescapeSmallFont());
				text(g, r.note, row.x + row.width - 6 - g.getFontMetrics().stringWidth(r.note), row.y + 13, r.noteColor);
			}
			if (r.action != null) {
				optionHits.add(new Hit(row, r.action, null, r.keepOpen));
			}
			rowY += rowH;
		}
		if (maxScroll > 0) {
			// A thin scroll bar: the mouse wheel moves the list.
			int barH = Math.max(12, bodyH * shown / rows.size());
			int barY = list.y + TAB_BAR + 3 + (bodyH - barH) * scroll / maxScroll;
			g.setColor(PANEL_EDGE);
			g.fillRect(list.x + list.width - 6, barY, 3, barH);
		}
		if (!rows.isEmpty() && !footer.isEmpty()) {
			int fy = list.y + TAB_BAR + 3 + bodyH + 4;
			g.setColor(PANEL_EDGE);
			g.drawLine(list.x + 3, fy, list.x + list.width - 4, fy);
			g.setFont(FontManager.getRunescapeSmallFont());
			fy += 14;
			for (String line : footer) {
				text(g, line, list.x + 8, fy, GREY);
				fy += 13;
			}
		}
		g.setFont(FontManager.getRunescapeFont());
		optionHits.add(new Hit(list, () -> { }, null, true));
		newHits.addAll(0, optionHits);
	}

	private void message(Graphics2D g, Rectangle win) {
		String message = manager.isLoading() || !manager.isLoaded() && manager.getError() == null ? "Loading your boss gear..."
			: manager.getError() != null ? manager.getError()
			: "No build loaded yet. Press Pick a build to load a wiki preset, or make a custom build on the website (Tools > Boss Gear > My sets).";
		g.setFont(FontManager.getRunescapeFont());
		int lineY = win.y + win.height / 2 - 10;
		for (String line : wrap(message, g.getFontMetrics(), win.width - 80)) {
			centred(g, line, win.x + win.width / 2, lineY, Color.WHITE);
			lineY += 16;
		}
	}

	/**
	 * One slot: the item (with its stack size) and a border saying whether you carry it (green), have it in
	 * your bank or storage at the last sync (orange, "B"), or miss it (red). {@code need}: how many the
	 * whole set needs of it (0: one).
	 */
	private void drawSlot(Graphics2D g, Rectangle r, BossGear.Item it, int need, boolean synced, List<Hit> newHits) {
		box(g, r, SLOT, SLOT_EDGE, SLOT_INNER);
		if (it == null) {
			return;
		}
		BufferedImage icon = icon(it.getItem(), it.getQty(), it.getQty() > 1);
		if (icon != null) {
			int iw = Math.min(icon.getWidth(), r.width - 2);
			int ih = Math.min(icon.getHeight(), r.height - 2);
			g.drawImage(icon, r.x + (r.width - iw) / 2, r.y + (r.height - ih) / 2, iw, ih, null);
		}
		int carried = manager.carried(it);
		int want = Math.max(1, need);
		Color edge;
		String badge = null;
		if (carried >= want) {
			edge = GREEN;
		} else if (it.isOwned()) {
			edge = STORED;
			badge = "B";
		} else {
			edge = synced ? RED : BEIGE;
		}
		g.setColor(edge);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		g.setFont(FontManager.getRunescapeSmallFont());
		if (badge != null) {
			text(g, badge, r.x + r.width - 8, r.y + r.height - 3, STORED);
		}
		if (it.isNoted()) {
			text(g, "N", r.x + 2, r.y + r.height - 3, YELLOW);
		}
		if (it.isAlternative()) {
			text(g, "A", r.x + 2, r.y + 10, ALT);
		}
		newHits.add(new Hit(r, () -> { }, manager.slotTooltip(it, need, synced)));
	}

	BufferedImage icon(int itemId, int quantity, boolean stackable) {
		return itemManager.getImage(itemId, quantity, stackable);
	}

	// ------------------------------------------------------------------ input

	@Override
	boolean isShown() {
		return manager.isOpen();
	}

	@Override
	void closeWindow() {
		manager.close();
	}

	@Override
	void scrolled(Point p, int rotation) {
		Rectangle list = switcherArea;
		if (switcherOpen && list != null && list.contains(p)) {
			switcherScroll = Math.max(0, switcherScroll + rotation * 3);
		}
	}
}

package com.osrscompanion;

import net.runelite.api.GameState;
import net.runelite.api.gameval.InventoryID;

/**
 * When the inventory and worn gear (bank-memory sources {@code inventory} and {@code worn}, always read
 * and sent together) and the bank may be read for
 * an upload. The website replaces a whole source per upload, so a read taken while the client is not
 * really in game (logging in, hopping, loading, a dead client thread) would wipe what the player owns.
 *
 * <ul>
 *   <li>Nothing is read unless the game state is {@link GameState#LOGGED_IN} and the local player is
 *       loaded (has a name).</li>
 *   <li>The carried items need both containers present (a null INV or WORN is "not known", never
 *       "empty"), and both must have arrived ({@code ItemContainerChanged}) since the last login or
 *       world hop. So the first inventory upload of a session never goes up before the game sent
 *       both containers. One exception: with nothing equipped the game never sends WORN, so once INV
 *       arrived and {@link #NO_WORN_TICKS} game ticks passed without a WORN container, the worn gear
 *       reads as empty (else such a player's inventory never syncs, and an item taken out of the bank
 *       is gone).</li>
 *   <li>The bank needs its container present (it is only filled once the bank was opened).</li>
 *   <li>The GIM group storage needs its container present and its interface open.</li>
 * </ul>
 *
 * Starts "arrived": a plugin started while logged in finds both containers already there. Pure, for
 * unit tests; client thread only.
 */
final class CarriedReadGate {
	/** Game ticks after the inventory arrived without a WORN container before nothing equipped is assumed. */
	static final int NO_WORN_TICKS = 5;
	/** No tick known (the 4-argument checks): a missing WORN container stays "not known". */
	static final int NO_TICK = Integer.MIN_VALUE;

	private boolean invArrived = true;
	private boolean wornArrived = true;
	/** The tick the inventory arrived at; NO_TICK when it was already there (the plugin started while logged in). */
	private int invArrivedTick = NO_TICK;

	/** A login, a world hop or the login screen: the containers have to arrive again. */
	void onGameState(GameState state) {
		if (state == GameState.LOGIN_SCREEN || state == GameState.LOGIN_SCREEN_AUTHENTICATOR
			|| state == GameState.LOGGING_IN || state == GameState.HOPPING) {
			invArrived = false;
			wornArrived = false;
			invArrivedTick = NO_TICK;
		}
	}

	/** An {@code ItemContainerChanged}; {@code present} is whether the client returns that container now. */
	void onContainerChanged(int containerId, boolean present) {
		onContainerChanged(containerId, present, NO_TICK);
	}

	/** As {@link #onContainerChanged(int, boolean)}, at game tick {@code tick}. */
	void onContainerChanged(int containerId, boolean present, int tick) {
		if (!present) {
			return;
		}
		if (containerId == InventoryID.INV) {
			if (!invArrived) {
				invArrivedTick = tick;
			}
			invArrived = true;
		} else if (containerId == InventoryID.WORN) {
			wornArrived = true;
		}
	}

	/**
	 * Whether nothing is equipped: no WORN container, while the inventory arrived at least
	 * {@link #NO_WORN_TICKS} ticks ago (or was already there when the plugin started). The worn gear then
	 * reads as empty. Never at {@link #NO_TICK}.
	 */
	boolean nothingWorn(boolean wornPresent, int tick) {
		if (wornPresent || !invArrived || tick == NO_TICK) {
			return false;
		}
		return invArrivedTick == NO_TICK || tick - invArrivedTick >= NO_WORN_TICKS;
	}

	/** In game with the player loaded: the only time anything is read. */
	static boolean inGame(GameState state, boolean playerLoaded) {
		return state == GameState.LOGGED_IN && playerLoaded;
	}

	/** Whether the inventory and worn gear can be read as the complete {@code inventory} and {@code worn} sources (both or neither). */
	boolean canReadCarried(GameState state, boolean playerLoaded, boolean invPresent, boolean wornPresent) {
		return canReadCarried(state, playerLoaded, invPresent, wornPresent, NO_TICK);
	}

	/** As above at game tick {@code tick}: a missing WORN container also passes when {@link #nothingWorn} (read as empty). */
	boolean canReadCarried(GameState state, boolean playerLoaded, boolean invPresent, boolean wornPresent, int tick) {
		if (!inGame(state, playerLoaded) || !invPresent || !invArrived) {
			return false;
		}
		return wornPresent ? wornArrived : nothingWorn(false, tick);
	}

	/** Whether the bank container can be read as the {@code bank} source. */
	boolean canReadBank(GameState state, boolean playerLoaded, boolean bankPresent) {
		return inGame(state, playerLoaded) && bankPresent;
	}

	/**
	 * Whether the GIM group storage container ({@code INV_GROUP_TEMP}) can be read as the {@code group_storage}
	 * source: in game, the container present and the group storage interface open (outside it the container is
	 * stale or gone, and an empty read would wipe the stored copy).
	 */
	boolean canReadGroupStorage(GameState state, boolean playerLoaded, boolean containerPresent, boolean interfaceOpen) {
		return inGame(state, playerLoaded) && containerPresent && interfaceOpen;
	}

}

package com.osrscompanion;

/**
 * One feature's circuit breaker (see {@link Guard}): {@link #limit} failures within {@link #windowMs}
 * open it, and an open breaker stays open for the rest of the session. A fatal error or a freeze
 * opens it at once ({@link #trip()}). Thread-safe; {@link #isOpen()} is a plain volatile read, so it
 * is cheap enough to check on every frame.
 *
 * An exempt breaker ({@link Guard#NEVER_DISABLED}) counts failures but never opens.
 */
final class CircuitBreaker {
	private final int limit;
	private final long windowMs;
	/** The last {@link #limit} failure times, a ring: {@code next} is where the next one goes (and the oldest). */
	private final long[] times;
	private final boolean exempt;
	private int next;
	private int count;
	private int total;
	private volatile boolean open;

	CircuitBreaker(int limit, long windowMs) {
		this(limit, windowMs, false);
	}

	/** @param exempt never opens: failures are counted, {@link #trip()} does nothing */
	CircuitBreaker(int limit, long windowMs, boolean exempt) {
		this.limit = Math.max(1, limit);
		this.windowMs = windowMs;
		this.times = new long[this.limit];
		this.exempt = exempt;
	}

	boolean isExempt() {
		return exempt;
	}

	boolean isOpen() {
		return open;
	}

	/**
	 * Counts one failure at {@code nowMs}.
	 *
	 * @return true when this failure opened the breaker (only ever once)
	 */
	synchronized boolean recordFailure(long nowMs) {
		total++;
		if (open || exempt) {
			return false;
		}
		times[next] = nowMs;
		next = (next + 1) % limit;
		if (count < limit) {
			count++;
		}
		// Full ring: the oldest of the last `limit` failures is the one `next` points at now.
		if (count == limit && nowMs - times[next] <= windowMs) {
			open = true;
			return true;
		}
		return false;
	}

	/** Opens the breaker now (a fatal error or a freeze); true when it was still closed. Never for an exempt one. */
	synchronized boolean trip() {
		if (open || exempt) {
			return false;
		}
		open = true;
		return true;
	}

	/** Every failure counted, before and after the breaker opened. */
	synchronized int totalFailures() {
		return total;
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.CollectionLogSyncPayload;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's Collection Log and syncs obtained items to the OSRS Companion API.
 *
 * <p>Since the 2023 collection log rework, obtained items are only materialised
 * when the collection log interface is drawn — there is no clean login-time read.
 * So the first time the player opens their collection log each session we replicate
 * WikiSync's technique: trigger the in-log "search" ({@link #SEARCH_SCRIPT}), which
 * forces the draw script ({@link #DRAW_SCRIPT}) to fire for every obtained item.
 * Each fire carries the item id and its obtained quantity on the argument stack
 * (args[1] and args[2]), so we collect both and push them. After that,
 * {@link #DRAW_SCRIPT} keeps firing for new-item unlocks, so incremental obtains
 * flow in real time. A final deduped sync runs on logout. No manual button, no
 * per-page clicking.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Slf4j
@Singleton
public class CollectionLogMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "collection-log-sync";

	// Fired once the collection log interface has been built/opened.
	private static final int SETUP_SCRIPT = 7797;
	// Fired once per obtained item as the collection log draws its list.
	private static final int DRAW_SCRIPT = 4100;
	// The in-log "search all" script; forces a full draw of every obtained item.
	private static final int SEARCH_SCRIPT = 2240;
	// Submit two ticks after the last draw script fires (lets the burst settle).
	private static final int SYNC_DELAY_TICKS = 2;

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final Gson gson;

	// Obtained item id -> its in-game obtained quantity, captured from the draw
	// script (args[1] = item id, args[2] = quantity).
	private final Map<Integer, Integer> obtainedQuantityByItemId = new HashMap<>();
	private GameState previousGameState = GameState.UNKNOWN;
	private boolean captureActive;
	private boolean fullReadTriggeredThisSession;
	private int tickScriptFired = -1;
	private String lastSyncJson;

	public void stop() {
		resetSessionState();
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	/**
	 * Re-pushes the currently captured collection log on the client thread. Used
	 * by the roadmap panel's "Sync &amp; refresh". A no-op until the log has been
	 * opened at least once this session (nothing is captured before then).
	 */
	public void forceSync() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			lastSyncJson = null;
			syncCollectionLog();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState state = event.getGameState();
			switch (state) {
				case LOGGED_IN:
					if (previousGameState != GameState.LOGGED_IN) {
						// Fresh login: capture from now so real-time unlocks are caught
						// even before the player opens their log.
						resetSessionState();
						captureActive = true;
					}
					break;
				case HOPPING:
				case LOGGING_IN:
				case CONNECTION_LOST:
					// Clear per-account state; the next login re-enumerates on log open.
					resetSessionState();
					break;
				default:
					if (previousGameState == GameState.LOGGED_IN) {
						// Logging out: flush whatever we captured, then reset.
						syncCollectionLog();
						resetSessionState();
					}
					break;
			}
			previousGameState = state;
		});
	}

	/**
	 * The collection log interface just finished setup. The first time this happens
	 * in a session, force a full read of every obtained item.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getScriptId() != SETUP_SCRIPT) {
				return;
			}
			if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config)) {
				return;
			}
			if (fullReadTriggeredThisSession) {
				return;
			}
			fullReadTriggeredThisSession = true;
			captureActive = true;
			Guard.invokeLater(clientThread, GUARD_FEATURE, this::triggerFullRead);
		});
	}

	/**
	 * Each obtained item the collection log draws fires this script with the item id
	 * (args[1]) and its obtained quantity (args[2]) on the argument stack. Captures
	 * both the full-read burst and single-item real-time unlocks.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getScriptId() != DRAW_SCRIPT || !captureActive) {
				return;
			}
			Object[] args = event.getScriptEvent().getArguments();
			if (args == null || args.length < 2 || !(args[1] instanceof Integer)) {
				return;
			}
			int itemId = (Integer) args[1];
			int quantity = args.length > 2 && args[2] instanceof Integer ? (Integer) args[2] : 0;
			obtainedQuantityByItemId.put(itemId, quantity);
			tickScriptFired = client.getTickCount();
		});
	}

	/**
	 * Submit shortly after the last draw-script fire so the whole burst is captured
	 * in one payload (mirrors WikiSync's two-tick settle).
	 */
	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (tickScriptFired == -1 || tickScriptFired + SYNC_DELAY_TICKS > client.getTickCount()) {
				return;
			}
			tickScriptFired = -1;
			syncCollectionLog();
		});
	}

	/** Opens the in-log search and runs it, forcing a draw of every obtained item. */
	private void triggerFullRead() {
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(SEARCH_SCRIPT);
	}

	private void syncCollectionLog() {
		if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null || obtainedQuantityByItemId.isEmpty()) {
			return;
		}

		List<Integer> sortedIds = new ArrayList<>(obtainedQuantityByItemId.keySet());
		Collections.sort(sortedIds);
		// TreeMap gives a stable JSON key order so the dedup check is reliable.
		Map<Integer, Integer> quantities = new TreeMap<>(obtainedQuantityByItemId);
		CollectionLogSyncPayload payload =
				// After the full read (the log was opened this session) the list is the whole log.
				new CollectionLogSyncPayload(playerUsername, sortedIds, quantities, fullReadTriggeredThisSession);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			return;
		}
		lastSyncJson = json;
		apiClient.sendCollectionLogSync(payload);
	}

	private void resetSessionState() {
		obtainedQuantityByItemId.clear();
		captureActive = false;
		fullReadTriggeredThisSession = false;
		tickScriptFired = -1;
	}
}

package com.osrscompanion;

/**
 * Pure decision logic for <em>when</em> {@link VarPump} may read the game values.
 *
 * <p>The client's varplayer array is not reset atomically on login / world-hop /
 * account-switch: the server replays the varp block over several ticks after
 * {@code GameState.LOGGED_IN}. Reading during that window can mirror a prior session's
 * fully-complete diary bits onto the current player, which the append-only backend records
 * permanently. This state machine ensures:
 *
 * <ul>
 *   <li>the first read of a session (the <em>baseline</em>) only happens after a short
 *       settle period, by which time the server's varp block has landed;</li>
 *   <li>the varbit-driven near-real-time resync never fires <em>before</em> that baseline
 *       (the varp replay is itself a flood of {@code VarbitChanged}, which previously
 *       pre-empted the login delay and triggered a read mid-replay);</li>
 *   <li>state resets on leaving {@code LOGGED_IN}, so a prior session's values can never be
 *       adopted as the next account's baseline.</li>
 * </ul>
 *
 * <p>It holds no RuneLite references, so it is unit-testable without a live {@code Client}.
 */
final class DiarySyncTrigger {
	/**
	 * Ticks to wait after login before the first (baseline) read, so the server's varp
	 * replay has landed. ~5 ticks is roughly 3 seconds, matching the previous login delay
	 * while now being enforced against every read path rather than a single scheduled task.
	 */
	static final int LOGIN_SETTLE_TICKS = 5;
	/** Minimum ticks between varbit-driven resyncs once the baseline has been established. */
	static final int RESYNC_THROTTLE_TICKS = 3;

	enum Decision {
		NONE,
		SYNC
	}

	private boolean loggedIn;
	private boolean baselineSynced;
	private int loginTick = -1;
	private boolean resyncPending;
	private int lastReadTick = -1;

	/** A varbit changed; request a resync. Acted on only once the baseline has run. */
	void varbitChanged() {
		resyncPending = true;
	}

	/**
	 * Drive from every {@code GameTick}. Returns {@link Decision#SYNC} when the monitor
	 * should read and sync now, {@link Decision#NONE} otherwise.
	 *
	 * @param currentTick the client tick count
	 * @param loggedInNow whether the client is currently in the LOGGED_IN state
	 */
	Decision tick(int currentTick, boolean loggedInNow) {
		if (!loggedInNow) {
			reset();
			return Decision.NONE;
		}
		if (!loggedIn) {
			// Entered logged-in (also covers a missed GameStateChanged, e.g. the plugin
			// being enabled mid-session): start the settle clock, do not read yet.
			enterSession(currentTick);
			return Decision.NONE;
		}
		if (!baselineSynced) {
			if (currentTick - loginTick >= LOGIN_SETTLE_TICKS) {
				baselineSynced = true;
				resyncPending = false;
				lastReadTick = currentTick;
				return Decision.SYNC;
			}
			return Decision.NONE;
		}
		if (resyncPending && currentTick - lastReadTick >= RESYNC_THROTTLE_TICKS) {
			resyncPending = false;
			lastReadTick = currentTick;
			return Decision.SYNC;
		}
		return Decision.NONE;
	}

	/**
	 * Call on a {@code LOGGED_IN -> not-logged-in} transition. Returns whether to flush the
	 * final state (only when a trustworthy baseline was established this session, so a
	 * logout during the settle window never sends transitional data), then resets.
	 */
	boolean leaveAndShouldFlush() {
		// baselineSynced is only ever set while logged in, so it already implies loggedIn.
		boolean flush = baselineSynced;
		reset();
		return flush;
	}

	/** True once this session's settle period has elapsed and the baseline read has run. */
	boolean isBaselineSynced() {
		return baselineSynced;
	}

	/** Clears all session state; the next logged-in tick starts a fresh settle window. */
	void reset() {
		loggedIn = false;
		baselineSynced = false;
		loginTick = -1;
		resyncPending = false;
		lastReadTick = -1;
	}

	private void enterSession(int currentTick) {
		reset();
		loggedIn = true;
		loginTick = currentTick;
	}
}

