	private volatile FarmRouteReady lastRun;
	private volatile boolean loadLastRun;
	/** The route got ready while logged out: the in-game popup waits for the next login. */
	private volatile String readyPopupPending;

	// ---- Loading -----------------------------------------------------------------

	/** A load without an answer after this long is tried again (opening the window, Refresh). */
	private static final long STUCK_LOAD_MS = 20_000;

	public void refreshIfStale() {
		if (!loading && System.currentTimeMillis() - fetchedAtMs > REFRESH_INTERVAL_MS) {
			refresh();
		}
	}

	public void refresh() {
		String player = roadmapManager.getPlayerUsername();
		if (player == null) {
			error = "Log in to the game to load your farm route.";
			return;
		}
		if (!roadmapManager.hasAppKey()) {
			error = "Add your App Key in the OSRS Companion settings first.";
			return;
		}
		loading = true;
		fetchedAtMs = System.currentTimeMillis();
		apiClient.getFarmRoute(player, callback(null));
	}

	/** Switches the active route (on the website too) and loads it. A running guide stops. */
	public void activate(FarmRoute.RouteSummary summary) {
		String player = roadmapManager.getPlayerUsername();
		if (summary == null || player == null || (route != null && route.getId() == summary.getId())) {
			return;
		}
		stop();
		loading = true;
		apiClient.activateFarmRoute(summary.getId(), player, callback(summary.getName()));
	}

	private OSRSCompanionApiClient.RoadmapCallback<FarmRoute.Response> callback(String switchedTo) {
		return new OSRSCompanionApiClient.RoadmapCallback<FarmRoute.Response>() {
			@Override
			public void onSuccess(FarmRoute.Response result) {
				FarmRoute old = route;
				route = result.getRoute();
				routes = result.getRoutes();
				error = null;
				loaded = true;
				loading = false;
				// A different route restarts the progress; a run going on the old route ends here (stopped part way).
				if (old == null || route == null || old.getId() != route.getId()) {
					if (running && old != null) {
						running = false;
						send("stop", old);
					}
					running = false;
					stopIndex = 0;
					state = null;
					seen.clear();
				} else if (stopIndex >= route.getStops().size()) {
					stopIndex = Math.max(0, route.getStops().size() - 1);
				}
				syncPending = true;
			}

			@Override
			public void onError(String message) {
				error = (switchedTo == null ? "Could not load your farm route" : "Could not switch to " + switchedTo) + " (" + message + ").";
				loading = false;
			}
		};
	}

	// ---- The website ------------------------------------------------------------------

	/** Asks the website to do this to the run (with what Time Tracking stored now). Client thread. */
	private void send(String action, FarmRoute r) {
		send(action, r, null);
	}

	private void send(String action, FarmRoute r, Map<String, Object> extra) {
		String player = runPlayer != null ? runPlayer : roadmapManager.getPlayerUsername();
		if (r == null || player == null) {
			return;
		}
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player_username", player);
		body.put("route_id", r.getId());
		body.put("action", action);
		synchronized (seen) {
			body.put("done", new ArrayList<>(seen));
		}
		body.put("profile", TimerMonitor.timeTracking(configManager));
		if (extra != null) {
			body.putAll(extra);
		}
		synchronized (queue) {
			queue.add(body);
		}
		pump();
	}

	private void pump() {
		Map<String, Object> next;
		synchronized (queue) {
			if (inFlight || queue.isEmpty()) {
				return;
			}
			inFlight = true;
			next = queue.poll();
		}
		apiClient.postFarmRun(gson.toJson(next), State.class, new OSRSCompanionApiClient.RoadmapCallback<State>() {
			@Override
			public void onSuccess(State answer) {
				apply(answer);
				done();
			}

			@Override
			public void onError(String message) {
				done();
			}
		});
	}

	private void done() {
		synchronized (queue) {
			inFlight = false;
		}
		pump();
	}

	/** The website's answer (OkHttp thread): the newest one for the current route wins. */
	private void apply(State answer) {
		FarmRoute r = route;
		boolean newest;
		synchronized (queue) {
			newest = queue.isEmpty();
		}
		if (r == null || answer.route_id != r.getId() || !newest) {
			return;
		}
		if (answer.patches == null) {
			answer.patches = Collections.emptyMap();
		}
		state = answer;
		if (running && answer.running) {
			stopIndex = answer.stop_index;
		}
		FarmRouteReady last = answer.last_run;
		FarmRouteReady known = lastRun;
		if (last != null && (known == null || known.getReadyAt() != last.getReadyAt() || known.getEndedAt() != last.getEndedAt())) {
			// The website's newest time for the last run; already told stays told for the same run.
			if (known != null && known.isNotified() && known.getEndedAt() == last.getEndedAt()) {
				last.markNotified();
			}
			lastRun = last;
			saveLastRun(last);
		}
	}

	private PatchState stateOf(FarmRoute.Patch p) {
		State s = state;
		PatchState ps = s == null ? null : s.patches.get(p.getKey());
		return ps == null ? new PatchState() : ps;
	}

	// ---- The run -------------------------------------------------------------------

	/** Starts the guide: the website notes every patch's state now and goes to the first stop with work. */
	public void start() {
		FarmRoute r = route;
		if (r == null || r.getStops().isEmpty()) {
			return;
		}
		compostTarget = null;
		awayFrom = -1;
		completedTick = -1;
		startXp = client.getSkillExperience(Skill.FARMING);
		lastXp = startXp;
		runTicks = 0;
		specialMode = GameModeUtil.isSpecialGameMode(client);
		runPlayer = roadmapManager.getPlayerUsername();
		state = null;
		seen.clear();
		running = true;
		// Only one guide is active at a time: a farm run turns the boss setup and the slayer guide off.
		turnOff(BOSS_ACTIVE_KEY);
		turnOff(SLAYER_GUIDE_KEY);
		stopIndex = 0;
		capeRemindedStop = -1;
		recountPending = true;
		send("start", r);
	}

	public void stop() {
		FarmRoute r = route;
		boolean was;
		synchronized (this) {
			was = running;
			running = false;
		}
		if (was) {
			Map<String, Object> extra = new LinkedHashMap<>();
			extra.put("xp_gained", lastXp - startXp);
			extra.put("active_ticks", runTicks);
			// For the website's Run history (when that setting is on).
			extra.put("record", config.syncFarmRuns() && !specialMode && SyncGuard.hasAppKey(config));
			send("stop", r, extra);
		}
		completedTick = -1;
		runPlayer = null;
	}

	public void next() {
		FarmRoute r = route;
		if (r != null && stopIndex < r.getStops().size() - 1) {
			stopIndex++;
			send("next", r);
		}
	}

	public void previous() {
		if (stopIndex > 0) {
			stopIndex--;
			send("previous", route);
		}
	}

	public void goTo(int index) {
		FarmRoute r = route;
		if (r != null && index >= 0 && index < r.getStops().size()) {
			stopIndex = index;
			send("goto", r, Collections.singletonMap("index", index));
		}
	}

	/** Skips the current stop's open patches and moves on. */
	public void skipStop() {
		if (getCurrentStop() != null) {
			send("skip", route);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick) {
		Guard.run(GUARD_FEATURE, () -> {
			if (loadLastRun) {
				loadLastRun = false;
				loadLastRun();
			}
			String popup = readyPopupPending;
			if (popup != null) {
				readyPopupPending = null;
				popups.showMessage(READY_TITLE, "<col=ffffff>" + popup + "</col>");
			}
			if (recountPending) {
				recountPending = false;
				recount();
			}
			if (open || running) {
				leprechaun = ToolLeprechaun.read(client);
				if (syncPending || client.getTickCount() - lastSyncTick >= SYNC_EVERY_TICKS) {
					syncPending = false;
					lastSyncTick = client.getTickCount();
					if (client.getGameState() == GameState.LOGGED_IN) {
						send("sync", route);
					}
				}
			}
			if (!running || route == null) {
				return;
			}
			runTicks++;
			int xp = client.getSkillExperience(Skill.FARMING);
			if (xp >= startXp) {
				lastXp = xp;
			}
			remindCape();
			checkAway();
			updateMinigameCooldown();
			checkPlanted();
			checkFinished();
		});
	}

	/** RuneLite's Time Tracking stored a patch change (you farmed): the website works the run out again. */
	@Subscribe
	public void onConfigChanged(ConfigChanged e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (TimeTrackingConfig.CONFIG_GROUP.equals(e.getGroup())) {
				syncPending = true;
				return;
			}
			if (!OSRSCompanionConfig.CONFIG_GROUP.equals(e.getGroup()) || !"true".equals(e.getNewValue())) {
				return;
			}
			// The farm run, the boss setup and the slayer guide are never active together.
			if (BOSS_ACTIVE_KEY.equals(e.getKey())) {
				turnOff(SLAYER_GUIDE_KEY);
			} else if (SLAYER_GUIDE_KEY.equals(e.getKey())) {
				turnOff(BOSS_ACTIVE_KEY);
			} else {
				return;
			}
			if (running) {
				stop();
			}
		});
	}

	// ---- Finishing -----------------------------------------------------------------------

	/**
	 * Patches planted, read from the game with the values the website sent: the guide moves on at once (as the website
	 * does: past a stop once nothing there needs a visit), with or without the website, and tells it.
	 */
	private void checkPlanted() {
		State s = state;
		FarmRoute r = route;
		int[] regions = client.getMapRegions();
		if (s == null || r == null || regions == null) {
			return;
		}
		boolean changed = false;
		for (FarmRoute.Stop stop : r.getStops()) {
			for (FarmRoute.Patch p : stop.getPatches()) {
				PatchState ps = s.patches.get(p.getKey());
				if (ps == null || ps.planted == null || ps.status != Status.TODO || Arrays.stream(regions).noneMatch(id -> id == ps.region)) {
					continue;
				}
				int v = client.getVarbitValue(p.getVarbit());
				if (Arrays.stream(ps.planted).anyMatch(range -> v >= range[0] && v <= range[1])) {
					ps.status = Status.DONE;
					s.planted++;
					seen.add(p.getKey());
					changed = true;
				}
			}
		}
		if (!changed) {
			return;
		}
		int next = stopIndex;
		while (next < r.getStops().size() && r.getStops().get(next).getPatches().stream().noneMatch(p -> stateOf(p).status == Status.TODO)) {
			next++;
		}
		if (next >= r.getStops().size()) {
			s.complete = true;
		} else if (next != stopIndex) {
			s.previous_stop = stopIndex;
			stopIndex = next;
		}
		send("sync", r);
	}

	/** A finished run: the summary popup straight away, then it stops once you leave the last stop, or after a minute. */
	private void checkFinished() {
		State s = state;
		if (!isComplete()) {
			completedTick = -1;
			return;
		}
		if (completedTick < 0) {
			completedTick = client.getTickCount();
			if (s.planted == 0) {
				// Nothing was planted: every patch is still growing or skipped.
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Farm run: nothing to do yet - every patch is still growing or skipped.", null);
				stop();
				return;
			}
			showFinished(s.planted);
			return;
		}
		WorldPoint at = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getWorldLocation();
		WorldPoint last = getCurrentTarget();
		boolean left = at != null && last != null && (at.getPlane() != last.getPlane() || at.distanceTo2D(last) > CAPE_REMINDER_DISTANCE);
		// The minute's grace waits while a patch here still has no compost (you are still at it).
		boolean timeUp = client.getTickCount() - completedTick >= FINISH_DELAY_TICKS && !hasCompostToDo();
		if (left || timeUp) {
			stop();
		}
	}

	/** The summary popup (when that setting is on) and a notification: patches done and Farming XP gained. */
	private void showFinished(int planted) {
		int xp = Math.max(0, client.getSkillExperience(Skill.FARMING) - startXp);
		if (config.farmRunPopup()) {
			popups.showMessage(FINISHED_TITLE, finishedBody(planted, xp));
		}
		notifier.notify("Farm run complete: " + planted + (planted == 1 ? " patch" : " patches")
			+ (xp > 0 ? ", " + QuantityFormatter.formatNumber(xp) + " Farming XP" : "") + ".");
	}

	/** The popup body: "8 patches, 1,234 Farming XP" (the XP left out when none was gained). */
	static String finishedBody(int patches, int xp) {
		return "<col=ffffff>" + patches + (patches == 1 ? " patch" : " patches")
			+ (xp > 0 ? ", " + QuantityFormatter.formatNumber(xp) + " Farming XP" : "") + "</col>";
	}

	// ---- One guide at a time -------------------------------------------------------------

	/** The boss setup's Active switch and the slayer guide's switch (this plugin's settings). */
	static final String BOSS_ACTIVE_KEY = "bossGearActive";
	static final String SLAYER_GUIDE_KEY = "slayerGuide";

	private void turnOff(String key) {
		if (Boolean.parseBoolean(configManager.getConfiguration(OSRSCompanionConfig.CONFIG_GROUP, key))) {
			configManager.setConfiguration(OSRSCompanionConfig.CONFIG_GROUP, key, false);
		}
	}

	// ---- Route ready again ----------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (e.getGameState() == GameState.LOGGED_IN) {
				loadLastRun = true;
			}
		});
	}

	/** The account's last run, as saved (client thread, logged in). */
	private void loadLastRun() {
		try {
			String json = configManager.getRSProfileConfiguration(OSRSCompanionConfig.CONFIG_GROUP, READY_KEY);
			lastRun = json == null ? null : gson.fromJson(json, FarmRouteReady.class);
		} catch (RuntimeException ex) {
			lastRun = null;
		}
	}

	private void saveLastRun(FarmRouteReady run) {
		try {
			configManager.setRSProfileConfiguration(OSRSCompanionConfig.CONFIG_GROUP, READY_KEY, gson.toJson(run));
		} catch (RuntimeException ex) {
		}
	}

	/**
	 * Every half minute (the plugin's executor), logged in or not: once the last run's patches are grown (as the
	 * website last worked it out), a notification and an in-game popup (at once or at the next login). Once a run.
	 */
	public void checkRouteReady() {
		FarmRouteReady run = lastRun;
		if (run == null || run.isNotified() || running || !config.farmRouteReadyNotify() || !run.isReady(System.currentTimeMillis() / 1000)) {
			return;
		}
		run.markNotified();
		saveLastRun(run);
		String message = FarmRouteReady.message(run.getRoute(), run.getPatches());
		notifier.notify(message);
		if (client.getGameState() == GameState.LOGGED_IN) {
			popups.showMessage(READY_TITLE, "<col=ffffff>" + message + "</col>");
		} else {
			readyPopupPending = message;
		}
	}

	// ---- Compost and the minigame teleport ---------------------------------------------

	/** Walked away from the stop just left: the website stops pointing compost out there. Client thread. */
	private void checkAway() {
		State s = state;
		FarmRoute r = route;
		int prev = s == null ? -1 : s.previous_stop;
		if (r == null || prev < 0 || prev >= r.getStops().size() || prev == awayFrom || client.getLocalPlayer() == null) {
			return;
		}
		FarmRoute.Stop stop = r.getStops().get(prev);
		if (client.getLocalPlayer().getWorldLocation().distanceTo2D(new WorldPoint(stop.getX(), stop.getY(), stop.getPlane())) > CAPE_REMINDER_DISTANCE) {
			awayFrom = prev;
			send("away", r);
		}
	}

	/** The inventory with the compost buckets set to this many (left out at 0). A bottomless bucket stays as it is. */
	static List<FarmRoute.Stack> withCompost(List<FarmRoute.Stack> inventory, int buckets) {
		List<FarmRoute.Stack> out = new ArrayList<>(inventory.size());
		for (FarmRoute.Stack s : inventory) {
			if (!"Compost".equals(s.getWhy()) || !isCompostBucket(s.getItem())) {
				out.add(s);
			} else if (buckets > 0) {
				out.add(s.withQty(buckets));
			}
		}
		return Collections.unmodifiableList(out);
	}

	private static boolean isCompostBucket(int itemId) {
		return itemId == ItemID.BUCKET_ULTRACOMPOST || itemId == ItemID.BUCKET_SUPERCOMPOST || itemId == ItemID.BUCKET_COMPOST;
	}

	/** Minutes left before the next minigame teleport, from the game's last-use time. Client thread. */
	private void updateMinigameCooldown() {
		lastMinigameTeleport = client.getVarpValue(LAST_MINIGAME_TELEPORT_VARP);
		FarmRoute.Stop stop = getCurrentStop();
		minigameCooldown = stop == null || !stop.getTravel().isMinigame() ? 0 : minigameCooldownLeft();
	}

	/** Minutes before any minigame teleport can be used again (0: ready, or never used). */
	private int minigameCooldownLeft() {
		long last = lastMinigameTeleport;
		long now = System.currentTimeMillis() / 60_000L;
		return last <= 0 ? 0 : (int) Math.max(0, last + MINIGAME_COOLDOWN_MINUTES - now);
	}

	/** The way to a stop: during a run, a minigame teleport still on its cooldown gives way to the route's fallback. */
	public FarmRoute.Travel travelOf(FarmRoute.Stop stop) {
		FarmRoute.Travel t = stop.getTravel();
		return running && t.isMinigame() && t.getFallback() != null && minigameCooldownLeft() > 0 ? t.getFallback() : t;
	}

	/** Compost (or Fertile Soil) used on a route patch: remember which, until the game's message says it worked. */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!running || e.getMenuAction() != MenuAction.WIDGET_TARGET_ON_GAME_OBJECT) {
				return;
			}
			Widget selected = client.getSelectedWidget();
			if (selected == null || (selected.getId() != InterfaceID.MagicSpellbook.FERTILE_SOIL && !isCompostItem(selected.getItemId()))) {
				return;
			}
			ObjectComposition def = client.getObjectDefinition(e.getId());
			int varbit = def == null ? -1 : def.getVarbitId();
			compostTarget = null;
			FarmRoute r = route;
			State s = state;
			int prev = s == null ? -1 : s.previous_stop;
			FarmRoute.Stop[] near = {getCurrentStop(), r != null && prev >= 0 && prev < r.getStops().size() ? r.getStops().get(prev) : null};
			for (FarmRoute.Stop stop : near) {
				for (FarmRoute.Patch p : stop == null ? Collections.<FarmRoute.Patch>emptyList() : stop.getPatches()) {
					if (p.getVarbit() == varbit && compostTarget == null) {
						compostTarget = p.getKey();
					}
				}
			}
		});
	}

	@Subscribe
	public void onChatMessage(ChatMessage e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (compostTarget != null && (e.getType() == ChatMessageType.GAMEMESSAGE || e.getType() == ChatMessageType.SPAM)
				&& COMPOST_MESSAGE.matcher(e.getMessage()).find()) {
				send("composted", route, Collections.singletonMap("key", compostTarget));
				compostTarget = null;
			}
		});
	}

	private static boolean isCompostItem(int itemId) {
		for (int id : COMPOST_ITEMS) {
			if (id == itemId) {
				return true;
			}
		}
		return false;
	}

	/** True while this route patch still needs compost (at the current stop, or the one just left while you are there). */
	public boolean needsCompost(FarmRoute.Patch p) {
		return running && stateOf(p).compost;
	}

	/** True while a patch at (or just behind) the current stop still needs compost. */
	public boolean hasCompostToDo() {
		State s = state;
		return running && s != null && s.patches.values().stream().anyMatch(p -> p.compost);
	}

	/** The stop just left while one of its patches (you are still there) has no compost yet, else null. */
	public FarmRoute.Stop compostStopBehind() {
		FarmRoute r = route;
		State s = state;
		int prev = s == null ? -1 : s.previous_stop;
		if (!running || r == null || prev < 0 || prev >= r.getStops().size() || prev == stopIndex) {
			return null;
		}
		FarmRoute.Stop stop = r.getStops().get(prev);
		return stop.getPatches().stream().anyMatch(this::needsCompost) ? stop : null;
	}

	/** Patches of the stop just left (you are still there) that have no compost yet. */
	public int compostBehind() {
		FarmRoute.Stop behind = compostStopBehind();
		return behind == null ? 0 : (int) behind.getPatches().stream().filter(this::needsCompost).count();
	}

	/** Minutes before the minigame teleport to the current stop can be used again (0: ready). */
	public int minigameCooldownMinutes() {
		return running ? minigameCooldown : 0;
	}

	/** The route's compost (bottomless bucket, ultracompost, supercompost), or null when it brings none. */
	public FarmRoute.Stack compostStack() {
		FarmRoute r = route;
		if (r == null) {
			return null;
		}
		for (FarmRoute.Stack s : r.getInventory()) {
			if ("Compost".equals(s.getWhy())) {
				return s;
			}
		}
		return null;
	}

	/** The compost to point at: the route's when carried (not an empty bucket), else the best compost carried, else the route's. */
	int compostItem() {
		FarmRoute.Stack s = compostStack();
		Map<Integer, Integer> have = carried;
		if (s != null && s.getItem() != ItemID.BOTTOMLESS_COMPOST_BUCKET && have.getOrDefault(s.getItem(), 0) > 0) {
			return s.getItem();
		}
		for (int id : COMPOST_ITEMS) {
			if (have.getOrDefault(id, 0) > 0) {
				return id;
			}
		}
		return s == null ? ItemID.BUCKET_ULTRACOMPOST : s.getItem();
	}

	/** True while the current stop still has herbs to pick and the cape is not worn (the setting on, 99 Farming). */
	public boolean needsFarmingCape() {
		if (config.farmingCapeMode() == FarmingCapeMode.OFF || !running || isComplete() || capeWorn || client.getRealSkillLevel(Skill.FARMING) < 99) {
			return false;
		}
		FarmRoute.Stop stop = getCurrentStop();
		return stop != null && stop.getPatches().stream().anyMatch(this::herbToPick);
	}

	/** A herb patch of the run still to pick (grown, not dead or diseased). */
	private boolean herbToPick(FarmRoute.Patch p) {
		PatchState s = stateOf(p);
		return isHerb(p) && s.status == Status.TODO && s.harvestable;
	}

	/** What to do at a patch still to do, as the website works it out (harvest, rake, compost, plant...). */
	public String nextStep(FarmRoute.Patch p) {
		String step = stateOf(p).step;
		return step != null ? step : p.getType() + (p.getCrop() != null ? ": " + p.getCrop() : "");
	}

	/** With "Farming cape for herbs" on Force: a herb patch of the run still to pick while the cape is not worn (99 Farming). */
	public boolean capeBlocks(FarmRoute.Patch p) {
		return config.farmingCapeMode() == FarmingCapeMode.FORCE && running && !capeWorn && herbToPick(p)
			&& client.getRealSkillLevel(Skill.FARMING) >= 99;
	}

	/** With "Farming cape for herbs" on Force: the cape is not worn while herbs of the run are still to pick. */
	public boolean capeMissing() {
		FarmRoute r = route;
		if (config.farmingCapeMode() != FarmingCapeMode.FORCE || !running || capeWorn || r == null || client.getRealSkillLevel(Skill.FARMING) < 99) {
			return false;
		}
		return r.getStops().stream().anyMatch(s -> s.getPatches().stream().anyMatch(this::herbToPick));
	}

	/** "Auto set cape teleport": the teleport to the current stop becomes its item's left click. Runs after every other plugin. */
	@Subscribe(priority = -100)
	public void onPostMenuSort(PostMenuSort e) {
		Guard.run(GUARD_FEATURE, () -> {
			FarmRoute.Stop stop = getCurrentStop();
			if (!config.autoCapeTeleport() || !running || stop == null || client.isMenuOpen()) {
				return;
			}
			teleports.apply(travelOf(stop), "farm step " + (stopIndex + 1));
		});
	}

	/** "Pick" on a herb patch the cape blocks moves below "Walk here", so a left click walks instead. */
	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!running || capeWorn || config.farmingCapeMode() != FarmingCapeMode.FORCE || !"Pick".equals(e.getOption())) {
				return;
			}
			ObjectComposition def = client.getObjectDefinition(e.getIdentifier());
			int varbit = def == null ? -1 : def.getVarbitId();
			FarmRoute r = route;
			if (varbit < 0 || r == null) {
				return;
			}
			for (FarmRoute.Stop s : r.getStops()) {
				for (FarmRoute.Patch p : s.getPatches()) {
					if (p.getVarbit() == varbit && capeBlocks(p)) {
						e.getMenuEntry().setDeprioritized(true);
						return;
					}
				}
			}
		});
	}

	private static boolean isHerb(FarmRoute.Patch p) {
		return p.getType() != null && p.getType().toLowerCase().contains("herb");
	}

	/** Once per stop, near it: a notification to put the Farming cape on before picking the herbs. */
	private void remindCape() {
		if (!needsFarmingCape() || capeRemindedStop == stopIndex || client.getLocalPlayer() == null) {
			return;
		}
		FarmRoute.Stop stop = getCurrentStop();
		WorldPoint at = client.getLocalPlayer().getWorldLocation();
		if (at.distanceTo2D(new WorldPoint(stop.getX(), stop.getY(), stop.getPlane())) <= CAPE_REMINDER_DISTANCE) {
			capeRemindedStop = stopIndex;
			String text = "Farm run: put on your Farming cape before you pick the herbs (5% more herbs).";
			// In the chat too: RuneLite only shows notifications while the game is not focused, by default.
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=ff9040>" + text + "</col>", null);
			notifier.notify(text);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			int id = event.getContainerId();
			if (id == InventoryID.INV || id == InventoryID.WORN) {
				recount();
			}
		});
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (RunePouchMonitor.isPouchVarbit(event.getVarbitId())) {
				recountPending = true;
			}
		});
	}

	/** Counts the inventory and worn items, plus the runes in a carried rune pouch. Client thread. */
	private void recount() {
		Map<Integer, Integer> counts = new HashMap<>();
		Map<Integer, Integer> byBase = new HashMap<>();
		Map<String, Integer> byName = new HashMap<>();
		boolean cape = false;
		boolean pouch = false;
		for (int container : new int[]{InventoryID.INV, InventoryID.WORN}) {
			ItemContainer c = client.getItemContainer(container);
			if (c == null) {
				continue;
			}
			for (Item item : c.getItems()) {
				if (item.getId() > 0) {
					count(counts, byBase, byName, item.getId(), item.getQuantity());
					cape |= container == InventoryID.WORN && (item.getId() == FARMING_CAPE || item.getId() == FARMING_CAPE_T);
					pouch |= container == InventoryID.INV && RUNE_POUCHES.contains(item.getId());
				}
			}
		}
		if (pouch) {
			// The pouch's runes (from its varbits) are carried too, so the window marks them green.
			for (Map.Entry<Integer, Integer> rune : RunePouchMonitor.read(client).entrySet()) {
				count(counts, byBase, byName, rune.getKey(), rune.getValue());
			}
		}
		carried = counts;
		carriedBase = byBase;
		carriedNames = byName;
		capeWorn = cape;
	}

	/** When the route is ready for its next run (epoch seconds): 0 nothing growing, -1 not known (from the website). */
	public long nextRunAt() {
		State s = state;
		return s == null ? -1 : s.next_run_at;
	}

	// ---- The window --------------------------------------------------------------------

	public void toggle() {
		if (open) {
			close();
		} else {
			openWindow();
		}
	}

	public void openWindow() {
		open = true;
		selectedStop = -1;
		recountPending = true;
		// Always fetch on open, so a route just made or edited on the website shows up straight away (the same
		// route keeps its progress; see callback()). A load that never answered doesn't block it.
		if (!loading || System.currentTimeMillis() - fetchedAtMs > STUCK_LOAD_MS) {
			refresh();
		}
	}

	public void close() {
		open = false;
	}

	/** The stop shown in the window's details: the one clicked, else the current one. */
	public int getSelectedStop() {
		FarmRoute r = route;
		int size = r == null ? 0 : r.getStops().size();
		int s = selectedStop >= 0 ? selectedStop : stopIndex;
		return size == 0 ? -1 : Math.min(s, size - 1);
	}

	public void selectStop(int index) {
		selectedStop = index;
	}

	/** How many of an item the tool leprechaun holds (tools: 1 when stored). */
	public int inLeprechaun(int itemId) {
		Integer n = leprechaun.get(itemId);
		return n == null ? 0 : n;
	}

	// ---- Read by the panel and overlays -------------------------------------------

	public FarmRoute.Stop getCurrentStop() {
		FarmRoute r = route;
		if (r == null || r.getStops().isEmpty()) {
			return null;
		}
		return r.getStops().get(Math.min(stopIndex, r.getStops().size() - 1));
	}

	/** The run is finished: every patch from the current stop to the end of the route is handled (the website's answer). */
	public boolean isComplete() {
		State s = state;
		return running && s != null && s.running && s.complete;
	}

	public Status statusOf(FarmRoute.Patch p) {
		return running ? stateOf(p).status : Status.TODO;
	}

	/** How many patches are handled out of all patches. */
	public int[] progress() {
		FarmRoute r = route;
		int done = 0;
		int total = 0;
		if (r != null) {
			for (FarmRoute.Stop s : r.getStops()) {
				for (FarmRoute.Patch p : s.getPatches()) {
					total++;
					if (!statusOf(p).isOpen()) {
						done++;
					}
				}
			}
		}
		return new int[]{done, total};
	}

	/** Item counts in the inventory plus worn equipment; variants count too (worn graceful, charges, trimmed cape). */
	public int carried(int itemId) {
		if (itemId == FARMING_CAPE || itemId == FARMING_CAPE_T) {
			return carried.getOrDefault(FARMING_CAPE, 0) + carried.getOrDefault(FARMING_CAPE_T, 0);
		}
		int[] combos = COMBO_RUNES.get(itemId);
		if (combos != null) {
			// An elemental rune: the combination runes that count as it are carried too (dust: air and earth).
			int n = carried.getOrDefault(itemId, 0);
			for (int combo : combos) {
				n += carried.getOrDefault(combo, 0);
			}
			return n;
		}
		Integer n = carried.get(itemId);
		if (n == null) {
			n = carriedBase.get(ItemVariationMapping.map(itemId));
		}
		if (n == null) {
			String name = nameOf(itemId);
			n = name == null ? null : carriedNames.get(name);
		}
		return n == null ? 0 : n;
	}

	private void count(Map<Integer, Integer> counts, Map<Integer, Integer> byBase, Map<String, Integer> byName, int itemId, int qty) {
		counts.merge(itemId, qty, Integer::sum);
		byBase.merge(ItemVariationMapping.map(itemId), qty, Integer::sum);
		String name = nameOf(itemId);
		if (name != null) {
			byName.merge(name, qty, Integer::sum);
		}
	}

	/** Whether a Farming cape (or the trimmed one) is worn. */
	public boolean isFarmingCapeWorn() {
		return capeWorn;
	}

	/** Item names (lower case) read on the client thread, for the side panel which paints on Swing's thread. */
	private final Map<Integer, String> names = new java.util.concurrent.ConcurrentHashMap<>();

	/** The item's name in lower case; off the client thread only when it was read there before, else null. */
	private String nameOf(int itemId) {
		String cached = names.get(itemId);
		if (cached != null || !client.isClientThread()) {
			return cached;
		}
		ItemComposition comp = client.getItemDefinition(itemId);
		String name = comp == null || comp.getName() == null ? null : comp.getName().toLowerCase();
		if (name != null) {
			names.put(itemId, name);
		}
		return name;
	}

	/** Whether the route (or the Farming cape setting) needs this item; variants count. For the bank filter. */
	public boolean needs(int itemId) {
		return neededStack(itemId) != null;
	}

	/** The loadout entry this item satisfies: the same item, a variant (charges, colours) or one of the same name. */
	public FarmRoute.Stack neededStack(int itemId) {
		return neededStack(itemId, loadout());
	}

	/** {@link #neededStack(int)} against a loadout the caller already has (the item overlay keeps one per frame). */
	FarmRoute.Stack neededStack(int itemId, List<FarmRoute.Stack> loadout) {
		int base = ItemVariationMapping.map(itemId);
		String name = null;
		for (FarmRoute.Stack s : loadout) {
			if (s.getItem() == itemId || ItemVariationMapping.map(s.getItem()) == base) {
				return s;
			}
		}
		for (FarmRoute.Stack s : loadout) {
			if (name == null) {
				name = nameOf(itemId);
				if (name == null) {
					return null;
				}
			}
			if (name.equals(nameOf(s.getItem()))) {
				return s;
			}
		}
		return null;
	}

	/** Where the guide points: the current stop's tile. */
	public WorldPoint getCurrentTarget() {
		FarmRoute.Stop s = getCurrentStop();
		return s == null ? null : new WorldPoint(s.getX(), s.getY(), s.getPlane());
	}

	/** Items worth highlighting right now: the teleport there, seeds/payments for open patches, compost while a patch has none. */
	public Map<Integer, Highlight> currentItems() {
		Map<Integer, Highlight> out = new HashMap<>();
		FarmRoute.Stop s = getCurrentStop();
		if (!running || s == null) {
			return out;
		}
		if (hasCompostToDo()) {
			out.put(compostItem(), Highlight.COMPOST);
		}
		for (Integer id : travelOf(s).getItems()) {
			out.put(id, Highlight.TELEPORT);
		}
		for (FarmRoute.Patch p : s.getPatches()) {
			if (!statusOf(p).isOpen()) {
				continue;
			}
			if (p.getSeed() != null && p.getSeed() > 0) {
				out.putIfAbsent(p.getSeed(), Highlight.SEED);
			}
			for (FarmRoute.Stack pay : p.getProtect()) {
				out.putIfAbsent(pay.getItem(), Highlight.PAYMENT);
			}
		}
		return out;
	}

	/** The whole loadout (inventory and equipment) with how many of each the run needs. */
	public List<FarmRoute.Stack> loadout() {
		FarmRoute r = route;
		if (r == null) {
			return Collections.emptyList();
		}
		List<FarmRoute.Stack> all = new ArrayList<>(r.getEquipment());
		all.addAll(inventory());
		return all;
	}

	/**
	 * The route's inventory (its compost counted by the website from the patches you will actually plant), plus the
	 * Farming cape when that setting is on and the route picks herbs.
	 */
	public List<FarmRoute.Stack> inventory() {
		FarmRoute r = route;
		if (r == null) {
			return Collections.emptyList();
		}
		State s = state;
		List<FarmRoute.Stack> inv = s != null && s.compost_to_bring >= 0 && client.getGameState() == GameState.LOGGED_IN
			? withCompost(r.getInventory(), s.compost_to_bring) : r.getInventory();
		boolean herbs = r.getStops().stream().anyMatch(st -> st.getPatches().stream().anyMatch(FarmRunManager::isHerb));
		boolean listed = inv.stream().anyMatch(st -> st.getItem() == FARMING_CAPE || st.getItem() == FARMING_CAPE_T)
			|| r.getEquipment().stream().anyMatch(st -> st.getItem() == FARMING_CAPE || st.getItem() == FARMING_CAPE_T);
		if (config.farmingCapeMode() == FarmingCapeMode.OFF || !herbs || listed || client.getRealSkillLevel(Skill.FARMING) < 99) {
			return inv;
		}
		List<FarmRoute.Stack> all = new ArrayList<>(inv);
		all.add(FarmRoute.Stack.extra(FARMING_CAPE, "Farming cape", "Wear before picking herbs"));
		return all;
	}

	enum Highlight {
		TELEPORT, SEED, PAYMENT, COMPOST
	}

	public void clear() {
		running = false;
		open = false;
		selectedStop = -1;
		leprechaun = Collections.emptyMap();
		route = null;
		routes = Collections.emptyList();
		loaded = false;
		error = null;
		state = null;
		synchronized (queue) {
			queue.clear();
		}
		awayFrom = -1;
		completedTick = -1;
		carried = Collections.emptyMap();
	}
}

package com.osrscompanion;

import com.osrscompanion.FarmPatchProgress.Status;
import com.osrscompanion.model.FarmRoute;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;

/**
 * The farm run step box (like Quest Helper's): which stop you are on, how to get there,
 * and what to do at each patch, ticking off as you plant; it points out a patch that has
 * no compost yet and a minigame teleport that is still on its cooldown.
 */
public class FarmRunOverlay extends OverlayPanel {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "farm-run-overlay";

	static final Color TITLE_COLOR = new Color(0xF2, 0x8C, 0x28);
	static final Color MUTED_COLOR = new Color(0xA5, 0xA5, 0xA5);
	static final Color DONE_COLOR = new Color(0x0D, 0xC1, 0x0D);
	static final Color TODO_COLOR = new Color(0xFF, 0xE0, 0x4A);
	static final Color COMPOST_COLOR = new Color(0xF9, 0x73, 0x16);
	private static final int WIDTH = 220;
	private static final int ICON_GAP = 6;
	private static final BufferedImage SPACER = new BufferedImage(1, 4, BufferedImage.TYPE_INT_ARGB);

	private final OSRSCompanionConfig config;
	private final FarmRunManager manager;
	private final ItemManager itemManager;
	private final Map<Integer, BufferedImage> icons = new HashMap<>();

	@Inject
	public FarmRunOverlay(OSRSCompanionConfig config, FarmRunManager manager, ItemManager itemManager) {
		this.config = config;
		this.manager = manager;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		return Guard.render(GUARD_FEATURE, () -> {
			if (!config.showFarmRun() || !manager.isRunning()) {
				return null;
			}
			FarmRoute route = manager.getRoute();
			FarmRoute.Stop stop = manager.getCurrentStop();
			if (route == null || stop == null) {
				return null;
			}
			FontMetrics fm = graphics.getFontMetrics();
			int textWidth = WIDTH - 14;
			panelComponent.getChildren().clear();

			int[] progress = manager.progress();
			String title = manager.isComplete() ? "Farm run complete!"
				: "Farm run - stop " + (manager.getStopIndex() + 1) + "/" + route.getStops().size();
			panelComponent.getChildren().add(LineComponent.builder().left(title).leftColor(manager.isComplete() ? DONE_COLOR : TITLE_COLOR)
				.right(progress[0] + "/" + progress[1] + " done").rightColor(MUTED_COLOR).build());

			if (manager.isComplete()) {
				for (String line : wrap("Every patch is planted, skipped or still growing. The run stops when you leave this stop.", fm, textWidth)) {
					panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(MUTED_COLOR).build());
				}
				for (FarmRoute.Patch p : stop.getPatches()) {
					if (manager.needsCompost(p)) {
						for (String line : wrap(p.getType() + ": no compost yet: use your " + compostName() + " on the patch.", fm, textWidth)) {
							panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(COMPOST_COLOR).build());
						}
					}
				}
				panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
				return super.render(graphics);
			}

			for (String line : wrap(stop.getName(), fm, textWidth)) {
				panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(Color.WHITE).build());
			}
			FarmRoute.Travel travel = manager.travelOf(stop);
			String via = (travel.isWalk() ? "" : travel.isSpell() ? "Cast " : "Use ") + travel.getName() + (travel.isSpell() ? " (normal spellbook)" : "");
			Integer travelItem = travel.getItems().isEmpty() ? null : travel.getItems().get(0);
			addIconLine(travelItem, via, Color.CYAN, fm, textWidth);
			for (String line : wrap(travel.getHow(), fm, textWidth)) {
				panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(MUTED_COLOR).build());
			}
			int cooldown = manager.minigameCooldownMinutes();
			if (cooldown > 0) {
				String wait = "Minigame teleports are on cooldown for " + cooldown + " more min" + (cooldown == 1 ? "" : "s")
					+ (travel != stop.getTravel() ? ": go this way instead of the " + stop.getTravel().getName() + "." : ": use another way there.");
				for (String line : wrap(wait, fm, textWidth)) {
					panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(Color.YELLOW).build());
				}
			}
			panelComponent.getChildren().add(new ImageComponent(SPACER));

			if (manager.needsFarmingCape()) {
				for (String line : wrap("Put on your Farming cape before picking the herbs.", fm, textWidth)) {
					panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(Color.YELLOW).build());
				}
			}
			String compost = compostName();
			int behind = manager.compostBehind();
			if (behind > 0) {
				String step = behind + (behind == 1 ? " patch" : " patches") + " at the last stop still " + (behind == 1 ? "has" : "have") + " no compost: use your " + compost + " on " + (behind == 1 ? "it." : "them.");
				for (String line : wrap(step, fm, textWidth)) {
					panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(COMPOST_COLOR).build());
				}
			}
			for (FarmRoute.Patch p : stop.getPatches()) {
				Status s = manager.statusOf(p);
				String label = p.getType() + (p.getCrop() != null ? ": " + p.getCrop() : "");
				Color color = s == Status.DONE ? DONE_COLOR : s == Status.TODO ? TODO_COLOR : MUTED_COLOR;
				String state = s == Status.DONE ? "done" : s == Status.NOT_READY ? "not ready" : s == Status.SKIPPED ? "skipped" : "";
				panelComponent.getChildren().add(LineComponent.builder().left(label).leftColor(color).right(state).rightColor(color).build());
				if (s.isOpen()) {
					for (String step : stepsFor(p)) {
						for (String line : wrap(step, fm, textWidth - 8)) {
							panelComponent.getChildren().add(LineComponent.builder().left("  " + line).leftColor(MUTED_COLOR).build());
						}
					}
				}
				if (manager.needsCompost(p)) {
					String step = (s == Status.DONE ? "No compost yet: use your " : "Compost it: use your ") + compost + " on the patch.";
					for (String line : wrap(step, fm, textWidth - 8)) {
						panelComponent.getChildren().add(LineComponent.builder().left("  " + line).leftColor(COMPOST_COLOR).build());
					}
				}
			}
			if (stop.getNote() != null) {
				for (String line : wrap(stop.getNote(), fm, textWidth)) {
					panelComponent.getChildren().add(LineComponent.builder().left(line).leftColor(TITLE_COLOR).build());
				}
			}
			panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
			return super.render(graphics);
		});
	}

	/** What to do at an open patch, in order. */
	static java.util.List<String> stepsFor(FarmRoute.Patch p) {
		java.util.List<String> steps = new java.util.ArrayList<>();
		String impl = p.getImpl() == null ? "" : p.getImpl();
		boolean tree = impl.contains("TREE") || impl.equals("REDWOOD") || impl.equals("CALQUAT") || impl.equals("CELASTRUS");
		if (impl.contains("COMPOST")) {
			steps.add("Take out the compost, then fill and close the bin.");
			return steps;
		}
		steps.add(tree ? "Check health; pay the gardener 200 coins to clear it." : "Harvest, then rake and compost.");
		if (p.getSeed() != null && p.getSeed() > 0) {
			steps.add("Plant " + (p.getSeedQty() > 1 ? p.getSeedQty() + " x " : "") + (p.getSeedName() == null ? p.getCrop() : p.getSeedName()) + ".");
		}
		List<FarmRoute.Stack> pay = p.getProtect();
		if (!pay.isEmpty()) {
			StringBuilder sb = new StringBuilder("Pay ");
			for (int i = 0; i < pay.size(); i++) {
				sb.append(i == 0 ? "" : ", ").append(pay.get(i).getQty()).append(" x ").append(pay.get(i).getName());
			}
			steps.add(sb.append(" to protect it.").toString());
		}
		return steps;
	}

	/** The compost the route brings ("Ultracompost", "Bottomless compost bucket"), or plain "compost". */
	private String compostName() {
		FarmRoute.Stack s = manager.compostStack();
		return s == null || s.getName() == null || "Item".equals(s.getName()) ? "compost" : s.getName();
	}

	private void addIconLine(Integer itemId, String text, Color color, FontMetrics fm, int width) {
		BufferedImage icon = itemId == null ? null : icons.computeIfAbsent(itemId, itemManager::getImage);
		LineComponent line = LineComponent.builder().left(text).leftColor(color).build();
		if (icon == null) {
			panelComponent.getChildren().add(line);
			return;
		}
		panelComponent.getChildren().add(SplitComponent.builder()
			.first(new ImageComponent(icon))
			.second(line)
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(ICON_GAP, 0))
			.build());
	}

	static java.util.List<String> wrap(String text, FontMetrics fm, int width) {
		return text == null || text.isEmpty() ? java.util.Collections.emptyList() : GameUi.wrap(text, fm, width);
	}
}

package com.osrscompanion;

import com.osrscompanion.FarmPatchProgress.Status;
import com.osrscompanion.model.FarmRoute;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Points the way during a farm run, like Quest Helper: the yellow hint arrow and a
 * world map marker on the current stop, and the stop's patches outlined in the scene
 * (yellow to do, green planted, grey nothing to do, orange still without compost: the
 * stop just left counts too while you are still there).
 */
public class FarmRunSceneOverlay extends Overlay {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "farm-run-markers";

	/** Patch objects further than this from the stop belong to another stop (varbits repeat between regions). */
	static final int STOP_RADIUS = 32;
	private static final int SCAN_EVERY_TICKS = 2;

	private final Client client;
	private final FarmRunManager manager;
	private final ModelOutlineRenderer outlines;
	private final WorldMapPointManager worldMap;
	private final ItemManager itemManager;

	private volatile List<Found> found = Collections.emptyList();
	private WorldMapPoint mapPoint;
	private WorldPoint arrowAt;
	private int ticks;
	/** The stop the objects found are for. */
	private FarmRoute.Stop foundFor;
	/** In your house on the way to the stop: the portal, nexus, fairy ring... the travel uses, and its name. */
	private volatile GameObject houseObject;
	private volatile String houseObjectName;
	static final Color HOUSE_COLOR = new Color(0x22, 0xD3, 0xEE);
	private static final Pattern PORTAL = Pattern.compile("the ([a-z' ()-]+?) portal");

	private static final class Found {
		final GameObject object;
		final FarmRoute.Patch patch;

		Found(GameObject object, FarmRoute.Patch patch) {
			this.object = object;
			this.patch = patch;
		}
	}

	@Inject
	public FarmRunSceneOverlay(Client client, FarmRunManager manager, ModelOutlineRenderer outlines, WorldMapPointManager worldMap,
		ItemManager itemManager) {
		this.client = client;
		this.manager = manager;
		this.outlines = outlines;
		this.worldMap = worldMap;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/**
	 * A new scene loads (a teleport, leaving your house): the objects found belong to the old one. Drawn
	 * there, the client fails on every frame until the next scan, which turned the markers off.
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (e.getGameState() != GameState.LOGGED_IN) {
				found = Collections.emptyList();
				houseObject = null;
				houseObjectName = null;
			}
		});
	}

	@Subscribe
	public void onGameTick(GameTick tick) {
		Guard.run(GUARD_FEATURE, () -> {
			// A finished run keeps pointing at the last patches while one of them still has no compost.
			boolean active = manager.isRunning() && (!manager.isComplete() || manager.hasCompostToDo());
			FarmRoute.Stop stop = active ? manager.getCurrentStop() : null;
			if (stop == null || client.getGameState() != GameState.LOGGED_IN) {
				found = Collections.emptyList();
				houseObject = null;
				clearPointers();
				return;
			}
			if (stop != foundFor) {
				// On to the next stop: the last stop's patches are not this one's (until the next scan they were).
				found = Collections.emptyList();
				foundFor = stop;
			}
			if (++ticks % SCAN_EVERY_TICKS == 0 || found.isEmpty()) {
				List<Found> all = new ArrayList<>(scan(stop));
				FarmRoute.Stop behind = manager.compostStopBehind();
				if (behind != null && behind != stop) {
					all.addAll(scan(behind));
				}
				found = all;
				findHouseObject(manager.travelOf(stop));
			}
			updatePointers(stop);
		});
	}

	/**
	 * What to use in your house for this way to the stop, as names to look for: the named portal
	 * ("then the Troll Stronghold portal"), the Portal Nexus, a fairy ring, spirit tree or jewellery box.
	 * Shared with the Slayer guide ({@link SlayerGuideHouseOverlay}).
	 */
	static List<String> houseObjectNames(FarmRoute.Travel travel) {
		if (travel == null) {
			return Collections.emptyList();
		}
		String name = travel.getName() == null ? "" : travel.getName().toLowerCase();
		String text = (name + " " + (travel.getHow() == null ? "" : travel.getHow())).toLowerCase();
		if (!text.contains("poh") && !text.contains("house")) {
			return Collections.emptyList();
		}
		if (name.contains("jewellery box")) {
			// "House teleport tab, then the jewellery box (Amulet of glory)": the box only, whatever the run after mentions.
			return Collections.singletonList("jewellery box");
		}
		List<String> out = new ArrayList<>();
		if (text.contains("nexus")) {
			out.add("portal nexus");
		}
		Matcher m = PORTAL.matcher(text);
		while (m.find()) {
			String place = m.group(1).replaceAll("\\(.*?\\)", "").trim();
			if (!place.isEmpty() && !place.equals("house")) {
				out.add(place);
			}
		}
		for (String other : new String[]{"fairy ring", "spirit tree", "jewellery box"}) {
			if (text.contains(other)) {
				out.add(other);
			}
		}
		return out;
	}

	/** In your house (an instance): finds the object the way there uses, for the outline and the arrow. Client thread. */
	private void findHouseObject(FarmRoute.Travel travel) {
		GameObject object = findHouseObject(client, travel);
		houseObject = object;
		houseObjectName = object == null ? null : objectName(client, object);
	}

	/** The object's name, through its impostor (a built hotspot's furniture). Client thread. */
	static String objectName(Client client, GameObject object) {
		ObjectComposition comp = client.getObjectDefinition(object.getId());
		if (comp != null && comp.getImpostorIds() != null && comp.getImpostor() != null) {
			comp = comp.getImpostor();
		}
		return comp == null ? null : comp.getName();
	}

	/**
	 * In your house (an instance): the object the way there uses (see {@link #houseObjectNames}), null when
	 * you are not in a house or it has none. Client thread.
	 */
	static GameObject findHouseObject(Client client, FarmRoute.Travel travel) {
		WorldView view = client.getTopLevelWorldView();
		List<String> names = houseObjectNames(travel);
		if (view == null || !view.isInstance() || names.isEmpty()) {
			return null;
		}
		Tile[][] tiles = view.getScene().getTiles()[view.getPlane()];
		for (Tile[] column : tiles) {
			for (Tile tile : column) {
				if (tile == null) {
					continue;
				}
				for (GameObject object : tile.getGameObjects()) {
					if (object == null) {
						continue;
					}
					String objectName = objectName(client, object);
					String name = objectName == null ? "" : objectName.toLowerCase();
					for (String wanted : names) {
						// A destination portal is named after the place ("Troll Stronghold Portal"); the nexus,
						// fairy ring and others by what they are (a spiritual fairy tree is a fairy ring too).
						boolean match = wanted.equals("fairy ring") ? name.contains("fairy ring") || name.contains("spiritual fairy tree")
							: name.contains(wanted);
						if (match && !name.equals("portal")) {
							return object;
						}
					}
				}
			}
		}
		return null;
	}

	/** Finds the stop's patch objects in the loaded scene (the patch object's varbit is the patch's). */
	private List<Found> scan(FarmRoute.Stop stop) {
		Map<Integer, FarmRoute.Patch> byVarbit = new HashMap<>();
		for (FarmRoute.Patch p : stop.getPatches()) {
			byVarbit.putIfAbsent(p.getVarbit(), p);
		}
		WorldView view = client.getTopLevelWorldView();
		if (view == null) {
			return Collections.emptyList();
		}
		Scene scene = view.getScene();
		int plane = view.getPlane();
		Tile[][] tiles = scene.getTiles()[plane];
		WorldPoint centre = new WorldPoint(stop.getX(), stop.getY(), stop.getPlane());
		List<Found> out = new ArrayList<>();
		for (Tile[] column : tiles) {
			for (Tile tile : column) {
				if (tile == null) {
					continue;
				}
				for (GameObject object : tile.getGameObjects()) {
					if (object == null || object.getWorldLocation().distanceTo2D(centre) > STOP_RADIUS) {
						continue;
					}
					ObjectComposition comp = client.getObjectDefinition(object.getId());
					if (comp == null || comp.getImpostorIds() == null) {
						continue;
					}
					FarmRoute.Patch patch = byVarbit.get(comp.getVarbitId());
					if (patch != null && out.stream().noneMatch(f -> f.object == object)) {
						out.add(new Found(object, patch));
					}
				}
			}
		}
		return out;
	}

	/**
	 * The arrow goes to the first patch still to do, else to one still without compost (the stop's
	 * tile until it is in view); the map marker to the stop.
	 */
	private void updatePointers(FarmRoute.Stop stop) {
		WorldPoint target = null;
		GameObject house = houseObject;
		if (house != null) {
			// In your house: the arrow points at the portal (or nexus...) to take.
			target = house.getWorldLocation();
		}
		for (Found f : found) {
			if (target == null && manager.statusOf(f.patch).isOpen()) {
				target = f.object.getWorldLocation();
				break;
			}
		}
		if (target == null) {
			for (Found f : found) {
				if (target == null && manager.needsCompost(f.patch)) {
					target = f.object.getWorldLocation();
					break;
				}
			}
		}
		if (target == null) {
			// Not in view yet: the furthest tile of the way there you can see (a boat), else the stop's tile.
			WorldPoint at = new WorldPoint(stop.getX(), stop.getY(), stop.getPlane());
			WorldView view = client.getTopLevelWorldView();
			target = view == null || inScene(view, at) != null ? null : furthestOnWay(view, manager.travelOf(stop));
			target = target == null ? at : target;
		}
		if (!target.equals(arrowAt)) {
			client.setHintArrow(target);
			arrowAt = target;
		}
		WorldPoint stopPoint = new WorldPoint(stop.getX(), stop.getY(), stop.getPlane());
		if (mapPoint == null || !stopPoint.equals(mapPoint.getWorldPoint())) {
			if (mapPoint != null) {
				worldMap.remove(mapPoint);
			}
			mapPoint = new WorldMapPoint(stopPoint, pin());
			mapPoint.setTooltip("Farm run: " + stop.getName());
			// Click to centre the world map on the stop ("Focus on <name>"). RuneLite
			// requires a name for clickable points (it asserts on it in developer mode).
			mapPoint.setName("Farm run: " + stop.getName());
			mapPoint.setTarget(stopPoint);
			mapPoint.setSnapToEdge(true);
			mapPoint.setJumpOnClick(true);
			worldMap.add(mapPoint);
		}
	}

	/**
	 * The furthest tile of the travel's way (from the website) in the loaded scene, else null. Shared with the
	 * Slayer guide ({@link SlayerGuideMarkers}).
	 */
	static WorldPoint furthestOnWay(WorldView view, FarmRoute.Travel travel) {
		List<int[]> way = travel == null ? Collections.emptyList() : travel.getWay();
		for (int i = way.size() - 1; i >= 0; i--) {
			WorldPoint at = inScene(view, new WorldPoint(way.get(i)[0], way.get(i)[1], way.get(i)[2]));
			if (at != null) {
				return at;
			}
		}
		return null;
	}

	/** The tile as it is in the loaded scene (an instance's copy of a template tile too), or null when it is not. */
	static WorldPoint inScene(WorldView view, WorldPoint p) {
		for (WorldPoint w : WorldPoint.toLocalInstance(view, p)) {
			if (w.getPlane() == view.getPlane() && LocalPoint.fromWorld(view, w) != null) {
				return w;
			}
		}
		return null;
	}

	/** Removes the arrow (only if it is ours) and the map marker. Client thread. */
	void clearPointers() {
		if (arrowAt != null) {
			if (arrowAt.equals(client.getHintArrowPoint())) {
				client.clearHintArrow();
			}
			arrowAt = null;
		}
		if (mapPoint != null) {
			worldMap.remove(mapPoint);
			mapPoint = null;
		}
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		return Guard.render(GUARD_FEATURE, () -> {
			GameObject house = houseObject;
			if (house != null && manager.isRunning()) {
				outlines.drawOutline(house, 3, HOUSE_COLOR, 4);
				String label = "Use: " + houseObjectName;
				Point at = house.getCanvasTextLocation(graphics, label, 200);
				if (at != null) {
					OverlayUtil.renderTextLocation(graphics, at, label, HOUSE_COLOR);
				}
			}
			List<Found> list = found;
			if (list.isEmpty() || !manager.isRunning()) {
				return null;
			}
			for (Found f : list) {
				Status s = manager.statusOf(f.patch);
				// Still without compost (the compost is highlighted in the inventory too): a patch to do says so
				// in its label, a planted one turns orange.
				boolean compost = manager.needsCompost(f.patch);
				Color color = compost && s != Status.TODO ? FarmRunOverlay.COMPOST_COLOR : s == Status.DONE ? FarmRunOverlay.DONE_COLOR
					: s == Status.TODO ? FarmRunOverlay.TODO_COLOR : FarmRunOverlay.MUTED_COLOR;
				outlines.drawOutline(f.object, 2, color, 4);
				Polygon tile = f.object.getCanvasTilePoly();
				if (tile != null && (s == Status.TODO || compost)) {
					graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 40));
					graphics.fill(tile);
				}
				String label = f.patch.getType();
				if (manager.capeBlocks(f.patch)) {
					// Farming cape for herbs on Force: no picking (left click walks) until the cape is on.
					label = "WEAR Farming cape";
					color = FarmRunOverlay.COMPOST_COLOR;
				} else if (s == Status.TODO) {
					label = manager.nextStep(f.patch);
				} else if (compost) {
					label += " - compost it";
				} else {
					label += s == Status.DONE ? " - done" : " - not ready";
				}
				Point at = f.object.getCanvasTextLocation(graphics, label, 160);
				if (at != null) {
					OverlayUtil.renderTextLocation(graphics, at, label, color);
				}
			}
			return null;
		});
	}

	private BufferedImage pinImage;

	/** The stop's mark on the world map: a watering can (the item picture, a bit bigger than a map icon; it fills in once loaded). */
	private BufferedImage pin() {
		if (pinImage == null) {
			pinImage = itemManager.getImage(ItemID.WATERING_CAN_8);
		}
		return pinImage;
	}
}

package com.osrscompanion;

import static com.osrscompanion.GameUi.*;

import com.osrscompanion.FarmPatchProgress.Status;
import com.osrscompanion.model.FarmRoute;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * The farm run window, drawn over the game like the gear progression window: the
 * route's stops on the left, what to bring (worn gear and inventory, with where
 * each missing item is: bank, seed vault, seed box or tool leprechaun) on the right,
 * and the selected stop's details with the run's buttons below it.
 */
@Singleton
public class FarmRunWindow extends GameWindow {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "farm-run-window";

	private static final int MAX_WIDTH = 900;
	private static final int MAX_HEIGHT = 600;
	private static final int MIN_WIDTH = 560;
	private static final int MIN_HEIGHT = 340;
	private static final int SUBTITLE_HEIGHT = 22;
	private static final int ROW_HEIGHT = 46;
	private static final int SLOT_GAP = 3;
	private static final int BUTTON_WIDTH = 120;
	private static final int BUTTON_HEIGHT = 20;
	private static final int SCROLL_STEP = 24;
	private static final Color STORED = new Color(0xFF981F);
	private static final Color CYAN = new Color(0x22D3EE);

	/** Worn-equipment layout as in the game: 3 columns, null = no slot there. */
	private static final String[][] EQUIPMENT = {
		{null, "head", null}, {"cape", "neck", "ammo"}, {"weapon", "body", "shield"}, {null, "legs", null}, {"hands", "feet", "ring"},
	};
	/** Storage names as the website sends them, with their one-letter badge. */
	private static final Map<String, String[]> STORAGE = new LinkedHashMap<>();

	static {
		Tables.map("farmStorage").forEach((place, text) -> STORAGE.put(place, Tables.strings(text).toArray(new String[0])));
	}

	private final FarmRunManager manager;
	private final ItemManager itemManager;

	private volatile Rectangle stopsArea;
	private volatile int scroll;
	private volatile int maxScroll;

	@Inject
	public FarmRunWindow(Client client, FarmRunManager manager, ItemManager itemManager) {
		super(client, GUARD_FEATURE);
		this.manager = manager;
		this.itemManager = itemManager;
	}

	// ------------------------------------------------------------------ render

	@Override
	public Dimension render(Graphics2D g) {
		return Guard.render(GUARD_FEATURE, () -> {
			List<Hit> newHits = new ArrayList<>();
			Rectangle win = frame(g, client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null && manager.isOpen(), MAX_WIDTH, MAX_HEIGHT, MIN_WIDTH, MIN_HEIGHT, "Farm Run", newHits);
			if (win == null) {
				return null;
			}
			int x = win.x;
			int y = win.y;
			int w = win.width;
			int h = win.height;

			FarmRoute route = manager.getRoute();
			if (route == null || route.getStops().isEmpty()) {
				message(g, win, newHits);
				finish(g, win, newHits, null);
				return new Dimension(w, h);
			}

			if (route.getReviewChanges() > 0) {
				// The route changed since it was saved (new unlocks, bank): the website lists what.
				g.setFont(FontManager.getRunescapeSmallFont());
				text(g, "Route changed - review it on the website", x + 12, y + 19, YELLOW);
			}
			Rectangle switchButton = subtitle(g, route, win, newHits);
			int bodyY = y + TITLE_HEIGHT + SUBTITLE_HEIGHT + 6;
			int bodyBottom = y + h - 10;
			int leftW = Math.max(250, (int) (w * 0.4));
			// Stops on top (60%), the run's numbers under them.
			int stopsH = (bodyBottom - bodyY) * 60 / 100;
			Rectangle stops = new Rectangle(x + 8, bodyY, leftW, stopsH);
			renderStops(g, route, stops, newHits);
			renderRunInfo(g, route, new Rectangle(stops.x, stops.y + stopsH + 6, leftW, bodyBottom - bodyY - stopsH - 6));

			int rightX = stops.x + stops.width + 8;
			int rightW = x + w - 8 - rightX;
			int bodyH = bodyBottom - bodyY;
			// Slots shrink on small screens so the inventory's 7 rows and the details both fit.
			int slot = Math.max(26, Math.min(36, (bodyH * 62 / 100 - 44) / 7 - SLOT_GAP));
			int loadoutH = 26 + 7 * (slot + SLOT_GAP) + 18;
			Rectangle loadout = new Rectangle(rightX, bodyY, rightW, loadoutH);
			renderLoadout(g, route, loadout, slot, newHits);
			Rectangle detail = new Rectangle(rightX, loadout.y + loadout.height + 6, rightW, bodyBottom - loadout.y - loadout.height - 6);
			renderDetail(g, route, detail, newHits);

			if (switcherOpen && switchButton != null) {
				renderSwitcher(g, switchButton, newHits);
			}
			finish(g, win, newHits, stops);
			return new Dimension(w, h);
		});
	}

	/** Route name (with a switcher), the run's numbers and the Start / Stop button. Returns the switch button. */
	private Rectangle subtitle(Graphics2D g, FarmRoute route, Rectangle win, List<Hit> newHits) {
		int subY = win.y + TITLE_HEIGHT + 16;
		g.setFont(FontManager.getRunescapeSmallFont());
		int after = text(g, "Route: ", win.x + 12, subY, BEIGE);
		g.setFont(FontManager.getRunescapeFont());
		after = text(g, truncate(route.getName(), g.getFontMetrics(), win.width / 4), after, subY, Color.WHITE);
		if (route.isReady() && !manager.isRunning()) {
			// Every patch of the run is ready to harvest.
			after = text(g, "  READY", after, subY, GREEN);
		}
		Rectangle switchButton = null;
		if (manager.getRoutes().size() > 1) {
			switchButton = new Rectangle(after + 8, subY - 13, 62, 17);
			button(g, switchButton, switcherOpen ? "Close" : "Switch", false);
			newHits.add(new Hit(switchButton, () -> switcherOpen = !switcherOpen, "Switch to another route"));
		} else {
			switcherOpen = false;
		}

		Rectangle start = new Rectangle(win.x + win.width - 12 - BUTTON_WIDTH, subY - 14, BUTTON_WIDTH, BUTTON_HEIGHT);
		boolean running = manager.isRunning();
		button(g, start, running ? "Stop run" : "Start run", false);
		newHits.add(new Hit(start, running ? manager::stop : manager::start,
			running ? "Stop guiding this run" : "Guide this run: arrow, patch outlines and the step box"));
		return switchButton;
	}

	/** The run's numbers, one per line: patches, ready, progress, run time, when the next run is due, XP and profit. */
	private void renderRunInfo(Graphics2D g, FarmRoute route, Rectangle area) {
		if (area.height < 40) {
			return;
		}
		panel(g, area);
		g.setFont(FontManager.getRunescapeBoldFont());
		text(g, "This run", area.x + 10, area.y + 18, ORANGE);

		int[] p = manager.progress();
		long ready = route.getStops().stream().flatMap(s -> s.getPatches().stream()).filter(pt -> "ready".equals(pt.getReady())).count();
		FarmRoute.Summary sum = route.getSummary();
		List<String[]> rows = new ArrayList<>();
		List<Color> colors = new ArrayList<>();
		java.util.function.BiConsumer<String[], Color> row = (r, c) -> { rows.add(r); colors.add(c); };
		row.accept(new String[]{"Patches", String.valueOf(p[1])}, Color.WHITE);
		if (manager.isRunning()) {
			row.accept(new String[]{"Done", manager.isComplete() ? "Run complete!" : p[0] + " / " + p[1]}, manager.isComplete() ? GREEN : YELLOW);
		} else {
			row.accept(new String[]{"Ready", String.valueOf(ready)}, ready > 0 ? GREEN : Color.WHITE);
		}
		if (sum != null) {
			row.accept(new String[]{"Run time", "~" + Math.max(1, Math.round(sum.getActiveSec() / 60.0)) + " min"}, Color.WHITE);
		}
		long next = manager.nextRunAt();
		long wait = next - System.currentTimeMillis() / 1000;
		row.accept(new String[]{"Next run", next < 0 ? "not known yet" : next == 0 || wait <= 0 ? "now" : "in ~" + duration(wait)},
			next < 0 ? GREY : next == 0 || wait <= 0 ? GREEN : Color.WHITE);
		if (sum != null && sum.getXp() > 0) {
			row.accept(new String[]{"Farming XP", "~" + QuantityFormatter.quantityToStackSize(sum.getXp())}, Color.WHITE);
		}
		if (sum != null && sum.getGp() != 0) {
			row.accept(new String[]{"Profit", "~" + QuantityFormatter.quantityToStackSize(sum.getGp()) + " gp"}, sum.getGp() > 0 ? GREEN : RED);
		}

		g.setFont(FontManager.getRunescapeFont());
		int y = area.y + 38;
		int right = area.x + area.width - 12;
		for (int i = 0; i < rows.size() && y <= area.y + area.height - 6; i++) {
			text(g, rows.get(i)[0], area.x + 12, y, BEIGE);
			String v = rows.get(i)[1];
			text(g, v, right - g.getFontMetrics().stringWidth(v), y, colors.get(i));
			y += 17;
		}
	}

	/** "45 min", "3h 20m". */
	private static String duration(long seconds) {
		long min = Math.max(1, Math.round(seconds / 60.0));
		return min < 60 ? min + " min" : min / 60 + "h " + min % 60 + "m";
	}

	private void renderSwitcher(Graphics2D g, Rectangle anchor, List<Hit> newHits) {
		List<FarmRoute.RouteSummary> routes = manager.getRoutes();
		switcher(g, new Rectangle(anchor.x, anchor.y + anchor.height + 2, 220, routes.size() * 18 + 6), routes, FarmRoute.RouteSummary::isActive,
			FarmRoute.RouteSummary::getName, r -> r.isActive() ? "active" : null, 38, 50, true, null, manager::activate, newHits);
	}

	/** No route to show: why (loading, an error, none made yet), and a Refresh button to load it again. */
	private void message(Graphics2D g, Rectangle win, List<Hit> newHits) {
		String message = manager.isLoading() ? "Loading your farm route..."
			: manager.getError() != null ? manager.getError()
			: !manager.isLoaded() ? "No farm route known yet. Press Refresh to load it."
			: "No farm route yet. On the OSRS Companion website, open Tools > Farm Runs and build one for this character, then press Refresh.";
		g.setFont(FontManager.getRunescapeFont());
		int lineY = win.y + win.height / 2 - 24;
		for (String line : wrap(message, g.getFontMetrics(), win.width - 80)) {
			centred(g, line, win.x + win.width / 2, lineY, Color.WHITE);
			lineY += 16;
		}
		Rectangle refresh = new Rectangle(win.x + (win.width - BUTTON_WIDTH) / 2, lineY + 8, BUTTON_WIDTH, BUTTON_HEIGHT);
		button(g, refresh, manager.isLoading() ? "Loading..." : "Refresh", manager.isLoading());
		newHits.add(new Hit(refresh, manager::refresh, "Load your farm route from the website"));
	}

	// ------------------------------------------------------------------ stops

	private void renderStops(Graphics2D g, FarmRoute route, Rectangle area, List<Hit> newHits) {
		panel(g, area);
		g.setFont(FontManager.getRunescapeBoldFont());
		text(g, "Stops", area.x + 10, area.y + 18, ORANGE);
		g.setFont(FontManager.getRunescapeSmallFont());
		String legend = manager.isRunning() ? "to do  done  nothing to do" : "ready  growing  not checked";
		int lx = area.x + area.width - 12 - g.getFontMetrics().stringWidth(legend);
		if (manager.isRunning()) {
			lx = text(g, "to do  ", lx, area.y + 17, YELLOW);
			lx = text(g, "done  ", lx, area.y + 17, GREEN);
			text(g, "nothing to do", lx, area.y + 17, GREY);
		} else {
			lx = text(g, "ready  ", lx, area.y + 17, GREEN);
			lx = text(g, "growing  ", lx, area.y + 17, GREY);
			text(g, "not checked", lx, area.y + 17, BEIGE);
		}

		Rectangle view = new Rectangle(area.x + 4, area.y + 26, area.width - 8, area.height - 30);
		List<FarmRoute.Stop> stops = route.getStops();
		int content = stops.size() * (ROW_HEIGHT + 2);
		maxScroll = Math.max(0, content - view.height);
		int offset = Math.min(scroll, maxScroll);
		int selected = manager.getSelectedStop();
		Shape oldClip = g.getClip();
		g.clip(view);
		for (int i = 0; i < stops.size(); i++) {
			FarmRoute.Stop stop = stops.get(i);
			Rectangle row = new Rectangle(view.x, view.y + i * (ROW_HEIGHT + 2) - offset, view.width - (maxScroll > 0 ? 6 : 0), ROW_HEIGHT);
			if (row.y + row.height < view.y || row.y > view.y + view.height) {
				continue;
			}
			boolean current = manager.isRunning() && i == manager.getStopIndex() && !manager.isComplete();
			boolean done = manager.isRunning() && stop.getPatches().stream().noneMatch(pt -> manager.statusOf(pt).isOpen());
			if (i == selected) {
				g.setColor(TAB_ON);
				g.fillRect(row.x, row.y, row.width, row.height);
			}
			if (current || i == selected) {
				g.setColor(current ? YELLOW : ORANGE);
				g.drawRect(row.x, row.y, row.width - 1, row.height - 1);
			}
			g.setFont(FontManager.getRunescapeFont());
			Color nameColor = current ? YELLOW : done ? GREEN : Color.WHITE;
			int nx = text(g, (i + 1) + ".", row.x + 6, row.y + 16, nameColor) + 5;
			// Patch icons on the right; the name takes what is left.
			int iconsW = Math.min(stop.getPatches().size(), 4) * 22;
			text(g, truncate(stop.getName(), g.getFontMetrics(), row.x + row.width - iconsW - 10 - nx), nx, row.y + 16, nameColor);
			int ix = row.x + row.width - 6 - iconsW;
			for (int p = 0; p < stop.getPatches().size() && p < 4; p++) {
				FarmRoute.Patch patch = stop.getPatches().get(p);
				patchIcon(g, patch, ix + p * 22, row.y + 4);
			}
			FarmRoute.Travel travel = manager.travelOf(stop);
			g.setFont(FontManager.getRunescapeSmallFont());
			int tx = row.x + 22;
			if (!travel.getItems().isEmpty()) {
				BufferedImage icon = icon(travel.getItems().get(0), 1, false);
				if (icon != null) {
					g.drawImage(icon, tx - 2, row.y + 22, 20, 18, null);
					tx += 20;
				}
			}
			text(g, truncate((travel.isWalk() ? "" : travel.isSpell() ? "Cast " : "") + travel.getName(), g.getFontMetrics(), row.width - (tx - row.x) - 8), tx, row.y + 37, BEIGE);
			if (view.contains(row.x, Math.max(view.y, Math.min(row.y + row.height / 2, view.y + view.height - 1)))) {
				final int index = i;
				newHits.add(new Hit(row.intersection(view), () -> manager.selectStop(index), null));
			}
		}
		g.setClip(oldClip);
		if (maxScroll > 0) {
			int trackX = area.x + area.width - 7;
			g.setColor(PANEL_EDGE);
			g.fillRect(trackX, view.y, 3, view.height);
			int thumbH = Math.max(20, view.height * view.height / Math.max(1, content));
			int thumbY = view.y + (view.height - thumbH) * offset / Math.max(1, maxScroll);
			g.setColor(FRAME_LIGHT);
			g.fillRect(trackX, thumbY, 3, thumbH);
		}
	}

	/** A patch's seed with a coloured bar under it: its state in the run, or its ready state before. */
	private void patchIcon(Graphics2D g, FarmRoute.Patch patch, int x, int y) {
		if (patch.getSeed() != null && patch.getSeed() > 0) {
			BufferedImage icon = icon(patch.getSeed(), 1, false);
			if (icon != null) {
				g.drawImage(icon, x, y, 20, 18, null);
			}
		}
		Color c;
		if (manager.isRunning()) {
			Status s = manager.statusOf(patch);
			c = s == Status.DONE ? GREEN : s == Status.TODO ? YELLOW : GREY;
		} else {
			String r = patch.getReady();
			c = "ready".equals(r) ? GREEN : "diseased".equals(r) || "dead".equals(r) ? RED : "growing".equals(r) ? GREY : BEIGE;
		}
		g.setColor(Color.BLACK);
		g.fillRect(x + 1, y + 20, 19, 4);
		g.setColor(c);
		g.fillRect(x + 2, y + 21, 17, 2);
	}

	// ------------------------------------------------------------------ loadout

	private void renderLoadout(Graphics2D g, FarmRoute route, Rectangle area, int slot, List<Hit> newHits) {
		panel(g, area);
		int carried = 0;
		int total = 0;
		for (FarmRoute.Stack s : manager.loadout()) {
			total++;
			if (manager.carried(s.getItem()) >= s.getQty()) {
				carried++;
			}
		}
		g.setFont(FontManager.getRunescapeBoldFont());
		text(g, "Bring", area.x + 10, area.y + 18, ORANGE);
		g.setFont(FontManager.getRunescapeSmallFont());
		String count = carried + " / " + total + " carried";
		text(g, count, area.x + area.width - 10 - g.getFontMetrics().stringWidth(count), area.y + 17, carried == total ? GREEN : BEIGE);

		int top = area.y + 26;
		int cell = slot + SLOT_GAP;
		// Worn equipment in the game's layout.
		Map<String, FarmRoute.Stack> worn = new LinkedHashMap<>();
		for (FarmRoute.Stack s : route.getEquipment()) {
			worn.putIfAbsent(s.getSlot(), s);
		}
		int ex = area.x + 10;
		int ey = top + cell; // a row lower so it sits beside the inventory's middle
		for (int r = 0; r < EQUIPMENT.length; r++) {
			for (int c = 0; c < 3; c++) {
				String name = EQUIPMENT[r][c];
				if (name == null) {
					continue;
				}
				Rectangle cellRect = new Rectangle(ex + c * cell, ey + r * cell, slot, slot);
				FarmRoute.Stack s = worn.get(name);
				drawItemSlot(g, cellRect, s, newHits);
			}
		}
		// Inventory: 4 x 7.
		int ix = ex + 3 * cell + 14;
		List<FarmRoute.Stack> inv = manager.inventory();
		for (int i = 0; i < 28; i++) {
			Rectangle cellRect = new Rectangle(ix + (i % 4) * cell, top + (i / 4) * cell, slot, slot);
			drawItemSlot(g, cellRect, i < inv.size() ? inv.get(i) : null, newHits);
		}
		if (inv.size() > 28) {
			g.setFont(FontManager.getRunescapeSmallFont());
			text(g, "+" + (inv.size() - 28) + " more", ix + 4 * cell + 4, top + 12, RED);
		}
		// Legend.
		g.setFont(FontManager.getRunescapeSmallFont());
		int ly = area.y + area.height - 6;
		int lx = area.x + 10;
		lx = text(g, "Carried  ", lx, ly, GREEN);
		lx = text(g, "Stored: ", lx, ly, STORED);
		lx = text(g, "B bank  V seed vault  S seed box  L tool leprechaun  ", lx, ly, BEIGE);
		text(g, "Missing", lx, ly, RED);
		int sideX = ix + 4 * cell + 6;
		int sideW = area.width - (sideX - area.x) - 8;
		if (route.getSpellbook() != null) {
			// Routes cast from the normal spellbook; red while you are on another one.
			boolean onNormal = client.getVarbitValue(VarbitID.SPELLBOOK) == 0;
			text(g, truncate("Spellbook: " + route.getSpellbook() + (onNormal ? "" : " (switch!)"), g.getFontMetrics(), sideW),
				sideX, top + 26, onNormal ? GREEN : RED);
		}
		if (!route.getRunes().isEmpty()) {
			text(g, truncate("Runes for: " + String.join(", ", route.getRunes()), g.getFontMetrics(), sideW), sideX, top + 40, BEIGE);
		}
	}

	/** One loadout slot: the item (with its quantity) and a border/badge saying whether you carry it or where it is. */
	private void drawItemSlot(Graphics2D g, Rectangle r, FarmRoute.Stack s, List<Hit> newHits) {
		box(g, r, SLOT, SLOT_EDGE, SLOT_INNER);
		if (s == null) {
			return;
		}
		BufferedImage icon = icon(s.getItem(), s.getQty(), s.getQty() > 1);
		if (icon != null) {
			int iw = Math.min(icon.getWidth(), r.width - 2);
			int ih = Math.min(icon.getHeight(), r.height - 2);
			g.drawImage(icon, r.x + (r.width - iw) / 2, r.y + (r.height - ih) / 2, iw, ih, null);
		}
		int carried = manager.carried(s.getItem());
		Map<String, Integer> where = whereStored(s);
		Color edge;
		String badge = null;
		if (carried >= s.getQty()) {
			edge = GREEN;
		} else if (!where.isEmpty()) {
			edge = STORED;
			String first = where.keySet().iterator().next();
			String[] label = STORAGE.get(first);
			badge = label != null ? label[0] : ItemWhere.isGroup(first) ? "G" : "+";
		} else {
			edge = RED;
		}
		g.setColor(edge);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		if (badge != null) {
			g.setFont(FontManager.getRunescapeSmallFont());
			text(g, badge, r.x + r.width - 8, r.y + r.height - 3, STORED);
		}
		newHits.add(new Hit(r, () -> { }, tooltipFor(s, carried, where)));
	}

	/** Where the item is besides your inventory: tool leprechaun (live), the badged storages, then any other storage. */
	private Map<String, Integer> whereStored(FarmRoute.Stack s) {
		Map<String, Integer> out = new LinkedHashMap<>();
		int lep = manager.inLeprechaun(s.getItem());
		if (lep > 0) {
			out.put("leprechaun", lep);
		}
		for (String key : STORAGE.keySet()) {
			Integer n = s.getWhere().get(key);
			if (n != null && n > 0) {
				out.put(key, n);
			}
		}
		for (Map.Entry<String, Integer> e : s.getWhere().entrySet()) {
			if (e.getValue() != null && e.getValue() > 0) {
				out.putIfAbsent(e.getKey(), e.getValue());
			}
		}
		return out;
	}

	private static String tooltipFor(FarmRoute.Stack s, int carried, Map<String, Integer> where) {
		StringBuilder sb = new StringBuilder(s.getName()).append(s.getQty() > 1 ? " x" + s.getQty() : "");
		sb.append(" - carrying ").append(carried);
		for (Map.Entry<String, Integer> e : where.entrySet()) {
			String[] label = STORAGE.get(e.getKey());
			String group = ItemWhere.groupLabel(e.getKey());
			sb.append(", ").append(label != null ? label[1] : group != null ? group : e.getKey().replace('_', ' ')).append(' ').append(e.getValue());
		}
		if (carried < s.getQty() && where.isEmpty()) {
			sb.append(", not in your bank or storage");
		}
		return sb.toString();
	}

	// ------------------------------------------------------------------ details

	private void renderDetail(Graphics2D g, FarmRoute route, Rectangle area, List<Hit> newHits) {
		panel(g, area);
		int index = manager.getSelectedStop();
		if (index < 0 || area.height < 40) {
			return;
		}
		FarmRoute.Stop stop = route.getStops().get(index);
		int textW = area.width - BUTTON_WIDTH - 30;
		g.setFont(FontManager.getRunescapeBoldFont());
		text(g, truncate("Stop " + (index + 1) + " - " + stop.getName(), g.getFontMetrics(), textW), area.x + 10, area.y + 18, ORANGE);
		g.setFont(FontManager.getRunescapeFont());
		int lineY = area.y + 34;
		FarmRoute.Travel t = manager.travelOf(stop);
		String via = (t.isWalk() ? "" : t.isSpell() ? "Cast " : "Use ") + t.getName() + (t.isSpell() ? " (normal spellbook)" : "")
			+ (t.getHow().isEmpty() ? "" : ": " + t.getHow());
		for (String line : wrap(via, g.getFontMetrics(), textW)) {
			if (lineY > area.y + area.height - 6) {
				break;
			}
			text(g, line, area.x + 10, lineY, CYAN);
			lineY += 15;
		}
		for (FarmRoute.Patch p : stop.getPatches()) {
			if (lineY > area.y + area.height - 6) {
				break;
			}
			Status s = manager.isRunning() ? manager.statusOf(p) : null;
			String state = s == null ? p.getReady().replace("unknown", "not checked") : s == Status.DONE ? "done" : s == Status.NOT_READY ? "nothing to do" : s == Status.SKIPPED ? "skipped" : "to do";
			Color c = s == Status.DONE || (s == null && "ready".equals(p.getReady())) ? GREEN : s == Status.TODO ? YELLOW : GREY;
			g.setFont(FontManager.getRunescapeFont());
			text(g, truncate(p.getType() + (p.getCrop() != null ? ": " + p.getCrop() : "") + " - " + state, g.getFontMetrics(), textW), area.x + 10, lineY, c);
			lineY += 15;
			if (s == null || s == Status.TODO) {
				g.setFont(FontManager.getRunescapeSmallFont());
				for (String step : FarmRunOverlay.stepsFor(p)) {
					if (lineY > area.y + area.height - 6) {
						break;
					}
					text(g, truncate("  " + step, g.getFontMetrics(), textW), area.x + 14, lineY, GREY);
					lineY += 13;
				}
			}
		}
		if (stop.getNote() != null && lineY <= area.y + area.height - 6) {
			g.setFont(FontManager.getRunescapeSmallFont());
			text(g, truncate(stop.getNote(), g.getFontMetrics(), textW), area.x + 10, lineY, ORANGE);
		}

		// Buttons on the right.
		int bx = area.x + area.width - BUTTON_WIDTH - 10;
		int by = area.y + 10;
		boolean running = manager.isRunning();
		boolean current = running && index == manager.getStopIndex();
		if (!running) {
			Rectangle start = new Rectangle(bx, by, BUTTON_WIDTH, BUTTON_HEIGHT);
			button(g, start, "Start run", false);
			newHits.add(new Hit(start, manager::start, "Start the run at step 1 (then pick another stop and Go to this stop if you want)"));
		} else if (!current) {
			Rectangle go = new Rectangle(bx, by, BUTTON_WIDTH, BUTTON_HEIGHT);
			button(g, go, "Go to this stop", false);
			newHits.add(new Hit(go, () -> manager.goTo(index), "Make this the current stop"));
		} else if (!manager.isComplete()) {
			Rectangle skip = new Rectangle(bx, by, BUTTON_WIDTH, BUTTON_HEIGHT);
			button(g, skip, "Skip this stop", false);
			newHits.add(new Hit(skip, manager::skipStop, "Leave these patches for next time"));
			by += BUTTON_HEIGHT + 6;
			if (index > 0) {
				Rectangle back = new Rectangle(bx, by, BUTTON_WIDTH, BUTTON_HEIGHT);
				button(g, back, "Back a stop", false);
				newHits.add(new Hit(back, manager::previous, null));
			}
		}
		Rectangle refresh = new Rectangle(bx, area.y + area.height - BUTTON_HEIGHT - 10, BUTTON_WIDTH, BUTTON_HEIGHT);
		button(g, refresh, manager.isLoading() ? "Loading..." : "Refresh", manager.isLoading());
		newHits.add(new Hit(refresh, manager::refresh, "Reload the route and ready times from the website"));
	}

	private void finish(Graphics2D g, Rectangle win, List<Hit> newHits, Rectangle stops) {
		stopsArea = stops;
		finish(g, win, newHits);
	}

	/** Package-private so a preview harness can supply images without a game client. */
	BufferedImage icon(int itemId, int quantity, boolean stackable) {
		return itemManager.getImage(itemId, quantity, stackable);
	}

	// ------------------------------------------------------------------ input

	@Override
	boolean isShown() {
		return manager.isOpen();
	}

	@Override
	void closeWindow() {
		manager.close();
	}

	@Override
	void scrolled(Point p, int rotation) {
		Rectangle area = stopsArea;
		if (area != null && area.contains(p)) {
			scroll = Math.max(0, Math.min(maxScroll, scroll + rotation * SCROLL_STEP));
		}
	}

	@Override
	boolean keepsSwitcherOpen(Hit clicked) {
		return clicked != null && clicked.tooltip != null && clicked.tooltip.startsWith("Switch");
	}
}

