/**
 * An in-game window in the middle of the screen (farm run, boss gear, roadmap, slayer gear, gear progression):
 * its frame with title and close button, clickable areas with tooltips, an optional switcher list, and the mouse
 * and keyboard (Escape closes the list, then the window; clicks and the wheel inside never reach the game).
 */
abstract class GameWindow extends Overlay implements MouseListener, MouseWheelListener, KeyListener {
	static final int SCREEN_MARGIN = 10;
	static final int TITLE_HEIGHT = 28;

	/** A clickable area of the last render: what a click does, its tooltip, and whether it leaves the switcher list open. */
	static final class Hit {
		final Rectangle area;
		final Runnable action;
		final String tooltip;
		final boolean keepOpen;

		Hit(Rectangle area, Runnable action, String tooltip) {
			this(area, action, tooltip, false);
		}

		Hit(Rectangle area, Runnable action, String tooltip, boolean keepOpen) {
			this.area = area;
			this.action = action;
			this.tooltip = tooltip;
			this.keepOpen = keepOpen;
		}
	}

	final Client client;
	private final String feature;
	volatile List<Hit> hits = Collections.emptyList();
	volatile Rectangle window;
	volatile Point mouse;
	volatile boolean switcherOpen;
	/** The open switcher list: no tooltips over it, and the wheel scrolls it. */
	volatile Rectangle switcherArea;

	GameWindow(Client client, String feature) {
		this.client = client;
		this.feature = feature;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Whether the window is open (its tool says so). */
	abstract boolean isShown();

	/** Escape with no switcher list open, and the close button. */
	abstract void closeWindow();

	/** The wheel turned over the window (outside nothing; default: nothing scrolls). */
	void scrolled(Point p, int rotation) {
	}

	/** Whether clicking this area leaves an open switcher list open. */
	boolean keepsSwitcherOpen(Hit clicked) {
		return clicked != null && clicked.keepOpen;
	}

	/**
	 * The window's frame: background, border, title, close button and the title bar's line. Null (and no clickable
	 * areas) when it is not shown or the screen is smaller than its minimum size.
	 */
	Rectangle frame(Graphics2D g, boolean shown, int maxW, int maxH, int minW, int minH, String title, List<Hit> newHits) {
		if (!shown) {
			window = null;
			hits = Collections.emptyList();
			return null;
		}
		int w = Math.min(maxW, client.getCanvasWidth() - 2 * SCREEN_MARGIN);
		int h = Math.min(maxH, client.getCanvasHeight() - 2 * SCREEN_MARGIN);
		if (w < minW || h < minH) {
			window = null;
			hits = Collections.emptyList();
			return null;
		}
		int x = (client.getCanvasWidth() - w) / 2;
		int y = (client.getCanvasHeight() - h) / 2;
		g.setColor(BG);
		g.fillRect(x, y, w, h);
		g.setColor(FRAME_DARK);
		g.setStroke(new BasicStroke(3));
		g.drawRect(x + 1, y + 1, w - 3, h - 3);
		g.setStroke(new BasicStroke(1));
		g.setColor(FRAME_LIGHT);
		g.drawRect(x + 3, y + 3, w - 7, h - 7);
		g.setFont(FontManager.getRunescapeBoldFont());
		centred(g, title, x + w / 2, y + 20, ORANGE);
		Rectangle close = new Rectangle(x + w - 28, y + 6, 20, 18);
		box(g, close, BG, PANEL_EDGE, BUTTON_INNER);
		g.setColor(new Color(0xC8A24A));
		g.setStroke(new BasicStroke(2));
		g.drawLine(close.x + 6, close.y + 5, close.x + 14, close.y + 13);
		g.drawLine(close.x + 14, close.y + 5, close.x + 6, close.y + 13);
		g.setStroke(new BasicStroke(1));
		newHits.add(new Hit(close, this::closeWindow, null));
		g.setColor(PANEL_EDGE);
		g.drawLine(x + 8, y + TITLE_HEIGHT, x + w - 9, y + TITLE_HEIGHT);
		g.setColor(FRAME_LIGHT);
		g.drawLine(x + 8, y + TITLE_HEIGHT + 1, x + w - 9, y + TITLE_HEIGHT + 1);
		return new Rectangle(x, y, w, h);
	}

	/**
	 * A switcher list: one 18 px row per option that fits, the active one in orange with its note in green, the
	 * others in white with their note (if any) in grey (noteX from the right edge, 0: right-aligned); a click on another one closes the list and picks it. Its
	 * areas go first, so a click inside the list never reaches what is drawn under it.
	 */
	<T> void switcher(Graphics2D g, Rectangle list, List<T> options, Predicate<T> active, Function<T, String> name,
			Function<T, String> note, int noteX, int nameRoom, boolean hoverActive, String listTooltip, Consumer<T> pick, List<Hit> newHits) {
		g.setFont(FontManager.getRunescapeFont());
		box(g, list, BG, FRAME_DARK, BUTTON_INNER);
		List<Hit> optionHits = new ArrayList<>();
		int rowY = list.y + 3;
		for (int i = 0; i < (list.height - 6) / 18; i++) {
			T o = options.get(i);
			boolean on = active.test(o);
			Rectangle row = new Rectangle(list.x + 3, rowY, list.width - 6, 18);
			Point m = mouse;
			if ((hoverActive || !on) && m != null && row.contains(m)) {
				g.setColor(TAB_ON);
				g.fillRect(row.x, row.y, row.width, row.height);
			}
			text(g, truncate(name.apply(o), g.getFontMetrics(), row.width - nameRoom), row.x + 6, row.y + 13, on ? ORANGE : Color.WHITE);
			String n = note.apply(o);
			if (n != null) {
				g.setFont(FontManager.getRunescapeSmallFont());
				text(g, n, row.x + row.width - (noteX > 0 ? noteX : 6 + g.getFontMetrics().stringWidth(n)), row.y + 13, on ? GREEN : GREY);
				g.setFont(FontManager.getRunescapeFont());
			}
			if (!on) {
				optionHits.add(new Hit(row, () -> {
					switcherOpen = false;
					pick.accept(o);
				}, null));
			}
			rowY += 18;
		}
		optionHits.add(new Hit(list, () -> { }, listTooltip));
		newHits.addAll(0, optionHits);
	}

	/** The tooltip of the area under the mouse (not over the open switcher list); keeps this render's clickable areas. */
	void finish(Graphics2D g, Rectangle win, List<Hit> newHits) {
		Point m = mouse;
		Rectangle list = switcherArea;
		boolean overList = switcherOpen && list != null && m != null && list.contains(m);
		if (!switcherOpen) {
			switcherArea = null;
		}
		if (m != null && win.contains(m) && !overList) {
			for (Hit hit : newHits) {
				if (hit.tooltip != null && hit.area.contains(m)) {
					tooltip(g, hit.tooltip, m, win);
					break;
				}
			}
		}
		window = win;
		hits = Collections.unmodifiableList(newHits);
	}

	private boolean inside(MouseEvent e) {
		Rectangle win = window;
		return isShown() && win != null && win.contains(e.getPoint());
	}

	private MouseEvent consumeInside(MouseEvent e) {
		return Guard.call(feature, () -> {
			if (inside(e)) {
				e.consume();
			}
			return e;
		}, e);
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e) {
		return Guard.call(feature, () -> {
			if (!inside(e)) {
				return e;
			}
			if (SwingUtilities.isLeftMouseButton(e)) {
				Point p = e.getPoint();
				boolean listWasOpen = switcherOpen;
				Hit clicked = null;
				for (Hit hit : hits) {
					if (hit.area.contains(p)) {
						clicked = hit;
						break;
					}
				}
				if (clicked != null) {
					clicked.action.run();
				}
				if (listWasOpen && switcherOpen && !keepsSwitcherOpen(clicked)) {
					switcherOpen = false;
				}
			}
			e.consume();
			return e;
		}, e);
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e) {
		return consumeInside(e);
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e) {
		return consumeInside(e);
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e) {
		return consumeInside(e);
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e) {
		return Guard.call(feature, () -> {
			mouse = e.getPoint();
			if (inside(e)) {
				e.consume();
			}
			return e;
		}, e);
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e) {
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e) {
		return Guard.call(feature, () -> {
			mouse = null;
			return e;
		}, e);
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e) {
		return Guard.call(feature, () -> {
			if (inside(e)) {
				scrolled(e.getPoint(), e.getWheelRotation());
				e.consume();
			}
			return e;
		}, e);
	}

	@Override
	public void keyTyped(KeyEvent e) {
	}

	@Override
	public void keyPressed(KeyEvent e) {
		Guard.run(feature, () -> {
			if (isShown() && e.getKeyCode() == KeyEvent.VK_ESCAPE) {
				if (switcherOpen) {
					switcherOpen = false;
				} else {
					closeWindow();
				}
				e.consume();
			}
		});
	}

	@Override
	public void keyReleased(KeyEvent e) {
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import lombok.Getter;
import com.osrscompanion.model.RoadmapGoal;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.SoundEffectID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.api.WidgetNode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

/**
 * Shows the game's own notification popup (the one used for collection log and
 * combat task completions) when a roadmap goal is completed, and plays a sound.
 *
 * <p>The popup is the {@code NOTIFICATION_DISPLAY} interface opened under the
 * current top-level layout's notifications component and initialised by its
 * script; it animates in on its own and is closed once its container collapses.
 * Popups queue so two quick completions show one after the other. Other features
 * (a finished farm run) show their own title and body the same way.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class GoalCompletionNotifier {
	/** Fills the notification interface with a title and body; RuneLite's
	 * {@code ScriptID} only names the follow-up open/delay scripts (3346/3347). */
	static final int NOTIFICATION_DISPLAY_INIT = 3343;
	/** In-game sound effect for the default option. */
	static final int DEFAULT_SOUND_ID = SoundEffectID.GE_ADD_OFFER_DINGALING;
	static final String TITLE = "<col=f28c28>Roadmap Goal Complete!</col>";
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "goal-popups";

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;

	/** A popup that is queued or on screen, with the roadmap progress to draw under it. */
	public static final class Popup {
		private final String title;
		private final String body;
		@Getter
		private final String roadmapTitle;
		@Getter
		private final int goalsDone;
		@Getter
		private final int goalsTotal;

		Popup(String title, String body, String roadmapTitle, int goalsDone, int goalsTotal) {
			this.title = title;
			this.body = body;
			this.roadmapTitle = roadmapTitle;
			this.goalsDone = goalsDone;
			this.goalsTotal = goalsTotal;
		}

	}

	private final Deque<Popup> queue = new ArrayDeque<>();
	private WidgetNode openNode;
	/** The popup currently on screen (read by the overlay on the render thread). */
	@Getter
	private volatile Popup active;

	/**
	 * Queues a popup for the goal; safe to call from any thread.
	 *
	 * @param goalsDone  completed goals in the roadmap (including this one)
	 * @param goalsTotal goals in the roadmap
	 */
	public void show(RoadmapGoal goal, String roadmapTitle, int goalsDone, int goalsTotal) {
		if (goal == null || goal.getName() == null) {
			return;
		}
		Popup popup = new Popup(TITLE, body(goal.getName(), roadmapTitle, goalsDone, goalsTotal),
				roadmapTitle, goalsDone, goalsTotal);
		enqueue(popup, true);
	}

	/**
	 * Queues a popup with its own title and body (no progress bar); safe to call from any thread.
	 * The caller decides whether it is wanted (its own setting); the sound follows the goal sound.
	 */
	public void showMessage(String title, String body) {
		if (title == null || body == null) {
			return;
		}
		enqueue(new Popup(title, body, null, 0, 0), false);
	}

	private void enqueue(Popup popup, boolean goal) {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			if ((goal && !config.showGoalPopup()) || client.getGameState() != GameState.LOGGED_IN) {
				return;
			}
			queue.add(popup);
			if (openNode == null) {
				showNext();
			}
		});
	}

	/** Drops queued popups and closes an open one (plugin shutdown). */
	public void clear() {
		// A clean-up: runs even when the feature was turned off, so no popup stays open.
		clientThread.invokeLater(Guard.wrapCleanup(GUARD_FEATURE, () -> {
			queue.clear();
			closeOpen();
		}));
	}

	/** Blank lines reserved at the bottom of the body so the roadmap progress bar
	 * ({@link GoalCompletionOverlay}) can be drawn inside the box. */
	static final String PROGRESS_SPACER = "<br><br>";

	/** Builds the popup body: the goal name in white, the roadmap title beneath,
	 * then reserved space for the progress bar when the roadmap has goals. */
	static String body(String goalName, String roadmapTitle, int goalsDone, int goalsTotal) {
		String name = Text.removeTags(goalName);
		StringBuilder sb = new StringBuilder("<col=ffffff>").append(name).append("</col>");
		if (roadmapTitle != null && !roadmapTitle.trim().isEmpty()) {
			sb.append("<br><col=c6c6c6>").append(Text.removeTags(roadmapTitle)).append("</col>");
		}
		if (goalsTotal > 0) {
			sb.append(PROGRESS_SPACER);
		}
		return sb.toString();
	}

	/** The notifications component of the given top-level layout, or -1 when the
	 * layout has no popup slot the plugin knows about. */
	static int parentComponentFor(int topLevelInterfaceId) {
		switch (topLevelInterfaceId) {
			case InterfaceID.TOPLEVEL_OSRS_STRETCH:
				return InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_PRE_EOC:
				return InterfaceID.ToplevelPreEoc.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_DISPLAY:
				return InterfaceID.ToplevelDisplay.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL:
				return InterfaceID.Toplevel.NOTIFICATIONS;
			default:
				return -1;
		}
	}

	// Client thread from here down.

	private void showNext() {
		Popup popup = queue.poll();
		if (popup == null) {
			return;
		}
		int parent = parentComponentFor(client.getTopLevelInterfaceId());
		if (parent == -1) {
			queue.clear();
			return;
		}
		try {
			openNode = client.openInterface(parent, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
			client.runScript(NOTIFICATION_DISPLAY_INIT, popup.title, popup.body, -1);
		} catch (RuntimeException e) {
			openNode = null;
			return;
		}
		active = popup;
		playSound();
		Guard.invokeLater(clientThread, GUARD_FEATURE, this::pollClosed);
	}

	/** Returns false to be invoked again next tick while the popup is still visible. */
	private boolean pollClosed() {
		if (openNode == null) {
			return true;
		}
		Widget container = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
		if (container != null && container.getWidth() > 0) {
			return false;
		}
		closeOpen();
		showNext();
		return true;
	}

	private void closeOpen() {
		active = null;
		if (openNode == null) {
			return;
		}
		try {
			client.closeInterface(openNode, true);
		} catch (RuntimeException e) {
		}
		openNode = null;
	}

	private void playSound() {
		if (!config.goalCompleteSound()) {
			return;
		}
		int volume = client.getPreferences().getSoundEffectVolume();
		if (volume <= 0) {
			return;
		}
		client.playSoundEffect(DEFAULT_SOUND_ID, volume);
	}
}

package com.osrscompanion;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the whole roadmap's progress bar inside the goal completion popup while
 * it is on screen. The game's notification widget only carries text, so the
 * popup body reserves blank lines at the bottom and this overlay paints the bar
 * ("done / total goals" plus percent) into that space, anchored to the widget.
 */
public class GoalCompletionOverlay extends Overlay {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "goal-completion-overlay";

	/** Inset from the popup's frame on each side. */
	private static final int SIDE_PAD = 14;
	/**
	 * Inset from the bottom of the popup's box. The body reserves two blank
	 * lines and the box adds its own margin under the text; the bar block
	 * (about two lines tall) sits at the bottom of that space so roughly a line
	 * of air separates it from the text above and a similar margin remains below.
	 */
	private static final int BOTTOM_PAD = 8;
	/** The box grows in during its open animation; wait until it has room. */
	private static final int MIN_BOX_HEIGHT = 48;

	private final Client client;
	private final GoalCompletionNotifier notifier;

	@Inject
	public GoalCompletionOverlay(Client client, GoalCompletionNotifier notifier) {
		this.client = client;
		this.notifier = notifier;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		return Guard.render(GUARD_FEATURE, () -> {
			GoalCompletionNotifier.Popup popup = notifier.getActive();
			if (popup == null || popup.getGoalsTotal() <= 0) {
				return null;
			}
			Widget container = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
			if (container == null || container.isHidden()) {
				return null;
			}
			Rectangle bounds = container.getBounds();
			if (bounds == null || bounds.width <= 2 * SIDE_PAD || bounds.height < MIN_BOX_HEIGHT) {
				return null;
			}

			int done = popup.getGoalsDone();
			int total = popup.getGoalsTotal();
			int percent = (int) Math.min(100, Math.max(0, (long) done * 100L / total));
			GoalProgressBarComponent bar = new GoalProgressBarComponent(
					percent / 100d, done + " / " + total + " goals", percent + "%");

			// Bar block height: top gap + bar + gap + one text line.
			int height = GoalProgressBarComponent.TOP_GAP + GoalProgressBarComponent.BAR_HEIGHT
					+ GoalProgressBarComponent.BAR_TEXT_GAP + graphics.getFontMetrics().getHeight();
			int width = bounds.width - 2 * SIDE_PAD;
			bar.setPreferredLocation(new Point(bounds.x + SIDE_PAD, bounds.y + bounds.height - BOTTOM_PAD - height));
			bar.setPreferredSize(new Dimension(width, 0));
			return bar.render(graphics);
		});
	}
}

package com.osrscompanion;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * In-memory cache of goal artwork (OSRS Wiki images for bosses, combat tasks
 * and the like), scaled to overlay icon size. Only images on the hardcoded
 * {@link #WIKI_HOST} are fetched; any other URL the server sends is ignored,
 * so the plugin never contacts a host taken from a server response. Images are
 * fetched once per URL, asynchronously; until one arrives
 * {@link #get} returns null and the overlay simply draws no icon. Failed URLs
 * are not retried for the rest of the session.
 */
@Singleton
public class GoalImageCache {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "goal-images";

	/** Icons are scaled to fit this square, matching RuneLite's item sprites. */
	static final int ICON_SIZE = 32;
	private static final int FETCH_TIMEOUT_SECONDS = 10;
	/** At most this many icons (and failed URLs) are kept, so a long session's memory stays bounded. */
	static final int MAX_IMAGES = 512;
	/** At most this many fetches at once. */
	static final int MAX_PENDING = 16;
	/** The only host goal images are fetched from. */
	static final String WIKI_HOST = "oldschool.runescape.wiki";
	private static final String WIKI_IMAGE_PATH = "/images/";

	private final OkHttpClient httpClient;

	private final Map<String, BufferedImage> images = new ConcurrentHashMap<>();
	private final Set<String> pending = ConcurrentHashMap.newKeySet();
	private final Set<String> failed = ConcurrentHashMap.newKeySet();

	@Inject
	public GoalImageCache(OkHttpClient okHttpClient) {
		this.httpClient = okHttpClient.newBuilder()
				.connectTimeout(FETCH_TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.readTimeout(FETCH_TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.callTimeout(FETCH_TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.build();
	}

	/**
	 * The scaled image for a URL if it has been loaded; otherwise starts loading
	 * it (once) and returns null. Safe to call every render frame.
	 */
	public BufferedImage get(String url) {
		if (!isAllowed(url)) {
			return null;
		}
		BufferedImage cached = images.get(url);
		if (cached != null) {
			return cached;
		}
		if (images.size() >= MAX_IMAGES || failed.size() >= MAX_IMAGES || pending.size() >= MAX_PENDING) {
			return null;
		}
		if (!failed.contains(url) && pending.add(url)) {
			fetch(url);
		}
		return null;
	}

	/** True when the URL is an https image on the OSRS Wiki. */
	static boolean isAllowed(String url) {
		HttpUrl parsed = url == null ? null : HttpUrl.parse(url);
		return parsed != null
				&& parsed.isHttps()
				&& WIKI_HOST.equals(parsed.host())
				&& parsed.port() == 443
				&& parsed.encodedPath().startsWith(WIKI_IMAGE_PATH);
	}

	public void clear() {
		images.clear();
		pending.clear();
		failed.clear();
	}

	/**
	 * Fetches asynchronously (OkHttp's own threads): never blocks the caller, which may be the client
	 * thread rendering, nor RuneLite's shared executor (one thread for every plugin).
	 */
	private void fetch(String url) {
		Request request;
		try {
			request = new Request.Builder().url(url).get().build();
		} catch (RuntimeException e) {
			failed.add(url);
			pending.remove(url);
			return;
		}
		httpClient.newCall(request).enqueue(new Callback() {
			@Override
			public void onFailure(Call call, IOException e) {
				failed.add(url);
				pending.remove(url);
			}

			@Override
			public void onResponse(Call call, Response response) {
				Guard.run(GUARD_FEATURE, () -> read(url, response));
			}
		});
	}

	private void read(String url, Response response) {
		try (Response r = response) {
			if (!r.isSuccessful() || r.body() == null) {
				failed.add(url);
				return;
			}
			try (InputStream in = r.body().byteStream()) {
				BufferedImage image = ImageIO.read(in);
				if (image == null) {
					failed.add(url);
					return;
				}
				images.put(url, fit(image));
			}
		} catch (IOException | RuntimeException e) {
			failed.add(url);
		} finally {
			pending.remove(url);
		}
	}

	/** Scales the image down to fit the icon square, keeping its aspect ratio. */
	static BufferedImage fit(BufferedImage image) {
		int w = image.getWidth();
		int h = image.getHeight();
		if (w <= ICON_SIZE && h <= ICON_SIZE) {
			return image;
		}
		double scale = Math.min((double) ICON_SIZE / w, (double) ICON_SIZE / h);
		int nw = Math.max(1, (int) Math.round(w * scale));
		int nh = Math.max(1, (int) Math.round(h * scale));
		return ImageUtil.resizeImage(image, nw, nh);
	}
}

package com.osrscompanion;

import com.osrscompanion.model.RoadmapGoal;
import java.time.Instant;
import java.util.*;
import java.util.function.Predicate;

/**
 * Splits a roadmap's goals into the dependency tree the panel draws and the
 * flat "Completed" list beneath it.
 *
 * <p>The tree keeps only incomplete goals; a goal moves to the completed list
 * the moment the plugin considers it done. The completed list is sorted newest
 * first: goals completed this session (which have no server timestamp yet)
 * come first, then by the server's completion time, unknown times last. Pure,
 * so it is testable without Swing.
 */
final class GoalPartition {
	private final List<RoadmapGoal> tree;
	private final List<RoadmapGoal> completed;

	private GoalPartition(List<RoadmapGoal> tree, List<RoadmapGoal> completed) {
		this.tree = Collections.unmodifiableList(tree);
		this.completed = Collections.unmodifiableList(completed);
	}

	/**
	 * @param goals    goals in sort order
	 * @param complete whether the plugin considers a goal complete (server or local)
	 * @param session  whether the goal's completion was first seen this session
	 *                 (sorted newest in the completed list)
	 */
	static GoalPartition of(List<RoadmapGoal> goals,
			Predicate<RoadmapGoal> complete, Predicate<RoadmapGoal> session) {
		List<RoadmapGoal> tree = new ArrayList<>();
		List<RoadmapGoal> done = new ArrayList<>();
		Map<Integer, Long> recency = new HashMap<>();
		for (RoadmapGoal g : goals) {
			if (!complete.test(g)) {
				tree.add(g);
				continue;
			}
			done.add(g);
			recency.put(g.getId(), recencyKey(g, session.test(g)));
		}
		// Newest first; List.sort is stable so ties keep the roadmap's order.
		done.sort((a, b) -> Long.compare(recency.get(b.getId()), recency.get(a.getId())));
		return new GoalPartition(tree, done);
	}

	/** Session completions have no server timestamp yet: treat them as newest;
	 * a missing or unparseable timestamp sorts oldest. */
	private static long recencyKey(RoadmapGoal g, boolean thisSession) {
		if (thisSession) {
			return Long.MAX_VALUE;
		}
		Instant at = g.getCompletedAt();
		return at == null ? Long.MIN_VALUE : at.toEpochMilli();
	}

	/** Goals to draw as the dependency tree, in the given order. */
	List<RoadmapGoal> getTree() {
		return tree;
	}

	/** Finished goals for the collapsible list, newest completion first. */
	List<RoadmapGoal> getCompleted() {
		return completed;
	}
}

package com.osrscompanion;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * Side-panel progress bar: the same 6px rounded pill the OSRS Companion app draws under
 * each goal. Stretches to the card width; height is fixed.
 */
final class GoalProgressBar extends JComponent {
	static final int HEIGHT = 6;
	private static final Color TRACK = new Color(0x17, 0x17, 0x22);
	private static final Color FILL = new Color(0x25, 0x63, 0xEB);

	private final double fraction;

	GoalProgressBar(double fraction) {
		this.fraction = Math.max(0, Math.min(1, fraction));
		setOpaque(false);
		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		try {
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			g2.setColor(TRACK);
			g2.fillRoundRect(0, 0, w, HEIGHT, HEIGHT, HEIGHT);
			int fill = (int) Math.round(w * fraction);
			if (fill > 0) {
				g2.setColor(FILL);
				g2.fillRoundRect(0, 0, Math.min(w, Math.max(fill, HEIGHT)), HEIGHT, HEIGHT, HEIGHT);
			}
		} finally {
			g2.dispose();
		}
	}
}

package com.osrscompanion;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * App-style progress bar for the goal overlay: a thin rounded bar with a
 * "current / target" label beneath it and an optional right-aligned percent.
 *
 * <p>RuneLite's {@code ProgressBarComponent} is fixed at 16px with square corners
 * and the label inside the bar, so it cannot match the app's look; this draws the
 * 6px pill the app uses instead.
 */
final class GoalProgressBarComponent implements LayoutableRenderableEntity {
	static final int TOP_GAP = 4;
	static final int BAR_HEIGHT = 6;
	static final int BAR_TEXT_GAP = 3;
	static final int PERCENT_GAP = 8;

	static final Color TRACK = new Color(0, 0, 0, 110);
	static final Color FILL = new Color(0x25, 0x63, 0xEB);
	static final Color LABEL = new Color(0xC6, 0xC6, 0xC6);

	private final double fraction;
	private final String label;
	private final String percent;

	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);
	private final Rectangle bounds = new Rectangle();

	/**
	 * @param fraction bar fill in [0, 1]
	 * @param label    text drawn under the bar, e.g. "12.4K XP / 100K XP"
	 * @param percent  right-aligned text, e.g. "12%", or null to omit
	 */
	GoalProgressBarComponent(double fraction, String label, String percent) {
		this.fraction = Math.max(0, Math.min(1, fraction));
		this.label = label == null ? "" : label;
		this.percent = percent;
	}

	@Override
	public Dimension render(Graphics2D g) {
		final int x = preferredLocation.x;
		final int barY = preferredLocation.y + TOP_GAP;
		final int width = preferredSize.width;
		final FontMetrics fm = g.getFontMetrics();

		Object oldAa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(TRACK);
		g.fillRoundRect(x, barY, width, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
		int fill = (int) Math.round(width * fraction);
		if (fill > 0) {
			g.setColor(FILL);
			// Never narrower than the corner diameter so a 1% bar is still a pill.
			g.fillRoundRect(x, barY, Math.min(width, Math.max(fill, BAR_HEIGHT)), BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
		}
		if (oldAa != null) {
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAa);
		}

		int textBaseline = barY + BAR_HEIGHT + BAR_TEXT_GAP + fm.getAscent();
		TextComponent text = new TextComponent();
		text.setText(label);
		text.setColor(LABEL);
		text.setPosition(new Point(x, textBaseline));
		text.render(g);

		if (percent != null) {
			int pw = fm.stringWidth(percent);
			if (fm.stringWidth(label) + PERCENT_GAP + pw <= width) {
				TextComponent pct = new TextComponent();
				pct.setText(percent);
				pct.setColor(LABEL);
				pct.setPosition(new Point(x + width - pw, textBaseline));
				pct.render(g);
			}
		}

		int height = TOP_GAP + BAR_HEIGHT + BAR_TEXT_GAP + fm.getHeight();
		bounds.setBounds(x, preferredLocation.y, width, height);
		return new Dimension(width, height);
	}

	/** Width needed so the label (and percent) fit on one line. */
	int minWidth(FontMetrics fm) {
		int w = fm.stringWidth(label);
		if (percent != null) {
			w += PERCENT_GAP + fm.stringWidth(percent);
		}
		return w;
	}

	@Override
	public Rectangle getBounds() {
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position) {
		this.preferredLocation = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension) {
		this.preferredSize = dimension;
	}
}

package com.osrscompanion;

import com.osrscompanion.model.GoalType;
import net.runelite.client.util.QuantityFormatter;

/**
 * Formats the "current / target" label under a goal's progress bar the same way
 * the OSRS Companion app does: XP and net worth abbreviated (12.4K, 1.3M), counts with
 * thousands separators, and a single-crop farming goal as "47% grown".
 */
final class GoalProgressLabel {
	private GoalProgressLabel() {
	}

	static String format(GoalType type, int current, int target, Integer percent) {
		if (type == GoalType.FARMING_TIMER && target <= 1) {
			return (percent == null ? 0 : percent) + "% grown";
		}
		boolean abbreviate = type.isSkill() || type == GoalType.NET_WORTH;
		String unit = type.isSkill() ? " XP" : "";
		return fmt(current, abbreviate) + unit + " / " + fmt(target, abbreviate) + unit;
	}

	/** "63%", or null when the goal has no percentage. */
	static String percent(Integer percent) {
		return percent == null ? null : Math.max(0, Math.min(100, percent)) + "%";
	}

	/** Bar fill fraction in [0, 1]. */
	static double fraction(Integer percent) {
		return percent == null ? 0 : Math.max(0, Math.min(100, percent)) / 100d;
	}

	private static String fmt(int value, boolean abbreviate) {
		long v = Math.max(0, value);
		return abbreviate ? QuantityFormatter.quantityToStackSize(v) : QuantityFormatter.formatNumber(v);
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import com.osrscompanion.model.Roadmap;
import com.osrscompanion.model.RoadmapGoal;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Goal progress as the website works it out from the synced data: the goal box and the roadmap window show
 * each goal's progress from the roadmap the website sent, and a goal the website newly reports complete (since
 * its last roadmap read this session) gets the completion popup and sound.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class GoalProgressTracker {
	private final RoadmapManager roadmapManager;
	private final GoalCompletionNotifier completionNotifier;
	/** Per roadmap, the goals complete at the website's last read this session; none yet: the first read sets it. */
	private final Map<Integer, Set<Integer>> completed = new ConcurrentHashMap<>();
	/** Goals completed during this session (they linger in the roadmap window's tree). */
	private final Set<Integer> completedThisSession = ConcurrentHashMap.newKeySet();

	/** A roadmap read from the website: goals newly complete since its last read get the popup. */
	public void onServerRoadmap(Roadmap roadmap) {
		if (roadmap == null) {
			return;
		}
		Set<Integer> now = new HashSet<>();
		for (RoadmapGoal goal : roadmap.getGoals()) {
			if (goal.isComplete()) {
				now.add(goal.getId());
			}
		}
		Set<Integer> before = completed.put(roadmap.getCollectionId(), now);
		if (before == null) {
			return;
		}
		for (RoadmapGoal goal : roadmap.getGoalsSorted()) {
			if (goal.isComplete() && !before.contains(goal.getId())) {
				completedThisSession.add(goal.getId());
				// A completion in another roadmap makes that roadmap the active one.
				roadmapManager.selectRoadmap(roadmap);
				completionNotifier.show(goal, roadmap.getTitle(), now.size(), roadmap.getGoals().size());
				roadmapManager.notifyPanel();
			}
		}
	}

	/** The player's current set of roadmaps; any others are forgotten. */
	public void retainRoadmaps(Set<Integer> collectionIds) {
		completed.keySet().retainAll(collectionIds);
	}

	public void clear() {
		completed.clear();
		completedThisSession.clear();
	}

	public boolean isComplete(RoadmapGoal goal) {
		return goal.isComplete();
	}

	/** True when the goal's completion was first seen this session (it lingers in the tree). */
	public boolean completedThisSession(RoadmapGoal goal) {
		return goal != null && completedThisSession.contains(goal.getId());
	}

	public GoalProgressView progressFor(RoadmapGoal goal) {
		return GoalProgressView.fromServer(goal);
	}

	/** The first goal in sort order the website does not have complete. */
	public RoadmapGoal firstIncompleteGoal(Roadmap roadmap) {
		if (roadmap == null) {
			return null;
		}
		for (RoadmapGoal goal : roadmap.getGoalsSorted()) {
			if (!goal.isComplete()) {
				return goal;
			}
		}
		return null;
	}
}

package com.osrscompanion;

import lombok.Getter;
import com.osrscompanion.model.GoalType;
import com.osrscompanion.model.RoadmapGoal;

/**
 * A goal's progress as the plugin currently believes it: the server's numbers
 * plus whatever the client has observed locally since. Immutable snapshot built
 * per read by {@link GoalProgressState}.
 */
public final class GoalProgressView {
	@Getter
	private final GoalType type;
	@Getter
	private final int current;
	@Getter
	private final int target;
	/** 0-100, or null for binary goals that have no progress bar. */
	@Getter
	private final Integer percent;
	@Getter
	private final boolean complete;

	GoalProgressView(GoalType type, int current, int target, Integer percent, boolean complete) {
		this.type = type;
		this.current = current;
		this.target = target;
		this.percent = percent;
		this.complete = complete;
	}

	/** The server's view of a goal, untouched by local tracking. */
	public static GoalProgressView fromServer(RoadmapGoal goal) {
		Integer percent = goal.getProgressPercent();
		if (goal.isComplete() && percent != null) {
			percent = 100;
		}
		return new GoalProgressView(goal.getType(), goal.getCurrent(), goal.getTarget(), percent, goal.isComplete());
	}

	/** True when this goal is drawn with a progress bar. */
	public boolean isMeasurable() {
		return percent != null;
	}
}

package com.osrscompanion;

import java.awt.Dimension;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;

/**
 * Runs the plugin's code so a bug in one feature can never break the RuneLite client.
 *
 * <ul>
 *   <li>{@link #run}, {@link #render} and {@link #call} catch every Throwable except {@link ThreadDeath}
 *       (rethrown). The first failure of a feature is logged with its stack.</li>
 *   <li>Each feature has a {@link CircuitBreaker}: {@value #FAILURE_LIMIT} failures within
 *       {@value #FAILURE_WINDOW_MS} ms or a fatal error ({@link VirtualMachineError}, such as
 *       OutOfMemoryError or StackOverflowError) turn the feature off for the rest of the session: its
 *       sections are skipped (renders draw nothing), and the player is told once.</li>
 *   <li>The features in {@link #NEVER_DISABLED} (uploads, the website version watcher) are exempt: their
 *       failures are still caught and logged, but they are never turned off, so one bad upload cannot
 *       stop every upload for the session.</li>
 *   <li>Under tests (system property {@value #RETHROW_TEST_FAILURES_PROPERTY}, set by build.gradle's
 *       {@code test} task), {@link AssertionError} is rethrown, so a failing assertion inside guarded
 *       code fails the test instead of being swallowed. Never in production.</li>
 * </ul>
 *
 * The static methods use one shared instance; tests make their own (fake clock).
 */
@Slf4j
public final class Guard {
	static final int FAILURE_LIMIT = 5;
	static final long FAILURE_WINDOW_MS = 60_000;
	/** More distinct features than this share one breaker, so the map stays bounded. */
	static final int MAX_FEATURES = 256;
	static final String OTHER_FEATURE = "other";
	/** The outbox and upload jobs ({@code GuardedExecutor.wrap(SYNC_FEATURE, ...)}). */
	public static final String SYNC_FEATURE = "sync";
	/** Features that are never turned off: every upload goes through them. */
	static final Set<String> NEVER_DISABLED = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		SYNC_FEATURE, WebVersionWatcher.GUARD_FEATURE)));
	/** {@code -D} switch the test task sets: rethrow {@link AssertionError} (see the class comment). */
	static final String RETHROW_TEST_FAILURES_PROPERTY = "osrscompanion.guard.rethrowTestFailures";

	private static volatile boolean rethrowTestFailures = Boolean.getBoolean(RETHROW_TEST_FAILURES_PROPERTY);
	/** Tests that must see every swallowed failure (the UI goldens) turn this on. */
	static volatile boolean failTests;

	private static volatile Guard shared = new Guard(System::currentTimeMillis);

	private final LongSupplier clockMs;
	private final Map<String, CircuitBreaker> breakers = new ConcurrentHashMap<>();
	/** Features whose first failure was logged with its stack. */
	private final Map<String, Boolean> logged = new ConcurrentHashMap<>();
	/** Hears once per feature that it is now off for the rest of the session (any thread). */
	private volatile Consumer<String> onDisabled = feature -> {
	};

	Guard(LongSupplier clockMs) {
		this.clockMs = clockMs;
	}

	/** The instance the static methods use. */
	static Guard shared() {
		return shared;
	}

	/** Swaps the shared instance (tests). */
	static void setShared(Guard guard) {
		shared = guard;
	}

	// ------------------------------------------------------------------ static entry points

	public static void run(String feature, Runnable body) {
		shared.runIn(feature, body);
	}

	/** An overlay's render: null (nothing drawn) when it failed or the feature is off. */
	public static Dimension render(String feature, Supplier<Dimension> body) {
		return shared.callIn(feature, body, null);
	}

	public static <T> T call(String feature, Supplier<T> body, T fallback) {
		return shared.callIn(feature, body, fallback);
	}

	/** The task, guarded: for executors and {@code clientThread.invokeLater}. */
	public static Runnable wrap(String feature, Runnable body) {
		return () -> shared.runIn(feature, body);
	}

	/**
	 * A {@code clientThread.invokeLater} poll, guarded. It returns false to run again next tick; when
	 * the feature is off or the body throws it returns true (done), so a broken poll never retries
	 * forever.
	 */
	public static BooleanSupplier wrapBool(String feature, BooleanSupplier body) {
		return () -> shared.callIn(feature, body::getAsBoolean, Boolean.TRUE);
	}

	/**
	 * A clean-up (plugin stop, unregistering what a feature registered), guarded: caught like the others, but it runs even when the feature is off, so nothing is left behind.
	 */
	public static Runnable wrapCleanup(String feature, Runnable body) {
		return () -> shared.callIn(feature, () -> {
			body.run();
			return null;
		}, null, true);
	}

	// The client thread's queue, each task run in its feature's section. The overloads mirror
	// ClientThread's own, so a lambda or method reference picks the same one it picked there.

	public static void invoke(ClientThread clientThread, String feature, Runnable body) {
		clientThread.invoke(wrap(feature, body));
	}

	public static void invoke(ClientThread clientThread, String feature, BooleanSupplier body) {
		clientThread.invoke(wrapBool(feature, body));
	}

	public static void invokeLater(ClientThread clientThread, String feature, Runnable body) {
		clientThread.invokeLater(wrap(feature, body));
	}

	public static void invokeLater(ClientThread clientThread, String feature, BooleanSupplier body) {
		clientThread.invokeLater(wrapBool(feature, body));
	}

	// ------------------------------------------------------------------ instance

	void setOnDisabled(Consumer<String> listener) {
		this.onDisabled = listener == null ? feature -> {
		} : listener;
	}

	/** Turns every feature back on (plugin start: a fresh session). */
	void resetBreakers() {
		breakers.clear();
		logged.clear();
	}

	boolean isDisabled(String feature) {
		CircuitBreaker b = breakers.get(key(feature));
		return b != null && b.isOpen();
	}

	void runIn(String feature, Runnable body) {
		callIn(feature, () -> {
			body.run();
			return null;
		}, null);
	}

	<T> T callIn(String feature, Supplier<T> body, T fallback) {
		return callIn(feature, body, fallback, false);
	}

	/** @param evenIfOff run the body even when the feature is off (clean-ups) */
	<T> T callIn(String feature, Supplier<T> body, T fallback, boolean evenIfOff) {
		CircuitBreaker breaker = breaker(feature);
		if (breaker.isOpen() && !evenIfOff) {
			return fallback;
		}
		try {
			return body.get();
		} catch (ThreadDeath death) {
			throw death;
		} catch (Throwable error) {
			if (isTestFailure(error)) {
				throw (AssertionError) error;
			}
			if (failTests) {
				throw new AssertionError(feature + " failed", error);
			}
			failed(feature, breaker, error);
			return fallback;
		}
	}

	private void failed(String feature, CircuitBreaker breaker, Throwable error) {
		boolean fatal = error instanceof VirtualMachineError;
		try {
			if (logged.putIfAbsent(key(feature), Boolean.TRUE) == null || fatal) {
				log.warn("OSRS Companion: {} failed", feature, error);
			} else {
			}
		} catch (Throwable ignored) {
			// Logging itself failed (out of memory?): the breaker below still works.
		}
		boolean opened = fatal ? breaker.trip() : breaker.recordFailure(clockMs.getAsLong());
		if (opened) {
			disabled(feature, fatal ? "a fatal error" : FAILURE_LIMIT + " errors within a minute");
		}
	}


	private void disabled(String feature, String why) {
		try {
			log.warn("OSRS Companion: {} is turned off for this session after {}", feature, why);
		} catch (Throwable ignored) {
			// see failed()
		}
		notify(() -> onDisabled.accept(feature));
	}

	/** The listener's own failures never escape. */
	private static void notify(Runnable call) {
		try {
			call.run();
		} catch (ThreadDeath death) {
			throw death;
		} catch (Throwable e) {
			if (isTestFailure(e)) {
				throw (AssertionError) e;
			}
			try {
			} catch (Throwable ignored) {
				// nothing left to do
			}
		}
	}

	private CircuitBreaker breaker(String feature) {
		String key = key(feature);
		CircuitBreaker b = breakers.get(key);
		if (b != null) {
			return b;
		}
		boolean exempt = isExempt(key);
		if (breakers.size() >= MAX_FEATURES && !exempt) {
			key = OTHER_FEATURE;
		}
		return breakers.computeIfAbsent(key, k -> new CircuitBreaker(FAILURE_LIMIT, FAILURE_WINDOW_MS, exempt));
	}

	/** True for the features that are never turned off ({@link #NEVER_DISABLED}). */
	static boolean isExempt(String feature) {
		return feature != null && NEVER_DISABLED.contains(feature);
	}

	/** A test's failed assertion, rethrown only while running under tests. */
	private static boolean isTestFailure(Throwable error) {
		return rethrowTestFailures && error instanceof AssertionError;
	}

	/** Tests switch the rethrow off to check the production behaviour (swallow and report). */
	static void setRethrowTestFailures(boolean rethrow) {
		rethrowTestFailures = rethrow;
	}

	static boolean rethrowsTestFailures() {
		return rethrowTestFailures;
	}

	private static String key(String feature) {
		return feature == null ? OTHER_FEATURE : feature;
	}

	/** "slayer-helper-overlay" as the player reads it: "Slayer helper overlay". */
	static String displayName(String feature) {
		if (feature == null || feature.isEmpty()) {
			return "a feature";
		}
		String s = feature.replace('-', ' ');
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.osrscompanion;

import java.util.*;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/**
 * RuneLite's shared executor, with every task of one feature run through {@link Guard}: a task that
 * throws is reported (and counts towards the feature's breaker) instead of silently cancelling a
 * periodic job, and a feature that was turned off stops doing work.
 *
 * The shared executor belongs to RuneLite: {@link #shutdown()} and {@link #shutdownNow()} only cancel
 * this feature's periodic jobs; {@link #cancelAllPeriodic()} (plugin stop) cancels every feature's.
 */
final class GuardedExecutor implements ScheduledExecutorService {
	/** Every periodic job any feature scheduled and has not cancelled, for the plugin's stop. */
	private static final Set<Future<?>> PERIODIC = ConcurrentHashMap.newKeySet();

	private final String feature;
	private final ScheduledExecutorService delegate;
	private final Set<Future<?>> mine = ConcurrentHashMap.newKeySet();

	private GuardedExecutor(String feature, ScheduledExecutorService delegate) {
		this.feature = feature;
		this.delegate = delegate;
	}

	/** The executor with this feature's tasks guarded; null stays null (tests without one). */
	static ScheduledExecutorService wrap(String feature, ScheduledExecutorService executor) {
		if (executor == null || executor instanceof GuardedExecutor && ((GuardedExecutor) executor).feature.equals(feature)) {
			return executor;
		}
		ScheduledExecutorService raw = executor instanceof GuardedExecutor ? ((GuardedExecutor) executor).delegate : executor;
		return new GuardedExecutor(feature, raw);
	}

	/** Cancels every feature's periodic jobs (plugin stop); one-off tasks still run. */
	static void cancelAllPeriodic() {
		for (Future<?> f : PERIODIC) {
			f.cancel(false);
		}
		PERIODIC.clear();
	}

	private Runnable guard(Runnable task) {
		return Guard.wrap(feature, task);
	}

	private <T> Callable<T> guard(Callable<T> task) {
		return () -> Guard.call(feature, () -> {
			try {
				return task.call();
			} catch (RuntimeException e) {
				throw e;
			} catch (Exception e) {
				throw new CompletionException(e);
			}
		}, null);
	}

	private <F extends Future<?>> F periodic(F future) {
		PERIODIC.removeIf(Future::isDone);
		mine.removeIf(Future::isDone);
		PERIODIC.add(future);
		mine.add(future);
		return future;
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
		return delegate.schedule(guard(command), delay, unit);
	}

	@Override
	public <V> ScheduledFuture<V> schedule(Callable<V> callable, long delay, TimeUnit unit) {
		return delegate.schedule(guard(callable), delay, unit);
	}

	@Override
	public ScheduledFuture<?> scheduleAtFixedRate(Runnable command, long initialDelay, long period, TimeUnit unit) {
		return periodic(delegate.scheduleAtFixedRate(guard(command), initialDelay, period, unit));
	}

	@Override
	public ScheduledFuture<?> scheduleWithFixedDelay(Runnable command, long initialDelay, long delay, TimeUnit unit) {
		return periodic(delegate.scheduleWithFixedDelay(guard(command), initialDelay, delay, unit));
	}

	@Override
	public void execute(Runnable command) {
		delegate.execute(guard(command));
	}

	@Override
	public Future<?> submit(Runnable task) {
		return delegate.submit(guard(task));
	}

	@Override
	public <T> Future<T> submit(Runnable task, T result) {
		return delegate.submit(guard(task), result);
	}

	@Override
	public <T> Future<T> submit(Callable<T> task) {
		return delegate.submit(guard(task));
	}

	@Override
	public <T> List<Future<T>> invokeAll(Collection<? extends Callable<T>> tasks) throws InterruptedException {
		return delegate.invokeAll(guardAll(tasks));
	}

	@Override
	public <T> List<Future<T>> invokeAll(Collection<? extends Callable<T>> tasks, long timeout, TimeUnit unit)
		throws InterruptedException {
		return delegate.invokeAll(guardAll(tasks), timeout, unit);
	}

	@Override
	public <T> T invokeAny(Collection<? extends Callable<T>> tasks) throws InterruptedException, ExecutionException {
		return delegate.invokeAny(guardAll(tasks));
	}

	@Override
	public <T> T invokeAny(Collection<? extends Callable<T>> tasks, long timeout, TimeUnit unit)
		throws InterruptedException, ExecutionException, TimeoutException {
		return delegate.invokeAny(guardAll(tasks), timeout, unit);
	}

	private <T> List<Callable<T>> guardAll(Collection<? extends Callable<T>> tasks) {
		List<Callable<T>> out = new ArrayList<>(tasks.size());
		for (Callable<T> t : tasks) {
			out.add(guard(t));
		}
		return out;
	}

	/** Not RuneLite's executor: only this feature's periodic jobs stop. */
	@Override
	public void shutdown() {
		for (Future<?> f : mine) {
			f.cancel(false);
			PERIODIC.remove(f);
		}
		mine.clear();
	}

	@Override
	public List<Runnable> shutdownNow() {
		shutdown();
		return new ArrayList<>();
	}

	@Override
	public boolean isShutdown() {
		return delegate.isShutdown();
	}

	@Override
	public boolean isTerminated() {
		return delegate.isTerminated();
	}

	@Override
	public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
		return delegate.awaitTermination(timeout, unit);
	}
}

package com.osrscompanion;

import com.osrscompanion.model.BankSyncPayload;
import java.util.*;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

/**
 * Shared utilities for collecting and canonicalizing items from RuneLite containers.
 */
final class ItemCollector {
	static final int EMPTY_SLOT_ID = -1;
	private static final int NO_PLACEHOLDER = -1;

	private ItemCollector() {
	}

	/**
	 * Collects items from a container, canonicalizing IDs and merging quantities.
	 * Skips empty slots and items with quantity <= 0.
	 */
	static void collectItems(ItemContainer container, ItemManager itemManager,
			Map<Integer, Integer> itemQuantities) {
		for (Item item : container.getItems()) {
			int itemId = item.getId();
			int quantity = item.getQuantity();

			if (itemId == EMPTY_SLOT_ID || quantity <= 0) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			itemQuantities.merge(canonicalId, quantity, Integer::sum);
		}
	}

	/**
	 * Collects items from a bank container, additionally skipping placeholder items.
	 */
	static void collectBankItems(ItemContainer bankContainer, ItemManager itemManager,
			Map<Integer, Integer> itemQuantities) {
		for (Item item : bankContainer.getItems()) {
			int itemId = item.getId();
			int quantity = item.getQuantity();

			if (itemId == EMPTY_SLOT_ID || quantity <= 0) {
				continue;
			}

			ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp.getPlaceholderTemplateId() != NO_PLACEHOLDER) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			itemQuantities.merge(canonicalId, quantity, Integer::sum);
		}
	}

	/**
	 * Converts an item quantity map into a list of BankItem payload objects, sorted by item ID.
	 * Sorting makes the payload canonical so identical contents always serialize identically,
	 * regardless of container slot order — a reorder alone won't look like a change to dedup.
	 */
	static List<BankSyncPayload.BankItem> toBankItemList(Map<Integer, Integer> itemQuantities) {
		List<BankSyncPayload.BankItem> items = new ArrayList<>();
		itemQuantities.entrySet().stream()
				.sorted(Map.Entry.comparingByKey())
				.forEach(e -> items.add(new BankSyncPayload.BankItem(e.getKey(), e.getValue())));
		return items;
	}
}

package com.osrscompanion;

/**
 * Where an item is, as the website names its sources: "teammate:Bob:worn" (a GIM teammate's worn gear),
 * "teammate:Bob:bank", "group_storage"... Turns a source key into "worn by Bob", "in Bob's inventory",
 * "in Bob's bank" or "in group storage". Pure.
 */
final class ItemWhere {
	static final String TEAMMATE_PREFIX = "teammate:";

	private ItemWhere() {
	}

	/** Whether the key is one of the GIM group's (a teammate's items or the group storage). */
	static boolean isGroup(String key) {
		return key != null && (key.startsWith(TEAMMATE_PREFIX) || "group_storage".equals(key));
	}

	/** The label of a group source key, or null for any other key. */
	static String groupLabel(String key) {
		if (key == null) {
			return null;
		}
		if ("group_storage".equals(key)) {
			return "in group storage";
		}
		if (!key.startsWith(TEAMMATE_PREFIX)) {
			return null;
		}
		String rest = key.substring(TEAMMATE_PREFIX.length());
		int colon = rest.lastIndexOf(':');
		String name = colon < 0 ? rest : rest.substring(0, colon);
		String source = colon < 0 ? "bank" : rest.substring(colon + 1);
		switch (source) {
			case "worn":
				return "worn by " + name;
			case "carried":
				return "carried by " + name;
			case "inventory":
				return "in " + name + "'s inventory";
			case "bank":
			case "bank_deposits":
				return "in " + name + "'s bank";
			default:
				return "in " + name + "'s " + source.replace('_', ' ');
		}
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.KillCountsSyncPayload;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's boss kill counts and syncs them to the OSRS Companion API.
 *
 * <p>Reads RuneLite's persisted {@code killcount} RSProfile config — the store the
 * in-game {@code !kc} command reads, which RuneLite populates from the game's own
 * kill-count chat messages. That makes it the accurate, self-correcting count
 * (unlike loot-tracker-derived KC) and lets us pull the player's whole KC history
 * in one read, instead of waiting to witness a kill.
 *
 * <p>Triggers: a sync on login (after a delay so the RSProfile is resolved) and on
 * logout, plus a near-real-time sync when a kill count changes. RuneLite rewrites
 * the config on each kill, firing {@link ConfigChanged}; we mark a re-check and
 * read + dedupe on the next {@link GameTick} (throttled). A JSON equality check
 * means an unchanged set is never resent.
 */
@Singleton
public class KillCountMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "kill-count-sync";

	private static final String KILLCOUNT_GROUP = "killcount";
	// The RSProfile is set a little after LOGGED_IN, so wait before the first read.
	private static final int LOGIN_SYNC_DELAY_SECONDS = 5;
	private static final int RESYNC_THROTTLE_TICKS = 3;
	// killcount keys that aren't boss KCs (Duel Arena win/loss/streak counters).
	private static final String DUEL_ARENA_PREFIX = "duel arena";

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean kcCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public KillCountMonitor(
			Client client,
			ClientThread clientThread,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ConfigManager configManager,
			ScheduledExecutorService executorService,
			Gson gson) {
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		kcCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the stored kill counts on the client thread. Used by the
	 * roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			lastSyncJson = null;
			syncKillCounts();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				// The RSProfile the kill counts live under is resolved shortly after login.
				executorService.schedule(() -> Guard.invokeLater(clientThread, GUARD_FEATURE, this::syncKillCounts),
						LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
			} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
				// Logging out: flush final state (this handler runs on the client thread).
				syncKillCounts();
			}
			previousGameState = newState;
		});
	}

	/** RuneLite rewrites a killcount config key on each kill; mark a re-check. */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (KILLCOUNT_GROUP.equals(event.getGroup())) {
				kcCheckPending = true;
			}
		});
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!kcCheckPending) {
				return;
			}
			if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
				return;
			}
			kcCheckPending = false;
			lastReadTick = client.getTickCount();
			syncKillCounts();
		});
	}

	/** Reads RuneLite's stored kill counts, builds the payload, and syncs (deduped). */
	private void syncKillCounts() {
		if (!config.syncKillCounts() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}
		String profile = configManager.getRSProfileKey();
		if (profile == null) {
			return;  // RSProfile not resolved yet
		}

		// TreeMap gives a stable JSON key order so the dedup check is reliable.
		Map<String, Integer> killCounts = new TreeMap<>();
		for (String boss : configManager.getRSProfileConfigurationKeys(KILLCOUNT_GROUP, profile, "")) {
			if (boss == null || boss.startsWith(DUEL_ARENA_PREFIX)) {
				continue;
			}
			Integer kc = configManager.getRSProfileConfiguration(KILLCOUNT_GROUP, boss, int.class);
			if (kc != null) {
				killCounts.put(boss, kc);
			}
		}

		if (killCounts.isEmpty()) {
			return;
		}

		KillCountsSyncPayload payload = new KillCountsSyncPayload(playerUsername, killCounts);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			return;
		}
		lastSyncJson = json;
		apiClient.sendKillCountsSync(payload);
	}
}

package com.osrscompanion;

import java.util.*;

/**
 * Live activity, the pure part: which activity the player is doing (from signals the
 * {@link LiveActivityMonitor} reads each tick), when they count as idle, and the region tables for raids
 * and minigames. No game access, so it is unit tested.
 *
 * <p>Priority, first match wins: raid or minigame, boss fight, slayer task, guided farm run, combat with
 * an NPC, skilling (an XP drop in the last minute), banking, then "other" (playing, nothing of the above).
 * Idle (no movement, XP or animation for five minutes) wins over everything but a raid or minigame: a
 * guide or a bank left open while away is not an activity.
 */
final class LiveActivity {
	private LiveActivity() {
	}

	/** No movement, XP or animation for this long: idle. */
	static final long IDLE_MS = 5 * 60_000L;
	/** A skill whose XP went up this recently is what you are training. */
	static final long SKILLING_WINDOW_MS = 60_000L;
	/** Still "in combat" this long after the last attack (between kills, a missed click...). */
	static final long COMBAT_GRACE_MS = 20_000L;
	/** Still at the boss this long after the last attack on it, while in the same map region (between kills). */
	static final long BOSS_GRACE_MS = 90_000L;
	/** A teleport stays the detail this long (a short event: no segment of its own on the website). */
	static final long TELEPORT_SHOW_MS = 60_000L;

	/** The activity kinds the website knows (CharacterActivity.activity). */
	enum Kind {
		RAID("raid"),
		MINIGAME("minigame"),
		BOSS("boss"),
		SLAYER("slayer"),
		FARM_RUN("farm_run"),
		COMBAT("combat"),
		SKILLING("skilling"),
		BANKING("banking"),
		/** Logged in and active, but none of the above (walking, talking, questing...). */
		OTHER("other"),
		IDLE("idle");

		final String wire;

		Kind(String wire) {
			this.wire = wire;
		}
	}

	/** What the monitor saw this tick; null / 0 / false where it saw nothing. */
	static final class Signals {
		String raid;
		String minigame;
		String boss;
		/** The boss NPC's id (the transformed composition's for NPCs that transform), or null. */
		Integer bossId;
		String slayerTask;
		int slayerLeft;
		/** At a task location or fighting the task's monster. */
		boolean slaying;
		String farmRoute;
		int farmDone;
		int farmTotal;
		String combatNpc;
		/** The id of the NPC being fought (the transformed composition's for NPCs that transform), or null. */
		Integer combatNpcId;
		/** Magic XP came with the Hitpoints XP lately: the fight is trained with Magic. */
		boolean combatMagic;
		/** The offensive spell last cast, when known (not with autocast). */
		String combatSpell;
		/** The slayer monster being fought ("Abyssal demon"), for its picture. */
		String slayerNpc;
		/** The id of {@link #slayerNpc}, or null. */
		Integer slayerNpcId;
		/** The farm run's picture: the route's most planted crop ("Ranarr weed"). */
		String farmItem;
		String skill;
		/** The item the skill last gave ("Raw shark", "Gold ring"), when known. */
		String skillItem;
		/** The Magic cast behind the latest Magic XP (an alch, Superheat...), when the skill is Magic. */
		MagicSpells.Cast magicCast;
		/** High / Low Level Alchemy casts this login. */
		int alchs;
		/** A teleport in the last {@link #TELEPORT_SHOW_MS}, newer than other skilling. */
		MagicSpells.Cast teleport;
		boolean bankOpen;
		boolean idle;
	}

	/**
	 * The chosen activity: its kind, what it is about (same subject = same activity), the NPC fought (for its picture)
	 * and the parts the website writes the text and picture from (a slayer task's kills left, the farm run's patches,
	 * the spell, the item...). The NPC id is not part of the key: another version of the same monster is the same
	 * activity.
	 */
	static final class Choice {
		final Kind kind;
		final String subject;
		final Integer npcId;
		final Map<String, Object> parts;

		Choice(Kind kind, String subject, Integer npcId, Map<String, Object> parts) {
			this.kind = kind;
			this.subject = subject;
			this.npcId = npcId;
			// Always sent (also empty): it tells the website to write the text itself.
			// Not Collections.emptyMap(): RuneLite's Gson cannot write it on Java 17+ (it tries to open its private
			// constructor), which turned live activity off for players running the plugin on a newer Java.
			this.parts = parts == null ? new LinkedHashMap<>() : parts;
		}

		/** Two choices with the same key are the same activity (only counts like "12 left" differ). */
		String key() {
			return kind.wire + "|" + (subject == null ? "" : subject);
		}
	}

	private static Map<String, Object> parts(Object... kv) {
		Map<String, Object> m = new LinkedHashMap<>();
		for (int i = 0; i < kv.length; i += 2) {
			if (kv[i + 1] != null) {
				m.put((String) kv[i], kv[i + 1]);
			}
		}
		return m;
	}

	/** The activity for these signals (see the class comment for the order). */
	static Choice choose(Signals s) {
		if (notBlank(s.raid)) {
			return new Choice(Kind.RAID, s.raid, null, null);
		}
		if (notBlank(s.minigame)) {
			return new Choice(Kind.MINIGAME, s.minigame, null, null);
		}
		if (s.idle) {
			return new Choice(Kind.IDLE, null, null, null);
		}
		if (notBlank(s.boss)) {
			return new Choice(Kind.BOSS, s.boss, positive(s.bossId), null);
		}
		if (s.slaying && notBlank(s.slayerTask)) {
			boolean npc = notBlank(s.slayerNpc);
			return new Choice(Kind.SLAYER, s.slayerTask, npc ? positive(s.slayerNpcId) : null,
				parts("left", s.slayerLeft, "npc", npc ? s.slayerNpc : null));
		}
		if (notBlank(s.farmRoute)) {
			return new Choice(Kind.FARM_RUN, s.farmRoute, null,
				parts("done", s.farmDone, "total", s.farmTotal, "item", notBlank(s.farmItem) ? s.farmItem : null));
		}
		if (notBlank(s.combatNpc)) {
			return new Choice(Kind.COMBAT, s.combatNpc, positive(s.combatNpcId),
				s.combatMagic ? parts("magic", true, "spell", notBlank(s.combatSpell) ? s.combatSpell : null) : null);
		}
		if (s.teleport != null) {
			// The Magic skill as subject: teleport after teleport stays one stretch of Magic on the website.
			return new Choice(Kind.SKILLING, "Magic", null, parts("cast", s.teleport));
		}
		if (notBlank(s.skill)) {
			if (s.magicCast != null && "magic".equalsIgnoreCase(s.skill)) {
				return new Choice(Kind.SKILLING, s.magicCast.spell, null, parts("cast", s.magicCast, "alchs", s.alchs));
			}
			return new Choice(Kind.SKILLING, s.skill, null, parts("skill", true, "item", notBlank(s.skillItem) ? s.skillItem : null));
		}
		if (s.bankOpen) {
			return new Choice(Kind.BANKING, null, null, null);
		}
		return new Choice(Kind.OTHER, null, null, null);
	}

	// ---- Idle ---------------------------------------------------------------------------------

	/**
	 * Idle: the local player's tile, XP and animation unchanged for {@link #IDLE_MS}. Someone fishing in
	 * place still gains XP (and animates), so they are not idle. Client thread only.
	 */
	static final class IdleTracker {
		private long lastActiveMs = -1;
		private int x = Integer.MIN_VALUE;
		private int y;
		private int plane;

		/** One tick: where the player stands, whether they animate and whether any XP went up. */
		void tick(long nowMs, int x, int y, int plane, boolean animating, boolean xpGained) {
			boolean moved = x != this.x || y != this.y || plane != this.plane;
			this.x = x;
			this.y = y;
			this.plane = plane;
			if (lastActiveMs < 0 || moved || animating || xpGained) {
				lastActiveMs = nowMs;
			}
		}

		boolean isIdle(long nowMs) {
			return lastActiveMs >= 0 && nowMs - lastActiveMs >= IDLE_MS;
		}

		/** When the player last did something (moved, animated, gained XP); -1 before the first tick. */
		long lastActiveMs() {
			return lastActiveMs;
		}

		void reset() {
			lastActiveMs = -1;
			x = Integer.MIN_VALUE;
		}
	}

	// ---- Skilling -----------------------------------------------------------------------------

	/** Skills whose XP comes from fighting: never "skilling" (combat is detected on its own). */
	private static final Set<String> COMBAT_ONLY = new HashSet<>(Arrays.asList("hitpoints", "slayer"));
	/** Skills that count as skilling only when no Hitpoints XP came in the same tick (alching, chinning...). */
	private static final Set<String> COMBAT_STYLE = new HashSet<>(Arrays.asList("attack", "strength", "defence", "ranged", "magic"));

	/**
	 * Whether an XP drop in this skill is skilling: not Hitpoints or Slayer, and a combat style only when
	 * no Hitpoints XP came with it (a spell cast on a monster gives both).
	 */
	static boolean isSkillingXp(String skill, boolean hitpointsXpSameTick) {
		String k = skill == null ? "" : skill.toLowerCase(Locale.ROOT);
		if (k.isEmpty() || COMBAT_ONLY.contains(k)) {
			return false;
		}
		return !COMBAT_STYLE.contains(k) || !hitpointsXpSameTick;
	}

	/** The skill with the latest skilling XP drop within {@link #SKILLING_WINDOW_MS}, or null. */
	static String skillingSkill(Map<String, Long> lastSkillingXpMs, long nowMs) {
		String best = null;
		long bestAt = Long.MIN_VALUE;
		for (Map.Entry<String, Long> e : lastSkillingXpMs.entrySet()) {
			long at = e.getValue();
			if (nowMs - at <= SKILLING_WINDOW_MS && at > bestAt) {
				best = e.getKey();
				bestAt = at;
			}
		}
		return best;
	}

	// ---- Raids, minigames and bosses ------------------------------------------------------------

	/** Map region (the template region inside instances) -> raid name. Chambers of Xeric and the Theatre also go by varbit. */
	static final Map<Integer, String> RAID_REGIONS = regions("raidRegions");
	/** Map region -> minigame name. The Gauntlet goes by varbit. */
	static final Map<Integer, String> MINIGAME_REGIONS = regions("minigameRegions");

	private static Map<Integer, String> regions(String table) {
		Map<Integer, String> m = new HashMap<>();
		Tables.map(table).forEach((name, regions) -> {
			for (int r : Tables.ids(regions)) {
				m.put(r, name);
			}
		});
		return m;
	}

	/** Boss NPC names (lower case), besides the slayer boss variants and the boss gear catalog. */
	private static final Set<String> BOSSES = Tables.stringSet("bossNames");

	static {
		for (java.util.List<String> names : SlayerBosses.BOSSES.values()) {
			for (String n : names) {
				BOSSES.add(n.toLowerCase(Locale.ROOT));
			}
		}
	}

	/** Whether an NPC is a boss: the list above (with the slayer boss variants) or one of {@code extra} (lower case). */
	static boolean isBoss(String npcName, Set<String> extra) {
		if (npcName == null) {
			return false;
		}
		String n = npcName.trim().toLowerCase(Locale.ROOT);
		return !n.isEmpty() && (BOSSES.contains(n) || extra != null && extra.contains(n));
	}

	// ---- Helpers ------------------------------------------------------------------------------

	/**
	 * The id of the NPC being fought: the transformed composition's id when the NPC transforms (a
	 * multiloc NPC), else its own id. Null when neither is a real id.
	 */
	static Integer npcId(int id, Integer transformedId) {
		if (transformedId != null && transformedId > 0) {
			return transformedId;
		}
		return id > 0 ? id : null;
	}

	private static Integer positive(Integer id) {
		return id != null && id > 0 ? id : null;
	}

	static boolean notBlank(String s) {
		return s != null && !s.trim().isEmpty();
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.BossGear;
import com.osrscompanion.model.FarmRoute;
import com.osrscompanion.model.SlayerGuide;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Live activity: while you are logged in (and "Share live activity" is on, with an App Key), tells the
 * website whether you are online or idle, what you are doing ({@link LiveActivity} picks it), your world
 * and the area. Shown on your home page and the admin page's Activity tab.
 *
 * <ul>
 *   <li>Each tick the status is worked out from what the client already has (a few varbits, your tile,
 *       target and animation, the bank widget, the slayer helper and farm run state). Cheap: no scans.</li>
 *   <li>A change of activity, area or world (or idle on / off) goes out as a priority upload once it held for
 *       {@link #DEBOUNCE_MS}, at most every {@link #MIN_CHANGE_GAP_MS}.</li>
 *   <li>Otherwise the status rides along with every outbox batch, and the {@link WebVersionWatcher} sends
 *       it as a heartbeat when nothing reached the website for {@link #HEARTBEAT_MS}; the website shows you
 *       as offline after about 10 minutes without one. Counts (kills left, patches done) ride along.</li>
 *   <li>Logging out (or stopping the plugin) sends "offline" at once. Switching the setting off sends
 *       nothing more: the website then shows you as offline after its timeout.</li>
 * </ul>
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Slf4j
@Singleton
public class LiveActivityMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "live-activity";

	/** A new activity is sent once it held this long (no flapping between two). */
	static final long DEBOUNCE_MS = 3_000;
	/** At most one change upload this often (the heartbeat still carries the latest). */
	static final long MIN_CHANGE_GAP_MS = 5_000;
	/** The website must hear from the plugin at least this often while you are logged in. */
	static final long HEARTBEAT_MS = 5 * 60_000L;
	/** A cast counts when Magic XP comes within this many ticks of the click. */
	static final int CAST_XP_TICKS = 5;
	/** A teleport counts when you moved far within this many ticks of the click. */
	static final int TELEPORT_TICKS = 12;
	/** Moving at least this many tiles at once (or to another plane) is a teleport. */
	static final int TELEPORT_TILES = 16;

	/** One status, as sent. Immutable: built on the client thread, read by the outbox and the watcher. */
	static final class Status {
		final String player;
		final String state;
		final LiveActivity.Choice choice;
		final long since;
		final int world;
		final String area;
		final int regionId;

		Status(String player, String state, LiveActivity.Choice choice, long since, int world, String area, int regionId) {
			this.player = player;
			this.state = state;
			this.choice = choice;
			this.since = since;
			this.world = world;
			this.area = area;
			this.regionId = regionId;
		}

		/** Same key: the same activity, world and area (count changes ride along with the next upload or heartbeat). */
		String key() {
			return state + "|" + choice.key() + "|" + world + "|" + (area == null ? "" : area);
		}

		Map<String, Object> body() {
			Map<String, Object> b = new LinkedHashMap<>();
			b.put("player_username", player);
			b.put("state", state);
			b.put("activity", choice.kind.wire);
			b.put("subject", choice.subject);
			b.put("npc_id", choice.npcId);
			// The website writes the text and picture from these.
			b.put("parts", choice.parts);
			b.put("since", since);
			b.put("world", world);
			b.put("area", area);
			b.put("region_id", regionId);
			b.put("plugin_version", PluginVersion.VERSION);
			return b;
		}
	}

	private final Client client;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final Gson gson;
	private final SlayerHelperManager slayerHelper;
	private final FarmRunManager farmRun;
	private final BossGearManager bossGear;

	// Read by the outbox and the watcher (other threads).
	private volatile Status current;
	private volatile boolean sharing;

	// Client thread only.
	private final LiveActivity.IdleTracker idle = new LiveActivity.IdleTracker();
	private final Map<String, Integer> lastXp = new HashMap<>();
	private final Map<String, Long> lastSkillingXpMs = new HashMap<>();
	/** XP gains not yet sorted into skilling or combat: skill, tick. */
	private final List<Object[]> pendingXp = new ArrayList<>();
	private int lastHitpointsXpTick = -1;
	private boolean xpGainedSinceTick;
	private String combatNpc;
	private Integer combatNpcId;
	private long combatAtMs;
	private String bossNpc;
	private Integer bossNpcId;
	private int bossRegion;
	private long bossAtMs;
	private String activityKey;
	private long activitySinceMs;
	private List<BossGear.CatalogBoss> catalogSeen;
	private Set<String> catalogBosses = Collections.emptySet();
	// Magic: the last "Cast" / "Break" click, the cast confirmed by Magic XP and the last teleport.
	private MagicSpells.Cast pendingCast;
	private int pendingCastTick;
	private MagicSpells.Cast lastCast;
	private long lastCastMs;
	private MagicSpells.Cast teleport;
	private long teleportMs;
	private int alchs;
	private long combatMagicMs;
	private WorldPoint lastAt;
	// Skilling items: inventory counts, and the item a skill last gave.
	private Map<Integer, Integer> lastInventory;
	private int gainedItem = -1;
	private int gainedTick = -1;
	private final Map<String, String> skillItem = new HashMap<>();
	private FarmRoute farmItemRoute;
	private String farmItem;

	// Sending (client thread, the outbox's and the watcher's).
	private String lastSentKey;
	private String pendingKey;
	private long pendingSinceMs;
	private long lastChangeSentMs;
	/** The player a status was sent for this login; an offline status goes out for them at logout. */
	private String sentFor;

	/** Every outbox batch carries the current status from now on. */
	public void start() {
		apiClient.setActivitySource(() -> Guard.call(GUARD_FEATURE, this::statusForBatch, null));
	}

	/** Plugin stop: "offline" for the player (queued before the outbox's last flush), and no more statuses. */
	public void stop() {
		apiClient.setActivitySource(null);
		Guard.run(GUARD_FEATURE, this::sendOffline);
		current = null;
	}

	// ---- Events ---------------------------------------------------------------------------------

	@Subscribe
	public void onGameTick(GameTick e) {
		Guard.run(GUARD_FEATURE, this::tick);
	}

	@Subscribe
	public void onStatChanged(StatChanged e) {
		Guard.run(GUARD_FEATURE, () -> {
			String skill = e.getSkill().getName().toLowerCase(Locale.ROOT);
			Integer previous = lastXp.put(skill, e.getXp());
			// The first value after login is the server's replay, not a gain.
			if (previous == null || e.getXp() <= previous) {
				return;
			}
			xpGainedSinceTick = true;
			int tick = client.getTickCount();
			if ("hitpoints".equals(skill)) {
				lastHitpointsXpTick = tick;
			}
			pendingXp.add(new Object[]{skill, tick});
		});
	}

	/** A "Cast" (spell widget, or a selected spell used on an item / NPC) or a tablet's "Break": remembered until XP or a jump confirms it. */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e) {
		Guard.run(GUARD_FEATURE, () -> {
			String option = e.getMenuOption();
			if (option == null || !(option.contains("Cast") || option.contains("Break"))) {
				return;
			}
			MagicSpells.Cast cast = MagicSpells.fromMenu(option, e.getMenuTarget(), e.getMenuAction() == MenuAction.WIDGET_TARGET_ON_NPC);
			if (cast != null) {
				pendingCast = cast;
				pendingCastTick = client.getTickCount();
			}
		});
	}

	/** The inventory item that went up (what a skill gave), noted items as themselves. Not while banking. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (e.getContainerId() != InventoryID.INV) {
				return;
			}
			ItemContainer inv = e.getItemContainer();
			Map<Integer, Integer> counts = new HashMap<>();
			if (inv != null) {
				for (Item item : inv.getItems()) {
					if (item != null && item.getId() > 0) {
						counts.merge(item.getId(), item.getQuantity(), Integer::sum);
					}
				}
			}
			Map<Integer, Integer> before = lastInventory;
			lastInventory = counts;
			if (before == null || client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null) {
				return;
			}
			for (Map.Entry<Integer, Integer> c : counts.entrySet()) {
				if (c.getValue() > before.getOrDefault(c.getKey(), 0)) {
					gainedItem = c.getKey();
					gainedTick = client.getTickCount();
					return;
				}
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.LOGIN_SCREEN_AUTHENTICATOR) {
				sendOffline();
				reset();
			}
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e) {
		Guard.run(GUARD_FEATURE, () -> {
			if (OSRSCompanionConfig.CONFIG_GROUP.equals(e.getGroup()) && OSRSCompanionConfig.SHARE_LIVE_ACTIVITY_KEY.equals(e.getKey())) {
				// Switched back on: the next tick sends the status at once.
				synchronized (this) {
					lastSentKey = null;
				}
			}
		});
	}

	// ---- The status -----------------------------------------------------------------------------

	private void tick() {
		Player local = client.getLocalPlayer();
		String player = SyncGuard.getPlayerUsername(client);
		if (client.getGameState() != GameState.LOGGED_IN || local == null || player == null) {
			return;
		}
		long now = System.currentTimeMillis();
		int tick = client.getTickCount();
		WorldPoint at = local.getLocalLocation() == null ? local.getWorldLocation() : WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		int region = at == null ? -1 : at.getRegionID();

		sortXp(now, tick);
		checkTeleport(at, now, tick);
		idle.tick(now, at == null ? 0 : at.getX(), at == null ? 0 : at.getY(), at == null ? 0 : at.getPlane(),
			local.getAnimation() != -1, xpGainedSinceTick);
		xpGainedSinceTick = false;

		LiveActivity.Signals s = new LiveActivity.Signals();
		readRaid(s, region);
		readTarget(s, local, now, region);
		readSlayer(s);
		readFarmRun(s);
		s.skill = LiveActivity.skillingSkill(lastSkillingXpMs, now);
		readMagic(s, now);
		s.bankOpen = client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null;
		s.idle = idle.isIdle(now);
		LiveActivity.Choice choice = LiveActivity.choose(s);

		String key = choice.key();
		if (!key.equals(activityKey)) {
			activityKey = key;
			activitySinceMs = choice.kind == LiveActivity.Kind.IDLE && idle.lastActiveMs() > 0 ? idle.lastActiveMs() : now;
		}
		String state = s.idle ? "idle" : "online";
		String area = s.raid != null ? s.raid : s.minigame != null ? s.minigame : areaName(at, region);
		Status status = new Status(player, state, choice, activitySinceMs, client.getWorld(), area, region);
		current = status;
		sharing = config.shareLiveActivity() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client);
		if (sharing) {
			maybeSendChange(status, now);
		}
	}

	/**
	 * XP gains since the last tick: skilling ones are remembered per skill (see {@link LiveActivity#isSkillingXp}),
	 * with the item that came with them; Magic XP confirms the last cast (and counts an alch).
	 */
	private void sortXp(long now, int tick) {
		for (Object[] gain : pendingXp) {
			String skill = (String) gain[0];
			int at = (int) gain[1];
			boolean withHitpoints = at == lastHitpointsXpTick;
			if ("magic".equals(skill)) {
				if (withHitpoints) {
					combatMagicMs = now;
				}
				MagicSpells.Cast cast = pendingCast;
				if (cast != null && cast.type != MagicSpells.Type.TELEPORT && at - pendingCastTick <= CAST_XP_TICKS) {
					if (lastCast != cast && (cast.type == MagicSpells.Type.HIGH_ALCH || cast.type == MagicSpells.Type.LOW_ALCH)) {
						alchs++;
					}
					lastCast = cast;
					lastCastMs = now;
				}
			}
			if (LiveActivity.isSkillingXp(skill, withHitpoints)) {
				lastSkillingXpMs.put(skill, now);
				if (!"magic".equals(skill) && gainedItem > 0 && Math.abs(at - gainedTick) <= 1) {
					String name = itemName(gainedItem);
					if (name != null) {
						skillItem.put(skill, name);
					}
				}
			}
		}
		pendingXp.clear();
	}

	/** A teleport click followed by a long jump (or a plane change) within {@link #TELEPORT_TICKS}: you teleported. */
	private void checkTeleport(WorldPoint at, long now, int tick) {
		WorldPoint before = lastAt;
		lastAt = at;
		MagicSpells.Cast cast = pendingCast;
		if (cast == null || cast.type != MagicSpells.Type.TELEPORT || at == null || before == null) {
			return;
		}
		if (tick - pendingCastTick > TELEPORT_TICKS) {
			pendingCast = null;
			return;
		}
		if (before.getPlane() != at.getPlane() || Math.max(Math.abs(before.getX() - at.getX()), Math.abs(before.getY() - at.getY())) >= TELEPORT_TILES) {
			teleport = cast;
			teleportMs = now;
			pendingCast = null;
		}
	}

	/** Magic signals: training Magic in a fight, the cast behind skilling Magic, a teleport shown for a minute. */
	private void readMagic(LiveActivity.Signals s, long now) {
		s.combatMagic = s.combatNpc != null && now - combatMagicMs <= LiveActivity.COMBAT_GRACE_MS;
		if (s.combatMagic && lastCast != null && lastCast.type == MagicSpells.Type.OFFENSIVE && now - lastCastMs <= LiveActivity.COMBAT_GRACE_MS) {
			s.combatSpell = lastCast.spell;
		}
		s.alchs = alchs;
		if (s.skill != null) {
			s.skillItem = skillItem.get(s.skill);
		}
		if (lastCast != null && now - lastCastMs <= LiveActivity.SKILLING_WINDOW_MS) {
			s.magicCast = lastCast;
		}
		if (teleport != null && now - teleportMs <= LiveActivity.TELEPORT_SHOW_MS) {
			// Only while nothing else was trained since (a skill's XP after the teleport wins).
			Long other = s.skill == null || "magic".equals(s.skill) ? null : lastSkillingXpMs.get(s.skill);
			if (other == null || other <= teleportMs) {
				s.teleport = teleport;
			}
		} else {
			teleport = null;
		}
	}

	/** An item's name (a noted item as the item), or null. Client thread. */
	private String itemName(int id) {
		ItemComposition c = client.getItemDefinition(id);
		if (c != null && c.getNote() != -1) {
			c = client.getItemDefinition(c.getLinkedNoteId());
		}
		String name = c == null ? null : c.getName();
		return name == null || name.isEmpty() || "null".equalsIgnoreCase(name) ? null : name;
	}

	private void readRaid(LiveActivity.Signals s, int region) {
		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1) {
			s.raid = "Chambers of Xeric";
		} else if (client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS) >= 2) {
			s.raid = "Theatre of Blood";
		} else {
			s.raid = LiveActivity.RAID_REGIONS.get(region);
		}
		if (s.raid == null) {
			s.minigame = LiveActivity.MINIGAME_REGIONS.get(region);
			if (s.minigame == null && client.getVarbitValue(VarbitID.PLAYER_IN_GAUNTLET) == 1) {
				s.minigame = "The Gauntlet";
			}
		}
	}

	/** Combat and boss fights: who you attack, kept for a short grace between kills. */
	private void readTarget(LiveActivity.Signals s, Player local, long now, int region) {
		Actor target = local.getInteracting();
		if (target instanceof NPC && ((NPC) target).getCombatLevel() > 0 && target.getName() != null) {
			String name = target.getName();
			Integer id = npcId((NPC) target);
			combatNpc = name;
			combatNpcId = id;
			combatAtMs = now;
			if (LiveActivity.isBoss(name, catalogBosses())) {
				bossNpc = name;
				bossNpcId = id;
				bossAtMs = now;
				bossRegion = region;
			}
		}
		if (bossNpc != null && now - bossAtMs <= LiveActivity.BOSS_GRACE_MS && region == bossRegion) {
			s.boss = bossNpc;
			s.bossId = bossNpcId;
		} else {
			bossNpc = null;
			bossNpcId = null;
		}
		if (combatNpc != null && now - combatAtMs <= LiveActivity.COMBAT_GRACE_MS) {
			s.combatNpc = combatNpc;
			s.combatNpcId = combatNpcId;
		} else {
			combatNpc = null;
			combatNpcId = null;
		}
	}

	/** The NPC's id: the transformed composition's for NPCs that transform, else its own. */
	private static Integer npcId(NPC npc) {
		NPCComposition t = npc.getTransformedComposition();
		return LiveActivity.npcId(npc.getId(), t == null ? null : t.getId());
	}

	private void readSlayer(LiveActivity.Signals s) {
		SlayerHelperManager.Task task = slayerHelper.getTask();
		if (task == null || task.remaining <= 0) {
			return;
		}
		s.slayerTask = task.displayName();
		s.slayerLeft = task.remaining;
		boolean onTarget = s.combatNpc != null && slayerHelper.isTaskTarget(s.combatNpc);
		s.slaying = slayerHelper.getHere() != null || onTarget;
		if (onTarget) {
			s.slayerNpc = s.combatNpc;
			s.slayerNpcId = s.combatNpcId;
		}
	}

	private void readFarmRun(LiveActivity.Signals s) {
		FarmRoute route = farmRun.isRunning() ? farmRun.getRoute() : null;
		if (route == null) {
			return;
		}
		s.farmRoute = LiveActivity.notBlank(route.getName()) ? route.getName() : "Farm run";
		int[] progress = farmRun.progress();
		s.farmDone = progress[0];
		s.farmTotal = progress[1];
		if (route != farmItemRoute) {
			farmItemRoute = route;
			Integer item = route.pictureItem();
			farmItem = item == null ? null : itemName(item);
		}
		s.farmItem = farmItem;
	}

	/** The area's name from the slayer guide's locations; null when unknown (the website names the region). */
	private String areaName(WorldPoint at, int region) {
		if (at == null) {
			return null;
		}
		SlayerGuide.Location here = slayerHelper.getHere();
		if (here != null && LiveActivity.notBlank(here.getName())) {
			return here.getName();
		}
		for (SlayerGuide.Location l : slayerHelper.guideLocations()) {
			if (l != null && LiveActivity.notBlank(l.getName()) && l.contains(at.getX(), at.getY(), at.getPlane(), region)) {
				return l.getName();
			}
		}
		return null;
	}

	/** The boss gear catalog's boss names (lower case), rebuilt when the catalog changes. */
	private Set<String> catalogBosses() {
		List<BossGear.CatalogBoss> catalog = bossGear.getCatalog();
		if (catalog != catalogSeen) {
			catalogSeen = catalog;
			Set<String> names = new HashSet<>();
			if (catalog != null) {
				for (BossGear.CatalogBoss b : catalog) {
					if (b != null && b.getName() != null) {
						names.add(b.getName().trim().toLowerCase(Locale.ROOT));
					}
				}
			}
			catalogBosses = names;
		}
		return catalogBosses;
	}

	// ---- Sending ----------------------------------------------------------------------------------

	/** Whether a change goes out now: it held {@link #DEBOUNCE_MS} and the last one is {@link #MIN_CHANGE_GAP_MS} ago. */
	static boolean shouldSendChange(String key, String lastSentKey, String pendingKey, long pendingSinceMs,
			long lastChangeSentMs, long nowMs) {
		if (key.equals(lastSentKey)) {
			return false;
		}
		if (lastSentKey == null) {
			return true;
		}
		return key.equals(pendingKey) && nowMs - pendingSinceMs >= DEBOUNCE_MS && nowMs - lastChangeSentMs >= MIN_CHANGE_GAP_MS;
	}

	private synchronized void maybeSendChange(Status status, long now) {
		String key = status.key();
		if (key.equals(lastSentKey)) {
			pendingKey = null;
			return;
		}
		if (!key.equals(pendingKey)) {
			pendingKey = key;
			pendingSinceMs = now;
		}
		if (shouldSendChange(key, lastSentKey, pendingKey, pendingSinceMs, lastChangeSentMs, now)) {
			lastChangeSentMs = now;
			send(status, true);
		}
	}

	/** True while there is a status to share: logged in, the setting on, an App Key, a normal world. */
	public boolean isSharing() {
		return sharing && current != null && client.getGameState() != GameState.LOGIN_SCREEN;
	}

	/** The heartbeat (the watcher, when nothing reached the website lately): the current status, at once. */
	public void heartbeat() {
		Guard.run(GUARD_FEATURE, () -> {
			Status s = current;
			if (s != null && isSharing()) {
				send(s, true);
			}
		});
	}

	/** The status for a batch about to go out (it then counts as sent), or null. Any thread. */
	private synchronized String statusForBatch() {
		Status s = current;
		if (s == null || !isSharing()) {
			return null;
		}
		lastSentKey = s.key();
		sentFor = s.player;
		return gson.toJson(s.body());
	}

	private synchronized void send(Status s, boolean priority) {
		lastSentKey = s.key();
		sentFor = s.player;
		apiClient.sendActivity(s.player, gson.toJson(s.body()), priority);
	}

	/** Logout or plugin stop: "offline" for the player a status was sent for, at once. */
	private synchronized void sendOffline() {
		String player = sentFor;
		sentFor = null;
		lastSentKey = null;
		current = null;
		if (player == null || !config.shareLiveActivity() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		Map<String, Object> b = new LinkedHashMap<>();
		b.put("player_username", player);
		b.put("state", "offline");
		b.put("activity", "offline");
		b.put("since", System.currentTimeMillis());
		b.put("plugin_version", PluginVersion.VERSION);
		apiClient.sendActivity(player, gson.toJson(b), true);
	}

	private void reset() {
		idle.reset();
		lastXp.clear();
		lastSkillingXpMs.clear();
		pendingXp.clear();
		lastHitpointsXpTick = -1;
		xpGainedSinceTick = false;
		combatNpc = null;
		combatNpcId = null;
		bossNpc = null;
		bossNpcId = null;
		pendingCast = null;
		lastCast = null;
		teleport = null;
		alchs = 0;
		combatMagicMs = 0;
		lastAt = null;
		lastInventory = null;
		gainedItem = -1;
		skillItem.clear();
		farmItemRoute = null;
		farmItem = null;
		activityKey = null;
		sharing = false;
		synchronized (this) {
			pendingKey = null;
			lastChangeSentMs = 0;
		}
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.LoadoutSyncPayload;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class LoadoutMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "loadout-sync";

	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	private static final int EQUIPMENT_CHANGE_DEBOUNCE_SECONDS = 15;
	private static final int EMPTY_SLOT_ID = -1;
	private static final int MAX_INVENTORY_SLOTS = 28;

	private static final String INVENTORY_SETUPS_CONFIG_GROUP = "inventorysetups";
	private static final String SETUPS_V3_PREFIX = "setupsV3_";

	private static final Map<Integer, String> EQUIPMENT_SLOT_MAP = new HashMap<>();

	static {
		Tables.map("loadoutSlots").forEach((slot, key) -> EQUIPMENT_SLOT_MAP.put(Integer.parseInt(slot), key.getAsString()));
	}

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private ScheduledFuture<?> debounceFuture = null;
	private String lastSyncJson = null;

	@Inject
	public LoadoutMonitor(
			Client client,
			ClientThread clientThread,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ScheduledExecutorService executorService,
			ConfigManager configManager,
			ItemManager itemManager,
			Gson gson) {
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
	}

	public void stop() {
		if (debounceFuture != null) {
			debounceFuture.cancel(false);
			debounceFuture = null;
		}
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	/**
	 * Re-runs the loadout sync immediately (on the client thread, since it reads
	 * item containers), forcing a resend by clearing the change-detection
	 * snapshot. Used by the roadmap panel's "Sync &amp; refresh" button.
	 */
	public void forceSync() {
		executorService.execute(() -> Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			lastSyncJson = null;
			syncLoadouts();
		}));
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!config.syncLoadouts()) {
				return;
			}

			GameState newState = event.getGameState();

			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				executorService.schedule(() -> Guard.invokeLater(clientThread, GUARD_FEATURE, this::syncLoadouts),
						LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
			} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
				syncLoadouts();
			}

			previousGameState = newState;
		});
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			int containerId = event.getContainerId();
			if (containerId != InventoryID.WORN && containerId != InventoryID.INV) {
				return;
			}

			if (!config.syncLoadouts()) {
				return;
			}

			if (debounceFuture != null) {
				debounceFuture.cancel(false);
			}
			debounceFuture = executorService.schedule(() -> Guard.invokeLater(clientThread, GUARD_FEATURE, this::syncLoadouts),
					EQUIPMENT_CHANGE_DEBOUNCE_SECONDS, TimeUnit.SECONDS);
		});
	}

	/**
	 * Builds the full loadout payload (active gear + Inventory Setups) and sends
	 * it to the OSRS Companion API if the contents changed since the last sync.
	 */
	private void syncLoadouts() {
		if (!SyncGuard.hasAppKey(config)) {
			return;
		}
		if (!config.syncLoadouts()) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Loadout sync skipped: could not get player username");
			return;
		}

		List<LoadoutSyncPayload.LoadoutSet> loadoutSets = new ArrayList<>();

		LoadoutSyncPayload.LoadoutSet activeGear = buildActiveGearLoadout();
		if (activeGear != null) {
			loadoutSets.add(activeGear);
		}

		loadoutSets.addAll(buildInventorySetups());

		LoadoutSyncPayload payload = new LoadoutSyncPayload(playerUsername, loadoutSets);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			return;
		}

		lastSyncJson = json;
		apiClient.sendLoadoutSync(payload);
	}

	/**
	 * Reads the player's currently worn equipment and inventory, returning them
	 * as an "active_gear" loadout set. Returns null if both are empty.
	 */
	private LoadoutSyncPayload.LoadoutSet buildActiveGearLoadout() {
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null) {
			return null;
		}

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseEquipmentSlots(equipment.getItems());

		List<LoadoutSyncPayload.InventoryItem> inventoryItems = new ArrayList<>();
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null) {
			Item[] invItems = inventory.getItems();
			for (int i = 0; i < invItems.length && i < MAX_INVENTORY_SLOTS; i++) {
				Item item = invItems[i];
				if (item.getId() == EMPTY_SLOT_ID || item.getQuantity() <= 0) {
					continue;
				}
				int canonicalId = itemManager.canonicalize(item.getId());
				inventoryItems.add(new LoadoutSyncPayload.InventoryItem(canonicalId, i));
			}
		}

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(
				"Current Gear", "active_gear", null,
				equipmentItems, inventoryItems);
	}

	private List<LoadoutSyncPayload.EquipmentItem> parseEquipmentSlots(Item[] items) {
		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = new ArrayList<>();
		for (int i = 0; i < items.length; i++) {
			String slot = EQUIPMENT_SLOT_MAP.get(i);
			if (slot == null) {
				continue;
			}
			Item item = items[i];
			if (item.getId() == EMPTY_SLOT_ID || item.getQuantity() <= 0) {
				continue;
			}
			int canonicalId = itemManager.canonicalize(item.getId());
			equipmentItems.add(new LoadoutSyncPayload.EquipmentItem(canonicalId, slot));
		}
		return equipmentItems;
	}

	/**
	 * Reads saved Inventory Setups from ConfigManager. Tries V3 format first,
	 * falling back to legacy V2/V1 formats if V3 is unavailable.
	 */
	private List<LoadoutSyncPayload.LoadoutSet> buildInventorySetups() {
		List<LoadoutSyncPayload.LoadoutSet> setups = new ArrayList<>();

		if (tryLoadV3Setups(setups)) {
			return setups;
		}

		loadLegacySetups(setups);
		return setups;
	}

	/**
	 * Attempts to load Inventory Setups using the V3 per-setup key format.
	 * Returns true if V3 keys were found (even if parsing individual setups fails).
	 */
	private boolean tryLoadV3Setups(List<LoadoutSyncPayload.LoadoutSet> setups) {
		try {
			String wholePrefix = ConfigManager.getWholeKey(INVENTORY_SETUPS_CONFIG_GROUP, null, SETUPS_V3_PREFIX);
			List<String> v3Keys = configManager.getConfigurationKeys(wholePrefix);
			if (v3Keys == null || v3Keys.isEmpty()) {
				return false;
			}

			Map<String, String> sectionMap = loadSectionMap();

			for (String fullKey : v3Keys) {
				String configKey = fullKey.substring(INVENTORY_SETUPS_CONFIG_GROUP.length() + 1);
				String setupJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, configKey);
				if (setupJson == null || setupJson.isBlank()) {
					continue;
				}
				try {
					JsonObject setup = gson.fromJson(setupJson, JsonObject.class);
					LoadoutSyncPayload.LoadoutSet loadoutSet = parseInventorySetupV3(setup, sectionMap);
					if (loadoutSet != null) {
						setups.add(loadoutSet);
					}
				} catch (Exception e) {
				}
			}
			return true;
		} catch (Exception e) {
			return false;
		}
	}

	/**
	 * Loads Inventory Setups from legacy V2 or V1 single-array config format.
	 */
	private void loadLegacySetups(List<LoadoutSyncPayload.LoadoutSet> setups) {
		String setupsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "setupsV2");
		if (setupsJson == null || setupsJson.isBlank()) {
			setupsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "setups");
		}
		if (setupsJson == null || setupsJson.isBlank()) {
			return;
		}

		try {
			JsonArray setupsArray = gson.fromJson(setupsJson, JsonArray.class);
			for (JsonElement element : setupsArray) {
				JsonObject setup = element.getAsJsonObject();
				LoadoutSyncPayload.LoadoutSet loadoutSet = parseLegacySetup(setup);
				if (loadoutSet != null) {
					setups.add(loadoutSet);
				}
			}
		} catch (Exception e) {
			log.warn("Failed to parse Inventory Setups data: {}", e.getMessage());
		}
	}

	/**
	 * Reads the Inventory Setups sections config and builds a map of
	 * setup name to section/category name for folder grouping.
	 */
	private Map<String, String> loadSectionMap() {
		Map<String, String> sectionMap = new HashMap<>();
		try {
			String sectionsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "sections");
			if (sectionsJson != null && !sectionsJson.isBlank()) {
				JsonArray sections = gson.fromJson(sectionsJson, JsonArray.class);
				for (JsonElement sectionEl : sections) {
					JsonObject section = sectionEl.getAsJsonObject();
					String sectionName = section.has("name") ? section.get("name").getAsString() : null;
					if (sectionName != null && section.has("setups")) {
						JsonArray setupNames = section.getAsJsonArray("setups");
						for (JsonElement nameEl : setupNames) {
							sectionMap.put(nameEl.getAsString(), sectionName);
						}
					}
				}
			}
		} catch (Exception e) {
		}
		return sectionMap;
	}

	private LoadoutSyncPayload.LoadoutSet parseInventorySetupV3(JsonObject setup, Map<String, String> sectionMap) {
		String name = getJsonString(setup, "name", "Unnamed Setup");
		String category = sectionMap.getOrDefault(name, null);

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseJsonEquipmentArray(setup, "eq");
		List<LoadoutSyncPayload.InventoryItem> inventoryItems = parseJsonInventoryArray(setup, "inv");

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(name, "inventory_setup", category, equipmentItems, inventoryItems);
	}

	private LoadoutSyncPayload.LoadoutSet parseLegacySetup(JsonObject setup) {
		String name = getJsonString(setup, "name", "Unnamed Setup");

		String category = null;
		if (setup.has("stackName") && !setup.get("stackName").isJsonNull()) {
			category = setup.get("stackName").getAsString();
		}

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseJsonEquipmentArray(setup, "equipment");
		List<LoadoutSyncPayload.InventoryItem> inventoryItems = parseJsonInventoryArray(setup, "inventory");

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(name, "inventory_setup", category, equipmentItems, inventoryItems);
	}

	/**
	 * Parses a JSON array of equipment items from the given field, mapping each
	 * slot index to a named equipment slot via EQUIPMENT_SLOT_MAP.
	 */
	private List<LoadoutSyncPayload.EquipmentItem> parseJsonEquipmentArray(JsonObject setup, String fieldName) {
		List<LoadoutSyncPayload.EquipmentItem> items = new ArrayList<>();
		if (!setup.has(fieldName) || setup.get(fieldName).isJsonNull()) {
			return items;
		}

		JsonArray array = setup.getAsJsonArray(fieldName);
		for (int i = 0; i < array.size(); i++) {
			if (array.get(i).isJsonNull()) {
				continue;
			}
			JsonObject eq = array.get(i).getAsJsonObject();
			int itemId = eq.has("id") ? eq.get("id").getAsInt() : EMPTY_SLOT_ID;
			if (itemId <= 0) {
				continue;
			}

			String slot = EQUIPMENT_SLOT_MAP.get(i);
			if (slot == null) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			items.add(new LoadoutSyncPayload.EquipmentItem(canonicalId, slot));
		}
		return items;
	}

	/**
	 * Parses a JSON array of inventory items from the given field, preserving
	 * each item's slot index position.
	 */
	private List<LoadoutSyncPayload.InventoryItem> parseJsonInventoryArray(JsonObject setup, String fieldName) {
		List<LoadoutSyncPayload.InventoryItem> items = new ArrayList<>();
		if (!setup.has(fieldName) || setup.get(fieldName).isJsonNull()) {
			return items;
		}

		JsonArray array = setup.getAsJsonArray(fieldName);
		for (int i = 0; i < array.size(); i++) {
			if (array.get(i).isJsonNull()) {
				continue;
			}
			JsonObject inv = array.get(i).getAsJsonObject();
			int itemId = inv.has("id") ? inv.get("id").getAsInt() : EMPTY_SLOT_ID;
			if (itemId <= 0) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			items.add(new LoadoutSyncPayload.InventoryItem(canonicalId, i));
		}
		return items;
	}

	private String getJsonString(JsonObject obj, String key, String defaultValue) {
		return obj.has(key) ? obj.get(key).getAsString() : defaultValue;
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.LootDropPayload;
import com.osrscompanion.model.LootSyncPayload;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
