import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
@Singleton
public class LootMonitor
{
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "loot-sync";

	private static final int PROFILE_SYNC_DELAY_SECONDS = 5;
	private static final int FLUSH_INTERVAL_SECONDS = 180;
	private static final String LOOT_TRACKER_CONFIG_GROUP = "loottracker";
	private static final String LOOT_TRACKER_DROPS_PREFIX = "drops_";
	private static final String LAST_SYNC_HASH_KEY = "lootSyncHash";
	private static final String LOOT_PAYLOAD_VERSION = "v2-kill-times";

	private final Client client;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	/** Persistent client identifier unique to this RuneLite installation. */
	private String clientId;
	/** Tracks cumulative kill counts per NPC name for the current session. */
	private final Map<String, Integer> sessionKillCounts = new LinkedHashMap<>();
	/** Queued loot drops waiting to be flushed to the API. */
	private final List<LootDropPayload> pendingDrops = new ArrayList<>();
	/** Caches NPC name -> NPC ID from NpcLootReceived events (fires before LootReceived). */
	private final Map<String, Integer> recentNpcIds = new LinkedHashMap<>();
	private ScheduledFuture<?> flushTask;
	/** Uploads a notable drop right away instead of waiting for the next timed flush. */
	private final NotableLootFlusher notableFlusher;
	/** MD5 hash of the last successfully synced loot data, used to skip redundant syncs. */
	private String lastSyncHash;

	@Inject
	public LootMonitor(
		Client client,
		OSRSCompanionConfig config,
		OSRSCompanionApiClient apiClient,
		ScheduledExecutorService executorService,
		ClientThread clientThread,
		ConfigManager configManager,
		ItemManager itemManager,
		Gson gson)
	{
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
		this.notableFlusher = new NotableLootFlusher(executorService, this::flushDrops);
	}

	public void start()
	{
		// Read or generate a persistent client ID (per-machine, not per RS profile).
		clientId = configManager.getConfiguration("osrscompanion", "clientId");
		if (clientId == null || clientId.isEmpty())
		{
			clientId = UUID.randomUUID().toString();
			configManager.setConfiguration("osrscompanion", "clientId", clientId);
		}

		flushTask = executorService.scheduleAtFixedRate(
			this::flushAndSyncTotals, FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * Every few minutes: uploads the queued drops, then the loot tracker totals when they
	 * changed (the hash check skips unchanged ones), so the website's all-time list keeps
	 * up while you play instead of only after logging out.
	 */
	private void flushAndSyncTotals()
	{
		flushDrops();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			syncLoot();
		}
	}

	/** Receives every loot drop the monitor queues for upload (set by the plugin). */
	public interface DropListener
	{
		void onDrop(int npcId, String npcName, int kills, List<LootSyncPayload.LootItem> items);
	}

	public void stop()
	{
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
		notableFlusher.cancel();
		flushDrops();
		previousGameState = GameState.UNKNOWN;
		sessionKillCounts.clear();
		recentNpcIds.clear();
		lastSyncHash = null;
	}

	/**
	 * Re-runs the loot sync immediately on the background executor, forcing a
	 * resend by clearing the change-detection hash. Used by the roadmap panel's
	 * "Sync &amp; refresh" button.
	 */
	public void forceSync()
	{
		executorService.execute(() ->
		{
			lastSyncHash = null;
			syncLoot();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();

			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
			{
				// Use clientThread.invokeLater to poll each tick until the RS profile
				// key is available. Returns false to retry, true when done.
				Guard.invokeLater(clientThread, GUARD_FEATURE, () ->
				{
					if (client.getGameState().getState() < GameState.LOGGED_IN.getState())
					{
						// Logged out before profile loaded — abort
						return true;
					}
					String profileKey = configManager.getRSProfileKey();
					if (profileKey == null)
					{
						return false; // not ready yet, retry next tick
					}
					executorService.schedule(this::syncLoot, PROFILE_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
					return true;
				});
			}
			else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
			{
				flushDrops();
				syncLoot();
			}

			previousGameState = newState;
		});
	}

	/**
	 * Handles loot drops from the RuneLite loot tracker plugin.
	 * LootReceived fires after the loot tracker processes a kill, providing
	 * the NPC name, kill count (amount), items, and NPC metadata with the ID.
	 */
	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		Guard.run(GUARD_FEATURE, () -> {
			NPC npc = event.getNpc();
			if (npc != null && npc.getName() != null)
			{
				recentNpcIds.put(npc.getName(), npc.getId());
			}
		});
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getType() != LootRecordType.NPC && event.getType() != LootRecordType.EVENT)
			{
				return;
			}
			if (!config.syncLoot())
			{
				return;
			}
			if (!SyncGuard.hasAppKey(config))
			{
				return;
			}
			if (GameModeUtil.isSpecialGameMode(client))
			{
				return;
			}

			String playerUsername = SyncGuard.getPlayerUsername(client);
			if (playerUsername == null)
			{
				return;
			}

			String npcName = event.getName();

			// event.getAmount() is the number of kills in THIS event (always 1),
			// not cumulative KC. We track KC ourselves: seed from the loot tracker
			// config on first kill, then increment locally per kill.
			int killCount = sessionKillCounts.compute(npcName, (name, current) ->
			{
				if (current == null)
				{
					// First kill this session — seed from loot tracker config.
					// Config has the count BEFORE this kill, so add the event amount.
					return readCumulativeKillCount(name) + event.getAmount();
				}
				return current + event.getAmount();
			});

			// The metadata contains an NpcMetadata object with the NPC ID.
			// NpcMetadata is package-private, so we access it via reflection-free approach:
			// resolve from nearby loaded NPCs by name, or from metadata if castable.
			int npcId = resolveNpcIdFromEvent(event);

			List<LootSyncPayload.LootItem> items = new ArrayList<>();
			boolean notable = false;
			for (ItemStack itemStack : event.getItems())
			{
				int itemId = canonicalizeItemId(itemStack.getId());
				items.add(new LootSyncPayload.LootItem(itemId, itemStack.getQuantity()));
				notable = notable || isNotable(itemId, itemStack.getQuantity());
			}

			if (items.isEmpty())
			{
				return;
			}

			String droppedAt = DateTimeFormatter.ISO_INSTANT.format(Instant.now().atOffset(ZoneOffset.UTC));
			LootDropPayload payload = new LootDropPayload(playerUsername, clientId, npcId, npcName, killCount, droppedAt, items);

			synchronized (pendingDrops)
			{
				pendingDrops.add(payload);
			}
			if (notable)
			{
				notableFlusher.request();
			}
		});
	}

	private boolean isNotable(int itemId, int quantity)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		boolean tradeable = comp == null || comp.isTradeable();
		return NotableLootFlusher.isNotable(itemId, quantity, itemManager.getItemPrice(itemId), tradeable);
	}

	/**
	 * Flushes all queued loot drops to the API in a single batch request.
	 */
	private void flushDrops()
	{
		List<LootDropPayload> dropsToSend;
		synchronized (pendingDrops)
		{
			if (pendingDrops.isEmpty())
			{
				return;
			}
			dropsToSend = new ArrayList<>(pendingDrops);
			pendingDrops.clear();
		}

		apiClient.sendLootDrops(dropsToSend);
	}

	/**
	 * Reads cumulative loot data from RuneLite's loot tracker config and syncs to the API.
	 */
	private void syncLoot()
	{
		if (!config.syncLoot())
		{
			return;
		}
		if (!SyncGuard.hasAppKey(config))
		{
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null)
		{
			log.warn("Loot sync skipped: could not get player username");
			return;
		}

		List<LootSyncPayload.LootRecord> lootRecords = readLootTrackerData();
		if (lootRecords.isEmpty())
		{
			return;
		}

		String currentHash = computeLootHash(lootRecords);

		// Lazily load persisted hash on first sync after start/restart
		if (lastSyncHash == null)
		{
			lastSyncHash = configManager.getRSProfileConfiguration("osrscompanion", LAST_SYNC_HASH_KEY);
		}

		if (currentHash.equals(lastSyncHash))
		{
			return;
		}

		LootSyncPayload payload = new LootSyncPayload(playerUsername, clientId, lootRecords);
		apiClient.sendLootSync(payload);

		lastSyncHash = currentHash;
		configManager.setRSProfileConfiguration("osrscompanion", LAST_SYNC_HASH_KEY, currentHash);
	}

	/**
	 * Computes an MD5 hash of the loot records for change detection.
	 * Records are sorted by NPC name to ensure deterministic ordering.
	 */
	private String computeLootHash(List<LootSyncPayload.LootRecord> records)
	{
		try
		{
			MessageDigest md = MessageDigest.getInstance("MD5");
			// Bumped when the payload gains fields, so existing totals upload once more.
			md.update(LOOT_PAYLOAD_VERSION.getBytes(java.nio.charset.StandardCharsets.UTF_8));
			List<LootSyncPayload.LootRecord> sorted = new ArrayList<>(records);
			sorted.sort((a, b) -> a.getNpcName().compareTo(b.getNpcName()));
			for (LootSyncPayload.LootRecord record : sorted)
			{
				md.update(record.getNpcName().getBytes(java.nio.charset.StandardCharsets.UTF_8));
				md.update(intToBytes(record.getNpcId()));
				md.update(intToBytes(record.getKillCount()));
				md.update(Long.toString(record.getLastAt() == null ? 0 : record.getLastAt()).getBytes(java.nio.charset.StandardCharsets.UTF_8));
				for (LootSyncPayload.LootItem item : record.getItems())
				{
					md.update(intToBytes(item.getItemId()));
					md.update(intToBytes(item.getQuantity()));
				}
			}
			byte[] digest = md.digest();
			StringBuilder sb = new StringBuilder();
			for (byte b : digest)
			{
				sb.append(String.format("%02x", b & 0xff));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			return UUID.randomUUID().toString();
		}
	}

	private static byte[] intToBytes(int value)
	{
		return new byte[] {
			(byte) (value >> 24), (byte) (value >> 16),
			(byte) (value >> 8), (byte) value
		};
	}

	/**
	 * Reads cumulative loot data from RuneLite's loot tracker ConfigManager storage.
	 *
	 * The loot tracker stores ConfigLoot objects as JSON under RSProfile keys
	 * with the format: drops_{LootRecordType}_{NpcName} (e.g. "drops_NPC_Zulrah").
	 */
	private List<LootSyncPayload.LootRecord> readLootTrackerData()
	{
		List<LootSyncPayload.LootRecord> records = new ArrayList<>();

		try
		{
			String profileKey = configManager.getRSProfileKey();
			if (profileKey == null)
			{
				return records;
			}

			List<String> keys = configManager.getRSProfileConfigurationKeys(
				LOOT_TRACKER_CONFIG_GROUP, profileKey, LOOT_TRACKER_DROPS_PREFIX
			);

			for (String key : keys)
			{
				try
				{
					String json = configManager.getConfiguration(LOOT_TRACKER_CONFIG_GROUP, profileKey, key);
					if (json == null || json.isEmpty())
					{
						continue;
					}

					LootSyncPayload.LootRecord record = parseConfigLootJson(json);
					if (record != null)
					{
						records.add(record);
					}
				}
				catch (Exception e)
				{
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to read loot tracker data from config", e);
		}

		return records;
	}

	/**
	 * Parses a serialized ConfigLoot JSON object into our LootRecord format.
	 * This runs on the executor thread so it avoids client-thread-only APIs
	 * (no NPC lookups, no ItemManager calls). The loot tracker already stores
	 * canonical item IDs and the NPC name is used by the backend for matching.
	 */
	private LootSyncPayload.LootRecord parseConfigLootJson(String json)
	{
		JsonObject obj = gson.fromJson(json, JsonObject.class);

		String type = obj.has("type") ? obj.get("type").getAsString() : "";
		if (!"NPC".equals(type) && !"EVENT".equals(type))
		{
			return null;
		}

		String npcName = obj.has("name") ? obj.get("name").getAsString() : null;
		if (npcName == null || npcName.isEmpty())
		{
			return null;
		}

		// Use a deterministic hash for the NPC ID since we can't call client
		// APIs from the executor thread. The backend resolves the real NPC via name.
		int npcId = npcName.hashCode() & 0x7FFFFFFF;
		int killCount = obj.has("kills") ? obj.get("kills").getAsInt() : 0;

		Map<Integer, Integer> aggregatedItems = new LinkedHashMap<>();
		if (obj.has("drops"))
		{
			JsonArray drops = obj.getAsJsonArray("drops");
			for (int i = 0; i + 1 < drops.size(); i += 2)
			{
				int itemId = drops.get(i).getAsInt();
				int quantity = drops.get(i + 1).getAsInt();
				aggregatedItems.merge(itemId, quantity, Integer::sum);
			}
		}

		List<LootSyncPayload.LootItem> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : aggregatedItems.entrySet())
		{
			items.add(new LootSyncPayload.LootItem(entry.getKey(), entry.getValue()));
		}

		// The loot tracker keeps when you first and last got loot from it (epoch millis).
		Long firstAt = epochMillis(obj, "first");
		Long lastAt = epochMillis(obj, "last");
		return new LootSyncPayload.LootRecord(npcId, npcName, killCount, items, firstAt, lastAt);
	}

	private static Long epochMillis(JsonObject obj, String field)
	{
		try
		{
			return obj.has(field) && obj.get(field).isJsonPrimitive() ? obj.get(field).getAsLong() : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Reads the cumulative kill count for an NPC from the loot tracker's config.
	 * The loot tracker stores config under key "drops_NPC_{name}" with a "kills" field.
	 * This runs on the client thread (called from onLootReceived) so ConfigManager access is safe.
	 */
	private int readCumulativeKillCount(String npcName)
	{
		try
		{
			String profileKey = configManager.getRSProfileKey();
			if (profileKey == null)
			{
				return 0;
			}
			String configKey = LOOT_TRACKER_DROPS_PREFIX + "NPC_" + npcName;
			String json = configManager.getConfiguration(LOOT_TRACKER_CONFIG_GROUP, profileKey, configKey);
			if (json == null || json.isEmpty())
			{
				return 0;
			}
			JsonObject obj = gson.fromJson(json, JsonObject.class);
			return obj.has("kills") ? obj.get("kills").getAsInt() : 0;
		}
		catch (Exception e)
		{
			return 0;
		}
	}

	/**
	 * Resolves the NPC ID from a LootReceived event.
	 * Checks the cache populated by NpcLootReceived, falls back to nearby NPC lookup.
	 */
	private int resolveNpcIdFromEvent(LootReceived event)
	{
		Integer cachedId = recentNpcIds.get(event.getName());
		if (cachedId != null && cachedId > 0)
		{
			return cachedId;
		}

		return resolveNpcId(event.getName());
	}

	/**
	 * Resolves an NPC name to its NPC ID by checking currently loaded NPCs.
	 * Falls back to a deterministic hash if no matching NPC is found nearby.
	 */
	private int resolveNpcId(String npcName)
	{
		for (NPC npc : getWorldNpcs())
		{
			if (npc.getName() != null && npc.getName().equalsIgnoreCase(npcName))
			{
				return npc.getId();
			}
		}
		return npcName.hashCode() & 0x7FFFFFFF;
	}

	private Iterable<? extends NPC> getWorldNpcs()
	{
		WorldView wv = client.getTopLevelWorldView();
		return wv == null ? Collections.emptyList() : wv.npcs();
	}

	/**
	 * Converts noted item IDs to their base item ID using the ItemManager.
	 */
	private int canonicalizeItemId(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		if (comp != null && comp.getNote() != -1)
		{
			return comp.getLinkedNoteId();
		}
		return itemId;
	}
}

package com.osrscompanion;

import java.util.*;
import java.util.regex.Pattern;

/**
 * Magic for live activity, the pure part: what a "Cast" (or a tablet's "Break") menu click was (the website
 * writes its text and picture: "Teleported to Varrock", "High alching Rune platebody"). No game access, so it
 * is unit tested.
 */
final class MagicSpells {
	private MagicSpells() {
	}

	/** What a spell does, for the text shown. */
	enum Type {
		TELEPORT,
		HIGH_ALCH,
		LOW_ALCH,
		OFFENSIVE,
		UTILITY
	}

	/** One cast: the spell, what it was cast on (an item or NPC name, or null) and what it does. */
	static final class Cast {
		final String spell;
		final String target;
		final Type type;
		/** A teleport tablet ("Varrock teleport", option "Break"): no Magic XP comes with it. */
		final boolean tablet;

		Cast(String spell, String target, Type type, boolean tablet) {
			this.spell = spell;
			this.target = target;
			this.type = type;
			this.tablet = tablet;
		}
	}

	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	/** "Hill Giant  (level-28)" -> "Hill Giant". */
	private static final Pattern LEVEL = Pattern.compile("\\s*\\((level|skill)-\\d+\\)\\s*$", Pattern.CASE_INSENSITIVE);

	/** Offensive spells by exact name (lower case), besides the elemental and Ancient patterns below. */
	private static final Set<String> OFFENSIVE = Tables.stringSet("offensiveSpells");
	private static final Pattern ELEMENTAL = Pattern.compile("^(wind|water|earth|fire) (strike|bolt|blast|wave|surge)$");
	private static final Pattern ANCIENT = Pattern.compile("^(smoke|shadow|blood|ice) (rush|burst|blitz|barrage)$");

	/** Menu text without colour tags and the trailing level: "<col=ff9040>Rune platebody</col>" -> "Rune platebody". */
	static String clean(String s) {
		if (s == null) {
			return null;
		}
		String t = LEVEL.matcher(TAGS.matcher(s).replaceAll("")).replaceAll("").replace(' ', ' ').trim();
		return t.isEmpty() ? null : t;
	}

	/**
	 * The cast a menu click is, or null: option "Cast" with the target "Spell" or "Spell -> item / NPC"
	 * (the spell widget's own click, or using a selected spell on something), or "Break" on a teleport tablet.
	 * {@code onNpc}: the click targets an NPC.
	 */
	static Cast fromMenu(String option, String target, boolean onNpc) {
		String opt = clean(option);
		String tgt = clean(target);
		if (opt == null || tgt == null) {
			return null;
		}
		if (opt.equalsIgnoreCase("Break") && tgt.toLowerCase(Locale.ROOT).contains("teleport")) {
			return new Cast(tgt, null, Type.TELEPORT, true);
		}
		if (!opt.equalsIgnoreCase("Cast")) {
			return null;
		}
		String spell = tgt;
		String on = null;
		int arrow = tgt.indexOf("->");
		if (arrow >= 0) {
			spell = clean(tgt.substring(0, arrow));
			on = clean(tgt.substring(arrow + 2));
		}
		if (spell == null) {
			return null;
		}
		return new Cast(spell, on, typeOf(spell, onNpc), false);
	}

	/** What a spell does: by its name; a spell not otherwise known that is cast on an NPC is offensive. */
	static Type typeOf(String spell, boolean onNpc) {
		String s = spell == null ? "" : spell.trim().toLowerCase(Locale.ROOT);
		if (s.equals("high level alchemy")) {
			return Type.HIGH_ALCH;
		}
		if (s.equals("low level alchemy")) {
			return Type.LOW_ALCH;
		}
		if (isTeleport(s)) {
			return Type.TELEPORT;
		}
		if (OFFENSIVE.contains(s) || ELEMENTAL.matcher(s).matches() || ANCIENT.matcher(s).matches()) {
			return Type.OFFENSIVE;
		}
		// Utility spells cast on monsters (Monster Examine, Dark Lure...) aren't attacks.
		if (onNpc && !s.equals("monster examine") && !s.equals("dark lure") && !s.startsWith("resurrect")) {
			return Type.OFFENSIVE;
		}
		return Type.UTILITY;
	}

	/** A spell (or tablet) that moves you: "... Teleport", "Teleport to ...", "Tele Group ..."; not Tele Block or Teleport Other. */
	static boolean isTeleport(String spellLower) {
		String s = spellLower == null ? "" : spellLower.trim().toLowerCase(Locale.ROOT);
		if (s.isEmpty() || s.equals("tele block") || s.startsWith("teleport other") || s.equals("telekinetic grab")) {
			return false;
		}
		return s.endsWith(" teleport") || s.contains(" teleport (") || s.startsWith("teleport to ") || s.startsWith("tele group ");
	}
}

package com.osrscompanion;

import com.osrscompanion.model.GoalType;
import com.osrscompanion.model.Roadmap;
import com.osrscompanion.model.RoadmapGoal;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;

/**
 * Game-window overlay showing the current goal of the selected roadmap.
 *
 * <p>Gated by {@link OSRSCompanionConfig#showNextGoal()}. Reads the cached roadmap from
 * {@link RoadmapManager} (no network on the render thread) and renders a
 * "[roadmap name] - Current Goal" header above the goal name, with the goal's
 * item icon beside it when the goal targets an item, plus an app-style progress
 * bar for measurable goals (see {@link GoalProgressBarComponent}). Renders
 * nothing when disabled, no app key, or no incomplete goal is available.
 */
public class NextGoalOverlay extends OverlayPanel {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "next-goal-overlay";

	private static final Color TITLE_COLOR = new Color(0xF2, 0x8C, 0x28); // OSRS Companion orange
	private static final Color MUTED_COLOR = new Color(0xA5, 0xA5, 0xA5);
	/** Shown under goals only the server can move while a re-read is pending. */
	private static final String SYNCING_TEXT = "Syncing with server...";

	/** Horizontal padding added to the widest line so text never touches the edge. */
	private static final int WIDTH_PADDING = 14;
	/** Floor so a very short goal still renders as a panel, not a sliver. */
	private static final int MIN_WIDTH = 120;
	/** Text wraps onto a new line once it would exceed this width. */
	private static final int MAX_TEXT_WIDTH = 200;
	/** Gap between the item icon and the goal name. */
	private static final int ICON_GAP = 6;
	/** Transparent spacer that adds vertical margin between the title and the goal. */
	private static final BufferedImage TITLE_CONTENT_SPACER =
			new BufferedImage(1, 4, BufferedImage.TYPE_INT_ARGB);

	private final OSRSCompanionConfig config;
	private final RoadmapManager roadmapManager;
	private final GoalProgressTracker goalProgressTracker;
	private final ItemManager itemManager;
	private final SkillIconManager skillIconManager;
	private final GoalImageCache goalImageCache;

	// Cache the last icon (keyed by "item:<id>" / "skill:<name>") so we don't
	// re-fetch every render frame.
	private String cachedIconKey;
	private BufferedImage cachedIcon;

	@Inject
	public NextGoalOverlay(OSRSCompanionConfig config, RoadmapManager roadmapManager,
			GoalProgressTracker goalProgressTracker,
			ItemManager itemManager, SkillIconManager skillIconManager,
			GoalImageCache goalImageCache) {
		this.config = config;
		this.roadmapManager = roadmapManager;
		this.goalProgressTracker = goalProgressTracker;
		this.itemManager = itemManager;
		this.skillIconManager = skillIconManager;
		this.goalImageCache = goalImageCache;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		return Guard.render(GUARD_FEATURE, () -> {
			if (!config.showNextGoal() || !roadmapManager.hasAppKey()) {
				return null;
			}

			Roadmap roadmap = roadmapManager.getCurrentRoadmap();
			if (roadmap == null) {
				return null;
			}
			// The tracker's view includes goals completed locally this session, so
			// the overlay advances the moment a goal is done rather than after the
			// next server read.
			RoadmapGoal goal = goalProgressTracker.firstIncompleteGoal(roadmap);
			if (goal == null || goal.getName() == null) {
				return null;
			}
			GoalProgressBarComponent bar = config.showGoalProgress()
					? barFor(goalProgressTracker.progressFor(goal))
					: null;

			String title = roadmap.getTitle();
			String header = (title == null || title.isEmpty())
					? "Current Goal"
					: title + " - Current Goal";
			String goalName = goal.getName();
			BufferedImage icon = iconFor(goal);
			int iconWidth = icon != null ? icon.getWidth() : 0;

			// Word-wrap both lines so long content flows onto multiple lines instead
			// of spilling past the background box. The goal name sits to the right of
			// the icon, so it wraps in the narrower space left beside it.
			FontMetrics metrics = graphics.getFontMetrics();
			List<String> titleLines = wrapText(header, MAX_TEXT_WIDTH, metrics);
			int contentMax = MAX_TEXT_WIDTH - (icon != null ? iconWidth + ICON_GAP : 0);
			List<String> goalLines = wrapText(goalName, contentMax, metrics);

			// Size the panel to the actual widest rendered line (left-aligned). The
			// whole goal-text block sits to the right of the icon, so its width is the
			// widest goal line plus the icon column.
			int widest = 0;
			for (String line : titleLines) {
				widest = Math.max(widest, metrics.stringWidth(line));
			}
			int goalTextWidth = 0;
			for (String line : goalLines) {
				goalTextWidth = Math.max(goalTextWidth, metrics.stringWidth(line));
			}
			int goalBlockWidth = goalTextWidth + (icon != null ? iconWidth + ICON_GAP : 0);
			widest = Math.max(widest, goalBlockWidth);
			if (bar != null) {
				widest = Math.max(widest, bar.minWidth(metrics));
			}

			panelComponent.getChildren().clear();
			panelComponent.setPreferredSize(
					new Dimension(Math.max(MIN_WIDTH, widest + WIDTH_PADDING), 0));

			// Title: left-aligned orange line(s).
			for (String line : titleLines) {
				panelComponent.getChildren().add(LineComponent.builder()
						.left(line)
						.leftColor(TITLE_COLOR)
						.build());
			}
			// Breathing room between the title and the goal content below it.
			panelComponent.getChildren().add(new ImageComponent(TITLE_CONTENT_SPACER));

			// Goal name: the icon sits beside the whole (possibly multi-line) goal
			// text, so wrapped lines like "from drops" align under the first line's
			// text rather than dropping under the icon.
			LayoutableRenderableEntity goalBlock = stackLines(goalLines);
			if (icon != null) {
				goalBlock = SplitComponent.builder()
						.first(new ImageComponent(icon))
						.second(goalBlock)
						.orientation(ComponentOrientation.HORIZONTAL)
						.gap(new Point(ICON_GAP, 0))
						.build();
			}
			panelComponent.getChildren().add(goalBlock);

			// Progress bar + "current / target" label for measurable goals.
			if (bar != null) {
				panelComponent.getChildren().add(bar);
			}

			// Server-driven goals (net worth, Tears of Guthix) only move on a server
			// read: say so while one is pending so the wait is not mistaken for a stall.
			if (goal.getType().isServerDriven() && roadmapManager.isSyncing()) {
				panelComponent.getChildren().add(new ImageComponent(TITLE_CONTENT_SPACER));
				panelComponent.getChildren().add(LineComponent.builder()
						.left(SYNCING_TEXT)
						.leftColor(MUTED_COLOR)
						.build());
				widest = Math.max(widest, metrics.stringWidth(SYNCING_TEXT));
				panelComponent.setPreferredSize(
						new Dimension(Math.max(MIN_WIDTH, widest + WIDTH_PADDING), 0));
			}

			return super.render(graphics);
		});
	}

	/** The bar for a measurable goal, or null for binary goals (no bar). */
	private static GoalProgressBarComponent barFor(GoalProgressView progress) {
		if (!progress.isMeasurable()) {
			return null;
		}
		String label = GoalProgressLabel.format(
				progress.getType(), progress.getCurrent(), progress.getTarget(), progress.getPercent());
		boolean grown = progress.getType() == GoalType.FARMING_TIMER && progress.getTarget() <= 1;
		String percent = grown ? null : GoalProgressLabel.percent(progress.getPercent());
		return new GoalProgressBarComponent(GoalProgressLabel.fraction(progress.getPercent()), label, percent);
	}

	/** Stacks the goal lines vertically so they can share the icon's column as a
	 * single block; wrapped lines then align under the first line's text. */
	private static LayoutableRenderableEntity stackLines(List<String> lines) {
		LayoutableRenderableEntity stacked =
				LineComponent.builder().left(lines.get(lines.size() - 1)).build();
		for (int i = lines.size() - 2; i >= 0; i--) {
			stacked = SplitComponent.builder()
					.first(LineComponent.builder().left(lines.get(i)).build())
					.second(stacked)
					.orientation(ComponentOrientation.VERTICAL)
					.build();
		}
		return stacked;
	}

	/** Greedily word-wraps text into lines no wider than {@code maxWidth}. */
	private static List<String> wrapText(String text, int maxWidth, FontMetrics metrics) {
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.trim().split("\\s+")) {
			if (line.length() == 0) {
				line.append(word);
			} else if (metrics.stringWidth(line + " " + word) <= maxWidth) {
				line.append(' ').append(word);
			} else {
				lines.add(line.toString());
				line.setLength(0);
				line.append(word);
			}
		}
		if (line.length() > 0) {
			lines.add(line.toString());
		}
		if (lines.isEmpty()) {
			lines.add(text);
		}
		return lines;
	}

	/** The goal's icon: an item sprite, a skill icon, the goal's wiki artwork (bosses,
	 * combat tasks) once it has loaded, or null when none is available. */
	private BufferedImage iconFor(RoadmapGoal goal) {
		Integer itemId = goal.getItemId();
		if (itemId != null) {
			return cached("item:" + itemId, () -> itemManager.getImage(itemId));
		}
		Skill skill = parseSkill(goal.getSkillName());
		if (skill != null) {
			return cached("skill:" + skill.name(), () -> skillIconManager.getSkillImage(skill));
		}
		// Not memoised here: the cache returns null until the fetch completes,
		// and its own lookup is a map read.
		return goalImageCache.get(goal.getImageUrl());
	}

	/** Memoise the last icon so we don't re-fetch it every render frame. */
	private BufferedImage cached(String key, java.util.function.Supplier<BufferedImage> loader) {
		if (!key.equals(cachedIconKey)) {
			cachedIconKey = key;
			cachedIcon = loader.get();
		}
		return cachedIcon;
	}

	/** The RuneLite {@link Skill} for a goal's skill name, or null if unknown
	 * (e.g. Sailing, which RuneLite doesn't have an icon for yet). */
	private static Skill parseSkill(String name) {
		if (name == null) {
			return null;
		}
		try {
			return Skill.valueOf(name.toUpperCase(Locale.ROOT));
		} catch (IllegalArgumentException e) {
			return null;
		}
	}
}

package com.osrscompanion;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import net.runelite.api.gameval.ItemID;

/**
 * Decides whether a loot stack is worth uploading right away, and rate-limits the
 * early uploads it triggers so a burst of notable drops costs at most one extra
 * request per {@link #MIN_INTERVAL_MS}. The regular timed flush is untouched.
 */
class NotableLootFlusher
{
	static final long NOTABLE_STACK_VALUE = 100_000L;
	static final long MIN_INTERVAL_MS = 10_000L;

	private final ScheduledExecutorService executorService;
	private final Runnable flush;
	private final LongSupplier clockMs;

	private ScheduledFuture<?> pending;
	private long lastFlushMs;
	private boolean hasFlushed;

	NotableLootFlusher(ScheduledExecutorService executorService, Runnable flush)
	{
		this(executorService, flush, () -> TimeUnit.NANOSECONDS.toMillis(System.nanoTime()));
	}

	NotableLootFlusher(ScheduledExecutorService executorService, Runnable flush, LongSupplier clockMs)
	{
		this.executorService = executorService;
		this.flush = flush;
		this.clockMs = clockMs;
	}

	/**
	 * A stack is notable when it is worth at least {@link #NOTABLE_STACK_VALUE}, or is a
	 * single untradeable item (pets, collection log uniques). Untradeable stacks such as
	 * currencies and shards drop constantly and are not notable.
	 */
	static boolean isNotable(int itemId, int quantity, long unitPrice, boolean tradeable)
	{
		if (quantity <= 0 || itemId == ItemID.COINS)
		{
			return false;
		}
		if (unitPrice * quantity >= NOTABLE_STACK_VALUE)
		{
			return true;
		}
		return !tradeable && quantity == 1;
	}

	/**
	 * Flushes now, or as soon as the minimum interval since the last early flush has
	 * passed. Requests made while a flush is already pending are absorbed by it.
	 */
	synchronized void request()
	{
		if (pending != null && !pending.isDone())
		{
			return;
		}
		long delayMs = hasFlushed ? Math.max(0L, lastFlushMs + MIN_INTERVAL_MS - clockMs.getAsLong()) : 0L;
		pending = executorService.schedule(this::run, delayMs, TimeUnit.MILLISECONDS);
	}

	synchronized void cancel()
	{
		if (pending != null)
		{
			pending.cancel(false);
			pending = null;
		}
	}

	private void run()
	{
		synchronized (this)
		{
			lastFlushMs = clockMs.getAsLong();
			hasFlushed = true;
		}
		flush.run();
	}
}

