	private java.util.concurrent.ScheduledFuture<?> roadmapWaitingPoll;
	private java.util.concurrent.ScheduledFuture<?> farmRouteReadyPoll;
	/** Every object registered on the event bus at start, unregistered at stop. */
	private java.util.List<Object> subscribers;
	/** A player was logged in since the last login screen: later LOGGED_IN events are region loads. */
	private boolean sessionLoaded;

	@Override
	protected void startUp() {
		// Never throws: each subsystem starts on its own, so one failure leaves the others working.
		step("crash safety", this::startCrashSafety);
		step("settings", this::migrateSettings);
		// Uploads queue in the outbox and go out batched (first, so the monitors' first syncs use it).
		step("outbox", () -> apiClient.startOutbox(GuardedExecutor.wrap(Guard.SYNC_FEATURE, executorService)));
		step("farming timers", this::startFarming);

		subscribers = java.util.Arrays.asList(this, timerMonitor, playerSkillsMonitor, bankMemoryMonitor, vaultMonitor,
				potionStorageMonitor, runePouchMonitor, plankSackMonitor, loadoutMonitor, lootMonitor,
				collectionLogMonitor, questMonitor, varPump, farmingUnlocksMonitor,
				killCountMonitor, slayerMonitor, slayerCatalogMonitor,
				slayerRewardsMonitor, farmRunManager, bankLayoutPrep,
				farmRunSceneOverlay, slayerHelperManager, slayerGuideMarkers, slayerGuideHouseOverlay, sessionMonitor,
				gameEvents, suppliesCheck, liveActivityMonitor);
		for (Object subscriber : subscribers) {
			if (subscriber != null) {
				step("register " + subscriber.getClass().getSimpleName(), () -> eventBus.register(subscriber));
			}
		}
		step("bank layout", bankLayoutPrep::startUp);
		step("timers", timerMonitor::start);
		step("play sessions", sessionMonitor::start);
		step("loot", lootMonitor::start);
		step("skills", playerSkillsMonitor::start);
		step("goal progress", this::connectGoalProgress);
		step("roadmap", () -> {
			roadmapManager.startPeriodicRefresh();
			// On the roadmap's own thread (guarded there), never RuneLite's shared executor.
			roadmapWaitingPoll = roadmapManager.executor().scheduleWithFixedDelay(roadmapManager::pollWhileWaiting,
					RoadmapManager.WAITING_POLL_SECONDS, RoadmapManager.WAITING_POLL_SECONDS, java.util.concurrent.TimeUnit.SECONDS);
		});
		// Live activity: every batch carries the status; the watcher below sends the heartbeat.
		step("live activity", liveActivityMonitor::start);
		// Website changes: the webVersion from batch answers or a small check every 30 s re-reads what changed.
		step("web updates", webVersionWatcher::start);
		// The last farm route ready again (all its patches grown), checked logged in or not.
		step("farm route ready", () -> farmRouteReadyPoll = executorService.scheduleWithFixedDelay(
				Guard.wrap(FarmRunManager.GUARD_FEATURE, farmRunManager::checkRouteReady), 30, 30, java.util.concurrent.TimeUnit.SECONDS));
		step("side panel", this::addSidePanel);
		step("overlays", this::addOverlays);
	}

	/** Every feature on again (a fresh session); one turned off after errors is told in the chat. */
	private void startCrashSafety() {
		Guard guard = Guard.shared();
		guard.resetBreakers();
		guard.setOnDisabled(feature -> chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage("OSRS Companion: " + Guard.displayName(feature) + " was turned off after an error.")
				.build()));
	}

	/**
	 * Runs one start or stop step; a failure is logged (without counting towards a breaker) and the
	 * next step still runs.
	 */
	private static void step(String name, Runnable body) {
		try {
			body.run();
		} catch (ThreadDeath death) {
			throw death;
		} catch (Throwable e) {
			log.warn("OSRS Companion: {} failed", name, e);
		}
	}

	private void startFarming() {

		timerMonitor = new TimerMonitor(client, config, apiClient, configManager,
				GuardedExecutor.wrap(TimerMonitor.GUARD_FEATURE, executorService), gson);
	}

	/**
	 * Local goal progress: monitors report what they upload, the tracker
	 * layers it on the server's roadmap and asks for a re-read afterwards.
	 */
	private void connectGoalProgress() {
		roadmapManager.setRoadmapListener(goalProgressTracker::onServerRoadmap);
		roadmapManager.setRoadmapSetListener(goalProgressTracker::retainRoadmaps);
		vaultMonitor.setCargoBankedListener(bankMemoryMonitor::onItemsBankedUnseen);
	}

	private void addSidePanel() {
		// Side-panel roadmap tab.
		roadmapPanel = new RoadmapPanel(this::toggleFarmRun, this::toggleBossGear, this::toggleSlayerGear, itemManager,
				spriteManager, goalImageCache, config, configManager, roadmapManager, farmRunManager, bossGearManager,
				slayerHelperManager, clientThread);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
				.tooltip("OSRS Companion Roadmaps")
				.icon(icon)
				.priority(7)
				.panel(roadmapPanel)
				.build();
		clientToolbar.addNavigation(navButton);
	}

	private void addOverlays() {
		// Next-goal game overlay (rendered only while showNextGoal is enabled).
		overlayManager.add(nextGoalOverlay);
		// Roadmap progress drawn under the goal completion popup while it shows.
		overlayManager.add(goalCompletionOverlay);

		// Farm run: the window (side-panel button), the step box, scene pointers and item highlights.
		overlayManager.add(farmRunWindow);
		mouseManager.registerMouseListener(farmRunWindow);
		mouseManager.registerMouseWheelListener(farmRunWindow);
		keyManager.registerKeyListener(farmRunWindow);
		overlayManager.add(farmRunOverlay);
		overlayManager.add(farmRunSceneOverlay);
		overlayManager.add(farmRunItemOverlay);

		// Slayer helper: the guide's box (stats at the location); the arrow and map icon come from the markers.
		overlayManager.add(slayerHelperOverlay);
		// In your house on the way: the jewellery box (portal, nexus...) the way there uses, outlined.
		overlayManager.add(slayerGuideHouseOverlay);

		// Boss gear: the window (side-panel button); the bank lays the set out while it is open.
		overlayManager.add(bossGearWindow);
		mouseManager.registerMouseListener(bossGearWindow);
		mouseManager.registerMouseWheelListener(bossGearWindow);
		keyManager.registerKeyListener(bossGearWindow);
		// Slayer gear: the DPS setups for the task (Slayer helper page tile); the picked one is what the bank lays out.
		overlayManager.add(slayerGearWindow);
		mouseManager.registerMouseListener(slayerGearWindow);
		mouseManager.registerMouseWheelListener(slayerGearWindow);
		keyManager.registerKeyListener(slayerGearWindow);
		// Supplies check: beside the open bank.
		overlayManager.add(suppliesOverlay);

	}

	/** The farm run, boss gear and slayer gear windows share the middle of the screen (and the bank): one at a time. */
	private void toggleFarmRun() {
		if (!farmRunManager.isOpen()) {
			bossGearManager.close();
			slayerHelperManager.closeGearWindow();
		}
		farmRunManager.toggle();
	}

	private void toggleBossGear() {
		if (!bossGearManager.isOpen()) {
			farmRunManager.close();
			slayerHelperManager.closeGearWindow();
		}
		bossGearManager.toggle();
	}

	private void toggleSlayerGear() {
		if (!slayerHelperManager.isGearOpen()) {
			farmRunManager.close();
			bossGearManager.close();
		}
		slayerHelperManager.toggleGearWindow();
	}

	@Override
	protected void shutDown() {
		// Never throws, and every step runs even when one before it failed: the executor jobs always stop.
		if (subscribers != null) {
			for (Object subscriber : subscribers) {
				if (subscriber != null) {
					step("unregister " + subscriber.getClass().getSimpleName(), () -> eventBus.unregister(subscriber));
				}
			}
			subscribers = null;
		}
		step("bank layout", bankLayoutPrep::shutDown);
		step("play sessions", sessionMonitor::stop);
		step("game events", gameEvents::stop);
		step("supplies", () -> {
			suppliesCheck.clear();
			overlayManager.remove(suppliesOverlay);
		});
		step("goal progress", this::disconnectGoalProgress);

		step("stop timerMonitor", () -> timerMonitor.stop());
		step("stop playerSkillsMonitor", () -> playerSkillsMonitor.stop());
		step("stop bankMemoryMonitor", () -> bankMemoryMonitor.stop());
		step("stop vaultMonitor", () -> vaultMonitor.stop());
		step("stop potionStorageMonitor", () -> potionStorageMonitor.stop());
		step("stop runePouchMonitor", () -> runePouchMonitor.stop());
		step("stop plankSackMonitor", () -> plankSackMonitor.stop());
		step("stop loadoutMonitor", () -> loadoutMonitor.stop());
		step("stop lootMonitor", () -> lootMonitor.stop());
		step("stop collectionLogMonitor", () -> collectionLogMonitor.stop());
		step("stop questMonitor", () -> questMonitor.stop());
		step("stop varPump", () -> varPump.stop());
		step("stop farmingUnlocksMonitor", () -> farmingUnlocksMonitor.stop());
		step("stop killCountMonitor", () -> killCountMonitor.stop());
		step("stop slayerMonitor", () -> slayerMonitor.stop());
		step("stop slayerCatalogMonitor", () -> slayerCatalogMonitor.stop());
		step("stop slayerRewardsMonitor", () -> slayerRewardsMonitor.stop());
		// "Offline" for the player, queued before the outbox's last flush below.
		step("live activity", liveActivityMonitor::stop);

		step("side panel", () -> {
			if (navButton != null) {
				clientToolbar.removeNavigation(navButton);
				navButton = null;
			}
			roadmapPanel = null;
		});
		step("overlays", this::removeOverlays);
		step("polls", () -> {
			if (roadmapWaitingPoll != null) {
				roadmapWaitingPoll.cancel(false);
				roadmapWaitingPoll = null;
			}
			if (farmRouteReadyPoll != null) {
				farmRouteReadyPoll.cancel(false);
				farmRouteReadyPoll = null;
			}
		});
		step("roadmap", roadmapManager::clear);
		step("web updates", webVersionWatcher::stop);
		// The monitors' stop() above queued their last uploads: send them now; nothing is retried after.
		step("outbox", apiClient::stopOutbox);
		// Whatever periodic job a feature left behind (the shared executor is RuneLite's: only ours stop).
		step("executor jobs", GuardedExecutor::cancelAllPeriodic);
		step("crash safety", () -> Guard.shared().setOnDisabled(null));
	}

	private void disconnectGoalProgress() {
		roadmapManager.stopPeriodicRefresh();
		roadmapManager.setRoadmapListener(null);
		roadmapManager.setRoadmapSetListener(null);
		roadmapManager.setPanelListener(null);
		vaultMonitor.setCargoBankedListener(null);
		goalCompletionNotifier.clear();
		goalProgressTracker.clear();
		goalImageCache.clear();
	}

	private void removeOverlays() {
		overlayManager.remove(nextGoalOverlay);
		overlayManager.remove(goalCompletionOverlay);
		overlayManager.remove(farmRunWindow);
		mouseManager.unregisterMouseListener(farmRunWindow);
		mouseManager.unregisterMouseWheelListener(farmRunWindow);
		keyManager.unregisterKeyListener(farmRunWindow);
		overlayManager.remove(farmRunOverlay);
		overlayManager.remove(farmRunSceneOverlay);
		overlayManager.remove(farmRunItemOverlay);
		clientThread.invoke(Guard.wrapCleanup(FarmRunSceneOverlay.GUARD_FEATURE,
				() -> step("farm run markers", farmRunSceneOverlay::clearPointers)));
		overlayManager.remove(slayerHelperOverlay);
		overlayManager.remove(slayerGuideHouseOverlay);
		// The open slayer session is stored and sent before it is forgotten.
		clientThread.invoke(Guard.wrapCleanup(SlayerHelperManager.GUARD_FEATURE, () -> step("slayer helper", () -> {
			slayerGuideMarkers.clear();
			slayerGuideHouseOverlay.clear();
			slayerHelperManager.shutDown();
		})));
		farmRunManager.clear();
		overlayManager.remove(bossGearWindow);
		mouseManager.unregisterMouseListener(bossGearWindow);
		mouseManager.unregisterMouseWheelListener(bossGearWindow);
		keyManager.unregisterKeyListener(bossGearWindow);
		slayerHelperManager.closeGearWindow();
		overlayManager.remove(slayerGearWindow);
		mouseManager.unregisterMouseListener(slayerGearWindow);
		mouseManager.unregisterMouseWheelListener(slayerGearWindow);
		keyManager.unregisterKeyListener(slayerGearWindow);
		bossGearManager.clear();
	}

	/**
	 * Re-pushes every login sync the monitors normally send (timers, skills, bank,
	 * loadout, loot). Used when an App Key is entered mid-session. Each monitor
	 * schedules its own work on the executor / client thread, so this never
	 * blocks the caller.
	 */
	private void forceSyncAll() {
		// This is an explicit user re-sync: clear the request-dedupe cache so an
		// unchanged payload still gets sent (the monitors each reset their own
		// dedupe state in forceSync(), but the client-side cache is separate).
		apiClient.clearDedupeCache();
		timerMonitor.forceSync();
		playerSkillsMonitor.forceSync();
		bankMemoryMonitor.forceSync();
		loadoutMonitor.forceSync();
		lootMonitor.forceSync();
		collectionLogMonitor.forceSync();
		questMonitor.forceSync();
		varPump.forceSync();
		farmingUnlocksMonitor.forceSync();
		killCountMonitor.forceSync();
		slayerMonitor.forceSync();
		slayerCatalogMonitor.forceSync();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> gameStateChanged(event));
	}

	private void gameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGIN_SCREEN) {
			sessionLoaded = false;
		}
		if (event.getGameState() == GameState.LOGGED_IN) {
			// LOGGED_IN also follows every region load (LOADING): the roadmap loads only on a real login.
			boolean login = !sessionLoaded;
			sessionLoaded = true;
			if (login) {
				// Load the roadmap almost immediately so it shows right after login
				// (a plain read, NOT a forced re-sync), then again once this session's
				// login syncs have landed so completion/progress is fresh. On the
				// roadmap's own thread, never RuneLite's shared executor.
				roadmapManager.executor().schedule(this::loadRoadmapQuietly, 1, java.util.concurrent.TimeUnit.SECONDS);
				roadmapManager.executor().schedule(this::loadRoadmapQuietly, 8, java.util.concurrent.TimeUnit.SECONDS);
			}
			executorService.schedule(Guard.wrap(FarmRunManager.GUARD_FEATURE, farmRunManager::refresh),
					9, java.util.concurrent.TimeUnit.SECONDS);
		} else if (event.getGameState() == GameState.LOGIN_SCREEN) {
			webVersionWatcher.onLoggedOut();
			// The monitors queue their logout uploads (some via the client thread / executor):
			// send everything shortly after, without waiting for the batch interval or a backoff.
			executorService.schedule(Guard.wrap(Guard.SYNC_FEATURE, apiClient::flushOutbox), 2, java.util.concurrent.TimeUnit.SECONDS);
		}
	}

	/**
	 * Fires a full re-sync the moment a complete App Key is entered while the
	 * player is already logged in. The per-monitor login syncs only run on the
	 * login transition, so users who paste their key mid-session would otherwise
	 * see nothing sync until their next login. Gated on a minimum key length so we
	 * don't fire on partial edits, and on being logged in (at the login screen the
	 * normal login sync already covers it).
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		Guard.run(GUARD_FEATURE, () -> configChanged(event));
	}

	private void configChanged(ConfigChanged event) {
		if (!SyncGuard.isCompleteAppKeyEntry(event.getGroup(), event.getKey(), event.getNewValue())) {
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN) {
			return;
		}
		forceSyncAll();
	}

	/**
	 * Reloads the roadmaps without forcing a data re-sync: the list and every roadmap, which
	 * keeps the overlay and the roadmap window current.
	 */
	private void loadRoadmapQuietly() {
		roadmapManager.refreshAllQuietly();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event) {
		Guard.run(GUARD_FEATURE, () -> chatMessage(event));
	}

	private void chatMessage(ChatMessage event) {
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.DIALOG) {
			return;
		}
		String msg = event.getMessage();
		if (msg != null && msg.contains(TEARS_CAVE_MESSAGE)) {
			timerMonitor.onTearsOfGuthixCompleted();
		}
	}

	/** Carries settings that were merged or renamed over to their new keys, once. */
	private void migrateSettings() {
		String group = OSRSCompanionConfig.CONFIG_GROUP;
		String oldSound = configManager.getConfiguration(group, "goalCompleteSound");
		if (oldSound != null) {
			if (configManager.getConfiguration(group, OSRSCompanionConfig.GOAL_SOUND_KEY) == null) {
				configManager.setConfiguration(group, OSRSCompanionConfig.GOAL_SOUND_KEY, !"OFF".equals(oldSound));
			}
			configManager.unsetConfiguration(group, "goalCompleteSound");
		}
		String herbs = configManager.getConfiguration(group, "farmingCapeForHerbs");
		String force = configManager.getConfiguration(group, "forceFarmingCape");
		if (herbs != null || force != null) {
			if (configManager.getConfiguration(group, OSRSCompanionConfig.FARMING_CAPE_KEY) == null) {
				// Force is the default now: only a switched-off reminder stays off.
				FarmingCapeMode mode = "false".equals(herbs) && !"true".equals(force) ? FarmingCapeMode.OFF : FarmingCapeMode.FORCE;
				configManager.setConfiguration(group, OSRSCompanionConfig.FARMING_CAPE_KEY, mode);
			}
			configManager.unsetConfiguration(group, "farmingCapeForHerbs");
			configManager.unsetConfiguration(group, "forceFarmingCape");
		}
		// Once: Remind (what the first merge of the two cape settings gave) becomes the new default, Force.
		if (configManager.getConfiguration(group, "farmingCapeForceDefault") == null) {
			if ("REMIND".equals(configManager.getConfiguration(group, OSRSCompanionConfig.FARMING_CAPE_KEY))) {
				configManager.setConfiguration(group, OSRSCompanionConfig.FARMING_CAPE_KEY, FarmingCapeMode.FORCE);
			}
			configManager.setConfiguration(group, "farmingCapeForceDefault", true);
		}
		String supplies = configManager.getConfiguration(group, "suppliesCheck");
		if (supplies != null) {
			boolean on = !"false".equals(supplies);
			for (String key : new String[]{OSRSCompanionConfig.TRIP_PLANNER_BOSS_KEY, OSRSCompanionConfig.TRIP_PLANNER_FARM_KEY}) {
				if (configManager.getConfiguration(group, key) == null) {
					configManager.setConfiguration(group, key, on);
				}
			}
			configManager.unsetConfiguration(group, "suppliesCheck");
		}
	}

	@Provides
	OSRSCompanionConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(OSRSCompanionConfig.class);
	}
}

package com.osrscompanion;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/** Side-panel pieces in the tool tiles' style: an on/off tile, info cards and a stats card. */
final class PanelTiles {
	private static final int ARC = 14;
	private static final Color FROM = new Color(0x161B26);
	private static final Color TO = new Color(0x222A3B);

	private PanelTiles() {
	}

	/** A rounded tile with a title, a line saying what the setting does, and a switch. */
	static final class Toggle extends JComponent {
		private final String title;
		private final String onText;
		private final String offText;
		private final Color accent;
		private final BooleanSupplier state;
		private final Runnable flip;
		/** Replaces the on/off line while it says something (e.g. "Paused while Inactive"); null: none. */
		private Supplier<String> override = () -> null;
		private boolean hover;

		Toggle(String title, String onText, String offText, Color accent, BooleanSupplier state, Runnable flip) {
			this.title = title;
			this.onText = onText;
			this.offText = offText;
			this.accent = accent;
			this.state = state;
			this.flip = flip;
			setPreferredSize(new Dimension(200, 46));
			setMinimumSize(new Dimension(120, 46));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			addMouseListener(new MouseAdapter() {
				@Override
				public void mouseEntered(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						hover = true;
						repaint();
					});
				}

				@Override
				public void mouseExited(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						hover = false;
						repaint();
					});
				}

				@Override
				public void mouseReleased(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						if (contains(e.getPoint())) {
							flip.run();
							repaint();
						}
					});
				}
			});
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				boolean on = state.getAsBoolean();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setPaint(new GradientPaint(0, 0, FROM, w, 0, on ? mix(TO, accent, 0.35f) : TO));
				g.fill(card);
				g.setStroke(new BasicStroke(hover ? 1.6f : 1f));
				g.setColor(alpha(on ? accent : new Color(0x4A5670), hover ? 230 : 150));
				g.draw(card);

				// The switch: a pill with a knob, the accent colour when on.
				int sw = 36;
				int sh = 18;
				int sx = w - sw - 12;
				int sy = (h - sh) / 2;
				g.setColor(on ? accent : new Color(0x3A4355));
				g.fillRoundRect(sx, sy, sw, sh, sh, sh);
				g.setColor(Color.WHITE);
				int knob = sh - 4;
				g.fillOval(on ? sx + sw - knob - 2 : sx + 2, sy + 2, knob, knob);

				g.setFont(FontManager.getRunescapeBoldFont());
				FontMetrics fm = g.getFontMetrics();
				shadow(g, fit(title, fm, sx - 20), 12, 19, Color.WHITE);
				g.setFont(FontManager.getRunescapeSmallFont());
				String why = override.get();
				shadow(g, fit(why != null ? why : on ? onText : offText, g.getFontMetrics(), sx - 20), 12, 35,
					on && why == null ? brighten(accent) : new Color(0xAEB6C4));
			} finally {
				g.dispose();
			}
		}

		/** Shows this line instead of the on/off text while it returns something. */
		Toggle withNote(Supplier<String> note) {
			override = note;
			return this;
		}
	}

	/**
	 * A rounded tile with a title, a row of chips of which one is picked (clicking another picks it), and
	 * a line saying what the picked one does: the boss page's gear mode.
	 */
	static final class Choice extends JComponent {
		private static final int CHIP_Y = 25;
		private static final int CHIP_H = 18;
		private final String title;
		private final String[] values;
		private final java.util.function.Function<String, String> label;
		private final java.util.function.Function<String, String> shortLabel;
		private final java.util.function.Function<String, String> describe;
		private final Color accent;
		private final Supplier<String> state;
		private final java.util.function.Consumer<String> pick;
		/** Replaces the description while it says something; null: none. */
		private Supplier<String> override = () -> null;
		private int hover = -1;

		Choice(String title, String[] values, java.util.function.Function<String, String> label, java.util.function.Function<String, String> shortLabel,
				java.util.function.Function<String, String> describe, Color accent, Supplier<String> state, java.util.function.Consumer<String> pick) {
			this.title = title;
			this.values = values.clone();
			this.label = label;
			this.shortLabel = shortLabel;
			this.describe = describe;
			this.accent = accent;
			this.state = state;
			this.pick = pick;
			setPreferredSize(new Dimension(200, 64));
			setMinimumSize(new Dimension(120, 64));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 64));
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			MouseAdapter mouse = new MouseAdapter() {
				@Override
				public void mouseMoved(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						int at = chipAt(e.getX(), e.getY());
						if (at != hover) {
							hover = at;
							repaint();
						}
					});
				}

				@Override
				public void mouseExited(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						hover = -1;
						repaint();
					});
				}

				@Override
				public void mouseReleased(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						int at = chipAt(e.getX(), e.getY());
						if (at >= 0) {
							pick.accept(Choice.this.values[at]);
							repaint();
						}
					});
				}
			};
			addMouseListener(mouse);
			addMouseMotionListener(mouse);
		}

		private int chipWidth() {
			return (getWidth() - 24 - 2 * 4) / values.length;
		}

		private int chipAt(int x, int y) {
			if (y < CHIP_Y || y > CHIP_Y + CHIP_H || x < 12) {
				return -1;
			}
			int i = (x - 12) / (chipWidth() + 4);
			return i < values.length ? i : -1;
		}

		/** Each chip says what it does. */
		@Override
		public String getToolTipText(MouseEvent e) {
			int at = chipAt(e.getX(), e.getY());
			return at < 0 ? super.getToolTipText(e) : label.apply(values[at]) + ": " + describe.apply(values[at]);
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				String on = state.get();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setPaint(new GradientPaint(0, 0, FROM, w, 0, mix(TO, accent, 0.2f)));
				g.fill(card);
				g.setColor(alpha(accent, 150));
				g.draw(card);

				g.setFont(FontManager.getRunescapeBoldFont());
				shadow(g, fit(title, g.getFontMetrics(), w - 24), 12, 18, Color.WHITE);

				g.setFont(FontManager.getRunescapeSmallFont());
				FontMetrics fm = g.getFontMetrics();
				int cw = chipWidth();
				boolean full = true;
				for (String v : values) {
					full &= fm.stringWidth(label.apply(v)) + 8 <= cw;
				}
				for (int i = 0; i < values.length; i++) {
					boolean picked = values[i].equals(on);
					int x = 12 + i * (cw + 4);
					RoundRectangle2D chip = new RoundRectangle2D.Float(x, CHIP_Y, cw, CHIP_H, CHIP_H, CHIP_H);
					g.setColor(picked ? mix(TO, accent, 0.55f) : i == hover ? new Color(0x2C3548) : new Color(0x1B2130));
					g.fill(chip);
					g.setColor(picked ? accent : new Color(0x4A5670));
					g.draw(chip);
					String text = fit(full ? label.apply(values[i]) : shortLabel.apply(values[i]), fm, cw - 6);
					shadow(g, text, x + (cw - fm.stringWidth(text)) / 2, CHIP_Y + 13, picked ? Color.WHITE : new Color(0xAEB6C4));
				}
				String why = override.get();
				shadow(g, fit(why != null ? why : on == null ? "" : describe.apply(on), fm, w - 24), 12, CHIP_Y + CHIP_H + 15, new Color(0xAEB6C4));
			} finally {
				g.dispose();
			}
		}

		/** Shows this line instead of the description while it returns something. */
		Choice withNote(Supplier<String> note) {
			override = note;
			return this;
		}
	}

	/**
	 * A card like {@link Info} with a picture on the right (same size and place, never dimmed), plus an
	 * Active / Inactive switch on its bottom row: the boss page's setup, the farm page's route.
	 */
	static final class SetupCard extends JComponent {
		private static final java.awt.Rectangle SWITCH_AREA = new java.awt.Rectangle(6, 46, 100, 24);
		private final String activeHeading;
		private final String selectedHeading;
		private final String activeTip;
		private final String inactiveTip;
		private final Color accent;
		private final Supplier<String[]> lines;
		private final Supplier<java.awt.image.BufferedImage> picture;
		private final BooleanSupplier hasSet;
		private final BooleanSupplier active;
		private final Runnable flip;
		/** Said before Active / Inactive ("Guide: Active"); null: nothing. */
		private String switchLabel;

		SetupCard(String activeHeading, String selectedHeading, String activeTip, String inactiveTip, Color accent, Supplier<String[]> lines,
				Supplier<java.awt.image.BufferedImage> picture, BooleanSupplier hasSet, BooleanSupplier active, Runnable flip) {
			this.activeHeading = activeHeading;
			this.selectedHeading = selectedHeading;
			this.activeTip = activeTip;
			this.inactiveTip = inactiveTip;
			this.accent = accent;
			this.lines = lines;
			this.picture = picture;
			this.hasSet = hasSet;
			this.active = active;
			this.flip = flip;
			setPreferredSize(new Dimension(200, 72));
			setMinimumSize(new Dimension(120, 72));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 72));
			// Registers the card with the tooltip manager; the text comes from getToolTipText(MouseEvent).
			setToolTipText("");
			addMouseListener(new MouseAdapter() {
				@Override
				public void mouseReleased(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						if (hasSet.getAsBoolean() && SWITCH_AREA.contains(e.getPoint())) {
							flip.run();
							repaint();
						}
					});
				}
			});
			addMouseMotionListener(new java.awt.event.MouseMotionAdapter() {
				@Override
				public void mouseMoved(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						boolean over = hasSet.getAsBoolean() && SWITCH_AREA.contains(e.getPoint());
						setCursor(Cursor.getPredefinedCursor(over ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
					});
				}
			});
		}

		/** Says what the switch is before Active / Inactive ("Guide: Active"). */
		SetupCard withSwitchLabel(String label) {
			switchLabel = label;
			return this;
		}

		@Override
		public String getToolTipText(MouseEvent e) {
			if (!hasSet.getAsBoolean() || !SWITCH_AREA.contains(e.getPoint())) {
				return null;
			}
			return active.getAsBoolean() ? activeTip : inactiveTip;
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setColor(new Color(0x1A1F2B));
				g.fill(card);
				g.setColor(new Color(0x313A4E));
				g.draw(card);
				boolean set = hasSet.getAsBoolean();
				boolean on = set && active.getAsBoolean();
				java.awt.image.BufferedImage img = picture.get();
				int textW = w - 24;
				if (img != null && img.getWidth() > 0) {
					// Same box and place as the other cards' pictures, at full quality whether Active or not.
					int box = 40;
					float scale = Math.min(box / (float) img.getWidth(), box / (float) img.getHeight());
					int iw = Math.round(img.getWidth() * scale);
					int ih = Math.round(img.getHeight() * scale);
					g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
					g.drawImage(img, w - 10 - box + (box - iw) / 2, (h - ih) / 2, iw, ih, null);
					textW = w - 24 - box - 6;
				}
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, on ? activeHeading : selectedHeading, 12, 16, new Color(0x8C96A8));
				String[] text = lines.get();
				if (text.length > 0) {
					g.setFont(FontManager.getRunescapeFont());
					shadow(g, fit(text[0], g.getFontMetrics(), textW), 12, 32, set && !on ? new Color(0x8C96A8) : Color.WHITE);
				}
				if (text.length > 1) {
					g.setFont(FontManager.getRunescapeSmallFont());
					shadow(g, fit(text[1], g.getFontMetrics(), textW), 12, 45, set && !on ? new Color(0x6B7385) : new Color(0xC9D1DE));
				}
				if (set) {
					int sx = 12;
					int sy = 50;
					g.setColor(on ? accent : new Color(0x3A4355));
					g.fillRoundRect(sx, sy, 30, 16, 16, 16);
					g.setColor(Color.WHITE);
					g.fillOval(on ? sx + 16 : sx + 2, sy + 2, 12, 12);
					g.setFont(FontManager.getRunescapeSmallFont());
					shadow(g, (switchLabel == null ? "" : switchLabel + ": ") + (on ? "Active" : "Inactive"), 48, 62,
						on ? brighten(accent) : new Color(0xAEB6C4));
				}
			} finally {
				g.dispose();
			}
		}
	}

	/** A card with a heading and up to a set number of lines: the first in white, the rest smaller (the slayer location). */
	static final class Lines extends JComponent {
		private final String heading;
		private final int count;
		private final Supplier<String[]> lines;
		private Supplier<String> tip = () -> null;

		Lines(String heading, int count, Supplier<String[]> lines) {
			this.heading = heading;
			this.count = count;
			this.lines = lines;
			int h = 38 + (count - 1) * 13 + 4;
			setPreferredSize(new Dimension(200, h));
			setMinimumSize(new Dimension(120, h));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		}

		/** A live tooltip (null: none). */
		Lines withTip(Supplier<String> tip) {
			this.tip = tip;
			// Registers the card with the tooltip manager; the text comes from getToolTipText(MouseEvent).
			setToolTipText("");
			return this;
		}

		@Override
		public String getToolTipText(MouseEvent e) {
			return tip.get();
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setColor(new Color(0x1A1F2B));
				g.fill(card);
				g.setColor(new Color(0x313A4E));
				g.draw(card);
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, heading, 12, 16, new Color(0x8C96A8));
				String[] text = lines.get();
				int y = 32;
				for (int i = 0; i < text.length && i < count; i++) {
					g.setFont(i == 0 ? FontManager.getRunescapeFont() : FontManager.getRunescapeSmallFont());
					shadow(g, fit(text[i], g.getFontMetrics(), w - 24), 12, y, i == 0 ? Color.WHITE : new Color(0xC9D1DE));
					y += i == 0 ? 15 : 13;
				}
			} finally {
				g.dispose();
			}
		}
	}

	/** A card with a heading and rows of a label and its value on the right (the slayer session's numbers). */
	static final class Stats extends JComponent {
		private static final int ROW = 14;
		private final String heading;
		private final Color accent;
		private final int count;
		private final Supplier<String[][]> rows;

		Stats(String heading, Color accent, int count, Supplier<String[][]> rows) {
			this.heading = heading;
			this.accent = accent;
			this.count = count;
			this.rows = rows;
			int h = 24 + count * ROW + 6;
			setPreferredSize(new Dimension(200, h));
			setMinimumSize(new Dimension(120, h));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setColor(new Color(0x1A1F2B));
				g.fill(card);
				g.setColor(alpha(accent, 120));
				g.draw(card);
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, heading, 12, 16, new Color(0x8C96A8));
				FontMetrics fm = g.getFontMetrics();
				String[][] all = rows.get();
				int y = 32;
				for (int i = 0; i < all.length && i < count; i++) {
					String label = all[i].length > 0 ? all[i][0] : "";
					String value = all[i].length > 1 && all[i][1] != null ? all[i][1] : "-";
					int vw = fm.stringWidth(value);
					shadow(g, fit(label, fm, w - 36 - vw), 12, y, new Color(0xAEB6C4));
					shadow(g, value, w - 12 - vw, y, i == 0 ? brighten(accent) : Color.WHITE);
					y += ROW;
				}
			} finally {
				g.dispose();
			}
		}
	}

	/** A quiet card with a heading and one or two lines of live text (current roadmap, route, setup). */
	static final class Info extends JComponent {
		private final String heading;
		private final Supplier<String[]> lines;
		private final Supplier<java.awt.image.BufferedImage> picture;

		Info(String heading, Supplier<String[]> lines) {
			this(heading, lines, () -> null);
		}

		/** With a picture on the right, like the tool tiles (the active boss, the next goal). */
		Info(String heading, Supplier<String[]> lines, Supplier<java.awt.image.BufferedImage> picture) {
			this.heading = heading;
			this.lines = lines;
			this.picture = picture;
			setPreferredSize(new Dimension(200, 54));
			setMinimumSize(new Dimension(120, 54));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 54));
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setColor(new Color(0x1A1F2B));
				g.fill(card);
				g.setColor(new Color(0x313A4E));
				g.draw(card);
				java.awt.image.BufferedImage img = picture.get();
				int textW = w - 24;
				if (img != null && img.getWidth() > 0) {
					int box = 40;
					float scale = Math.min(box / (float) img.getWidth(), box / (float) img.getHeight());
					int iw = Math.round(img.getWidth() * scale);
					int ih = Math.round(img.getHeight() * scale);
					g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
					g.drawImage(img, w - 10 - box + (box - iw) / 2, (h - ih) / 2, iw, ih, null);
					textW = w - 24 - box - 6;
				}
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, heading, 12, 16, new Color(0x8C96A8));
				String[] text = lines.get();
				g.setFont(FontManager.getRunescapeFont());
				FontMetrics fm = g.getFontMetrics();
				int y = 32;
				for (int i = 0; i < text.length && i < 2; i++) {
					g.setFont(i == 0 ? FontManager.getRunescapeFont() : FontManager.getRunescapeSmallFont());
					shadow(g, fit(text[i], g.getFontMetrics(), textW), 12, y, i == 0 ? Color.WHITE : new Color(0xC9D1DE));
					y += i == 0 ? 15 : 13;
				}
			} finally {
				g.dispose();
			}
		}
	}

	/** What a {@link Progress} card shows; null lines mean "nothing loaded" (then only the first two lines draw). */
	static final class ProgressState {
		final String[] lines;
		/** Big text inside the ring (the tier number), the ring's share (whole progression) and the bar's (this tier); -1: none. */
		final String badge;
		final float ring;
		final float bar;

		ProgressState(String[] lines, String badge, float ring, float bar) {
			this.lines = lines;
			this.badge = badge;
			this.ring = ring;
			this.bar = bar;
		}
	}

	/**
	 * A card like {@link Info} with a progress ring on the right (the whole progression, the current
	 * tier's number inside) and a bar under the text (the current tier).
	 */
	static final class Progress extends JComponent {
		private final String heading;
		private final Color accent;
		private final Supplier<ProgressState> state;

		Progress(String heading, Color accent, Supplier<ProgressState> state) {
			this.heading = heading;
			this.accent = accent;
			this.state = state;
			setPreferredSize(new Dimension(200, 64));
			setMinimumSize(new Dimension(120, 64));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 64));
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setColor(new Color(0x1A1F2B));
				g.fill(card);
				g.setColor(new Color(0x313A4E));
				g.draw(card);
				ProgressState s = state.get();
				int textW = w - 24;
				if (s.ring >= 0) {
					// The ring: a dim track, the done share in the accent from the top, the tier number inside.
					int d = 42;
					int rx = w - 10 - d;
					int ry = (h - d) / 2;
					g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
					g.setColor(new Color(0x2C3446));
					g.drawOval(rx + 3, ry + 3, d - 6, d - 6);
					g.setColor(accent);
					int arc = Math.round(360 * Math.min(1f, s.ring));
					if (arc > 0) {
						g.drawArc(rx + 3, ry + 3, d - 6, d - 6, 90, -arc);
					}
					g.setStroke(new BasicStroke(1f));
					if (s.badge != null) {
						g.setFont(FontManager.getRunescapeBoldFont());
						FontMetrics fm = g.getFontMetrics();
						shadow(g, s.badge, rx + (d - fm.stringWidth(s.badge)) / 2, ry + (d + fm.getAscent()) / 2 - 2, Color.WHITE);
					}
					textW = w - 24 - d - 6;
				}
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, heading, 12, 15, new Color(0x8C96A8));
				String[] text = s.lines;
				int y = 30;
				for (int i = 0; i < text.length && i < 2; i++) {
					g.setFont(i == 0 ? FontManager.getRunescapeFont() : FontManager.getRunescapeSmallFont());
					shadow(g, fit(text[i], g.getFontMetrics(), textW), 12, y, i == 0 ? Color.WHITE : new Color(0xC9D1DE));
					y += i == 0 ? 14 : 12;
				}
				if (s.bar >= 0) {
					int bw = textW;
					g.setColor(new Color(0x2C3446));
					g.fillRoundRect(12, h - 12, bw, 5, 5, 5);
					g.setColor(accent);
					int fill = Math.round(bw * Math.min(1f, s.bar));
					if (fill > 0) {
						g.fillRoundRect(12, h - 12, Math.max(5, fill), 5, 5, 5);
					}
				}
			} finally {
				g.dispose();
			}
		}
	}

	/**
	 * A tinted info card with an "i" mark: a heading, a short text (wrapped) and a link line; the whole card opens
	 * the link (where something is set up on the website).
	 */
	static final class Callout extends JComponent {
		private static final int TEXT_Y = 36;
		private static final int LINE = 13;
		private final String heading;
		private final String text;
		private final String link;
		private final Color accent;
		private boolean hover;

		Callout(String heading, String text, String link, Color accent, Runnable open) {
			this.heading = heading;
			this.text = text;
			this.link = link;
			this.accent = accent;
			setMinimumSize(new Dimension(120, 60));
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			addMouseListener(new MouseAdapter() {
				@Override
				public void mouseEntered(MouseEvent e) {
					hover = true;
					repaint();
				}

				@Override
				public void mouseExited(MouseEvent e) {
					hover = false;
					repaint();
				}

				@Override
				public void mouseReleased(MouseEvent e) {
					Guard.run(RoadmapPanel.GUARD_FEATURE, () -> {
						if (contains(e.getPoint())) {
							open.run();
						}
					});
				}
			});
		}

		private java.util.List<String> lines(int width) {
			FontMetrics fm = getFontMetrics(FontManager.getRunescapeSmallFont());
			java.util.List<String> out = new java.util.ArrayList<>();
			String line = "";
			for (String word : text.split(" ")) {
				String next = line.isEmpty() ? word : line + " " + word;
				if (!line.isEmpty() && fm.stringWidth(next) > width) {
					out.add(line);
					next = word;
				}
				line = next;
			}
			out.add(line);
			return out;
		}

		@Override
		public Dimension getPreferredSize() {
			int w = getWidth() > 0 ? getWidth() : 205;
			return new Dimension(w, TEXT_Y + lines(w - 26).size() * LINE + 15);
		}

		@Override
		public Dimension getMaximumSize() {
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}

		@Override
		protected void paintComponent(Graphics graphics) {
			Graphics2D g = (Graphics2D) graphics.create();
			try {
				smooth(g);
				int w = getWidth();
				int h = getHeight();
				RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, ARC, ARC);
				g.setColor(mix(new Color(0x1A1F2B), accent, hover ? 0.16f : 0.1f));
				g.fill(card);
				g.setClip(card);
				g.setColor(accent);
				g.fillRect(0, 0, 3, h);
				g.setClip(null);
				g.setColor(alpha(accent, hover ? 210 : 120));
				g.draw(card);
				// The "i" mark.
				g.setColor(alpha(accent, 70));
				g.fillOval(12, 7, 14, 14);
				g.setColor(accent);
				g.setStroke(new BasicStroke(1.2f));
				g.drawOval(12, 7, 14, 14);
				g.fillRect(18, 13, 2, 5);
				g.fillRect(18, 10, 2, 2);
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, fit(heading, g.getFontMetrics(), w - 44), 32, 19, brighten(accent));
				int y = TEXT_Y;
				for (String line : lines(w - 26)) {
					shadow(g, line, 14, y, new Color(0xC9D1DE));
					y += LINE;
				}
				y += 4;
				shadow(g, link, 14, y, hover ? Color.WHITE : brighten(accent));
				if (hover) {
					g.fillRect(14, y + 2, g.getFontMetrics().stringWidth(link), 1);
				}
			} finally {
				g.dispose();
			}
		}
	}

	private static void smooth(Graphics2D g) {
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color) {
		g.setColor(new Color(0, 0, 0, 170));
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String fit(String s, FontMetrics fm, int width) {
		if (s == null) {
			return "";
		}
		if (fm.stringWidth(s) <= width) {
			return s;
		}
		String t = s;
		while (t.length() > 1 && fm.stringWidth(t + "...") > width) {
			t = t.substring(0, t.length() - 1);
		}
		return t + "...";
	}

	private static Color alpha(Color c, int a) {
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}

	private static Color mix(Color a, Color b, float t) {
		return new Color(Math.round(a.getRed() + (b.getRed() - a.getRed()) * t), Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	private static Color brighten(Color c) {
		return mix(c, Color.WHITE, 0.35f);
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks the plank sack from its per-plank varbits (exact, no interface
 * needed), feeding the goal tracker live and uploading bank-memory source
 * {@code plank_sack} through a debounced {@link SourceSyncer}.
 */
@Slf4j
@Singleton
public class PlankSackMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "plank-sack-sync";

	static final String SOURCE = "plank_sack";

	/** Varbit to the plank item it counts. */
	static final Map<Integer, Integer> PLANK_VARBITS;

	static {
		Map<Integer, Integer> m = new LinkedHashMap<>();
		Tables.list("plankSack").forEach(p -> m.put(Tables.id(p.getAsJsonArray().get(0)), Tables.id(p.getAsJsonArray().get(1))));
		PLANK_VARBITS = java.util.Collections.unmodifiableMap(m);
	}

	private final Client client;
	private final SourceSyncer syncer;

	private boolean dirty;
	private GameState previousGameState = GameState.UNKNOWN;

	@Inject
	public PlankSackMonitor(
			Client client,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			Gson gson,
			ScheduledExecutorService executor) {
		executor = GuardedExecutor.wrap(GUARD_FEATURE, executor);
		this.client = client;
		this.syncer = new SourceSyncer(SOURCE, gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
		this.syncer.setPriorityFlush(apiClient::requestOutboxFlush);
	}

	public void stop() {
		syncer.stop();
		dirty = false;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (PLANK_VARBITS.containsKey(event.getVarbitId())) {
				dirty = true;
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				dirty = true;
			} else if (SyncGuard.isLogout(previousGameState, newState)) {
				syncer.flushPending();
			}
			previousGameState = newState;
		});
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!dirty) {
				return;
			}
			dirty = false;
			Map<Integer, Integer> contents = contents(client::getVarbitValue);
			syncer.submit(contents, false);
		});
	}

	/** Plank item id to count from the varbit values. */
	static Map<Integer, Integer> contents(IntUnaryOperator varbitValue) {
		Map<Integer, Integer> contents = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> e : PLANK_VARBITS.entrySet()) {
			int count = varbitValue.applyAsInt(e.getKey());
			if (count > 0) {
				contents.put(e.getValue(), count);
			}
		}
		return contents;
	}
}

package com.osrscompanion;

import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.PlayerSkillsSyncPayload;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Uploads skill levels and XP: on login, on logout, and while training (at most
 * every {@link #TRAINING_SYNC_INTERVAL_SECONDS} while XP is actually rising) so
 * the server can keep roadmap skill goals current without waiting for logout.
 * The XP drop that reaches a skill goal of the roadmap shown goes up at once, and
 * the roadmaps are re-read when it has arrived, so the goal ticks off in about a second.
 */
@Slf4j
@Singleton
public class PlayerSkillsMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "skills-sync";

	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	/** How often to re-upload while training; nothing is sent when XP is static. */
	static final int TRAINING_SYNC_INTERVAL_SECONDS = 10;

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final RoadmapManager roadmapManager;

	private GameState previousGameState = GameState.UNKNOWN;
	/** Last XP seen per skill (client thread); the first value after login is the replay. */
	private final Map<String, Integer> lastSeenXp = new HashMap<>();
	private volatile boolean xpDirty;
	private ScheduledFuture<?> trainingTask;

	@Inject
	public PlayerSkillsMonitor(
			Client client,
			ClientThread clientThread,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ScheduledExecutorService executorService,
			RoadmapManager roadmapManager) {
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.roadmapManager = roadmapManager;
	}

	public void start() {
		if (trainingTask == null) {
			trainingTask = executorService.scheduleAtFixedRate(this::syncIfDirty,
					TRAINING_SYNC_INTERVAL_SECONDS, TRAINING_SYNC_INTERVAL_SECONDS, TimeUnit.SECONDS);
		}
	}

	public void stop() {
		if (trainingTask != null) {
			trainingTask.cancel(false);
			trainingTask = null;
		}
		previousGameState = GameState.UNKNOWN;
		lastSeenXp.clear();
		xpDirty = false;
	}

	/** Re-runs the skills sync now (App Key entered while logged in, or the roadmap's "Sync &amp; refresh"). */
	public void forceSync() {
		syncOnClientThread();
	}

	/** The game is read on the client thread only: RuneLite asserts it for varbits and the local player. */
	private void syncOnClientThread() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> syncPlayerSkills());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();

			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				executorService.schedule(this::syncOnClientThread, LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
			} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
				lastSeenXp.clear();
				xpDirty = false;
				syncPlayerSkills();
			}

			previousGameState = newState;
		});
	}

	@Subscribe
	public void onStatChanged(StatChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			Integer previous = lastSeenXp.put(event.getSkill().getName(), event.getXp());
			if (xpIncreased(previous, event.getXp())) {
				xpDirty = true;
				if (roadmapManager.reachesSkillGoal(event.getSkill().getName(), previous, event.getXp())) {
					xpDirty = false;
					syncPlayerSkills(roadmapManager::refreshAllQuietly);
				}
			}
		});
	}

	/** True only for a real gain: the first observation after login is the server
	 * replay, and boosted-level events carry the same XP. */
	static boolean xpIncreased(Integer previous, int now) {
		return previous != null && now > previous;
	}

	private void syncIfDirty() {
		if (!xpDirty || client.getGameState() != GameState.LOGGED_IN) {
			return;
		}
		xpDirty = false;
		syncOnClientThread();
	}

	/**
	 * Reads all skill levels and XP from the client, builds a payload with
	 * total and combat levels, and sends it to the OSRS Companion API. Client thread.
	 */
	private void syncPlayerSkills() {
		syncPlayerSkills(null);
	}

	/** The upload; {@code onSuccess} runs once the website has it (OkHttp thread). */
	private void syncPlayerSkills(Runnable onSuccess) {
		if (!SyncGuard.hasAppKey(config)) {
			return;
		}
		if (!config.syncSkills()) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Player skills sync skipped: could not get player username");
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) {
			return;
		}
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		int totalLevel = 0;

		for (Skill skill : Skill.values()) {
			int level = client.getRealSkillLevel(skill);
			int xp = client.getSkillExperience(skill);
			skills.put(skill.getName(), new PlayerSkillsSyncPayload.SkillData(level, xp));
			totalLevel += level;
		}

		int combatLevel = localPlayer.getCombatLevel();

		// Account type (Group Ironman helmet on the website): varbit IRONMAN, sent only when it names an iron type.
		Integer accountType = PlayerSkillsSyncPayload.accountTypeOf(client.getVarbitValue(VarbitID.IRONMAN));
		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload(playerUsername, skills, totalLevel, combatLevel, accountType);
		apiClient.sendPlayerSkillsSync(payload, onSuccess);
	}
}

package com.osrscompanion;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;
import java.util.regex.Pattern;

/**
 * This plugin's version (for example {@code 1.0.0}), from {@code version.properties}. It is set by
 * hand for each Plugin Hub release, so every build of the same commit reports the same version.
 */
public final class PluginVersion {
	static final String RESOURCE = "version.properties";
	/** What a version may look like: it is sent as an HTTP header and stored by the website. */
	private static final Pattern SAFE = Pattern.compile("[0-9A-Za-z._-]{1,32}");
	private static final String FALLBACK = "0.0";

	/** This build's version, for example {@code 1.0.0}. */
	public static final String VERSION = resolve(load(RESOURCE));

	private PluginVersion() {
	}

	/** "OSRS Companion v1.0.0", for the side panel. */
	public static String label() {
		return "OSRS Companion v" + VERSION;
	}

	/** The file's version, or {@value #FALLBACK} when it is missing or not header-safe. */
	static String resolve(Properties props) {
		String v = props == null ? null : props.getProperty("version");
		v = v == null ? null : v.trim();
		return v != null && SAFE.matcher(v).matches() ? v : FALLBACK;
	}

	private static Properties load(String name) {
		try (InputStream in = PluginVersion.class.getResourceAsStream(name)) {
			if (in == null) {
				return null;
			}
			Properties p = new Properties();
			p.load(in);
			return p;
		} catch (IOException | RuntimeException e) {
			return null;
		}
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.BankSyncPayload;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;
import net.runelite.api.GameState;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors potion storage contents and syncs them to the OSRS Companion API.
 * Potion storage is not a regular container — doses are tracked in VarPlayers
 * and must be read via client scripts.
 */
@Slf4j
@Singleton
public class PotionStorageMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "potion-storage-sync";

	private static final String SOURCE = "potion_storage";
	private static final int MAX_DOSES = 4;

	private final Client client;
	private final OSRSCompanionConfig config;
	private final SourceSyncer syncer;

	private Set<Integer> potionStoreVarps;
	private boolean needsRebuild;
	/** Re-read on every game tick up to this one (the doses can arrive a tick or two after the bank opens). */
	private int readUntilTick = -1;
	private GameState previousGameState = GameState.UNKNOWN;

	@Inject
	public PotionStorageMonitor(
			Client client,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			Gson gson,
			ScheduledExecutorService executor) {
		executor = GuardedExecutor.wrap(GUARD_FEATURE, executor);
		this.client = client;
		this.config = config;
		this.syncer = new SourceSyncer(SOURCE, gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
		this.syncer.setPriorityFlush(apiClient::requestOutboxFlush);
	}

	public void stop() {
		syncer.stop();
		potionStoreVarps = null;
		needsRebuild = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (SyncGuard.isLogout(previousGameState, newState)) {
				syncer.flushPending();
			}
			previousGameState = newState;
		});
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.BANKMAIN) {
				needsRebuild = true;
				readUntilTick = client.getTickCount() + 3;
			}
		});
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (readUntilTick >= 0 && client.getTickCount() <= readUntilTick && client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null) {
				needsRebuild = true;
			} else {
				readUntilTick = -1;
			}
		});
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (potionStoreVarps != null && potionStoreVarps.contains(event.getVarpId())) {
				needsRebuild = true;
			}
		});
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload()) {
				potionStoreVarps = null;
			}
		});
	}

	/**
	 * On client tick, if a potion store varp changed, rebuild potion data and sync.
	 * We process on ClientTick (like RuneLite's PotionStorage) so the script runs
	 * on the client thread before the CS2 VM updates widgets.
	 */
	@Subscribe
	public void onClientTick(ClientTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!needsRebuild) {
				return;
			}
			needsRebuild = false;

			if (!config.syncBankMemory() || !SyncGuard.hasAppKey(config)) {
				return;
			}
			if (GameModeUtil.isSpecialGameMode(client)) {
				return;
			}

			// The varps that change with the storage (to re-read on a change), from its widget once the bank
			// has built it. The storage is read either way: it needn't have been opened.
			if (potionStoreVarps == null) {
				Widget w = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
				int[] triggers = w == null ? null : w.getVarTransmitTrigger();
				if (triggers != null) {
					potionStoreVarps = new HashSet<>();
					Arrays.stream(triggers).forEach(potionStoreVarps::add);
				}
			}

			Map<Integer, Integer> quantities = new LinkedHashMap<>();
			for (BankSyncPayload.BankItem item : collectPotionItems()) {
				quantities.merge(item.getItemId(), item.getQuantity(), Integer::sum);
			}
			// Nothing read before the storage's varps are known may only mean they haven't arrived yet:
			// never clear what the website has on that.
			if (quantities.isEmpty() && potionStoreVarps == null) {
				return;
			}
			syncer.submit(quantities, false);
		});
	}

	/**
	 * Reads all potions from potion storage using game enums and client scripts.
	 * Each potion is stored as its 4-dose item ID (or highest available dose for mixes).
	 */
	private List<BankSyncPayload.BankItem> collectPotionItems() {
		List<BankSyncPayload.BankItem> items = new ArrayList<>();

		EnumComposition potions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
		EnumComposition unfinished = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);

		for (EnumComposition enumComp : new EnumComposition[]{potions, unfinished}) {
			for (int potionEnumId : enumComp.getIntVals()) {
				EnumComposition potionEnum = client.getEnum(potionEnumId);

				client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
				int totalDoses = client.getIntStack()[0];

				if (totalDoses <= 0) {
					continue;
				}

				// Find the highest dose variant available for this potion
				int maxDose = findMaxDose(potionEnum);
				int itemId = potionEnum.getIntValue(maxDose);
				int quantity = totalDoses / maxDose;
				int remainderDoses = totalDoses % maxDose;

				if (quantity > 0) {
					items.add(new BankSyncPayload.BankItem(itemId, quantity));
				}

				// Add remainder as lower-dose item if applicable
				if (remainderDoses > 0) {
					int remainderItemId = potionEnum.getIntValue(remainderDoses);
					items.add(new BankSyncPayload.BankItem(remainderItemId, 1));
				}
			}
		}

		int vials = client.getVarpValue(VarPlayerID.POTIONSTORE_VIALS);
		if (vials > 0) {
			items.add(new BankSyncPayload.BankItem(ItemID.VIAL_EMPTY, vials));
		}

		return items;
	}

	/** Finds the highest dose key (4, 3, 2, or 1) that has a valid item ID in the enum. */
	private int findMaxDose(EnumComposition potionEnum) {
		for (int dose = MAX_DOSES; dose >= 1; dose--) {
			int itemId = potionEnum.getIntValue(dose);
			if (itemId > 0) {
				return dose;
			}
		}
		return 1;
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.QuestsSyncPayload;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.*;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's quest progress and syncs it to the OSRS Companion API.
 *
 * <p>Reads every quest's state via RuneLite's {@link Quest} enum + {@link QuestState}
 * (the same source WikiSync uses) and pushes a {questName: status} map where status is
 * 0 = not started, 1 = in progress, 2 = completed. Using {@link Quest#getName()} for the
 * keys reproduces WikiSync's exact names (including the Recipe for Disaster subquests),
 * so the backend consumes the payload unchanged.
 *
 * <p>Triggers: a sync on login (after a short delay so quest varps have loaded) and on
 * logout, plus a near-real-time sync when a quest completes. Quest state changes flip a
 * varp, so we mark a re-check on {@link VarbitChanged} and read+dedupe on the next
 * {@link GameTick} (throttled), which collapses varp churn to at most one read per few
 * ticks. A JSON equality check means an unchanged quest set is never resent.
 *
 * <p>A quest RuneLite's {@link Quest} enum doesn't list yet (a brand-new release) is
 * invisible to that read, so two more sources fill the gap. The game builds its quest
 * list from a database table and RuneLite's client fires a {@code questFilter} script
 * callback for each row it lays out; the row ids collected there give every quest's
 * display name and, through the same script the enum uses, its state. And the
 * quest-complete scroll names any quest as it finishes, so a name read from it is
 * carried as completed for the rest of the login session. The scroll text is parsed
 * the way RuneLite's own screenshot plugin parses it.
 */
@Singleton
public class QuestMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "quest-sync";

	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	// Minimum ticks between varp-driven reads, so continuous varp churn during play
	// doesn't re-read every quest every tick. A quest completion still syncs within
	// a few ticks, and login/logout syncs are the safety net.
	private static final int RESYNC_THROTTLE_TICKS = 3;

	// "You have completed The Corsair Curse!" / "'One Small Favour' completed!"
	private static final Pattern QUEST_PATTERN_1 = Pattern.compile(
			".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: [Qq]uest)?[!.]?$");
	private static final Pattern QUEST_PATTERN_2 = Pattern.compile(
			"'?(?<quest>.+?)'?(?: [Qq]uest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$");
	// Recipe for Disaster subquests announce "You have freed/defeated/saved ...".
	private static final List<String> RFD_TAGS = Arrays.asList("Another Cook", "freed", "defeated", "saved");
	// Quests whose name ends in "Quest", which the patterns strip.
	private static final List<String> WORD_QUEST_IN_NAME_TAGS = Arrays.asList(
			"Another Cook", "Doric", "Heroes", "Legends", "Observatory", "Olaf", "Waterfall");

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean questCheckPending;
	private boolean questScrollPending;
	/** Quest names read from the quest-complete scroll this login session. */
	private final Set<String> completedFromScroll = new HashSet<>();
	/** Quest table row ids seen while the game laid out its quest list. */
	private final Set<Integer> questRows = new HashSet<>();
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public QuestMonitor(
			Client client,
			ClientThread clientThread,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson) {
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		questCheckPending = false;
		questScrollPending = false;
		completedFromScroll.clear();
		questRows.clear();
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the current quest states on the client thread. Used by the
	 * roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			lastSyncJson = null;
			syncQuests();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				// Quest varps load shortly after LOGGED_IN, so wait before reading.
				executorService.schedule(() -> Guard.invokeLater(clientThread, GUARD_FEATURE, this::syncQuests),
						LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
			} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
				// Logging out: flush final state (this handler runs on the client thread).
				syncQuests();
			}
			if (newState == GameState.LOGIN_SCREEN) {
				// Scroll completions belong to the account that was logged in.
				completedFromScroll.clear();
			}
			previousGameState = newState;
		});
	}

	/**
	 * The game lays out its quest list from the quest table, and RuneLite's client
	 * calls back once per row with the row id on top of the int stack (the row below it
	 * is the hide flag, left untouched). Rows are only collected here; names and states
	 * are read on the next sync.
	 */
	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!"questFilter".equals(event.getEventName())) {
				return;
			}
			int[] intStack = client.getIntStack();
			int size = client.getIntStackSize();
			if (size < 1) {
				return;
			}
			if (questRows.add(intStack[size - 1])) {
				questCheckPending = true;
			}
		});
	}

	/** The quest-complete scroll opened; read its title once its text is set. */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.QUESTSCROLL) {
				questScrollPending = true;
			}
		});
	}

	/** A quest state change flips a varp; mark a re-check for the next game tick. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			questCheckPending = true;
		});
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (questScrollPending) {
				questScrollPending = false;
				readQuestScroll();
			}
			if (!questCheckPending) {
				return;
			}
			if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
				return;
			}
			questCheckPending = false;
			lastReadTick = client.getTickCount();
			syncQuests();
		});
	}

	/** Reads the quest name off the quest-complete scroll and syncs it as completed. */
	private void readQuestScroll() {
		Widget title = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
		String name = title == null ? null : parseQuestCompletedScroll(title.getText());
		if (name == null) {
			return;
		}
		if (completedFromScroll.add(name)) {
			questCheckPending = false;
			lastReadTick = client.getTickCount();
			syncQuests();
		}
	}

	/**
	 * The quest named by the quest-complete scroll's title text, or null when the text
	 * isn't a completion. Mirrors RuneLite's screenshot plugin: Recipe for Disaster
	 * subquests are prefixed, and names the scroll shortens get their "Quest" back.
	 */
	static String parseQuestCompletedScroll(String text) {
		if (text == null) {
			return null;
		}
		Matcher m1 = QUEST_PATTERN_1.matcher(text);
		Matcher m2 = QUEST_PATTERN_2.matcher(text);
		Matcher match = m1.matches() ? m1 : m2;
		if (!match.matches()) {
			return null;
		}
		String quest = match.group("quest");
		String verb = match.group("verb") != null ? match.group("verb") : "";
		if (verb.contains("kind of")) {
			return null; // a partial completion is not a completion
		}
		if (verb.contains("completely")) {
			quest += " II";
		}
		String questAndVerb = quest + verb;
		if (RFD_TAGS.stream().anyMatch(questAndVerb::contains)) {
			quest = "Recipe for Disaster - " + quest;
		}
		if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(quest::contains)) {
			quest += " Quest";
		}
		return quest;
	}

	/** Reads all quest states, builds the payload, and syncs (deduped). Client thread only. */
	private void syncQuests() {
		if (!config.syncQuests() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		// Sorted keys give a stable JSON ordering so the dedup check is reliable.
		Map<String, Integer> questStates = new TreeMap<>();
		for (Quest quest : Quest.values()) {
			questStates.put(quest.getName(), toStatus(quest.getState(client)));
		}
		// Quests the enum doesn't list, read from the game's own quest table; the
		// enum's read wins for names it has.
		for (int row : questRows) {
			String name = questRowName(row);
			if (name != null && !questStates.containsKey(name)) {
				questStates.put(name, questRowStatus(row));
			}
		}
		// Completions the enum can't see yet; the enum's own read wins for names it has.
		for (String name : completedFromScroll) {
			questStates.putIfAbsent(name, 2);
		}

		QuestsSyncPayload payload = new QuestsSyncPayload(playerUsername, questStates);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			return;
		}
		lastSyncJson = json;
		apiClient.sendQuestsSync(payload);
	}

	/** A quest row's display name, or null when the row can't be read. */
	private String questRowName(int row) {
		try {
			Object[] field = client.getDBTableField(row, DBTableID.Quest.COL_DISPLAYNAME, 0);
			return field != null && field.length > 0 && field[0] instanceof String ? (String) field[0] : null;
		} catch (RuntimeException e) {
			return null;
		}
	}

	/** A quest row's status (0/1/2), read the same way {@link Quest#getState} does. */
	private int questRowStatus(int row) {
		client.runScript(ScriptID.QUEST_STATUS_GET, row);
		return statusFromScript(client.getIntStack()[0]);
	}

	/**
	 * Maps the raw {@code QUEST_STATUS_GET} result to the WikiSync status code, mirroring
	 * {@link Quest#getState}: 2 is finished, 1 is not started, anything else in progress.
	 */
	static int statusFromScript(int raw) {
		if (raw == 2) {
			return 2;
		}
		return raw == 1 ? 0 : 1;
	}

	/** Maps a RuneLite {@link QuestState} to the WikiSync status code (0/1/2). */
	private static int toStatus(QuestState state) {
		if (state == QuestState.FINISHED) {
			return 2;
		}
		if (state == QuestState.IN_PROGRESS) {
			return 1;
		}
		return 0;
	}
}

package com.osrscompanion;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.LongSupplier;

/**
 * Coalesces roadmap re-reads: a periodic refresh plus debounced on-demand
 * requests. Several requests inside the delay window collapse into one read that
 * fires after the <em>last</em> request, so a burst of uploads produces a single
 * fetch once they have all landed. A read already in flight defers the next one
 * briefly instead of stacking requests, and reads are at least
 * {@link #MIN_INTERVAL_SECONDS} apart: a player uploading every few seconds
 * gets one re-read a minute, not one per upload.
 */
final class ReconcileScheduler {
	static final int PERIODIC_MINUTES = 10;
	static final int RETRY_WHEN_BUSY_SECONDS = 5;
	static final int MIN_INTERVAL_SECONDS = 60;
	/** A pending read closer than this counts as "syncing" for the UI hint. */
	static final int SYNCING_HINT_SECONDS = 15;

	private final ScheduledExecutorService executor;
	private final Runnable refresh;
	private final LongSupplier clockMs;
	private final AtomicBoolean inFlight = new AtomicBoolean();

	private ScheduledFuture<?> periodic;
	private ScheduledFuture<?> pending;
	private boolean busyRetryUsed;
	private long lastFireMs = Long.MIN_VALUE;
	private long pendingDueMs;

	ReconcileScheduler(ScheduledExecutorService executor, Runnable refresh) {
		this(executor, refresh, System::currentTimeMillis);
	}

	ReconcileScheduler(ScheduledExecutorService executor, Runnable refresh, LongSupplier clockMs) {
		this.executor = executor;
		this.refresh = refresh;
		this.clockMs = clockMs;
	}

	/** Re-read after {@code delaySeconds}, or once the minimum interval since
	 * the last read has passed if that is later; replaces any pending request. */
	synchronized void request(int delaySeconds) {
		if (pending != null) {
			pending.cancel(false);
		}
		long delayMs = TimeUnit.SECONDS.toMillis(Math.max(0, delaySeconds));
		if (lastFireMs != Long.MIN_VALUE) {
			long earliestMs = lastFireMs + TimeUnit.SECONDS.toMillis(MIN_INTERVAL_SECONDS);
			delayMs = Math.max(delayMs, earliestMs - clockMs.getAsLong());
		}
		pendingDueMs = clockMs.getAsLong() + delayMs;
		pending = executor.schedule(this::firePending, delayMs, TimeUnit.MILLISECONDS);
	}

	/** Starts the periodic refresh; safe to call more than once. */
	synchronized void startPeriodic() {
		if (periodic == null) {
			periodic = executor.scheduleAtFixedRate(
					this::firePeriodic, PERIODIC_MINUTES, PERIODIC_MINUTES, TimeUnit.MINUTES);
		}
	}

	synchronized void stop() {
		if (periodic != null) {
			periodic.cancel(false);
			periodic = null;
		}
		if (pending != null) {
			pending.cancel(false);
			pending = null;
		}
		inFlight.set(false);
		busyRetryUsed = false;
		lastFireMs = Long.MIN_VALUE;
	}

	/** True while a re-read is scheduled or running. */
	synchronized boolean isBusy() {
		return pending != null || inFlight.get();
	}

	/** True while a re-read is running or due within {@link #SYNCING_HINT_SECONDS}.
	 * Drives the "Syncing" hint: a read held back by the minimum interval
	 * would otherwise show it for up to a minute. */
	synchronized boolean isSyncingSoon() {
		if (inFlight.get()) {
			return true;
		}
		return pending != null
				&& pendingDueMs - clockMs.getAsLong() <= TimeUnit.SECONDS.toMillis(SYNCING_HINT_SECONDS);
	}

	/** Claims the in-flight slot; false when a read is already running. */
	boolean markInFlight() {
		return inFlight.compareAndSet(false, true);
	}

	void clearInFlight() {
		inFlight.set(false);
	}

	private void firePending() {
		synchronized (this) {
			pending = null;
		}
		fire();
	}

	/** The periodic read also answers any request still waiting, so drop it
	 * (left scheduled, a later request could no longer cancel it). */
	private void firePeriodic() {
		synchronized (this) {
			if (pending != null) {
				pending.cancel(false);
				pending = null;
			}
		}
		fire();
	}

	private void fire() {
		synchronized (this) {
			if (inFlight.get()) {
				// Let the running read finish; try once more shortly after.
				if (!busyRetryUsed) {
					busyRetryUsed = true;
					request(RETRY_WHEN_BUSY_SECONDS);
				}
				return;
			}
			busyRetryUsed = false;
			lastFireMs = clockMs.getAsLong();
		}
		refresh.run();
	}
}

package com.osrscompanion;

import com.osrscompanion.model.RoadmapSummary;
import java.util.*;
import java.util.concurrent.TimeUnit;

/**
 * The player's last fetched roadmap list, reused by background refreshes so they
 * re-read only the roadmaps themselves. Roadmaps created or deleted elsewhere
 * show up once the list is older than {@link #REUSE_MS} (the periodic refresh
 * always is) or when the panel opens.
 */
final class RoadmapListCache {
	static final long REUSE_MS = TimeUnit.MINUTES.toMillis(5);

	private String player;
	private List<RoadmapSummary> summaries;
	private long fetchedAtMs;

	synchronized void record(String player, List<RoadmapSummary> summaries, long nowMs) {
		this.player = player;
		this.summaries = summaries == null
				? Collections.emptyList()
				: Collections.unmodifiableList(new ArrayList<>(summaries));
		this.fetchedAtMs = nowMs;
	}

	/** The list to reuse for {@code player}, or null when it has to be fetched. */
	synchronized List<RoadmapSummary> reusable(String player, long nowMs) {
		if (summaries == null || this.player == null || !this.player.equals(player)) {
			return null;
		}
		return nowMs - fetchedAtMs < REUSE_MS ? summaries : null;
	}

	/** Forget the list (a roadmap read failed, or the session ended). */
	synchronized void invalidate() {
		summaries = null;
		player = null;
	}
}

package com.osrscompanion;

import lombok.Getter;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.Roadmap;
import com.osrscompanion.model.RoadmapGoal;
import com.osrscompanion.model.RoadmapList;
import com.osrscompanion.model.RoadmapSummary;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;

/**
 * Shared roadmap state for the side panel and the overlay.
 *
 * <p>Holds the currently selected roadmap id (persisted per RuneLite profile via
 * {@link ConfigManager}) and the last fetched {@link Roadmap}, so the panel and
 * the overlay render the same data without each issuing their own requests. All
 * mutation happens through here; the panel drives fetches, the overlay reads the
 * cached roadmap.
 *
 * <p>Also owns the background reconciliation: a periodic re-read of every one
 * of the player's roadmaps plus debounced re-reads requested shortly after data
 * uploads, so the server's view of goal progress reaches the plugin without the
 * panel open. Every fetched roadmap is handed to the roadmap listener (the goal
 * tracker); only the selected one becomes the overlay's current roadmap.
 *
 * <p>The roadmap's background work runs on its own small daemon thread ({@link #executor()}), never
 * on RuneLite's shared executor: every plugin's scheduled jobs share that one thread, so a slow
 * roadmap pass there (a "Slow: roadmap took 4667 ms on pool-2-thread-1") held all of them up. The
 * thread exists only while roadmap work is scheduled.
 */
@Slf4j
@Singleton
public class RoadmapManager {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "roadmap";

	static final String CONFIG_GROUP = "osrscompanion";
	static final String SELECTED_ROADMAP_KEY = "selectedRoadmapId";
	static final String COMPLETED_EXPANDED_KEY = "completedGoalsExpanded";
	static final String THREAD_NAME = "osrs-companion-roadmap";
	/** The roadmap thread ends after this long without work. */
	static final long IDLE_SECONDS = 30;

	private final Client client;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;
	private final ReconcileScheduler scheduler;
	private final RoadmapListCache listCache = new RoadmapListCache();

	/** The last fetched roadmap (may be null), used by the overlay. */
	@Getter
	private volatile Roadmap currentRoadmap;
	/** Hears every fetched roadmap, selected or not; set by the plugin. */
	private volatile Consumer<Roadmap> roadmapListener;
	/** Hears the player's current set of roadmap ids after each list fetch. */
	private volatile Consumer<Set<Integer>> roadmapSetListener;
	/** Hears roadmaps that arrived from a background refresh; set by the open panel. */
	private volatile Consumer<Roadmap> panelListener;
	private volatile boolean panelActive;

	/**
	 * How often {@link #pollWhileWaiting()} looks for a roadmap while the box has none: a backstop, as
	 * a roadmap made on the website is picked up by the web version check ({@link WebVersionWatcher}); this
	 * also retries a load that failed at login.
	 */
	static final int WAITING_POLL_SECONDS = 2 * 60;

	@Inject
	public RoadmapManager(
			Client client,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ConfigManager configManager) {
		this.executor = GuardedExecutor.wrap(GUARD_FEATURE, newOwnExecutor());
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.scheduler = new ReconcileScheduler(executor, this::refreshAllQuietly);
	}

	/**
	 * The roadmap's own executor: one daemon thread, started on demand and ended after
	 * {@value #IDLE_SECONDS} s without work, so nothing is left running once the plugin stops (its
	 * periodic jobs are cancelled then). Its tasks are run through the {@link Guard}.
	 */
	ScheduledExecutorService executor() {
		return executor;
	}

	static ScheduledThreadPoolExecutor newOwnExecutor() {
		ScheduledThreadPoolExecutor ex = new ScheduledThreadPoolExecutor(1, r -> {
			Thread t = new Thread(r, THREAD_NAME);
			t.setDaemon(true);
			t.setUncaughtExceptionHandler((th, e) -> log.warn("Roadmap thread failed", e));
			return t;
		});
		ex.setKeepAliveTime(IDLE_SECONDS, TimeUnit.SECONDS);
		ex.allowCoreThreadTimeOut(true);
		ex.setRemoveOnCancelPolicy(true);
		return ex;
	}

	/** The logged-in RS username, or null if not logged in. */
	public String getPlayerUsername() {
		return SyncGuard.getPlayerUsername(client);
	}

	public boolean hasAppKey() {
		return SyncGuard.hasAppKey(config);
	}

	void setCurrentRoadmap(Roadmap roadmap) {
		this.currentRoadmap = roadmap;
	}

	void clear() {
		setCurrentRoadmap(null);
		listCache.invalidate();
	}

	public void setRoadmapListener(Consumer<Roadmap> listener) {
		this.roadmapListener = listener;
	}

	public void setRoadmapSetListener(Consumer<Set<Integer>> listener) {
		this.roadmapSetListener = listener;
	}

	/** Every fetched roadmap goes to the tracker; the selected one also becomes current. */
	private void onRoadmapFetched(Roadmap roadmap) {
		Consumer<Roadmap> listener = roadmapListener;
		if (listener != null) {
			listener.accept(roadmap);
		}
		Integer selected = getSelectedRoadmapId();
		if (selected != null && selected == roadmap.getCollectionId()) {
			setCurrentRoadmap(roadmap);
		}
	}

	/**
	 * Makes a roadmap the active one (a goal in it just completed): persists the
	 * selection, swaps the overlay's roadmap and lets an open panel follow.
	 */
	public void selectRoadmap(Roadmap roadmap) {
		if (roadmap == null) {
			return;
		}
		Integer selected = getSelectedRoadmapId();
		if (selected == null || selected != roadmap.getCollectionId()) {
			setSelectedRoadmapId(roadmap.getCollectionId());
		}
		setCurrentRoadmap(roadmap);
	}

	public void setPanelListener(Consumer<Roadmap> listener) {
		this.panelListener = listener;
	}

	/** Asks an open panel to re-render the cached roadmap (local progress changed). */
	public void notifyPanel() {
		Roadmap roadmap = currentRoadmap;
		Consumer<Roadmap> listener = panelListener;
		if (roadmap != null && listener != null) {
			listener.accept(roadmap);
		}
	}

	public Integer getSelectedRoadmapId() {
		return configManager.getConfiguration(
				CONFIG_GROUP, SELECTED_ROADMAP_KEY, Integer.class);
	}

	public void setSelectedRoadmapId(int collectionId) {
		configManager.setConfiguration(CONFIG_GROUP, SELECTED_ROADMAP_KEY, collectionId);
	}

	/** Whether the panel's "Completed (N)" list is expanded; collapsed by default. */
	public boolean isCompletedGoalsExpanded() {
		Boolean expanded = configManager.getConfiguration(
				CONFIG_GROUP, COMPLETED_EXPANDED_KEY, Boolean.class);
		return expanded != null && expanded;
	}

	/**
	 * Tells the tracker which roadmaps exist and fetches each one that the caller
	 * is not already fetching itself, so goals in every roadmap are tracked.
	 *
	 * @param skipId roadmap the caller fetches on its own (may be null)
	 * @param onDone runs once every fetch has finished (may be null)
	 */
	private void onRoadmapListFetched(RoadmapList list, String player, Runnable onDone) {
		List<RoadmapSummary> summaries = list.getRoadmaps();
		listCache.record(player, summaries, System.currentTimeMillis());
		Set<Integer> ids = new HashSet<>();
		for (RoadmapSummary summary : summaries) {
			ids.add(summary.getCollectionId());
		}
		Consumer<Set<Integer>> setListener = roadmapSetListener;
		if (setListener != null) {
			setListener.accept(ids);
		}
		Integer selected = getSelectedRoadmapId();
		if (summaries.isEmpty()) {
			// No roadmaps (any more): the box has nothing to show.
			setCurrentRoadmap(null);
		} else if (selected == null || !ids.contains(selected)) {
			// None picked yet, or the picked one was deleted on the website: show the first.
			setSelectedRoadmapId(summaries.get(0).getCollectionId());
		}
		fetchEach(summaries, player, onDone);
	}

	/** Fetches each roadmap and feeds it to the tracker; {@code onDone} runs once
	 * all have finished. A failed read drops the cached list (the roadmap may be
	 * gone), so the next refresh fetches the list again. */
	private void fetchEach(List<RoadmapSummary> summaries, String player, Runnable onDone) {
		if (summaries.isEmpty()) {
			if (onDone != null) {
				onDone.run();
			}
			return;
		}
		AtomicInteger remaining = new AtomicInteger(summaries.size());
		for (RoadmapSummary summary : summaries) {
			apiClient.getRoadmap(summary.getCollectionId(), player, new OSRSCompanionApiClient.RoadmapCallback<Roadmap>() {
				@Override
				public void onSuccess(Roadmap result) {
					onRoadmapFetched(result);
					finish();
				}

				@Override
				public void onError(String message) {
					listCache.invalidate();
					finish();
				}

				private void finish() {
					if (remaining.decrementAndGet() == 0 && onDone != null) {
						onDone.run();
					}
				}
			});
		}
	}

	// ------------------------------------------------------- reconciliation

	/** Starts the periodic background re-read of the selected roadmap. */
	public void startPeriodicRefresh() {
		scheduler.startPeriodic();
	}

	public void stopPeriodicRefresh() {
		scheduler.stop();
	}

	/**
	 * Called every {@link #WAITING_POLL_SECONDS}: while the roadmap box is on but has no roadmap
	 * to show (none loaded yet, or none made on the website yet), re-reads the list fresh, so a
	 * roadmap shows without opening the goal overview.
	 */
	public void pollWhileWaiting() {
		if (currentRoadmap != null || !config.showNextGoal() || !hasAppKey()) {
			return;
		}
		listCache.invalidate();
		refreshAllQuietly();
	}

	/**
	 * Whether XP rising from {@code before} to {@code now} in the skill reaches an unfinished skill goal of the
	 * roadmap shown ("Runecraft" matches a "runecrafting" goal).
	 */
	public boolean reachesSkillGoal(String skill, int before, int now) {
		Roadmap roadmap = currentRoadmap;
		for (RoadmapGoal g : roadmap == null ? Collections.<RoadmapGoal>emptyList() : roadmap.getGoals()) {
			Long at = g.getCompletingXp();
			if (at != null && g.getSkillName() != null && g.getSkillName().toLowerCase().startsWith(skill.toLowerCase()) && before < at && now >= at) {
				return true;
			}
		}
		return false;
	}

	/** Re-reads the roadmap list and every roadmap now (the website changed something). */
	public void refreshAllFresh() {
		listCache.invalidate();
		refreshAllQuietly();
	}

	/** True while a server re-read is running or about to (drives "Syncing" hints). */
	public boolean isSyncing() {
		return scheduler.isSyncingSoon();
	}

	/**
	 * Refreshes every roadmap silently (no UI callback): the list (reused while
	 * recent, see {@link RoadmapListCache}), then each roadmap's rendered goals.
	 * Runs on login, on the periodic schedule and after uploads that can move a
	 * goal, so goal progress in any roadmap reaches the plugin even when the
	 * panel is closed. A plain GET re-evaluates goals server-side, so no
	 * recompute call is needed.
	 */
	public void refreshAllQuietly() {
		if (!hasAppKey() || (!config.showNextGoal() && !panelActive)) {
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN || GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String player = getPlayerUsername();
		if (player == null) {
			return;
		}
		if (!scheduler.markInFlight()) {
			return;
		}
		notifyPanel();
		Runnable done = () -> {
			scheduler.clearInFlight();
			notifyPanel();
		};
		List<RoadmapSummary> known = listCache.reusable(player, System.currentTimeMillis());
		if (known != null) {
			fetchEach(known, player, done);
			return;
		}
		apiClient.getRoadmaps(player, new OSRSCompanionApiClient.RoadmapCallback<RoadmapList>() {
			@Override
			public void onSuccess(RoadmapList result) {
				onRoadmapListFetched(result, player, done);
			}

			@Override
			public void onError(String message) {
				scheduler.clearInFlight();
				notifyPanel();
			}
		});
	}

}

package com.osrscompanion;

import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.BossGear;
import com.osrscompanion.model.FarmRoute;
import com.osrscompanion.model.Roadmap;
import com.osrscompanion.model.RoadmapGoal;
import com.osrscompanion.model.SlayerGuide;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Insets;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JViewport;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.LinkBrowser;
import net.runelite.api.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The OSRS Companion side panel: a menu of five tool tiles (like the website's tool banners).
 * Each opens its own page with a Back tile, what is active, its on/off settings (e.g. whether the
 * bank lays out the boss setup or farm route) and a tile to open its window over the game.
 */
public class RoadmapPanel extends PluginPanel {
	/** The side panel's feature for {@link Guard}: its tiles' mouse listeners and its refresh timer. */
	static final String GUARD_FEATURE = "side-panel";
	private static final Color ROADMAP = new Color(0x60A5FA);
	private static final Color FARM = new Color(0x4ADE80);
	private static final Color BOSS = new Color(0xA78BFA);
	private static final Color SLAYER = new Color(0xF87171);
	private static final Color TRIPS = new Color(0x2DD4BF);

	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final GoalImageCache images;
	private final OSRSCompanionConfig config;
	private final ConfigManager configManager;
	private final RoadmapManager roadmapManager;
	private final FarmRunManager farmRun;
	private final BossGearManager bossGear;
	private final SlayerHelperManager slayer;
	private final ClientThread clientThread;

	private final CardLayout cards = new CardLayout();
	/** The pages; only as tall as the page on show (a card layout is as tall as its tallest page). */
	private final JPanel deck = new JPanel(cards) {
		@Override
		public Dimension getPreferredSize() {
			for (Component c : getComponents()) {
				if (c.isVisible()) {
					Dimension d = c.getPreferredSize();
					Insets in = getInsets();
					return new Dimension(d.width + in.left + in.right, d.height + in.top + in.bottom);
				}
			}
			return super.getPreferredSize();
		}
	};
	/** The boss page's gear display and the gap under the tile above it, shown while its setting is on. */
	private BossGearPanelView gearView;
	private Component gearViewGap;
	/** The slayer page's session numbers and the gap under them, shown while a session is going. */
	private JComponent slayerStats;
	private Component slayerStatsGap;
	/** The slayer debug switch and its gap: shown only for the developer's characters. */
	/** The Slayer skill icon, loaded in the background (the task card's picture). */
	private volatile java.awt.image.BufferedImage slayerIcon;
	/** Keeps the live cards (current roadmap, route, setup) and switches up to date while the panel is open. */
	private final Timer refresh = new Timer(1000, e -> Guard.run(GUARD_FEATURE, this::tick));

	public RoadmapPanel(Runnable openFarmRun, Runnable openBossGear, Runnable openSlayerGear,
			ItemManager itemManager, SpriteManager spriteManager, GoalImageCache images, OSRSCompanionConfig config, ConfigManager configManager,
			RoadmapManager roadmapManager, FarmRunManager farmRun, BossGearManager bossGear,
			SlayerHelperManager slayer, ClientThread clientThread) {
		super(false);
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		this.images = images;
		this.config = config;
		this.configManager = configManager;
		this.roadmapManager = roadmapManager;
		this.farmRun = farmRun;
		this.bossGear = bossGear;
		this.slayer = slayer;
		this.clientThread = clientThread;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		deck.add(mainMenu(), "main");
		deck.add(roadmapPage(), "roadmap");
		deck.add(farmPage(openFarmRun), "farm");
		deck.add(bossPage(openBossGear), "boss");
		deck.add(slayerPage(openSlayerGear), "slayer");
		deck.add(tripsPage(), "trips");
		// The boss page's gear display is tall: the pages scroll.
		JPanel top = new JPanel(new BorderLayout());
		top.add(deck, BorderLayout.NORTH);
		JScrollPane scroll = new JScrollPane(top, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED, ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		// Paint everything again on scroll: the default (copying the pixels already drawn) leaves the
		// hand-painted tiles grey until they are hovered.
		scroll.getViewport().setScrollMode(JViewport.SIMPLE_SCROLL_MODE);
		scroll.getVerticalScrollBar().addAdjustmentListener(e -> scroll.getViewport().repaint());
		add(scroll, BorderLayout.CENTER);
		tick();

		JLabel note = new JLabel("<html><body style='width:170px'><i>Progress updates as you play and "
			+ "syncs with the website in the background.</i><br><br>" + PluginVersion.label() + "</body></html>");
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setBorder(BorderFactory.createEmptyBorder(10, 0, 0, 0));
		add(note, BorderLayout.SOUTH);
	}

	/**
	 * Repaints the live cards, shows or hides the boss gear display with its setting, and lays the
	 * page out again when the display's height changed (a set loaded, switched or went Inactive).
	 */
	/** The Slayer helper page's gear (the website's DPS setups); laid out again when its height changes. */
	private SlayerGearPanelView slayerGear;

	private void tick() {
		if (gearView != null) {
			boolean showGear = config.bossGearPanelDisplay();
			if (gearView.isVisible() != showGear) {
				gearView.setVisible(showGear);
				gearViewGap.setVisible(showGear);
				deck.revalidate();
			} else if (showGear && gearView.getHeight() != gearView.getPreferredSize().height) {
				gearView.revalidate();
			}
			// The display needs the setup loaded, like opening the Boss page does.
			if (showGear && bossGear.getSet() == null && !bossGear.isLoading() && !bossGear.isLoaded() && bossGear.getError() == null) {
				bossGear.refresh();
			}
		}
		if (slayerGear != null && slayerGear.getHeight() != slayerGear.getPreferredSize().height) {
			// The setups loaded or another one is on show: its height changes.
			slayerGear.revalidate();
		}
		if (slayerStats != null) {
			boolean showStats = slayer.getStats() != null;
			if (slayerStats.isVisible() != showStats) {
				slayerStats.setVisible(showStats);
				slayerStatsGap.setVisible(showStats);
				deck.revalidate();
			}
		}
		deck.repaint();
	}

	@Override
	public void onActivate() {
		refresh.start();
	}

	@Override
	public void onDeactivate() {
		refresh.stop();
	}

	// ---- Pages --------------------------------------------------------------------------

	private JPanel mainMenu() {
		JPanel p = page();
		JLabel title = new JLabel("OSRS Companion");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(title);
		p.add(Box.createVerticalStrut(10));
		add(p, roadmapTile(() -> show("roadmap")), "Roadmap: your goals and settings.");
		add(p, farmTile(() -> show("farm")), "Farm run: your route, bank layout and the farm run window.");
		add(p, bossTile(() -> show("boss")), "Boss gear: your build, bank layout, gear display and the boss gear window.");
		add(p, slayerTile(() -> show("slayer")), "Slayer helper: your task, the best place to do it, a guide there and your kill stats.");
		add(p, tripsTile(() -> show("trips")), "Trip planner: how many boss trips and farm runs the supplies in your bank last.");
		add(p, websiteTile(), "Open the OSRS Companion website in your browser.");
		return p;
	}

	/** Opens the website in the browser. */
	private FeatureTile websiteTile() {
		String base = OSRSCompanionApiClient.BASE_URL;
		String host = base.replaceFirst("^https?://", "");
		return FeatureTile.banner("OPEN", "WEBSITE", host, new Color(0x60A5FA), new Color(0x0B1220), new Color(0x1D4ED8), null,
			() -> LinkBrowser.browse(base + "/home"));
	}

	private JPanel roadmapPage() {
		JPanel p = page();
		add(p, back(), "Back to all tools");
		add(p, new PanelTiles.Info("SELECTED ROADMAP", () -> {
			Roadmap r = roadmapManager.getCurrentRoadmap();
			if (r == null) {
				return new String[]{"No roadmap loaded yet", "Make one on the website: it shows within 30 s"};
			}
			RoadmapGoal next = r.firstIncompleteGoal();
			return new String[]{r.getTitle(), next == null ? "Every goal is done!" : "Next: " + next.getName()};
		}, () -> {
			Roadmap r = roadmapManager.getCurrentRoadmap();
			RoadmapGoal next = r == null ? null : r.firstIncompleteGoal();
			return next == null ? null : images.get(next.getImageUrl());
		}), null);
		add(p, new PanelTiles.Callout("SET UP ON THE WEBSITE", "Pick your roadmap, add goals and change their order on the website. Changes show here within 30 seconds.",
			"Open your roadmaps >", ROADMAP, () -> LinkBrowser.browse(OSRSCompanionApiClient.BASE_URL + "/tools/roadmap")), "Opens the roadmaps on the OSRS Companion website.");
		add(p, toggle("Roadmap box", "Next goal in the game", "Hidden", ROADMAP, "showNextGoal", config::showNextGoal), null);
		add(p, toggle("Goal popup", "Popup on completion", "No popup", ROADMAP, "showGoalPopup", config::showGoalPopup), null);
		return p;
	}

	private JPanel farmPage(Runnable openWindow) {
		JPanel p = page();
		add(p, back(), "Back to all tools");
		// The route, with a switch that starts (Active) or stops (Inactive) the run.
		add(p, new PanelTiles.SetupCard("ACTIVE ROUTE", "SELECTED ROUTE",
			"Active: the run is going (guide, bank layout). Click to stop it.",
			"Inactive: no run going. Click to start the run at its first stop.", FARM, () -> {
			FarmRoute r = farmRun.getRoute();
			if (r == null) {
				return new String[]{"No route loaded yet", "Make one on the website, then open the window"};
			}
			int[] done = farmRun.progress();
			String state = farmRun.isRunning() ? (farmRun.isComplete() ? "Run complete" : "Running: " + done[0] + " / " + done[1] + " patches")
				: r.isReady() ? "READY - every crop ready" : "Not running";
			return new String[]{r.getName(), state};
		}, () -> {
			FarmRoute r = farmRun.getRoute();
			Integer item = r == null ? null : r.pictureItem();
			return item == null ? null : itemManager.getImage(item);
		}, () -> farmRun.getRoute() != null, farmRun::isRunning, () -> {
			// Starting reads the patches' state from the game: on the client thread.
			Guard.invoke(clientThread, FarmRunManager.GUARD_FEATURE, () -> {
				if (farmRun.isRunning()) {
					farmRun.stop();
				} else {
					farmRun.start();
				}
			});
			deck.repaint();
		}), null);
		add(p, toggle("Active in the bank", "Bank shows items during a run", "Bank left alone", FARM, "farmRunBankFilter", config::farmRunBankFilter)
			.withNote(() -> config.farmRunBankFilter() && !config.showFarmRun() ? "Paused while the guide is off" : null),
			"Only one bank layout is active at a time: turning this on turns the other bank layouts off.");
		add(p, toggle("Run guide", "Arrow + patch outlines", "Guide hidden", FARM, "showFarmRun", config::showFarmRun), null);
		add(p, overview("ROUTE", "OVERVIEW", "Stops and what to bring", FARM, new Color(0x08130C), new Color(0x166534), SpriteID.MINIMAP_ORB_WORLD_MAP_PLANET, openWindow).iconSize(28),
			"Open or close the farm run window: stops, what to bring, start or stop the run, switch route (Escape closes it).");
		return p;
	}

	private JPanel bossPage(Runnable openWindow) {
		JPanel p = page();
		add(p, back(), "Back to all tools");
		add(p, new PanelTiles.SetupCard("ACTIVE SETUP", "SELECTED SETUP",
			"Active: the bank lays out this setup and the gear display shows it. Click to set Inactive (the setup stays selected).",
			"Inactive: the setup stays selected, but the bank is left alone and no gear is shown. Click to set Active.", BOSS, () -> {
			BossGear s = bossGear.getSet();
			if (s == null) {
				return new String[]{bossGear.isLoading() ? "Loading..." : "No setup picked yet", "Load one in Gear overview"};
			}
			return new String[]{s.getBossName(), buildLabel(s)};
		}, () -> {
			BossGear s = bossGear.getSet();
			return s == null ? null : images.get(s.getImage());
		}, () -> bossGear.getSet() != null, bossGear::isSetActive, () -> {
			bossGear.setSetActive(!bossGear.isSetActive());
			deck.repaint();
		}), null);
		add(p, toggle("Bank layout", "Bank shows this setup", "Bank left alone", BOSS, "bossGearBankLayout", config::bossGearBankLayout)
			.withNote(() -> bossGear.getSet() != null && !bossGear.isSetActive() && config.bossGearBankLayout() ? "Paused while Inactive" : null),
			"Only one bank layout is active at a time: turning this on turns the other bank layouts off.");
		add(p, toggle("Gear display", "Shown below", "Hidden", BOSS, "bossGearPanelDisplay", config::bossGearPanelDisplay)
			.withNote(() -> bossGear.getSet() != null && !bossGear.isSetActive() && config.bossGearPanelDisplay() ? "Hidden while Inactive" : null),
			"Show the active setup's worn gear, inventory and rune pouch in this panel.");
		add(p, new PanelTiles.Choice("Gear mode", BossGear.MODES, BossGear::modeLabel, BossGear::modeShortLabel, BossGear::modeDescription, BOSS,
			bossGear::getMode, m -> {
				bossGear.setMode(m);
				deck.repaint();
			}).withNote(() -> isCustomBuild(bossGear.getSet()) ? "Wiki presets only: custom builds unchanged" : null),
			"Which gear wiki presets bring: Best in slot (always the wiki's best, owned or not), Best owned (the best you own from the wiki's "
				+ "list) or Owned alternatives (also your best item of the setup's style where you own none of the list, marked A). "
				+ "Synced with the website's Boss Gear page.");
		add(p, overview("GEAR", "OVERVIEW", "Load a preset or build", BOSS, new Color(0x120A24), new Color(0x5B21B6), SpriteID.TAB_EQUIPMENT, openWindow),
			"Open or close the boss gear window: the setup's gear and inventory; load a wiki preset or one of your custom builds there (Escape closes it).");
		gearView = new BossGearPanelView(bossGear, itemManager);
		gearView.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(gearView);
		gearViewGap = Box.createVerticalStrut(8);
		p.add(gearViewGap);
		return p;
	}

	/** The trip planner: a switch per tool for the supplies box beside the bank (trips / runs your bank lasts). */
	private JPanel tripsPage() {
		JPanel p = page();
		add(p, back(), "Back to all tools");
		add(p, toggle("Boss trips", "Shown in the bank", "Hidden", TRIPS, OSRSCompanionConfig.TRIP_PLANNER_BOSS_KEY, config::tripPlannerBoss),
			"With the bank open: how many trips your bank's supplies last for the active boss setup and which one runs out first (no bank layout needed).");
		add(p, toggle("Farm runs", "Shown in the bank", "Hidden", TRIPS, OSRSCompanionConfig.TRIP_PLANNER_FARM_KEY, config::tripPlannerFarm),
			"With the bank open: how many runs your bank's supplies last for the farm route and which one runs out first (no bank layout needed).");
		add(p, toggle("Count runes", "Runes count", "Runes left out", TRIPS, OSRSCompanionConfig.TRIP_PLANNER_RUNES_KEY, config::tripPlannerRunes),
			"Whether runes (teleports, spells, the rune pouch) count towards the trips and runs; off, they never limit them.");
		return p;
	}

	private JPanel slayerPage(Runnable openGearWindow) {
		JPanel p = page();
		add(p, back(), "Back to all tools");
		// The task, with the switch that turns the guide to its location on (Active) or off.
		add(p, new PanelTiles.SetupCard("TASK - GUIDE ON", "SLAYER TASK",
			"Active: the guide leads you to the location (step box, arrow, Slayer icon on the world map). Click to turn it off.",
			"Inactive: no guide. Click to be guided to the task's location.", SLAYER, this::slayerTaskLines,
			() -> slayerIcon, () -> true, config::slayerGuide, () -> {
				configManager.setConfiguration(OSRSCompanionConfig.CONFIG_GROUP, "slayerGuide", !config.slayerGuide());
				deck.repaint();
			}).withSwitchLabel("Guide"), null);
		slayerStats = new PanelTiles.Stats("AT THE LOCATION", SLAYER, 10, this::slayerStatRows);
		add(p, slayerStats, "This visit to the task's location: it is sent to the website, which charts it per task.");
		slayerStatsGap = p.getComponent(p.getComponentCount() - 1);
		slayerStats.setVisible(false);
		slayerStatsGap.setVisible(false);
		add(p, new PanelTiles.Lines("LOCATION", 3, this::slayerLocationLines).withTip(() -> {
			SlayerGuide.Location l = slayer.getLocation();
			return l == null || l.getRequirements().isEmpty() ? null : "Needs: " + String.join(", ", l.getRequirements());
		}), null);
		add(p, toggle("Bank layout", "Bank shows this setup", "Bank left alone", SLAYER, "slayerGearBankLayout", config::slayerGearBankLayout)
			.withNote(() -> config.slayerGearBankLayout() && !config.slayerGuide() ? "Paused while the guide is off" : null),
			"Only one bank layout is active at a time: turning this on turns the other bank layouts off.");
		add(p, overview("GEAR", "OVERVIEW", "Pick a DPS setup", SLAYER, new Color(0x1F0A0A), new Color(0x991B1B), SpriteID.TAB_EQUIPMENT, openGearWindow),
			"Open or close the slayer gear window: the website's DPS setups against the task's monster; pick the one to use (Escape closes it).");
		// The setup picked in the window (the best until one is picked), against the task's monster.
		slayerGear = new SlayerGearPanelView(slayer, itemManager);
		add(p, slayerGear, null);
		spriteManager.getSpriteAsync(SpriteID.SKILL_SLAYER, 0, img -> {
			slayerIcon = img;
			SwingUtilities.invokeLater(deck::repaint);
		});
		return p;
	}

	private String[] slayerTaskLines() {
		SlayerHelperManager.Task t = slayer.getTask();
		if (t == null) {
			return new String[]{"No slayer task", "Get one from a slayer master"};
		}
		String master = slayer.getMaster();
		return new String[]{t.displayName(), t.remaining + " left" + (t.original > 0 ? " of " + t.original : "") + (master != null ? " - " + master : "")};
	}

	private String[] slayerLocationLines() {
		SlayerGuide.Location l = slayer.getLocation();
		if (l != null) {
			SlayerGuide.Location here = slayer.getHere();
			String name = (here != null && here.getKey() != null && here.getKey().equals(l.getKey()) ? "Here: " : "") + l.getName()
				+ (l.isMulti() ? " (multi)" : "");
			return new String[]{name, l.getWhy(), l.getTravel() == null ? "" : "Way there: " + l.getTravel().getName()};
		}
		if (slayer.getTask() == null) {
			return new String[]{"No task, no location", "", ""};
		}
		if (slayer.isFetchingForTask()) {
			return new String[]{"Retrieving location and gear", "information for the new task...", ""};
		}
		if (slayer.getError() != null) {
			return new String[]{"No location loaded", slayer.getError(), ""};
		}
		if (!slayer.isGuideForTask()) {
			return new String[]{"No location data was found", "The website doesn't have this task yet", "(it needs Slayer sync on)"};
		}
		return new String[]{"No location data was found", "The website has no locations", "for this task yet"};
	}

	private String[][] slayerStatRows() {
		SlayerHelperManager.Stats s = slayer.getStats();
		SlayerHelperManager.Task t = slayer.getTask();
		if (s == null) {
			return new String[0][];
		}
		long now = System.currentTimeMillis();
		long time = s.timeInArea(now);
		return new String[][]{
			{"In the area", slayer.getHere() != null ? "Yes" : "No"},
			{"Time at location", SlayerFormat.clock(time)},
			{"Trip timer", SlayerFormat.clock(s.total(now))},
			{"Kills", String.valueOf(s.kills)},
			{"TTK", s.avgKillMs > 0 ? SlayerFormat.seconds(s.avgKillMs) : "-"},
			{"Time per kill", s.kills > 0 && time > 0 ? SlayerFormat.seconds(time / s.kills) : "-"},
			{"Kills/h", s.kills > 0 && time > 0 ? String.valueOf(Math.round(s.kills * 3_600_000.0 / time)) : "-"},
			{"Est. time left", s.estimatedLeftMs > 0 && t != null ? SlayerFormat.clock(s.estimatedLeftMs) : "-"},
			{"Loot", SlayerFormat.gp(s.lootGp)},
			{"Avg loot / kill", s.kills > 0 ? SlayerFormat.gp(s.avgLootGp) : "-"}};
	}

	/** Whether the loaded build is one of your custom builds (owned alternatives apply to wiki presets only). */
	private boolean isCustomBuild(BossGear s) {
		if (s == null) {
			return false;
		}
		for (BossGear.SetSummary sum : bossGear.getSets()) {
			if (sum.getId() == s.getId()) {
				return sum.isCustom();
			}
		}
		return false;
	}

	/** The build's name under the boss: your own name for a custom build, else the wiki setup's style. */
	private String buildLabel(BossGear s) {
		for (BossGear.SetSummary sum : bossGear.getSets()) {
			if (sum.getId() == s.getId() && sum.isCustom()) {
				return sum.getLabel() + " (custom build)";
			}
		}
		return s.getStyle() + " (wiki preset)";
	}

	// ---- Pieces -----------------------------------------------------------------------------

	private void show(String page) {
		// The pages show what is active: load it when it isn't yet.
		if ("boss".equals(page) && bossGear.getSet() == null && !bossGear.isLoading()) {
			bossGear.refresh();
		} else if ("farm".equals(page)) {
			farmRun.refreshIfStale();
		} else if ("slayer".equals(page)) {
			slayer.refreshIfStale();
		}
		cards.show(deck, page);
		deck.revalidate();
		deck.repaint();
	}

	/** A full-size tile that opens the tool's window, with the game's own interface icon (loaded in the background). */
	private FeatureTile overview(String white, String accentWord, String subtitle, Color accent, Color from, Color to, int spriteId, Runnable action) {
		FeatureTile tile = FeatureTile.banner(white, accentWord, subtitle, accent, from, to, null, action);
		spriteManager.getSpriteAsync(spriteId, 0, img -> SwingUtilities.invokeLater(() -> tile.setIcon(img)));
		return tile;
	}

	private FeatureTile back() {
		return FeatureTile.banner("< BACK", "", "All tools", new Color(0x94A3B8), new Color(0x10141C), new Color(0x334155), null, () -> show("main"));
	}

	private FeatureTile roadmapTile(Runnable action) {
		return FeatureTile.banner("ROAD", "MAP", "Your goals, tracked as you play",
			ROADMAP, new Color(0x0D1530), new Color(0x1E40AF), itemManager.getImage(ItemID.SKILLCAPE_QP), action);
	}

	private FeatureTile farmTile(Runnable action) {
		return FeatureTile.banner("FARM", "RUN", "Route & guided run",
			FARM, new Color(0x08130C), new Color(0x166534), itemManager.getImage(ItemID.WATERING_CAN_8), action);
	}

	private FeatureTile bossTile(Runnable action) {
		return FeatureTile.banner("BOSS", "GEAR", "Builds + bank layout",
			BOSS, new Color(0x120A24), new Color(0x5B21B6), itemManager.getImage(ItemID.VORKATH_HEAD), action);
	}

	private FeatureTile slayerTile(Runnable action) {
		return FeatureTile.banner("SLAYER", "HELPER", "Task, best spot & kill stats",
			SLAYER, new Color(0x1F0A0A), new Color(0x991B1B), itemManager.getImage(ItemID.SLAYER_HELM), action);
	}

	/** The bank chest picture: the planner counts what is in your bank, for boss trips and farm runs alike. */
	private FeatureTile tripsTile(Runnable action) {
		FeatureTile tile = FeatureTile.banner("TRIP", "PLANNER", "Trips from bank supplies",
			TRIPS, new Color(0x05171A), new Color(0x0F766E), null, action);
		spriteManager.getSpriteAsync(SpriteID.WELCOME_SCREEN_BANK_CHEST, 0, img -> SwingUtilities.invokeLater(() -> tile.setIcon(img)));
		return tile;
	}

	/** An on/off tile for a boolean setting of this plugin. */
	private PanelTiles.Toggle toggle(String title, String on, String off, Color accent, String key, java.util.function.BooleanSupplier value) {
		return new PanelTiles.Toggle(title, on, off, accent, value,
			() -> configManager.setConfiguration(OSRSCompanionConfig.CONFIG_GROUP, key, !value.getAsBoolean()));
	}

	private static JPanel page() {
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		return p;
	}

	private static void add(JPanel page, JComponent tile, String tooltip) {
		tile.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (tooltip != null) {
			tile.setToolTipText(tooltip);
		}
		page.add(tile);
		page.add(Box.createVerticalStrut(8));
	}
