package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GameState;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks the rune pouch (regular, divine and colossal: up to six slots) from
 * its varbits, which the game keeps current whether the pouch is carried or
 * banked. Every change is handed to the goal tracker so rune goals move
 * live, and uploaded as bank-memory source {@code rune_pouch} through a
 * debounced {@link SourceSyncer} (casting drains a rune per tick).
 */
@Slf4j
@Singleton
public class RunePouchMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "rune-pouch-sync";

	static final String SOURCE = "rune_pouch";

	private static final int[] TYPE_VARBITS = Tables.ids(Tables.list("runePouchTypes"));
	private static final int[] QUANTITY_VARBITS = Tables.ids(Tables.list("runePouchQuantities"));

	private final Client client;
	private final SourceSyncer syncer;

	private boolean dirty;
	private GameState previousGameState = GameState.UNKNOWN;

	@Inject
	public RunePouchMonitor(
			Client client,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			Gson gson,
			ScheduledExecutorService executor) {
		executor = GuardedExecutor.wrap(GUARD_FEATURE, executor);
		this.client = client;
		this.syncer = new SourceSyncer(SOURCE, gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
		this.syncer.setPriorityFlush(apiClient::requestOutboxFlush);
	}

	public void stop() {
		syncer.stop();
		dirty = false;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (isPouchVarbit(event.getVarbitId())) {
				dirty = true;
			}
		});
	}

	/** True for the rune pouch's slot type and quantity varbits. */
	static boolean isPouchVarbit(int id) {
		for (int i = 0; i < TYPE_VARBITS.length; i++) {
			if (id == TYPE_VARBITS[i] || id == QUANTITY_VARBITS[i]) {
				return true;
			}
		}
		return false;
	}

	/** The pouch's runes now (item id to quantity), whether it is carried or not. Client thread. */
	static Map<Integer, Integer> read(Client client) {
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null) {
			return new LinkedHashMap<>();
		}
		int[] types = new int[TYPE_VARBITS.length];
		int[] quantities = new int[QUANTITY_VARBITS.length];
		for (int i = 0; i < TYPE_VARBITS.length; i++) {
			types[i] = client.getVarbitValue(TYPE_VARBITS[i]);
			quantities[i] = client.getVarbitValue(QUANTITY_VARBITS[i]);
		}
		return contents(types, quantities, runes::getIntValue);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				dirty = true; // push the pouch as it is at login
			} else if (SyncGuard.isLogout(previousGameState, newState)) {
				syncer.flushPending();
			}
			previousGameState = newState;
		});
	}

	/** Reads on the game tick so a burst of varbit changes is read once. */
	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!dirty) {
				return;
			}
			dirty = false;
			if (client.getEnum(EnumID.RUNEPOUCH_RUNE) == null) {
				return;
			}
			Map<Integer, Integer> contents = read(client);
			syncer.submit(contents, false);
		});
	}

	/**
	 * Slot varbits to item id and quantity. A slot's type is a rune-pouch rune
	 * index (0 = empty) resolved through the {@code RUNEPOUCH_RUNE} enum; the
	 * same rune in two slots is merged.
	 */
	static Map<Integer, Integer> contents(int[] types, int[] quantities, IntUnaryOperator runeToItemId) {
		Map<Integer, Integer> contents = new LinkedHashMap<>();
		for (int i = 0; i < types.length && i < quantities.length; i++) {
			if (types[i] <= 0 || quantities[i] <= 0) {
				continue;
			}
			int itemId = runeToItemId.applyAsInt(types[i]);
			if (itemId <= 0) {
				continue;
			}
			contents.merge(itemId, quantities[i], Integer::sum);
		}
		return contents;
	}
}

package com.osrscompanion;

import com.osrscompanion.api.OSRSCompanionApiClient;
import java.time.Instant;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tells the website when a play session starts (login) and ends (logout), with a ping
 * every few minutes in between so a client closed without logging out still ends the
 * session at the last ping. World hops and reconnects stay in the same session.
 */
@Singleton
public class SessionMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "play-sessions";

	static final int PING_INTERVAL_MINUTES = 5;

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executorService;

	/** Name of the player the open session belongs to; null when logged out. */
	private volatile String player;
	private ScheduledFuture<?> pingTask;

	@Inject
	public SessionMonitor(Client client, ClientThread clientThread, OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient, ScheduledExecutorService executorService) {
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
	}

	public void start() {
		pingTask = executorService.scheduleAtFixedRate(this::ping, PING_INTERVAL_MINUTES, PING_INTERVAL_MINUTES, TimeUnit.MINUTES);
		// Enabled (or rebuilt) while already in game: that is a session too.
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			if (client.getGameState() == GameState.LOGGED_IN) {
				begin();
			}
		});
	}

	public void stop() {
		if (pingTask != null) {
			pingTask.cancel(false);
			pingTask = null;
		}
		finish();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState state = event.getGameState();
			if (state == GameState.LOGGED_IN && player == null) {
				begin();
			} else if (state == GameState.LOGIN_SCREEN && player != null) {
				// Only the login screen ends a session: HOPPING, LOADING and CONNECTION_LOST come back.
				finish();
			}
		});
	}

	/** Waits (tick by tick) until the player's name is known, then reports the login. Client thread. */
	private void begin() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			if (client.getGameState() != GameState.LOGGED_IN) {
				return true;
			}
			String name = SyncGuard.getPlayerUsername(client);
			if (name == null) {
				return false;
			}
			if (player == null && reportable()) {
				player = name;
				send(name, "start");
			}
			return true;
		});
	}

	private void finish() {
		String name = player;
		player = null;
		if (name != null && reportable()) {
			send(name, "end");
		}
	}

	private void ping() {
		String name = player;
		if (name != null && reportable() && client.getGameState() == GameState.LOGGED_IN) {
			send(name, "ping");
		}
	}

	private boolean reportable() {
		return SyncGuard.hasAppKey(config) && config.syncSessions() && !GameModeUtil.isSpecialGameMode(client);
	}

	private void send(String name, String event) {
		apiClient.sendSessionEvent(name, event, Instant.now().toString());
	}
}

package com.osrscompanion;

import java.util.*;

/**
 * Slayer tasks that can also be done on a boss variant, and the boss NPCs that count for them (OSRS
 * Wiki, each task's "boss variants count towards the task"). A boss kill counts as one task kill but
 * takes far longer, so a session records how many of its kills were the boss (see {@link SlayerSession}).
 * The website mirrors this list in src/lib/slayerBosses.ts. No game access.
 *
 * <p>Not here: the slayer "Boss" task itself (its boss is the task), and variants that are no boss
 * (basilisk knights, demonic gorillas, superiors, lizardman shamans).
 */
final class SlayerBosses {
	private SlayerBosses() {
	}

	/** Task name (lower case, as the game names the task) -> the boss NPC names that count for it. */
	static final Map<String, List<String>> BOSSES = new LinkedHashMap<>();

	static {
		Tables.map("slayerBosses").forEach((task, names) -> BOSSES.put(task, Tables.strings(names)));
	}

	/** The boss NPCs that count for a task ("Hydras" -> Alchemical Hydra); empty when it has none. */
	static List<String> forTask(String taskName) {
		String task = clean(taskName);
		if (task.isEmpty()) {
			return Collections.emptyList();
		}
		List<String> exact = BOSSES.get(task);
		if (exact != null) {
			return exact;
		}
		// "Hydra", "Cave krakens", "Kalphites": the same task by its singular.
		String one = SlayerMonsters.singular(task);
		for (Map.Entry<String, List<String>> e : BOSSES.entrySet()) {
			if (SlayerMonsters.singular(e.getKey()).equals(one)) {
				return e.getValue();
			}
		}
		return Collections.emptyList();
	}

	/** Whether this NPC is a boss variant of the task (any case, tags ignored). */
	static boolean isBoss(String taskName, String npcName) {
		String npc = clean(npcName);
		if (npc.isEmpty()) {
			return false;
		}
		for (String b : forTask(taskName)) {
			if (npc.equals(clean(b))) {
				return true;
			}
		}
		return false;
	}

	/** "Alchemical Hydra" -> "boss-alchemical-hydra": the key of the area round a boss (a session's location). */
	static String areaKey(String npcName) {
		String slug = clean(npcName).replaceAll("[^a-z0-9]+", "-").replaceAll("^-+|-+$", "");
		return "boss-" + (slug.isEmpty() ? "unknown" : slug);
	}

	private static String clean(String s) {
		return s == null ? "" : s.replaceAll("<[^>]*>", "").replace(' ', ' ').trim().toLowerCase();
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.SlayerCatalogPayload;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Dumps the game-cache slayer DB tables (SlayerTask, SlayerMasterTask,
 * SlayerArea, SlayerTaskSublist, SlayerUnlock) and uploads them to the OSRS Companion
 * API once per cache revision.
 *
 * <p>This is global data, identical for every player on the same revision, so
 * the flow is: dump on the client thread, hash, ask the server whether it
 * already has this hash, and upload only when it does not. In practice one
 * player per game update pays the upload for everyone.
 *
 * <p>Rows are enumerated by probing indexed key columns over bounded ranges
 * (the tables key on small integers); misses are cheap cache lookups.
 */
@Slf4j
@Singleton
public class SlayerCatalogMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "slayer-catalog-sync";

	private static final int LOGIN_DUMP_DELAY_SECONDS = 12;
	private static final int MAX_TASK_ID = 512;
	private static final int MAX_MASTER_ID = 32;
	private static final int MAX_AREA_ID = 256;
	private static final int MAX_SUBLIST_ID = 64;
	private static final int MAX_UNLOCK_BIT = 96;

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	/** Hash already confirmed present server-side this session; skip re-checks. */
	private String confirmedHash;
	/** Cache revision whose dump was already confirmed; skips the ~1k table
	 * probes a world hop would otherwise repeat. */
	private int confirmedRevision = -1;

	@Inject
	public SlayerCatalogMonitor(
			Client client,
			ClientThread clientThread,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson) {
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		confirmedHash = null;
		confirmedRevision = -1;
	}

	public void forceSync() {
		confirmedHash = null;
		confirmedRevision = -1;
		Guard.invokeLater(clientThread, GUARD_FEATURE, this::dumpAndUpload);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				// Late enough that the cache DB tables are certainly readable, and
				// well behind the state monitors' own login syncs.
				executorService.schedule(() -> Guard.invokeLater(clientThread, GUARD_FEATURE, this::dumpAndUpload),
						LOGIN_DUMP_DELAY_SECONDS, TimeUnit.SECONDS);
			}
			previousGameState = newState;
		});
	}

	/** Dumps the tables and uploads when the server lacks this hash. Client thread only. */
	private void dumpAndUpload() {
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}
		if (client.getRevision() == confirmedRevision) {
			return;
		}

		Map<String, List<Map<String, Object>>> tables;
		try {
			tables = dumpTables();
		} catch (RuntimeException e) {
			log.warn("Slayer catalog dump failed", e);
			return;
		}
		if (tables.get("slayer_task").isEmpty()) {
			return;
		}

		String tablesJson = gson.toJson(tables);
		String hash = sha256(tablesJson);
		if (hash == null || hash.equals(confirmedHash)) {
			return;
		}
		String revision = String.valueOf(client.getRevision());

		SlayerCatalogPayload payload =
				new SlayerCatalogPayload(playerUsername, revision, hash, tables);
		apiClient.getSlayerCatalogStatus(hash, new OSRSCompanionApiClient.RoadmapCallback<>() {
			@Override
			public void onSuccess(SlayerCatalogPayload.Status status) {
				confirmedHash = hash;
				confirmedRevision = client.getRevision();
				if (status.isNeeded()) {
					apiClient.sendSlayerCatalog(payload);
				} else {
				}
			}

			@Override
			public void onError(String message) {
			}
		});
	}

	private Map<String, List<Map<String, Object>>> dumpTables() {
		Map<String, List<Map<String, Object>>> tables = new LinkedHashMap<>();
		tables.put("slayer_task", dumpSlayerTasks());
		tables.put("slayer_master_task", dumpMasterTasks());
		tables.put("slayer_area", dumpAreas());
		tables.put("slayer_task_sublist", dumpSublist());
		tables.put("slayer_unlock", dumpUnlocks());
		return tables;
	}

	private List<Map<String, Object>> dumpSlayerTasks() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int id = 0; id < MAX_TASK_ID; id++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, id)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("id", id);
				out.put("name", firstString(row, DBTableID.SlayerTask.ID,
						DBTableID.SlayerTask.COL_NAME_UPPERCASE));
				out.put("min_combat_level", firstInt(row, DBTableID.SlayerTask.ID,
						DBTableID.SlayerTask.COL_MIN_COMLEVEL));
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpMasterTasks() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int masterId = 0; masterId < MAX_MASTER_ID; masterId++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerMasterTask.ID,
					DBTableID.SlayerMasterTask.COL_MASTER_ID, 0, masterId)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("master_id", masterId);
				// COL_TASK is a dbrow reference; dereference to the task's id.
				Integer taskRow = firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_TASK);
				out.put("task_id", taskRow == null ? null
						: firstInt(taskRow, DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID));
				out.put("weight", firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_WEIGHT));
				out.put("min_amount", firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_MIN_AMOUNT));
				out.put("max_amount", firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_MAX_AMOUNT));
				Integer unlockRow = firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_TASK_UNLOCK);
				out.put("unlock_bit", unlockRow == null ? null
						: firstInt(unlockRow, DBTableID.SlayerUnlock.ID, DBTableID.SlayerUnlock.COL_BIT));
				Integer areaRow = firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_AREAS);
				List<Integer> areas = new ArrayList<>();
				if (areaRow != null) {
					Integer areaId = firstInt(areaRow, DBTableID.SlayerArea.ID,
							DBTableID.SlayerArea.COL_AREA_ID);
					if (areaId != null) {
						areas.add(areaId);
					}
				}
				out.put("areas", areas);
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpAreas() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int areaId = 1; areaId < MAX_AREA_ID; areaId++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("id", areaId);
				out.put("name", firstString(row, DBTableID.SlayerArea.ID,
						DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER));
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpSublist() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int sublistId = 1; sublistId < MAX_SUBLIST_ID; sublistId++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerTaskSublist.ID,
					DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, sublistId)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("sublist_id", sublistId);
				Integer taskRow = firstInt(row, DBTableID.SlayerTaskSublist.ID,
						DBTableID.SlayerTaskSublist.COL_TASK);
				out.put("task_id", taskRow == null ? null
						: firstInt(taskRow, DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID));
				out.put("task_name", taskRow == null ? null
						: firstString(taskRow, DBTableID.SlayerTask.ID,
								DBTableID.SlayerTask.COL_NAME_UPPERCASE));
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpUnlocks() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int bit = 0; bit < MAX_UNLOCK_BIT; bit++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerUnlock.ID, DBTableID.SlayerUnlock.COL_BIT, 0, bit)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("bit", bit);
				out.put("cost", firstInt(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_COST));
				out.put("name", firstString(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_NAME));
				out.put("description", firstString(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_DESCRIPTION));
				Integer refundable = firstInt(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_REFUNDABLE);
				out.put("refundable", refundable != null && refundable != 0);
				Integer taskRow = firstInt(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_RELATED_TASK);
				out.put("task_id", taskRow == null ? null
						: firstInt(taskRow, DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID));
				rows.add(out);
			}
		}
		return rows;
	}

	private Integer firstInt(int row, int table, int column) {
		try {
			Object[] values = client.getDBTableField(row, column, 0);
			if (values != null && values.length > 0 && values[0] instanceof Integer) {
				return (Integer) values[0];
			}
		} catch (RuntimeException e) {
		}
		return null;
	}

	private String firstString(int row, int table, int column) {
		try {
			Object[] values = client.getDBTableField(row, column, 0);
			if (values != null && values.length > 0 && values[0] instanceof String) {
				return (String) values[0];
			}
		} catch (RuntimeException e) {
		}
		return null;
	}

	private static String sha256(String input) {
		try {
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(hash.length * 2);
			for (byte b : hash) {
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		} catch (NoSuchAlgorithmException e) {
			return null;
		}
	}
}

package com.osrscompanion;

import java.util.Locale;

/** How the Slayer helper writes times and amounts. No game access. */
final class SlayerFormat {
	private SlayerFormat() {
	}

	/** "4:05", "12:30", "1:02:09". */
	static String clock(long ms) {
		long total = Math.max(0, ms) / 1000;
		long h = total / 3600;
		long m = (total % 3600) / 60;
		long s = total % 60;
		return h > 0 ? String.format(Locale.ROOT, "%d:%02d:%02d", h, m, s) : String.format(Locale.ROOT, "%d:%02d", m, s);
	}

	/** "18.5s" (under a minute), else like {@link #clock}. */
	static String seconds(long ms) {
		if (ms < 60_000) {
			return String.format(Locale.ROOT, "%.1fs", Math.max(0, ms) / 1000.0);
		}
		return clock(ms);
	}

	/** "950 gp", "33.5K", "2.35M". */
	static String gp(long gp) {
		if (Math.abs(gp) < 10_000) {
			return gp + " gp";
		}
		if (Math.abs(gp) < 1_000_000) {
			return trim(gp / 1000.0) + "K";
		}
		return trim(gp / 1_000_000.0) + "M";
	}

	private static String trim(double v) {
		String s = Math.abs(v) >= 100 ? String.format(Locale.ROOT, "%.0f", v) : Math.abs(v) >= 10 ? String.format(Locale.ROOT, "%.1f", v) : String.format(Locale.ROOT, "%.2f", v);
		if (s.contains(".")) {
			s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
		}
		return s;
	}

	/** "north-east" for a step of (dx, dy) on the game map (y grows north); null when there is no step. */
	static String compass(int dx, int dy) {
		if (dx == 0 && dy == 0) {
			return null;
		}
		double angle = Math.toDegrees(Math.atan2(dy, dx));
		String[] names = {"east", "north-east", "north", "north-west", "west", "south-west", "south", "south-east"};
		return names[(int) Math.round(((angle + 360) % 360) / 45.0) % 8];
	}
}

package com.osrscompanion;

import com.osrscompanion.model.SlayerGear;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.swing.JComponent;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

/**
 * The Slayer helper page's gear: the website's Gear &amp; DPS calculator's best owned setups against
 * the task's monster, one at a time in the game's equipment layout (carried green, in the bank
 * orange), with what else it counts on (potion, prayer, style or spell, darts). It shows the setup
 * picked in the Slayer gear window (the best until one is picked there).
 */
class SlayerGearPanelView extends JComponent {
	private static final int SLOT = 36;
	private static final int CELL = 40;
	private static final int DOLL_TOP = 50;
	private static final Color CARD = new Color(0x1A1F2B);
	private static final Color EDGE = new Color(0x313A4E);
	private static final Color HEADING = new Color(0x8C96A8);
	private static final Color TEXT = new Color(0xC9D1DE);
	private static final Color SLOT_FILL = new Color(0x11151E);
	private static final Color SLOT_EDGE = new Color(0x2A3242);
	private static final Color GREEN = new Color(0x0DC10D);
	private static final Color STORED = new Color(0xFF981F);
	private static final Color ACCENT = new Color(0xF87171);

	private final SlayerHelperManager manager;
	private final ItemManager itemManager;
	/** Each drawn slot's area and tooltip, from the last paint. */
	private volatile List<Tip> tips = Collections.emptyList();

	private static final class Tip {
		final Rectangle area;
		final String text;

		Tip(Rectangle area, String text) {
			this.area = area;
			this.text = text;
		}
	}

	SlayerGearPanelView(SlayerHelperManager manager, ItemManager itemManager) {
		this.manager = manager;
		this.itemManager = itemManager;
		setMinimumSize(new Dimension(120, 54));
		setToolTipText("");
	}

	/** Two lines of text without setups, else the doll and a line per extra. */
	private int wantedHeight() {
		SlayerGear.Set set = manager.getGearSet();
		return set == null ? 54 : DOLL_TOP + 5 * CELL + 8 + set.getExtras().size() * 13 + 10;
	}

	@Override
	public Dimension getPreferredSize() {
		return new Dimension(200, wantedHeight());
	}

	@Override
	public Dimension getMaximumSize() {
		return new Dimension(Integer.MAX_VALUE, wantedHeight());
	}

	@Override
	public String getToolTipText(MouseEvent e) {
		for (Tip t : tips) {
			if (t.area.contains(e.getPoint())) {
				return t.text;
			}
		}
		return null;
	}

	@Override
	protected void paintComponent(Graphics graphics) {
		Graphics2D g = (Graphics2D) graphics.create();
		try {
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			RoundRectangle2D card = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1.5f, h - 1.5f, 14, 14);
			g.setColor(CARD);
			g.fill(card);
			g.setColor(EDGE);
			g.draw(card);
			g.setFont(FontManager.getRunescapeSmallFont());
			shadow(g, "SLAYER GEAR", 12, 16, HEADING);

			SlayerGear gear = manager.getGear();
			SlayerGear.Set set = manager.getGearSet();
			List<Tip> newTips = new ArrayList<>();
			if (set == null) {
				g.setFont(FontManager.getRunescapeFont());
				shadow(g, fit(gear == null || manager.isFetchingForTask() ? "Retrieving gear for the task..." : "No setups for this task", g.getFontMetrics(), w - 24), 12, 32, Color.WHITE);
				g.setFont(FontManager.getRunescapeSmallFont());
				shadow(g, fit(gear == null ? "" : "Sync your bank and skills", g.getFontMetrics(), w - 24), 12, 45, TEXT);
				tips = newTips;
				return;
			}

			// How many setups there are to pick from in the window (top right).
			int count = gear.getSets().size();
			if (count > 1) {
				String of = (manager.getGearIndex() + 1) + " of " + count;
				shadow(g, of, w - 12 - g.getFontMetrics().stringWidth(of), 16, HEADING);
			}

			// Which setup, best first, and its numbers.
			g.setFont(FontManager.getRunescapeBoldFont());
			String title = set.getLabel() + (manager.getGearIndex() == 0 ? " (best)" : "");
			shadow(g, fit(title, g.getFontMetrics(), w - 24), 12, 32, ACCENT);
			g.setFont(FontManager.getRunescapeSmallFont());
			String numbers = "Max " + set.getMaxHit() + " · " + String.format(Locale.ROOT, "%.2f", set.getDps()) + " DPS · "
				+ Math.round(set.getKillsPerHour()) + " kills/h";
			shadow(g, fit(numbers, g.getFontMetrics(), w - 24), 12, 45, TEXT);

			// The worn gear in the game's 3-column doll.
			int x0 = (w - (3 * CELL - 4)) / 2;
			for (int r = 0; r < BossGearWindow.EQUIPMENT.length; r++) {
				for (int c = 0; c < 3; c++) {
					String slot = BossGearWindow.EQUIPMENT[r][c];
					if (slot != null) {
						slot(g, new Rectangle(x0 + c * CELL, DOLL_TOP + r * CELL, SLOT, SLOT), set.slot(slot), newTips);
					}
				}
			}

			// What else the numbers count on.
			int y = DOLL_TOP + 5 * CELL + 14;
			for (SlayerGear.Extra x : set.getExtras()) {
				shadow(g, x.getLabel() + ":", 12, y, HEADING);
				int lx = 12 + g.getFontMetrics().stringWidth(x.getLabel() + ": ");
				shadow(g, fit(x.getName(), g.getFontMetrics(), w - 12 - lx), lx, y, TEXT);
				y += 13;
			}
			tips = newTips;
		} finally {
			g.dispose();
		}
	}

	/** One slot: the item at its own size, green when carried (worn or in the inventory), else orange (in your storage). */
	private void slot(Graphics2D g, Rectangle r, SlayerGear.Piece piece, List<Tip> newTips) {
		g.setColor(SLOT_FILL);
		g.fillRect(r.x, r.y, r.width, r.height);
		if (piece == null) {
			g.setColor(SLOT_EDGE);
			g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
			return;
		}
		BufferedImage icon = itemManager.getImage(piece.getItem());
		if (icon != null && icon.getWidth() > 0) {
			g.drawImage(icon, r.x + (r.width - icon.getWidth()) / 2, r.y + (r.height - icon.getHeight()) / 2, null);
		}
		boolean carried = manager.carried(piece.getItem()) > 0;
		g.setColor(carried ? GREEN : STORED);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		if (!carried) {
			g.setFont(FontManager.getRunescapeSmallFont());
			shadow(g, "B", r.x + r.width - 8, r.y + r.height - 3, STORED);
		}
		newTips.add(new Tip(r, piece.getName() + (carried ? " - carried" : " - in your bank or storage")));
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color) {
		g.setColor(new Color(0, 0, 0, 170));
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String fit(String s, FontMetrics fm, int width) {
		if (fm.stringWidth(s) <= width) {
			return s;
		}
		String t = s;
		while (t.length() > 1 && fm.stringWidth(t + "...") > width) {
			t = t.substring(0, t.length() - 1);
		}
		return t + "...";
	}
}

