/**
 * Monitors slayer state (assignment, points, streaks, block list, unlocks,
 * the Task Storage slot) and task transitions, and syncs them to the OSRS Companion
 * API.
 *
 * <p>State is read directly from the slayer varps/varbits (no dependency on
 * RuneLite's Slayer plugin being enabled), with task and area names resolved
 * client-side through the game-cache DB tables. Each read, each change of the task count and each
 * completion chat line is also recorded as a game event ({@link GameEvents}): the website works out from
 * them how each task ended (completed, skipped, blocked...) and the time spent on it.
 */
@Slf4j
@Singleton
public class SlayerMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "slayer-task-sync";

	private static final int LOGIN_SYNC_DELAY_SECONDS = 5;
	private static final int RESYNC_THROTTLE_TICKS = 3;
	/**
	 * Minimum interval between amount-only syncs (task progress ticks down every kill). Uploads are
	 * batched by the outbox, so this can be short; a kill inside the window is sent when it closes.
	 */
	private static final long AMOUNT_SYNC_MIN_INTERVAL_MS = 10_000L;
	/**
	 * Ticks between a task ending and the website closing it: the completion chat message can arrive a tick
	 * after the varp flips, so the website waits for this "slayer_fin" event.
	 */
	private static final int EVENT_FINALIZE_DELAY_TICKS = 3;
	/** SLAYER_TARGET value meaning "a boss task"; resolve via the sublist table. */
	private static final int BOSS_TASK_SENTINEL = 98;
	/**
	 * The slayer task-offer dialog (Mortimer's 2-3 choices, each with a name,
	 * an amount range and a modifier). It raises no WidgetLoaded event, being
	 * a nested child of the game frame rather than its own interface, so it is
	 * polled instead. A wrong id costs nothing beyond a null lookup: the parse
	 * only accepts offer-shaped rows, so it can never yield bad data.
	 *
	 * <p>The whole subtree under the container is read, not one child list.
	 * Reading only the dynamic children captured every name and amount but
	 * never a modifier from any live dialog, so the modifier rows do not live
	 * where the names do.
	 */
	private static final int TASK_OFFER_GROUP = 236;
	private static final int TASK_OFFER_CHILD = 3;
	private static final int OFFER_SCAN_INTERVAL_TICKS = 5;
	/** How deep under the dialog container its text rows may sit. */
	private static final int OFFER_SCAN_MAX_DEPTH = 5;
	/**
	 * How long a capture stays the "same dialog" for downgrade purposes. A
	 * re-read of the open dialog must never replace a richer capture with a
	 * thinner one; the same two tasks offered again later is a new dialog and
	 * replaces it whatever it carries.
	 */
	private static final long OFFER_REFRESH_WINDOW_MS = 60_000L;
	/** How long captured offers ride along in the state sync before expiring. */
	private static final long OFFER_RETENTION_MS = 30 * 60_000L;
	private static final String STORED_TASK_CONFIG_KEY = "storedSlayerTask";

	/**
	 * Clientscripts that draw the rewards-interface Tasks tab: 328 runs once at
	 * interface setup, 421 re-runs on every var retransmit while it stays open.
	 * Both render the current and stored task from the IF1-IF6 transfer varps,
	 * so firing right after them reads values the server just served.
	 */
	private static final int SLAYER_REWARDS_TASKS_INIT_SCRIPT = 328;
	private static final int SLAYER_REWARDS_TASKS_REDRAW_SCRIPT = 421;

	// Loose on purpose: matches the known completion message variants ("You've
	// completed X tasks in a row...", points and Wilderness forms). The website
	// treats chat as corroboration, so a miss degrades gracefully.
	static final java.util.regex.Pattern COMPLETION_CHAT_PATTERN =
			java.util.regex.Pattern.compile("completed.{0,40}?\\d[\\d,]* tasks?",
					java.util.regex.Pattern.CASE_INSENSITIVE);

	private static final Set<Integer> WATCHED_VARPS = Tables.idSet("slayerWatchedVarps");
	/** Each slayer master's own block list: one varbit per slot holding a task id (tables.json). */
	static final Map<String, int[]> MASTER_BLOCK_VARBITS = new LinkedHashMap<>();
	static {
		Tables.map("slayerMasterBlockVarbits").forEach((master, ids) -> MASTER_BLOCK_VARBITS.put(master, Tables.ids(ids)));
	}

	private static final Set<Integer> WATCHED_VARBITS = watchedVarbits();

	private static Set<Integer> watchedVarbits() {
		Set<Integer> out = new java.util.HashSet<>(Set.of(
				VarbitID.SLAYER_MASTER,
				VarbitID.SLAYER_POINTS,
				VarbitID.SLAYER_TASKS_COMPLETED,
				VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED,
				VarbitID.SLAYER_TARGET_BOSSID));
		for (int[] ids : MASTER_BLOCK_VARBITS.values()) {
			for (int id : ids) {
				out.add(id);
			}
		}
		return java.util.Collections.unmodifiableSet(out);
	}

	// Ordered block list varps: the shared 15 slots (1 + 12 + 2 diary).
	private static final int[] BLOCK_LIST_VARPS = Tables.ids(Tables.list("slayerBlockListVarps"));

	/** Snapshot of the slayer varp/varbit state at one read. */
	static class Snapshot {
		Integer taskId;
		String taskName;
		Integer bossTaskId;
		Integer areaId;
		Integer masterId;
		int amountRemaining;
		int amountOriginal;
		int points;
		int streak;
		int wildernessStreak;
		List<Integer> blockList = new ArrayList<>();
		/** Each master's block list (task ids), from the per-master varbits. */
		Map<String, List<Integer>> blockedByMaster = new LinkedHashMap<>();
		Map<String, Integer> unlockBitfields = new LinkedHashMap<>();
		Integer slayerLevel;
		Long slayerXp;

		boolean hasTask() {
			return amountRemaining > 0 && (taskId != null && taskId != 0);
		}

		/**
		 * Task identity, ignoring progress. Boss tasks differ by sublist id.
		 * The master is part of identity: a different master can reassign the
		 * SAME monster in one interaction (task id unchanged, amount and
		 * master varbit updated together), and without the master in the
		 * comparison that transition is invisible: the old row never closes
		 * and the skip goes unrecorded. The same master can never deal the
		 * same monster back-to-back (the current task is excluded from the
		 * assignment pool), so including it costs nothing.
		 */
		boolean sameTask(Snapshot other) {
			return java.util.Objects.equals(taskId, other.taskId)
					&& java.util.Objects.equals(bossTaskId, other.bossTaskId)
					&& java.util.Objects.equals(areaId, other.areaId)
					&& java.util.Objects.equals(masterId, other.masterId);
		}
	}

	/**
	 * The Task Storage slot, captured opportunistically. No persistent varp
	 * carries the banked task: the server holds it and only copies it into the
	 * shared IF4/IF5/IF6 interface-transfer varps (amount, task id, boss
	 * sublist id) while the slayer rewards screen is open. Captures persist to
	 * RSProfile config so the last known slot survives restarts.
	 */
	static class StoredTaskCapture {
		int taskId;
		int amount;
		int bossTaskId;
		String taskName;
		String capturedAt;
	}

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;
	private final ConfigManager configManager;
	private final GameEvents gameEvents;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean checkPending;
	private int lastReadTick = -1;
	private String lastSyncJson;
	private long lastAmountSyncMs;
	/** The task's kills left in the last sync (-1: none yet). */
	private int lastSyncedAmount = -1;
	private StoredTaskCapture storedTask;
	private List<Map<String, Object>> pendingOffers = new ArrayList<>();
	private List<String> pendingOfferRows;
	private long offersCapturedMs;
	private String lastOffersKey;
	private int lastOfferScanTick = -1;
	private String offersCapturedAt;
	private boolean storedTaskDirty;
	private Snapshot previous;
	/** The tick to send "slayer_fin" at (a task ended), or -1. */
	private int finalizeAt = -1;
	/** A task was closed since the last sync: the next read syncs (the website gets the new state with it). */
	private boolean closed;

	@Inject
	public SlayerMonitor(
			Client client,
			ClientThread clientThread,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson,
			ConfigManager configManager,
			GameEvents gameEvents) {
		executorService = GuardedExecutor.wrap(GUARD_FEATURE, executorService);
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
		this.configManager = configManager;
		this.gameEvents = gameEvents;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		checkPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
		lastAmountSyncMs = 0;
		lastSyncedAmount = -1;
		previous = null;
		finalizeAt = -1;
		closed = false;
		// Drop the in-memory capture but keep the persisted copy: the stored
		// task is only readable while the rewards screen is open, so the last
		// capture is restored on the next login.
		storedTask = null;
		storedTaskDirty = false;
	}

	/** Re-reads and re-pushes slayer state; clears the dedup cache. */
	public void forceSync() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			lastSyncJson = null;
			readAndSync(true);
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				// Slayer varps and DB tables settle shortly after login.
				executorService.schedule(() -> Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
					previous = null; // don't fabricate a transition across sessions
					readAndSync(true);
				}), LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
			} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
				readAndSync(true);
			}
			previousGameState = newState;
		});
	}

	@Subscribe
	public void onChatMessage(ChatMessage event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getType() != ChatMessageType.GAMEMESSAGE) {
				return;
			}
			String message = net.runelite.client.util.Text.removeTags(event.getMessage());
			if (COMPLETION_CHAT_PATTERN.matcher(message).find()) {
				gameEvents.add("slayer_chat", "text", message);
				checkPending = true;
			}
		});
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getScriptId() == SLAYER_REWARDS_TASKS_INIT_SCRIPT
					|| event.getScriptId() == SLAYER_REWARDS_TASKS_REDRAW_SCRIPT) {
				captureStoredTask();
			}
		});
	}

	/**
	 * Reads the Task Storage slot from the IF transfer varps. Client thread
	 * only (script events fire there).
	 *
	 * <p>The IF varps are scratch shared by many interfaces (bank, colosseum,
	 * bond conversion, ...). The tasks-tab script also mirrors the ACTIVE task
	 * into IF1/IF2; requiring those to match the live task varps proves the
	 * scratch currently serves the slayer rewards screen.
	 */
	private void captureStoredTask() {
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (client.getVarpValue(VarPlayerID.IF1) != client.getVarpValue(VarPlayerID.SLAYER_COUNT)
				|| client.getVarpValue(VarPlayerID.IF2)
						!= client.getVarpValue(VarPlayerID.SLAYER_TARGET)) {
			return;
		}
		int amount = client.getVarpValue(VarPlayerID.IF4);
		int taskId = client.getVarpValue(VarPlayerID.IF5);
		int bossTaskId = client.getVarpValue(VarPlayerID.IF6);
		if (!hasStoredTask(taskId, amount)) {
			// Normalize "no stored task" so residual junk in the scratch varps
			// can't masquerade as a banked assignment.
			amount = 0;
			taskId = 0;
			bossTaskId = 0;
		}
		if (storedTask != null && storedTask.taskId == taskId
				&& storedTask.amount == amount && storedTask.bossTaskId == bossTaskId) {
			return; // unchanged; keep the original capture timestamp
		}
		StoredTaskCapture capture = new StoredTaskCapture();
		capture.taskId = taskId;
		capture.amount = amount;
		capture.bossTaskId = bossTaskId;
		capture.taskName = taskId == 0
				? null
				: resolveTaskName(taskId, bossTaskId == 0 ? null : bossTaskId);
		capture.capturedAt = Instant.now().toString();
		storedTask = capture;
		storedTaskDirty = true;
		configManager.setRSProfileConfiguration(
				"osrscompanion", STORED_TASK_CONFIG_KEY, gson.toJson(capture));
		checkPending = true;
	}

	/**
	 * Whether the raw IF varp pair encodes a banked task, mirroring the render
	 * conditions in the rewards-interface script (which draws name-only for a
	 * boss slot with amount -1).
	 */
	static boolean hasStoredTask(int taskId, int amount) {
		if (taskId == BOSS_TASK_SENTINEL) {
			return amount > 0 || amount == -1;
		}
		return taskId != 0 && amount > 0;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getVarpId() == VarPlayerID.SLAYER_COUNT) {
				// Kills (the count going down), for the time spent on the task.
				gameEvents.add("slayer_count", "v", event.getValue());
			}
			if (WATCHED_VARPS.contains(event.getVarpId())
					|| WATCHED_VARBITS.contains(event.getVarbitId())) {
				checkPending = true;
			}
		});
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (lastOfferScanTick == -1
					|| client.getTickCount() - lastOfferScanTick >= OFFER_SCAN_INTERVAL_TICKS) {
				lastOfferScanTick = client.getTickCount();
				scanForTaskOffers();
			}
			if (finalizeAt >= 0 && client.getTickCount() >= finalizeAt) {
				finalizeAt = -1;
				closed = true;
				gameEvents.add("slayer_fin");
				readAndSync(false);
				return;
			}
			if (!checkPending) {
				return;
			}
			if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
				return;
			}
			checkPending = false;
			lastReadTick = client.getTickCount();
			readAndSync(false);
		});
	}

	/** Reads the snapshot, detects transitions, and syncs. Client thread only. */
	private void readAndSync(boolean force) {
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		Snapshot now = readSnapshot();
		// First read of the session: the last stored-task capture unless a live capture already replaced it.
		if (previous == null && storedTask == null) {
			restoreStoredTask();
		}
		// For the website (task outcomes and times). first: the first read of a session (no transition from
		// the one before); force: logout or a forced sync (a task that ended is closed at once).
		gameEvents.add("slayer", "first", previous == null, "force", force, "task", now.taskId, "boss", now.bossTaskId,
				"area", now.areaId, "master", now.masterId, "name", now.taskName, "left", now.amountRemaining,
				"orig", now.amountOriginal, "pts", now.points, "st", now.streak, "wst", now.wildernessStreak,
				"blk", now.blockList, "bm", now.blockedByMaster);
		// A forced read closes a task that ended at once; a second task ending closes the first.
		closed |= force && finalizeAt >= 0;
		if (previous != null && previous.hasTask() && (!now.hasTask() || !now.sameTask(previous))) {
			closed |= finalizeAt >= 0;
			finalizeAt = client.getTickCount() + EVENT_FINALIZE_DELAY_TICKS;
		}
		boolean taskChanged = previous == null
				|| previous.hasTask() != now.hasTask()
				|| (now.hasTask() && !now.sameTask(previous));
		// A kill on the task (its count went down): sent at once, outside the amount window.
		boolean killed = !taskChanged && previous != null && now.hasTask() && now.amountRemaining < previous.amountRemaining;
		previous = now;
		if (finalizeAt >= 0) {
			if (!force) {
				// The task's end is still open; the sync goes with its closing in a moment.
				return;
			}
			closed = true;
			finalizeAt = -1;
		}

		boolean amountWindowOpen =
				System.currentTimeMillis() - lastAmountSyncMs >= AMOUNT_SYNC_MIN_INTERVAL_MS;
		if (!force && !taskChanged && !killed && !closed && !amountWindowOpen
				&& !storedTaskDirty) {
			// A kill inside the window: look again on a later tick, so it goes up once the window
			// closes instead of waiting for the next kill.
			if (now.amountRemaining != lastSyncedAmount) {
				checkPending = true;
			}
			return;
		}

		SlayerSyncPayload payload = buildPayload(playerUsername, now);
		storedTaskDirty = false;
		String json = payload.toJson(gson);
		if (json.equals(lastSyncJson) && !closed) {
			return;
		}
		lastSyncJson = closed ? null : json;
		closed = false;
		lastAmountSyncMs = System.currentTimeMillis();
		lastSyncedAmount = now.amountRemaining;

		apiClient.sendSlayerSync(payload, killed);
	}

	private Snapshot readSnapshot() {
		Snapshot s = new Snapshot();
		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		s.taskId = taskId == 0 ? null : taskId;
		s.amountRemaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		s.amountOriginal = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		s.areaId = areaId == 0 ? null : areaId;
		int bossId = client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID);
		s.bossTaskId = bossId == 0 ? null : bossId;
		int masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		s.masterId = masterId == 0 ? null : masterId;
		if (taskId != 0 && s.amountRemaining > 0) {
			s.amountOriginal = originalAmount(taskId, bossId, areaId, masterId, s.amountOriginal, s.amountRemaining);
		}
		s.points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		s.streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		s.wildernessStreak = client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
		for (int varp : BLOCK_LIST_VARPS) {
			s.blockList.add(client.getVarpValue(varp));
		}
		for (Map.Entry<String, int[]> e : MASTER_BLOCK_VARBITS.entrySet()) {
			List<Integer> ids = new ArrayList<>();
			for (int varbit : e.getValue()) {
				int id = client.getVarbitValue(varbit);
				if (id != 0) {
					ids.add(id);
				}
			}
			s.blockedByMaster.put(e.getKey(), ids);
		}
		s.unlockBitfields.put(String.valueOf(VarPlayerID.SLAYER_REWARDS_UNLOCKS),
				client.getVarpValue(VarPlayerID.SLAYER_REWARDS_UNLOCKS));
		s.unlockBitfields.put(String.valueOf(VarPlayerID.SLAYER_REWARDS_UNLOCKS1),
				client.getVarpValue(VarPlayerID.SLAYER_REWARDS_UNLOCKS1));
		s.unlockBitfields.put(String.valueOf(VarPlayerID.SLAYER_REWARDS_UNLOCKS2),
				client.getVarpValue(VarPlayerID.SLAYER_REWARDS_UNLOCKS2));
		s.slayerLevel = client.getRealSkillLevel(Skill.SLAYER);
		s.slayerXp = (long) client.getSkillExperience(Skill.SLAYER);
		if (s.hasTask()) {
			s.taskName = resolveTaskName(s.taskId, s.bossTaskId);
		}
		return s;
	}

	private static final String TASK_SIZE_CONFIG_KEY = "slayerTaskSize";
	private final TaskSize taskSize = new TaskSize();
	private boolean taskSizeLoaded;

	/**
	 * The task's size as the plugin sends it (amount_original): SLAYER_COUNT_ORIGINAL, but never below the
	 * highest count seen on this assignment. The varp can be below the count: Mortimer's quantity modifier
	 * adds kills on top of the amount rolled (the varp keeps the roll), and the varp can still hold an
	 * earlier task's size. Below the count, killed (size - count) went negative on the website. Kept per
	 * RuneScape profile, so a restart mid-task keeps the size. Client thread only.
	 */
	synchronized int originalAmount(int taskId, int bossId, int areaId, int masterId, int varpOriginal, int remaining) {
		if (!taskSizeLoaded) {
			taskSizeLoaded = true;
			taskSize.restore(configManager.getRSProfileConfiguration("osrscompanion", TASK_SIZE_CONFIG_KEY));
		}
		String before = taskSize.stored();
		int size = taskSize.update(taskId + ":" + bossId + ":" + areaId + ":" + masterId + ":" + varpOriginal, varpOriginal, remaining);
		String after = taskSize.stored();
		if (after != null && !after.equals(before)) {
			configManager.setRSProfileConfiguration("osrscompanion", TASK_SIZE_CONFIG_KEY, after);
		}
		return size;
	}

	/**
	 * The highest task count seen on one assignment (task, boss, area, master and the varp's size: a new
	 * assignment changes one of them). No game access.
	 */
	static final class TaskSize {
		private String key;
		private int peak;

		/** The size for this read: the larger of the varp's size and the highest count seen on the assignment. */
		int update(String assignment, int varpOriginal, int remaining) {
			if (remaining <= 0) {
				return Math.max(0, varpOriginal);
			}
			if (!assignment.equals(key)) {
				key = assignment;
				peak = 0;
			}
			peak = Math.max(peak, remaining);
			return Math.max(varpOriginal, peak);
		}

		/** "assignment|peak" for the config, or null before the first task. */
		String stored() {
			return key == null ? null : key + "|" + peak;
		}

		void restore(String stored) {
			if (stored == null) {
				return;
			}
			int bar = stored.lastIndexOf('|');
			if (bar <= 0) {
				return;
			}
			try {
				peak = Integer.parseInt(stored.substring(bar + 1));
				key = stored.substring(0, bar);
			} catch (NumberFormatException e) {
				key = null;
				peak = 0;
			}
		}
	}

	/**
	 * The task's display name ("Abyssal demons"), or null when it can't be read; for the Slayer
	 * helper, which reads the task varps itself. Client thread only.
	 */
	String taskName(int taskId, Integer bossTaskId) {
		return resolveTaskName(taskId, bossTaskId);
	}

	/**
	 * Resolves the task display name via the game-cache DB tables, handling the
	 * boss-task sentinel. Adapted from RuneLite SlayerPlugin.updateTask().
	 */
	private String resolveTaskName(int taskId, Integer bossTaskId) {
		try {
			int taskDbRow;
			if (taskId == BOSS_TASK_SENTINEL && bossTaskId != null) {
				List<Integer> bossRows = client.getDBRowsByValue(
						DBTableID.SlayerTaskSublist.ID,
						DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
						0,
						bossTaskId);
				if (bossRows.isEmpty()) {
					return null;
				}
				taskDbRow = (Integer) client.getDBTableField(
						bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
			} else {
				List<Integer> taskRows = client.getDBRowsByValue(
						DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
				if (taskRows.isEmpty()) {
					return null;
				}
				taskDbRow = taskRows.get(0);
			}
			return (String) client.getDBTableField(
					taskDbRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
		} catch (RuntimeException e) {
			return null;
		}
	}


	/** Reads the task-offer dialog if it is open. Client thread only. */
	private void scanForTaskOffers() {
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		if (SyncGuard.getPlayerUsername(client) == null) {
			return;
		}
		Widget container = client.getWidget(TASK_OFFER_GROUP, TASK_OFFER_CHILD);
		if (container == null) {
			return;
		}
		List<OfferRow> rows = new ArrayList<>();
		collectRows(container, 0, rows);
		if (rows.isEmpty()) {
			return;
		}
		List<String> texts = readingOrder(rows);
		List<Map<String, Object>> offers = parseTaskOffers(texts);
		if (!offers.isEmpty()) {
			acceptOffers(offers, texts);
		}
	}

	/**
	 * Every text-bearing widget under the dialog, whichever child list holds
	 * it. The static, dynamic and nested lists are all walked because the
	 * modifier row is not in the same one as the name and amount rows.
	 */
	private static void collectRows(Widget widget, int depth, List<OfferRow> rows) {
		if (widget == null || depth > OFFER_SCAN_MAX_DEPTH) {
			return;
		}
		String text = widget.getText();
		if (text != null && !text.isEmpty()) {
			Point at = widget.getCanvasLocation();
			rows.add(at == null
					? new OfferRow(text, null, null)
					: new OfferRow(text, at.getX(), at.getY()));
		}
		for (Widget[] set : new Widget[][] {
				widget.getStaticChildren(), widget.getDynamicChildren(),
				widget.getNestedChildren()}) {
			if (set == null) {
				continue;
			}
			for (Widget child : set) {
				collectRows(child, depth + 1, rows);
			}
		}
	}

	/** One text row of the offer dialog, with where on screen it drew. */
	static final class OfferRow {
		final String text;
		final Integer x;
		final Integer y;

		OfferRow(String text, Integer x, Integer y) {
			this.text = text;
			this.x = x;
			this.y = y;
		}

		boolean positioned() {
			return x != null && y != null && y >= 0;
		}
	}

	/**
	 * The rows top to bottom as the player reads them. The dialog is a
	 * vertical list, so screen position restores the reading order even when
	 * the rows are gathered from different child lists, which walk order
	 * groups rather than interleaves. Positions are only trusted when every
	 * row has one; otherwise walk order stands.
	 */
	static List<String> readingOrder(List<OfferRow> rows) {
		List<OfferRow> ordered = new ArrayList<>(rows);
		boolean positioned = true;
		for (OfferRow row : rows) {
			positioned &= row.positioned();
		}
		if (positioned) {
			ordered.sort(Comparator.comparingInt((OfferRow row) -> row.y)
					.thenComparingInt(row -> row.x));
		}
		List<String> texts = new ArrayList<>(ordered.size());
		for (OfferRow row : ordered) {
			texts.add(row.text);
		}
		return texts;
	}

	/** Stores newly seen offers and ships them with the next state sync. */
	private void acceptOffers(List<Map<String, Object>> offers, List<String> rows) {
		String key = gson.toJson(offers);
		if (key.equals(lastOffersKey)) {
			return; // same dialog still open
		}
		if (isThinnerReread(offers)) {
			return;
		}
		lastOffersKey = key;
		pendingOffers = offers;
		// The rows only ride along when a modifier is missing: they are what
		// says where the missing row actually lives, without a release to ask.
		pendingOfferRows = modifierCount(offers) < offers.size() ? rows : null;
		offersCapturedMs = System.currentTimeMillis();
		offersCapturedAt = Instant.now().toString();
		readAndSync(true);
	}

	/**
	 * Whether this read is the dialog already captured, seen with fewer
	 * modifiers than last time. A row that populates late (or blanks as the
	 * dialog closes) makes the same dialog read differently on either side of
	 * it, and the fuller read is the true one.
	 */
	private boolean isThinnerReread(List<Map<String, Object>> offers) {
		if (pendingOffers.isEmpty()
				|| System.currentTimeMillis() - offersCapturedMs > OFFER_REFRESH_WINDOW_MS) {
			return false;
		}
		return offerNames(offers).equals(offerNames(pendingOffers))
				&& modifierCount(offers) < modifierCount(pendingOffers);
	}

	private static List<Object> offerNames(List<Map<String, Object>> offers) {
		List<Object> names = new ArrayList<>(offers.size());
		for (Map<String, Object> offer : offers) {
			names.add(offer.get("name"));
		}
		return names;
	}

	private static int modifierCount(List<Map<String, Object>> offers) {
		int count = 0;
		for (Map<String, Object> offer : offers) {
			if (offer.containsKey("modifier_text")) {
				count++;
			}
		}
		return count;
	}

	/** "Amount: 80 to 120", or a single "Amount: 48". */
	static final java.util.regex.Pattern AMOUNT_ROW = java.util.regex.Pattern.compile(
			"^Amount:\\s*(\\d+)(?:\\s*to\\s*(\\d+))?\\s*$", java.util.regex.Pattern.CASE_INSENSITIVE);
	/**
	 * "+15 Slayer points", "+30% Slayer XP", "+100 Assigned", "x2 clue
	 * scrolls", "-20 Assigned". Modifiers subtract as well as add, so the sign
	 * is part of the value: a "-20 Assigned" task asks for 20 fewer kills than
	 * the amount rolled, and reading it as +20 would have it ask for 40 more.
	 */
	static final java.util.regex.Pattern MODIFIER_ROW = java.util.regex.Pattern.compile(
			"^([+\\-x])?\\s*(\\d+)(%?)\\s+(.+?)\\s*$", java.util.regex.Pattern.CASE_INSENSITIVE);
	/** How many rows either side of an amount row still belong to that offer. */
	private static final int OFFER_BLOCK_SPAN = 6;

	private static String plain(List<String> texts, int index) {
		if (index < 0 || index >= texts.size() || texts.get(index) == null) {
			return "";
		}
		return net.runelite.client.util.Text.removeTags(texts.get(index)).trim();
	}

	/**
	 * Parses the offer dialog's rows, anchored on each "Amount: X to Y" row:
	 * the name is the row before it and the modifier the row after, with blank
	 * rows skipped on both sides. The rows are only consecutive once the
	 * dialog's untexted widgets are stepped over, which is why this searches
	 * rather than indexes.
	 *
	 * <p>The modifier row is kept verbatim as modifier_text even when it does
	 * not parse, so a wording this pattern misses still reaches the server.
	 * Package-private for tests.
	 */
	static List<Map<String, Object>> parseTaskOffers(List<String> texts) {
		List<Map<String, Object>> offers = new ArrayList<>();
		for (int i = 0; i < texts.size(); i++) {
			java.util.regex.Matcher amount = AMOUNT_ROW.matcher(plain(texts, i));
			if (!amount.matches()) {
				continue;
			}
			String name = nameBefore(texts, i);
			if (name == null) {
				continue;
			}
			Map<String, Object> offer = new LinkedHashMap<>();
			offer.put("name", name);
			int min = Integer.parseInt(amount.group(1));
			offer.put("amount_min", min);
			offer.put("amount_max",
					amount.group(2) == null ? min : Integer.parseInt(amount.group(2)));

			String modifier = modifierAfter(texts, i);
			if (modifier != null) {
				offer.put("modifier_text", modifier);
				java.util.regex.Matcher mod = MODIFIER_ROW.matcher(modifier);
				if (mod.matches()) {
					String sign = mod.group(1) == null ? "" : mod.group(1);
					int value = Integer.parseInt(mod.group(2));
					offer.put("modifier_value", "-".equals(sign) ? -value : value);
					offer.put("modifier_is_percent", !mod.group(3).isEmpty());
					offer.put("modifier_multiplies", "x".equalsIgnoreCase(sign));
					offer.put("modifier_label", mod.group(4));
				}
			}
			offers.add(offer);
		}
		return offers;
	}

	/** The task name an amount row belongs to: the row above it, blanks aside. */
	private static String nameBefore(List<String> texts, int amountIndex) {
		for (int i = amountIndex - 1;
				i >= 0 && i >= amountIndex - OFFER_BLOCK_SPAN; i--) {
			String row = plain(texts, i);
			if (row.isEmpty() || MODIFIER_ROW.matcher(row).matches()) {
				continue;
			}
			return AMOUNT_ROW.matcher(row).matches() ? null : row;
		}
		return null;
	}

	/**
	 * The modifier an amount row belongs to: the first row below it, blanks
	 * aside. The next offer's name sits in that same gap, so a row butting up
	 * against the next amount row is that name and not this offer's modifier.
	 */
	private static String modifierAfter(List<String> texts, int amountIndex) {
		List<String> block = new ArrayList<>();
		boolean nextOfferReached = false;
		for (int i = amountIndex + 1;
				i < texts.size() && i <= amountIndex + OFFER_BLOCK_SPAN; i++) {
			String row = plain(texts, i);
			if (row.isEmpty()) {
				continue;
			}
			if (AMOUNT_ROW.matcher(row).matches()) {
				nextOfferReached = true;
				break;
			}
			block.add(row);
		}
		if (nextOfferReached && !block.isEmpty()) {
			block.remove(block.size() - 1);
		}
		return block.isEmpty() ? null : block.get(0);
	}

	private SlayerSyncPayload buildPayload(String playerUsername, Snapshot s) {
		SlayerSyncPayload.State state = new SlayerSyncPayload.State(
				s.taskId,
				s.taskName,
				s.bossTaskId,
				s.areaId,
				s.masterId,
				s.amountRemaining,
				s.amountOriginal,
				s.points,
				s.streak,
				s.wildernessStreak,
				s.blockList,
				s.unlockBitfields,
				buildExtra(s),
				s.slayerLevel,
				s.slayerXp,
				Instant.now().toString());
		return new SlayerSyncPayload(playerUsername, state);
	}

	/** Assembles the state extra map: stored task, each master's block list and any recent task offers. */
	private Map<String, Object> buildExtra(Snapshot s) {
		Map<String, Object> extra = storedTaskExtra(storedTask);
		extra.put("blocked_by_master", s.blockedByMaster);
		if (!pendingOffers.isEmpty()
				&& System.currentTimeMillis() - offersCapturedMs <= OFFER_RETENTION_MS) {
			extra.put("task_offers", pendingOffers);
			extra.put("task_offers_captured_at", offersCapturedAt);
			if (pendingOfferRows != null) {
				extra.put("task_offer_rows", pendingOfferRows);
			}
		}
		return extra;
	}

	/**
	 * The extra-map entries for the captured Task Storage slot. Empty until a
	 * capture exists; zeros mean "capture confirmed the storage is empty",
	 * which the backend distinguishes from never-captured.
	 */
	static Map<String, Object> storedTaskExtra(StoredTaskCapture capture) {
		Map<String, Object> extra = new LinkedHashMap<>();
		if (capture == null) {
			return extra;
		}
		extra.put("stored_task_id", capture.taskId);
		extra.put("stored_task_amount", capture.amount);
		extra.put("stored_boss_task_id", capture.bossTaskId);
		if (capture.taskName != null) {
			extra.put("stored_task_name", capture.taskName);
		}
		extra.put("stored_task_captured_at", capture.capturedAt);
		return extra;
	}

	/** Reloads the last stored-task capture so restarts keep the known slot. */
	private void restoreStoredTask() {
		String stored = configManager.getRSProfileConfiguration("osrscompanion", STORED_TASK_CONFIG_KEY);
		if (stored == null || stored.isEmpty()) {
			return;
		}
		try {
			StoredTaskCapture parsed = gson.fromJson(stored, StoredTaskCapture.class);
			if (parsed != null && parsed.capturedAt != null) {
				storedTask = parsed;
			}
		} catch (RuntimeException e) {
			configManager.unsetRSProfileConfiguration("osrscompanion", STORED_TASK_CONFIG_KEY);
		}
	}
}

package com.osrscompanion;

import java.util.List;

/** Whether an NPC counts as the slayer task's monster. No game access. */
final class SlayerMonsters {
	private SlayerMonsters() {
	}

	/**
	 * True when the NPC's name is one of the location's monsters (any case), or, when the location
	 * names none, loosely matches the task: "Abyssal demon" for "Abyssal demons", "Kalphite worker"
	 * for "Kalphite", "Greater demon" for "Greater demons".
	 */
	static boolean matches(String npcName, List<String> monsters, String taskName) {
		String npc = clean(npcName);
		if (npc.isEmpty()) {
			return false;
		}
		if (monsters != null && !monsters.isEmpty()) {
			for (String m : monsters) {
				if (npc.equals(clean(m))) {
					return true;
				}
			}
			return false;
		}
		String task = clean(taskName);
		if (task.isEmpty()) {
			return false;
		}
		// "Zombies" is "zombie" + s, "Wolves" is "wolf": try the plain cut and the English singular.
		String[] tasks = {task, task.endsWith("s") ? task.substring(0, task.length() - 1) : task, singular(task)};
		String[] npcs = {npc, singular(npc)};
		for (String n : npcs) {
			for (String t : tasks) {
				if (n.equals(t) || n.startsWith(t + " ") || n.endsWith(" " + t)) {
					return true;
				}
			}
		}
		return false;
	}

	private static String clean(String s) {
		return s == null ? "" : s.replaceAll("<[^>]*>", "").replace(' ', ' ').trim().toLowerCase();
	}

	/** "abyssal demons" -> "abyssal demon", "dagannoth" stays, "wolves" -> "wolf", "harpie bug swarms" -> "harpie bug swarm". Lower case in. */
	static String singular(String s) {
		if (s.endsWith("ves")) {
			return s.substring(0, s.length() - 3) + "f";
		}
		if (s.endsWith("ies") && s.length() > 4) {
			return s.substring(0, s.length() - 3) + "y";
		}
		if (s.endsWith("ches") || s.endsWith("shes") || s.endsWith("xes") || s.endsWith("sses")) {
			return s.substring(0, s.length() - 2);
		}
		if (s.endsWith("s") && !s.endsWith("ss") && s.length() > 3) {
			return s.substring(0, s.length() - 1);
		}
		return s;
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import com.osrscompanion.model.SlayerRewardsPayload;
import java.time.Instant;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Scrapes the Slayer Rewards task list interface when the player opens it and
 * syncs the rows to the OSRS Companion API.
 *
 * <p>The game renders, per task: the name with its amount range, a status icon
 * (available / cannot assign / blocked / current task), and the assignment
 * percentage the game itself computed for THIS player's blocks, unlocks and
 * levels. That percentage is data no varp exposes, and it is the calibration
 * source for OSRS Companion's task-probability engine, so this is worth capturing
 * every time the interface opens. Opportunistic by nature: it only fires when
 * the player visits the rewards screen.
 *
 * <p>Each row is a run of four consecutive children in the DRAWABLE layer:
 * name text (type 4), spacer (type 3), status sprite (type 5), percent text
 * (type 4). Status is read from the sprite id, never from colours.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class SlayerRewardsMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "slayer-rewards-sync";

	/** "Aberrant Spectres (130-200)" -> name, min, max. */
	private static final Pattern NAME_WITH_RANGE =
			Pattern.compile("^(.*?)\\s*\\((\\d+)\\s*-\\s*(\\d+)\\)\\s*$");
	private static final Pattern PERCENT = Pattern.compile("^([\\d.]+)%$");

	private static final int TYPE_TEXT = 4;
	private static final int TYPE_SPACER = 3;
	private static final int TYPE_SPRITE = 5;

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final Gson gson;

	/** Minimum interval between scrape posts even when content changed. */
	private static final long MIN_SCRAPE_INTERVAL_MS = 10_000L;

	/**
	 * Dedupe key of the last sent scrape: rows + master only. The payload's
	 * captured_at is stamped per build, so comparing full payload JSON would
	 * never match and every tab toggle in the rewards UI would post a full
	 * snapshot.
	 */
	private String lastContentKey;
	private long lastScrapeSentMs;

	public void stop() {
		lastContentKey = null;
		lastScrapeSentMs = 0;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() != InterfaceID.SLAYER_REWARDS_TASK_LIST) {
				return;
			}
			// Children populate as the interface finishes loading; read next cycle.
			Guard.invokeLater(clientThread, GUARD_FEATURE, this::scrapeAndSync);
		});
	}

	/** Reads the task list rows and syncs them. Client thread only. */
	private void scrapeAndSync() {
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		Widget drawable = client.getWidget(InterfaceID.SlayerRewardsTaskList.DRAWABLE);
		if (drawable == null) {
			return;
		}
		Widget[] children = drawable.getDynamicChildren();
		if (children == null || children.length < 4) {
			return;
		}

		List<SlayerRewardsPayload.Row> rows = new ArrayList<>();
		for (int i = 0; i + 3 < children.length; i++) {
			if (!isTaskRow(children, i)) {
				continue;
			}
			SlayerRewardsPayload.Row row = parseRow(
					children[i].getText(),
					children[i + 2].getSpriteId(),
					children[i + 3].getText());
			if (row != null) {
				rows.add(row);
				i += 3;
			}
		}
		if (rows.isEmpty()) {
			return;
		}

		int masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		String contentKey = masterId + "|" + gson.toJson(rows);
		if (contentKey.equals(lastContentKey)) {
			return;
		}
		long nowMs = System.currentTimeMillis();
		if (nowMs - lastScrapeSentMs < MIN_SCRAPE_INTERVAL_MS) {
			return;
		}
		SlayerRewardsPayload payload = new SlayerRewardsPayload(
				playerUsername,
				masterId == 0 ? null : masterId,
				rows,
				Instant.now().toString());
		lastContentKey = contentKey;
		lastScrapeSentMs = nowMs;
		apiClient.sendSlayerRewards(payload);
	}

	private static boolean isTaskRow(Widget[] children, int i) {
		return children[i].getType() == TYPE_TEXT && children[i].getText() != null
				&& children[i + 1].getType() == TYPE_SPACER
				&& children[i + 2].getType() == TYPE_SPRITE
				&& children[i + 3].getType() == TYPE_TEXT && children[i + 3].getText() != null;
	}

	/** Parses one widget row; package-private for tests. Returns null on mismatch. */
	static SlayerRewardsPayload.Row parseRow(String nameText, int spriteId, String percentText) {
		if (nameText == null || percentText == null) {
			return null;
		}
		Matcher percentMatcher = PERCENT.matcher(Text.removeTags(percentText).trim());
		if (!percentMatcher.matches()) {
			return null;
		}
		double percent;
		try {
			percent = Double.parseDouble(percentMatcher.group(1));
		} catch (NumberFormatException e) {
			return null;
		}

		String name = Text.removeTags(nameText).trim();
		Integer amountMin = null;
		Integer amountMax = null;
		Matcher nameMatcher = NAME_WITH_RANGE.matcher(name);
		if (nameMatcher.matches()) {
			name = nameMatcher.group(1).trim();
			amountMin = Integer.valueOf(nameMatcher.group(2));
			amountMax = Integer.valueOf(nameMatcher.group(3));
		}
		if (name.isEmpty()) {
			return null;
		}
		return new SlayerRewardsPayload.Row(name, amountMin, amountMax, percent, spriteId);
	}
}

package com.osrscompanion;

import com.google.gson.annotations.SerializedName;
import java.time.Instant;
import java.util.*;

/**
 * One slayer session: one task assignment at one location, from the first time you walk into the
 * area until the task is done (or you move to another location / get another task). It counts
 * the time actually spent inside the area (tick by tick, only while inside), the separate visits
 * (trips), the task kills, each monster's kill time and the loot's value.
 *
 * <p>Stored as JSON in the RuneScape profile's config so a client restart keeps it, and sent to the
 * website as the POST /api/runelite/slayer/sessions/ body ({@link #payload}). No game access: the
 * caller passes the time.
 */
final class SlayerSession {
	/** The website charts the distribution from at most this many recent kill times. */
	static final int MAX_KILL_TIMES = 500;
	/**
	 * Longer gaps between two ticks inside the area are not counted (the client froze, or this is the
	 * first tick after a restart): a tick is 600 ms, so this only drops real gaps.
	 */
	static final long MAX_TICK_GAP_MS = 3_000L;
	/** A bank trip counts at most this long (lingering at the bank is not part of the task). */
	static final long BANK_TRIP_CAP_MS = 8 * 60_000L;
	/**
	 * The trip timer runs on this long after leaving the area (a bank trip); not back by then, that time
	 * is taken off again and the timer stands still until you are back.
	 */
	static final long TRIP_GRACE_MS = 15 * 60_000L;
	/**
	 * A time away longer than this is not a bank trip (a break, another activity): the trip timer's limit,
	 * so the waiting is left out of the bank time (and the estimate) as it is of the timer.
	 */
	static final long MAX_BANK_TRIP_MS = TRIP_GRACE_MS;

	@SerializedName("session_uuid")
	String uuid;
	/** The character it belongs to (the website's player). */
	@SerializedName("player")
	String player;
	/** Which assignment this is (see {@link SlayerHelperManager}); a different task starts a new session. */
	@SerializedName("task_key")
	String taskKey;
	@SerializedName("task_id")
	Integer taskId;
	@SerializedName("task_name")
	String taskName;
	@SerializedName("area_id")
	Integer areaId;
	@SerializedName("master")
	String master;
	@SerializedName("location_key")
	String locationKey;
	@SerializedName("location_name")
	String locationName;
	/** NPC names that count as the task monster at this location (empty: by the task's name). */
	@SerializedName("monsters")
	List<String> monsters = new ArrayList<>();
	@SerializedName("amount_original")
	int amountOriginal;
	@SerializedName("amount_at_start")
	int amountAtStart;
	@SerializedName("amount_remaining")
	int amountRemaining;
	@SerializedName("started_ms")
	long startedMs;
	/** 0 while the session is open. */
	@SerializedName("ended_ms")
	long endedMs;
	@SerializedName("completed")
	boolean completed;
	@SerializedName("time_in_area_ms")
	long timeInAreaMs;
	@SerializedName("trip_count")
	int tripCount;
	/** Times away from the area that included a bank visit and ended back here, and their total length. */
	@SerializedName("bank_trips")
	int bankTrips;
	@SerializedName("bank_trip_ms")
	long bankTripMs;
	/** When the player last left the area (0: inside, or not counting), and whether a bank was opened since. */
	@SerializedName("left_ms")
	long leftMs;
	@SerializedName("bank_seen_away")
	boolean bankSeenAway;
	/** The times away from the area that were back within {@link #TRIP_GRACE_MS}: part of the trip timer. */
	@SerializedName("away_counted_ms")
	long awayCountedMs;
	@SerializedName("kills")
	int kills;
	@SerializedName("kill_time_total_ms")
	long killTimeTotalMs;
	@SerializedName("kill_time_count")
	int killTimeCount;
	@SerializedName("kill_times_ms")
	List<Long> killTimesMs = new ArrayList<>();
	@SerializedName("loot_gp")
	long lootGp;
	/**
	 * Task kills that were a boss variant of the task (Alchemical Hydra on a hydra task, see
	 * {@link SlayerBosses}), and the fight time of the timed boss and regular kills: the website tells a
	 * regular, boss or mixed session apart from them (a boss counts as one kill but is far slower).
	 */
	@SerializedName("boss_kills")
	int bossKills;
	@SerializedName("boss_kill_time_ms_total")
	long bossKillTimeMs;
	@SerializedName("regular_kill_time_ms_total")
	long regularKillTimeMs;
	/** Task kills per exact NPC, region and multi-combat (see {@link SlayerKillLog}); sent whole as kill_log. */
	@SerializedName("kill_log")
	List<SlayerKillLog.Entry> killLog = new ArrayList<>();
	/** The centre of the area round a boss or an unknown spot (x, y, plane) when the session is at one, for a restart. */
	@SerializedName("boss_area_tile")
	List<Integer> bossAreaTile;

	/** Slayer XP gained while the session was open (the task's kills). */
	@SerializedName("slayer_xp")
	long slayerXp;
	/** Inside the area on the last tick, and when that tick was (0: none yet since loading). */
	@SerializedName("inside")
	boolean inside;
	@SerializedName("last_tick_ms")
	long lastTickMs;
	/** Last time anything in the session changed (for the sync and the restore after a restart). */
	@SerializedName("updated_ms")
	long updatedMs;

	/** Starts a session on the first tick inside the area: trip 1. */
	static SlayerSession start(String taskKey, Integer taskId, String taskName, Integer areaId, String master,
			String locationKey, String locationName, int amountOriginal, int amountRemaining, long nowMs) {
		SlayerSession s = new SlayerSession();
		s.uuid = UUID.randomUUID().toString();
		s.taskKey = taskKey;
		s.taskId = taskId;
		s.taskName = taskName;
		s.areaId = areaId;
		s.master = master;
		s.locationKey = locationKey;
		s.locationName = locationName;
		s.amountOriginal = amountOriginal;
		s.amountAtStart = amountRemaining;
		s.amountRemaining = amountRemaining;
		s.startedMs = nowMs;
		s.updatedMs = nowMs;
		return s;
	}

	/**
	 * One game tick: while inside, the time since the last tick inside is added to the time at the
	 * location; walking (or teleporting) back in starts a new trip. Leaving notes the time; coming back
	 * after a bank visit (see {@link #bankOpened}) counts the time away as a bank trip. Returns true on entering.
	 */
	boolean tick(boolean nowInside, long nowMs) {
		boolean entered = false;
		if (nowInside) {
			if (!inside) {
				tripCount++;
				entered = true;
				updatedMs = nowMs;
				if (leftMs > 0) {
					long away = nowMs - leftMs;
					if (bankSeenAway && away > 0 && away <= MAX_BANK_TRIP_MS) {
						bankTrips++;
						bankTripMs += Math.min(away, BANK_TRIP_CAP_MS);
					}
					// Back within the grace time: the time away stays on the trip timer; later, it never counted.
					if (away > 0 && away <= TRIP_GRACE_MS) {
						awayCountedMs += away;
					}
				}
				leftMs = 0;
				bankSeenAway = false;
			} else if (lastTickMs > 0) {
				long gap = nowMs - lastTickMs;
				if (gap > 0 && gap <= MAX_TICK_GAP_MS) {
					timeInAreaMs += gap;
					updatedMs = nowMs;
				}
			}
			lastTickMs = nowMs;
		} else if (inside) {
			updatedMs = nowMs;
			leftMs = nowMs;
			bankSeenAway = false;
		}
		inside = nowInside;
		return entered;
	}

	/** A bank was opened: while away from the area, the time away becomes a bank trip once back. */
	void bankOpened() {
		if (!inside && leftMs > 0) {
			bankSeenAway = true;
		}
	}

	/** After loading from the config: the time offline is never counted (nor as a bank trip). */
	void resumed() {
		lastTickMs = 0;
		leftMs = 0;
		bankSeenAway = false;
	}

	void addKills(int n, long nowMs) {
		if (n > 0) {
			kills += n;
			updatedMs = nowMs;
		}
	}

	void addKillTime(long ms, long nowMs) {
		addKillTime(ms, false, nowMs);
	}

	/** A timed kill; a boss variant's also counts as a boss kill. */
	void addKillTime(long ms, boolean boss, long nowMs) {
		if (boss) {
			bossKills++;
			bossKillTimeMs += ms;
		} else {
			regularKillTimeMs += ms;
		}
		killTimeTotalMs += ms;
		killTimeCount++;
		killTimesMs.add(ms);
		while (killTimesMs.size() > MAX_KILL_TIMES) {
			killTimesMs.remove(0);
		}
		updatedMs = nowMs;
	}

	/** n task kills of this NPC in the kill log (they are counted in {@link #kills} by {@link #addKills}). */
	void logKills(SlayerKillLog.Npc npc, int n, long nowMs) {
		if (npc != null && n > 0) {
			SlayerKillLog.addKills(killLog(), npc, n);
			updatedMs = nowMs;
		}
	}

	/** A timed kill of this NPC in the kill log (it is in the session's kill times by {@link #addKillTime}). */
	void logFightTime(SlayerKillLog.Npc npc, long ms, long nowMs) {
		if (npc != null && ms >= 0) {
			SlayerKillLog.addFightTime(killLog(), npc, ms);
			updatedMs = nowMs;
		}
	}

	private List<SlayerKillLog.Entry> killLog() {
		if (killLog == null) {
			killLog = new ArrayList<>();
		}
		return killLog;
	}

	void addLoot(long gp, long nowMs) {
		if (gp > 0) {
			lootGp += gp;
			updatedMs = nowMs;
		}
	}

	void addSlayerXp(long xp, long nowMs) {
		if (xp > 0) {
			slayerXp += xp;
			updatedMs = nowMs;
		}
	}

	void setRemaining(int remaining, long nowMs) {
		if (remaining != amountRemaining) {
			amountRemaining = remaining;
			updatedMs = nowMs;
		}
	}

	/**
	 * Logged out: you are out of the area from now (the website's timer runs on for 15 minutes at most, as
	 * after walking out); the session stays open, a relog goes on with it (see {@link #resumed}).
	 */
	void loggedOut(long nowMs) {
		if (endedMs == 0 && inside) {
			leftMs = nowMs;
			updatedMs = nowMs;
		}
		inside = false;
		lastTickMs = 0;
	}

	/**
	 * The task is done (completed) or this session ends another way (new task, other location). Ended
	 * while away from the area (not by the last kill): it ends when you left, never later, so the waiting
	 * (past the 15 minutes or not) is not part of it; the trip timer stays at what it was then.
	 */
	void close(boolean done, long nowMs) {
		if (endedMs == 0) {
			endedMs = !done && !inside && leftMs > 0 && leftMs <= nowMs ? leftMs : nowMs;
			completed = done;
			if (done) {
				amountRemaining = 0;
			}
			inside = false;
			updatedMs = nowMs;
		}
	}

	boolean isOpen() {
		return endedMs == 0;
	}

	/** The per-monster average kill time; 0 before the first timed kill. */
	long avgKillMs() {
		return killTimeCount == 0 ? 0 : Math.round(killTimeTotalMs / (double) killTimeCount);
	}

	/** Task kills per hour spent in the area; 0 until there is time and kills. */
	double killsPerHour() {
		return timeInAreaMs < 1_000 || kills == 0 ? 0 : Math.round(kills * 3_600_000.0 / timeInAreaMs * 10) / 10.0;
	}

	long avgLootGp() {
		return kills == 0 ? 0 : Math.round(lootGp / (double) kills);
	}

	/**
	 * The trip timer: the time in the area plus the times away that were back within
	 * {@link #TRIP_GRACE_MS} (bank trips), and, while away now (an open session), the time since leaving
	 * up to that limit. Away longer, that time comes off again and the timer pauses until you are back;
	 * coming back goes on from there. {@code liveInsideMs}: the time inside since the last tick.
	 */
	long tripMs(long nowMs, long liveInsideMs) {
		long ms = timeInAreaMs + awayCountedMs + Math.max(0, liveInsideMs);
		if (endedMs == 0 && !inside && leftMs > 0) {
			long away = nowMs - leftMs;
			if (away > 0 && away <= TRIP_GRACE_MS) {
				ms += away;
			}
		}
		return Math.max(0, ms);
	}

	/** Kills before the estimate uses the time in the area (until then the fight time stands in). */
	static final int ESTIMATE_MIN_KILLS = 3;

	/**
	 * Remaining kills times the real time a kill takes: the time in the area plus the bank trips, per
	 * kill (walking to spots, looting, waiting and AFK included, as the website's Est. time left), or
	 * the average fight time for the first kills; 0 when not known yet.
	 */
	long estimatedLeftMs() {
		long perKill = kills >= ESTIMATE_MIN_KILLS && timeInAreaMs >= 1_000
			? Math.round((timeInAreaMs + Math.max(0, bankTripMs)) / (double) kills)
			: avgKillMs();
		return Math.max(0, amountRemaining) * perKill;
	}

	/** The POST /api/runelite/slayer/sessions/ body, keys as the contract has them. */
	Map<String, Object> payload(String player) {
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("player", player);
		m.put("session_uuid", uuid);
		m.put("task_id", taskId);
		m.put("task_name", taskName);
		m.put("area_id", areaId);
		m.put("master", master);
		m.put("location_key", locationKey);
		m.put("amount_original", amountOriginal);
		m.put("amount_at_start", amountAtStart);
		m.put("amount_remaining", amountRemaining);
		m.put("started_at", iso(startedMs));
		m.put("ended_at", endedMs == 0 ? null : iso(endedMs));
		m.put("completed", completed);
		m.put("time_in_area_sec", timeInAreaMs / 1000);
		m.put("trip_count", tripCount);
		m.put("bank_trips", bankTrips);
		m.put("bank_trip_sec", bankTripMs / 1000);
		// The trip timer without the time away now; when away (open session), when you left: the website
		// runs it on for up to TRIP_GRACE_MS from there, as here.
		m.put("trip_sec", (timeInAreaMs + awayCountedMs) / 1000);
		m.put("left_at", endedMs == 0 && !inside && leftMs > 0 ? iso(leftMs) : null);
		m.put("kills", kills);
		m.put("avg_kill_ms", avgKillMs());
		m.put("kills_per_hour", killsPerHour());
		m.put("loot_gp", lootGp);
		m.put("avg_loot_gp", avgLootGp());
		m.put("slayer_xp", slayerXp);
		m.put("kill_times_ms", new ArrayList<>(killTimesMs));
		// Never more boss kills than the task's count (a boss timed but its kill not counted, e.g. just before the session).
		m.put("boss_kills", Math.max(0, Math.min(bossKills, Math.max(kills, 0))));
		m.put("boss_kill_time_ms_total", bossKillTimeMs);
		m.put("regular_kill_time_ms_total", regularKillTimeMs);
		m.put("kill_log", SlayerKillLog.payload(killLog));
		return m;
	}

	/** "2026-10-07T12:00:00Z": whole seconds. */
	static String iso(long epochMs) {
		return Instant.ofEpochSecond(Math.floorDiv(epochMs, 1000L)).toString();
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.model.BankSyncPayload;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

/**
 * Uploads bank-memory sources (bank, inventory and gear, vaults, cargo
 * holds, pouches, storage-item ledgers) on one shared cadence:
 *
 * <ul>
 *   <li>A source's first contents of the session go up at once.</li>
 *   <li>Later changes are held and collapsed for {@link #DEFAULT_DEBOUNCE_SECONDS}, so routine
 *       skilling costs one request per burst.</li>
 *   <li>Unchanged contents are never re-sent.</li>
 *   <li>{@link #flushPending()} (logout, plugin stop) and an {@code immediate}
 *       submit (a goal completed locally, a container was emptied, the panel's
 *       sync button) skip the wait.</li>
 * </ul>
 *
 * Several sources may share one syncer (the bank monitor sends bank,
 * inventory and worn gear together); pending contents merge per source.
 * Linked sources ({@link #linkSources}) always go up together: when one of
 * them changes, the others in the same submit are sent with it even when
 * unchanged (the website reads an "inventory" without "worn" as an older
 * plugin's inventory + worn gear). Gates (sync
 * enabled, app key, game mode, username) are supplied as functions so this
 * stays unit-testable.
 */
final class SourceSyncer {
	static final long DEFAULT_DEBOUNCE_SECONDS = 15;

	private final String label;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final LongSupplier clockMs;
	private final BooleanSupplier syncEnabled;
	private final Supplier<String> username;
	private final Consumer<BankSyncPayload> send;

	/** Runs after every upload; set by the monitor (the bank monitor triggers a roadmap reconcile). */
	private volatile Runnable onSent;
	/** Runs after an urgent upload (immediate submit, logout): asks the API outbox to send at once. */
	private volatile Runnable priorityFlush;

	/** Contents last uploaded this session, per source. A source absent here was never sent. */
	private final Map<String, Map<Integer, Integer>> sentBySource = new HashMap<>();
	private final Map<String, Map<Integer, Integer>> pendingBySource = new LinkedHashMap<>();
	/** Groups of sources that are always uploaded together (see the class comment). */
	private final List<Set<String>> linkedGroups = new ArrayList<>();
	private String pendingUsername;
	private ScheduledFuture<?> pendingSync;
	private long pendingDueMs;

	SourceSyncer(
			String label,
			Gson gson,
			ScheduledExecutorService executor,
			BooleanSupplier syncEnabled,
			Supplier<String> username,
			Consumer<BankSyncPayload> send) {
		this(label, gson, executor, System::currentTimeMillis, syncEnabled, username, send);
	}

	SourceSyncer(
			String label,
			Gson gson,
			ScheduledExecutorService executor,
			LongSupplier clockMs,
			BooleanSupplier syncEnabled,
			Supplier<String> username,
			Consumer<BankSyncPayload> send) {
		this.label = label;
		this.gson = gson;
		// The debounced upload runs as "sync", which is never turned off: contents already read must
		// still go up when the monitor's own feature was turned off (its breaker), or a later upload of
		// another source would be the only one the website sees.
		this.executor = GuardedExecutor.wrap(Guard.SYNC_FEATURE, executor);
		this.clockMs = clockMs;
		this.syncEnabled = syncEnabled;
		this.username = username;
		this.send = send;
	}

	void setPriorityFlush(Runnable priorityFlush) {
		this.priorityFlush = priorityFlush;
	}

	/**
	 * These sources always go up together: a submit that changes one of them also sends the others it
	 * carries, unchanged or not.
	 */
	synchronized void linkSources(String... sources) {
		linkedGroups.add(new HashSet<>(Arrays.asList(sources)));
	}

	/** New contents for the syncer's single source (its label). */
	void submit(Map<Integer, Integer> quantities, boolean immediate) {
		Map<String, Map<Integer, Integer>> bySource = new LinkedHashMap<>();
		bySource.put(label, quantities == null ? Map.of() : quantities);
		submitSources(bySource, immediate);
	}

	/**
	 * New contents for one or more sources (canonical item id to quantity).
	 * Uploaded after the debounce, or right away when {@code immediate}.
	 */
	synchronized void submitSources(Map<String, Map<Integer, Integer>> bySource, boolean immediate) {
		if (bySource == null || bySource.isEmpty() || !syncEnabled.getAsBoolean()) {
			return;
		}
		String playerUsername = username.get();
		if (playerUsername == null) {
			return;
		}
		boolean neverSent = false;
		boolean anyChange = false;
		for (Map.Entry<String, Map<Integer, Integer>> e : bySource.entrySet()) {
			String source = e.getKey();
			Map<Integer, Integer> contents = new LinkedHashMap<>(e.getValue());
			Map<Integer, Integer> baseline = pendingBySource.containsKey(source)
					? pendingBySource.get(source) : sentBySource.get(source);
			Map<Integer, Integer> sent = sentBySource.get(source);
			if (sent != null && sent.equals(contents)) {
				pendingBySource.remove(source); // back to what the server has
				continue;
			}
			if (baseline != null && baseline.equals(contents)) {
				continue; // already pending as-is
			}
			anyChange = true;
			if (sent == null) {
				neverSent = true;
			}
			pendingBySource.put(source, contents);
		}
		for (Set<String> group : linkedGroups) {
			if (group.stream().noneMatch(pendingBySource::containsKey)) {
				continue;
			}
			for (String source : group) {
				if (!pendingBySource.containsKey(source) && bySource.containsKey(source)) {
					pendingBySource.put(source, new LinkedHashMap<>(bySource.get(source)));
				}
			}
		}
		if (pendingBySource.isEmpty()) {
			cancelPending();
			return;
		}
		pendingUsername = playerUsername;
		if (immediate || neverSent) {
			// A source's first contents go with the login burst; an immediate one is urgent.
			flush(immediate);
			return;
		}
		if (!anyChange && pendingSync != null) {
			return;
		}
		long delayMs = TimeUnit.SECONDS.toMillis(DEFAULT_DEBOUNCE_SECONDS);
		long now = clockMs.getAsLong();
		if (pendingSync != null) {
			// A shorter wait already running (goal change) is never extended.
			delayMs = Math.min(delayMs, Math.max(0, pendingDueMs - now));
			cancelPending();
		}
		pendingDueMs = now + delayMs;
		pendingSync = executor.schedule(() -> flush(false), delayMs, TimeUnit.MILLISECONDS);
	}

	/** Sends whatever is pending now (logout, plugin shutdown, forced sync). */
	synchronized void flushPending() {
		flush(true);
	}

	private synchronized void flush(boolean urgent) {
		cancelPending();
		if (pendingBySource.isEmpty() || pendingUsername == null) {
			return;
		}
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		for (Map.Entry<String, Map<Integer, Integer>> e : pendingBySource.entrySet()) {
			itemsBySource.put(e.getKey(), ItemCollector.toBankItemList(e.getValue()));
			sentBySource.put(e.getKey(), e.getValue());
		}
		BankSyncPayload payload = new BankSyncPayload(pendingUsername, itemsBySource);
		pendingBySource.clear();
		send.accept(payload);
		Runnable flush = priorityFlush;
		if (urgent && flush != null) {
			flush.run();
		}
		Runnable listener = onSent;
		if (listener != null) {
			listener.run();
		}
	}

	/** Forgets what was sent so the next submit uploads even unchanged contents. */
	synchronized void invalidate() {
		sentBySource.clear();
	}

	synchronized void stop() {
		flushPending();
		sentBySource.clear();
	}


	private void cancelPending() {
		if (pendingSync != null) {
			pendingSync.cancel(false);
			pendingSync = null;
		}
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import lombok.Getter;
import com.osrscompanion.model.BossGear;
import com.osrscompanion.model.FarmRoute;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;

/**
 * How many trips your bank supports, worked out while the bank is open: for the active boss setup
 * ("Enough for ~6 trips, runs out of: Prayer potion(4)") and for the farm route ("~4 farm runs").
 * Per trip it takes what your last logged trips at that boss used on average, or else the setup's
 * inventory and rune pouch (only what gets used up: food, potions by doses, runes, ammo, teleports).
 * Have = bank + what you carry, potions by doses and variants together. The results stay after the
 * bank closes, for the Boss gear window ("at your last bank visit").
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class SuppliesCheck {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "supplies-check";

	private final Client client;
	private final OSRSCompanionConfig config;
	private final BossGearManager bossGear;
	private final FarmRunManager farmRun;
	private final SupplyCounter counter;

	/** One supply in a result: its name and item, how many a trip takes, how many you have and how many trips that lasts. */
	static final class Row {
		final String name;
		final int itemId;
		final String perTrip;
		final long have;
		final int trips;

		Row(String name, int itemId, String perTrip, long have, int trips) {
			this.name = name;
			this.itemId = itemId;
			this.perTrip = perTrip;
			this.have = have;
			this.trips = trips;
		}

		boolean isShort() {
			return trips < 1;
		}
	}

	/** One check: for which setup / route, how many trips, what runs out first, where the need comes from and every supply. */
	static final class Result {
		final int forId;
		final String title;
		final int trips;
		final String unit;
		final String runsOut;
		final String source;
		final List<Row> rows;

		Result(int forId, String title, int trips, String unit, String runsOut, String source, List<Row> rows) {
			this.forId = forId;
			this.title = title;
			this.trips = trips;
			this.unit = unit;
			this.runsOut = runsOut;
			this.source = source;
			this.rows = rows;
		}

		/** "Enough for ~6 trips" / "Not enough for one trip". */
		String headline() {
			if (trips < 1) {
				return "Not enough for one " + unit;
			}
			return "Enough for ~" + trips + " " + unit + (trips == 1 ? "" : "s");
		}
	}

	@Getter
	private volatile Result boss;
	@Getter
	private volatile Result farm;
	private boolean dirty;
	private Object lastSet;
	private Object lastRoute;

	public void clear() {
		boss = null;
		farm = null;
		lastSet = null;
		lastRoute = null;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGroupId() == InterfaceID.BANKMAIN) {
				dirty = true;
			}
		});
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			int id = event.getContainerId();
			if (id == InventoryID.BANK || id == InventoryID.INV || id == InventoryID.WORN) {
				dirty = true;
			}
		});
	}

	/** A trip planner switch changed: check again. */
	@Subscribe
	public void onConfigChanged(net.runelite.client.events.ConfigChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (OSRSCompanionConfig.CONFIG_GROUP.equals(event.getGroup()) && event.getKey().startsWith("tripPlanner")) {
				dirty = true;
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (event.getGameState() == GameState.LOGIN_SCREEN) {
				clear();
			}
		});
	}

	/** At most once a tick, and only while the bank is open and something changed (the bank, what you carry, the setup or route). */
	@Subscribe
	public void onGameTick(GameTick tick) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!(config.tripPlannerBoss() || config.tripPlannerFarm()) || client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null) {
				return;
			}
			// For the tool whose trip planner switch is on and that is active (no bank layout needed): the active
			// boss setup, the farm route of a run that is going.
			BossGear set = config.tripPlannerBoss() && bossGear.isSetActive() ? bossGear.getSet() : null;
			FarmRoute route = config.tripPlannerFarm() && farmRun.isRunning() ? farmRun.getRoute() : null;
			if (!dirty && set == lastSet && route == lastRoute) {
				return;
			}
			Map<String, Long> have = counter.bank();
			if (have == null) {
				return;
			}
			dirty = false;
			lastSet = set;
			lastRoute = route;
			for (Map.Entry<String, Long> e : counter.carried().entrySet()) {
				have.merge(e.getKey(), e.getValue(), Long::sum);
			}
			boss = set == null ? null : checkBoss(set, have);
			farm = route == null ? null : checkFarm(route, have);
		});
	}

	private Result checkBoss(BossGear set, Map<String, Long> have) {
		// What your last trips at this boss used, as the website worked them out from the game events.
		List<Map<String, Long>> past = set.getTripSupplies();
		Map<String, Double> need;
		String source;
		if (!past.isEmpty()) {
			need = TripSupplies.averagePerTrip(past);
			source = "Per trip: average of your last " + (past.size() == 1 ? "trip" : past.size() + " trips");
		} else {
			need = new LinkedHashMap<>();
			List<BossGear.Item> items = new ArrayList<>();
			for (BossGear.Item it : set.getInventory()) {
				if (it != null) {
					items.add(it);
				}
			}
			items.addAll(set.getPouch());
			for (BossGear.Item it : items) {
				addNeed(need, it.getItem(), it.getQty());
			}
			source = "Per trip: the setup's inventory";
		}
		return result(set.getId(), set.getBossName(), "trip", source, need, have);
	}

	private Result checkFarm(FarmRoute route, Map<String, Long> have) {
		Map<String, Double> need = new LinkedHashMap<>();
		for (FarmRoute.Stack s : farmRun.inventory()) {
			addNeed(need, s.getItem(), s.getQty());
		}
		return result(route.getId(), route.getName(), "farm run", "Per run: the route's seeds, compost and teleports", need, have);
	}

	private void addNeed(Map<String, Double> need, int itemId, int qty) {
		if (itemId <= 0 || qty <= 0 || !counter.consumable(itemId)) {
			return;
		}
		Map<String, Long> one = new LinkedHashMap<>();
		counter.add(one, itemId, qty);
		for (Map.Entry<String, Long> e : one.entrySet()) {
			need.merge(e.getKey(), e.getValue().doubleValue(), Double::sum);
		}
	}

	private Result result(int forId, String title, String unit, String source, Map<String, Double> need, Map<String, Long> have) {
		if (!config.tripPlannerRunes()) {
			// "Count runes" off: runes (and combination runes) don't limit the trips.
			need = new LinkedHashMap<>(need);
			need.keySet().removeIf(k -> {
				SupplyCounter.Rep rep = counter.rep(k);
				String name = rep == null ? k.substring(2) : rep.name;
				return name != null && name.toLowerCase(java.util.Locale.ROOT).endsWith(" rune");
			});
		}
		if (need.isEmpty()) {
			return null;
		}
		TripSupplies.Check check = TripSupplies.tripsSupported(need, have);
		List<Row> rows = new ArrayList<>();
		for (TripSupplies.Need n : check.needs) {
			SupplyCounter.Rep rep = counter.rep(n.key);
			String name = rep == null ? n.key.substring(2) : rep.name;
			int dose = rep == null ? 1 : rep.dose;
			// Dosed supplies show as items of the dose pictured ("1.8" Prayer potion(4)), the rest as they are.
			double per = n.perTrip / dose;
			String perTrip = per == Math.rint(per) ? String.valueOf((long) per) : String.format("%.1f", per);
			rows.add(new Row(name, rep == null ? -1 : rep.id, perTrip, n.have / dose, n.trips));
		}
		TripSupplies.Need limiting = check.limiting();
		String runsOut = limiting == null || rows.isEmpty() ? null : rows.get(0).name;
		return new Result(forId, title, check.trips, unit, runsOut, source, Collections.unmodifiableList(rows));
	}
}

package com.osrscompanion;

import static com.osrscompanion.GameUi.*;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The supplies check next to the open bank: how many trips (boss setup) and farm runs (route) the bank
 * and what you carry support, and per supply how many a trip takes and how many trips it lasts; red for
 * what you have less than one trip of. Beside the bank when there is room, else a one-line box over its top.
 */
@Singleton
public class SuppliesOverlay extends Overlay {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "supplies-overlay";

	private static final int WIDTH = 230;
	private static final int ROW = 22;
	private static final int MAX_ROWS = 8;

	private final Client client;
	private final OSRSCompanionConfig config;
	private final SuppliesCheck check;
	private final BossGearManager bossGear;
	private final FarmRunManager farmRun;
	private final ItemManager itemManager;

	@Inject
	public SuppliesOverlay(Client client, OSRSCompanionConfig config, SuppliesCheck check, BossGearManager bossGear, FarmRunManager farmRun,
		ItemManager itemManager) {
		this.client = client;
		this.config = config;
		this.check = check;
		this.bossGear = bossGear;
		this.farmRun = farmRun;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** The checks to show: the boss setup while it is active, the farm route while a run goes (only one of them is ever active). */
	private List<SuppliesCheck.Result> shown() {
		List<SuppliesCheck.Result> out = new ArrayList<>();
		SuppliesCheck.Result boss = check.getBoss();
		if (boss != null && config.tripPlannerBoss() && bossGear.isSetActive()) {
			out.add(boss);
		}
		SuppliesCheck.Result farm = check.getFarm();
		if (farm != null && config.tripPlannerFarm() && farmRun.isRunning()) {
			out.add(farm);
		}
		return out;
	}

	@Override
	public Dimension render(Graphics2D g) {
		return Guard.render(GUARD_FEATURE, () -> {
			if (!config.tripPlannerBoss() && !config.tripPlannerFarm()) {
				return null;
			}
			Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
			if (bank == null || bank.isHidden()) {
				return null;
			}
			List<SuppliesCheck.Result> results = shown();
			if (results.isEmpty()) {
				return null;
			}
			Rectangle b = bank.getBounds();
			boolean left = b.x >= WIDTH + 12;
			boolean right = client.getCanvasWidth() - (b.x + b.width) >= WIDTH + 12;
			boolean full = left || right;
			int h = 8;
			for (SuppliesCheck.Result r : results) {
				h += full ? 46 + Math.min(MAX_ROWS, r.rows.size()) * ROW + 6 : 30;
			}
			int x = left ? b.x - WIDTH - 6 : right ? b.x + b.width + 6 : b.x + b.width - WIDTH - 30;
			int y = full ? b.y + 4 : b.y + 34;
			Rectangle area = new Rectangle(x, y, WIDTH, h);
			box(g, area, BG, FRAME_DARK, FRAME_LIGHT);
			int ly = y + 4;
			for (SuppliesCheck.Result r : results) {
				ly = full ? drawFull(g, r, x, ly) : drawLine(g, r, x, ly);
			}
			return null;
		});
	}

	private static Color tone(int trips) {
		return trips < 1 ? RED : trips < 3 ? ORANGE : GREEN;
	}

	/** Headline and what runs out, in one box line (no room beside the bank). */
	private int drawLine(Graphics2D g, SuppliesCheck.Result r, int x, int y) {
		g.setFont(FontManager.getRunescapeSmallFont());
		text(g, truncate(r.title, g.getFontMetrics(), WIDTH - 16), x + 8, y + 12, BEIGE);
		String line = r.headline() + (r.runsOut == null ? "" : " (runs out of: " + r.runsOut + ")");
		text(g, truncate(line, g.getFontMetrics(), WIDTH - 16), x + 8, y + 25, tone(r.trips));
		return y + 30;
	}

	private int drawFull(Graphics2D g, SuppliesCheck.Result r, int x, int y) {
		g.setFont(FontManager.getRunescapeBoldFont());
		text(g, truncate(r.title, g.getFontMetrics(), WIDTH - 16), x + 8, y + 14, ORANGE);
		g.setFont(FontManager.getRunescapeSmallFont());
		String head = r.headline() + (r.runsOut == null ? "" : " (runs out of: " + r.runsOut + ")");
		text(g, truncate(head, g.getFontMetrics(), WIDTH - 16), x + 8, y + 28, tone(r.trips));
		text(g, truncate(r.source, g.getFontMetrics(), WIDTH - 16), x + 8, y + 41, GREY);
		int ry = y + 46;
		for (int i = 0; i < r.rows.size() && i < MAX_ROWS; i++) {
			SuppliesCheck.Row row = r.rows.get(i);
			Rectangle slot = new Rectangle(x + 8, ry, 20, 20);
			if (row.itemId > 0) {
				BufferedImage icon = itemManager.getImage(row.itemId);
				if (icon != null) {
					g.drawImage(icon, slot.x, slot.y, 20, 18, null);
				}
			}
			Color c = row.isShort() ? RED : Color.WHITE;
			String word = "trip".equals(r.unit) ? "trip" : "run";
			String right = row.trips == Integer.MAX_VALUE ? "" : row.trips + " " + word + (row.trips == 1 ? "" : "s");
			int rw = g.getFontMetrics().stringWidth(right);
			text(g, truncate(row.name + " x" + row.perTrip, g.getFontMetrics(), WIDTH - 44 - rw), x + 32, ry + 14, c);
			text(g, right, x + WIDTH - 8 - rw, ry + 14, row.isShort() ? RED : tone(row.trips));
			ry += ROW;
		}
		return y + 46 + Math.min(MAX_ROWS, r.rows.size()) * ROW + 6;
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Counts items as supplies ({@link TripSupplies} keys and units) for the boss trip log and the supplies
 * check, and remembers for each key the item that pictures it (the highest dose seen) and its name.
 * Client thread, except {@link #rep} which only reads what was counted.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class SupplyCounter {
	private final Client client;
	private final ItemManager itemManager;

	/** The item that stands for a key: its id, dose (1 for undosed items) and name. */
	static final class Rep {
		final int id;
		final int dose;
		final String name;

		Rep(int id, int dose, String name) {
			this.id = id;
			this.dose = dose;
			this.name = name;
		}
	}

	private final Map<String, Rep> reps = new ConcurrentHashMap<>();

	/** The key of an item (noted and placeholder versions count as the item). */
	String key(int itemId) {
		int id = itemManager.canonicalize(itemId);
		String name = nameOf(id);
		String key = TripSupplies.key(ItemVariationMapping.map(id), name);
		TripSupplies.Dosed d = TripSupplies.dosed(name);
		int dose = d == null ? 1 : d.dose;
		Rep rep = reps.get(key);
		if (rep == null || dose > rep.dose) {
			reps.put(key, new Rep(id, dose, name == null ? "Item " + id : name));
		}
		return key;
	}

	/** Adds a stack to a count. */
	void add(Map<String, Long> counts, int itemId, long quantity) {
		if (itemId <= 0 || quantity <= 0) {
			return;
		}
		String key = key(itemId);
		counts.merge(key, TripSupplies.units(nameOf(itemManager.canonicalize(itemId)), quantity), Long::sum);
	}

	/** Inventory, worn items and the runes in a carried rune pouch. */
	Map<String, Long> carried() {
		Map<String, Long> out = new HashMap<>();
		boolean pouch = false;
		for (int container : new int[]{InventoryID.INV, InventoryID.WORN}) {
			ItemContainer c = client.getItemContainer(container);
			if (c == null) {
				continue;
			}
			for (Item item : c.getItems()) {
				add(out, item.getId(), item.getQuantity());
				pouch |= container == InventoryID.INV && FarmRunManager.RUNE_POUCHES.contains(item.getId());
			}
		}
		if (pouch) {
			for (Map.Entry<Integer, Integer> rune : RunePouchMonitor.read(client).entrySet()) {
				add(out, rune.getKey(), rune.getValue());
			}
		}
		return out;
	}

	/** The open bank's items, or null when it is not open. */
	Map<String, Long> bank() {
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null) {
			return null;
		}
		Map<String, Long> out = new HashMap<>();
		for (Item item : bank.getItems()) {
			add(out, item.getId(), item.getQuantity());
		}
		return out;
	}

	/**
	 * Whether an item gets used up on a trip: stackable (runes, ammo, tablets, seeds), eaten or drunk, or
	 * compost. Gear switches and teleport jewellery are not.
	 */
	boolean consumable(int itemId) {
		ItemComposition comp = itemManager.getItemComposition(itemManager.canonicalize(itemId));
		if (comp == null) {
			return false;
		}
		if (comp.isStackable()) {
			return true;
		}
		String name = comp.getName() == null ? "" : comp.getName().toLowerCase(Locale.ROOT);
		if (name.contains("compost") && !name.contains("bottomless")) {
			return true;
		}
		String[] actions = comp.getInventoryActions();
		if (actions != null) {
			for (String a : actions) {
				if ("Eat".equalsIgnoreCase(a) || "Drink".equalsIgnoreCase(a)) {
					return true;
				}
			}
		}
		return false;
	}

	/** The item standing for a key, or null when it was never counted. */
	Rep rep(String key) {
		return reps.get(key);
	}

	private String nameOf(int itemId) {
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp == null ? null : comp.getName();
	}
}

package com.osrscompanion;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;

/**
 * Shared pre-sync validation checks used by all monitors.
 */
public final class SyncGuard {

	/**
	 * Minimum length a value must reach to be treated as a complete app key.
	 * Keys are currently generated server-side as a 16-character string (see the
	 * backend's UserProfile.generate_runelite_key); this floor stays valid if that
	 * length ever changes, while still rejecting obviously-partial input.
	 */
	public static final int APP_KEY_MIN_LENGTH = 8;

	private SyncGuard() {
	}

	public static boolean hasAppKey(OSRSCompanionConfig config) {
		String key = config.osrsCompanionAppKey();
		return key != null && !key.isBlank();
	}

	/**
	 * Returns true when a ConfigChanged event represents a complete OSRS Companion app key
	 * being entered: the OSRS Companion config group, the app-key item, and a value at least
	 * APP_KEY_MIN_LENGTH characters long. The length floor rejects obviously-partial
	 * input and key clears while tolerating a future change to the key length.
	 */
	public static boolean isCompleteAppKeyEntry(String group, String key, String newValue) {
		if (!OSRSCompanionConfig.CONFIG_GROUP.equals(group) || !OSRSCompanionConfig.APP_KEY.equals(key)) {
			return false;
		}
		return newValue != null && newValue.trim().length() >= APP_KEY_MIN_LENGTH;
	}

	/**
	 * Returns the local player's username, or null if unavailable.
	 */
	/**
	 * True when the game-state transition is a real logout (to the login
	 * screen). Region loads, world hops and connection drops pass through
	 * LOADING / HOPPING / CONNECTION_LOST with the player still known, so they
	 * are not logouts and must not trigger final syncs or session resets.
	 */
	public static boolean isLogout(GameState previous, GameState next) {
		boolean nextIsLogin = next == GameState.LOGIN_SCREEN || next == GameState.LOGIN_SCREEN_AUTHENTICATOR;
		boolean previousWasLogin = previous == GameState.LOGIN_SCREEN || previous == GameState.LOGIN_SCREEN_AUTHENTICATOR;
		return nextIsLogin && !previousWasLogin;
	}

	public static String getPlayerUsername(Client client) {
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) {
			return null;
		}
		String name = localPlayer.getName();
		if (name == null || name.isBlank()) {
			return null;
		}
		return name;
	}
}

package com.osrscompanion;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * The plugin's fixed tables (tables.json next to this class), read once. An id is written [id, "Class.NAME"]
 * (the name of RuneLite's constant, checked by TablesTest); only the number is read.
 */
final class Tables {
	private static final JsonObject ROOT = new JsonParser().parse(new InputStreamReader(
		Tables.class.getResourceAsStream("tables.json"), StandardCharsets.UTF_8)).getAsJsonObject();

	private Tables() {
	}

	/** A table's entries in file order, its "_comment" left out. */
	static Map<String, JsonElement> map(String table) {
		Map<String, JsonElement> out = new LinkedHashMap<>();
		ROOT.getAsJsonObject(table).entrySet().forEach(e -> {
			if (!e.getKey().startsWith("_")) {
				out.put(e.getKey(), e.getValue());
			}
		});
		return out;
	}

	/** A table that is a list (its "values"). */
	static JsonArray list(String table) {
		return ROOT.getAsJsonObject(table).getAsJsonArray("values");
	}

	static int id(JsonElement e) {
		return (e.isJsonArray() ? e.getAsJsonArray().get(0) : e).getAsInt();
	}

	static int[] ids(JsonElement e) {
		JsonArray a = e.getAsJsonArray();
		int[] out = new int[a.size()];
		for (int i = 0; i < out.length; i++) {
			out[i] = id(a.get(i));
		}
		return out;
	}

	static Set<Integer> idSet(String table) {
		Set<Integer> out = new HashSet<>();
		list(table).forEach(e -> out.add(id(e)));
		return out;
	}

	static List<String> strings(JsonElement e) {
		List<String> out = new ArrayList<>();
		e.getAsJsonArray().forEach(s -> out.add(s.getAsString()));
		return out;
	}

	static Set<String> stringSet(String table) {
		return new HashSet<>(strings(list(table)));
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import com.osrscompanion.model.FarmRoute;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Predicate;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.util.Text;

/**
 * "Auto set teleport left click": makes the teleport a guide's way there uses the left click of its
 * item, worn or in the inventory. Capes (Max cape, Construction cape, Farming cape, Ardougne cloak)
 * get the named teleport; any other teleport item (Xeric's talisman, Kharedst's memoirs, jewellery...)
 * the option the travel text names, else its teleport option. Shared by the farm run and the
 * Slayer helper; the caller decides when it applies. Client thread (from PostMenuSort).
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class TeleportLeftClick {
	/** Capes with teleports a route uses: Max capes, Construction capes, Farming capes, Ardougne cloaks. */
	private static final Set<Integer> TELEPORT_CAPES = Tables.idSet("teleportCapes");
	/** "Max cape (Hosidius house portal)": the cape's teleport to a town's house portal. */
	private static final Pattern HOUSE_PORTAL = Pattern.compile("\\(([a-z' ]+) house portal\\)");
	/** Item options that never teleport: not made the left click. */
	private static final Set<String> NOT_TELEPORTS = Tables.stringSet("notTeleports");

	private final Client client;
	/** Item names (lower case), read once on the client thread. */
	private final Map<Integer, String> names = new ConcurrentHashMap<>();
	/** The last menu choice written to the log, so a hovered item is logged once, not every frame. */

	/**
	 * Makes the travel's teleport the left click of the menu about to show. {@code where} names the
	 * guide's step for the log ("farm step 3", "slayer"). Client thread.
	 */
	public void apply(FarmRoute.Travel travel, String where) {
		apply(travel, where, m -> false);
	}

	/**
	 * As {@link #apply(FarmRoute.Travel, String)}, but entries {@code keep} accepts are never made the left
	 * click (the Slayer helper keeps "Wear" on a teleport item the suggested setup wears). Client thread.
	 */
	public void apply(FarmRoute.Travel travel, String where, Predicate<MenuEntry> keep) {
		if (travel == null) {
			return;
		}
		Predicate<MenuEntry> cape = m -> isTeleportCape(m) && !keep.test(m);
		MenuEntry[] entries = client.getMenuEntries();
		if (Arrays.stream(entries).noneMatch(cape)) {
			travelItemLeftClick(entries, travel, where, keep);
			return;
		}
		List<String> wanted = capeOptions(travel);
		int best = capeEntry(entries, wanted, cape);
		MenuEntry fromSub = null;
		if (best < 0) {
			// Not on the cape's own menu (the Max cape in the inventory): its "Teleports" sub menu has it.
			List<String> subWanted = capeSubOptions(travel);
			for (MenuEntry m : entries) {
				if (fromSub != null || subWanted.isEmpty() || !cape.test(m) || m.getSubMenu() == null) {
					continue;
				}
				for (MenuEntry sub : m.getSubMenu().getMenuEntries()) {
					String option = Text.removeTags(sub.getOption()).toLowerCase();
					if (subWanted.stream().anyMatch(option::equals)) {
						fromSub = sub;
						break;
					}
				}
			}
		}
		if (best < 0 && fromSub == null) {
			// Only then a generic option that opens the cape's teleport list (the Farming cape's Teleport).
			best = capeEntry(entries, capeFallbackOptions(travel), cape);
		}
		if (best < 0 && fromSub != null) {
			copyToTop(fromSub);
			return;
		}
		moveToLeftClick(entries, best);
	}

	/**
	 * Any other teleport item the step uses (Kharedst's memoirs, Book of the dead, Xeric's talisman, a
	 * necklace...): its option (or sub menu option) named in the step's travel text becomes the left click,
	 * else its teleport option (Rub, Reminisce, Teleport...).
	 */
	private void travelItemLeftClick(MenuEntry[] entries, FarmRoute.Travel travel, String where, Predicate<MenuEntry> keep) {
		if (travel.getItems().isEmpty()) {
			return;
		}
		Set<String> wantedNames = new HashSet<>();
		Set<Integer> ids = new HashSet<>();
		for (int id : travel.getItems()) {
			ids.add(ItemVariationMapping.map(id));
			String n = nameOf(id);
			if (n != null) {
				wantedNames.add(baseName(n));
			}
		}
		String text = travelText(travel);
		MenuEntry best = null;
		boolean bestFromSub = false;
		int bestScore = 0;
		boolean seen = false;
		for (MenuEntry m : entries) {
			boolean ours = (m.getItemId() > 0 && ids.contains(ItemVariationMapping.map(m.getItemId()))) || wantedNames.contains(baseName(m.getTarget()));
			if (!ours || keep.test(m)) {
				continue;
			}
			List<MenuEntry> options = new ArrayList<>();
			options.add(m);
			if (m.getSubMenu() != null) {
				options.addAll(Arrays.asList(m.getSubMenu().getMenuEntries()));
			}
			for (MenuEntry o : options) {
				String option = Text.removeTags(o.getOption()).toLowerCase().trim();
				seen = true;
				int score = optionScore(option, text);
				if (score > bestScore) {
					best = o;
					bestFromSub = o != m;
					bestScore = score;
				}
			}
		}
		if (!seen) {
			return;
		}
		if (best == null) {
			return;
		}
		if (bestFromSub) {
			copyToTop(best);
			return;
		}
		moveToLeftClick(entries, Arrays.asList(entries).indexOf(best));
	}

	/**
	 * How good an item option is as the teleport: named in the travel text (longest name wins), else a
	 * generic teleport option (Rub, Reminisce, Teleport...); 0 for options that never teleport.
	 */
	static int optionScore(String option, String travelText) {
		if (option.isEmpty() || NOT_TELEPORTS.contains(option)) {
			return 0;
		}
		if (travelText.contains(option)) {
			return 100 + option.length();
		}
		return option.contains("teleport") || option.equals("rub") || option.equals("reminisce") || option.equals("commune")
			|| option.equals("break") || option.equals("operate") ? 10 : 0;
	}

	/** The cape entry whose option contains the best-ranked of {@code wanted}, -1 when none does. */
	private static int capeEntry(MenuEntry[] entries, List<String> wanted, Predicate<MenuEntry> cape) {
		int best = -1;
		int bestRank = Integer.MAX_VALUE;
		for (int i = 0; i < entries.length; i++) {
			if (!cape.test(entries[i])) {
				continue;
			}
			String option = Text.removeTags(entries[i].getOption()).toLowerCase();
			for (int rank = 0; rank < wanted.size() && rank < bestRank; rank++) {
				if (option.contains(wanted.get(rank))) {
					best = i;
					bestRank = rank;
				}
			}
		}
		return best;
	}

	/** The last entry is the left click: moves this one there. */
	private void moveToLeftClick(MenuEntry[] entries, int index) {
		int last = entries.length - 1;
		if (index < 0 || index == last) {
			return;
		}
		MenuEntry pick = entries[index];
		// A low priority (deprioritized) entry on top makes a left click open the menu instead (the
		// Ardougne cloak's teleports are): raise it, as Menu Entry Swapper does.
		if (pick.getType() == MenuAction.CC_OP_LOW_PRIORITY) {
			pick.setType(MenuAction.CC_OP);
		}
		pick.setDeprioritized(false);
		System.arraycopy(entries, index + 1, entries, index, last - index);
		entries[last] = pick;
		client.setMenuEntries(entries);
	}

	/**
	 * A copy of a sub menu entry on top, the left click (added last), as Menu Entry Swapper does for its
	 * sub menu swaps: same action, and a low priority op raised so it isn't sorted below the others.
	 */
	private void copyToTop(MenuEntry from) {
		client.createMenuEntry(-1)
			.setDeprioritized(false)
			.setOption(from.getOption())
			.setTarget(from.getTarget())
			.setIdentifier(from.getIdentifier())
			.setType(from.getType() == MenuAction.CC_OP_LOW_PRIORITY ? MenuAction.CC_OP : from.getType())
			.setItemId(from.getItemId())
			.setParam0(from.getParam0())
			.setParam1(from.getParam1())
			.onClick(from.onClick());
	}

	private static String travelText(FarmRoute.Travel travel) {
		return ((travel.getName() == null ? "" : travel.getName()) + " " + (travel.getHow() == null ? "" : travel.getHow())).toLowerCase();
	}

	/**
	 * The cape options for a way there, best first: Tele to POH, a town's POH Portals, the Farming
	 * Guild, the Ardougne cloak's farm or Monastery teleport. Empty when it isn't a cape teleport.
	 * Only options that teleport straight there: a generic one is {@link #capeFallbackOptions}.
	 */
	static List<String> capeOptions(FarmRoute.Travel travel) {
		if (travel == null) {
			return Collections.emptyList();
		}
		String text = travelText(travel);
		if (text.contains("tele to poh")) {
			return Collections.singletonList("tele to poh");
		}
		if (HOUSE_PORTAL.matcher(text).find()) {
			// Worn: the town is in its "POH Portals" list.
			return Collections.singletonList("poh portals");
		}
		if (text.contains("farming guild") || text.contains("farming cape")) {
			return Collections.singletonList("farming guild");
		}
		if (text.contains("ardougne cloak")) {
			return text.contains("monastery") ? Arrays.asList("kandarin monastery", "monastery")
				: Arrays.asList("ardougne farm", "farm");
		}
		return Collections.emptyList();
	}

	/**
	 * When neither the cape's menu nor a sub menu has the teleport itself: the option that opens its
	 * teleport list or teleports there by default (the Farming cape's "Teleport", the Max cape's "Other
	 * Teleports"). Never before the sub menus, or the inventory Max cape's "Teleports" would win.
	 */
	static List<String> capeFallbackOptions(FarmRoute.Travel travel) {
		String text = travel == null ? "" : travelText(travel);
		return text.contains("farming guild") || text.contains("farming cape")
			? Arrays.asList("other teleports", "teleport") : Collections.emptyList();
	}

	/**
	 * In the inventory the Max cape keeps its teleports in the "Teleports" sub menu: the entry there for
	 * the way there (Home for Tele to POH, a town, Farming Guild). Empty when there is none.
	 */
	static List<String> capeSubOptions(FarmRoute.Travel travel) {
		if (travel == null) {
			return Collections.emptyList();
		}
		String text = travelText(travel);
		if (text.contains("tele to poh")) {
			return Collections.singletonList("home");
		}
		Matcher portal = HOUSE_PORTAL.matcher(text);
		if (portal.find()) {
			return Collections.singletonList(portal.group(1));
		}
		if (text.contains("farming guild")) {
			return Collections.singletonList("farming guild");
		}
		return Collections.emptyList();
	}

	/** Teleport capes by name (the menu's target), as worn and inventory entries don't always carry the item id. */
	private static boolean isTeleportCape(MenuEntry m) {
		if (TELEPORT_CAPES.contains(m.getItemId())) {
			return true;
		}
		String target = Text.removeTags(m.getTarget() == null ? "" : m.getTarget()).toLowerCase();
		return target.contains("max cape") || target.contains("construct. cape") || target.contains("construction cape")
			|| target.contains("farming cape") || target.contains("ardougne cloak");
	}

	/** The item name without its charges or dose, to match "Ring of dueling(5)" with "Ring of dueling(8)". */
	static String baseName(String name) {
		return Text.removeTags(name == null ? "" : name).toLowerCase().replaceAll("\\s*\\(\\d+\\)$", "").trim();
	}

	/** The item's name in lower case. Client thread. */
	private String nameOf(int itemId) {
		String cached = names.get(itemId);
		if (cached != null || !client.isClientThread()) {
			return cached;
		}
		ItemComposition comp = client.getItemDefinition(itemId);
		String name = comp == null || comp.getName() == null ? null : comp.getName().toLowerCase();
		if (name != null) {
			names.put(itemId, name);
		}
		return name;
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;

/**
 * The timers: sends what RuneLite's Time Tracking plugin stored for this account (its {@code timetracking}
 * config: each patch's last seen value and time, the farm tick offset, bird houses, the farming contract) and the
 * clock tab's timers, and the website works out the farming, bird house, contract and clock timers from it
 * (POST /api/runelite/time-tracking). Checked every 45 seconds while logged in and sent when it changed; once
 * after login, and at once after Tears of Guthix.
 */
public class TimerMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "timers-sync";

	private static final int SYNC_INTERVAL_SECONDS = 45;
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	/** Clock timers that loop and the Tears of Guthix reset change with time alone: sent again this often. */
	private static final long RESEND_MS = 10 * 60_000L;

	private final Client client;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private ScheduledFuture<?> scheduledFuture;
	private String lastSent;
	private long lastSentMs;
	/** Tears of Guthix is playable again 7 days after it, from 00:00 UTC; known only this session. */
	private volatile Instant tearsOfGuthixNextReset;
	private GameState previousGameState = GameState.UNKNOWN;

	public TimerMonitor(Client client, OSRSCompanionConfig config, OSRSCompanionApiClient apiClient, ConfigManager configManager,
			ScheduledExecutorService executorService, Gson gson) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void start() {
		if (scheduledFuture == null) {
			scheduledFuture = executorService.scheduleAtFixedRate(this::sync, 10, SYNC_INTERVAL_SECONDS, TimeUnit.SECONDS);
		}
	}

	public void stop() {
		if (scheduledFuture != null) {
			scheduledFuture.cancel(false);
			scheduledFuture = null;
		}
		lastSent = null;
		tearsOfGuthixNextReset = null;
		previousGameState = GameState.UNKNOWN;
	}

	/** Sends again at once, even unchanged (the panel's "Sync &amp; refresh"). */
	public void forceSync() {
		executorService.execute(() -> {
			lastSent = null;
			sync();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
				lastSent = null;
				executorService.schedule(this::sync, LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
			}
			previousGameState = newState;
		});
	}

	/** Entering the Tears of Guthix cave. */
	public void onTearsOfGuthixCompleted() {
		tearsOfGuthixNextReset = Instant.now().atZone(ZoneOffset.UTC).toLocalDate().plusDays(7).atStartOfDay(ZoneOffset.UTC).toInstant();
		lastSent = null;
		executorService.execute(this::sync);
	}

	/** What RuneLite's Time Tracking stored for the account logged in (its RS profile's timetracking keys). */
	static Map<String, String> timeTracking(ConfigManager configManager) {
		Map<String, String> profile = new TreeMap<>();
		String profileKey = configManager.getRSProfileKey();
		if (profileKey != null) {
			for (String key : configManager.getRSProfileConfigurationKeys(TimeTrackingConfig.CONFIG_GROUP, profileKey, "")) {
				String value = configManager.getConfiguration(TimeTrackingConfig.CONFIG_GROUP, profileKey, key);
				if (value != null) {
					profile.put(key, value);
				}
			}
		}
		return profile;
	}

	private void sync() {
		String player = SyncGuard.getPlayerUsername(client);
		String profileKey = configManager.getRSProfileKey();
		if (!SyncGuard.hasAppKey(config) || !config.syncTimeTracking() || client.getGameState() != GameState.LOGGED_IN
				|| GameModeUtil.isSpecialGameMode(client) || player == null || profileKey == null) {
			return;
		}
		Map<String, String> profile = timeTracking(configManager);
		Instant tog = tearsOfGuthixNextReset;
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player_username", player);
		body.put("profile", profile);
		body.put("clock", configManager.getConfiguration(TimeTrackingConfig.CONFIG_GROUP, TimeTrackingConfig.TIMERS));
		body.put("tog_reset", tog == null ? null : tog.getEpochSecond());
		String json = gson.toJson(body);
		long now = System.currentTimeMillis();
		boolean timed = body.get("clock") != null || tog != null;
		if (json.equals(lastSent) && !(timed && now - lastSentMs >= RESEND_MS)) {
			return;
		}
		lastSent = json;
		lastSentMs = now;
		apiClient.sendTimeTracking(json, player);
	}
}

package com.osrscompanion;

import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * What the tool leprechaun is storing, from the farming-tools varbits (readable
 * anywhere while logged in). Tools count 1 when stored; compost counts are the
 * stored amount as far as the varbits tell (the "extra" varbits only add more).
 */
final class ToolLeprechaun {
	private ToolLeprechaun() {
	}

	/** Item id to quantity stored. Client thread. */
	static Map<Integer, Integer> read(Client client) {
		Map<Integer, Integer> out = new HashMap<>();
		put(out, ItemID.RAKE, client.getVarbitValue(VarbitID.FARMING_TOOLS_RAKE) + client.getVarbitValue(VarbitID.FARMING_TOOLS_EXTRARAKES));
		put(out, ItemID.DIBBER, client.getVarbitValue(VarbitID.FARMING_TOOLS_DIBBER) + client.getVarbitValue(VarbitID.FARMING_TOOLS_EXTRADIBBERS));
		put(out, ItemID.SPADE, client.getVarbitValue(VarbitID.FARMING_TOOLS_SPADE) + client.getVarbitValue(VarbitID.FARMING_TOOLS_EXTRASPADES));
		put(out, ItemID.GARDENING_TROWEL, client.getVarbitValue(VarbitID.FARMING_TOOLS_TROWEL) + client.getVarbitValue(VarbitID.FARMING_TOOLS_EXTRATROWELS));
		int secateurs = client.getVarbitValue(VarbitID.FARMING_TOOLS_SECATEURS) + client.getVarbitValue(VarbitID.FARMING_TOOLS_EXTRASECATEURS);
		// The stored secateurs are the magic ones when this flag is set.
		put(out, client.getVarbitValue(VarbitID.FARMING_TOOLS_FAIRYSECATEURS) > 0 ? ItemID.FAIRY_ENCHANTED_SECATEURS : ItemID.SECATEURS, secateurs);
		put(out, ItemID.BUCKET_COMPOST, client.getVarbitValue(VarbitID.FARMING_TOOLS_COMPOST) + client.getVarbitValue(VarbitID.FARMING_TOOLS_EXTRACOMPOST));
		put(out, ItemID.BUCKET_SUPERCOMPOST, client.getVarbitValue(VarbitID.FARMING_TOOLS_SUPERCOMPOST) + client.getVarbitValue(VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST));
		put(out, ItemID.BUCKET_ULTRACOMPOST, client.getVarbitValue(VarbitID.FARMING_TOOLS_ULTRACOMPOST));
		put(out, ItemID.PLANT_CURE, client.getVarbitValue(VarbitID.FARMING_TOOLS_PLANTCURE));
		if (client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE) > 0) {
			// Either bucket id (empty or filled) counts as the stored bucket.
			out.put(ItemID.BOTTOMLESS_COMPOST_BUCKET, 1);
			out.put(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, 1);
		}
		return out;
	}

	private static void put(Map<Integer, Integer> out, int itemId, int qty) {
		if (qty > 0) {
			out.put(itemId, qty);
		}
	}
}

package com.osrscompanion;

import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The maths behind the boss trip log and the supplies check, free of the game client so it is unit
 * tested. Supplies are counted in units per key: an item whose name ends in a dose ("Prayer
 * potion(3)") counts its doses under the name without the dose, so a (4) and a (3) add up to 7
 * doses; any other item counts one per item under its base id (its variants together).
 */
final class TripSupplies {
	private static final Pattern DOSED = Pattern.compile("^(.+?)\\s?\\((\\d)\\)$");

	/** Kill count messages name some bosses differently from the Boss Gear page: both map to one key. */
	private static final Map<String, String> BOSS_ALIASES = new HashMap<>();
	/** Raids and their modes ("Theatre of Blood: Hard Mode") count as the raid. */
	private static final String[] PREFIX_BOSSES = {"chambersofxeric", "theatreofblood", "tombsofamascut"};

	static {
		Tables.map("tripBossAliases").forEach((boss, as) -> BOSS_ALIASES.put(boss, as.getAsString()));
	}

	private TripSupplies() {
	}

	/** A name with a dose: the name without it (lower case) and the dose. */
	static final class Dosed {
		final String stem;
		final int dose;

		Dosed(String stem, int dose) {
			this.stem = stem;
			this.dose = dose;
		}
	}

	/** "Prayer potion(3)" gives prayer potion, 3; null for a name without a dose (or a dose of 0). */
	static Dosed dosed(String name) {
		if (name == null) {
			return null;
		}
		Matcher m = DOSED.matcher(name.trim());
		if (!m.matches()) {
			return null;
		}
		int dose = m.group(2).charAt(0) - '0';
		return dose <= 0 ? null : new Dosed(m.group(1).trim().toLowerCase(Locale.ROOT), dose);
	}

	/** The supply key of an item: its dose-less name for dosed items, else its base id. */
	static String key(int baseId, String name) {
		Dosed d = dosed(name);
		return d != null ? "d:" + d.stem : "i:" + baseId;
	}

	/** How many units a stack is: doses for dosed items, else the quantity. */
	static long units(String name, long quantity) {
		Dosed d = dosed(name);
		return d == null ? quantity : quantity * d.dose;
	}

	/**
	 * Adds what went down between two counts to {@code used}. Only keys in {@code brought} count (what
	 * you left the bank with): loot picked up and dropped or bagged again is not a supply. Increases
	 * (loot, empty vials, a switch taken off) are ignored.
	 */
	static void addUsed(Map<String, Long> before, Map<String, Long> after, Set<String> brought, Map<String, Long> used) {
		for (Map.Entry<String, Long> e : before.entrySet()) {
			if (!brought.contains(e.getKey())) {
				continue;
			}
			long down = e.getValue() - after.getOrDefault(e.getKey(), 0L);
			if (down > 0) {
				used.merge(e.getKey(), down, Long::sum);
			}
		}
	}

	/** Units used per trip on average over the given trips (every trip counts, also those where a key was not used). */
	static Map<String, Double> averagePerTrip(Collection<Map<String, Long>> trips) {
		Map<String, Double> out = new LinkedHashMap<>();
		if (trips.isEmpty()) {
			return out;
		}
		for (Map<String, Long> trip : trips) {
			for (Map.Entry<String, Long> e : trip.entrySet()) {
				out.merge(e.getKey(), e.getValue().doubleValue(), Double::sum);
			}
		}
		out.replaceAll((k, v) -> v / trips.size());
		out.values().removeIf(v -> v <= 0);
		return out;
	}

	/** One needed supply: how many units a trip takes, how many you have and how many trips that is. */
	static final class Need {
		final String key;
		final double perTrip;
		final long have;
		final int trips;

		Need(String key, double perTrip, long have) {
			this.key = key;
			this.perTrip = perTrip;
			this.have = have;
			this.trips = perTrip <= 0 ? Integer.MAX_VALUE : (int) Math.min(Integer.MAX_VALUE, Math.floor(have / perTrip + 1e-9));
		}
	}

	/** How many trips your supplies last: the fewest any needed supply allows, and that supply (the first of it). */
	static final class Check {
		final int trips;
		final List<Need> needs;

		Check(int trips, List<Need> needs) {
			this.trips = trips;
			this.needs = needs;
		}

		/** The supply that runs out first, or null when nothing is needed. */
		Need limiting() {
			return needs.isEmpty() ? null : needs.get(0);
		}
	}

	/** How many trips {@code have} supports with {@code perTrip} needed each trip; the needs come fewest trips first. */
	static Check tripsSupported(Map<String, Double> perTrip, Map<String, Long> have) {
		List<Need> needs = new ArrayList<>();
		for (Map.Entry<String, Double> e : perTrip.entrySet()) {
			if (e.getValue() != null && e.getValue() > 0) {
				needs.add(new Need(e.getKey(), e.getValue(), have.getOrDefault(e.getKey(), 0L)));
			}
		}
		needs.sort(Comparator.comparingInt((Need n) -> n.trips).thenComparing(n -> n.key));
		return new Check(needs.isEmpty() ? 0 : needs.get(0).trips, needs);
	}

	/** A boss name as one comparable key: lower case letters and digits, no leading "the", aliases applied. */
	static String bossKey(String name) {
		if (name == null) {
			return "";
		}
		String n = name.toLowerCase(Locale.ROOT).trim();
		if (n.startsWith("the ")) {
			n = n.substring(4);
		}
		n = n.replaceAll("[^a-z0-9]", "");
		for (String raid : PREFIX_BOSSES) {
			if (n.startsWith(raid)) {
				return raid;
			}
		}
		return BOSS_ALIASES.getOrDefault(n, n);
	}
}

package com.osrscompanion;

import lombok.RequiredArgsConstructor;
import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * The data pump: sends the raw game values the website asks for (GET /api/runelite/vars, once per login: per
 * source, its varbits, varplayers, quests and regions), and the website works out what they mean: the
 * achievement diaries, combat achievements, Managing Miscellania, the house location, the farming unlocks and the
 * dailies. Only the sources whose sync is on are sent. Read and sent like the diary sync: never during the
 * post-login replay ({@link DiarySyncTrigger}), a few ticks after a watched value changes, on walking into a
 * watched region (a visit), after 00:00 UTC (the dailies), and once at logout.
 */
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Singleton
public class VarPump {
	static final String GUARD_FEATURE = "var-pump";
	private static final long DAY_MS = 86_400_000L;

	/** What one source needs, as GET /api/runelite/vars answers it. */
	static final class Source {
		int[] varbits = new int[0];
		int[] varps = new int[0];
		String[] quests = new String[0];
		int[] regions = new int[0];
	}

	static final class WatchList {
		Map<String, Source> sources = Collections.emptyMap();
	}

	private final Client client;
	private final ClientThread clientThread;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final Gson gson;
	private final DiarySyncTrigger trigger = new DiarySyncTrigger();

	private volatile WatchList watchList;
	private volatile Set<Integer> varbits;
	private volatile Set<Integer> varps;
	private volatile Set<Integer> regions;
	private volatile boolean fetching;
	private GameState previousGameState = GameState.UNKNOWN;
	private boolean wasInRegion;
	/** When this login (or world hop) began; 0 logged out. */
	private long sessionStart;
	private long sentDay = -1;
	private String lastSentJson;

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState state = event.getGameState();
			if (previousGameState == GameState.LOGGED_IN && state != GameState.LOGGED_IN && trigger.leaveAndShouldFlush()) {
				// Logging out: the values are still this player's fully loaded ones.
				send();
			}
			if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING) {
				// A new session: the claimed flags are today's again, and the next login sends once even unchanged.
				sessionStart = 0;
				lastSentJson = null;
				wasInRegion = false;
			}
			if (state == GameState.LOGIN_SCREEN) {
				// The next login asks for the watch list again (the website may watch more by then).
				setWatchList(null);
			}
			previousGameState = state;
		});
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			Set<Integer> bits = varbits;
			if (bits == null || bits.contains(event.getVarbitId()) || varps.contains(event.getVarpId())) {
				trigger.varbitChanged();
			}
		});
	}

	@Subscribe
	public void onGameTick(GameTick tick) {
		Guard.run(GUARD_FEATURE, () -> {
			boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
			if (loggedIn) {
				if (sessionStart == 0) {
					sessionStart = System.currentTimeMillis();
				}
				Set<Integer> watched = regions;
				Integer region = region();
				boolean inRegion = watched != null && region != null && watched.contains(region);
				if (inRegion && !wasInRegion || sentDay >= 0 && sentDay != today()) {
					trigger.varbitChanged();
				}
				wasInRegion = inRegion;
			}
			if (trigger.tick(client.getTickCount(), loggedIn) == DiarySyncTrigger.Decision.SYNC) {
				send();
			}
		});
	}

	/** Sends again (the panel's "Sync & refresh", an App Key entered), once the session has settled. */
	public void forceSync() {
		Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
			if (client.getGameState() == GameState.LOGGED_IN && trigger.isBaselineSynced()) {
				lastSentJson = null;
				send();
			}
		});
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		trigger.reset();
		lastSentJson = null;
		sessionStart = 0;
		sentDay = -1;
		wasInRegion = false;
		setWatchList(null);
	}

	private static long today() {
		return Math.floorDiv(System.currentTimeMillis(), DAY_MS);
	}

	private Integer region() {
		Player me = client.getLocalPlayer();
		return me == null || me.getWorldLocation() == null ? null : me.getWorldLocation().getRegionID();
	}

	/** Whether the sync this source belongs to is on. */
	boolean enabled(String source) {
		switch (source) {
			case "achievement_diaries":
				return config.syncAchievementDiaries();
			case "combat_achievements":
				return config.syncCombatAchievements();
			case "kingdom":
				return config.syncKingdom();
			case "house_location":
				return config.syncHouseLocation();
			case "farming_unlocks":
				return config.syncTimeTracking();
			case "dailies":
				return config.syncDailies();
			default:
				return false;
		}
	}

	/** Reads the enabled sources' values and sends them (deduped per day); asks for the watch list first. Client thread. */
	private void send() {
		if (!SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null) {
			return;
		}
		WatchList list = watchList;
		if (list == null) {
			fetchWatchList(player);
			return;
		}
		List<String> sources = new ArrayList<>();
		Map<Integer, Integer> bitValues = new TreeMap<>();
		Map<Integer, Integer> playerValues = new TreeMap<>();
		Map<String, String> questStates = new TreeMap<>();
		for (Map.Entry<String, Source> e : list.sources.entrySet()) {
			if (!enabled(e.getKey())) {
				continue;
			}
			sources.add(e.getKey());
			Source s = e.getValue();
			for (int id : s.varbits) {
				bitValues.put(id, client.getVarbitValue(id));
			}
			for (int id : s.varps) {
				playerValues.put(id, client.getVarpValue(id));
			}
			for (String quest : s.quests) {
				try {
					questStates.put(quest, Quest.valueOf(quest).getState(client).name());
				} catch (IllegalArgumentException unknownToThisRuneLite) {
					// The website leaves a source alone without all its values.
				}
			}
		}
		if (sources.isEmpty()) {
			return;
		}
		String json = json(player, sources, bitValues, playerValues, questStates, region(), sessionStart);
		long day = today();
		// The same values on a new day still go out: the dailies read them differently after 00:00 UTC.
		if (json.equals(lastSentJson) && day == sentDay) {
			return;
		}
		lastSentJson = json;
		sentDay = day;
		apiClient.sendVars(json, player);
	}

	String json(String player, List<String> sources, Map<Integer, Integer> bitValues, Map<Integer, Integer> playerValues,
		Map<String, String> quests, Integer region, long sessionStart) {
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player_username", player);
		// Plain copies: RuneLite's Gson cannot write the JDK's own empty / immutable collections on Java 17+.
		body.put("sources", new ArrayList<>(sources));
		body.put("varbits", new LinkedHashMap<>(bitValues));
		body.put("varps", new LinkedHashMap<>(playerValues));
		body.put("quests", new LinkedHashMap<>(quests));
		body.put("region", region);
		body.put("session_start", sessionStart > 0 ? sessionStart : null);
		return gson.toJson(body);
	}

	void setWatchList(WatchList list) {
		Set<Integer> bits = null;
		Set<Integer> players = null;
		Set<Integer> places = null;
		if (list != null) {
			bits = new HashSet<>();
			players = new HashSet<>();
			places = new HashSet<>();
			for (Source s : list.sources.values()) {
				for (int id : s.varbits) {
					bits.add(id);
				}
				for (int id : s.varps) {
					players.add(id);
				}
				for (int id : s.regions) {
					places.add(id);
				}
			}
		}
		varps = players;
		regions = places;
		varbits = bits;
		watchList = list;
	}

	private void fetchWatchList(String player) {
		if (fetching) {
			return;
		}
		fetching = true;
		apiClient.getVarWatchList(player, WatchList.class, new OSRSCompanionApiClient.RoadmapCallback<WatchList>() {
			@Override
			public void onSuccess(WatchList result) {
				setWatchList(result);
				fetching = false;
				// Sent on the client thread as soon as the list is in.
				Guard.invokeLater(clientThread, GUARD_FEATURE, () -> {
					if (client.getGameState() == GameState.LOGGED_IN && trigger.isBaselineSynced()) {
						send();
					}
				});
			}

			@Override
			public void onError(String message) {
				fetching = false;
			}
		});
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.api.OSRSCompanionApiClient;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Monitors vault and storage containers the client exposes as real item
 * containers (Seed Vault, Looting Bag, Sailing cargo holds, seed box, ...)
 * and syncs their contents to the OSRS Companion API using the bank sync endpoint
 * with a per-source key. Every read is also handed to the goal tracker so
 * owned-item goals do not count a deposit as a loss.
 */
@Singleton
public class VaultMonitor {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "vault-sync";

	/** Container id to bank-sync source. Each container is its own source:
	 * the backend replaces a whole source per upload and the plugin can only
	 * snapshot a container it has seen, so two containers must not share one. */
	private static final Map<Integer, String> VAULT_SOURCES = new HashMap<>();

	static {
		Tables.map("vaultSources").forEach((source, id) -> VAULT_SOURCES.put(Tables.id(id), source));
	}

	/** Set on container ids the client reports for interface-owned inventories (a boat's hold arrives as 965 | 0x8000). */
	static final int REMOTE_CONTAINER_FLAG = 0x8000;

	/** The bank-sync source for a container id, or null when not tracked. */
	static String sourceFor(int containerId) {
		String source = VAULT_SOURCES.get(containerId);
		if (source == null && (containerId & REMOTE_CONTAINER_FLAG) != 0) {
			source = VAULT_SOURCES.get(containerId & ~REMOTE_CONTAINER_FLAG);
		}
		return source;
	}

	/** Crew member option that banks the current boat's hold without any container event reaching the client. */
	static final String BANK_CARGO_OPTION = "Bank-cargo";

	private final Client client;
	private final ItemManager itemManager;
	private final SourceSyncer syncer;
	private GameState previousGameState = GameState.UNKNOWN;
	/** Contents last read this session, per source. */
	private final Map<String, Map<Integer, Integer>> lastRead = new HashMap<>();
	/** Receives the hold's contents when a crew member banks them; set by the plugin. */
	private volatile Consumer<Map<Integer, Integer>> cargoBankedListener;

	public void setCargoBankedListener(Consumer<Map<Integer, Integer>> listener) {
		this.cargoBankedListener = listener;
	}

	/** Receives every container read (source, canonical item id to quantity),
	 * before any sync gate, so goal progress moves even with sync disabled. */

	@Inject
	public VaultMonitor(
			Client client,
			OSRSCompanionConfig config,
			OSRSCompanionApiClient apiClient,
			ItemManager itemManager,
			Gson gson,
			ScheduledExecutorService executor) {
		executor = GuardedExecutor.wrap(GUARD_FEATURE, executor);
		this.client = client;
		this.itemManager = itemManager;
		this.syncer = new SourceSyncer("vaults", gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
		this.syncer.setPriorityFlush(apiClient::requestOutboxFlush);
	}

	public void stop() {
		syncer.stop();
		lastRead.clear();
	}

	/** The source of the current boat's hold, from the Sailing varp holding its inventory id, or null. */
	static String currentHoldSource(int holdInventoryId) {
		String source = sourceFor(holdInventoryId);
		return source != null && source.startsWith("boat_cargo_hold_") ? source : null;
	}

	/**
	 * "Bank-cargo" on a crew member moves the hold into the bank with no
	 * container event, so the bank would count the items again on its next
	 * read while the hold snapshot still held them. Hand the hold's contents
	 * to the bank-deposits overlay (cleared when the bank is read) and empty
	 * the hold locally and on the server.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		Guard.run(GUARD_FEATURE, () -> {
			if (!BANK_CARGO_OPTION.equalsIgnoreCase(event.getMenuOption())) {
				return;
			}
			String current = currentHoldSource(client.getVarpValue(VarPlayerID.SAILING_BOAT_CARGOHOLD_INV));
			Map<Integer, Integer> banked = new LinkedHashMap<>();
			Map<String, Map<Integer, Integer>> emptied = new LinkedHashMap<>();
			for (Map.Entry<String, Map<Integer, Integer>> e : lastRead.entrySet()) {
				boolean hold = e.getKey().startsWith("boat_cargo_hold_");
				if (!hold || e.getValue().isEmpty() || (current != null && !current.equals(e.getKey()))) {
					continue;
				}
				e.getValue().forEach((id, qty) -> banked.merge(id, qty, Integer::sum));
				emptied.put(e.getKey(), new LinkedHashMap<>());
			}
			if (emptied.isEmpty()) {
				return;
			}
			for (String source : emptied.keySet()) {
				lastRead.put(source, new LinkedHashMap<>());
			}
			Consumer<Map<Integer, Integer>> bankedListener = cargoBankedListener;
			if (bankedListener != null) {
				bankedListener.accept(banked);
			}
			syncer.submitSources(emptied, true);
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			GameState newState = event.getGameState();
			if (SyncGuard.isLogout(previousGameState, newState)) {
				syncer.flushPending();
			}
			previousGameState = newState;
		});
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		Guard.run(GUARD_FEATURE, () -> {
			String source = sourceFor(event.getContainerId());
			if (source == null) {
				return;
			}
			ItemContainer container = client.getItemContainer(event.getContainerId());
			if (container == null) {
				return;
			}

			Map<Integer, Integer> itemQuantities = new LinkedHashMap<>();
			ItemCollector.collectItems(container, itemManager, itemQuantities);
			lastRead.put(source, new LinkedHashMap<>(itemQuantities));

			Map<String, Map<Integer, Integer>> bySource = new LinkedHashMap<>();
			bySource.put(source, itemQuantities);
			syncer.submitSources(bySource, false);
		});
	}
}

package com.osrscompanion;

import com.osrscompanion.api.OSRSCompanionApiClient;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;

/**
 * Notices changes made on the website (roadmaps, farm routes, gear setups, slayer picks, settings...)
 * without each feature polling: the website bumps a webVersion per character, every batch upload
 * answers with it, and every {@link #CHECK_SECONDS} a tiny {@code GET /api/runelite/version} asks
 * for it when no batch answered lately. A different value than the last one seen re-reads
 * everything that shows website data; the features' own periodic re-reads are only a backstop.
 *
 * <p>It is also the live activity heartbeat: while the status is shared ({@link LiveActivityMonitor}),
 * every batch carries it, and when no batch answered for {@link LiveActivityMonitor#HEARTBEAT_MS} the
 * status goes out on its own (a batch, whose answer carries the webVersion too, so no version check is
 * needed then). Idle, that is the heartbeat every 5 minutes with the version check every 30 s in between, so
 * website changes still reach the plugin within about 30 s.
 */
@Singleton
public class WebVersionWatcher {
	/** This class's feature for {@link Guard} (breaker, reports, the chat message). */
	static final String GUARD_FEATURE = "web-updates";

	static final int CHECK_SECONDS = 30;
	/** How often the (network-free) decision runs; the heartbeat then goes out 15 to 16 s after the last contact. */
	static final int TICK_SECONDS = 1;
	/** A batch response this recent already carried the webVersion. */
	static final long RECENT_BATCH_MS = TimeUnit.SECONDS.toMillis(CHECK_SECONDS);

	private final Client client;
	private final OSRSCompanionConfig config;
	private final OSRSCompanionApiClient apiClient;
	private final ScheduledExecutorService executor;
	private final RoadmapManager roadmapManager;
	private final FarmRunManager farmRunManager;
	private final SlayerHelperManager slayerHelperManager;
	private final BossGearManager bossGearManager;
	private final LiveActivityMonitor liveActivity;

	private ScheduledFuture<?> task;
	private volatile long lastVersionCheckMs = Long.MIN_VALUE;
	private volatile long lastHeartbeatMs = Long.MIN_VALUE;

	@Inject
	public WebVersionWatcher(Client client, OSRSCompanionConfig config, OSRSCompanionApiClient apiClient,
			ScheduledExecutorService executor, RoadmapManager roadmapManager, FarmRunManager farmRunManager,
			SlayerHelperManager slayerHelperManager, BossGearManager bossGearManager,
			LiveActivityMonitor liveActivity) {
		executor = GuardedExecutor.wrap(GUARD_FEATURE, executor);
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.executor = executor;
		this.roadmapManager = roadmapManager;
		this.farmRunManager = farmRunManager;
		this.slayerHelperManager = slayerHelperManager;
		this.bossGearManager = bossGearManager;
		this.liveActivity = liveActivity;
	}

	public synchronized void start() {
		apiClient.setWebVersionChangedListener(() -> executor.execute(this::refreshAll));
		if (task == null) {
			task = executor.scheduleWithFixedDelay(this::check, TICK_SECONDS, TICK_SECONDS, TimeUnit.SECONDS);
		}
	}

	public synchronized void stop() {
		if (task != null) {
			task.cancel(false);
			task = null;
		}
		apiClient.setWebVersionChangedListener(null);
		apiClient.resetWebVersion();
		lastVersionCheckMs = Long.MIN_VALUE;
		lastHeartbeatMs = Long.MIN_VALUE;
	}

	/** Logged out: the next login's first webVersion is a new baseline (the login loads everything anyway). */
	public void onLoggedOut() {
		apiClient.resetWebVersion();
		lastHeartbeatMs = Long.MIN_VALUE;
	}

	/** Whether the live activity heartbeat is due: nothing reached the website (batch or heartbeat) for HEARTBEAT_MS. */
	static boolean shouldHeartbeat(long nowMs, long lastBatchResponseMs, long lastHeartbeatMs) {
		long last = Math.max(lastBatchResponseMs, lastHeartbeatMs);
		return last == Long.MIN_VALUE || nowMs - last >= LiveActivityMonitor.HEARTBEAT_MS;
	}

	/** Whether the version GET is worth sending now. */
	static boolean shouldCheck(boolean loggedIn, boolean hasAppKey, String player, long nowMs, long lastBatchResponseMs) {
		if (!loggedIn || !hasAppKey || player == null) {
			return false;
		}
		return lastBatchResponseMs == Long.MIN_VALUE || nowMs - lastBatchResponseMs >= RECENT_BATCH_MS;
	}

	private void check() {
		try {
			long now = System.currentTimeMillis();
			long lastBatch = apiClient.getLastBatchResponseMs();
			if (liveActivity.isSharing() && shouldHeartbeat(now, lastBatch, lastHeartbeatMs)) {
				// The heartbeat's batch answers with the webVersion: it is the version check too.
				lastHeartbeatMs = now;
				liveActivity.heartbeat();
				return;
			}
			// Between heartbeats (and when the status isn't shared): the version check, so website changes
			// still arrive within CHECK_SECONDS.
			String player = SyncGuard.getPlayerUsername(client);
			if (!shouldCheck(client.getGameState() == GameState.LOGGED_IN, SyncGuard.hasAppKey(config), player,
					now, Math.max(Math.max(lastBatch, lastVersionCheckMs), lastHeartbeatMs))) {
				return;
			}
			lastVersionCheckMs = now;
			apiClient.getWebVersion(player, new OSRSCompanionApiClient.RoadmapCallback<Integer>() {
				@Override
				public void onSuccess(Integer result) {
					// observeWebVersion (in the client) already told the listener about a change.
				}

				@Override
				public void onError(String message) {
				}
			});
		} catch (RuntimeException e) {
		}
	}

	/** Re-reads everything that shows website data (each feature only if it is in use). */
	void refreshAll() {
		if (client.getGameState() != GameState.LOGGED_IN || !SyncGuard.hasAppKey(config)) {
			return;
		}
		run("roadmaps", roadmapManager::refreshAllFresh);
		run("farm route", farmRunManager::refresh);
		if (slayerHelperManager.getGuide() != null) {
			run("slayer guide", slayerHelperManager::refresh);
		}
		if (bossGearManager.isLoaded() || bossGearManager.isOpen()) {
			run("boss gear", bossGearManager::refresh);
		}
	}

	private static void run(String what, Runnable refresh) {
		try {
			refresh.run();
		} catch (RuntimeException e) {
		}
	}
}

