		postForResult(BOSS_GEAR_ENDPOINT + "sets/" + setId + "/activate/", gson.toJson(body), "boss-gear-activate",
			BossGear.Response.class, callback);
	}

	/** The data pump's watch list: per data type, the values the website wants ({@link com.osrscompanion.VarPump}). */
	public <T> void getVarWatchList(String playerUsername, Class<T> type, RoadmapCallback<T> callback)
	{
		getAsync(VARS_ENDPOINT + "?player=" + urlEncode(playerUsername), "vars", type, callback);
	}

	/** The game events the website works the boss trips and history out from ({@link com.osrscompanion.GameEvents}); in order, never merged. */
	public void sendEvents(String json, boolean priority)
	{
		postAsync(EVENTS_ENDPOINT, json, "events", false, false, null, priority, null);
	}

	/** The data pump's raw values (merged per player: only the newest set matters). */
	public void sendVars(String json, String playerUsername)
	{
		postAsync(VARS_ENDPOINT, json, "vars", false, true, key("vars", playerUsername), false,
			null);
	}


	private <T> void getAsync(String endpoint, String label, Class<T> type, RoadmapCallback<T> callback)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			callback.onError("No OSRS Companion App Key configured");
			return;
		}

		Request request = new Request.Builder()
			.url(BASE_URL + endpoint)
			.header("X-RuneLite-Key", config.osrsCompanionAppKey().trim())
			.get()
			.build();

		okHttpClient.newCall(request).enqueue(parsingCallback(endpoint, label, type, callback));
	}

	private <T> void postForResult(String endpoint, String json, String label, Class<T> type,
		RoadmapCallback<T> callback)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			callback.onError("No OSRS Companion App Key configured");
			return;
		}

		Request request = new Request.Builder()
			.url(BASE_URL + endpoint)
			.header("Content-Type", "application/json")
			.header("X-RuneLite-Key", config.osrsCompanionAppKey().trim())
			.post(RequestBody.create(JSON_MEDIA_TYPE, json))
			.build();

		largeRequestClient.newCall(request).enqueue(parsingCallback(endpoint, label, type, callback));
	}

	/** The {@link Guard} feature of a website answer's callback, by what was asked ("roadmap", "slayer guide"...). */
	static String feature(String label)
	{
		return "api-" + (label == null ? "request" : label.toLowerCase().replaceAll("[^a-z0-9]+", "-"));
	}

	private <T> Callback parsingCallback(String endpoint, String label, Class<T> type, RoadmapCallback<T> callback)
	{
		return new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed {} request to OSRS Companion API: {}", label, e.getMessage());
				// The callback is a feature's code, on OkHttp's thread: guarded like the rest.
				Guard.run(feature(label), () -> callback.onError("Network error"));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Guard.run(feature(label), () -> handle(response));
			}

			private void handle(Response response)
			{
				try
				{
					if (response.code() < HTTP_OK_MIN || response.code() >= HTTP_OK_MAX)
					{
						log.warn("OSRS Companion API returned {} for {}", response.code(), label);
						callback.onError("Server returned " + response.code());
						return;
					}
					String responseBody = response.body() != null ? response.body().string() : "";
					T parsed = gson.fromJson(responseBody, type);
					if (parsed == null)
					{
						callback.onError("Empty response");
						return;
					}
					callback.onSuccess(parsed);
				}
				catch (JsonSyntaxException e)
				{
					log.warn("Failed to parse {} response: {}", label, e.getMessage());
					callback.onError("Could not read response");
				}
				catch (IOException e)
				{
					log.warn("Failed to read {} response: {}", label, e.getMessage());
					callback.onError("Could not read response");
				}
				finally
				{
					response.close();
				}
			}
		};
	}

	private static String urlEncode(String value)
	{
		if (value == null)
		{
			return "";
		}
		try
		{
			return URLEncoder.encode(value, StandardCharsets.UTF_8.name());
		}
		catch (UnsupportedEncodingException e)
		{
			return value;
		}
	}

	/** Coalescing key of a full-state upload for one player. */
	private static String key(String syncType, String player)
	{
		return syncType + "|" + player;
	}

	/**
	 * A fire-and-forget upload. With the outbox running (see {@link #startOutbox}) it is queued and
	 * sent batched; before that (or in tests) it goes out on its own straight away, as it always did.
	 *
	 * @param coalesceKey non-null for a full-state upload a newer copy may replace while queued
	 * @param priority    send with the next flush at once (drops, finished tasks)
	 */
	private void postAsync(String endpoint, String json, String syncType, boolean largeRequest,
		boolean dedupe, String coalesceKey, boolean priority, Runnable onSuccess)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			return;
		}

		SyncOutbox box = outbox;
		// An identical body is skipped only when no other upload of this type is still on its way:
		// otherwise going back to what the server had must still replace the newer queued one.
		if (dedupe && isDuplicate(lastSentBodyByType.get(syncType), json) && (box == null || !box.hasPending(syncType)))
		{
			return;
		}

		Runnable success = () -> {
			if (dedupe)
			{
				lastSentBodyByType.put(syncType, json);
			}
			if (onSuccess != null)
			{
				onSuccess.run();
			}
		};
		String baseUrl = BASE_URL;
		String appKey = config.osrsCompanionAppKey().trim();
		SyncOutbox.Item item = new SyncOutbox.Item(baseUrl, appKey, endpoint, "POST", json, syncType,
			coalesceKey, priority, largeRequest, success);
		if (box != null)
		{
			box.enqueue(item);
			return;
		}
		sendOne(item, new SyncOutbox.SingleCallback()
		{
			@Override
			public void onResponse(int httpStatus)
			{
				if (httpStatus >= HTTP_OK_MIN && httpStatus < HTTP_OK_MAX)
				{
					success.run();
				}
				else
				{
					log.warn("OSRS Companion API returned {} for {} sync", httpStatus, syncType);
				}
			}

			@Override
			public void onNetworkFailure(String message)
			{
				log.warn("Failed to send {} sync to OSRS Companion API: {}", syncType, message);
			}
		});
	}

	// ------------------------------------------------------------------ outbox

	/**
	 * Starts queueing uploads in the outbox (batched, retried) on {@code executor}. Safe to call
	 * again after {@link #stopOutbox()}.
	 */
	public synchronized void startOutbox(ScheduledExecutorService executor)
	{
		if (outbox == null)
		{
			SyncOutbox box = new SyncOutbox(new SyncOutbox.Sender()
			{
				@Override
				public void sendBatch(String baseUrl, String appKey, List<SyncOutbox.Item> items, SyncOutbox.BatchCallback callback)
				{
					OSRSCompanionApiClient.this.sendBatch(baseUrl, appKey, items, callback);
				}

				@Override
				public void sendOne(SyncOutbox.Item item, SyncOutbox.SingleCallback callback)
				{
					OSRSCompanionApiClient.this.sendOne(item, callback);
				}
			}, executor, System::currentTimeMillis);
			box.setWebVersionListener(this::observeWebVersion);
			box.setBatchExtra(this::activityExtra);
			outbox = box;
		}
		outbox.start();
	}

	/** Sends what is queued one last time and stops retrying (plugin shutdown). */
	public void stopOutbox()
	{
		SyncOutbox box = outbox;
		if (box != null)
		{
			box.stop();
		}
	}

	/** Sends everything queued now, ignoring any network backoff (logout, shutdown). */
	public void flushOutbox()
	{
		SyncOutbox box = outbox;
		if (box != null)
		{
			box.flushNow();
		}
	}

	/** Whether an upload of this label (e.g. "bank") is still queued or on its way. */
	public boolean hasPendingUpload(String label)
	{
		SyncOutbox box = outbox;
		return box != null && box.hasPending(label);
	}

	/** Sends what is queued soon (a goal or a container that should show quickly). */
	public void requestOutboxFlush()
	{
		SyncOutbox box = outbox;
		if (box != null)
		{
			box.requestFlush();
		}
	}

	/** When the last batch response arrived (epoch ms), or {@link Long#MIN_VALUE} if none yet. */
	public long getLastBatchResponseMs()
	{
		SyncOutbox box = outbox;
		return box == null ? Long.MIN_VALUE : box.getLastBatchResponseMs();
	}

	private void sendBatch(String baseUrl, String appKey, List<SyncOutbox.Item> items, SyncOutbox.BatchCallback callback)
	{
		Request request = new Request.Builder()
			.url(baseUrl + BATCH_ENDPOINT)
			.header("Content-Type", "application/json")
			.header("X-RuneLite-Key", appKey)
			.post(RequestBody.create(JSON_MEDIA_TYPE, batchBody(gson, items)))
			.build();
		largeRequestClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.onNetworkFailure(e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				List<Integer> statuses = null;
				Integer webVersion = null;
				int code = response.code();
				try
				{
					if (code >= HTTP_OK_MIN && code < HTTP_OK_MAX && response.body() != null)
					{
						BatchResult parsed = parseBatchResponse(response.body().string());
						statuses = parsed.statuses;
						webVersion = parsed.webVersion;
					}
				}
				catch (IOException e)
				{
					log.warn("Failed to read the batch response: {}", e.getMessage());
				}
				catch (RuntimeException e)
				{
					log.warn("Failed to read the batch response: {}", e.getMessage());
				}
				finally
				{
					response.close();
				}
				callback.onResponse(code, statuses, webVersion);
			}
		});
	}

	/** {@code {"requests":[{"path","method","body"}]}}, the bodies spliced in as the JSON they already are. */
	static String batchBody(Gson gson, List<SyncOutbox.Item> items)
	{
		StringBuilder sb = new StringBuilder("{");
		// The top-level player lets the server resolve webVersion even when no entry succeeds.
		for (SyncOutbox.Item item : items)
		{
			String player = playerInBody(item.getBody());
			if (player != null)
			{
				sb.append("\"player_username\":").append(gson.toJson(player)).append(',');
				break;
			}
		}
		sb.append("\"requests\":[");
		for (int i = 0; i < items.size(); i++)
		{
			SyncOutbox.Item item = items.get(i);
			if (i > 0)
			{
				sb.append(',');
			}
			sb.append("{\"path\":").append(gson.toJson(item.getPath()))
				.append(",\"method\":").append(gson.toJson(item.getMethod()))
				.append(",\"body\":").append(item.getBody() == null || item.getBody().isEmpty() ? "null" : item.getBody())
				.append('}');
		}
		return sb.append("]}").toString();
	}

	private static final java.util.regex.Pattern PLAYER_FIELD =
		java.util.regex.Pattern.compile("\"(?:player_username|player)\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"");

	/** The first player name a JSON body carries (cheap scan, no full parse), or null. */
	static String playerInBody(String body)
	{
		if (body == null)
		{
			return null;
		}
		java.util.regex.Matcher m = PLAYER_FIELD.matcher(body);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return new JsonParser().parse("\"" + m.group(1) + "\"").getAsString();
		}
		catch (RuntimeException e)
		{
			return m.group(1);
		}
	}

	static final class BatchResult
	{
		final List<Integer> statuses;
		final Integer webVersion;

		BatchResult(List<Integer> statuses, Integer webVersion)
		{
			this.statuses = statuses;
			this.webVersion = webVersion;
		}
	}

	/** Reads {@code {"results":[{"status","body"}],"webVersion"}}; missing parts come back null. */
	static BatchResult parseBatchResponse(String json)
	{
		JsonElement root = new JsonParser().parse(json);
		if (root == null || !root.isJsonObject())
		{
			return new BatchResult(null, null);
		}
		JsonObject obj = root.getAsJsonObject();
		List<Integer> statuses = null;
		JsonElement results = obj.get("results");
		if (results != null && results.isJsonArray())
		{
			statuses = new ArrayList<>();
			for (JsonElement r : results.getAsJsonArray())
			{
				JsonElement status = r.isJsonObject() ? r.getAsJsonObject().get("status") : null;
				statuses.add(status != null && status.isJsonPrimitive() ? status.getAsInt() : null);
			}
		}
		return new BatchResult(statuses, readWebVersion(obj));
	}

	private static Integer readWebVersion(JsonObject obj)
	{
		JsonElement v = obj.get("webVersion");
		return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isNumber() ? v.getAsInt() : null;
	}

	/** One upload on its own (no outbox yet, or a server without the batch endpoint). */
	private void sendOne(SyncOutbox.Item item, SyncOutbox.SingleCallback callback)
	{
		Request request = new Request.Builder()
			.url(item.getBaseUrl() + item.getPath())
			.header("Content-Type", "application/json")
			.header("X-RuneLite-Key", item.getAppKey())
			.post(RequestBody.create(JSON_MEDIA_TYPE, item.getBody()))
			.build();

		OkHttpClient client = item.isLarge() ? largeRequestClient : okHttpClient;
		client.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.onNetworkFailure(e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				int code = response.code();
				response.close();
				callback.onResponse(code);
			}
		});
	}

	// ------------------------------------------------------------- web version

	/**
	 * Asks the website for the player's webVersion (bumped whenever they change something there).
	 * The answer is passed to {@link #observeWebVersion} as well as to the callback.
	 */
	public void getWebVersion(String playerUsername, RoadmapCallback<Integer> callback)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			callback.onError("No OSRS Companion App Key configured");
			return;
		}
		Request request = new Request.Builder()
			.url(BASE_URL + VERSION_ENDPOINT + "?player=" + urlEncode(playerUsername))
			.header("X-RuneLite-Key", config.osrsCompanionAppKey().trim())
			.get()
			.build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				callback.onError("Network error");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				Integer version = null;
				try
				{
					if (response.code() >= HTTP_OK_MIN && response.code() < HTTP_OK_MAX && response.body() != null)
					{
						JsonElement root = new JsonParser().parse(response.body().string());
						version = root != null && root.isJsonObject() ? readWebVersion(root.getAsJsonObject()) : null;
					}
				}
				catch (IOException e)
				{
				}
				catch (RuntimeException e)
				{
				}
				finally
				{
					response.close();
				}
				if (version == null)
				{
					callback.onError("No web version");
					return;
				}
				observeWebVersion(version);
				callback.onSuccess(version);
			}
		});
	}

	/** Hears that the website's data changed (a different webVersion than the last one seen). */
	public void setWebVersionChangedListener(Runnable listener)
	{
		this.webVersionChangedListener = listener;
	}

	/**
	 * Notes a webVersion from a batch response or the version check; a change from the last value
	 * seen (not the first value since {@link #resetWebVersion()}) tells the listener.
	 */
	public void observeWebVersion(int version)
	{
		boolean changed;
		synchronized (this)
		{
			changed = lastWebVersion != null && lastWebVersion != version;
			lastWebVersion = version;
		}
		Runnable listener = webVersionChangedListener;
		if (changed && listener != null)
		{
			listener.run();
		}
	}

	/** Forgets the last webVersion (logout): the next login's first value is a baseline, not a change. */
	public synchronized void resetWebVersion()
	{
		lastWebVersion = null;
	}

	static boolean isDuplicate(String previousBody, String currentJson)
	{
		return previousBody != null && previousBody.equals(currentJson);
	}

	/**
	 * Forgets the last-sent body for every sync type, so the next send of each
	 * type goes out even if its payload is byte-identical to the previous one.
	 *
	 * <p>The roadmap panel's "Sync &amp; refresh" is an explicit, user-triggered
	 * re-sync: the dedupe guard (which silently skips unchanged idempotent syncs)
	 * must not swallow it, or the button would do nothing when the player's data
	 * hasn't changed since the last automatic sync.
	 */
	public void clearDedupeCache()
	{
		lastSentBodyByType.clear();
	}
}

package com.osrscompanion.api;

import lombok.Getter;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.IntConsumer;
import java.util.function.LongSupplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Holds the fire-and-forget uploads to {@code /api/runelite/*} and sends them together through
 * {@code POST /api/runelite/batch}, so a burst of changes costs one request instead of one each.
 *
 * <ul>
 *   <li>A flush runs at most every {@link #FLUSH_INTERVAL_MS} while something is queued, and right
 *       away for a priority request (a drop, a finished task, a goal) or {@link #flushNow()} (logout,
 *       plugin stop). Nothing queued means no request at all.</li>
 *   <li>A full-state upload (its {@code coalesceKey} set) queued again before it went out replaces
 *       the older copy; both callers' success callbacks still run. Events (no key) are never merged
 *       or dropped.</li>
 *   <li>Order is kept: one batch at a time, oldest first, at most {@link #MAX_BATCH_REQUESTS}
 *       requests (and about {@link #MAX_BATCH_CHARS} characters) each.</li>
 *   <li>A network failure (or a 5xx/429 for the whole batch) keeps the requests and tries again
 *       after 10 s, 20 s, 40 s... capped at {@link #BACKOFF_MAX_MS}; a request still unsent after
 *       {@link #MAX_AGE_MS} is dropped, so memory stays bounded.</li>
 *   <li>A server without the batch endpoint (404) gets each request on its own, in order, as before,
 *       and the batch endpoint is tried again {@link #BATCH_RETRY_AFTER_404_MS} later.</li>
 * </ul>
 *
 * The network side is a {@link Sender} and time is a clock, so the logic is unit-testable.
 */
@Slf4j
public final class SyncOutbox {
	static final long FLUSH_INTERVAL_MS = 10_000;
	static final long BACKOFF_BASE_MS = 10_000;
	static final long BACKOFF_MAX_MS = 120_000;
	static final long MAX_AGE_MS = 30 * 60_000L;
	static final int MAX_BATCH_REQUESTS = 50;
	static final int MAX_BATCH_CHARS = 2_000_000;
	static final long BATCH_RETRY_AFTER_404_MS = 10 * 60_000L;

	/** One queued upload. */
	public static final class Item {
		@Getter
		final String baseUrl;
		@Getter
		final String appKey;
		@Getter
		final String path;
		@Getter
		final String method;
		@Getter
		final String body;
		@Getter
		final String label;
		/** Non-null for a full-state upload: a newer one with the same key replaces it while queued. */
		final String coalesceKey;
		@Getter
		final boolean large;
		boolean priority;
		final List<Runnable> onSuccess = new ArrayList<>();
		long enqueuedAtMs;
		long seq;
		boolean inFlight;

		public Item(String baseUrl, String appKey, String path, String method, String body, String label,
			String coalesceKey, boolean priority, boolean large, Runnable onSuccess) {
			this.baseUrl = baseUrl;
			this.appKey = appKey;
			this.path = path;
			this.method = method;
			this.body = body;
			this.label = label;
			this.coalesceKey = coalesceKey;
			this.priority = priority;
			this.large = large;
			if (onSuccess != null) {
				this.onSuccess.add(onSuccess);
			}
		}

	}

	/** How a batch went: the HTTP status of the batch, and per request (in order) its status. */
	public interface BatchCallback {
		/** {@code statuses} and {@code webVersion} may be null when the response had none. */
		void onResponse(int httpStatus, List<Integer> statuses, Integer webVersion);

		void onNetworkFailure(String message);
	}

	public interface SingleCallback {
		void onResponse(int httpStatus);

		void onNetworkFailure(String message);
	}

	/** The network: sends asynchronously and answers exactly once through the callback. */
	public interface Sender {
		void sendBatch(String baseUrl, String appKey, List<Item> items, BatchCallback callback);

		void sendOne(Item item, SingleCallback callback);
	}

	private final Sender sender;
	private final ScheduledExecutorService executor;
	private final LongSupplier clockMs;

	private final List<Item> queue = new ArrayList<>();
	private long nextSeq;
	private boolean inFlight;
	/** Items queued before the current flush started (a split batch's rest goes on at once). */
	private long flushUpToSeq = -1;
	private boolean flushAfterInFlight;
	private ScheduledFuture<?> scheduled;
	private long scheduledDueMs;
	private int failures;
	private long backoffUntilMs;
	private long batchUnsupportedUntilMs;
	private boolean stopped;
	/** When a batch response last arrived (clock ms), or {@link Long#MIN_VALUE} if never. */
	@Getter
	private volatile long lastBatchResponseMs = Long.MIN_VALUE;
	private volatile IntConsumer webVersionListener;

	/**
	 * Adds one request to a batch about to be sent (the live activity status rides along with every
	 * batch this way). It is sent once with that batch and never queued or retried on its own.
	 */
	public interface BatchExtra {
		/** The request to add to this chunk (same server and key), or null for none. */
		Item extraFor(List<Item> chunk);
	}

	private volatile BatchExtra batchExtra;

	public SyncOutbox(Sender sender, ScheduledExecutorService executor, LongSupplier clockMs) {
		this.sender = sender;
		this.executor = executor;
		this.clockMs = clockMs;
	}

	public void setWebVersionListener(IntConsumer listener) {
		this.webVersionListener = listener;
	}

	public void setBatchExtra(BatchExtra extra) {
		this.batchExtra = extra;
	}

	public synchronized int size() {
		return queue.size();
	}

	/** True while an upload of this label is queued or on its way (the dedupe check must not skip then). */
	public synchronized boolean hasPending(String label) {
		for (Item i : queue) {
			if (i.label.equals(label)) {
				return true;
			}
		}
		return false;
	}

	/** Queues an upload; it goes out with the next flush (at once when it is a priority one). */
	public void enqueue(Item item) {
		boolean runNow;
		synchronized (this) {
			long now = clockMs.getAsLong();
			pruneExpired(now);
			item.enqueuedAtMs = now;
			if (item.coalesceKey != null) {
				for (Iterator<Item> it = queue.iterator(); it.hasNext(); ) {
					Item old = it.next();
					if (!old.inFlight && item.coalesceKey.equals(old.coalesceKey)
						&& Objects.equals(item.baseUrl, old.baseUrl) && Objects.equals(item.appKey, old.appKey)) {
						it.remove();
						// The older callers learn of the upload too, before the newer one.
						List<Runnable> merged = new ArrayList<>(old.onSuccess);
						merged.addAll(item.onSuccess);
						item.onSuccess.clear();
						item.onSuccess.addAll(merged);
						item.priority |= old.priority;
					}
				}
			}
			item.seq = nextSeq++;
			queue.add(item);
			runNow = requestFlushLocked(item.priority || stopped ? 0 : FLUSH_INTERVAL_MS, now);
		}
		if (runNow) {
			flush();
		}
	}

	/** Asks for a flush soon (a priority moment), still waiting out a network backoff. */
	public void requestFlush() {
		boolean runNow;
		synchronized (this) {
			if (queue.isEmpty()) {
				return;
			}
			runNow = requestFlushLocked(0, clockMs.getAsLong());
		}
		if (runNow) {
			flush();
		}
	}

	/** Sends everything queued now, ignoring any backoff (logout, plugin stop). */
	public void flushNow() {
		synchronized (this) {
			backoffUntilMs = 0;
			if (inFlight) {
				flushAfterInFlight = true;
				return;
			}
		}
		flush();
	}

	/** Re-enables retries after {@link #stop()} (plugin started again). */
	public synchronized void start() {
		stopped = false;
	}

	/**
	 * Sends what is queued one last time; afterwards nothing is retried (failed requests are dropped)
	 * and later requests go out at once, so nothing lingers once the plugin is off.
	 */
	public void stop() {
		synchronized (this) {
			stopped = true;
			cancelScheduledLocked();
		}
		flushNow();
	}

	/** True when a flush should run on the caller's thread right now. */
	private boolean requestFlushLocked(long delayMs, long now) {
		if (inFlight) {
			if (delayMs == 0) {
				flushAfterInFlight = true;
			}
			return false;
		}
		long due = Math.max(now + delayMs, backoffUntilMs);
		if (scheduled != null && scheduledDueMs <= due) {
			return false;
		}
		cancelScheduledLocked();
		scheduledDueMs = due;
		scheduled = executor.schedule(this::flush, Math.max(0, due - now), TimeUnit.MILLISECONDS);
		return false;
	}

	private void cancelScheduledLocked() {
		if (scheduled != null) {
			scheduled.cancel(false);
			scheduled = null;
		}
	}

	/** Sends the next batch (runs on the executor; the sending itself is asynchronous). */
	void flush() {
		List<Item> chunk;
		boolean useBatch;
		synchronized (this) {
			scheduled = null;
			if (inFlight) {
				return;
			}
			long now = clockMs.getAsLong();
			pruneExpired(now);
			if (queue.isEmpty()) {
				return;
			}
			if (now < backoffUntilMs) {
				requestFlushLocked(0, now);
				return;
			}
			flushUpToSeq = nextSeq - 1;
			chunk = takeChunkLocked();
			for (Item i : chunk) {
				i.inFlight = true;
			}
			inFlight = true;
			flushAfterInFlight = false;
			useBatch = now >= batchUnsupportedUntilMs;
		}
		if (useBatch) {
			addExtra(chunk);
			sendBatch(chunk);
		} else {
			sendIndividually(chunk, 0, new Integer[chunk.size()]);
		}
	}

	/** The {@link BatchExtra}'s request, appended (in flight with the chunk, never queued). */
	private void addExtra(List<Item> chunk) {
		BatchExtra extra = batchExtra;
		if (extra == null || chunk.size() >= MAX_BATCH_REQUESTS) {
			return;
		}
		try {
			Item item = extra.extraFor(Collections.unmodifiableList(chunk));
			Item first = chunk.get(0);
			if (item != null && Objects.equals(item.baseUrl, first.baseUrl) && Objects.equals(item.appKey, first.appKey)) {
				item.inFlight = true;
				item.enqueuedAtMs = clockMs.getAsLong();
				chunk.add(item);
			}
		} catch (RuntimeException e) {
		}
	}

	/** The oldest requests that share one server and key, at most 50 and about 2 MB. */
	private List<Item> takeChunkLocked() {
		List<Item> chunk = new ArrayList<>();
		Item first = queue.get(0);
		long chars = 0;
		for (Item i : queue) {
			if (chunk.size() >= MAX_BATCH_REQUESTS
				|| !Objects.equals(i.baseUrl, first.baseUrl) || !Objects.equals(i.appKey, first.appKey)) {
				break;
			}
			long size = i.body.length() + i.path.length() + 64;
			if (!chunk.isEmpty() && chars + size > MAX_BATCH_CHARS) {
				break;
			}
			chunk.add(i);
			chars += size;
		}
		return chunk;
	}

	private void sendBatch(List<Item> chunk) {
		Item first = chunk.get(0);
		try {
			sender.sendBatch(first.baseUrl, first.appKey, Collections.unmodifiableList(chunk), new BatchCallback() {
				@Override
				public void onResponse(int httpStatus, List<Integer> statuses, Integer webVersion) {
					onBatchResponse(chunk, httpStatus, statuses, webVersion);
				}

				@Override
				public void onNetworkFailure(String message) {
					log.warn("Failed to send {} queued uploads to the OSRS Companion API: {}", chunk.size(), message);
					complete(chunk, new Integer[chunk.size()], true);
				}
			});
		} catch (RuntimeException e) {
			log.warn("Failed to send queued uploads to the OSRS Companion API", e);
			complete(chunk, new Integer[chunk.size()], true);
		}
	}

	private void onBatchResponse(List<Item> chunk, int httpStatus, List<Integer> statuses, Integer webVersion) {
		Integer[] results = new Integer[chunk.size()];
		if (httpStatus == 404) {
			synchronized (this) {
				batchUnsupportedUntilMs = clockMs.getAsLong() + BATCH_RETRY_AFTER_404_MS;
			}
			sendIndividually(chunk, 0, results);
			return;
		}
		if (httpStatus == 429 || httpStatus >= 500) {
			log.warn("OSRS Companion API returned {} for a batch of {} uploads; will retry", httpStatus, chunk.size());
			complete(chunk, results, true);
			return;
		}
		if (httpStatus < 200 || httpStatus >= 300) {
			log.warn("OSRS Companion API returned {} for a batch of {} uploads; dropped", httpStatus, chunk.size());
			Arrays.fill(results, httpStatus);
			complete(chunk, results, false);
			return;
		}
		lastBatchResponseMs = clockMs.getAsLong();
		for (int i = 0; i < results.length; i++) {
			results[i] = statuses != null && i < statuses.size() && statuses.get(i) != null ? statuses.get(i) : -1;
		}
		complete(chunk, results, false);
		IntConsumer listener = webVersionListener;
		if (webVersion != null && listener != null) {
			try {
				listener.accept(webVersion);
			} catch (RuntimeException e) {
				log.warn("Web version listener failed", e);
			}
		}
	}

	/** The old way (a server without the batch endpoint): one request at a time, in order. */
	private void sendIndividually(List<Item> chunk, int index, Integer[] results) {
		if (index >= chunk.size()) {
			complete(chunk, results, false);
			return;
		}
		try {
			sender.sendOne(chunk.get(index), new SingleCallback() {
				@Override
				public void onResponse(int httpStatus) {
					results[index] = httpStatus;
					sendIndividually(chunk, index + 1, results);
				}

				@Override
				public void onNetworkFailure(String message) {
					log.warn("Failed to send {} sync to OSRS Companion API: {}", chunk.get(index).label, message);
					complete(chunk, results, true);
				}
			});
		} catch (RuntimeException e) {
			log.warn("Failed to send {} sync to OSRS Companion API", chunk.get(index).label, e);
			complete(chunk, results, true);
		}
	}

	/**
	 * Settles a chunk: requests with a status are done (success callbacks for 2xx, dropped otherwise);
	 * those without one stay queued for a retry when {@code retry}.
	 */
	private void complete(List<Item> chunk, Integer[] results, boolean retry) {
		List<Runnable> callbacks = new ArrayList<>();
		boolean runNow;
		synchronized (this) {
			long now = clockMs.getAsLong();
			inFlight = false;
			for (int i = 0; i < chunk.size(); i++) {
				Item item = chunk.get(i);
				item.inFlight = false;
				Integer status = results[i];
				if (status == null) {
					if (stopped) {
						queue.remove(item);
					}
					continue;
				}
				queue.remove(item);
				if (status >= 200 && status < 300) {
					callbacks.addAll(item.onSuccess);
				} else {
					log.warn("OSRS Companion API returned {} for {} sync", status, item.label);
				}
			}
			if (retry && !stopped) {
				failures++;
				long backoff = Math.min(BACKOFF_MAX_MS, BACKOFF_BASE_MS << Math.min(failures - 1, 10));
				backoffUntilMs = now + backoff;
				mergeRetriedLocked(chunk);
			} else if (!retry) {
				failures = 0;
				backoffUntilMs = 0;
			}
			pruneExpired(now);
			runNow = false;
			if (!queue.isEmpty()) {
				boolean continuing = !retry && queue.get(0).seq <= flushUpToSeq;
				boolean urgent = flushAfterInFlight || stopped || anyPriorityLocked();
				flushAfterInFlight = false;
				if (continuing && now >= backoffUntilMs) {
					runNow = true;
				} else {
					requestFlushLocked(continuing || urgent ? 0 : FLUSH_INTERVAL_MS, now);
				}
			}
		}
		for (Runnable r : callbacks) {
			try {
				r.run();
			} catch (RuntimeException e) {
				log.warn("Upload callback failed", e);
			}
		}
		if (runNow) {
			flush();
		}
	}

	/** A failed full-state upload that a newer copy queued meanwhile replaces is not sent twice. */
	private void mergeRetriedLocked(List<Item> chunk) {
		for (Item failed : chunk) {
			if (failed.coalesceKey == null || !queue.contains(failed)) {
				continue;
			}
			for (Item later : queue) {
				if (later != failed && later.seq > failed.seq && failed.coalesceKey.equals(later.coalesceKey)
					&& Objects.equals(failed.baseUrl, later.baseUrl) && Objects.equals(failed.appKey, later.appKey)) {
					List<Runnable> merged = new ArrayList<>(failed.onSuccess);
					merged.addAll(later.onSuccess);
					later.onSuccess.clear();
					later.onSuccess.addAll(merged);
					later.priority |= failed.priority;
					queue.remove(failed);
					break;
				}
			}
		}
	}

	private boolean anyPriorityLocked() {
		for (Item i : queue) {
			if (i.priority) {
				return true;
			}
		}
		return false;
	}

	private void pruneExpired(long now) {
		for (Iterator<Item> it = queue.iterator(); it.hasNext(); ) {
			Item i = it.next();
			if (!i.inFlight && now - i.enqueuedAtMs > MAX_AGE_MS) {
				it.remove();
				log.warn("Dropped {} sync: not delivered within {} minutes", i.label, MAX_AGE_MS / 60_000);
			}
		}
	}
}

package com.osrscompanion.model;

import lombok.Getter;
import com.google.gson.Gson;
import java.util.*;

/**
 * Payload for syncing bank/vault items to the OSRS Companion API.
 * Matches the format expected by POST /api/runelite/bank/
 *
 * Items is a map keyed by source (e.g. "bank", "seed_vault") to a list of items.
 */
public class BankSyncPayload {
	private final String player_username;
	@Getter
	private final Map<String, List<BankItem>> items;

	public BankSyncPayload(String playerUsername, Map<String, List<BankItem>> items) {
		this.player_username = playerUsername;
		this.items = items;
	}

	public String getPlayerUsername() {
		return player_username;
	}

	public int getTotalItemCount() {
		return items.values().stream().mapToInt(List::size).sum();
	}

	public String toJson(Gson gson) {
		return gson.toJson(this);
	}

	/**
	 * Represents a single bank item with ID and quantity.
	 */
	public static class BankItem {
		private final int item_id;
		@Getter
		private final int quantity;

		public BankItem(int itemId, int quantity) {
			this.item_id = itemId;
			this.quantity = quantity;
		}

		public int getItemId() {
			return item_id;
		}

	}
}

package com.osrscompanion.model;

import lombok.Getter;
import com.google.gson.annotations.SerializedName;
import java.util.*;

/**
 * The active boss gear set as returned by GET /api/runelite/boss-gear/: per worn slot the item to
 * bring (picked by the gear mode), the wiki's 28 inventory slots and rune pouch, plus every saved set
 * to switch between. Besides the worn slots, "special" is the special attack weapon and "switch" /
 * "switch_shield" the Alternate weapon and its off-hand; with a two-handed weapon there is no "shield".
 */
public class BossGear {
	/** Gear modes of wiki presets: always the best in slot, the best owned from the wiki's list, or that plus owned alternatives. */
	public static final String MODE_BIS = "bis";
	public static final String MODE_OWNED = "owned";
	public static final String MODE_ALTERNATIVES = "alternatives";
	public static final String[] MODES = {MODE_BIS, MODE_OWNED, MODE_ALTERNATIVES};

	/** A gear mode's name as the website shows it. */
	public static String modeLabel(String mode) {
		return MODE_BIS.equals(mode) ? "Best in slot" : MODE_ALTERNATIVES.equals(mode) ? "Owned alternatives" : "Best owned";
	}

	/** A short name for narrow places. */
	public static String modeShortLabel(String mode) {
		return MODE_BIS.equals(mode) ? "BiS" : MODE_ALTERNATIVES.equals(mode) ? "Alts" : "Owned";
	}

	/** What a gear mode does, in one line. */
	public static String modeDescription(String mode) {
		return MODE_BIS.equals(mode) ? "Every slot shows the wiki's best in slot, owned or not."
			: MODE_ALTERNATIVES.equals(mode) ? "Best owned from the wiki's list; where you own none, your best item of the setup's style (marked A)."
			: "The best item you own from the slot's wiki list; red when you own none. Inventory items you lack become an owned one doing the same job (marked A).";
	}

	/** The mode after this one (bis, owned, alternatives, bis, ...). */
	public static String nextMode(String mode) {
		for (int i = 0; i < MODES.length; i++) {
			if (MODES[i].equals(mode)) {
				return MODES[(i + 1) % MODES.length];
			}
		}
		return MODE_OWNED;
	}

	@Getter
	@SerializedName("id")
	private int id;

	@Getter
	@SerializedName("boss")
	private String boss;

	@SerializedName("boss_name")
	private String bossName;

	/** The boss picture on the OSRS Wiki (for the side panel). */
	@Getter
	@SerializedName("image")
	private String image;

	@SerializedName("style")
	private String style;

	@Getter
	@SerializedName("inventory_label")
	private String inventoryLabel;

	/** Whether the bank was ever synced: without it "owned" says nothing. */
	@Getter
	@SerializedName("synced")
	private boolean synced;

	/** The boss's strategy page on the OSRS Wiki (Go to wiki). */
	@Getter
	@SerializedName("url")
	private String url;

	/** The weapon brought is two-handed: the shield slot stays empty. */
	@Getter
	@SerializedName("two_handed")
	private boolean twoHanded;

	@SerializedName("equipment")
	private List<Slot> equipment;

	/** The 28 inventory slots in order; null entries are empty slots. */
	@SerializedName("inventory")
	private List<Item> inventory;

	@SerializedName("pouch")
	private List<Item> pouch;

	/** The spellbook the rune pouch's runes are for (Standard, Ancient, Lunar, Arceuus), or null. */
	@Getter
	@SerializedName("spellbook")
	private String spellbook;

	/** What your last (up to ten) trips at this boss used, by supply key, oldest first. */
	@SerializedName("trip_supplies")
	private List<Map<String, Long>> tripSupplies;

	public List<Map<String, Long>> getTripSupplies() {
		return tripSupplies == null ? java.util.Collections.emptyList() : tripSupplies;
	}

	/** The ammo / spell options for the weapon, best first (the bank layout shows the setting's number of them). */
	@Getter
	@SerializedName("supplies")
	private SlayerGear.Supplies supplies;

	/** The same for the other ranged weapons the set brings (a blowpipe's darts, a switch crossbow's bolts). */
	@SerializedName("more_supplies")
	private List<SlayerGear.Supplies> moreSupplies;

	/** What recharges the set's charged items (runes, scales, ether...). */
	@SerializedName("bring")
	private List<SlayerGear.Bring> bring;

	public List<SlayerGear.Bring> getBring() {
		return bring == null ? java.util.Collections.emptyList() : bring;
	}

	/** The items of the first {@code n} ammo / spell options of each weapon (runes once each), best first. */
	public List<Integer> supplyItems(int n) {
		java.util.LinkedHashSet<Integer> out = new java.util.LinkedHashSet<>();
		List<SlayerGear.Supplies> all = new java.util.ArrayList<>();
		if (supplies != null) {
			all.add(supplies);
		}
		if (moreSupplies != null) {
			all.addAll(moreSupplies);
		}
		for (SlayerGear.Supplies s : all) {
			if (s == null) {
				continue;
			}
			List<SlayerGear.Supplies.Option> options = s.getOptions();
			for (SlayerGear.Supplies.Option o : options.subList(0, Math.min(Math.max(0, n), options.size()))) {
				out.addAll(o.getItems());
			}
		}
		return new java.util.ArrayList<>(out);
	}

	public String getBossName() {
		return bossName == null ? "Boss" : bossName;
	}

	public String getStyle() {
		return style == null ? "" : style;
	}

	public List<Slot> getEquipment() {
		return equipment == null ? Collections.emptyList() : equipment;
	}

	/** The 28 inventory slots (null: empty); a switch already worn ({@link #wornAt}) counts as empty. */
	public List<Item> getInventory() {
		if (inventory == null) {
			return Collections.emptyList();
		}
		List<Item> out = new java.util.ArrayList<>(inventory.size());
		for (Item it : inventory) {
			out.add(it != null && it.isWorn() ? null : it);
		}
		return out;
	}

	/** The switch in inventory slot {@code i} that the setup already wears (nothing to bring), or null. */
	public Item wornAt(int i) {
		Item it = inventory != null && i < inventory.size() ? inventory.get(i) : null;
		return it != null && it.isWorn() ? it : null;
	}

	public List<Item> getPouch() {
		return pouch == null ? Collections.emptyList() : pouch;
	}

	/** The item for a worn slot (head, cape, ..., special), or null. */
	public Slot slot(String name) {
		for (Slot s : getEquipment()) {
			if (name.equals(s.getSlot())) {
				return s;
			}
		}
		return null;
	}

	public static class Item {
		/** The id to show: the version the player owns, else the item itself. */
		@Getter
		@SerializedName("item")
		private int item;

		@SerializedName("name")
		private String name;

		/** Every id that counts as this item (owned version, the item, its other versions). */
		@SerializedName("ids")
		private List<Integer> ids;

		/** In the bank or other synced storage, worn or carried at the last sync. */
		@Getter
		@SerializedName("owned")
		private boolean owned;

		@SerializedName("qty")
		private int qty;

		@Getter
		@SerializedName("noted")
		private boolean noted;

		/** bis | partial | missing | alt | unknown for worn slots; inventory and pouch items only say "alt". */
		@SerializedName("status")
		private String status;

		/** Status "alt": the wiki item(s) this owned item stands in for (not owned). */
		@SerializedName("alt_for")
		private String altFor;

		/** Why this item and nothing weaker (a boss mechanic), or why a slot brings it (crystal armour with the Bow of Faerdhinen). */
		@SerializedName("need")
		private String need;

		public String getName() {
			return name == null ? "Item" : name;
		}

		public List<Integer> getIds() {
			return ids == null || ids.isEmpty() ? Collections.singletonList(item) : ids;
		}

		/** The stack size, 1 when the wiki gives none. */
		public int getQty() {
			return Math.max(1, qty);
		}

		public String getStatus() {
			return status == null ? "unknown" : status;
		}

		/**
		 * An owned item brought instead of the wiki's that you don't own: an owned alternative in a worn
		 * slot, or an inventory item that does the same job ("Best owned" / "Owned alternatives").
		 */
		public boolean isAlternative() {
			return "alt".equals(status);
		}

		public String getAltFor() {
			return altForOr("the wiki's item");
		}

		/** An inventory switch whose best owned item is already worn: its slot stays empty. */
		public boolean isWorn() {
			return "worn".equals(status);
		}

		/** The mechanic or rule behind the item, null when there is none. */
		public String getNeed() {
			return need == null || need.isEmpty() ? null : need;
		}

		protected String altForOr(String fallback) {
			return altFor == null || altFor.isEmpty() ? fallback : altFor;
		}
	}

	public static class Slot extends Item {
		@Getter
		@SerializedName("slot")
		private String slot;

		@Getter
		@SerializedName("rank")
		private Integer rank;

		@Override
		public String getAltFor() {
			return altForOr("the best in slot");
		}
