		public State(
				Integer taskId,
				String taskName,
				Integer bossTaskId,
				Integer areaId,
				Integer masterId,
				int amountRemaining,
				int amountOriginal,
				int points,
				int streak,
				int wildernessStreak,
				List<Integer> blockList,
				Map<String, Integer> unlockBitfields,
				Map<String, Object> extra,
				Integer slayerLevel,
