/** Golden renders of the farm run's inventory and bank item highlights (see {@link UiKit}). */
public class FarmRunItemsUiGoldenTest {
	private final FarmRunManager manager = mock(FarmRunManager.class);
	private final FarmRoute route = UiSamples.route();

	/** Item ids in an inventory (group 149) or the bank (group 12), in 4 columns of 42 x 36. */
	private UiKit.Rendered draw(int group, int... items) {
		return UiKit.guarded(() -> drawUnguarded(group, items));
	}

	private UiKit.Rendered drawUnguarded(int group, int... items) {
		FarmRunItemOverlay overlay = new FarmRunItemOverlay(new TestOSRSCompanionConfig(), manager);
		BufferedImage img = new BufferedImage(200, 300, BufferedImage.TYPE_INT_ARGB);
		List<String> log = new ArrayList<>();
		Graphics2D g = new RecordingGraphics(img.createGraphics(), log, i -> "img");
		Widget container = mock(Widget.class);
		when(container.getId()).thenReturn(group << 16);
		for (int i = 0; i < items.length; i++) {
			WidgetItem wi = mock(WidgetItem.class);
			when(wi.getWidget()).thenReturn(container);
			when(wi.getCanvasBounds()).thenReturn(new Rectangle(8 + (i % 4) * 42, 8 + (i / 4) * 36, 36, 32));
			log.add("item " + items[i]);
			overlay.renderItemOverlay(g, items[i], wi);
		}
		return new UiKit.Rendered(log, img);
	}

	private void running(boolean complete) {
		when(manager.isRunning()).thenReturn(true);
		when(manager.isComplete()).thenReturn(complete);
		Map<Integer, FarmRunManager.Highlight> h = new HashMap<>();
		h.put(13128, FarmRunManager.Highlight.TELEPORT);
		h.put(5295, FarmRunManager.Highlight.SEED);
		h.put(5986, FarmRunManager.Highlight.PAYMENT);
		h.put(21483, FarmRunManager.Highlight.COMPOST);
		when(manager.currentItems()).thenReturn(h);
		when(manager.loadout()).thenReturn(route.getInventory());
	}

	@Test
	public void inventoryDuringTheRun() {
		running(false);
		UiKit.golden("farm-items-inventory", draw(149, 13128, 5295, 5986, 21483, 952, 1));
	}

	@Test
	public void bankShowsWhatToBringStill() {
		running(false);
		when(manager.neededStack(anyInt(), anyList())).thenReturn(null);
		FarmRoute.Stack spade = route.getInventory().get(1);
		FarmRoute.Stack rake = route.getInventory().get(0);
		when(manager.neededStack(952, route.getInventory())).thenReturn(spade);
		when(manager.neededStack(5341, route.getInventory())).thenReturn(rake);
		when(manager.carried(952)).thenReturn(0);
		when(manager.carried(5341)).thenReturn(1);
		UiKit.golden("farm-items-bank", draw(12, 952, 5341, 5295, 1, 13128));
	}

	@Test
	public void completeRunOnlyHighlightsCompost() {
		running(true);
		UiKit.golden("farm-items-complete", draw(149, 13128, 5295, 21483));
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.model.FarmRoute;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class FarmRunManagerTest {
	@Test
	public void finishedBodyListsPatchesAndXp() {
		assertEquals("<col=ffffff>8 patches, 1,234 Farming XP</col>", FarmRunManager.finishedBody(8, 1234));
	}

	@Test
	public void finishedBodyLeavesOutXpWhenNone() {
		assertEquals("<col=ffffff>1 patch</col>", FarmRunManager.finishedBody(1, 0));
	}

	@Test
	public void compostFlagFallsBackToThePatchType() {
		Gson gson = new Gson();
		assertTrue(gson.fromJson("{\"impl\":\"HERB\"}", FarmRoute.Patch.class).takesCompost());
		assertFalse(gson.fromJson("{\"impl\":\"COMPOST\"}", FarmRoute.Patch.class).takesCompost());
		assertFalse(gson.fromJson("{\"impl\":\"HERB\",\"compost\":false}", FarmRoute.Patch.class).takesCompost());
	}

	@Test
	public void routePictureIsTheMostVisitedPatchTypesMostPlantedCrop() {
		Gson gson = new Gson();
		// 3 tree patches (2 magic, 1 yew), 2 herbs, 4 compost bins: a magic sapling.
		String trees = "{\"stops\":[{\"patches\":["
			+ "{\"impl\":\"TREE\",\"seed\":5374},{\"impl\":\"TREE\",\"seed\":5374},{\"impl\":\"TREE\",\"seed\":5373},"
			+ "{\"impl\":\"HERB\",\"seed\":5295,\"produce\":207},{\"impl\":\"HERB\",\"seed\":5295,\"produce\":207},"
			+ "{\"impl\":\"COMPOST\",\"seed\":6032},{\"impl\":\"COMPOST\",\"seed\":6032},{\"impl\":\"COMPOST\",\"seed\":6032},{\"impl\":\"COMPOST\",\"seed\":6032}]}]}";
		assertEquals(Integer.valueOf(5374), gson.fromJson(trees, FarmRoute.class).pictureItem());
		// Mostly herbs: the herb they give, not the seed.
		String herbs = "{\"stops\":[{\"patches\":[{\"impl\":\"FRUIT_TREE\",\"seed\":5501},"
			+ "{\"impl\":\"HERB\",\"seed\":5295,\"produce\":207},{\"impl\":\"HERB\",\"seed\":5295,\"produce\":207}]}]}";
		assertEquals(Integer.valueOf(207), gson.fromJson(herbs, FarmRoute.class).pictureItem());
		assertNull(gson.fromJson("{\"stops\":[]}", FarmRoute.class).pictureItem());
	}

	@Test
	public void compostCountFollowsThePatchesNotTheRoute() {
		Gson gson = new Gson();
		List<FarmRoute.Stack> inv = Arrays.asList(
			gson.fromJson("{\"item\":5295,\"qty\":9,\"why\":\"Seed\"}", FarmRoute.Stack.class),
			gson.fromJson("{\"item\":21483,\"qty\":9,\"why\":\"Compost\",\"name\":\"Ultracompost\"}", FarmRoute.Stack.class));
		List<FarmRoute.Stack> four = FarmRunManager.withCompost(inv, 4);
		assertEquals(2, four.size());
		assertEquals(9, four.get(0).getQty());
		assertEquals(4, four.get(1).getQty());
		assertEquals("Ultracompost", four.get(1).getName());
		// No patch to compost: the compost is left out.
		assertEquals(1, FarmRunManager.withCompost(inv, 0).size());
		// A bottomless bucket is one item whatever the count.
		List<FarmRoute.Stack> bucket = Arrays.asList(gson.fromJson("{\"item\":22997,\"qty\":1,\"why\":\"Compost\"}", FarmRoute.Stack.class));
		assertEquals(1, FarmRunManager.withCompost(bucket, 5).get(0).getQty());
	}
}

