package com.osrscompanion;

import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class GoalImageCacheTest {
	@Test
	public void smallImagesAreLeftAlone() {
		BufferedImage small = new BufferedImage(20, 16, BufferedImage.TYPE_INT_ARGB);
		assertSame(small, GoalImageCache.fit(small));
	}

	@Test
	public void largeImagesFitTheIconSquareKeepingAspect() {
		BufferedImage tall = new BufferedImage(200, 400, BufferedImage.TYPE_INT_ARGB);
		BufferedImage fitted = GoalImageCache.fit(tall);
		assertEquals(GoalImageCache.ICON_SIZE, fitted.getHeight());
		assertEquals(16, fitted.getWidth());

		BufferedImage wide = new BufferedImage(640, 64, BufferedImage.TYPE_INT_ARGB);
		BufferedImage fittedWide = GoalImageCache.fit(wide);
		assertEquals(GoalImageCache.ICON_SIZE, fittedWide.getWidth());
		assertTrue(fittedWide.getHeight() <= GoalImageCache.ICON_SIZE);
	}

	@Test
	public void onlyWikiImagesAreFetched() {
		assertTrue(GoalImageCache.isAllowed("https://oldschool.runescape.wiki/images/Zulrah.png"));
		assertTrue(GoalImageCache.isAllowed("https://oldschool.runescape.wiki/images/Attack_icon.png?7d0d4"));

		assertFalse(GoalImageCache.isAllowed(null));
		assertFalse(GoalImageCache.isAllowed(""));
		assertFalse(GoalImageCache.isAllowed("http://oldschool.runescape.wiki/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://example.com/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki.example.com/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki@example.com/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki:8443/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki/w/Zulrah"));
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.model.RoadmapGoal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class GoalPartitionTest {
	private static final Gson GSON = new Gson();

	private static RoadmapGoal goal(int id, boolean complete, String completedAt) {
		String at = completedAt == null ? "null" : "\"" + completedAt + "\"";
		return GSON.fromJson("{\"id\":" + id + ",\"sort_order\":" + id + ",\"name\":\"G" + id
				+ "\",\"is_complete\":" + complete + ",\"completed_at\":" + at + "}", RoadmapGoal.class);
	}

	private static List<Integer> ids(List<RoadmapGoal> goals) {
		List<Integer> out = new ArrayList<>();
		for (RoadmapGoal g : goals) {
			out.add(g.getId());
		}
		return out;
	}

	private static GoalPartition split(List<RoadmapGoal> goals, Integer... sessionIds) {
		Set<Integer> session = new HashSet<>(Arrays.asList(sessionIds));
		return GoalPartition.of(goals, RoadmapGoal::isComplete, g -> session.contains(g.getId()));
	}

	@Test
	public void allIncompleteStaysInTree() {
		List<RoadmapGoal> goals = Arrays.asList(goal(1, false, null), goal(2, false, null));
		GoalPartition p = split(goals);
		assertEquals(Arrays.asList(1, 2), ids(p.getTree()));
		assertTrue(p.getCompleted().isEmpty());
	}

	@Test
	public void completedGoalsLeaveTheTreeNewestFirst() {
		List<RoadmapGoal> goals = Arrays.asList(
				goal(1, true, "2026-09-01T10:00:00Z"),
				goal(2, false, null),
				goal(3, true, "2026-09-05T10:00:00+00:00"),
				goal(4, true, "2026-09-03T10:00:00Z"));
		GoalPartition p = split(goals);
		assertEquals(Collections.singletonList(2), ids(p.getTree()));
		assertEquals(Arrays.asList(3, 4, 1), ids(p.getCompleted()));
	}

	@Test
	public void sessionCompletedGoalsMoveToCompletedAsNewest() {
		List<RoadmapGoal> goals = Arrays.asList(
				goal(1, true, "2026-09-09T10:00:00Z"),
				goal(2, true, null),
				goal(3, false, null));
		GoalPartition p = split(goals, 2);
		assertEquals(Collections.singletonList(3), ids(p.getTree()));
		assertEquals(Arrays.asList(2, 1), ids(p.getCompleted()));
	}

	@Test
	public void unknownTimesSortLastAndTiesKeepOrder() {
		List<RoadmapGoal> goals = Arrays.asList(
				goal(1, true, null),
				goal(2, true, "2026-09-01T10:00:00Z"),
				goal(3, true, "garbage"),
				goal(4, true, "2026-09-01T10:00:00Z"));
		GoalPartition p = split(goals);
		assertEquals(Arrays.asList(2, 4, 1, 3), ids(p.getCompleted()));
	}

	@Test
	public void emptyInput() {
		GoalPartition p = split(Collections.emptyList());
		assertTrue(p.getTree().isEmpty());
		assertTrue(p.getCompleted().isEmpty());
	}
}

package com.osrscompanion;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class GoalProgressBarComponentTest {
	@Test
	public void rendersBarAndReportsSize() {
		BufferedImage image = new BufferedImage(200, 40, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		FontMetrics fm = g.getFontMetrics();

		GoalProgressBarComponent bar = new GoalProgressBarComponent(0.5, "123 / 500", "25%");
		bar.setPreferredLocation(new Point(0, 0));
		bar.setPreferredSize(new Dimension(200, 0));
		Dimension size = bar.render(g);

		int expectedHeight = GoalProgressBarComponent.TOP_GAP + GoalProgressBarComponent.BAR_HEIGHT
				+ GoalProgressBarComponent.BAR_TEXT_GAP + fm.getHeight();
		assertEquals(new Dimension(200, expectedHeight), size);
		assertEquals(size, bar.getBounds().getSize());

		int y = GoalProgressBarComponent.TOP_GAP + GoalProgressBarComponent.BAR_HEIGHT / 2;
		int filled = image.getRGB(20, y);
		int empty = image.getRGB(180, y);
		assertEquals(GoalProgressBarComponent.FILL.getRGB(), filled);
		assertNotEquals(GoalProgressBarComponent.FILL.getRGB(), empty);
		g.dispose();
	}

	@Test
	public void minWidthGrowsWithPercent() {
		BufferedImage image = new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB);
		FontMetrics fm = image.createGraphics().getFontMetrics();
		int without = new GoalProgressBarComponent(0.1, "123 / 500", null).minWidth(fm);
		int with = new GoalProgressBarComponent(0.1, "123 / 500", "25%").minWidth(fm);
		assertTrue(with > without);
	}
}

