package com.osrscompanion;

import com.google.gson.Gson;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.zip.GZIPOutputStream;
import org.junit.Test;

/**
 * The website writes the live activity's text and picture now: this runs the plugin's old choice (with its texts)
 * and the new one (kind, subject and parts) on random signals and writes both to build/oracle/activity-oracle.json.gz,
 * which the website's test composes from the parts and compares with the old texts.
 */
public class LiveActivityOracleTest {
	private static final String[] SPELLS = {
		"Varrock Teleport", "Lumbridge Teleport", "Watchtower Teleport", "Ape Atoll Teleport", "Ape Atoll Teleport (Arceuus)",
		"Teleport to House", "Kharyrll Teleport", "Ghorrock Teleport", "Moonclan Teleport", "Tele Group Waterbirth",
		"Tele Group Moonclan", "Tele Group Barbarian", "Lumbridge Home Teleport", "Civitas illa Fortis Home Teleport",
		"Teleport to Target", "Teleport to Ape Atoll", "Salve Graveyard Teleport", "Respawn Teleport", " Teleport",
		"High Level Alchemy", "Low Level Alchemy", "Fire Strike", "Ice Barrage", "Crumble Undead", "Some New Spell",
		"Superheat Item", "Lvl-1 Enchant", "Humidify", "Plank Make", "Monster Examine", "Dark Lure", "Spin Flax"};
	private static final String[] TABLETS = {"Varrock teleport", "Kourend castle teleport", "Teleport to house", "Watchtower teleport",
		"Ape atoll teleport", "Salve graveyard teleport", "Arceuus library teleport"};
	private static final String[] NAMES = {"Rune platebody", "Iron dagger", "Hill Giant", "Abyssal demon", "Raw shark", "Gold ring",
		"Ranarr weed", " Snapdragon ", "Blue dragon"};
	private static final String[] TASKS = {"abyssal demons", "blue dragons", "ABERRANT SPECTRES", "Kalphite", " cave krakens", "x"};
	private static final String[] SKILLS = {"fishing", "FISHING", "Fishing", "magic", "MAGIC", "Magic", "woodcutting", " runecraft", "AgIlity"};
	private static final String[] STRINGS = {null, "", "  ", "Chambers of Xeric", "Wintertodt", "Vorkath", "Herb run", "Hill Giant"};

	private final Random r = new Random(20261011);

	private <T> T pick(T[] a) {
		return a[r.nextInt(a.length)];
	}

	private String maybe(String[] a) {
		int k = r.nextInt(10);
		return k == 0 ? null : k == 1 ? "" : k == 2 ? " " : pick(a);
	}

	private Object[] casts() {
		if (r.nextInt(4) == 0) {
			return null;
		}
		if (r.nextInt(5) == 0) {
			String t = pick(TABLETS);
			return new Object[]{MagicSpells.fromMenu("Break", t, false), OldMagicSpells.fromMenu("Break", t, false)};
		}
		String target = pick(SPELLS) + (r.nextBoolean() ? " -> " + pick(NAMES) : "");
		boolean onNpc = r.nextBoolean();
		return new Object[]{MagicSpells.fromMenu("Cast", target, onNpc), OldMagicSpells.fromMenu("Cast", target, onNpc)};
	}

	@Test
	public void writeOracle() throws Exception {
		Gson gson = new Gson();
		List<Map<String, Object>> cases = new ArrayList<>();
		for (int n = 0; n < 20000; n++) {
			LiveActivity.Signals s = new LiveActivity.Signals();
			// Each signal is set only now and then, so every branch wins often.
			int from = r.nextInt(11);
			s.raid = from <= 0 && r.nextInt(3) == 0 ? pick(STRINGS) : null;
			s.minigame = from <= 1 && r.nextInt(3) == 0 ? pick(STRINGS) : null;
			s.idle = from <= 2 && r.nextInt(4) == 0;
			s.boss = from <= 3 && r.nextInt(3) == 0 ? pick(STRINGS) : null;
			s.bossId = r.nextInt(4) == 0 ? null : r.nextInt(3) - 1 + r.nextInt(2) * 8000;
			s.slayerTask = from <= 4 ? maybe(TASKS) : null;
			s.slaying = r.nextBoolean();
			s.slayerLeft = r.nextInt(3) == 0 ? 0 : r.nextInt(200);
			s.slayerNpc = maybe(NAMES);
			s.slayerNpcId = r.nextInt(4) == 0 ? null : r.nextInt(3) - 1 + r.nextInt(2) * 400;
			s.farmRoute = from <= 5 && r.nextInt(2) == 0 ? pick(STRINGS) : null;
			s.farmDone = r.nextInt(10);
			s.farmTotal = r.nextInt(3) == 0 ? 0 : r.nextInt(12);
			s.farmItem = maybe(NAMES);
			s.combatNpc = from <= 6 && r.nextInt(2) == 0 ? maybe(NAMES) : null;
			s.combatNpcId = r.nextInt(4) == 0 ? null : r.nextInt(3) - 1 + r.nextInt(2) * 2000;
			s.combatMagic = r.nextBoolean();
			s.combatSpell = maybe(SPELLS);
			Object[] tele = from <= 7 && r.nextInt(3) == 0 ? casts() : null;
			Object[] cast = casts();
			s.skill = from <= 8 ? maybe(SKILLS) : null;
			s.skillItem = maybe(NAMES);
			s.alchs = r.nextInt(3) == 0 ? 0 : r.nextInt(3) == 0 ? 1 : r.nextInt(500);
			s.bankOpen = from <= 9 && r.nextBoolean();
			s.teleport = tele == null ? null : (MagicSpells.Cast) tele[0];
			s.magicCast = cast == null ? null : (MagicSpells.Cast) cast[0];

			OldLiveActivity.Signals o = new OldLiveActivity.Signals();
			for (Field f : LiveActivity.Signals.class.getDeclaredFields()) {
				f.setAccessible(true);
				Field of = OldLiveActivity.Signals.class.getDeclaredField(f.getName());
				of.setAccessible(true);
				if (f.getType() != MagicSpells.Cast.class) {
					of.set(o, f.get(s));
				}
			}
			o.teleport = tele == null ? null : (OldMagicSpells.Cast) tele[1];
			o.magicCast = cast == null ? null : (OldMagicSpells.Cast) cast[1];

			LiveActivity.Choice c = LiveActivity.choose(s);
			OldLiveActivity.Choice old = OldLiveActivity.choose(o);
			if (!c.kind.wire.equals(old.kind.wire) || !String.valueOf(c.npcId).equals(String.valueOf(old.npcId))) {
				throw new AssertionError("kind/npc differ: " + old);
			}
			Map<String, Object> sent = new LinkedHashMap<>();
			sent.put("activity", c.kind.wire);
			sent.put("subject", c.subject);
			sent.put("npc_id", c.npcId);
			sent.put("parts", c.parts);
			Map<String, Object> expected = new LinkedHashMap<>();
			expected.put("subject", old.subject);
			expected.put("detail", old.detail);
			expected.put("icon", old.icon);
			Map<String, Object> one = new LinkedHashMap<>();
			// As the plugin sends it (Gson), and what the old plugin sent.
			one.put("sent", gson.fromJson(gson.toJson(sent), Map.class));
			one.put("expected", expected);
			cases.add(one);
		}
		Path out = Paths.get("build", "oracle", "activity-oracle.json.gz");
		Files.createDirectories(out.getParent());
		try (Writer w = new OutputStreamWriter(new GZIPOutputStream(Files.newOutputStream(out)), StandardCharsets.UTF_8)) {
			new Gson().newBuilder().serializeNulls().create().toJson(cases, w);
		}
	}
}

package com.osrscompanion;

import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

/** What makes a live activity status go out at once (the key) and what waits for the next upload. */
public class LiveActivityStatusKeyTest {
	private static LiveActivityMonitor.Status status(String area, int world, int left) {
		Map<String, Object> parts = new LinkedHashMap<>();
		parts.put("left", left);
		LiveActivity.Choice choice = new LiveActivity.Choice(LiveActivity.Kind.SLAYER, "Abyssal demons", null, parts);
		return new LiveActivityMonitor.Status("Player", "online", choice, 1_000L, world, area, 12345);
	}

	@Test
	public void areaAndWorldChangesGoOutAtOnce() {
		assertNotEquals(status("Catacombs of Kourend", 302, 40).key(), status("Slayer Tower", 302, 40).key());
		assertNotEquals(status("Slayer Tower", 302, 40).key(), status("Slayer Tower", 330, 40).key());
	}

	@Test
	public void countChangesWaitForTheNextUpload() {
		assertEquals(status("Slayer Tower", 302, 40).key(), status("Slayer Tower", 302, 39).key());
	}

	@Test
	public void theHeartbeatIsFiveMinutes() {
		assertEquals(5 * 60_000L, LiveActivityMonitor.HEARTBEAT_MS);
	}
}

package com.osrscompanion;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class LiveActivityTest {
	private static final long NOW = 10_000_000L;

	/** Every signal at once: each step below takes away the winner and checks the next one wins. */
	private static LiveActivity.Signals all() {
		LiveActivity.Signals s = new LiveActivity.Signals();
		s.raid = "Chambers of Xeric";
		s.minigame = "Wintertodt";
		s.boss = "Vorkath";
		s.slayerTask = "blue dragons";
		s.slayerLeft = 12;
		s.slaying = true;
		s.farmRoute = "Herb run";
		s.farmDone = 3;
		s.farmTotal = 9;
		s.combatNpc = "Blue dragon";
		s.skill = "Fishing";
		s.bankOpen = true;
		return s;
	}

	@Test
	public void priorityOrder() {
		LiveActivity.Signals s = all();
		assertEquals(LiveActivity.Kind.RAID, LiveActivity.choose(s).kind);
		s.raid = null;
		assertEquals(LiveActivity.Kind.MINIGAME, LiveActivity.choose(s).kind);
		s.minigame = null;
		LiveActivity.Choice boss = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.BOSS, boss.kind);
		s.boss = null;
		LiveActivity.Choice slayer = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.SLAYER, slayer.kind);
		assertEquals("blue dragons", slayer.subject);
		s.slaying = false;
		LiveActivity.Choice farm = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.FARM_RUN, farm.kind);
		s.farmRoute = null;
		LiveActivity.Choice combat = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.COMBAT, combat.kind);
		s.combatNpc = null;
		assertEquals(LiveActivity.Kind.SKILLING, LiveActivity.choose(s).kind);
		s.skill = null;
		assertEquals(LiveActivity.Kind.BANKING, LiveActivity.choose(s).kind);
		s.bankOpen = false;
		assertEquals(LiveActivity.Kind.OTHER, LiveActivity.choose(s).kind);
	}

	@Test
	public void idleWinsOverAllButRaidsAndMinigames() {
		LiveActivity.Signals s = all();
		s.idle = true;
		assertEquals(LiveActivity.Kind.RAID, LiveActivity.choose(s).kind);
		s.raid = null;
		assertEquals(LiveActivity.Kind.MINIGAME, LiveActivity.choose(s).kind);
		s.minigame = null;
		assertEquals(LiveActivity.Kind.IDLE, LiveActivity.choose(s).kind);
	}

	@Test
	public void sameActivityKeepsItsKeyWhenOnlyCountsChange() {
		LiveActivity.Signals s = all();
		s.raid = null;
		s.minigame = null;
		s.boss = null;
		String before = LiveActivity.choose(s).key();
		s.slayerLeft = 11;
		LiveActivity.Choice after = LiveActivity.choose(s);
		assertEquals(before, after.key());
	}

	@Test
	public void idleAfterFiveMinutesWithoutMovementXpOrAnimation() {
		LiveActivity.IdleTracker t = new LiveActivity.IdleTracker();
		assertFalse(t.isIdle(NOW));
		t.tick(NOW, 3200, 3200, 0, false, false);
		t.tick(NOW + LiveActivity.IDLE_MS - 1, 3200, 3200, 0, false, false);
		assertFalse(t.isIdle(NOW + LiveActivity.IDLE_MS - 1));
		t.tick(NOW + LiveActivity.IDLE_MS, 3200, 3200, 0, false, false);
		assertTrue(t.isIdle(NOW + LiveActivity.IDLE_MS));
		assertEquals(NOW, t.lastActiveMs());
		// Moving ends it.
		t.tick(NOW + LiveActivity.IDLE_MS + 600, 3201, 3200, 0, false, false);
		assertFalse(t.isIdle(NOW + LiveActivity.IDLE_MS + 600));
	}

	@Test
	public void fishingInPlaceIsNotIdle() {
		LiveActivity.IdleTracker t = new LiveActivity.IdleTracker();
		long at = NOW;
		for (int i = 0; i < 1000; i++, at += 600) {
			// Same tile, no animation on most ticks, but XP every 10 ticks.
			t.tick(at, 2600, 3400, 0, false, i % 10 == 0);
		}
		assertFalse(t.isIdle(at));
		LiveActivity.IdleTracker anim = new LiveActivity.IdleTracker();
		at = NOW;
		for (int i = 0; i < 1000; i++, at += 600) {
			anim.tick(at, 2600, 3400, 0, true, false);
		}
		assertFalse(anim.isIdle(at));
	}

	@Test
	public void skillingIsTheLatestNonCombatXpDropWithinAMinute() {
		Map<String, Long> last = new HashMap<>();
		assertNull(LiveActivity.skillingSkill(last, NOW));
		last.put("fishing", NOW - 30_000);
		last.put("cooking", NOW - 10_000);
		assertEquals("cooking", LiveActivity.skillingSkill(last, NOW));
		assertEquals("fishing", LiveActivity.skillingSkill(Collections.singletonMap("fishing", NOW - 60_000), NOW));
		assertNull(LiveActivity.skillingSkill(Collections.singletonMap("fishing", NOW - 60_001), NOW));
	}

	@Test
	public void combatXpIsNotSkilling() {
		assertFalse(LiveActivity.isSkillingXp("hitpoints", false));
		assertFalse(LiveActivity.isSkillingXp("Slayer", false));
		assertFalse(LiveActivity.isSkillingXp("magic", true));
		assertTrue(LiveActivity.isSkillingXp("magic", false));
		assertTrue(LiveActivity.isSkillingXp("woodcutting", true));
		assertFalse(LiveActivity.isSkillingXp(null, false));
	}

	@Test
	public void bossesFromTheListTheSlayerVariantsAndTheCatalog() {
		assertTrue(LiveActivity.isBoss("Vorkath", null));
		assertTrue(LiveActivity.isBoss("alchemical hydra", null));
		assertTrue(LiveActivity.isBoss("Branda the Fire Queen", null));
		assertFalse(LiveActivity.isBoss("Blue dragon", null));
		assertTrue(LiveActivity.isBoss("Some new boss", Collections.singleton("some new boss")));
		assertFalse(LiveActivity.isBoss(null, null));
	}

	@Test
	public void regionTables() {
		assertEquals("Inferno", LiveActivity.MINIGAME_REGIONS.get(9043));
		assertEquals("Tombs of Amascut", LiveActivity.RAID_REGIONS.get(15188));
		assertNull(LiveActivity.RAID_REGIONS.get(12850));
	}

	@Test
	public void changesAreDebouncedAndSpaced() {
		// The first status of a login goes out at once.
		assertTrue(LiveActivityMonitor.shouldSendChange("a", null, "a", NOW, 0, NOW));
		// Unchanged: nothing.
		assertFalse(LiveActivityMonitor.shouldSendChange("a", "a", null, 0, NOW, NOW));
		// Changed, but not held long enough yet.
		assertFalse(LiveActivityMonitor.shouldSendChange("b", "a", "b", NOW, 0, NOW + LiveActivityMonitor.DEBOUNCE_MS - 1));
		assertTrue(LiveActivityMonitor.shouldSendChange("b", "a", "b", NOW, 0, NOW + LiveActivityMonitor.DEBOUNCE_MS));
		// Held, but the last change went out too recently.
		long t = NOW + LiveActivityMonitor.DEBOUNCE_MS;
		assertFalse(LiveActivityMonitor.shouldSendChange("b", "a", "b", NOW, t - 1_000, t));
		assertTrue(LiveActivityMonitor.shouldSendChange("b", "a", "b", NOW, t - LiveActivityMonitor.MIN_CHANGE_GAP_MS, t));
	}

	@Test
	public void magicDetail() {
		LiveActivity.Signals s = new LiveActivity.Signals();
		s.skill = "magic";
		s.magicCast = MagicSpells.fromMenu("Cast", "High Level Alchemy -> Rune platebody", false);
		s.alchs = 37;
		LiveActivity.Choice c = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.SKILLING, c.kind);
		assertEquals("High Level Alchemy", c.subject);
		assertEquals(37, c.parts.get("alchs"));

		// A teleport: Magic stays the subject (one stretch on the website), the place is the detail.
		s.teleport = MagicSpells.fromMenu("Cast", "Varrock Teleport", false);
		c = LiveActivity.choose(s);
		assertEquals("skilling|Magic", c.key());
		s.teleport = MagicSpells.fromMenu("Cast", "Camelot Teleport", false);
		assertEquals("skilling|Magic", LiveActivity.choose(s).key());

		// Magic in a fight: combat on the monster, trained with Magic.
		s.combatNpc = "Hill Giant";
		s.combatMagic = true;
		s.combatSpell = "Fire Strike";
		c = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.COMBAT, c.kind);
		assertEquals("Hill Giant", c.subject);
	}

	@Test
	public void skillingItemAndPictures() {
		LiveActivity.Signals s = new LiveActivity.Signals();
		s.skill = "fishing";
		s.skillItem = "Raw shark";
		LiveActivity.Choice c = LiveActivity.choose(s);
		assertEquals("skilling|fishing", c.key());
		assertEquals("Raw shark", c.parts.get("item"));

		s = new LiveActivity.Signals();
		s.slayerTask = "abyssal demons";
		s.slaying = true;
		s.slayerNpc = "Abyssal demon";
		assertEquals("Abyssal demon", LiveActivity.choose(s).parts.get("npc"));
		s = new LiveActivity.Signals();
		s.farmRoute = "Herb run";
		s.farmItem = "Ranarr weed";
		assertEquals("Ranarr weed", LiveActivity.choose(s).parts.get("item"));
	}

	@Test
	public void npcIdForFights() {
		// Combat: the id of the NPC fought; not part of the key (another version is the same activity).
		LiveActivity.Signals s = new LiveActivity.Signals();
		s.combatNpc = "Hill Giant";
		s.combatNpcId = 2098;
		LiveActivity.Choice c = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.COMBAT, c.kind);
		assertEquals(Integer.valueOf(2098), c.npcId);
		s.combatNpcId = 2099;
		assertEquals(c.key(), LiveActivity.choose(s).key());
		s.combatMagic = true;
		assertEquals(Integer.valueOf(2099), LiveActivity.choose(s).npcId);

		// Slayer: the task monster's id while fighting it; null at the location without a target.
		s = new LiveActivity.Signals();
		s.slayerTask = "abyssal demons";
		s.slaying = true;
		s.combatNpc = "Abyssal demon";
		s.combatNpcId = 415;
		s.slayerNpc = "Abyssal demon";
		s.slayerNpcId = 415;
		c = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.SLAYER, c.kind);
		assertEquals(Integer.valueOf(415), c.npcId);
		s.slayerNpc = null;
		assertNull(LiveActivity.choose(s).npcId);

		// Boss: the boss's id.
		s = new LiveActivity.Signals();
		s.boss = "Vorkath";
		s.bossId = 8061;
		c = LiveActivity.choose(s);
		assertEquals(LiveActivity.Kind.BOSS, c.kind);
		assertEquals(Integer.valueOf(8061), c.npcId);

		// Other kinds never carry one.
		s.boss = null;
		s.skill = "fishing";
		assertNull(LiveActivity.choose(s).npcId);
		s.skill = null;
		s.combatNpc = null;
		assertNull(LiveActivity.choose(s).npcId);
	}

	@Test
	public void npcIdPrefersTransformed() {
		assertEquals(Integer.valueOf(8061), LiveActivity.npcId(8059, 8061));
		assertEquals(Integer.valueOf(8059), LiveActivity.npcId(8059, null));
		assertEquals(Integer.valueOf(8059), LiveActivity.npcId(8059, -1));
		assertNull(LiveActivity.npcId(-1, null));
	}
}

package com.osrscompanion;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
