package com.osrscompanion;

// The plugin's ChargesPluginBridge before the website kept the storage items: the reference for StorageEventsOracleTest.

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BiFunction;

/**
 * Reads the storage state the community "Charges Improved" plugin
 * (config group {@code tictac7x-charges}) keeps for the same storage items
 * we infer. When a player runs it, its state is exact and battle-tested,
 * so it overrides our own inference: read once at login and again on every
 * change it writes. Read-only: the plugin hub forbids writing to another
 * plugin's config group.
 */
final class OldChargesPluginBridge {
	static final String CONFIG_GROUP = "tictac7x-charges";
	static final String STORAGE_SUFFIX = "_storage";

	/** Their config key (without the suffix) to our bank-memory source. Several keys fold into one source. */
	static final Map<String, String> SOURCE_BY_KEY;

	static {
		Map<String, String> m = new LinkedHashMap<>();
		m.put("fish_barrel", "fish_barrel");
		m.put("herb_sack", "herb_sack");
		m.put("silklined_herb_sack", "herb_sack");
		m.put("log_basket", "log_basket");
		m.put("forestry_basket", "log_basket");
		m.put("gem_bag", "gem_bag");
		m.put("gem_pouch", "gem_bag");
		m.put("gem_satchel", "gem_bag");
		m.put("gem_tote", "gem_bag");
		m.put("gem_sack", "gem_bag");
		m.put("coal_bag", "coal_bag");
		SOURCE_BY_KEY = Collections.unmodifiableMap(m);
	}

	private OldChargesPluginBridge() {
	}

	/** Our source for one of their config keys ({@code fish_barrel_storage}), or null when not one we mirror. */
	static String sourceForConfigKey(String key) {
		if (key == null || !key.endsWith(STORAGE_SUFFIX)) {
			return null;
		}
		return SOURCE_BY_KEY.get(key.substring(0, key.length() - STORAGE_SUFFIX.length()));
	}

	/** Their JSON ({@code [{"itemId":13439,"quantity":5}]}) to item id to quantity; null when absent or malformed. */
	static Map<Integer, Integer> parse(String json) {
		if (json == null || json.isBlank()) {
			return null;
		}
		try {
			JsonElement root = new JsonParser().parse(json);
			if (!root.isJsonArray()) {
				return null;
			}
			Map<Integer, Integer> contents = new LinkedHashMap<>();
			for (JsonElement e : (JsonArray) root) {
				if (!e.isJsonObject()) {
					continue;
				}
				JsonObject o = e.getAsJsonObject();
				if (!o.has("itemId") || !o.has("quantity")) {
					continue;
				}
				int qty = o.get("quantity").getAsInt();
				if (qty > 0) {
					contents.merge(o.get("itemId").getAsInt(), qty, Integer::sum);
				}
			}
			return contents;
		} catch (RuntimeException ex) {
			return null;
		}
	}

	/**
	 * Every mirrored source's contents as their plugin has them, summing the
	 * keys that fold into one source. Sources with no stored value at all are
	 * left out (their plugin is not installed, or never tracked that item).
	 */
	static Map<String, Map<Integer, Integer>> readAll(BiFunction<String, String, String> config) {
		Map<String, Map<Integer, Integer>> bySource = new LinkedHashMap<>();
		for (Map.Entry<String, String> e : SOURCE_BY_KEY.entrySet()) {
			Map<Integer, Integer> contents = parse(config.apply(CONFIG_GROUP, e.getKey() + STORAGE_SUFFIX));
			if (contents == null) {
				continue;
			}
			Map<Integer, Integer> merged = bySource.computeIfAbsent(e.getValue(), s -> new LinkedHashMap<>());
			contents.forEach((id, qty) -> merged.merge(id, qty, Integer::sum));
		}
		return bySource;
	}

	/** The config keys that fold into a source. */
	static List<String> keysFor(String source) {
		List<String> keys = new java.util.ArrayList<>();
		for (Map.Entry<String, String> e : SOURCE_BY_KEY.entrySet()) {
			if (e.getValue().equals(source)) {
				keys.add(e.getKey() + STORAGE_SUFFIX);
			}
		}
		return keys;
	}
}

package com.osrscompanion;

// The plugin's LiveActivity before the website wrote the texts: the reference for LiveActivityOracleTest.

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Live activity, the pure part: which activity the player is doing (from signals the
 * {@link LiveActivityMonitor} reads each tick), when they count as idle, and the region tables for raids
 * and minigames. No game access, so it is unit tested.
 *
 * <p>Priority, first match wins: raid or minigame, boss fight, slayer task, guided farm run, combat with
 * an NPC, skilling (an XP drop in the last minute), banking, then "other" (playing, nothing of the above).
 * Idle (no movement, XP or animation for five minutes) wins over everything but a raid or minigame: a
 * guide or a bank left open while away is not an activity.
 */
final class OldLiveActivity {
	private OldLiveActivity() {
	}

	/** No movement, XP or animation for this long: idle. */
	static final long IDLE_MS = 5 * 60_000L;
	/** A skill whose XP went up this recently is what you are training. */
	static final long SKILLING_WINDOW_MS = 60_000L;
	/** Still "in combat" this long after the last attack (between kills, a missed click...). */
	static final long COMBAT_GRACE_MS = 20_000L;
	/** Still at the boss this long after the last attack on it, while in the same map region (between kills). */
	static final long BOSS_GRACE_MS = 90_000L;
	/** A teleport stays the detail this long (a short event: no segment of its own on the website). */
	static final long TELEPORT_SHOW_MS = 60_000L;

	/** The activity kinds the website knows (CharacterActivity.activity). */
	enum Kind {
		RAID("raid"),
		MINIGAME("minigame"),
		BOSS("boss"),
		SLAYER("slayer"),
		FARM_RUN("farm_run"),
		COMBAT("combat"),
		SKILLING("skilling"),
		BANKING("banking"),
		/** Logged in and active, but none of the above (walking, talking, questing...). */
		OTHER("other"),
		IDLE("idle");

		final String wire;

		Kind(String wire) {
			this.wire = wire;
		}
	}

	/** What the monitor saw this tick; null / 0 / false where it saw nothing. */
	static final class Signals {
		String raid;
		String minigame;
		String boss;
		/** The boss NPC's id (the transformed composition's for NPCs that transform), or null. */
		Integer bossId;
		String slayerTask;
		int slayerLeft;
		/** At a task location or fighting the task's monster. */
		boolean slaying;
		String farmRoute;
		int farmDone;
		int farmTotal;
		String combatNpc;
		/** The id of the NPC being fought (the transformed composition's for NPCs that transform), or null. */
		Integer combatNpcId;
		/** Magic XP came with the Hitpoints XP lately: the fight is trained with Magic. */
		boolean combatMagic;
		/** The offensive spell last cast, when known (not with autocast). */
		String combatSpell;
		/** The slayer monster being fought ("Abyssal demon"), for its picture. */
		String slayerNpc;
		/** The id of {@link #slayerNpc}, or null. */
		Integer slayerNpcId;
		/** The farm run's picture: the route's most planted crop ("Ranarr weed"). */
		String farmItem;
		String skill;
		/** The item the skill last gave ("Raw shark", "Gold ring"), when known. */
		String skillItem;
		/** The Magic cast behind the latest Magic XP (an alch, Superheat...), when the skill is Magic. */
		OldMagicSpells.Cast magicCast;
		/** High / Low Level Alchemy casts this login. */
		int alchs;
		/** A teleport in the last {@link #TELEPORT_SHOW_MS}, newer than other skilling. */
		OldMagicSpells.Cast teleport;
		boolean bankOpen;
		boolean idle;
	}

	/**
	 * The chosen activity: its kind, what it is about (same subject = same activity), the text shown and
	 * a picture hint: the wiki file of the thing involved ("Raw shark.png", "Varrock Teleport.png"), or null.
	 * For combat, slayer and boss activities also the id of the NPC fought (for its exact picture), or null.
	 * The NPC id is not part of the key: another version of the same monster is the same activity.
	 */
	static final class Choice {
		final Kind kind;
		final String subject;
		final String detail;
		final String icon;
		final Integer npcId;

		Choice(Kind kind, String subject, String detail) {
			this(kind, subject, detail, null);
		}

		Choice(Kind kind, String subject, String detail, String icon) {
			this(kind, subject, detail, icon, null);
		}

		Choice(Kind kind, String subject, String detail, String icon, Integer npcId) {
			this.kind = kind;
			this.subject = subject;
			this.detail = detail;
			this.icon = icon;
			this.npcId = npcId;
		}

		/** Two choices with the same key are the same activity (only counts like "12 left" differ). */
		String key() {
			return kind.wire + "|" + (subject == null ? "" : subject);
		}

		@Override
		public String toString() {
			return key() + " (" + detail + ")";
		}
	}

	/** The activity for these signals (see the class comment for the order). */
	static Choice choose(Signals s) {
		if (notBlank(s.raid)) {
			return new Choice(Kind.RAID, s.raid, s.raid);
		}
		if (notBlank(s.minigame)) {
			return new Choice(Kind.MINIGAME, s.minigame, s.minigame);
		}
		if (s.idle) {
			return new Choice(Kind.IDLE, null, "Idle");
		}
		if (notBlank(s.boss)) {
			return new Choice(Kind.BOSS, s.boss, s.boss, null, positive(s.bossId));
		}
		if (s.slaying && notBlank(s.slayerTask)) {
			String task = capitalize(s.slayerTask);
			return new Choice(Kind.SLAYER, task, task + (s.slayerLeft > 0 ? " · " + s.slayerLeft + " left" : ""),
				notBlank(s.slayerNpc) ? OldMagicSpells.wikiFile(s.slayerNpc) : null,
				notBlank(s.slayerNpc) ? positive(s.slayerNpcId) : null);
		}
		if (notBlank(s.farmRoute)) {
			return new Choice(Kind.FARM_RUN, s.farmRoute,
				s.farmRoute + (s.farmTotal > 0 ? " · " + s.farmDone + "/" + s.farmTotal + " patches" : ""),
				notBlank(s.farmItem) ? OldMagicSpells.wikiFile(s.farmItem) : null);
		}
		if (notBlank(s.combatNpc)) {
			if (s.combatMagic) {
				return new Choice(Kind.COMBAT, s.combatNpc,
					"Training Magic on " + s.combatNpc + (notBlank(s.combatSpell) ? " · " + s.combatSpell : ""),
					OldMagicSpells.spellIcon(s.combatSpell), positive(s.combatNpcId));
			}
			return new Choice(Kind.COMBAT, s.combatNpc, s.combatNpc, null, positive(s.combatNpcId));
		}
		if (s.teleport != null) {
			// The Magic skill as subject: teleport after teleport stays one stretch of Magic on the website.
			return new Choice(Kind.SKILLING, "Magic", s.teleport.text(), s.teleport.icon());
		}
		if (notBlank(s.skill)) {
			String skill = capitalize(s.skill);
			if (s.magicCast != null && "magic".equalsIgnoreCase(s.skill)) {
				return magicChoice(s.magicCast, s.alchs);
			}
			return notBlank(s.skillItem)
				? new Choice(Kind.SKILLING, skill, skill + " · " + s.skillItem, OldMagicSpells.wikiFile(s.skillItem))
				: new Choice(Kind.SKILLING, skill, skill);
		}
		if (s.bankOpen) {
			return new Choice(Kind.BANKING, null, "Banking");
		}
		return new Choice(Kind.OTHER, null, "Playing");
	}

	/** Skilling Magic with a known cast: the spell as subject, "High alching Rune platebody · 37 alchs" as detail. */
	static Choice magicChoice(OldMagicSpells.Cast cast, int alchs) {
		boolean alch = cast.type == OldMagicSpells.Type.HIGH_ALCH || cast.type == OldMagicSpells.Type.LOW_ALCH;
		String text = cast.text() + (alch && alchs > 0 ? " · " + alchs + (alchs == 1 ? " alch" : " alchs") : "");
		return new Choice(Kind.SKILLING, cast.spell, text, cast.icon());
	}

	// ---- Idle ---------------------------------------------------------------------------------

	/**
	 * Idle: the local player's tile, XP and animation unchanged for {@link #IDLE_MS}. Someone fishing in
	 * place still gains XP (and animates), so they are not idle. Client thread only.
	 */
	static final class IdleTracker {
		private long lastActiveMs = -1;
		private int x = Integer.MIN_VALUE;
		private int y;
		private int plane;

		/** One tick: where the player stands, whether they animate and whether any XP went up. */
		void tick(long nowMs, int x, int y, int plane, boolean animating, boolean xpGained) {
			boolean moved = x != this.x || y != this.y || plane != this.plane;
			this.x = x;
			this.y = y;
			this.plane = plane;
			if (lastActiveMs < 0 || moved || animating || xpGained) {
				lastActiveMs = nowMs;
			}
		}

		boolean isIdle(long nowMs) {
			return lastActiveMs >= 0 && nowMs - lastActiveMs >= IDLE_MS;
		}

		/** When the player last did something (moved, animated, gained XP); -1 before the first tick. */
		long lastActiveMs() {
			return lastActiveMs;
		}

		void reset() {
			lastActiveMs = -1;
			x = Integer.MIN_VALUE;
		}
	}

	// ---- Skilling -----------------------------------------------------------------------------

	/** Skills whose XP comes from fighting: never "skilling" (combat is detected on its own). */
	private static final Set<String> COMBAT_ONLY = new HashSet<>(Arrays.asList("hitpoints", "slayer"));
	/** Skills that count as skilling only when no Hitpoints XP came in the same tick (alching, chinning...). */
	private static final Set<String> COMBAT_STYLE = new HashSet<>(Arrays.asList("attack", "strength", "defence", "ranged", "magic"));

	/**
	 * Whether an XP drop in this skill is skilling: not Hitpoints or Slayer, and a combat style only when
	 * no Hitpoints XP came with it (a spell cast on a monster gives both).
	 */
	static boolean isSkillingXp(String skill, boolean hitpointsXpSameTick) {
		String k = skill == null ? "" : skill.toLowerCase(Locale.ROOT);
		if (k.isEmpty() || COMBAT_ONLY.contains(k)) {
			return false;
		}
		return !COMBAT_STYLE.contains(k) || !hitpointsXpSameTick;
	}

	/** The skill with the latest skilling XP drop within {@link #SKILLING_WINDOW_MS}, or null. */
	static String skillingSkill(Map<String, Long> lastSkillingXpMs, long nowMs) {
		String best = null;
		long bestAt = Long.MIN_VALUE;
		for (Map.Entry<String, Long> e : lastSkillingXpMs.entrySet()) {
			long at = e.getValue();
			if (nowMs - at <= SKILLING_WINDOW_MS && at > bestAt) {
				best = e.getKey();
				bestAt = at;
			}
		}
		return best;
	}

	// ---- Raids, minigames and bosses ------------------------------------------------------------

	/** Map region (the template region inside instances) -> raid name. Chambers of Xeric and the Theatre also go by varbit. */
	static final Map<Integer, String> RAID_REGIONS;
	/** Map region -> minigame name. The Gauntlet goes by varbit. */
	static final Map<Integer, String> MINIGAME_REGIONS;

	static {
		Map<Integer, String> raids = new HashMap<>();
		for (int r : new int[]{14160, 15698, 15700, 14162, 14164, 14674, 14676, 15186, 15188, 15184, 15696, 14672}) {
			raids.put(r, "Tombs of Amascut");
		}
		for (int r : new int[]{12613, 13125, 13122, 13123, 13379, 12611}) {
			raids.put(r, "Theatre of Blood");
		}
		RAID_REGIONS = Collections.unmodifiableMap(raids);

		Map<Integer, String> games = new HashMap<>();
		games.put(9043, "Inferno");
		games.put(9551, "Fight Caves");
		games.put(7216, "Fortis Colosseum");
		games.put(14484, "Guardians of the Rift");
		games.put(12078, "Tempoross");
		games.put(6462, "Wintertodt");
		games.put(12126, "Zalcano");
		games.put(9033, "Nightmare Zone");
		games.put(10536, "Pest Control");
		games.put(13491, "Giants' Foundry");
		games.put(14231, "Barrows");
		games.put(7512, "The Gauntlet");
		games.put(7768, "The Corrupted Gauntlet");
		MINIGAME_REGIONS = Collections.unmodifiableMap(games);
	}

	/** Boss NPC names (lower case), besides the slayer boss variants and the boss gear catalog. */
	private static final Set<String> BOSSES = new HashSet<>(Arrays.asList(
		"abyssal sire", "alchemical hydra", "amoxliatl", "araxxor", "artio", "branda the fire queen", "bryophyta",
		"callisto", "calvar'ion", "cerberus", "chaos elemental", "chaos fanatic", "commander zilyana", "corporeal beast",
		"crazy archaeologist", "dagannoth prime", "dagannoth rex", "dagannoth supreme", "dawn", "deranged archaeologist",
		"doom of mokhaiotl", "duke sucellus", "dusk", "eldric the ice king", "general graardor", "giant mole", "hespori",
		"k'ril tsutsaroth", "kalphite queen", "king black dragon", "kraken", "kree'arra", "nex", "obor",
		"phantom muspah", "phosani's nightmare", "sarachnis", "scorpia", "scurrius", "shellbane gryphon", "skotizo",
		"sol heredit", "spindel", "the hueycoatl", "the leviathan", "the nightmare", "the whisperer",
		"thermonuclear smoke devil", "tztok-jad", "tzkal-zuk", "vardorvis", "venenatis", "vet'ion", "vorkath", "yama",
		"zulrah"));

	static {
		for (java.util.List<String> names : SlayerBosses.BOSSES.values()) {
			for (String n : names) {
				BOSSES.add(n.toLowerCase(Locale.ROOT));
			}
		}
	}

	/** Whether an NPC is a boss: the list above (with the slayer boss variants) or one of {@code extra} (lower case). */
	static boolean isBoss(String npcName, Set<String> extra) {
		if (npcName == null) {
			return false;
		}
		String n = npcName.trim().toLowerCase(Locale.ROOT);
		return !n.isEmpty() && (BOSSES.contains(n) || extra != null && extra.contains(n));
	}

	// ---- Helpers ------------------------------------------------------------------------------

	/**
	 * The id of the NPC being fought: the transformed composition's id when the NPC transforms (a
	 * multiloc NPC), else its own id. Null when neither is a real id.
	 */
	static Integer npcId(int id, Integer transformedId) {
		if (transformedId != null && transformedId > 0) {
			return transformedId;
		}
		return id > 0 ? id : null;
	}

	private static Integer positive(Integer id) {
		return id != null && id > 0 ? id : null;
	}

	static boolean notBlank(String s) {
		return s != null && !s.trim().isEmpty();
	}

	/** "abyssal demons" -> "Abyssal demons"; "FISHING" stays as the game names skills ("Fishing"). */
	static String capitalize(String s) {
		if (s == null || s.isEmpty()) {
			return s;
		}
		String t = s.trim();
		if (t.equals(t.toUpperCase(Locale.ROOT))) {
			t = t.toLowerCase(Locale.ROOT);
		}
		return Character.toUpperCase(t.charAt(0)) + t.substring(1);
	}
}

package com.osrscompanion;

// The plugin's MagicSpells before the website wrote the texts: the reference for LiveActivityOracleTest.

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Magic for live activity, the pure part: what a "Cast" (or a tablet's "Break") menu click was, and the
 * text and wiki icon the website shows for it ("Teleported to Varrock", "High alching Rune platebody",
 * "Training Magic on Hill Giant", "Casting Superheat Item"). No game access, so it is unit tested.
 */
final class OldMagicSpells {
	private OldMagicSpells() {
	}

	/** What a spell does, for the text shown. */
	enum Type {
		TELEPORT,
		HIGH_ALCH,
		LOW_ALCH,
		OFFENSIVE,
		UTILITY
	}

	/** One cast: the spell, what it was cast on (an item or NPC name, or null) and what it does. */
	static final class Cast {
		final String spell;
		final String target;
		final Type type;
		/** A teleport tablet ("Varrock teleport", option "Break"): no Magic XP comes with it. */
		final boolean tablet;

		Cast(String spell, String target, Type type, boolean tablet) {
			this.spell = spell;
			this.target = target;
			this.type = type;
			this.tablet = tablet;
		}

		/** "Teleported to Varrock", "High alching Rune platebody", "Training Magic on Hill Giant", "Casting Humidify". */
		String text() {
			switch (type) {
				case TELEPORT:
					return "Teleported to " + teleportPlace(spell);
				case HIGH_ALCH:
					return target == null ? "High alching" : "High alching " + target;
				case LOW_ALCH:
					return target == null ? "Low alching" : "Low alching " + target;
				case OFFENSIVE:
					return target == null ? "Training Magic · " + spell : "Training Magic on " + target;
				default:
					return "Casting " + spell;
			}
		}

		/** The wiki file that pictures this cast: the alched item, else the spell (or tablet). */
		String icon() {
			if ((type == Type.HIGH_ALCH || type == Type.LOW_ALCH) && target != null) {
				return wikiFile(target);
			}
			return tablet ? wikiFile(spell + " (tablet)") : spellIcon(spell);
		}
	}

	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	/** "Hill Giant  (level-28)" -> "Hill Giant". */
	private static final Pattern LEVEL = Pattern.compile("\\s*\\((level|skill)-\\d+\\)\\s*$", Pattern.CASE_INSENSITIVE);

	/** Offensive spells by exact name (lower case), besides the elemental and Ancient patterns below. */
	private static final Set<String> OFFENSIVE = new HashSet<>(Arrays.asList(
		"crumble undead", "iban blast", "magic dart", "saradomin strike", "claws of guthix", "flames of zamorak",
		"confuse", "weaken", "curse", "bind", "snare", "entangle", "vulnerability", "enfeeble", "stun", "tele block",
		"inferior demonbane", "superior demonbane", "dark demonbane", "ghostly grasp", "skeletal grasp", "undead grasp",
		"corruption", "lesser corruption", "greater corruption"));
	private static final Pattern ELEMENTAL = Pattern.compile("^(wind|water|earth|fire) (strike|bolt|blast|wave|surge)$");
	private static final Pattern ANCIENT = Pattern.compile("^(smoke|shadow|blood|ice) (rush|burst|blitz|barrage)$");

	/**
	 * Teleport destinations whose spell name doesn't simply say it (lower case spell -> place). Anything
	 * else named "X Teleport", "Teleport to X" or "Tele Group X" goes to X.
	 */
	private static final Map<String, String> PLACES;

	static {
		Map<String, String> p = new HashMap<>();
		p.put("teleport to house", "your house");
		p.put("watchtower teleport", "the Watchtower");
		p.put("ape atoll teleport", "Ape Atoll");
		p.put("ape atoll teleport (arceuus)", "Ape Atoll");
		// Ancient Magicks.
		p.put("paddewwa teleport", "Paddewwa (Edgeville Dungeon)");
		p.put("senntisten teleport", "Senntisten (Digsite)");
		p.put("kharyrll teleport", "Kharyrll (Canifis)");
		p.put("lassar teleport", "Lassar (Ice Mountain)");
		p.put("dareeyak teleport", "Dareeyak (Wilderness)");
		p.put("carrallanger teleport", "Carrallanger (Graveyard of Shadows)");
		p.put("annakarl teleport", "Annakarl (Demonic Ruins)");
		p.put("ghorrock teleport", "Ghorrock (Frozen Waste Plateau)");
		// Lunar.
		p.put("moonclan teleport", "Moonclan (Lunar Isle)");
		p.put("ourania teleport", "Ourania (ZMI altar)");
		p.put("waterbirth teleport", "Waterbirth Island");
		p.put("barbarian teleport", "the Barbarian Outpost");
		p.put("khazard teleport", "Port Khazard");
		p.put("fishing guild teleport", "the Fishing Guild");
		p.put("ice plateau teleport", "the Ice Plateau");
		// Arceuus.
		p.put("arceuus library teleport", "the Arceuus Library");
		p.put("mind altar teleport", "the Mind Altar");
		p.put("respawn teleport", "your respawn point");
		p.put("cemetery teleport", "the Forgotten Cemetery");
		p.put("barrows teleport", "Barrows");
		// Home teleports.
		p.put("lumbridge home teleport", "Lumbridge");
		p.put("edgeville home teleport", "Edgeville");
		p.put("lunar home teleport", "Lunar Isle");
		p.put("arceuus home teleport", "Arceuus");
		p.put("civitas illa fortis home teleport", "Civitas illa Fortis");
		p.put("teleport to target", "your target");
		PLACES = Collections.unmodifiableMap(p);
	}

	/** Spell icons on the wiki that aren't "<Spell>.png". */
	private static final Map<String, String> ICONS;

	static {
		Map<String, String> i = new HashMap<>();
		i.put("ape atoll teleport", "Ape Atoll Teleport (standard).png");
		ICONS = Collections.unmodifiableMap(i);
	}

	/** Menu text without colour tags and the trailing level: "<col=ff9040>Rune platebody</col>" -> "Rune platebody". */
	static String clean(String s) {
		if (s == null) {
			return null;
		}
		String t = LEVEL.matcher(TAGS.matcher(s).replaceAll("")).replaceAll("").replace(' ', ' ').trim();
		return t.isEmpty() ? null : t;
	}

	/**
	 * The cast a menu click is, or null: option "Cast" with the target "Spell" or "Spell -> item / NPC"
	 * (the spell widget's own click, or using a selected spell on something), or "Break" on a teleport tablet.
	 * {@code onNpc}: the click targets an NPC.
	 */
	static Cast fromMenu(String option, String target, boolean onNpc) {
		String opt = clean(option);
		String tgt = clean(target);
		if (opt == null || tgt == null) {
			return null;
		}
		if (opt.equalsIgnoreCase("Break") && tgt.toLowerCase(Locale.ROOT).contains("teleport")) {
			return new Cast(tgt, null, Type.TELEPORT, true);
		}
		if (!opt.equalsIgnoreCase("Cast")) {
			return null;
		}
		String spell = tgt;
		String on = null;
		int arrow = tgt.indexOf("->");
		if (arrow >= 0) {
			spell = clean(tgt.substring(0, arrow));
			on = clean(tgt.substring(arrow + 2));
		}
		if (spell == null) {
			return null;
		}
		return new Cast(spell, on, typeOf(spell, onNpc), false);
	}

	/** What a spell does: by its name; a spell not otherwise known that is cast on an NPC is offensive. */
	static Type typeOf(String spell, boolean onNpc) {
		String s = spell == null ? "" : spell.trim().toLowerCase(Locale.ROOT);
		if (s.equals("high level alchemy")) {
			return Type.HIGH_ALCH;
		}
		if (s.equals("low level alchemy")) {
			return Type.LOW_ALCH;
		}
		if (isTeleport(s)) {
			return Type.TELEPORT;
		}
		if (OFFENSIVE.contains(s) || ELEMENTAL.matcher(s).matches() || ANCIENT.matcher(s).matches()) {
			return Type.OFFENSIVE;
		}
		// Utility spells cast on monsters (Monster Examine, Dark Lure...) aren't attacks.
		if (onNpc && !s.equals("monster examine") && !s.equals("dark lure") && !s.startsWith("resurrect")) {
			return Type.OFFENSIVE;
		}
		return Type.UTILITY;
	}

	/** A spell (or tablet) that moves you: "... Teleport", "Teleport to ...", "Tele Group ..."; not Tele Block or Teleport Other. */
	static boolean isTeleport(String spellLower) {
		String s = spellLower == null ? "" : spellLower.trim().toLowerCase(Locale.ROOT);
		if (s.isEmpty() || s.equals("tele block") || s.startsWith("teleport other") || s.equals("telekinetic grab")) {
			return false;
		}
		return s.endsWith(" teleport") || s.contains(" teleport (") || s.startsWith("teleport to ") || s.startsWith("tele group ");
	}

	/** "Varrock Teleport" -> "Varrock", "Teleport to House" -> "your house", "Kharyrll Teleport" -> "Kharyrll (Canifis)". */
	static String teleportPlace(String spell) {
		String s = spell == null ? "" : spell.trim();
		String lower = s.toLowerCase(Locale.ROOT);
		if (lower.startsWith("tele group ")) {
			return teleportPlace(s.substring("tele group ".length()) + " Teleport");
		}
		String known = PLACES.get(lower);
		if (known != null) {
			return known;
		}
		String place = s;
		if (lower.startsWith("teleport to ")) {
			place = s.substring("teleport to ".length());
		} else if (lower.endsWith(" teleport")) {
			place = s.substring(0, s.length() - " teleport".length());
		}
		place = place.trim();
		if (place.isEmpty()) {
			return "somewhere";
		}
		// Tablets are named in lower case ("Kourend castle teleport"): the place keeps its first capital.
		return Character.toUpperCase(place.charAt(0)) + place.substring(1);
	}

	/** The wiki's icon file for a spell: "<Spell>.png", with the few exceptions in {@link #ICONS}. */
	static String spellIcon(String spell) {
		if (spell == null || spell.trim().isEmpty()) {
			return "Magic icon.png";
		}
		String s = spell.trim();
		if (s.toLowerCase(Locale.ROOT).startsWith("tele group ")) {
			return wikiFile(s);
		}
		String exception = ICONS.get(s.toLowerCase(Locale.ROOT));
		return exception != null ? exception : wikiFile(s);
	}

	/** "Rune platebody" -> "Rune platebody.png". */
	static String wikiFile(String name) {
		return name.trim() + ".png";
	}
}

