package com.osrscompanion;

import java.util.concurrent.TimeUnit;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ReconcileSchedulerTest {
	private final FakeScheduledExecutorService executor = new FakeScheduledExecutorService();
	private int refreshes;
	private final ReconcileScheduler scheduler =
			new ReconcileScheduler(executor, () -> refreshes++, () -> executor.nowMs);

	@Test
	public void requestsDebounceToTheLastOne() {
		scheduler.request(10);
		scheduler.request(10);
		scheduler.request(10);
		assertEquals(1, executor.liveTasks().size());
		executor.runDue(TimeUnit.SECONDS.toMillis(10));
		assertEquals(1, refreshes);
		assertTrue(executor.liveTasks().isEmpty());
	}

	@Test
	public void periodicIsIdempotentAndRepeats() {
		scheduler.startPeriodic();
		scheduler.startPeriodic();
		assertEquals(1, executor.liveTasks().size());
		executor.runDue(TimeUnit.MINUTES.toMillis(ReconcileScheduler.PERIODIC_MINUTES));
		executor.runDue(TimeUnit.MINUTES.toMillis(ReconcileScheduler.PERIODIC_MINUTES * 2));
		assertEquals(2, refreshes);
	}

	@Test
	public void stopCancelsEverything() {
		scheduler.startPeriodic();
		scheduler.request(5);
		scheduler.stop();
		executor.runDue(TimeUnit.HOURS.toMillis(1));
		assertEquals(0, refreshes);
	}

	@Test
	public void busyDefersOnceThenRuns() {
		assertTrue(scheduler.markInFlight());
		scheduler.request(1);
		executor.runDue(TimeUnit.SECONDS.toMillis(1));
		assertEquals(0, refreshes);
		assertEquals(1, executor.liveTasks().size());
		scheduler.clearInFlight();
		executor.runDue(TimeUnit.SECONDS.toMillis(1 + ReconcileScheduler.RETRY_WHEN_BUSY_SECONDS));
		assertEquals(1, refreshes);
	}

	@Test
	public void busyWhilePendingOrInFlight() {
		assertFalse(scheduler.isBusy());
		scheduler.request(10);
		assertTrue(scheduler.isBusy());
		assertTrue(scheduler.markInFlight());
		executor.runDue(TimeUnit.SECONDS.toMillis(10));
		assertTrue(scheduler.isBusy());
		scheduler.clearInFlight();
		executor.runDue(TimeUnit.SECONDS.toMillis(10 + ReconcileScheduler.RETRY_WHEN_BUSY_SECONDS));
		assertFalse(scheduler.isBusy());
	}

	@Test
	public void readsAreAtLeastTheMinimumIntervalApart() {
		scheduler.request(10);
		executor.runDue(TimeUnit.SECONDS.toMillis(10));
		assertEquals(1, refreshes);

		// An upload 5 s after that read would re-read at 15 s; it waits for 70 s.
		executor.runDue(TimeUnit.SECONDS.toMillis(15));
		scheduler.request(10);
		executor.runDue(TimeUnit.SECONDS.toMillis(69));
		assertEquals(1, refreshes);
		executor.runDue(TimeUnit.SECONDS.toMillis(70));
		assertEquals(2, refreshes);
	}

	@Test
	public void manyUploadsInAMinuteCollapseIntoOneRead() {
		scheduler.request(10);
		executor.runDue(TimeUnit.SECONDS.toMillis(10));
		for (int second = 20; second <= 60; second += 10) {
			executor.runDue(TimeUnit.SECONDS.toMillis(second));
			scheduler.request(10);
		}
		executor.runDue(TimeUnit.SECONDS.toMillis(80));
		assertEquals(2, refreshes);
		assertTrue(executor.liveTasks().isEmpty());
	}

	@Test
	public void periodicReadSupersedesAPendingRequest() {
		scheduler.startPeriodic();
		long periodMs = TimeUnit.MINUTES.toMillis(ReconcileScheduler.PERIODIC_MINUTES);
		executor.runDue(periodMs - TimeUnit.SECONDS.toMillis(5));
		scheduler.request(10);
		executor.runDue(periodMs);
		assertEquals(1, refreshes);
		assertFalse(scheduler.isBusy());

		// The superseded request never fires on its own later.
		executor.runDue(periodMs + TimeUnit.MINUTES.toMillis(2));
		assertEquals(1, refreshes);
	}

	@Test
	public void stopForgetsTheLastRead() {
		scheduler.request(0);
		executor.runDue(0);
		scheduler.stop();
		scheduler.request(1);
		executor.runDue(TimeUnit.SECONDS.toMillis(1));
		assertEquals(2, refreshes);
	}

	@Test
	public void syncingHintOnlyWhenTheReadIsClose() {
		scheduler.request(10);
		assertTrue(scheduler.isSyncingSoon());
		executor.runDue(TimeUnit.SECONDS.toMillis(10));

		// Held back by the minimum interval: due at 70 s, so no hint yet at 20 s.
		executor.runDue(TimeUnit.SECONDS.toMillis(20));
		scheduler.request(10);
		assertTrue(scheduler.isBusy());
		assertFalse(scheduler.isSyncingSoon());

		executor.runDue(TimeUnit.SECONDS.toMillis(70 - ReconcileScheduler.SYNCING_HINT_SECONDS));
		assertTrue(scheduler.isSyncingSoon());
	}

	@Test
	public void syncingHintWhileInFlight() {
		assertFalse(scheduler.isSyncingSoon());
		assertTrue(scheduler.markInFlight());
		assertTrue(scheduler.isSyncingSoon());
		scheduler.clearInFlight();
		assertFalse(scheduler.isSyncingSoon());
	}
}

package com.osrscompanion;

import java.awt.Color;
import java.awt.Composite;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GraphicsConfiguration;
import java.awt.Image;
import java.awt.Paint;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.font.FontRenderContext;
import java.awt.font.GlyphVector;
import java.awt.geom.AffineTransform;
import java.awt.geom.PathIterator;
import java.awt.image.BufferedImage;
import java.awt.image.BufferedImageOp;
import java.awt.image.ImageObserver;
import java.awt.image.RenderedImage;
import java.awt.image.renderable.RenderableImage;
import java.text.AttributedCharacterIterator;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Draws onto a real image and writes every drawing call to a log: the text with its position, font and
 * colour, every shape and every image with where it went. Two renders with the same log are pixel-identical
 * on any machine, which is what the UI golden tests compare (the PNG is only for looking at).
 */
public final class RecordingGraphics extends Graphics2D {
	private final Graphics2D g;
	private final List<String> log;
	private final ImageNames images;

	public RecordingGraphics(Graphics2D delegate, List<String> log, ImageNames images) {
		this.g = delegate;
		this.log = log;
		this.images = images;
	}

	/** Gives drawn images a stable name for the log (fake item icons are named by the test kit). */
	public interface ImageNames {
		String name(Image image);
	}

	// ---- logging ---------------------------------------------------------------------------------

	private void rec(String what) {
		AffineTransform t = g.getTransform();
		StringBuilder sb = new StringBuilder(what);
		if (t.getTranslateX() != 0 || t.getTranslateY() != 0 || !t.isIdentity()) {
			sb.append(" @t(").append(num(t.getTranslateX())).append(',').append(num(t.getTranslateY()));
			if (t.getScaleX() != 1 || t.getScaleY() != 1 || t.getShearX() != 0 || t.getShearY() != 0) {
				sb.append(",m=").append(num(t.getScaleX())).append('/').append(num(t.getShearY())).append('/')
					.append(num(t.getShearX())).append('/').append(num(t.getScaleY()));
			}
			sb.append(')');
		}
		Shape clip = g.getClip();
		if (clip != null) {
			Rectangle r = clip.getBounds();
			sb.append(" clip(").append(r.x).append(',').append(r.y).append(',').append(r.width).append(',').append(r.height).append(')');
		}
		log.add(sb.toString());
	}

	private String paint() {
		Paint p = g.getPaint();
		String s = p instanceof Color ? color((Color) p) : p == null ? "null" : p.getClass().getSimpleName();
		Composite c = g.getComposite();
		if (c instanceof AlphaComposite && (((AlphaComposite) c).getAlpha() != 1f || ((AlphaComposite) c).getRule() != AlphaComposite.SRC_OVER)) {
			s += " a=" + num(((AlphaComposite) c).getAlpha()) + "/" + ((AlphaComposite) c).getRule();
		}
		return s;
	}

	private String stroke() {
		Stroke st = g.getStroke();
		if (st instanceof BasicStroke) {
			BasicStroke b = (BasicStroke) st;
			return "w=" + num(b.getLineWidth()) + (b.getDashArray() != null ? " dash" : "");
		}
		return st.getClass().getSimpleName();
	}

	private static String color(Color c) {
		return String.format(Locale.ROOT, "#%02x%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue(), c.getAlpha());
	}

	private static String font(Font f) {
		return f == null ? "null" : f.getFontName(Locale.ROOT) + "/" + f.getStyle() + "/" + num(f.getSize2D());
	}

	private static String num(double d) {
		if (d == Math.rint(d)) {
			return String.valueOf((long) d);
		}
		return String.format(Locale.ROOT, "%.3f", d);
	}

	private static String shape(Shape s) {
		if (s instanceof Rectangle) {
			Rectangle r = (Rectangle) s;
			return "rect(" + r.x + "," + r.y + "," + r.width + "," + r.height + ")";
		}
		StringBuilder sb = new StringBuilder(s.getClass().getSimpleName()).append('[');
		double[] c = new double[6];
		int n = 0;
		for (PathIterator it = s.getPathIterator(null); !it.isDone() && n < 64; it.next(), n++) {
			int type = it.currentSegment(c);
			sb.append(type).append(':').append(num(c[0])).append(',').append(num(c[1])).append(' ');
		}
		return sb.append(']').toString();
	}

