package com.osrscompanion;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

/** The roadmap's background work runs on its own daemon thread, never RuneLite's shared executor. */
public class RoadmapExecutorTest {
	@Test
	public void runsOnItsOwnDaemonThreadThatEndsWhenIdle() throws Exception {
		ScheduledThreadPoolExecutor ex = RoadmapManager.newOwnExecutor();
		try {
			AtomicReference<Thread> ran = new AtomicReference<>();
			CountDownLatch done = new CountDownLatch(1);
			ex.schedule(() -> {
				ran.set(Thread.currentThread());
				done.countDown();
			}, 10, TimeUnit.MILLISECONDS);
			assertTrue(done.await(5, TimeUnit.SECONDS));
			assertEquals(RoadmapManager.THREAD_NAME, ran.get().getName());
			assertTrue(ran.get().isDaemon());
			assertNotSame(Thread.currentThread(), ran.get());
			assertTrue("the thread is not kept forever", ex.allowsCoreThreadTimeOut());
			assertEquals(RoadmapManager.IDLE_SECONDS, ex.getKeepAliveTime(TimeUnit.SECONDS));
		} finally {
			ex.shutdown();
		}
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.model.RoadmapSummary;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class RoadmapListCacheTest {
	private static final List<RoadmapSummary> ONE = Collections.singletonList(
			new Gson().fromJson("{\"collection_id\":7,\"title\":\"Maxing\",\"goal_count\":3}", RoadmapSummary.class));

	private final RoadmapListCache cache = new RoadmapListCache();

	@Test
	public void emptyUntilRecorded() {
		assertNull(cache.reusable("Zezima", 0));
	}

	@Test
	public void reusedForTheSamePlayerWhileRecent() {
		cache.record("Zezima", ONE, 1_000);
		assertEquals(ONE, cache.reusable("Zezima", 1_000 + RoadmapListCache.REUSE_MS - 1));
		assertNull(cache.reusable("Zezima", 1_000 + RoadmapListCache.REUSE_MS));
	}

	@Test
	public void neverReusedForAnotherPlayer() {
		cache.record("Zezima", ONE, 0);
		assertNull(cache.reusable("Lynx Titan", 1));
	}

	@Test
	public void invalidateForcesAFetch() {
		cache.record("Zezima", ONE, 0);
		cache.invalidate();
		assertNull(cache.reusable("Zezima", 1));
	}

	@Test
	public void anEmptyListIsReusedToo() {
		cache.record("Zezima", Collections.emptyList(), 0);
		assertEquals(Collections.emptyList(), cache.reusable("Zezima", 1));
	}
}

package com.osrscompanion;

import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RunePouchMonitorTest {
	@Test
	public void slotsResolveThroughTheRuneEnumAndMerge() {
		// Rune index 1 -> item 561 (nature), 2 -> 560 (death); slot 3 empty, slot 4 nature again.
		Map<Integer, Integer> contents = RunePouchMonitor.contents(
				new int[]{1, 2, 0, 1, 0, 0}, new int[]{1000, 250, 7, 500, 0, 0},
				rune -> rune == 1 ? 561 : rune == 2 ? 560 : -1);
		assertEquals(Integer.valueOf(1500), contents.get(561));
		assertEquals(Integer.valueOf(250), contents.get(560));
		assertEquals(2, contents.size());
	}

	@Test
	public void emptyPouchIsEmpty() {
		assertTrue(RunePouchMonitor.contents(new int[6], new int[6], rune -> 561).isEmpty());
		// An unknown rune index is skipped rather than uploaded as a bogus item.
		assertTrue(RunePouchMonitor.contents(new int[]{9}, new int[]{5}, rune -> -1).isEmpty());
	}
}

