/**
 * The website works out how slayer tasks ended (and the time spent on them) now. This plays random slayer
 * play (assignments, kills, completions with and without the chat line, skips, blocks, streak resets,
 * loading screens and logouts) through the plugin's old SlayerMonitor and the new one side by side, and
 * writes what the new one records (the game events) and what the old one sent (its task events and timing)
 * to build/oracle/slayer-events.json.gz, which the website's processor must turn into the same.
 */
public class SlayerEventsOracleTest {
	private static final int[] TASKS = {25, 39, 51, 73, 80};
	private static final int[] BOSSES = {41, 72};

	/** The game as both monitors see it. */
	private final Map<Integer, Integer> varps = new HashMap<>();
	private final Map<Integer, Integer> varbits = new HashMap<>();
	private int tick = 1000;
	private long ms = 1_790_000_000_000L;
	private GameState state = GameState.LOGIN_SCREEN;
	private final List<Object[]> scheduled = new ArrayList<>();
	private final List<Map<String, Object>> recorded = new ArrayList<>();
	private final List<OldSlayerTaskEvent> oldEvents = new ArrayList<>();
	private Random r;

	private Client client() {
		Client c = mock(Client.class);
		when(c.getVarpValue(anyInt())).thenAnswer(i -> varps.getOrDefault((Integer) i.getArgument(0), 0));
		when(c.getVarbitValue(anyInt())).thenAnswer(i -> varbits.getOrDefault((Integer) i.getArgument(0), 0));
		when(c.getTickCount()).thenAnswer(i -> tick);
		when(c.getGameState()).thenAnswer(i -> state);
		Player me = mock(Player.class);
		when(me.getName()).thenReturn("Tester");
		when(c.getLocalPlayer()).thenReturn(me);
		when(c.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(c.getRealSkillLevel(Skill.SLAYER)).thenReturn(90);
		when(c.getSkillExperience(Skill.SLAYER)).thenReturn(5_400_000);
		return c;
	}

	private ConfigManager configManager() {
		Map<String, String> store = new HashMap<>();
		ConfigManager cm = mock(ConfigManager.class);
		when(cm.getRSProfileConfiguration(anyString(), anyString())).thenAnswer(i -> store.get((String) i.getArgument(1)));
		doAnswer(i -> store.put(i.getArgument(1), String.valueOf((Object) i.getArgument(2))))
			.when(cm).setRSProfileConfiguration(anyString(), anyString(), any(Object.class));
		doAnswer(i -> store.remove((String) i.getArgument(1))).when(cm).unsetRSProfileConfiguration(anyString(), anyString());
		return cm;
	}

	private ScheduledExecutorService executor() {
		ScheduledExecutorService ex = mock(ScheduledExecutorService.class);
		doAnswer(i -> {
			scheduled.add(new Object[]{ms + ((TimeUnit) i.getArgument(2)).toMillis(i.getArgument(1)), i.getArgument(0)});
			return null;
		}).when(ex).schedule(any(Runnable.class), anyLong(), any(TimeUnit.class));
		return ex;
	}

	private ClientThread clientThread() {
		ClientThread ct = mock(ClientThread.class);
		doAnswer(i -> {
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(any(Runnable.class));
		return ct;
	}

	private OldSlayerMonitor old;
	private SlayerMonitor now;

	private void setUp() {
		TestOSRSCompanionConfig config = new TestOSRSCompanionConfig();
		config.setOsrsCompanionAppKey("key");
		OSRSCompanionApiClient api = mock(OSRSCompanionApiClient.class);
		OldSlayerMonitor.clock = () -> ms;
		OldSlayerMonitor.sink = p -> oldEvents.addAll(p.getEvents());
		old = new OldSlayerMonitor(client(), clientThread(), config, api, executor(), new Gson(), configManager());
		GameEvents events = new GameEvents(null, null, null, null, null, null, null, null, null) {
			@Override
			Map<String, Object> add(String type, Object... kv) {
				Map<String, Object> e = new LinkedHashMap<>();
				e.put("t", tick);
				e.put("ms", ms);
				e.put("e", type);
				for (int i = 0; i < kv.length; i += 2) {
					e.put((String) kv[i], kv[i + 1]);
				}
				recorded.add(e);
				return e;
			}
		};
		now = new SlayerMonitor(client(), clientThread(), config, api, executor(), new Gson(), configManager(), events);
	}

	// ---- What happens in the game, to both monitors ----

	private void varp(int id, int value) {
		if (varps.getOrDefault(id, 0) == value) {
			return;
		}
		varps.put(id, value);
		VarbitChanged e = new VarbitChanged();
		e.setVarpId(id);
		e.setValue(value);
		old.onVarbitChanged(e);
		now.onVarbitChanged(e);
	}

	private void varbit(int id, int value) {
		if (varbits.getOrDefault(id, 0) == value) {
			return;
		}
		varbits.put(id, value);
		VarbitChanged e = new VarbitChanged();
		e.setVarbitId(id);
		e.setValue(value);
		old.onVarbitChanged(e);
		now.onVarbitChanged(e);
	}

	private void chat(String text) {
		ChatMessage m = new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", text, null, 0);
		old.onChatMessage(m);
		now.onChatMessage(m);
	}

	private void gameState(GameState s) {
		state = s;
		GameStateChanged e = new GameStateChanged();
		e.setGameState(s);
		old.onGameStateChanged(e);
		now.onGameStateChanged(e);
	}

	/** One game tick (and what was scheduled for it). */
	private void tick() {
		if (state == GameState.LOGGED_IN) {
			old.onGameTick(new GameTick());
			now.onGameTick(new GameTick());
		}
		tick++;
		ms += 600 + r.nextInt(3) - 1;
		for (Object[] s : new ArrayList<>(scheduled)) {
			if ((long) s[0] <= ms) {
				scheduled.remove(s);
				((Runnable) s[1]).run();
			}
		}
	}

	private void ticks(int n) {
		for (int i = 0; i < n; i++) {
			// Now and then a loading screen (a teleport) or a logout in between.
			if (state == GameState.LOGGED_IN && r.nextInt(400) == 0) {
				gameState(GameState.LOADING);
				tick();
				gameState(GameState.LOGGED_IN);
			} else if (state == GameState.LOGGED_IN && r.nextInt(1500) == 0) {
				gameState(GameState.LOGIN_SCREEN);
				for (int k = r.nextInt(200); k > 0; k--) {
					tick();
				}
				gameState(GameState.LOGGED_IN);
			}
			tick();
		}
	}

	private int pick(int[] a) {
		return a[r.nextInt(a.length)];
	}

	private void assign() {
		int task = r.nextInt(6) == 0 ? 98 : pick(TASKS);
		int amount = 5 + r.nextInt(60);
		// The varps can land over two ticks.
		varp(VarPlayerID.SLAYER_TARGET, task);
		varbit(VarbitID.SLAYER_TARGET_BOSSID, task == 98 ? pick(BOSSES) : 0);
		varbit(VarbitID.SLAYER_MASTER, 1 + r.nextInt(9));
		varp(VarPlayerID.SLAYER_AREA, r.nextInt(3) == 0 ? 1 + r.nextInt(20) : 0);
		if (r.nextInt(4) == 0) {
			ticks(1);
		}
		// Mortimer's quantity modifier: more kills than the size the varp keeps.
		varp(VarPlayerID.SLAYER_COUNT_ORIGINAL, r.nextInt(5) == 0 ? Math.max(1, amount - r.nextInt(10)) : amount);
		varp(VarPlayerID.SLAYER_COUNT, amount);
	}

	private void points(int delta) {
		varbit(VarbitID.SLAYER_POINTS, Math.max(0, varbits.getOrDefault(VarbitID.SLAYER_POINTS, 0) + delta));
	}

	private void clearTask() {
		varp(VarPlayerID.SLAYER_COUNT, 0);
		if (r.nextBoolean()) {
			varp(VarPlayerID.SLAYER_TARGET, 0);
		}
	}

	private void complete() {
		int chatAt = r.nextInt(4) == 0 ? 99 : r.nextInt(9) - 3;
		if (chatAt < 0) {
			chat("You've completed " + (1 + varbits.getOrDefault(VarbitID.SLAYER_TASKS_COMPLETED, 0)) + " tasks in a row and received 15 points.");
			ticks(-chatAt);
		}
		varp(VarPlayerID.SLAYER_COUNT, 0);
		int how = r.nextInt(5);
		if (how <= 2) {
			varbit(VarbitID.SLAYER_TASKS_COMPLETED, varbits.getOrDefault(VarbitID.SLAYER_TASKS_COMPLETED, 0) + 1);
		} else if (how == 3) {
			varbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, varbits.getOrDefault(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 0) + 1);
		}
		if (r.nextInt(4) != 0) {
			points(r.nextInt(3) == 0 ? 0 : 15);
		}
		if (chatAt >= 0 && chatAt != 99) {
			ticks(chatAt);
			chat("You have completed your task! You've completed " + varbits.getOrDefault(VarbitID.SLAYER_TASKS_COMPLETED, 0) + " tasks in a row.");
		}
	}

	private void block() {
		int task = varps.getOrDefault(VarPlayerID.SLAYER_TARGET, 0);
		if (r.nextBoolean()) {
			int slot = VarbitID.SLAYER_BLOCKED_NIEVE_1;
			varbit(slot, task);
		} else {
			int v = varps.getOrDefault(VarPlayerID.SLAYER_REWARDS_BLOCKED_3, 0);
			varp(VarPlayerID.SLAYER_REWARDS_BLOCKED_3, (v << 8 | task) & 0x7FFFFFFF);
		}
		points(-100);
		clearTask();
	}

	private void play() {
		gameState(GameState.LOGGED_IN);
		ticks(10);
		for (int step = 0; step < 40; step++) {
			boolean hasTask = varps.getOrDefault(VarPlayerID.SLAYER_COUNT, 0) > 0 && varps.getOrDefault(VarPlayerID.SLAYER_TARGET, 0) != 0;
			if (!hasTask) {
				ticks(r.nextInt(30));
				assign();
				ticks(1 + r.nextInt(5));
				continue;
			}
			int what = r.nextInt(20);
			if (what < 12) {
				// Kills: short gaps, now and then a break longer than five minutes.
				int kills = 1 + r.nextInt(8);
				for (int k = 0; k < kills && varps.get(VarPlayerID.SLAYER_COUNT) > 1; k++) {
					ticks(r.nextInt(30) == 0 ? 500 + r.nextInt(400) : 2 + r.nextInt(40));
					varp(VarPlayerID.SLAYER_COUNT, varps.get(VarPlayerID.SLAYER_COUNT) - 1);
				}
				if (varps.get(VarPlayerID.SLAYER_COUNT) == 1 && r.nextBoolean()) {
					ticks(2 + r.nextInt(40));
					complete();
				}
			} else if (what < 15) {
				// A skip: points spent, the next task (sometimes the same monster from another master).
				points(-30);
				if (r.nextBoolean()) {
					varbit(VarbitID.SLAYER_MASTER, 1 + r.nextInt(9));
					varp(VarPlayerID.SLAYER_COUNT, 5 + r.nextInt(60));
				} else {
					assign();
				}
			} else if (what < 17) {
				block();
			} else if (what < 18) {
				// The streak lost (a task from Turael), or the task cancelled with nothing else.
				varbit(VarbitID.SLAYER_TASKS_COMPLETED, 0);
				assign();
			} else if (what < 19) {
				clearTask();
			} else {
				chat("You've completed 12 tasks in a row.");
			}
			ticks(1 + r.nextInt(6));
		}
		ticks(20);
		gameState(GameState.LOGIN_SCREEN);
		ticks(3);
	}

	private static Object field(Object o, String name) throws Exception {
		Field f = o.getClass().getDeclaredField(name);
		f.setAccessible(true);
		return f.get(o);
	}

	@Test
	public void writeOracle() throws Exception {
		Gson gson = new Gson();
		List<Map<String, Object>> cases = new ArrayList<>();
		for (int n = 0; n < 150; n++) {
			r = new Random(20261012L + n);
			varps.clear();
			varbits.clear();
			recorded.clear();
			oldEvents.clear();
			scheduled.clear();
			state = GameState.LOGIN_SCREEN;
			setUp();
			// Some characters start with a streak and points.
			varbits.put(VarbitID.SLAYER_TASKS_COMPLETED, r.nextInt(50));
			varbits.put(VarbitID.SLAYER_POINTS, r.nextInt(800));
			play();
			Map<String, Object> one = new LinkedHashMap<>();
			// As GameEvents sends them (Gson leaves out nulls).
			one.put("events", gson.fromJson(gson.toJson(recorded), List.class));
			List<Object> expected = new ArrayList<>();
			for (OldSlayerTaskEvent e : oldEvents) {
				Map<?, ?> m = gson.fromJson(gson.toJson(e), Map.class);
				m.remove("event_uuid");
				expected.add(m);
			}
			one.put("expected", expected);
			Map<String, Object> timing = new LinkedHashMap<>();
			timing.put("first", field(old, "firstKillMs"));
			timing.put("last", field(old, "lastKillMs"));
			timing.put("active", field(old, "activeMs"));
			one.put("timing", timing);
			cases.add(one);
		}
		Path out = Paths.get("build", "oracle", "slayer-events.json.gz");
		Files.createDirectories(out.getParent());
		try (Writer w = new OutputStreamWriter(new GZIPOutputStream(Files.newOutputStream(out)), StandardCharsets.UTF_8)) {
			new GsonBuilder().serializeNulls().create().toJson(cases, w);
		}
		long events = cases.stream().mapToLong(c -> ((List<?>) c.get("expected")).size()).sum();
		System.out.println("slayer oracle: " + cases.size() + " sequences, " + events + " task events");
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.model.SlayerGear;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/** The Slayer gear window's picked setup (stored per task) and its bank layout. */
public class SlayerGearPickTest {
	private static final String GEAR = "{\"task\":\"Abyssal demons\",\"monster\":\"Abyssal demon\",\"sets\":["
		+ "{\"key\":\"melee\",\"label\":\"Melee\",\"max_hit\":42,\"dps\":5.31,\"kills_per_hour\":118,"
		+ "\"equipment\":[{\"slot\":\"head\",\"item\":11864,\"name\":\"Slayer helmet\"},{\"slot\":\"weapon\",\"item\":4151,\"name\":\"Abyssal whip\"},"
		+ "{\"slot\":\"weapon\",\"item\":4587,\"name\":\"Dragon scimitar\"},{\"slot\":\"ring\",\"item\":0,\"name\":\"None\"}],"
		+ "\"extras\":[{\"label\":\"Potion\",\"name\":\"Super combat potion\"}]},"
		+ "{\"key\":\"ranged\",\"label\":\"Ranged\",\"max_hit\":30,\"dps\":4.1,\"kills_per_hour\":90},"
		+ "{\"key\":\"barrage\",\"label\":\"Barrage\",\"max_hit\":30,\"dps\":3.2,\"kills_per_hour\":300,\"spell\":\"Ice Barrage\"}]}";

	private final SlayerGear gear = new Gson().fromJson(GEAR, SlayerGear.class);

	@Test
	public void picksTheStoredSetupElseTheBest() {
		assertEquals(0, SlayerHelperManager.gearIndex(gear.getSets(), null));
		assertEquals(2, SlayerHelperManager.gearIndex(gear.getSets(), "barrage"));
		assertEquals(1, SlayerHelperManager.gearIndex(gear.getSets(), "ranged"));
		// A setup that is gone (no longer owned / calculated) falls back to the best.
		assertEquals(0, SlayerHelperManager.gearIndex(gear.getSets(), "magic"));
	}

	@Test
	public void storesThePickPerTask() {
		assertEquals("slayerGearSet.abyssal_demons", SlayerHelperManager.gearConfigKey(gear));
		assertNull(SlayerHelperManager.gearConfigKey(null));
		assertNull(SlayerHelperManager.gearConfigKey(new Gson().fromJson("{\"sets\":[]}", SlayerGear.class)));
		assertEquals("slayerGearSet.kalphite_queen",
			SlayerHelperManager.gearConfigKey(new Gson().fromJson("{\"monster\":\"Kalphite Queen\"}", SlayerGear.class)));
	}

	@Test
	public void laysOutTheWornGearOnePerSlot() {
		Map<String, Integer> worn = BankLayoutPrep.slayerWorn(gear.getSets().get(0), id -> id);
		assertEquals(2, worn.size());
		assertEquals(Integer.valueOf(11864), worn.get("head"));
		assertEquals(Integer.valueOf(4151), worn.get("weapon"));
		int[] positions = BankLayouts.build(worn, java.util.Collections.emptyList(), java.util.Collections.emptyList(), -1);
		assertEquals(11864, positions[BankLayouts.EQUIPMENT_POS.get("head")]);
		assertEquals(4151, positions[BankLayouts.EQUIPMENT_POS.get("weapon")]);
	}

	@Test
	public void anOpenWindowDrivesTheBank() {
		assertNull(BankLayoutPrep.pick(false, false, false, false, false));
		assertEquals(BankLayoutPrep.Driver.SLAYER, BankLayoutPrep.pick(false, false, false, true, false));
		assertEquals(BankLayoutPrep.Driver.SLAYER, BankLayoutPrep.pick(true, false, true, true, true));
		assertEquals(BankLayoutPrep.Driver.BOSS, BankLayoutPrep.pick(true, true, true, true, true));
		assertEquals(BankLayoutPrep.Driver.FARM, BankLayoutPrep.pick(true, false, true, true, false));
		assertEquals(BankLayoutPrep.Driver.BOSS, BankLayoutPrep.pick(true, false, false, true, false));
	}

	@Test
	public void numbersLine() {
		assertEquals("Max 42 · 5.31 DPS · 118 kills/h", SlayerGearWindow.numbers(gear.getSets().get(0)));
	}

	@Test
	public void supplyOptionsBestFirstAsManyAsSet() {
		SlayerGear.Set set = new Gson().fromJson("{\"key\":\"magic\",\"spell\":\"Fire Surge\",\"supplies\":{\"kind\":\"spell\",\"options\":["
			+ "{\"name\":\"Fire Surge\",\"items\":[21880,556,554]},{\"name\":\"Fire Wave\",\"items\":[565,556,554]},"
			+ "{\"name\":\"Fire Blast\",\"items\":[560,556,554]},{\"name\":\"Fire Bolt\",\"items\":[562,556,554]}]}}", SlayerGear.Set.class);
		// Runes once each, in the order of the spells.
		assertEquals(java.util.Arrays.asList(21880, 556, 554, 565, 560), set.supplyItems(3));
		assertEquals("Fire Surge > Fire Wave > Fire Blast", set.supplyText(3));
		assertEquals(java.util.Collections.emptyList(), set.supplyItems(0));
		assertNull(set.supplyText(0));
		assertEquals(java.util.Collections.emptyList(), gear.getSets().get(0).supplyItems(3));
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.model.SlayerGuide;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The guide's JSON, the area check, task monster names and the helper's number formats. */
public class SlayerGuideTest {
	private static final String GUIDE = "{\"task\":{\"task_id\":42,\"task_name\":\"Abyssal demons\",\"area_id\":null,\"area_name\":null,"
		+ "\"amount_remaining\":143,\"amount_original\":190,\"master\":\"Duradel\"},"
		+ "\"locations\":[{\"key\":\"abyssal-demons-catacombs\",\"name\":\"Catacombs of Kourend\",\"tile\":[1675,10090,0],\"radius\":20,"
		+ "\"region_ids\":[6556,6557],\"multi\":true,\"recommended\":true,\"why\":\"Multi-combat, safe spot\","
		+ "\"requirements\":[\"Kourend Catacombs access\"],\"travel\":{\"name\":\"Xeric's talisman (Xeric's Heart)\","
		+ "\"how\":\"Rub Xeric's talisman, then run into the Catacombs.\",\"items\":[13393],\"spell\":false},"
		+ "\"steps\":[\"Rub Xeric's talisman: Xeric's Heart\",\"Enter the Catacombs (statue)\"],\"monsters\":[\"Abyssal demon\"]},"
		+ "{\"key\":\"abyssal-demons-slayer-tower\",\"name\":\"Slayer Tower\",\"tile\":[3420,3570,2],\"radius\":10}],"
		+ "\"selected\":\"abyssal-demons-catacombs\"}";

	@Test
	public void readsTheContractsGuide() {
		SlayerGuide g = new Gson().fromJson(GUIDE, SlayerGuide.class);
		assertEquals(Integer.valueOf(42), g.getTask().getTaskId());
		assertNull(g.getTask().getAreaId());
		assertEquals(143, g.getTask().getAmountRemaining());
		assertEquals("Duradel", g.getTask().getMaster());
		assertEquals(2, g.getLocations().size());
		SlayerGuide.Location l = g.selectedLocation();
		assertEquals("Catacombs of Kourend", l.getName());
		assertEquals(1675, l.getX());
		assertEquals(10090, l.getY());
		assertEquals(0, l.getPlane());
		assertTrue(l.isMulti());
		assertEquals(Collections.singletonList(13393), l.getTravel().getItems());
		assertEquals(Collections.singletonList("Abyssal demon"), l.getMonsters());
		// The second one sent no travel, steps or regions.
		SlayerGuide.Location tower = g.getLocations().get(1);
		assertNull(tower.getTravel());
		assertTrue(tower.getSteps().isEmpty());
		assertTrue(tower.getRegionIds().isEmpty());
	}

	@Test
	public void readsTheWayThere() {
		SlayerGuide g = new Gson().fromJson(GUIDE.replace("\"spell\":false}", "\"spell\":false,\"way\":[[2453,3520,0],[1,2],null,[2027,5612,0]]}"),
			SlayerGuide.class);
		java.util.List<int[]> way = g.selectedLocation().getTravel().getWay();
		// The short and null tiles are left out.
		assertEquals(2, way.size());
		assertTrue(Arrays.equals(new int[]{2453, 3520, 0}, way.get(0)));
		assertTrue(Arrays.equals(new int[]{2027, 5612, 0}, way.get(1)));
		assertTrue(new Gson().fromJson(GUIDE, SlayerGuide.class).selectedLocation().getTravel().getWay().isEmpty());
	}

	@Test
	public void picksTheSelectedThenTheRecommendedLocation() {
		Gson gson = new Gson();
		SlayerGuide picked = gson.fromJson(GUIDE.replace("\"selected\":\"abyssal-demons-catacombs\"", "\"selected\":\"abyssal-demons-slayer-tower\""),
			SlayerGuide.class);
		assertEquals("Slayer Tower", picked.selectedLocation().getName());
		SlayerGuide none = gson.fromJson(GUIDE.replace("\"selected\":\"abyssal-demons-catacombs\"", "\"selected\":null"), SlayerGuide.class);
		assertEquals("Catacombs of Kourend", none.selectedLocation().getName());
		assertNull(gson.fromJson("{\"task\":null,\"locations\":[],\"selected\":null}", SlayerGuide.class).selectedLocation());
	}

	@Test
	public void inTheAreaByRadiusOnTheSamePlaneOrByRegion() {
		SlayerGuide.Location l = new Gson().fromJson(GUIDE, SlayerGuide.class).selectedLocation();
		assertTrue(l.contains(1675, 10090, 0, 0));
		assertTrue(l.contains(1695, 10070, 0, 0));
		assertFalse(l.contains(1696, 10090, 0, 0));
		// Same tiles, another floor.
		assertFalse(l.contains(1675, 10090, 1, 0));
		// Anywhere in one of its map regions.
		assertTrue(l.contains(1600, 10000, 1, 6557));
	}

	@Test
	public void taskMonstersByTheLocationsNamesOrTheTask() {
		assertTrue(SlayerMonsters.matches("Abyssal demon", Arrays.asList("Abyssal demon"), "Abyssal demons"));
		// The location's list decides when there is one.
		assertFalse(SlayerMonsters.matches("Greater abyssal demon", Arrays.asList("Abyssal demon"), "Abyssal demons"));
		assertTrue(SlayerMonsters.matches("<col=ffff00>abyssal demon</col>", Arrays.asList("Abyssal demon"), null));
		// Without one, loosely by the task's name.
		assertTrue(SlayerMonsters.matches("Abyssal demon", null, "Abyssal demons"));
		assertTrue(SlayerMonsters.matches("Zombie", null, "Zombies"));
		assertTrue(SlayerMonsters.matches("Wolf", null, "Wolves"));
		assertTrue(SlayerMonsters.matches("Kalphite Worker", null, "Kalphite"));
		assertTrue(SlayerMonsters.matches("Mutated Bloodveld", null, "Bloodvelds"));
		assertTrue(SlayerMonsters.matches("Dust devil", null, "Dust devils"));
		assertFalse(SlayerMonsters.matches("Black demon", null, "Abyssal demons"));
		assertFalse(SlayerMonsters.matches("Guard", null, "Abyssal demons"));
		assertFalse(SlayerMonsters.matches(null, null, "Abyssal demons"));
		assertFalse(SlayerMonsters.matches("Abyssal demon", null, null));
	}

	@Test
	public void formats() {
		assertEquals("0:00", SlayerFormat.clock(0));
		assertEquals("4:05", SlayerFormat.clock(245_400));
		assertEquals("1:02:09", SlayerFormat.clock(3_729_000));
		assertEquals("18.5s", SlayerFormat.seconds(18_500));
		assertEquals("1:05", SlayerFormat.seconds(65_000));
		assertEquals("950 gp", SlayerFormat.gp(950));
		assertEquals("33.5K", SlayerFormat.gp(33_500));
		assertEquals("2.35M", SlayerFormat.gp(2_350_000));
		assertEquals("120K", SlayerFormat.gp(120_000));
	}

	@Test
	public void compassDirections() {
		assertEquals("north", SlayerFormat.compass(0, 10));
		assertEquals("north-east", SlayerFormat.compass(100, 90));
		assertEquals("south-west", SlayerFormat.compass(-50, -60));
		assertEquals("west", SlayerFormat.compass(-300, 20));
		assertNull(SlayerFormat.compass(0, 0));
	}
}

package com.osrscompanion;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SlayerKillLogTest {
	private static final long START = 1_791_374_400_000L;

	private static final SlayerKillLog.Npc DEMON = new SlayerKillLog.Npc(415, "Abyssal demon", 124, 6557, true);
	private static final SlayerKillLog.Npc DEMON_SINGLE = new SlayerKillLog.Npc(415, "Abyssal demon", 124, 6557, false);
	private static final SlayerKillLog.Npc DEMON_OTHER_REGION = new SlayerKillLog.Npc(415, "Abyssal demon", 124, 6813, true);
	private static final SlayerKillLog.Npc DEMON_OTHER_ID = new SlayerKillLog.Npc(7241, "<col=ffff00>Abyssal demon</col>", 124, 6557, true);

	private static SlayerSession session() {
		return SlayerSession.start("42:0:0:6", 42, "Abyssal demons", null, "Duradel", "abyssal-demons-catacombs",
			"Catacombs of Kourend", 190, 190, START);
	}

	@Test
	public void theSameNpcRegionAndMultiMerge() {
		SlayerSession s = session();
		s.logKills(DEMON, 1, START);
		s.logFightTime(DEMON, 12_000, START);
		s.logKills(new SlayerKillLog.Npc(415, "Abyssal demon", 124, 6557, true), 2, START);
		s.logFightTime(DEMON, 18_000, START);
		assertEquals(1, s.killLog.size());
		SlayerKillLog.Entry e = s.killLog.get(0);
		assertEquals(3, e.kills);
		assertEquals(30_000, e.fightMsTotal);
		assertEquals(2, e.fightMsCount);
	}

	@Test
	public void anotherIdRegionOrMultiIsAnotherEntry() {
		SlayerSession s = session();
		s.logKills(DEMON, 1, START);
		s.logKills(DEMON_SINGLE, 1, START);
		s.logKills(DEMON_OTHER_REGION, 1, START);
		s.logKills(DEMON_OTHER_ID, 1, START);
		assertEquals(4, s.killLog.size());
		// Tags are stripped from the name.
		assertEquals("Abyssal demon", s.killLog.get(3).npcName);
		assertEquals(7241, s.killLog.get(3).npcId);
	}

	@Test
	public void theLogKeepsTheMostKilled() {
		List<SlayerKillLog.Entry> log = new ArrayList<>();
		for (int i = 0; i < SlayerKillLog.MAX_ENTRIES; i++) {
			SlayerKillLog.addKills(log, new SlayerKillLog.Npc(1000 + i, "Npc " + i, 10, 1, false), 5);
		}
		// One entry with fewer kills: a new NPC pushes it out, not the new one.
		log.get(7).kills = 1;
		SlayerKillLog.addKills(log, new SlayerKillLog.Npc(9999, "New", 10, 1, false), 1);
		assertEquals(SlayerKillLog.MAX_ENTRIES, log.size());
		assertTrue(log.stream().noneMatch(e -> e.npcId == 1007));
		assertTrue(log.stream().anyMatch(e -> e.npcId == 9999));
		// The payload never has more than the cap, most killed first.
		SlayerKillLog.addKills(log, new SlayerKillLog.Npc(9999, "New", 10, 1, false), 10);
		List<Map<String, Object>> out = SlayerKillLog.payload(log);
		assertEquals(SlayerKillLog.MAX_ENTRIES, out.size());
		assertEquals(9999, out.get(0).get("npc_id"));
		assertEquals(11, out.get(0).get("kills"));
	}

	@Test
	public void thePayloadHasTheKillLog() {
		SlayerSession s = session();
		s.addKills(3, START);
		s.logKills(DEMON, 2, START);
		s.logKills(DEMON_SINGLE, 1, START);
		s.logFightTime(DEMON, 9_500, START);
		Map<String, Object> payload = s.payload("Zezima");
		JsonObject json = new Gson().toJsonTree(payload).getAsJsonObject();
		JsonArray log = json.getAsJsonArray("kill_log");
		assertEquals(2, log.size());
		JsonObject first = log.get(0).getAsJsonObject();
		assertEquals(Arrays.asList("npc_id", "npc_name", "combat_level", "region_id", "multi", "kills", "fight_ms_total", "fight_ms_count"),
			new ArrayList<>(first.keySet()));
		assertEquals(415, first.get("npc_id").getAsInt());
		assertEquals("Abyssal demon", first.get("npc_name").getAsString());
		assertEquals(124, first.get("combat_level").getAsInt());
		assertEquals(6557, first.get("region_id").getAsInt());
		assertTrue(first.get("multi").getAsBoolean());
		assertEquals(2, first.get("kills").getAsInt());
		assertEquals(9_500, first.get("fight_ms_total").getAsLong());
		assertEquals(1, first.get("fight_ms_count").getAsInt());
		JsonObject second = log.get(1).getAsJsonObject();
		assertFalse(second.get("multi").getAsBoolean());
		assertEquals(0, second.get("fight_ms_count").getAsInt());
		// The existing keys are still there.
		assertTrue(json.has("boss_kills"));
		assertTrue(json.has("kill_times_ms"));
		// No kills yet: an empty array.
		assertEquals(0, new Gson().toJsonTree(session().payload("Zezima")).getAsJsonObject().getAsJsonArray("kill_log").size());
	}

	@Test
	public void theLogSurvivesARestart() {
		Gson gson = new Gson();
		SlayerSession s = session();
		s.logKills(DEMON, 4, START);
		s.logFightTime(DEMON, 7_000, START);
		SlayerSession back = gson.fromJson(gson.toJson(s), SlayerSession.class);
		assertEquals(1, back.killLog.size());
		SlayerKillLog.Entry e = back.killLog.get(0);
		assertEquals(415, e.npcId);
		assertEquals("Abyssal demon", e.npcName);
		assertEquals(124, e.combatLevel);
		assertEquals(6557, e.regionId);
		assertTrue(e.multi);
		assertEquals(4, e.kills);
		assertEquals(7_000, e.fightMsTotal);
		assertEquals(1, e.fightMsCount);
		// It goes on adding to the same entry after the restart.
		back.logKills(DEMON, 1, START + 1);
		assertEquals(5, back.killLog.get(0).kills);
		// A session stored before the kill log: none, and logging still works.
		SlayerSession old = gson.fromJson("{\"session_uuid\":\"x\",\"kill_log\":null}", SlayerSession.class);
		old.logKills(DEMON, 1, START);
		assertEquals(1, old.killLog.size());
		assertEquals(1, ((List<?>) old.payload("Zezima").get("kill_log")).size());
	}

	@Test
	public void anUnknownSpotHasItsRegionsKeyAndAnAreaAfterARestart() {
		assertEquals("spot-12850", SlayerKillLog.spotKey(12850));
		assertEquals("Unknown spot (region 12850)", SlayerKillLog.spotName(12850));
		assertTrue(SlayerHelperManager.isAdhocKey("spot-12850"));
		assertTrue(SlayerHelperManager.isAdhocKey("boss-cerberus"));
		assertFalse(SlayerHelperManager.isAdhocKey("abyssal-demons-catacombs"));
		SlayerSession s = SlayerSession.start("42:0:0:6", 42, "Abyssal demons", null, "Duradel", SlayerKillLog.spotKey(12850),
			SlayerKillLog.spotName(12850), 190, 190, START);
		s.monsters = Collections.emptyList();
		assertNull(SlayerHelperManager.bossAreaOf(s));
		s.bossAreaTile = Arrays.asList(3200, 3200, 0);
		assertNotNull(SlayerHelperManager.bossAreaOf(s));
		assertEquals("spot-12850", SlayerHelperManager.bossAreaOf(s).getKey());
		assertTrue(SlayerHelperManager.bossAreaOf(s).contains(3200 + SlayerHelperManager.BOSS_AREA_RADIUS, 3200, 0, 0));
	}

	@Test
	public void aCountedKillGoesToTheMonsterThatDied() {
		SlayerKillLog.Matcher m = new SlayerKillLog.Matcher();
		// Death first, then the count.
		assertNull(m.died(DEMON, true, 10));
		assertEquals(Collections.singletonList(DEMON), m.counted(1, 10, true));
		// Count first, then the death a tick later.
		assertTrue(m.counted(1, 20, true).isEmpty());
		assertEquals(DEMON_SINGLE, m.died(DEMON_SINGLE, true, 21));
		// Your kill is preferred over someone else's.
		m.died(DEMON_OTHER_REGION, true, 30);
		m.died(DEMON_OTHER_ID, false, 30);
		assertEquals(Collections.singletonList(DEMON_OTHER_REGION), m.counted(1, 30, true));
		// A count no death explains goes to the last monster after the window.
		assertTrue(m.counted(1, 100, true).isEmpty());
		assertTrue(m.expire(100 + SlayerKillLog.Matcher.WINDOW_TICKS, false).isEmpty());
		assertEquals(Collections.singletonList(DEMON_OTHER_REGION), m.expire(101 + SlayerKillLog.Matcher.WINDOW_TICKS, false));
		// A count the session didn't count doesn't wait.
		assertTrue(m.counted(1, 200, false).isEmpty());
		assertNull(m.died(DEMON, true, 200));
	}
}

package com.osrscompanion;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class SlayerKillTimerTest {
	@Test
	public void barrageTimesEveryMonsterOnItsOwn() {
		SlayerKillTimer timer = new SlayerKillTimer();
		// One barrage hits three monsters at once; a fourth is only splashed by the next cast.
		timer.hit(1, 0);
		timer.hit(2, 0);
		timer.hit(3, 0);
		timer.hit(4, 2_400);
		// Later casts land on the ones already being timed: their start stays the first hit.
		timer.hit(1, 2_400);
		timer.hit(2, 2_400);
		assertEquals(Long.valueOf(6_000), timer.died(1, 6_000));
		assertEquals(Long.valueOf(9_000), timer.died(2, 9_000));
		assertEquals(Long.valueOf(9_600), timer.died(4, 12_000));
		assertEquals(Long.valueOf(13_000), timer.died(3, 13_000));
		assertEquals(0, timer.fighting());
	}

	@Test
	public void startingTheAttackStartsTheTimerBeforeTheFirstHit() {
		SlayerKillTimer timer = new SlayerKillTimer();
		timer.attacked(7, 1_000);
		timer.hit(7, 3_000);
		assertEquals(Long.valueOf(9_000), timer.died(7, 10_000));
	}

	@Test
	public void monstersNeverHitDontCount() {
		SlayerKillTimer timer = new SlayerKillTimer();
		// Clicked on, but someone else killed it before your first hit.
		timer.attacked(5, 0);
		assertNull(timer.died(5, 4_000));
		// Never touched at all.
		assertNull(timer.died(6, 4_000));
	}

	@Test
	public void aDeathCountsOnce() {
		SlayerKillTimer timer = new SlayerKillTimer();
		timer.hit(3, 0);
		// ActorDeath, then NpcDespawned for the same monster.
		assertEquals(Long.valueOf(5_000), timer.died(3, 5_000));
		assertNull(timer.died(3, 5_600));
	}

	@Test
	public void aMonsterThatWalkedOffIsForgotten() {
		SlayerKillTimer timer = new SlayerKillTimer();
		timer.hit(9, 0);
		timer.forget(9);
		// The index comes back as a new monster: its own timer.
		timer.hit(9, 60_000);
		assertEquals(Long.valueOf(4_000), timer.died(9, 64_000));
	}

	@Test
	public void fightsThatNeverEndAreDropped() {
		SlayerKillTimer timer = new SlayerKillTimer();
		timer.hit(1, 0);
		timer.hit(2, SlayerKillTimer.STALE_MS);
		timer.prune(SlayerKillTimer.STALE_MS + 1);
		assertEquals(1, timer.fighting());
		assertNull(timer.died(1, SlayerKillTimer.STALE_MS + 2));
	}
}

