package com.osrscompanion;

import com.google.gson.Gson;
import com.osrscompanion.model.BankSyncPayload;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SourceSyncerTest {
	private static final long DEFAULT_MS = TimeUnit.SECONDS.toMillis(SourceSyncer.DEFAULT_DEBOUNCE_SECONDS);

	private FakeScheduledExecutorService executor;
	private List<BankSyncPayload> sent;
	private boolean enabled;
	private long now;
	private SourceSyncer syncer;

	@Before
	public void setUp() {
		executor = new FakeScheduledExecutorService();
		sent = new ArrayList<>();
		enabled = true;
		now = 0;
		syncer = new SourceSyncer("fish_barrel", new Gson(), executor, () -> now, () -> enabled, () -> "Zezima", sent::add);
	}

	private static Map<Integer, Integer> qty(int itemId, int q) {
		Map<Integer, Integer> m = new HashMap<>();
		m.put(itemId, q);
		return m;
	}

	private void advance(long ms) {
		now += ms;
		executor.runDue(now);
	}

	private int quantity(BankSyncPayload p, String source, int itemId) {
		for (BankSyncPayload.BankItem i : p.getItems().get(source)) {
			if (i.getItemId() == itemId) {
				return i.getQuantity();
			}
		}
		return 0;
	}

	@Test
	public void firstContentsSendAtOnceThenRoutineChangesWaitThreeMinutes() {
		syncer.submit(qty(13439, 1), false);
		assertEquals(1, sent.size());
		for (int i = 2; i <= 11; i++) {
			syncer.submit(qty(13439, i), false);
		}
		assertEquals(1, sent.size());
		advance(DEFAULT_MS - 1);
		assertEquals("still waiting", 1, sent.size());
		advance(1);
		assertEquals(2, sent.size());
		assertEquals(11, quantity(sent.get(1), "fish_barrel", 13439));
	}

	@Test
	public void unchangedContentsAreNotResent() {
		syncer.submit(qty(13439, 5), false);
		syncer.submit(qty(13439, 5), false);
		syncer.submit(qty(13439, 5), true);
		assertEquals(1, sent.size());
		assertTrue(executor.liveTasks().isEmpty());
		// A change that reverts before the debounce fires sends nothing.
		syncer.submit(qty(13439, 6), false);
		syncer.submit(qty(13439, 5), false);
		advance(DEFAULT_MS);
		assertEquals(1, sent.size());
	}

	@Test
	public void immediateSubmitAndFlushSkipTheWait() {
		syncer.submit(qty(13439, 5), false);
		syncer.submit(qty(13439, 6), false);
		assertEquals(1, sent.size());
		syncer.submit(new HashMap<>(), true); // emptied at the bank
		assertEquals(2, sent.size());
		assertTrue(sent.get(1).getItems().get("fish_barrel").isEmpty());
		assertTrue(executor.liveTasks().isEmpty());

		syncer.submit(qty(13439, 2), false);
		assertEquals(2, sent.size());
		syncer.flushPending(); // logout
		assertEquals(3, sent.size());
		assertTrue(executor.liveTasks().isEmpty());
	}

	@Test
	public void multipleSourcesMergeIntoOnePendingUpload() {
		SourceSyncer bank = new SourceSyncer("bank memory", new Gson(), executor, () -> now, () -> enabled, () -> "Zezima", sent::add);
		Map<String, Map<Integer, Integer>> first = new HashMap<>();
		first.put("inventory", qty(1511, 5));
		bank.submitSources(first, false);
		assertEquals(1, sent.size());
		// The bank opens later: a source never sent goes up at once, with the inventory as it is.
		Map<String, Map<Integer, Integer>> withBank = new HashMap<>();
		withBank.put("bank", qty(1511, 100));
		withBank.put("inventory", qty(1511, 5));
		bank.submitSources(withBank, false);
		assertEquals(2, sent.size());
		assertEquals(100, quantity(sent.get(1), "bank", 1511));
		// Routine changes to both sources collapse into one request.
		Map<String, Map<Integer, Integer>> later = new HashMap<>();
		later.put("bank", qty(1511, 90));
		later.put("inventory", qty(1511, 15));
		bank.submitSources(later, false);
		Map<String, Map<Integer, Integer>> invOnly = new HashMap<>();
		invOnly.put("inventory", qty(1511, 16));
		bank.submitSources(invOnly, false);
		advance(DEFAULT_MS);
		assertEquals(3, sent.size());
		assertEquals(90, quantity(sent.get(2), "bank", 1511));
		assertEquals(16, quantity(sent.get(2), "inventory", 1511));
	}

	@Test
	public void linkedSourcesAlwaysGoUpTogether() {
		SourceSyncer bank = new SourceSyncer("bank memory", new Gson(), executor, () -> now, () -> enabled, () -> "Zezima", sent::add);
		bank.linkSources("inventory", "worn");
		Map<String, Map<Integer, Integer>> first = new HashMap<>();
		first.put("inventory", qty(1511, 5));
		first.put("worn", qty(20997, 1));
		bank.submitSources(first, false);
		assertEquals(1, sent.size());
		assertTrue(sent.get(0).getItems().containsKey("worn"));

		// Only the inventory changed: the worn gear still goes with it (an "inventory" alone reads as an older
		// plugin's inventory + worn gear on the website).
		Map<String, Map<Integer, Integer>> invChanged = new HashMap<>();
		invChanged.put("inventory", qty(1511, 6));
		invChanged.put("worn", qty(20997, 1));
		bank.submitSources(invChanged, true);
		assertEquals(2, sent.size());
		assertEquals(6, quantity(sent.get(1), "inventory", 1511));
		assertEquals(1, quantity(sent.get(1), "worn", 20997));

		// Only the worn gear changed (unequipped into the inventory, read in one go): both go.
		Map<String, Map<Integer, Integer>> wornChanged = new HashMap<>();
		wornChanged.put("inventory", qty(1511, 6));
		wornChanged.put("worn", new HashMap<>());
		bank.submitSources(wornChanged, true);
		assertEquals(3, sent.size());
		assertEquals(6, quantity(sent.get(2), "inventory", 1511));
		assertTrue(sent.get(2).getItems().get("worn").isEmpty());

		// Nothing changed: nothing goes up.
		bank.submitSources(wornChanged, true);
		assertEquals(3, sent.size());

		// A change that reverts before the debounce: neither stays pending.
		Map<String, Map<Integer, Integer>> moved = new HashMap<>();
		moved.put("inventory", qty(1511, 7));
		moved.put("worn", new HashMap<>());
		bank.submitSources(moved, false);
		bank.submitSources(wornChanged, false);
		advance(DEFAULT_MS);
		assertEquals(3, sent.size());
	}

	@Test
	public void unlinkedSourcesStillGoUpAlone() {
		SourceSyncer bank = new SourceSyncer("bank memory", new Gson(), executor, () -> now, () -> enabled, () -> "Zezima", sent::add);
		bank.linkSources("inventory", "worn");
		Map<String, Map<Integer, Integer>> first = new HashMap<>();
		first.put("inventory", qty(1511, 5));
		first.put("worn", qty(20997, 1));
		first.put("bank", qty(995, 100));
		bank.submitSources(first, true);
		Map<String, Map<Integer, Integer>> bankOnly = new HashMap<>(first);
		bankOnly.put("bank", qty(995, 50));
		bank.submitSources(bankOnly, true);
		assertEquals(2, sent.size());
		assertEquals(java.util.Collections.singleton("bank"), sent.get(1).getItems().keySet());
	}

	@Test
	public void invalidateForcesTheNextSubmitAndGatedOffSendsNothing() {
		syncer.submit(qty(13439, 5), false);
		syncer.invalidate();
		syncer.submit(qty(13439, 5), true);
		assertEquals(2, sent.size());
		enabled = false;
		syncer.submit(qty(13439, 9), true);
		assertEquals(2, sent.size());
		assertFalse(enabled);
	}

	@Test
	public void onlyUrgentUploadsAskForAPriorityFlush() {
		int[] flushes = {0};
		syncer.setPriorityFlush(() -> flushes[0]++);
		syncer.submit(qty(1, 1), false); // first contents of the session: go with the login burst
		assertEquals(1, sent.size());
		assertEquals(0, flushes[0]);
		syncer.submit(qty(1, 2), false);
		advance(DEFAULT_MS);
		assertEquals(2, sent.size());
		assertEquals(0, flushes[0]);
		syncer.submit(qty(1, 3), true);
		assertEquals(3, sent.size());
		assertEquals(1, flushes[0]);
		syncer.submit(qty(1, 4), false);
		syncer.flushPending();
		assertEquals(2, flushes[0]);
	}

	@Test
	public void aPendingUploadStillGoesUpWhenTheMonitorsFeatureWasTurnedOff() {
		Guard guard = new Guard(() -> now);
		Guard previous = Guard.shared();
		Guard.setShared(guard);
		try {
			// As BankMemoryMonitor builds it: the shared executor wrapped in its own feature.
			SourceSyncer bank = new SourceSyncer("bank memory", new Gson(), GuardedExecutor.wrap("bank-sync", executor),
				() -> now, () -> enabled, () -> "Zezima", sent::add);
			bank.submit(qty(13124, 1), false);
			assertEquals(1, sent.size());
			bank.submit(qty(13124, 2), false);
			// The bank sync tripped its breaker (five errors).
			for (int i = 0; i < Guard.FAILURE_LIMIT; i++) {
				guard.runIn("bank-sync", () -> {
					throw new IllegalStateException("boom");
				});
			}
			assertTrue(guard.isDisabled("bank-sync"));
			advance(DEFAULT_MS);
			assertEquals("what was already read is not dropped", 2, sent.size());
			assertEquals(2, quantity(sent.get(1), "bank memory", 13124));
		} finally {
			Guard.setShared(previous);
		}
	}
}

package com.osrscompanion;

import net.runelite.api.WorldType;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for special game mode detection using WorldType enum.
 * Verifies that all special game mode world types are available for checking.
 * Special modes that should be excluded: SEASONAL, DEADMAN, FRESH_START_WORLD,
 * TOURNAMENT_WORLD, BETA_WORLD, NOSAVE_MODE, QUEST_SPEEDRUNNING, PVP_ARENA
 * (a PvP Arena world hands the player a temporary copy of their character).
 */
public class SpecialGameModeTest
{
	@Test
	public void testSpecialGameModeWorldTypesExist()
	{
		assertNotNull("WorldType.SEASONAL should exist", WorldType.SEASONAL);
		assertNotNull("WorldType.DEADMAN should exist", WorldType.DEADMAN);
		assertNotNull("WorldType.FRESH_START_WORLD should exist", WorldType.FRESH_START_WORLD);
		assertNotNull("WorldType.TOURNAMENT_WORLD should exist", WorldType.TOURNAMENT_WORLD);
		assertNotNull("WorldType.BETA_WORLD should exist", WorldType.BETA_WORLD);
		assertNotNull("WorldType.NOSAVE_MODE should exist", WorldType.NOSAVE_MODE);
		assertNotNull("WorldType.QUEST_SPEEDRUNNING should exist", WorldType.QUEST_SPEEDRUNNING);
		assertNotNull("WorldType.PVP_ARENA should exist", WorldType.PVP_ARENA);
	}

	@Test
	public void testNormalGameModeWorldTypesExist()
	{
		assertNotNull("WorldType.MEMBERS should exist", WorldType.MEMBERS);
		assertNotNull("WorldType.SKILL_TOTAL should exist", WorldType.SKILL_TOTAL);
		assertNotNull("WorldType.PVP should exist", WorldType.PVP);
	}

	@Test
	public void testWorldTypeEnumValues()
	{
		WorldType[] types = WorldType.values();
		assertNotNull(types);
		assertTrue("Should have multiple WorldType values", types.length >= 7);

		boolean hasAllSpecialModes = true;
		WorldType[] specialModes = {
			WorldType.SEASONAL,
			WorldType.DEADMAN,
			WorldType.FRESH_START_WORLD,
			WorldType.TOURNAMENT_WORLD,
			WorldType.BETA_WORLD,
			WorldType.NOSAVE_MODE,
			WorldType.QUEST_SPEEDRUNNING,
			WorldType.PVP_ARENA
		};

		for (WorldType specialMode : specialModes)
		{
			boolean found = false;
			for (WorldType type : types)
			{
				if (type == specialMode)
				{
					found = true;
					break;
				}
			}
			if (!found)
			{
				hasAllSpecialModes = false;
				break;
			}
		}
		assertTrue("WorldType enum should contain all special game mode types", hasAllSpecialModes);
	}
}

