/**
 * The website keeps the storage items' contents now (fish barrel, log basket, gem bag, coal bag, herb sack). This
 * plays random gathering (catches with the item open or closed, full and empty messages, Fill / Empty / Check,
 * the bank and deposit box, the Charges plugin's state, loading screens and logouts) through the plugin's old
 * StorageItemMonitor and the new GameEvents side by side, and writes what GameEvents records and what the old
 * monitor uploaded (each changed tick, and what went into a deposit box) to build/oracle/storage-events.json.gz.
 * It also writes the specs (build/oracle/storage-specs.json) from the same run, so the website's data has the
 * exact item order the plugin iterated.
 */
public class StorageEventsOracleTest {
	private static final String CHARGES = "tictac7x-charges";

	private Map<Integer, String> names;
	private List<OldStorageItemSpec> specs;
	private Random r;
	private int tick;
	private GameState state;
	private final Map<Integer, Integer> inv = new LinkedHashMap<>();
	private final Map<Integer, Integer> worn = new LinkedHashMap<>();
	private final Map<String, String> charges = new HashMap<>();
	private String messageBox;
	private int selectedItem = -1;
	private final List<Object> recorded = new ArrayList<>();
	private final List<Object> uploads = new ArrayList<>();
	private final List<Object> deposits = new ArrayList<>();
	private OldStorageItemMonitor old;
	private GameEvents now;
	private Gson gson = new Gson();

	private ItemContainer container(Map<Integer, Integer> items) {
		ItemContainer c = mock(ItemContainer.class);
		when(c.getItems()).thenAnswer(i -> items.entrySet().stream().map(e -> new Item(e.getKey(), e.getValue())).toArray(Item[]::new));
		return c;
	}

	private Client client() {
		Client c = mock(Client.class);
		when(c.getTickCount()).thenAnswer(i -> tick);
		when(c.getGameState()).thenAnswer(i -> state);
		Player me = mock(Player.class);
		when(me.getName()).thenReturn("Tester");
		when(c.getLocalPlayer()).thenReturn(me);
		when(c.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(c.getItemContainer(anyInt())).thenAnswer(i -> {
			int id = i.getArgument(0);
			return id == InventoryID.INV ? container(inv) : id == InventoryID.WORN ? container(worn) : null;
		});
		Widget box = mock(Widget.class);
		when(box.getText()).thenAnswer(i -> messageBox);
		when(c.getWidget(anyInt())).thenAnswer(i -> (int) i.getArgument(0) == (193 << 16 | 2) ? box : null);
		when(c.getWidget(193, 2)).thenReturn(box);
		Widget selected = mock(Widget.class);
		when(selected.getItemId()).thenAnswer(i -> selectedItem);
		when(c.getSelectedWidget()).thenReturn(selected);
		return c;
	}

	private ItemManager itemManager() {
		ItemManager im = mock(ItemManager.class);
		when(im.canonicalize(anyInt())).thenAnswer(i -> i.getArgument(0));
		when(im.getItemComposition(anyInt())).thenAnswer(i -> {
			ItemComposition comp = mock(ItemComposition.class);
			int id = i.getArgument(0);
			when(comp.getName()).thenReturn(names.getOrDefault(id, "Item " + id));
			return comp;
		});
		return im;
	}

	private ConfigManager configManager() {
		ConfigManager cm = mock(ConfigManager.class);
		when(cm.getConfiguration(eq(CHARGES), anyString())).thenAnswer(i -> charges.get((String) i.getArgument(1)));
		when(cm.getConfigurationKeys(anyString())).thenAnswer(i -> {
			List<String> keys = new ArrayList<>();
			for (String k : charges.keySet()) {
				keys.add(CHARGES + "." + k);
			}
			return keys;
		});
		return cm;
	}

	private ClientThread clientThread() {
		ClientThread ct = mock(ClientThread.class);
		doAnswer(i -> {
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(any(Runnable.class));
		return ct;
	}

	private void setUp() {
		TestOSRSCompanionConfig noKey = new TestOSRSCompanionConfig();
		old = new OldStorageItemMonitor(client(), clientThread(), noKey, mock(OSRSCompanionApiClient.class), itemManager(), gson,
			mock(ScheduledExecutorService.class), configManager());
		OldStorageItemMonitor.sink = (source, contents) -> uploads.add(entry("t", tick, "source", source, "contents", contents));
		old.setEmptiedToDepositBoxListener(contents -> deposits.add(entry("t", tick, "contents", contents)));
		TestOSRSCompanionConfig config = new TestOSRSCompanionConfig();
		config.setOsrsCompanionAppKey("key");
		OSRSCompanionApiClient api = mock(OSRSCompanionApiClient.class);
		doAnswer(i -> {
			Map<?, ?> body = gson.fromJson((String) i.getArgument(0), Map.class);
			recorded.addAll((List<?>) body.get("events"));
			return null;
		}).when(api).sendEvents(anyString(), anyBoolean());
		SupplyCounter counter = mock(SupplyCounter.class);
		when(counter.carried()).thenReturn(new HashMap<>());
		now = new GameEvents(client(), config, api, itemManager(), counter, gson, null, configManager(), clientThread());
	}

	private static Map<String, Object> entry(Object... kv) {
		Map<String, Object> m = new LinkedHashMap<>();
		for (int i = 0; i < kv.length; i += 2) {
			m.put((String) kv[i], kv[i + 1]);
		}
		return m;
	}

	// ---- The game, to both ----

	private void inventoryChanged() {
		ItemContainerChanged e = new ItemContainerChanged(InventoryID.INV, container(inv));
		old.onItemContainerChanged(e);
		now.onItemContainerChanged(e);
	}

	private void wornChanged() {
		ItemContainerChanged e = new ItemContainerChanged(InventoryID.WORN, container(worn));
		old.onItemContainerChanged(e);
		now.onItemContainerChanged(e);
	}

	private void chat(ChatMessageType type, String text) {
		ChatMessage m = new ChatMessage(null, type, "", text, null, 0);
		old.onChatMessage(m);
		now.onChatMessage(m);
	}

	private final Map<Skill, Integer> xp = new HashMap<>();

	private void xp(Skill skill, int gained) {
		int v = xp.getOrDefault(skill, 1_000_000) + gained;
		xp.put(skill, v);
		StatChanged e = new StatChanged(skill, v, 99, 99);
		old.onStatChanged(e);
		now.onStatChanged(e);
	}

	private void click(String option, MenuAction action, int widgetItem, String target) {
		MenuOptionClicked e = mock(MenuOptionClicked.class);
		when(e.getMenuOption()).thenReturn(option);
		when(e.getMenuAction()).thenReturn(action);
		when(e.getMenuTarget()).thenReturn(target);
		Widget w = mock(Widget.class);
		when(w.getItemId()).thenReturn(widgetItem);
		when(e.getWidget()).thenReturn(w);
		old.onMenuOptionClicked(e);
		now.onMenuOptionClicked(e);
	}

	private void widget(int group, boolean open) {
		if (open) {
			WidgetLoaded e = new WidgetLoaded();
			e.setGroupId(group);
			old.onWidgetLoaded(e);
			now.onWidgetLoaded(e);
		} else {
			WidgetClosed e = new WidgetClosed(group, 0, true);
			old.onWidgetClosed(e);
			now.onWidgetClosed(e);
		}
	}

	private void config(String key, String value) {
		if (value == null) {
			charges.remove(key);
		} else {
			charges.put(key, value);
		}
		ConfigChanged e = new ConfigChanged();
		e.setGroup(CHARGES);
		e.setKey(key);
		e.setNewValue(value);
		old.onConfigChanged(e);
		now.onConfigChanged(e);
	}

	private void gameState(GameState s) {
		state = s;
		GameStateChanged e = new GameStateChanged();
		e.setGameState(s);
		old.onGameStateChanged(e);
		now.onGameStateChanged(e);
	}

	private void tick() {
		if (state == GameState.LOGGED_IN) {
			old.onGameTick(new GameTick());
			// Now and then the plugin's timed flush: the end of this tick.
			if (r.nextInt(20) == 0) {
				now.add("gt");
			}
		}
		tick++;
	}

	// ---- What a player does ----

	private int pick(List<Integer> a) {
		return a.get(r.nextInt(a.size()));
	}

	private String chatName(OldStorageItemSpec s, int id) {
		return s.chatName(names.get(id));
	}

	private void give(int id, int q) {
		inv.merge(id, q, Integer::sum);
		if (inv.get(id) <= 0) {
			inv.remove(id);
		}
	}

	private String gatherLine(OldStorageItemSpec s, int id) {
		String n = chatName(s, id);
		switch (s.source) {
			case "fish_barrel":
				return n.endsWith("s") && r.nextBoolean() ? "You catch some " + n + "." : "You catch a " + n + "!";
			case "log_basket":
				return r.nextInt(5) == 0 ? "You get some " + n + " and give them to Leela." : "You get some " + n + ".";
			case "gem_bag":
				return r.nextInt(4) == 0 ? "You steal an uncut " + n + " and add it to your gem bag." : "You just " + (r.nextBoolean() ? "mined" : "found") + " an uncut " + n + "!";
			case "coal_bag":
				return "You manage to mine some coal.";
			default:
				return "You put the Grimy " + n + " herb into your herb sack.";
		}
	}

	private String listing(OldStorageItemSpec s, Map<Integer, Integer> what) {
		StringBuilder b = new StringBuilder(s.checkPrefix);
		if (s.source.equals("coal_bag")) {
			int n = what.values().stream().mapToInt(Integer::intValue).sum();
			return "The coal bag contains " + (n == 1 ? "one piece" : n + " pieces") + " of coal.";
		}
		if (s.source.equals("gem_bag")) {
			List<String> parts = new ArrayList<>();
			what.forEach((id, q) -> {
				String n = chatName(s, id);
				parts.add((n.endsWith("y") ? n.substring(0, n.length() - 1) + "ies" : n.endsWith("z") ? n + "es" : n + "s") + ": " + q);
			});
			return String.join(" / ", parts);
		}
		List<String> parts = new ArrayList<>();
		what.forEach((id, q) -> parts.add(q + " x " + names.get(id)));
		return b.append(' ').append(String.join(", ", parts)).toString();
	}

	private void play() {
		gameState(GameState.LOGGED_IN);
		for (int step = 0; step < 250; step++) {
			OldStorageItemSpec s = specs.get(r.nextInt(specs.size()));
			List<Integer> closed = new ArrayList<>(new java.util.TreeSet<>(s.closedIds));
			List<Integer> open = new ArrayList<>(new java.util.TreeSet<>(s.openIds));
			List<Integer> accepts = new ArrayList<>(s.acceptedIds);
			int what = r.nextInt(30);
			if (what < 3) {
				// Pick up, swap open / closed or drop the container.
				for (int id : s.closedIds) {
					inv.remove(id);
					worn.remove(id);
				}
				for (int id : s.openIds) {
					inv.remove(id);
					worn.remove(id);
				}
				if (r.nextInt(5) != 0) {
					int id = r.nextBoolean() ? pick(open) : pick(closed);
					if (r.nextInt(6) == 0) {
						worn.put(id, 1);
					} else {
						inv.put(id, 1);
					}
				}
				inventoryChanged();
				wornChanged();
			} else if (what < 15) {
				// Gathering: the item goes in (open, room) or lands in the inventory.
				int id = pick(accepts.subList(0, Math.min(accepts.size(), 6)));
				int n = 1 + r.nextInt(4);
				for (int k = 0; k < n; k++) {
					chat(s.source.equals("herb_sack") || r.nextInt(4) == 0 ? ChatMessageType.GAMEMESSAGE : ChatMessageType.SPAM, gatherLine(s, id));
					if (r.nextInt(8) == 0 && !s.extraGatherMessages.isEmpty()) {
						chat(ChatMessageType.SPAM, s.extraGatherMessages.iterator().next());
					}
					if (r.nextInt(5) == 0) {
						give(id, 1);
						inventoryChanged();
					}
					if (s.consumeSkill != null && r.nextInt(6) == 0) {
						xp(s.consumeSkill, 50);
					}
					if (s.xpCreditSkill != null) {
						if (r.nextBoolean()) {
							click("Pick", MenuAction.GAME_OBJECT_SECOND_OPTION, -1, "<col=ffff>Herbs");
						}
						xp(s.xpCreditSkill, (int) Math.round(s.xpPerItem.getOrDefault(id, 30.0)) + r.nextInt(2));
					}
					if (r.nextInt(25) == 0 && !s.fullMessages.isEmpty()) {
						chat(ChatMessageType.GAMEMESSAGE, s.fullMessages.iterator().next());
					}
					tick();
				}
			} else if (what < 18) {
				// Fill: the accepted items leave the inventory.
				int id = pick(accepts.subList(0, Math.min(accepts.size(), 4)));
				give(id, 1 + r.nextInt(10));
				inventoryChanged();
				tick();
				int c = r.nextBoolean() ? pick(open) : pick(closed);
				if (r.nextBoolean()) {
					click("Fill", MenuAction.CC_OP, c, "");
				} else {
					selectedItem = id;
					click("Use", MenuAction.WIDGET_TARGET_ON_WIDGET, c, "");
				}
				tick();
				if (r.nextInt(4) != 0) {
					inv.remove(id);
					inventoryChanged();
				}
			} else if (what < 21) {
				// Empty: into the inventory, the bank or a deposit box.
				int c = r.nextBoolean() ? pick(open) : pick(closed);
				int place = r.nextInt(3);
				if (place == 1) {
					widget(InterfaceID.BANKMAIN, true);
				} else if (place == 2) {
					widget(InterfaceID.BANK_DEPOSITBOX, true);
				}
				click(r.nextBoolean() ? "Empty" : "Empty-to-bank", MenuAction.CC_OP, c, "");
				tick();
				if (place == 0) {
					give(pick(accepts.subList(0, Math.min(accepts.size(), 4))), 1 + r.nextInt(6));
					inventoryChanged();
					if (r.nextBoolean() && !s.emptiedMessages.isEmpty()) {
						chat(ChatMessageType.GAMEMESSAGE, new java.util.TreeSet<>(s.emptiedMessages).first());
					}
				} else if (r.nextBoolean()) {
					chat(ChatMessageType.GAMEMESSAGE, "You empty all of your containers into the bank.");
				}
				tick();
				widget(place == 2 ? InterfaceID.BANK_DEPOSITBOX : InterfaceID.BANKMAIN, false);
			} else if (what < 24) {
				// Check: the listing in the message box, or chat lines (the herb sack), or empty.
				int c = r.nextBoolean() ? pick(open) : pick(closed);
				click("Check", MenuAction.CC_OP, c, "");
				Map<Integer, Integer> listing = new LinkedHashMap<>();
				for (int k = r.nextInt(3); k >= 0; k--) {
					listing.merge(pick(accepts.subList(0, Math.min(accepts.size(), 5))), 1 + r.nextInt(20), Integer::sum);
				}
				if (r.nextInt(6) == 0) {
					chat(ChatMessageType.GAMEMESSAGE, new java.util.TreeSet<>(s.checkEmptyMessages).first());
				} else if (s.source.equals("herb_sack")) {
					chat(ChatMessageType.GAMEMESSAGE, s.checkPrefix);
					listing.forEach((id, q) -> chat(ChatMessageType.GAMEMESSAGE, q + " x " + names.get(id)));
				} else if (r.nextBoolean()) {
					messageBox = listing(s, listing);
					widget(193, true);
				} else {
					chat(ChatMessageType.GAMEMESSAGE, listing(s, listing));
				}
				tick();
			} else if (what < 25) {
				// The Charges plugin wrote its exact state.
				String key = s.source + "_storage";
				StringBuilder json = new StringBuilder("[");
				for (int k = r.nextInt(3); k > 0; k--) {
					json.append(json.length() > 1 ? "," : "").append("{\"itemId\":").append(pick(accepts)).append(",\"quantity\":").append(r.nextInt(30)).append('}');
				}
				config(key, r.nextInt(8) == 0 ? "not json" : json.append(']').toString());
			} else if (what < 26) {
				gameState(GameState.LOADING);
				tick();
				gameState(GameState.LOGGED_IN);
			} else if (what < 27) {
				gameState(GameState.LOGIN_SCREEN);
				tick();
				tick();
				gameState(GameState.LOGGED_IN);
			} else {
				for (int k = 1 + r.nextInt(5); k > 0; k--) {
					tick();
				}
			}
			tick();
		}
		gameState(GameState.LOGIN_SCREEN);
	}

	@Test
	public void writeOracle() throws Exception {
		names = new HashMap<>();
		Map<String, String> raw = gson.fromJson(new InputStreamReader(getClass().getResourceAsStream("storage-names.json"), StandardCharsets.UTF_8),
			new TypeToken<Map<String, String>>() { }.getType());
		raw.forEach((k, v) -> names.put(Integer.parseInt(k), v));
		specs = OldStorageItemSpec.all();
		new StorageSpecExportTest().writeSpecs();

		List<Map<String, Object>> cases = new ArrayList<>();
		for (int n = 0; n < 60; n++) {
			r = new Random(20261012L + n);
			tick = 5000;
			state = GameState.LOGIN_SCREEN;
			inv.clear();
			worn.clear();
			charges.clear();
			xp.clear();
			recorded.clear();
			uploads.clear();
			deposits.clear();
			setUp();
			play();
			// What GameEvents still holds (not flushed yet).
			Field f = GameEvents.class.getDeclaredField("buffer");
			f.setAccessible(true);
			recorded.addAll(gson.fromJson(gson.toJson(f.get(now)), List.class));
			Field t = OldStorageItemMonitor.class.getDeclaredField("tracked");
			t.setAccessible(true);
			Map<String, Object> finalContents = new LinkedHashMap<>();
			for (Object tracked : (List<?>) t.get(old)) {
				Field l = tracked.getClass().getDeclaredField("ledger");
				l.setAccessible(true);
				OldStorageItemLedger ledger = (OldStorageItemLedger) l.get(tracked);
				finalContents.put(ledger.spec.source, ledger.contents());
			}
			cases.add(entry("events", new ArrayList<>(recorded), "uploads", gson.fromJson(gson.toJson(uploads), List.class),
				"deposits", gson.fromJson(gson.toJson(deposits), List.class), "final", gson.fromJson(gson.toJson(finalContents), Map.class)));
		}
		Path out = Paths.get("build", "oracle", "storage-events.json.gz");
		Files.createDirectories(out.getParent());
		try (Writer w = new OutputStreamWriter(new GZIPOutputStream(Files.newOutputStream(out)), StandardCharsets.UTF_8)) {
			new GsonBuilder().serializeNulls().create().toJson(cases, w);
		}
		long ups = cases.stream().mapToLong(c -> ((List<?>) c.get("uploads")).size()).sum();
		long deps = cases.stream().mapToLong(c -> ((List<?>) c.get("deposits")).size()).sum();
		System.out.println("storage oracle: " + cases.size() + " sessions, " + ups + " uploads, " + deps + " deposit-box empties");
	}
}

package com.osrscompanion;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class StorageItemLedgerTest {
	private static final Map<Integer, String> NAMES = new HashMap<>();

	static {
		NAMES.put(ItemID.RAW_ANGLERFISH, "Raw anglerfish");
		NAMES.put(ItemID.RAW_SHARK, "Raw shark");
		NAMES.put(ItemID.RAW_SHRIMP, "Raw shrimps");
		NAMES.put(ItemID.MORT_SLIMEY_EEL, "Raw slimy eel");
		NAMES.put(ItemID.TBWT_RAW_KARAMBWAN, "Raw karambwan");
		NAMES.put(ItemID.OAK_LOGS, "Oak logs");
		NAMES.put(ItemID.YEW_LOGS, "Yew logs");
		NAMES.put(ItemID.UNCUT_SAPPHIRE, "Uncut sapphire");
		NAMES.put(ItemID.UNCUT_RUBY, "Uncut ruby");
		NAMES.put(ItemID.UNCUT_RED_TOPAZ, "Uncut red topaz");
		NAMES.put(ItemID.COAL, "Coal");
		NAMES.put(ItemID.UNIDENTIFIED_RANARR, "Grimy ranarr weed");
		NAMES.put(ItemID.UNIDENTIFIED_GUAM, "Grimy guam leaf");
	}

	private static OldStorageItemLedger ledger(OldStorageItemSpec spec) {
		return new OldStorageItemLedger(spec, id -> NAMES.getOrDefault(id, "Item " + id));
	}

	private static Map<Integer, Integer> qty(int id, int q) {
		Map<Integer, Integer> m = new HashMap<>();
		m.put(id, q);
		return m;
	}

	@Test
	public void catchesWithOpenBarrelAreCreditedPerFish() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		assertTrue(l.settle(true));
		l.onGatherMessage("You catch a shark.");
		l.onGatherMessage("Rada's blessing enabled you to catch an extra fish.");
		l.settle(true);
		l.onGatherMessage("You catch some shrimps.");
		l.onGatherMessage("You catch a slimy swamp eel.");
		l.onGatherMessage("You catch a Karambwan.");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.RAW_ANGLERFISH));
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.RAW_SHARK));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.RAW_SHRIMP));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.MORT_SLIMEY_EEL));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.TBWT_RAW_KARAMBWAN));
	}

	@Test
	public void closedBarrelOrFishLandingInInventoryIsNotCredited() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		assertFalse(l.settle(false));
		assertTrue(l.contents().isEmpty());

		// Open, but the fish showed up in the inventory: the barrel is full.
		l.onGatherMessage("You catch an anglerfish!");
		l.onInventoryDiff(qty(ItemID.RAW_ANGLERFISH, 1), Map.of(), false, false);
		assertFalse(l.settle(true));
		assertTrue(l.isFull());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void infernalHarpoonCookedFishIsNotStored() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.onXp(Skill.COOKING, 230);
		l.settle(true);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void fillMovesInventoryFishInAndCapacityCaps() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.fishBarrel());
		l.onInventoryDiff(Map.of(), qty(ItemID.RAW_SHARK, 20), true, false);
		l.onInventoryDiff(Map.of(), qty(ItemID.RAW_ANGLERFISH, 20), true, false);
		l.settle(false);
		assertEquals(Integer.valueOf(20), l.contents().get(ItemID.RAW_SHARK));
		assertEquals(Integer.valueOf(8), l.contents().get(ItemID.RAW_ANGLERFISH));
		assertEquals(28, l.total());
		assertTrue(l.isFull());
		// Without a recent Fill click, fish leaving the inventory is a drop / use.
		l.onInventoryDiff(Map.of(), qty(ItemID.RAW_SHARK, 5), false, false);
		l.settle(false);
		assertEquals(28, l.total());
	}

	@Test
	public void emptyingIntoTheBankClearsAndCheckResyncs() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertTrue(l.onGameMessage("You empty all of your containers into the bank."));
		assertTrue(l.settle(true));
		assertTrue(l.contents().isEmpty());

		assertTrue(l.onCheckText("The barrel contains: 5 x Raw anglerfish,<br>3 x Raw shark"));
		assertTrue(l.settle(false));
		assertEquals(Integer.valueOf(5), l.contents().get(ItemID.RAW_ANGLERFISH));
		assertEquals(Integer.valueOf(3), l.contents().get(ItemID.RAW_SHARK));
		assertTrue(l.onCheckText("The barrel is empty."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
		// Unrelated text is ignored.
		assertFalse(l.onCheckText("You have 3 x Raw shark in your bank."));
		assertFalse(l.onGameMessage("Your Ring of Recoil has shattered."));
	}

	@Test
	public void fullMessageStopsCreditingUntilEmptied() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		l.onGameMessage("The barrel is full. It may be emptied at a bank.");
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertEquals(1, l.total());
		l.onGameMessage("Your containers are already empty.");
		l.settle(true);
		assertTrue(l.contents().isEmpty());
		assertFalse(l.isFull());
	}

	@Test
	public void logBasketCountsChoppedLogsAndPartialEmpties() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.logBasket());
		l.onGatherMessage("You get some oak logs.");
		l.onGatherMessage("Your Kandarin headgear provides you with an additional log.");
		l.settle(true);
		l.onGatherMessage("You get some yew logs.");
		l.onXp(Skill.FIREMAKING, 200); // infernal axe burnt it
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.OAK_LOGS));
		assertNull(l.contents().get(ItemID.YEW_LOGS));
		// "Empty" then one log appears in the inventory.
		l.onInventoryDiff(qty(ItemID.OAK_LOGS, 1), Map.of(), false, true);
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.OAK_LOGS));
		assertTrue(l.onGameMessage("You empty your basket into the bank."));
		l.settle(true);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void gemBagParsesMinedGemsAndTheCheckMessage() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.gemBag());
		l.onGatherMessage("You just mined a sapphire!");
		l.onGatherMessage("You just found a ruby!");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_SAPPHIRE));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_RUBY));
		assertTrue(l.onGameMessage("Sapphires: 12 / Rubies: 3 / Red topazes: 2"));
		l.settle(false);
		assertEquals(Integer.valueOf(12), l.contents().get(ItemID.UNCUT_SAPPHIRE));
		assertEquals(Integer.valueOf(3), l.contents().get(ItemID.UNCUT_RUBY));
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNCUT_RED_TOPAZ));
		assertTrue(l.onGameMessage("You empty your gem bag into the bank."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void coalBagCountsMinedCoalAndParsesItsCheckMessage() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.coalBag());
		l.onGatherMessage("You manage to mine some coal.");
		l.onGatherMessage("Your Celestial ring allows you to mine an additional ore.");
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.COAL));
		assertTrue(l.onGameMessage("The coal bag contains 27 pieces of coal."));
		l.settle(false);
		assertEquals(Integer.valueOf(27), l.contents().get(ItemID.COAL));
		assertTrue(l.onGameMessage("The coal bag contains one piece of coal."));
		l.settle(false);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.COAL));
		assertTrue(l.onGameMessage("The coal bag is now empty."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void herbSackCreditsHarvestsByFarmingXpOnly() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.herbSack());
		// Ranarr harvest: 30.5 XP shows as 30 or 31 with nothing entering the inventory.
		l.onXp(Skill.FARMING, 31);
		l.settle(true);
		l.onXp(Skill.FARMING, 30);
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		// An allotment harvest changes the inventory: no herb credit even when the XP happens to match.
		l.onXp(Skill.FARMING, 12);
		l.onInventoryDiff(Map.of(), Map.of(), false, false);
		l.settle(true);
		assertNull(l.contents().get(ItemID.UNIDENTIFIED_GUAM));
		// Closed sack: the herb lands in the inventory instead.
		l.onXp(Skill.FARMING, 30);
		l.settle(false);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		// Check lists one herb per line until the tick settles.
		assertTrue(l.onGameMessage("You look in your herb sack and see:"));
		assertTrue(l.onGameMessage("7 x Grimy ranarr weed"));
		assertTrue(l.onGameMessage("2 x Grimy guam leaf"));
		l.settle(true);
		assertEquals(Integer.valueOf(7), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_GUAM));
	}

	@Test
	public void unknownLedgerSeedsFromTheServerOnFirstSignalOnly() {
		Map<Integer, Integer> server = new HashMap<>();
		server.put(ItemID.RAW_ANGLERFISH, 2);
		OldStorageItemLedger l = new OldStorageItemLedger(OldStorageItemSpec.fishBarrel(),
				id -> NAMES.getOrDefault(id, "Item " + id), () -> server);
		assertFalse(l.isKnown());
		assertFalse(l.settle(true));
		assertTrue("nothing observed yet", l.contents().isEmpty());
		// First catch of the session builds on the server's 2.
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertTrue(l.isKnown());
		assertEquals(Integer.valueOf(3), l.contents().get(ItemID.RAW_ANGLERFISH));
		// Next session: unknown again until a signal, and re-seeded from whatever the server has then.
		l.resetSession();
		server.put(ItemID.RAW_ANGLERFISH, 10);
		assertFalse(l.isKnown());
		l.onGameMessage("The barrel is full. It may be emptied at a bank.");
		assertTrue(l.isKnown());
		assertEquals(Integer.valueOf(10), l.contents().get(ItemID.RAW_ANGLERFISH));
	}

	@Test
	public void singularisesCheckNames() {
		assertEquals("sapphire", OldStorageItemLedger.singular("Sapphires"));
		assertEquals("ruby", OldStorageItemLedger.singular("Rubies"));
		assertEquals("red topaz", OldStorageItemLedger.singular("Red topazes"));
		assertEquals("opal", OldStorageItemLedger.singular("Opal"));
	}

	@Test
	public void herbSackCountsPickupsAndPickedPatchesByName() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.herbSack());
		l.onGatherMessage("You put the Grimy ranarr weed herb into your herb sack.");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		// Harvest: the patch clicked names the herb, the XP confirms it.
		l.onPickTarget("<col=ffff>Herbs</col>");
		l.onPickTarget("Ranarr weed");
		l.onXp(Skill.FARMING, 31);
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
	}

	@Test
	public void outsideStateResyncsExactly() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		l.resync(qty(ItemID.RAW_SHARK, 9));
		assertTrue(l.settle(false));
		assertEquals(Integer.valueOf(9), l.contents().get(ItemID.RAW_SHARK));
		assertNull(l.contents().get(ItemID.RAW_ANGLERFISH));
		assertTrue(l.isKnown());
		// Emptied to a deposit box with the item's own option.
		assertTrue(l.onGameMessage("You empty the barrel."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void gemBagCountsThievingAndEmptiesForEveryVariant() {
		OldStorageItemLedger l = ledger(OldStorageItemSpec.gemBag());
		l.onGatherMessage("You steal an uncut sapphire and add it to your gem sack.");
		l.onGatherMessage("You put the stolen Uncut ruby into your gem bag.");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_SAPPHIRE));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_RUBY));
		assertTrue(l.onGameMessage("You empty the gem sack into the bank."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}
}

package com.osrscompanion;

import com.google.gson.GsonBuilder;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * The storage items' specs as the plugin had them (ids, capacities, chat patterns and messages), written to
 * build/oracle/storage-specs.json for the website's src/data/runelite/storageItems.json, so nothing is copied by hand.
 */
public class StorageSpecExportTest {
	@Test
	public void writeSpecs() throws Exception {
		Map<Integer, String> constants = new LinkedHashMap<>();
		for (Field f : ItemID.class.getFields()) {
			if (Modifier.isStatic(f.getModifiers()) && f.getType() == int.class) {
				constants.putIfAbsent(f.getInt(null), f.getName());
			}
		}
		List<Map<String, Object>> specs = new ArrayList<>();
		Map<Integer, String> ids = new LinkedHashMap<>();
		for (OldStorageItemSpec s : OldStorageItemSpec.all()) {
			Map<String, Object> m = new LinkedHashMap<>();
			m.put("source", s.source);
			m.put("closed", new TreeSet<>(s.closedIds));
			m.put("open", new TreeSet<>(s.openIds));
			m.put("accepts", new ArrayList<>(s.acceptedIds));
			m.put("capacity", s.capacity);
			m.put("perItem", s.perItemCapacity);
			List<String> patterns = new ArrayList<>();
			for (Pattern p : s.gatherPatterns) {
				patterns.add(p.pattern());
			}
			m.put("gather", patterns);
			m.put("extraGather", new TreeSet<>(s.extraGatherMessages));
			m.put("emptied", new TreeSet<>(s.emptiedMessages));
			m.put("emptiedPrefixes", new TreeSet<>(s.emptiedPrefixes));
			m.put("full", new TreeSet<>(s.fullMessages));
			m.put("checkPrefix", s.checkPrefix);
			m.put("checkEmpty", new TreeSet<>(s.checkEmptyMessages));
			m.put("consumeSkill", s.consumeSkill == null ? null : s.consumeSkill.getName());
			m.put("xpCreditSkill", s.xpCreditSkill == null ? null : s.xpCreditSkill.getName());
			m.put("xpPerItem", s.xpPerItem);
			m.put("stripPrefix", s.namePrefixToStrip);
			m.put("aliases", s.nameAliases);
			specs.add(m);
			for (int id : s.acceptedIds) {
				ids.put(id, constants.get(id));
			}
		}
		Map<String, Object> out = new LinkedHashMap<>();
		out.put("specs", specs);
		out.put("ids", ids);
		Path p = Paths.get("build", "oracle", "storage-specs.json");
		Files.createDirectories(p.getParent());
		Files.write(p, new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().create().toJson(out).getBytes(StandardCharsets.UTF_8));
	}
}

package com.osrscompanion;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests for {@link SyncGuard#isCompleteAppKeyEntry}, which decides whether a
 * ConfigChanged event should trigger an auto full-sync.
 */
public class SyncGuardTest
{
	private static final String FULL_KEY = "ABCDEFGHJKLMNPQR"; // 16 chars

	@Test
	public void testCompleteKeyInOSRSCompanionGroupTriggers()
	{
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			OSRSCompanionConfig.CONFIG_GROUP, OSRSCompanionConfig.APP_KEY, FULL_KEY));
	}

	@Test
	public void testKeyWithSurroundingWhitespaceIsTrimmed()
	{
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			OSRSCompanionConfig.CONFIG_GROUP, OSRSCompanionConfig.APP_KEY, "  " + FULL_KEY + "  "));
	}

	@Test
	public void testShortPartialKeyDoesNotTrigger()
	{
		// 7 chars, below the minimum length.
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			OSRSCompanionConfig.CONFIG_GROUP, OSRSCompanionConfig.APP_KEY, "ABCDEFG"));
	}

	@Test
	public void testMinLengthKeyTriggers()
	{
		// Exactly at the minimum length (boundary).
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			OSRSCompanionConfig.CONFIG_GROUP, OSRSCompanionConfig.APP_KEY, "ABCDEFGH"));
	}

	@Test
	public void testLongerThanCurrentKeyStillTriggers()
	{
