package com.osrscompanion;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WebVersionWatcherTest {
	private static final long NOW = 1_000_000L;

	@Test
	public void checksOnlyWhenLoggedInWithAKeyAndNoRecentBatch() {
		assertTrue(WebVersionWatcher.shouldCheck(true, true, "Zezima", NOW, Long.MIN_VALUE));
		assertTrue(WebVersionWatcher.shouldCheck(true, true, "Zezima", NOW, NOW - WebVersionWatcher.RECENT_BATCH_MS));
		assertFalse(WebVersionWatcher.shouldCheck(true, true, "Zezima", NOW, NOW - 5_000));
		assertFalse(WebVersionWatcher.shouldCheck(false, true, "Zezima", NOW, Long.MIN_VALUE));
		assertFalse(WebVersionWatcher.shouldCheck(true, false, "Zezima", NOW, Long.MIN_VALUE));
		assertFalse(WebVersionWatcher.shouldCheck(true, true, null, NOW, Long.MIN_VALUE));
	}

	@Test
	public void heartbeatWhenNothingReachedTheWebsiteForHeartbeatMs() {
		long beat = LiveActivityMonitor.HEARTBEAT_MS;
		assertTrue(WebVersionWatcher.shouldHeartbeat(NOW, Long.MIN_VALUE, Long.MIN_VALUE));
		assertFalse(WebVersionWatcher.shouldHeartbeat(NOW, NOW - beat + 1, Long.MIN_VALUE));
		assertTrue(WebVersionWatcher.shouldHeartbeat(NOW, NOW - beat, Long.MIN_VALUE));
		// A heartbeat that got no answer (server down) still waits HEARTBEAT_MS before the next one.
		assertFalse(WebVersionWatcher.shouldHeartbeat(NOW, NOW - beat - 60_000, NOW - 5_000));
		assertTrue(WebVersionWatcher.shouldHeartbeat(NOW, NOW - beat - 60_000, NOW - beat));
	}
}

package com.osrscompanion;

import java.awt.Canvas;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;

/**
 * Plays the mouse and keyboard on the in-game windows for the UI golden tests: finds their clickable areas
 * (the windows keep them in a {@code hits} list after each render), hovers, clicks, scrolls, presses keys.
 */
final class WindowDriver {
	private static final Canvas SOURCE = new Canvas();

	private WindowDriver() {
	}

	/** A clickable area of the last render, with its tooltip (null when it has none). */
	static final class Area {
		final Rectangle bounds;
		final String tooltip;

		Area(Rectangle bounds, String tooltip) {
			this.bounds = bounds;
			this.tooltip = tooltip;
		}

		Point centre() {
			return new Point(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2);
		}

		@Override
		public String toString() {
			return bounds + " " + tooltip;
		}
	}

	static List<Area> areas(Object window) {
		List<Area> out = new ArrayList<>();
		for (Object hit : (List<?>) get(window, "hits")) {
			Rectangle r = null;
			String tip = null;
			for (Field f : hit.getClass().getDeclaredFields()) {
				f.setAccessible(true);
				try {
					Object v = f.get(hit);
					if (v instanceof Rectangle && r == null) {
						r = (Rectangle) v;
					} else if (v instanceof String && tip == null) {
						tip = (String) v;
					}
				} catch (IllegalAccessException e) {
					throw new IllegalStateException(e);
				}
			}
			out.add(new Area(r, tip));
		}
		return out;
	}

	/** The first area whose tooltip starts with the text. */
	static Area area(Object window, String tooltipStart) {
		for (Area a : areas(window)) {
			if (a.tooltip != null && a.tooltip.startsWith(tooltipStart)) {
				return a;
			}
		}
		throw new AssertionError("No area with tooltip '" + tooltipStart + "' in " + areas(window));
	}

	static void move(Object window, Point p) {
		((MouseListener) window).mouseMoved(new MouseEvent(SOURCE, MouseEvent.MOUSE_MOVED, 0, 0, p.x, p.y, 0, false));
	}

	static void click(Object window, Point p) {
		MouseListener l = (MouseListener) window;
		l.mousePressed(new MouseEvent(SOURCE, MouseEvent.MOUSE_PRESSED, 0, InputEvent.BUTTON1_DOWN_MASK, p.x, p.y, 1, false, MouseEvent.BUTTON1));
		l.mouseReleased(new MouseEvent(SOURCE, MouseEvent.MOUSE_RELEASED, 0, 0, p.x, p.y, 1, false, MouseEvent.BUTTON1));
	}

	static void scroll(Object window, Point p, int notches) {
		((MouseWheelListener) window).mouseWheelMoved(new MouseWheelEvent(SOURCE, MouseEvent.MOUSE_WHEEL, 0, 0, p.x, p.y, 0, false,
			MouseWheelEvent.WHEEL_UNIT_SCROLL, 3, notches));
	}

	static void key(Object window, int keyCode) {
		((KeyListener) window).keyPressed(new KeyEvent(SOURCE, KeyEvent.KEY_PRESSED, 0, 0, keyCode, KeyEvent.CHAR_UNDEFINED));
	}

	/** The field on the object's class or one it extends (the windows keep theirs in {@link GameWindow}). */
	private static Field field(Object target, String name) throws NoSuchFieldException {
		for (Class<?> c = target.getClass(); c != null; c = c.getSuperclass()) {
			try {
				Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				return f;
			} catch (NoSuchFieldException e) {
				// look in the class it extends
			}
		}
		throw new NoSuchFieldException(name);
	}

	static Object get(Object target, String field) {
		try {
			return field(target, field).get(target);
		} catch (ReflectiveOperationException e) {
			throw new IllegalStateException(e);
		}
	}

	static void set(Object target, String field, Object value) {
		try {
			field(target, field).set(target, value);
		} catch (ReflectiveOperationException e) {
			throw new IllegalStateException(e);
		}
	}
}

package com.osrscompanion.api;

import com.google.gson.Gson;
import com.osrscompanion.OSRSCompanionConfig;
import com.osrscompanion.model.BankSyncPayload;
import com.osrscompanion.model.PlayerSkillsSyncPayload;
import com.osrscompanion.model.Roadmap;
import com.osrscompanion.model.RoadmapList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests that OSRSCompanionApiClient handles config correctly and payload structure.
 */
public class OSRSCompanionApiClientTest {
	private static OSRSCompanionConfig emptyKeyConfig() {
		com.osrscompanion.TestOSRSCompanionConfig c = new com.osrscompanion.TestOSRSCompanionConfig();
		c.setOsrsCompanionAppKey("");
		return c;
	}

	@Test
	public void testSendWithEmptyAppKeyDoesNotThrow() {
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(emptyKeyConfig(), new Gson(), new OkHttpClient());
		client.sendTimeTracking("{\"player_username\":\"TestPlayer\",\"profile\":{}}", "TestPlayer");
		// Should not throw; with empty key it returns early
	}

	@Test
	public void testSendPlayerSkillsWithEmptyAppKeyDoesNotThrow() {
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(emptyKeyConfig(), new Gson(), new OkHttpClient());
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		skills.put("Attack", new PlayerSkillsSyncPayload.SkillData(75, 1200000));
		skills.put("Defence", new PlayerSkillsSyncPayload.SkillData(70, 800000));
		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload("TestPlayer", skills, 145, 85);
		client.sendPlayerSkillsSync(payload);
		// Should not throw; with empty key it returns early
	}

	@Test
	public void testSendBankSyncWithEmptyAppKeyDoesNotThrow() {
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(emptyKeyConfig(), new Gson(), new OkHttpClient());
		Map<String, java.util.List<BankSyncPayload.BankItem>> items = new HashMap<>();
		items.put("bank", Arrays.asList(new BankSyncPayload.BankItem(4151, 1)));
		BankSyncPayload payload = new BankSyncPayload("TestPlayer", items);
		client.sendBankSync(payload);
		// Should not throw; with empty key it returns early
	}

	@Test
	public void testPlayerSkillsPayloadStructure() {
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		skills.put("Attack", new PlayerSkillsSyncPayload.SkillData(75, 1200000));
		skills.put("Defence", new PlayerSkillsSyncPayload.SkillData(70, 800000));
		skills.put("Strength", new PlayerSkillsSyncPayload.SkillData(80, 2000000));
		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload("TestPlayer", skills, 225, 95);
		String json = payload.toJson(new Gson());

		assertNotNull(json);
		assertTrue(json.contains("\"player\":\"TestPlayer\""));
		assertTrue(json.contains("\"skills\""));
		/* API expects skills as {"SkillName": {"level": N, "current_xp": N}} */
		assertTrue(json.contains("Attack"));
		assertTrue(json.contains("\"level\":75"));
		assertTrue(json.contains("\"level\":70"));
		assertTrue(json.contains("\"level\":80"));
		assertTrue(json.contains("\"current_xp\":1200000"));
		assertTrue(json.contains("\"current_xp\":800000"));
		assertTrue(json.contains("\"current_xp\":2000000"));
	}

	@Test
	public void testGetRoadmapsWithEmptyKeyCallsOnError() {
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(emptyKeyConfig(), new Gson(), new OkHttpClient());
		AtomicReference<String> error = new AtomicReference<>();
		AtomicBoolean success = new AtomicBoolean(false);
		client.getRoadmaps("TestPlayer", new OSRSCompanionApiClient.RoadmapCallback<RoadmapList>() {
			@Override
			public void onSuccess(RoadmapList result) {
				success.set(true);
			}

			@Override
			public void onError(String message) {
				error.set(message);
			}
		});
		// No key => synchronous onError, no network call.
		assertFalse(success.get());
		assertNotNull(error.get());
	}

	@Test
	public void testRecomputeRoadmapWithEmptyKeyCallsOnError() {
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(emptyKeyConfig(), new Gson(), new OkHttpClient());
		AtomicReference<String> error = new AtomicReference<>();
		client.recomputeRoadmap(1, "TestPlayer", new OSRSCompanionApiClient.RoadmapCallback<Roadmap>() {
			@Override
			public void onSuccess(Roadmap result) {
			}

			@Override
			public void onError(String message) {
				error.set(message);
			}
		});
		assertEquals("No OSRS Companion App Key configured", error.get());
	}

	@Test
	public void testIsDuplicateReturnsFalseWhenPreviousNull() {
		/* First-ever send for a syncType always goes out. */
		assertFalse(OSRSCompanionApiClient.isDuplicate(null, "{\"timers\":[]}"));
	}

	@Test
	public void testIsDuplicateReturnsTrueWhenBytesEqual() {
		String body = "{\"timers\":[{\"timer_type\":\"tree\"}]}";
		assertTrue(OSRSCompanionApiClient.isDuplicate(body, body));
	}

	@Test
	public void testIsDuplicateReturnsFalseWhenBytesDiffer() {
		/* Bodies differing only by player_username are not duplicates (multi-account safety). */
		String bodyA = "{\"player_username\":\"PlayerA\",\"timers\":[]}";
		String bodyB = "{\"player_username\":\"PlayerB\",\"timers\":[]}";
		assertFalse(OSRSCompanionApiClient.isDuplicate(bodyA, bodyB));
	}

	@Test
	public void testDuplicateSendWithEmptyAppKeyDoesNotThrow() {
		/* The dedupe guard runs after the app-key guard, so the empty-key path is unaffected. */
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(emptyKeyConfig(), new Gson(), new OkHttpClient());
		String json = "{\"player_username\":\"TestPlayer\",\"profile\":{}}";
		client.sendTimeTracking(json, "TestPlayer");
		client.sendTimeTracking(json, "TestPlayer");
		// Should not throw; with empty key both return early before the dedupe check
	}

	/** A base client that answers every call itself and records what it was sent. */
	private static OkHttpClient recordingClient(AtomicReference<Request> sent, CountDownLatch done) {
		return new OkHttpClient.Builder()
				.addInterceptor(chain -> {
					sent.set(chain.request());
					done.countDown();
					return new Response.Builder()
							.request(chain.request())
							.protocol(Protocol.HTTP_1_1)
							.code(200)
							.message("OK")
							.body(ResponseBody.create(null, "{\"roadmaps\":[]}"))
							.build();
				})
				.build();
	}

	@Test
	public void everyRequestCarriesThePluginVersion() throws InterruptedException {
		com.osrscompanion.TestOSRSCompanionConfig config = new com.osrscompanion.TestOSRSCompanionConfig();
		config.setOsrsCompanionAppKey("test-key");
		AtomicReference<Request> sent = new AtomicReference<>();
		CountDownLatch done = new CountDownLatch(1);
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(config, new Gson(), recordingClient(sent, done));

		client.getRoadmaps("Zezima", new OSRSCompanionApiClient.RoadmapCallback<RoadmapList>() {
			@Override
			public void onSuccess(RoadmapList result) {
			}

			@Override
			public void onError(String message) {
			}
		});

		assertTrue(done.await(5, TimeUnit.SECONDS));
		assertEquals(OSRSCompanionApiClient.PLUGIN_VERSION, sent.get().header(OSRSCompanionApiClient.VERSION_HEADER));
		assertEquals("test-key", sent.get().header("X-RuneLite-Key"));
	}

	@Test
	public void pluginVersionIsHeaderSafe() {
		assertTrue(OSRSCompanionApiClient.PLUGIN_VERSION.matches("[0-9A-Za-z._-]{1,32}"));
	}

	@Test
	public void webVersionChangeIsReportedButNotTheFirstValue() {
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(emptyKeyConfig(), new Gson(), new OkHttpClient());
		java.util.concurrent.atomic.AtomicInteger changes = new java.util.concurrent.atomic.AtomicInteger();
		client.setWebVersionChangedListener(changes::incrementAndGet);
		client.observeWebVersion(4);
		assertEquals("first value is the baseline", 0, changes.get());
		client.observeWebVersion(4);
		assertEquals(0, changes.get());
		client.observeWebVersion(5);
		assertEquals(1, changes.get());
		client.resetWebVersion();
		client.observeWebVersion(9);
		assertEquals("after logout the first value is a new baseline", 1, changes.get());
	}

	@Test
	public void activityRidesAlongWithABatchOfTheSamePlayerOnly() {
		com.osrscompanion.TestOSRSCompanionConfig c = new com.osrscompanion.TestOSRSCompanionConfig();
		c.setOsrsCompanionAppKey("abcdefgh");
		OSRSCompanionApiClient client = new OSRSCompanionApiClient(c, new Gson(), new OkHttpClient());
		String base = OSRSCompanionApiClient.BASE_URL;
		SyncOutbox.Item bank = new SyncOutbox.Item(base, "abcdefgh", "/api/runelite/bank/", "POST",
			"{\"player_username\":\"Zezima\"}", "bank", null, false, false, null);
		// No source: nothing.
		assertEquals(null, client.activityExtra(Collections.singletonList(bank)));
		client.setActivitySource(() -> "{\"player_username\":\"Zezima\",\"state\":\"online\"}");
		SyncOutbox.Item extra = client.activityExtra(Collections.singletonList(bank));
		assertNotNull(extra);
		assertEquals(OSRSCompanionApiClient.ACTIVITY_ENDPOINT, extra.getPath());
		assertEquals(OSRSCompanionApiClient.ACTIVITY_LABEL, extra.getLabel());
		// A batch that already has a status, or is for another player, gets none.
		assertEquals(null, client.activityExtra(Arrays.asList(bank, extra)));
		client.setActivitySource(() -> "{\"player_username\":\"Other\"}");
		assertEquals(null, client.activityExtra(Collections.singletonList(bank)));
		// Nothing to share (logged out, switched off): none.
		client.setActivitySource(() -> null);
		assertEquals(null, client.activityExtra(Collections.singletonList(bank)));
	}
}

package com.osrscompanion.api;

import com.google.gson.Gson;
import com.osrscompanion.FakeScheduledExecutorService;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SyncOutboxTest {
	/** Records what was sent; answers only when the test says so. */
	private static final class FakeSender implements SyncOutbox.Sender {
		final List<List<SyncOutbox.Item>> batches = new ArrayList<>();
		final List<SyncOutbox.BatchCallback> batchCallbacks = new ArrayList<>();
		final List<SyncOutbox.Item> singles = new ArrayList<>();
		final List<SyncOutbox.SingleCallback> singleCallbacks = new ArrayList<>();

		@Override
		public void sendBatch(String baseUrl, String appKey, List<SyncOutbox.Item> items, SyncOutbox.BatchCallback callback) {
			batches.add(new ArrayList<>(items));
			batchCallbacks.add(callback);
		}

		@Override
		public void sendOne(SyncOutbox.Item item, SyncOutbox.SingleCallback callback) {
			singles.add(item);
			singleCallbacks.add(callback);
		}

		SyncOutbox.BatchCallback lastBatch() {
			return batchCallbacks.get(batchCallbacks.size() - 1);
		}

		/** Answers the last batch with 200 for every request. */
		void okLast(Integer webVersion) {
			List<SyncOutbox.Item> items = batches.get(batches.size() - 1);
			lastBatch().onResponse(200, Collections.nCopies(items.size(), 200), webVersion);
		}
	}

	private FakeScheduledExecutorService executor;
	private FakeSender sender;
	private SyncOutbox outbox;
	private List<String> succeeded;

	@Before
	public void setUp() {
		executor = new FakeScheduledExecutorService();
		sender = new FakeSender();
		outbox = new SyncOutbox(sender, executor, () -> executor.nowMs);
		succeeded = new ArrayList<>();
	}

	private SyncOutbox.Item item(String path, String body, String key, boolean priority) {
		String tag = path + body;
		return new SyncOutbox.Item("https://x", "k", path, "POST", body, path, key, priority, false, () -> succeeded.add(tag));
	}

	private void advance(long ms) {
		executor.runDue(executor.nowMs + ms);
	}

	private static List<String> bodies(List<SyncOutbox.Item> items) {
		List<String> out = new ArrayList<>();
		for (SyncOutbox.Item i : items) {
			out.add(i.getBody());
		}
		return out;
	}

	@Test
	public void nothingQueuedSendsNothing() {
		advance(60_000);
		outbox.requestFlush();
		outbox.flushNow();
		assertTrue(sender.batches.isEmpty());
		assertTrue(sender.singles.isEmpty());
	}

	@Test
	public void batchesEverythingQueuedWithinTheIntervalInOrder() {
		outbox.enqueue(item("/a", "{\"n\":1}", null, false));
		advance(3_000);
		outbox.enqueue(item("/b", "{\"n\":2}", null, false));
		advance(6_000);
		assertTrue("not before the interval", sender.batches.isEmpty());
		advance(1_000);
		assertEquals(1, sender.batches.size());
		assertEquals(Arrays.asList("{\"n\":1}", "{\"n\":2}"), bodies(sender.batches.get(0)));
		sender.okLast(null);
		assertEquals(Arrays.asList("/a{\"n\":1}", "/b{\"n\":2}"), succeeded);
		assertEquals(0, outbox.size());
	}

	@Test
	public void priorityFlushesAtOnceWithWhatIsQueued() {
		outbox.enqueue(item("/bank", "{\"b\":1}", "bank", false));
		outbox.enqueue(item("/loot/drop", "{\"d\":1}", null, true));
		advance(0);
		assertEquals(1, sender.batches.size());
		assertEquals(2, sender.batches.get(0).size());
	}

	@Test
	public void fullStateUploadsCoalesceToTheNewestAndRunBothCallbacks() {
		outbox.enqueue(item("/bank", "{\"v\":1}", "bank|p", false));
		outbox.enqueue(item("/drop", "{\"e\":1}", null, false));
		outbox.enqueue(item("/bank", "{\"v\":2}", "bank|p", false));
		outbox.enqueue(item("/bank", "{\"other\":1}", "bank|q", false));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		assertEquals(Arrays.asList("{\"e\":1}", "{\"v\":2}", "{\"other\":1}"), bodies(sender.batches.get(0)));
		sender.okLast(null);
		// The replaced copy's caller hears of the upload too, first.
		assertEquals(Arrays.asList("/drop{\"e\":1}", "/bank{\"v\":1}", "/bank{\"v\":2}", "/bank{\"other\":1}"), succeeded);
	}

	@Test
	public void eventsAreNeverDropped() {
		for (int i = 0; i < 5; i++) {
			outbox.enqueue(item("/loot/drop", "{\"d\":" + i + "}", null, false));
		}
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		assertEquals(5, sender.batches.get(0).size());
	}

	@Test
	public void inFlightCopyIsNotReplacedAndNewerGoesNext() {
		outbox.enqueue(item("/skills", "{\"v\":1}", "skills", true));
		advance(0);
		assertEquals(1, sender.batches.size());
		outbox.enqueue(item("/skills", "{\"v\":2}", "skills", false));
		sender.okLast(null);
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		assertEquals(2, sender.batches.size());
		assertEquals(Collections.singletonList("{\"v\":2}"), bodies(sender.batches.get(1)));
	}

	@Test
	public void splitsAtFiftyAndSendsTheRestRightAway() {
		for (int i = 0; i < 120; i++) {
			outbox.enqueue(item("/e", "{\"i\":" + i + "}", null, false));
		}
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		assertEquals(1, sender.batches.size());
		assertEquals(50, sender.batches.get(0).size());
		sender.okLast(null);
		assertEquals(2, sender.batches.size());
		assertEquals(50, sender.batches.get(1).size());
		assertEquals("{\"i\":50}", sender.batches.get(1).get(0).getBody());
		sender.okLast(null);
		assertEquals(20, sender.batches.get(2).size());
		sender.okLast(null);
		assertEquals(120, succeeded.size());
		assertEquals("/e{\"i\":119}", succeeded.get(119));
	}

	@Test
	public void networkFailureRetriesWithBackoffKeepingOrder() {
		outbox.enqueue(item("/a", "{\"n\":1}", null, false));
		outbox.enqueue(item("/b", "{\"n\":2}", null, false));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		sender.lastBatch().onNetworkFailure("offline");
		assertEquals(2, outbox.size());

		long[] expectedWaits = {10_000, 20_000, 40_000, 80_000, 120_000, 120_000};
		for (long wait : expectedWaits) {
			int before = sender.batches.size();
			advance(wait - 1);
			assertEquals("no retry before " + wait, before, sender.batches.size());
			advance(1);
			assertEquals("retry after " + wait, before + 1, sender.batches.size());
			sender.lastBatch().onNetworkFailure("offline");
		}
		advance(120_000);
		sender.okLast(null);
		assertEquals(Arrays.asList("/a{\"n\":1}", "/b{\"n\":2}"), succeeded);
		assertEquals(0, outbox.size());
	}

	@Test
	public void serverErrorForTheWholeBatchIsRetried() {
		outbox.enqueue(item("/a", "{}", null, true));
		advance(0);
		sender.lastBatch().onResponse(503, null, null);
		assertEquals(1, outbox.size());
		advance(SyncOutbox.BACKOFF_BASE_MS);
		assertEquals(2, sender.batches.size());
	}

	@Test
	public void unauthorisedBatchIsDroppedNotRetried() {
		outbox.enqueue(item("/a", "{}", null, true));
		advance(0);
		sender.lastBatch().onResponse(401, null, null);
		assertEquals(0, outbox.size());
		assertTrue(succeeded.isEmpty());
		advance(10 * 60_000);
		assertEquals(1, sender.batches.size());
	}

	@Test
	public void perEntryFailureDropsOnlyThatEntry() {
		outbox.enqueue(item("/a", "{\"n\":1}", null, false));
		outbox.enqueue(item("/b", "{\"n\":2}", null, false));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		sender.lastBatch().onResponse(200, Arrays.asList(500, 200), 3);
		assertEquals(Collections.singletonList("/b{\"n\":2}"), succeeded);
		assertEquals(0, outbox.size());
	}

	@Test
	public void requestsOlderThanThirtyMinutesAreDropped() {
		outbox.enqueue(item("/a", "{}", null, false));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		sender.lastBatch().onNetworkFailure("offline");
		// Keep failing for over 30 minutes.
		for (int i = 0; i < 20 && outbox.size() > 0; i++) {
			advance(SyncOutbox.BACKOFF_MAX_MS);
			if (sender.batchCallbacks.size() > i + 1) {
				sender.lastBatch().onNetworkFailure("offline");
			}
		}
		advance(SyncOutbox.MAX_AGE_MS);
		outbox.flushNow();
		assertEquals(0, outbox.size());
		assertTrue(succeeded.isEmpty());
	}

	@Test
	public void flushNowIgnoresBackoff() {
		outbox.enqueue(item("/a", "{}", null, true));
		advance(0);
		sender.lastBatch().onNetworkFailure("offline");
		outbox.flushNow();
		assertEquals(2, sender.batches.size());
	}

	@Test
	public void priorityWaitsOutBackoff() {
		outbox.enqueue(item("/a", "{}", null, true));
		advance(0);
		sender.lastBatch().onNetworkFailure("offline");
		outbox.enqueue(item("/b", "{}", null, true));
		advance(0);
		assertEquals(1, sender.batches.size());
		advance(SyncOutbox.BACKOFF_BASE_MS);
		assertEquals(2, sender.batches.size());
		assertEquals(2, sender.batches.get(1).size());
	}

	@Test
	public void oldServerWithoutBatchGetsEachRequestInOrder() {
		outbox.enqueue(item("/a", "{\"n\":1}", null, false));
		outbox.enqueue(item("/b", "{\"n\":2}", null, false));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		sender.lastBatch().onResponse(404, null, null);
		assertEquals(1, sender.singles.size());
		assertEquals("/a", sender.singles.get(0).getPath());
		sender.singleCallbacks.get(0).onResponse(200);
		assertEquals(2, sender.singles.size());
		assertEquals("/b", sender.singles.get(1).getPath());
		sender.singleCallbacks.get(1).onResponse(200);
		assertEquals(Arrays.asList("/a{\"n\":1}", "/b{\"n\":2}"), succeeded);

		// The next flush goes straight to single requests (no batch attempt) for a while.
		outbox.enqueue(item("/c", "{}", null, true));
		advance(0);
		assertEquals(1, sender.batches.size());
		assertEquals(3, sender.singles.size());
		sender.singleCallbacks.get(2).onResponse(200);

		// ...and tries the batch endpoint again later.
		advance(SyncOutbox.BATCH_RETRY_AFTER_404_MS);
		outbox.enqueue(item("/d", "{}", null, true));
		advance(0);
		assertEquals(2, sender.batches.size());
	}

	@Test
	public void singleRequestNetworkFailureKeepsTheRestForRetry() {
		outbox.enqueue(item("/a", "{}", null, false));
		outbox.enqueue(item("/b", "{}", null, false));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		sender.lastBatch().onResponse(404, null, null);
		sender.singleCallbacks.get(0).onResponse(200);
		sender.singleCallbacks.get(1).onNetworkFailure("offline");
		assertEquals(1, outbox.size());
		advance(SyncOutbox.BACKOFF_BASE_MS);
		assertEquals(3, sender.singles.size());
		assertEquals("/b", sender.singles.get(2).getPath());
	}

	@Test
	public void webVersionAndBatchTimeAreReported() {
		List<Integer> versions = new ArrayList<>();
		outbox.setWebVersionListener(versions::add);
		assertEquals(Long.MIN_VALUE, outbox.getLastBatchResponseMs());
		outbox.enqueue(item("/a", "{}", null, true));
		advance(5_000);
		sender.okLast(7);
		assertEquals(Collections.singletonList(7), versions);
		assertEquals(5_000, outbox.getLastBatchResponseMs());
	}

	@Test
	public void stopFlushesAndDropsOnFailureInsteadOfRetrying() {
		outbox.enqueue(item("/a", "{}", null, false));
		outbox.stop();
		assertEquals(1, sender.batches.size());
		sender.lastBatch().onNetworkFailure("offline");
		assertEquals(0, outbox.size());
		advance(10 * 60_000);
		assertEquals(1, sender.batches.size());
	}

	@Test
	public void separateKeysGoInSeparateBatches() {
		outbox.enqueue(new SyncOutbox.Item("https://x", "k1", "/a", "POST", "{}", "a", null, false, false, null));
		outbox.enqueue(new SyncOutbox.Item("https://x", "k2", "/b", "POST", "{}", "b", null, false, false, null));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		assertEquals(1, sender.batches.get(0).size());
		sender.okLast(null);
		assertEquals(2, sender.batches.size());
		assertEquals("k2", sender.batches.get(1).get(0).getAppKey());
	}

	@Test
	public void hasPendingSeesQueuedLabels() {
		assertFalse(outbox.hasPending("/a"));
		outbox.enqueue(item("/a", "{}", null, false));
		assertTrue(outbox.hasPending("/a"));
	}

	@Test
	public void batchBodySplicesTheJsonBodiesAndNamesThePlayer() {
		List<SyncOutbox.Item> items = Arrays.asList(
				new SyncOutbox.Item("u", "k", "/api/runelite/session/", "POST", "{\"x\":1}", "s", null, false, false, null),
				new SyncOutbox.Item("u", "k", "/api/runelite/skills/", "POST", "{\"player\":\"Zez \\\"ima\\\"\",\"skills\":{}}", "s", null, false, false, null));
		String body = OSRSCompanionApiClient.batchBody(new Gson(), items);
		assertEquals("{\"player_username\":\"Zez \\\"ima\\\"\",\"requests\":["
				+ "{\"path\":\"/api/runelite/session/\",\"method\":\"POST\",\"body\":{\"x\":1}},"
				+ "{\"path\":\"/api/runelite/skills/\",\"method\":\"POST\",\"body\":{\"player\":\"Zez \\\"ima\\\"\",\"skills\":{}}}]}", body);
	}

	@Test
	public void parsesBatchResponse() {
		OSRSCompanionApiClient.BatchResult r = OSRSCompanionApiClient.parseBatchResponse(
				"{\"results\":[{\"status\":200,\"body\":{}},{\"status\":404,\"body\":null}],\"webVersion\":12}");
		assertEquals(Arrays.asList(200, 404), r.statuses);
		assertEquals(Integer.valueOf(12), r.webVersion);
		OSRSCompanionApiClient.BatchResult empty = OSRSCompanionApiClient.parseBatchResponse("{}");
		assertNull(empty.statuses);
		assertNull(empty.webVersion);
	}

	@Test
	public void playerInBodyFindsEitherField() {
		assertEquals("Zezima", OSRSCompanionApiClient.playerInBody("{\"a\":1,\"player_username\":\"Zezima\"}"));
		assertEquals("Lynx", OSRSCompanionApiClient.playerInBody("{\"player\" : \"Lynx\"}"));
		assertNull(OSRSCompanionApiClient.playerInBody("{\"timers\":[]}"));
	}

	@Test
	public void refusedUploadsAreNotSuccesses() {
		outbox.enqueue(item("/ok", "{}", null, false));
		outbox.enqueue(item("/bad", "{}", null, false));
		advance(SyncOutbox.FLUSH_INTERVAL_MS);
		sender.lastBatch().onResponse(200, Arrays.asList(200, 400), null);
		assertEquals(Collections.singletonList("/ok{}"), succeeded);
	}

	@Test
	public void batchExtraRidesAlongOnceAndIsNeverRetried() {
		List<Integer> asked = new ArrayList<>();
		outbox.setBatchExtra(chunk -> {
			asked.add(chunk.size());
			return new SyncOutbox.Item("https://x", "k", "/activity", "POST", "{\"s\":1}", "activity", null, false, false, null);
		});
		outbox.enqueue(item("/a", "{\"n\":1}", null, true));
		advance(0);
		assertEquals(Collections.singletonList(1), asked);
		assertEquals(Arrays.asList("{\"n\":1}", "{\"s\":1}"), bodies(sender.batches.get(0)));
		// A failed batch retries its queued uploads, not the extra (the next batch gets a fresh one).
		sender.lastBatch().onNetworkFailure("offline");
		assertEquals(1, outbox.size());
		advance(SyncOutbox.BACKOFF_MAX_MS);
		assertEquals(2, sender.batches.size());
		assertEquals(Arrays.asList("{\"n\":1}", "{\"s\":1}"), bodies(sender.batches.get(1)));
		sender.okLast(null);
		assertEquals(0, outbox.size());
	}

	@Test
	public void batchExtraForAnotherServerOrKeyIsLeftOut() {
		outbox.setBatchExtra(chunk -> new SyncOutbox.Item("https://other", "k", "/activity", "POST", "{}", "activity", null, false, false, null));
		outbox.enqueue(item("/a", "{\"n\":1}", null, true));
		advance(0);
		assertEquals(1, sender.batches.get(0).size());
	}
}

package com.osrscompanion.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Tests for BankSyncPayload JSON serialization.
 */
public class BankSyncPayloadTest {
	private final Gson gson = new Gson();

	@Test
	public void testPayloadStructure() {
		List<BankSyncPayload.BankItem> items = Arrays.asList(
				new BankSyncPayload.BankItem(4151, 1),
				new BankSyncPayload.BankItem(385, 500));
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", items);
		BankSyncPayload payload = new BankSyncPayload("TestPlayer", itemsBySource);
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"player_username\":\"TestPlayer\""));
		assertTrue(json.contains("\"bank\""));
		assertTrue(json.contains("\"item_id\":4151"));
		assertTrue(json.contains("\"quantity\":1"));
		assertTrue(json.contains("\"item_id\":385"));
		assertTrue(json.contains("\"quantity\":500"));
	}

	@Test
	public void testEmptyItemsMap() {
		BankSyncPayload payload = new BankSyncPayload("EmptyPlayer", Collections.emptyMap());
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"player_username\":\"EmptyPlayer\""));
		assertTrue(json.contains("\"items\":{}"));
	}

	@Test
	public void testEmptySourceList() {
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", Collections.emptyList());
		BankSyncPayload payload = new BankSyncPayload("EmptyBank", itemsBySource);
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"bank\":[]"));
	}

	@Test
	public void testGetters() {
		BankSyncPayload.BankItem item = new BankSyncPayload.BankItem(4151, 10);
		assertEquals(4151, item.getItemId());
		assertEquals(10, item.getQuantity());

		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", Collections.singletonList(item));
		BankSyncPayload payload = new BankSyncPayload("Zezima", itemsBySource);
		assertEquals("Zezima", payload.getPlayerUsername());
		assertEquals(1, payload.getItems().size());
		assertEquals(1, payload.getTotalItemCount());
	}

	@Test
	public void testMultipleSources() {
		List<BankSyncPayload.BankItem> bankItems = Arrays.asList(
				new BankSyncPayload.BankItem(4151, 1));
		List<BankSyncPayload.BankItem> vaultItems = Arrays.asList(
				new BankSyncPayload.BankItem(385, 200));
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", bankItems);
		itemsBySource.put("seed_vault", vaultItems);
		BankSyncPayload payload = new BankSyncPayload("MultiPlayer", itemsBySource);

		assertEquals(2, payload.getTotalItemCount());
		String json = payload.toJson(gson);
		assertTrue(json.contains("\"bank\""));
		assertTrue(json.contains("\"seed_vault\""));
	}

	@Test
	public void testLargeQuantityValues() {
		BankSyncPayload.BankItem item = new BankSyncPayload.BankItem(995, 2147483647);
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", Collections.singletonList(item));
		BankSyncPayload payload = new BankSyncPayload("RichPlayer", itemsBySource);
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"item_id\":995"));
		assertTrue(json.contains("\"quantity\":2147483647"));
	}
}

package com.osrscompanion.model;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BossGearTest {
	@Test
	public void parsesTheActiveSetAndTheSavedSets() {
		String json = "{\"sets\":[{\"id\":3,\"boss\":\"vorkath\",\"boss_name\":\"Vorkath\",\"setup\":0,\"style\":\"Ranged\",\"inventory\":null,\"active\":true}],"
			+ "\"set\":{\"id\":3,\"boss\":\"vorkath\",\"boss_name\":\"Vorkath\",\"style\":\"Ranged\",\"inventory_label\":\"Ranged\",\"synced\":true,"
