package com.osrscompanion.model;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class PlayerSkillsSyncPayloadTest {
	@Test
	public void testPayloadCreation() {
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		skills.put("Attack", new PlayerSkillsSyncPayload.SkillData(75, 1200000));
		skills.put("Defence", new PlayerSkillsSyncPayload.SkillData(70, 800000));
		skills.put("Strength", new PlayerSkillsSyncPayload.SkillData(80, 2000000));

		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload("TestPlayer", skills, 225, 95);

		assertEquals("TestPlayer", payload.getPlayer());
		assertEquals(3, payload.getSkills().size());
		assertEquals(225, payload.getTotalLevel());
		assertEquals(95, payload.getCombatLevel());
		assertEquals(75, payload.getSkills().get("Attack").getLevel());
		assertEquals(1200000, payload.getSkills().get("Attack").getCurrentXp());
	}

	@Test
	public void testJsonSerialization() {
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		skills.put("Attack", new PlayerSkillsSyncPayload.SkillData(75, 1200000));
		skills.put("Defence", new PlayerSkillsSyncPayload.SkillData(70, 800000));

		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload("TestPlayer", skills, 145, 85);
		Gson gson = new Gson();
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("TestPlayer"));
		assertTrue(json.contains("Attack"));
		assertTrue(json.contains("Defence"));
		assertTrue(json.contains("total_level"));
		assertTrue(json.contains("combat_level"));
		assertTrue(json.contains("current_xp"));
		JsonObject jsonObject = gson.fromJson(json, JsonObject.class);
		assertEquals("TestPlayer", jsonObject.get("player").getAsString());
		assertEquals(145, jsonObject.get("total_level").getAsInt());
		assertEquals(85, jsonObject.get("combat_level").getAsInt());
		assertTrue(jsonObject.has("skills"));
		JsonObject skillsObject = jsonObject.getAsJsonObject("skills");
		JsonObject attackSkill = skillsObject.getAsJsonObject("Attack");
		assertEquals(75, attackSkill.get("level").getAsInt());
		assertEquals(1200000, attackSkill.get("current_xp").getAsInt());
	}

	@Test
	public void testEmptySkills() {
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload("EmptyPlayer", skills, 0, 3);

		assertEquals("EmptyPlayer", payload.getPlayer());
		assertTrue(payload.getSkills().isEmpty());
		assertEquals(0, payload.getTotalLevel());
		assertEquals(3, payload.getCombatLevel());
	}

	@Test
	public void testSkillDataCreation() {
		PlayerSkillsSyncPayload.SkillData skillData = new PlayerSkillsSyncPayload.SkillData(99, 13034431);

		assertEquals(99, skillData.getLevel());
		assertEquals(13034431, skillData.getCurrentXp());
	}

	@Test
	public void accountTypeFromTheIronmanVarbit() {
		assertNull(PlayerSkillsSyncPayload.accountTypeOf(0)); // normal, or not loaded yet
		for (int v = 1; v <= 6; v++) {
			assertEquals(Integer.valueOf(v), PlayerSkillsSyncPayload.accountTypeOf(v));
		}
		assertNull(PlayerSkillsSyncPayload.accountTypeOf(7));
		assertNull(PlayerSkillsSyncPayload.accountTypeOf(-1));
	}

	@Test
	public void accountTypeIsSentOnlyWhenKnown() {
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		Gson gson = new Gson();
		JsonObject gim = gson.fromJson(new PlayerSkillsSyncPayload("Gim", skills, 32, 3, 5).toJson(gson), JsonObject.class);
		assertEquals(5, gim.get("account_type").getAsInt());
		JsonObject normal = gson.fromJson(new PlayerSkillsSyncPayload("Main", skills, 32, 3).toJson(gson), JsonObject.class);
		assertFalse(normal.has("account_type"));
	}
}

package com.osrscompanion.model;

import com.google.gson.Gson;
import java.time.Instant;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests parsing of the roadmap API responses and the next-goal / progress
 * helpers the panel and overlay rely on.
 */
public class RoadmapModelTest {
	private static final Gson GSON = new Gson();

	@Test
	public void aSkillGoalCompletesAtItsStartXpPlusTheXpItNeeds() {
		// 45 Crafting added at 60,000 XP: 1,512 more XP (current / target are XP gained / needed).
		RoadmapGoal goal = GSON.fromJson("{\"id\":1,\"goal_type\":\"skill_level\",\"current\":0,\"target\":1512,"
			+ "\"is_complete\":false,\"meta\":{\"skill\":\"crafting\",\"start_xp\":60000}}", RoadmapGoal.class);
		assertEquals(Long.valueOf(61512), goal.getCompletingXp());
		// Done, another type, or from before start_xp was kept: none.
		assertNull(GSON.fromJson("{\"goal_type\":\"skill_level\",\"target\":1512,\"is_complete\":true,\"meta\":{\"skill\":\"crafting\",\"start_xp\":60000}}",
			RoadmapGoal.class).getCompletingXp());
		assertNull(GSON.fromJson("{\"goal_type\":\"kc\",\"target\":5,\"meta\":{\"start_xp\":1}}", RoadmapGoal.class).getCompletingXp());
		assertNull(GSON.fromJson("{\"goal_type\":\"skill_xp\",\"target\":5,\"meta\":{\"skill\":\"crafting\"}}", RoadmapGoal.class).getCompletingXp());
	}

	@Test
	public void testParseRoadmapList() {
		String json = "{\"player\":\"Zezima\",\"runelite_connected\":true,"
				+ "\"roadmaps\":[{\"collection_id\":1,\"title\":\"Maxing\",\"goal_count\":3},"
				+ "{\"collection_id\":2,\"title\":\"Iron grind\",\"goal_count\":0}]}";
		RoadmapList list = GSON.fromJson(json, RoadmapList.class);

		assertEquals("Zezima", list.getPlayer());
		assertTrue(list.isRuneliteConnected());
		assertEquals(2, list.getRoadmaps().size());
		assertEquals("Maxing", list.getRoadmaps().get(0).getTitle());
		assertEquals(3, list.getRoadmaps().get(0).getGoalCount());
	}

	@Test
	public void testRoadmapListEmptyRoadmapsIsNeverNull() {
		RoadmapList list = GSON.fromJson("{\"player\":\"Z\"}", RoadmapList.class);
		assertNotNull(list.getRoadmaps());
		assertTrue(list.getRoadmaps().isEmpty());
	}

	@Test
	public void testParseRoadmapDetailAndSorting() {
		String json = "{\"collection_id\":1,\"title\":\"Maxing\",\"goal_count\":2,"
				+ "\"goals\":["
				+ "{\"id\":11,\"goal_type\":\"skill_level\",\"sort_order\":2,\"name\":\"Level 99 Slayer\","
				+ "\"current\":50,\"target\":100,\"progress_percent\":63,\"is_complete\":false},"
				+ "{\"id\":10,\"goal_type\":\"quest\",\"sort_order\":1,\"name\":\"Cook's Assistant\","
				+ "\"current\":1,\"target\":1,\"progress_percent\":null,\"is_complete\":true}]}";
		Roadmap roadmap = GSON.fromJson(json, Roadmap.class);

		assertEquals(1, roadmap.getCollectionId());
		assertEquals(2, roadmap.getGoals().size());
		// Sorted by sort_order: the quest (1) before the skill (2).
		assertEquals(10, roadmap.getGoalsSorted().get(0).getId());
		assertEquals(11, roadmap.getGoalsSorted().get(1).getId());
	}

	@Test
	public void testFirstIncompleteGoalSkipsCompleted() {
		String json = "{\"collection_id\":1,\"goals\":["
				+ "{\"id\":1,\"sort_order\":1,\"name\":\"Done\",\"is_complete\":true},"
				+ "{\"id\":2,\"sort_order\":2,\"name\":\"Next up\",\"is_complete\":false},"
				+ "{\"id\":3,\"sort_order\":3,\"name\":\"Later\",\"is_complete\":false}]}";
		Roadmap roadmap = GSON.fromJson(json, Roadmap.class);

		RoadmapGoal next = roadmap.firstIncompleteGoal();
		assertNotNull(next);
		assertEquals("Next up", next.getName());
	}

	@Test
	public void testFirstIncompleteGoalNullWhenAllComplete() {
		String json = "{\"collection_id\":1,\"goals\":["
				+ "{\"id\":1,\"sort_order\":1,\"name\":\"Done\",\"is_complete\":true}]}";
		Roadmap roadmap = GSON.fromJson(json, Roadmap.class);
		assertNull(roadmap.firstIncompleteGoal());
	}

	@Test
	public void testProgressLabel() {
		RoadmapGoal measurable = GSON.fromJson(
				"{\"id\":1,\"progress_percent\":42,\"is_complete\":false}", RoadmapGoal.class);
		assertEquals("42%", measurable.progressLabel());

		RoadmapGoal binary = GSON.fromJson(
				"{\"id\":2,\"progress_percent\":null,\"is_complete\":false}", RoadmapGoal.class);
		assertEquals("", binary.progressLabel());
		assertFalse(binary.isComplete());
	}

	@Test
	public void testCompletedAtParsesAndTolerates() {
		assertEquals(Instant.parse("2026-09-07T12:34:56.123456Z"),
				GSON.fromJson("{\"id\":1,\"completed_at\":\"2026-09-07T12:34:56.123456Z\"}", RoadmapGoal.class)
						.getCompletedAt());
		assertEquals(Instant.parse("2026-09-07T12:34:56Z"),
				GSON.fromJson("{\"id\":1,\"completed_at\":\"2026-09-07T12:34:56+00:00\"}", RoadmapGoal.class)
						.getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":null}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":\"\"}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":\"not-a-date\"}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":\"2026-09-07\"}", RoadmapGoal.class).getCompletedAt());
	}

	@Test
	public void testImageUrlParses() {
		assertEquals("https://oldschool.runescape.wiki/images/Tormented_Demon.png",
				GSON.fromJson("{\"id\":1,\"image_url\":\"https://oldschool.runescape.wiki/images/Tormented_Demon.png\"}",
						RoadmapGoal.class).getImageUrl());
		assertNull(GSON.fromJson("{\"id\":1,\"image_url\":null}", RoadmapGoal.class).getImageUrl());
	}

	@Test
	public void testNpcMetaParses() {
		RoadmapGoal g = GSON.fromJson("{\"id\":1,\"meta\":{\"npc_id\":384,\"npc_name\":\"Guard\"}}", RoadmapGoal.class);
		assertEquals(Integer.valueOf(384), g.getNpcId());
		assertEquals("Guard", g.getNpcName());
		assertNull(GSON.fromJson("{\"id\":1,\"meta\":{}}", RoadmapGoal.class).getNpcName());
	}
}

