package com.osrscompanion.runelite.farming;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * RuneLite's farming produce. Each one's name, contract name, patch type, item, growth ticks and stages come from
 * {@code produce.txt}, a table generated from RuneLite's own Produce (kept in the tests as {@code RuneLiteProduce},
 * which checks every value against it). Run: node update.js
 */
@Getter
public enum Produce
{
	WEEDS, SCARECROW, POTATO, ONION, CABBAGE, TOMATO, SWEETCORN, STRAWBERRY, WATERMELON, SNAPE_GRASS, MARIGOLD, ROSEMARY,
	NASTURTIUM, WOAD, LIMPWURT, WHITE_LILY, REDBERRIES, CADAVABERRIES, DWELLBERRIES, JANGERBERRIES, WHITEBERRIES,
	POISON_IVY, BARLEY, HAMMERSTONE, ASGARNIAN, JUTE, YANILLIAN, FLAX, KRANDORIAN, WILDBLOOD, HEMP, COTTON, GUAM,
	MARRENTILL, TARROMIN, HARRALANDER, RANARR, TOADFLAX, IRIT, AVANTOE, KWUARM, HUASCA, SNAPDRAGON, CADANTINE, LANTADYME,
	DWARF_WEED, TORSTOL, GOUTWEED, ANYHERB, OAK, WILLOW, MAPLE, YEW, MAGIC, APPLE, BANANA, ORANGE, CURRY, PINEAPPLE,
	PAPAYA, PALM, DRAGONFRUIT, CACTUS, POTATO_CACTUS, TEAK, MAHOGANY, CAMPHOR, IRONWOOD, ROSEWOOD, ATTAS, IASOR, KRONOS,
	ELKHORN_CORAL, PILLAR_CORAL, UMBRAL_CORAL, SEAWEED, GRAPE, MUSHROOM, BELLADONNA, CALQUAT, SPIRIT_TREE, CELASTRUS,
	REDWOOD, HESPORI, CRYSTAL_TREE, EMPTY_COMPOST_BIN, COMPOST, SUPERCOMPOST, ULTRACOMPOST, ROTTEN_TOMATO,
	EMPTY_BIG_COMPOST_BIN, BIG_COMPOST, BIG_SUPERCOMPOST, BIG_ULTRACOMPOST, BIG_ROTTEN_TOMATO;

	static final String TABLE = "produce.txt";

	/** User-visible name */
	private String name;
	/** Farming contract names */
	private String contractName;
	/** Patch type for the crop */
	private PatchImplementation patchImplementation;
	/** User-visible item icon */
	private int itemID;
	/** How many minutes per growth tick */
	private int tickrate;
	/** How many states this crop has during growth. Typically tickcount+1 */
	private int stages;
	/** How many minutes to regrow crops, or zero if it doesn't regrow */
	private int regrowTickrate;
	/** How many states this crop has during harvest. This is often called lives. */
	private int harvestStages;

	static
	{
		try (InputStream stream = Produce.class.getResourceAsStream(TABLE))
		{
			if (stream == null)
			{
				throw new IllegalStateException(TABLE + " is missing");
			}
			BufferedReader in = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8));
			String line;
			while ((line = in.readLine()) != null)
			{
				if (line.isEmpty() || line.charAt(0) == '#')
				{
					continue;
				}
				// NAME, name, contract name, patch type (- for none), item, tick rate, stages, regrow tick rate, harvest stages
				String[] f = line.split("\t");
				Produce p = valueOf(f[0]);
				p.name = f[1];
				p.contractName = f[2];
				p.patchImplementation = "-".equals(f[3]) ? null : PatchImplementation.valueOf(f[3]);
				p.itemID = Integer.parseInt(f[4]);
				p.tickrate = Integer.parseInt(f[5]);
				p.stages = Integer.parseInt(f[6]);
				p.regrowTickrate = Integer.parseInt(f[7]);
				p.harvestStages = Integer.parseInt(f[8]);
			}
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Could not read " + TABLE, e);
		}
	}

	@Nullable
	static Produce getByItemID(int itemId)
	{
		for (Produce produce : Produce.values())
		{
			if (produce.getItemID() == itemId)
			{
				return produce;
			}
		}
		return null;
	}

	@Nullable
	static Produce getByContractName(String contractName)
	{
		for (Produce produce : Produce.values())
		{
			if (produce.getContractName().equalsIgnoreCase(contractName))
			{
				return produce;
			}
		}
		return null;
	}
}

package com.osrscompanion.runelite.farming;

import static org.junit.Assert.assertEquals;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.Test;

/**
 * The plugin's produce table ({@code produce.txt}) against RuneLite's own Produce, kept here as
 * {@link RuneLiteProduce}: the table is generated from it and every produce has the same values. A missing table
 * is written by this test (after {@code node update.js} copied a new RuneLite version, delete it and run the tests).
 */
public class ProduceTableTest {
	static final Path TABLE = Paths.get("src", "test", "resources", "com", "osrscompanion", "runelite", "farming", Produce.TABLE);

	static String generate() {
		StringBuilder sb = new StringBuilder("# Generated from RuneLite's Produce by ProduceTableTest: NAME, name, contract name, patch type,"
			+ " item, tick rate, stages, regrow tick rate, harvest stages (tab-separated)\n");
		for (RuneLiteProduce p : RuneLiteProduce.values()) {
			sb.append(p.name()).append('\t').append(p.getName()).append('\t').append(p.getContractName()).append('\t')
				.append(p.getPatchImplementation() == null ? "-" : p.getPatchImplementation().name()).append('\t')
				.append(p.getItemID()).append('\t').append(p.getTickrate()).append('\t').append(p.getStages()).append('\t')
				.append(p.getRegrowTickrate()).append('\t').append(p.getHarvestStages()).append('\n');
		}
		return sb.toString();
	}

	@Test
	public void theTableIsGeneratedFromRuneLitesCode() throws IOException {
		String generated = generate();
		if (!Files.exists(TABLE)) {
			Files.createDirectories(TABLE.getParent());
			Files.write(TABLE, generated.getBytes(StandardCharsets.UTF_8));
		}
		String stored = new String(Files.readAllBytes(TABLE), StandardCharsets.UTF_8).replace("\r\n", "\n");
		assertEquals("produce.txt is out of date: delete it and run the tests to generate it again", generated, stored);
	}

	@Test
	public void everyProduceHasRuneLitesValues() {
		assertEquals(RuneLiteProduce.values().length, Produce.values().length);
		for (RuneLiteProduce ref : RuneLiteProduce.values()) {
			Produce p = Produce.valueOf(ref.name());
			String n = ref.name();
			assertEquals(n, ref.ordinal(), p.ordinal());
			assertEquals(n, ref.getName(), p.getName());
			assertEquals(n, ref.getContractName(), p.getContractName());
			assertEquals(n, ref.getPatchImplementation(), p.getPatchImplementation());
			assertEquals(n, ref.getItemID(), p.getItemID());
			assertEquals(n, ref.getTickrate(), p.getTickrate());
			assertEquals(n, ref.getStages(), p.getStages());
			assertEquals(n, ref.getRegrowTickrate(), p.getRegrowTickrate());
			assertEquals(n, ref.getHarvestStages(), p.getHarvestStages());
		}
	}

	@Test
	public void lookupsMatchRuneLite() {
		for (RuneLiteProduce ref : RuneLiteProduce.values()) {
			RuneLiteProduce byItem = RuneLiteProduce.getByItemID(ref.getItemID());
			Produce mine = Produce.getByItemID(ref.getItemID());
			assertEquals(ref.name(), byItem == null ? null : byItem.name(), mine == null ? null : mine.name());
			RuneLiteProduce byContract = RuneLiteProduce.getByContractName(ref.getContractName());
			Produce mineContract = Produce.getByContractName(ref.getContractName());
			assertEquals(ref.name(), byContract == null ? null : byContract.name(), mineContract == null ? null : mineContract.name());
		}
	}
}

