	/**
	 * User-visible name
	 */
	private final String name;
	/**
	 * Farming contract names
	 */
	private final String contractName;
	/**
	 * Patch type for the crop
	 */
	private final PatchImplementation patchImplementation;
	/**
	 * User-visible item icon
	 */
	private final int itemID;
	/**
	 * How many minutes per growth tick
	 */
	private final int tickrate;
	/**
	 * How many states this crop has during growth. Typically tickcount+1
	 */
	private final int stages;
	/**
	 * How many minutes to regrow crops, or zero if it doesn't regrow
	 */
	private final int regrowTickrate;
	/**
	 * How many states this crop has during harvest.
	 * This is often called lives.
	 */
	private final int harvestStages;

	RuneLiteProduce(String name, String contractName, PatchImplementation patchImplementation, int itemID, int tickrate, int stages, int regrowTickrate, int harvestStages)
	{
		this.name = name;
		this.contractName = contractName;
		this.patchImplementation = patchImplementation;
		this.itemID = itemID;
		this.tickrate = tickrate;
		this.stages = stages;
		this.regrowTickrate = regrowTickrate;
		this.harvestStages = harvestStages;
	}

	RuneLiteProduce(String name, int itemID, int tickrate, int stages, int regrowTickrate, int harvestStages)
	{
		this(name, name, null, itemID, tickrate, stages, regrowTickrate, harvestStages);
	}

	RuneLiteProduce(String name, PatchImplementation patchImplementation, int itemID, int tickrate, int stages, int regrowTickrate, int harvestStages)
	{
		this(name, name, patchImplementation, itemID, tickrate, stages, regrowTickrate, harvestStages);
	}

	RuneLiteProduce(String name, String contractName, PatchImplementation patchImplementation, int itemID, int tickrate, int stages)
	{
		this(name, contractName, patchImplementation, itemID, tickrate, stages, 0, 1);
	}

	RuneLiteProduce(String name, PatchImplementation patchImplementation, int itemID, int tickrate, int stages)
	{
		this(name, name, patchImplementation, itemID, tickrate, stages, 0, 1);
	}

	RuneLiteProduce(String name, int itemID, int tickrate, int stages)
	{
		this(name, name, null, itemID, tickrate, stages, 0, 1);
	}

	@Nullable
	static RuneLiteProduce getByItemID(int itemId)
	{
		for (RuneLiteProduce produce : RuneLiteProduce.values())
		{
			if (produce.getItemID() == itemId)
			{
				return produce;
			}
		}
		return null;
	}

	@Nullable
	static RuneLiteProduce getByContractName(String contractName)
	{
		for (RuneLiteProduce produce : RuneLiteProduce.values())
		{
			if (produce.getContractName().equalsIgnoreCase(contractName))
			{
				return produce;
			}
		}
		return null;
	}
	public String getName()
	{
		return name;
	}

	public String getContractName()
	{
		return contractName;
	}

	public PatchImplementation getPatchImplementation()
	{
		return patchImplementation;
	}

	public int getItemID()
	{
		return itemID;
	}

	public int getTickrate()
	{
		return tickrate;
	}

	public int getStages()
	{
		return stages;
	}

	public int getRegrowTickrate()
	{
		return regrowTickrate;
	}

	public int getHarvestStages()
	{
		return harvestStages;
	}
